CREATE OR REPLACE FUNCTION "public"."abuse_image_file_may_go"("bucket" "text", "path" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.picture_checks
    join public.abuse_image_evidence on abuse_image_evidence.picture_id = picture_checks.id
    where picture_checks.bucket = abuse_image_file_may_go.bucket and picture_checks.path = abuse_image_file_may_go.path
      and (picture_checks.user_id = (select auth.uid())
           or (abuse_image_evidence.described_by_user_id = (select auth.uid())
               and public.is_picture_reviewer((select auth.uid())))));
$$;


ALTER FUNCTION "public"."abuse_image_file_may_go"("bucket" "text", "path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."abuse_image_file_may_go"("bucket" "text", "path" "text") IS 'True for the uploader or the rejecting picture reviewer when the file is a suspected abuse image whose evidence is kept (ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."accept_current_legal_versions"("document_slugs" "text"[], "reading_language" "text" DEFAULT 'ro'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  requested_slug text;
  version_id uuid;
  recorded_count integer := 0;
begin
  -- Step 1: only a signed-in person with a live profile can accept anything.
  if caller_id is null or not exists (
    select 1 from public.profiles where profiles.id = caller_id and profiles.deleted_at is null
  ) then
    raise exception 'Sign in to accept the terms.' using errcode = 'insufficient_privilege';
  end if;

  foreach requested_slug in array document_slugs loop
    -- Step 2: the current live version of that document, in the reading language if it exists.
    select versions.id into version_id
    from public.legal_document_versions as versions
    join public.legal_documents as documents on documents.id = versions.document_id
    where documents.slug = requested_slug and documents.needs_acceptance
      and versions.published_at <= now()
    order by versions.published_at desc, (versions.language = reading_language) desc,
      (versions.language = 'en') desc
    limit 1;
    if version_id is null then
      raise exception 'There is no document "%" to accept.', requested_slug
        using errcode = 'invalid_parameter_value';
    end if;

    -- Step 3: record the acceptance with the time (GDPR Art 7(1): we must be able to show it).
    insert into public.consents (user_id, legal_document_version_id, method)
    values (caller_id, version_id, 're_accept');
    recorded_count := recorded_count + 1;
  end loop;

  return recorded_count;
end;
$$;


ALTER FUNCTION "public"."accept_current_legal_versions"("document_slugs" "text"[], "reading_language" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_current_legal_versions"("document_slugs" "text"[], "reading_language" "text") IS 'Records the signed-in person''s acceptance of the current legal versions named (S1-E14-01).';



