COMMENT ON FUNCTION "public"."account_signed_in_recently"() IS 'True when the person logged in within account_deletion_fresh_sign_in_minutes, from the token''s amr claim (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."account_state"("target_user_id" "uuid") RETURNS "public"."account_status"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  profile_row public.profiles;
  email_confirmed_on timestamptz;
  band public.age_band;
  adults_only boolean := public.is_feature_enabled('adults_only');
begin
  -- Step 1: no live profile, no account.
  select * into profile_row from public.profiles where profiles.id = target_user_id;
  if not found or profile_row.deleted_at is not null then
    return 'deleted';
  end if;

  -- Step 2: the email must be confirmed (S1-E2-01).
  select users.email_confirmed_at into email_confirmed_on
  from auth.users where users.id = target_user_id;
  if email_confirmed_on is null then
    return 'email_unconfirmed';
  end if;

  -- Step 3: a ban or a suspension stops every write (S1-E10-06; DSA art. 23).
  if (public.active_sanction(target_user_id, 'ban')).id is not null then
    return 'banned';
  end if;
  if (public.active_sanction(target_user_id, 'suspension')).id is not null then
    return 'suspended';
  end if;

  -- Step 4: a staff account never writes as a member; a writer account stays separate (Q14a).
  if exists (select 1 from public.staff_roles where staff_roles.user_id = target_user_id) then
    return 'staff_account';
  end if;

  -- Step 4b: still waiting for a place (WAITLIST-1).
  if public.is_on_waitlist(target_user_id) then
    return 'waitlisted';
  end if;

  -- Step 5: the age rules (S1-E2-02, S1-E2-08), the age check before a parent is asked.
  if profile_row.age_check_result = 'failed' then
    return 'age_check_failed';
  end if;
  band := public.age_band_from_birth(
    profile_row.birth_year,
    profile_row.birth_month,
    profile_row.age_check_result,
    (now() at time zone 'Europe/Bucharest')::date
  );
  if band = 'under_13' or (adults_only and band <> '18_plus') then
    return 'minor_not_admitted';
  end if;
  if profile_row.age_check_result = 'pending' and not (adults_only and band = '18_plus') then
    return 'age_check_pending';
  end if;

  -- Step 6: below the age the country's rule sets, a parent's or guardian's yes (S1-E2-03,
  -- MARKETS-1; GDPR art. 8 and local equivalents), after any grace the rules gave.
  if public.needs_country_consent(target_user_id)
     and coalesce(profile_row.consent_grace_until, '-infinity') <= now() then
    return 'awaiting_parental_consent';
  end if;

  -- Step 7: a username, so what the person writes can be shown with a name (S1-E2-04).
  if profile_row.handle is null then
    return 'handle_missing';
  end if;

  -- Step 8: a new important version of the terms or privacy notice must be accepted (S1-E14-01).
  if public.needs_legal_acceptance(target_user_id) then
    return 'legal_acceptance_required';
  end if;

  return 'active';
end;
$$;


ALTER FUNCTION "public"."account_state"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."account_state"("target_user_id" "uuid") IS 'Internal: why an account can or cannot write; only active may write (architecture 1.7.8).';



CREATE OR REPLACE FUNCTION "public"."act_of_story"("target_story_id" "uuid", "act_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  found_id uuid;
begin
  if coalesce(act_id, '') = '' then
    return null;
  end if;
  select story_plan_acts.id into found_id from public.story_plan_acts
  where story_plan_acts.story_id = target_story_id and story_plan_acts.id::text = act_id;
  if found_id is null then
    raise exception 'That act isn''t in this story.' using errcode = 'check_violation', hint = 'other_story';
  end if;
  return found_id;
end;
$$;


ALTER FUNCTION "public"."act_of_story"("target_story_id" "uuid", "act_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."act_of_story"("target_story_id" "uuid", "act_id" "text") IS 'Internal: one of the story''s acts by its ID, or null for none (S1-E17-24).';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."sanctions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "public"."sanction_kind" NOT NULL,
    "case_id" "uuid",
    "applied_by_user_id" "uuid" NOT NULL,
    "note" "text" NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ends_at" timestamp with time zone,
    "lifted_at" timestamp with time zone,
    "lifted_by_user_id" "uuid",
    "lift_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sanctions_lift_fields_go_together" CHECK ((("lifted_at" IS NULL) = ("lifted_by_user_id" IS NULL))),
    CONSTRAINT "sanctions_note_is_written" CHECK ((("btrim"("note") <> ''::"text") AND ("char_length"("note") <= 4000))),
    CONSTRAINT "sanctions_timed_kinds_end" CHECK ((("kind" = ANY (ARRAY['suspension'::"public"."sanction_kind", 'reporting_pause'::"public"."sanction_kind"])) = ("ends_at" IS NOT NULL)))
);


ALTER TABLE "public"."sanctions" OWNER TO "postgres";


COMMENT ON TABLE "public"."sanctions" IS 'kind: staff
A warning, suspension, ban or reporting pause on an account: who applied it, why, when it ends and whether it was lifted (S1-E10-06; DSA art. 23).';



COMMENT ON COLUMN "public"."sanctions"."note" IS 'The staff note: only staff read it; the account gets a statement of reasons (S1-E10-04).';



CREATE OR REPLACE FUNCTION "public"."active_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind") RETURNS "public"."sanctions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select * from public.sanctions
  where sanctions.user_id = target_user_id and sanctions.kind = wanted_kind
    and sanctions.lifted_at is null
    and (sanctions.ends_at is null or sanctions.ends_at > now())
  order by sanctions.starts_at desc
  limit 1;
$$;


ALTER FUNCTION "public"."active_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."active_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind") IS 'Internal: the live sanction of one kind on an account, if any (S1-E10-06).';



CREATE OR REPLACE FUNCTION "public"."ad_booking_clash"("wanted_slot_key" "text", "first_day" "date", "last_day" "date", "leave_out_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select campaigns.name || ' (' || bookings.starts_on || ' to ' || bookings.ends_on || ')'
  from public.ad_bookings as bookings
  join public.sponsor_campaigns as campaigns on campaigns.id = bookings.campaign_id
  where bookings.slot_key = wanted_slot_key
    and bookings.cancelled_at is null
    and campaigns.state <> 'ended'
    and bookings.id is distinct from leave_out_id
    and bookings.starts_on <= last_day and bookings.ends_on >= first_day
  order by bookings.starts_on
  limit 1;
$$;


ALTER FUNCTION "public"."ad_booking_clash"("wanted_slot_key" "text", "first_day" "date", "last_day" "date", "leave_out_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ad_booking_clash"("wanted_slot_key" "text", "first_day" "date", "last_day" "date", "leave_out_id" "uuid") IS 'Internal: the live booking of a slot that overlaps some days, named for the refusal (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."ad_booking_targets"("fields" "jsonb") RETURNS TABLE("categories" "text"[], "tags" "text"[], "languages" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    coalesce((select array_agg(distinct value) from jsonb_array_elements_text(coalesce(fields -> 'categories', '[]')) as value
              where value in (select slug from public.categories)), '{}'),
    coalesce((select array_agg(distinct public.normalise_tag(value)) from jsonb_array_elements_text(coalesce(fields -> 'tags', '[]')) as value
              where public.normalise_tag(value) <> ''), '{}'),
    coalesce((select array_agg(distinct value) from jsonb_array_elements_text(coalesce(fields -> 'languages', '[]')) as value
              where value in ('ro', 'en')), '{}');
$$;


ALTER FUNCTION "public"."ad_booking_targets"("fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ad_booking_targets"("fields" "jsonb") IS 'Internal: cleans a booking''s category, tag and language lists (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."ad_network_is_ready"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select public.is_feature_enabled('ad_network')
    and coalesce(public.setting_value('ad_network_publisher_id') #>> '{}', '') ~ '^ca-pub-[0-9]{16}$'
    and coalesce(public.setting_value('ad_network_slot_id') #>> '{}', '') ~ '^[0-9]{6,12}$';
$_$;


ALTER FUNCTION "public"."ad_network_is_ready"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ad_network_is_ready"() IS 'Internal: the ad network is switched on and its account and ad unit look right (S1-E12-04, S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."ad_placement_week"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "week_start" "date", "network_ready" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  booked record;
  house_title text;
begin
  -- Step 1: a booking that stands and whose campaign hasn't ended.
  select bookings.id, campaigns.name as campaign_name, sponsors.name as sponsor_name into booked
  from public.ad_bookings as bookings
  join public.sponsor_campaigns as campaigns on campaigns.id = bookings.campaign_id
  join public.sponsors on sponsors.id = campaigns.sponsor_id
  where bookings.slot_key = wanted_slot_key and bookings.cancelled_at is null and campaigns.state <> 'ended'
    and bookings.starts_on <= week_start + 6 and bookings.ends_on >= week_start
  order by bookings.starts_on limit 1;
  if booked.id is not null then
    return jsonb_build_object('week_start', week_start, 'state', 'booked', 'booking_id', booked.id,
      'campaign_name', booked.campaign_name, 'sponsor_name', booked.sponsor_name);
  end if;
  -- Step 2: one of staff's own house ads for this slot or any slot.
  select house_ads.title_en into house_title from public.house_ads
  where house_ads.archived_at is null and (house_ads.slot_key is null or house_ads.slot_key = wanted_slot_key)
    and house_ads.starts_on <= week_start + 6 and house_ads.ends_on >= week_start
  order by house_ads.slot_key is null, house_ads.starts_on limit 1;
  if house_title is not null then
    return jsonb_build_object('week_start', week_start, 'state', 'house', 'house_title', house_title);
  end if;
  -- Step 3: the network for a wide slot when it is on, else our built-in ads.
  return jsonb_build_object('week_start', week_start,
    'state', case when network_ready and slot_format = 'wide' then 'network' else 'free' end);
end;
$$;


ALTER FUNCTION "public"."ad_placement_week"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "week_start" "date", "network_ready" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ad_placement_week"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "week_start" "date", "network_ready" boolean) IS 'Internal: what fills one ad slot in one week, for Staff › Sponsors › Placements (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."ad_slot_is_booked"("wanted_slot_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.ad_bookings as bookings
    join public.sponsor_campaigns as campaigns on campaigns.id = bookings.campaign_id
    where bookings.slot_key = wanted_slot_key and bookings.cancelled_at is null
      and public.romania_today() between bookings.starts_on and bookings.ends_on
      and public.sponsor_campaign_is_live(campaigns));
$$;


