COMMENT ON FUNCTION "public"."ad_slot_is_booked"("wanted_slot_key" "text") IS 'Internal: a live booking holds this ad slot today (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."add_bible_section"("story_slug" "text", "section_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your story bible.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if (select count(*) from public.story_bible_sections where story_id = target_story_id) >= 50 then
    raise exception 'A bible can hold at most 50 sections.' using errcode = 'check_violation', hint = 'too_many_sections';
  end if;
  -- At the end; the table's checks refuse an empty or over-long name.
  insert into public.story_bible_sections (story_id, user_id, name, position)
  select target_story_id, (select auth.uid()), btrim(public.normalise_romanian_letters(coalesce(section_name, ''))),
    coalesce(max(position), 0) + 1
  from public.story_bible_sections where story_id = target_story_id
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_bible_section"("story_slug" "text", "section_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_bible_section"("story_slug" "text", "section_name" "text") IS 'Adds a section of the writer''s own at the end of one of their story bibles (S1-E17-17).';



CREATE OR REPLACE FUNCTION "public"."add_chapter_scene"("chapter_code" "text", "scene_title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_plan public.chapter_plans;
  new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your chapter plan.' using errcode = 'insufficient_privilege';
  end if;
  target_plan := public.my_chapter_plan(chapter_code);
  if target_plan.chapter_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if (select count(*) from public.chapter_scenes where chapter_id = target_plan.chapter_id) >= 100 then
    raise exception 'A chapter can hold at most 100 scenes.' using errcode = 'check_violation', hint = 'too_many_scenes';
  end if;
  insert into public.chapter_scenes (chapter_id, story_id, user_id, position, title)
  select target_plan.chapter_id, target_plan.story_id, target_plan.user_id, coalesce(max(position), 0) + 1,
    public.plan_text(scene_title)
  from public.chapter_scenes where chapter_id = target_plan.chapter_id
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_chapter_scene"("chapter_code" "text", "scene_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_chapter_scene"("chapter_code" "text", "scene_title" "text") IS 'Adds a scene at the end of one of the caller''s chapters (S1-E17-25).';



