COMMENT ON FUNCTION "public"."add_chapter_share"("target_chapter_id" "uuid") IS 'Internal: adds one to today''s share total for a chapter; never records who (S1-E4-05).';



CREATE OR REPLACE FUNCTION "public"."add_chapter_to_act"("story_slug" "text", "act_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  target_act public.story_plan_acts;
  made jsonb;
  goal integer;
begin
  -- Step 1: the story and the act (create_chapter() checks the account gate again).
  if (select auth.uid()) is null then
    raise exception 'Sign in to add a chapter.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  select * into target_act from public.story_plan_acts
  where story_plan_acts.id = public.act_of_story(target_story_id, act_id);
  -- Step 2: the chapter, at the end of the book for now.
  made := public.create_chapter(story_slug);
  if made ->> 'outcome' <> 'ok' or target_act.id is null then
    return made;
  end if;
  -- Step 3: its place: after the last chapter of this act or an earlier one (0 for none).
  select coalesce(max(chapters.position), 0) + 1 into goal
  from public.chapters
  join public.chapter_plans as plans on plans.chapter_id = chapters.id
  join public.story_plan_acts as acts on acts.id = plans.act_id
  where chapters.story_id = target_story_id and chapters.deleted_at is null
    and acts.position <= target_act.position;
  -- Step 4: the chapters from there on move one place down; the new one takes the gap.
  update public.chapters set position = position + 1
  where chapters.story_id = target_story_id and chapters.deleted_at is null
    and chapters.position >= goal and chapters.code <> made ->> 'code';
  update public.chapters set position = goal where chapters.code = made ->> 'code';
  update public.chapter_plans set act_id = target_act.id
  where chapter_plans.chapter_id = (select chapters.id from public.chapters where chapters.code = made ->> 'code');
  return jsonb_build_object('outcome', 'ok', 'code', made ->> 'code', 'position', goal);
end;
$$;


ALTER FUNCTION "public"."add_chapter_to_act"("story_slug" "text", "act_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_chapter_to_act"("story_slug" "text", "act_id" "text") IS 'Adds a draft chapter at the end of one of the caller''s acts (S1-E17-19).';



CREATE OR REPLACE FUNCTION "public"."add_character_detail"("story_slug" "text", "field_name" "text", "sheet_group" "text", "own_group" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  wanted_group text := nullif(btrim(coalesce(own_group, '')), '');
  wanted_name text := btrim(coalesce(field_name, ''));
  new_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story.
  if caller_id is null then
    raise exception 'Sign in to add a detail.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- One change to a story's details at a time: two presses of "Add" at the same moment wait
  -- for each other, so the checks below see the first one's detail (break test, 10 Nov 2026).
  perform pg_advisory_xact_lock(hashtext('story_character_fields:' || target_story_id::text));
  -- Step 2: one place at most.
  if sheet_group is not null and wanted_group is not null then
    raise exception 'A detail sits in one place.'
      using errcode = 'check_violation', hint = 'two_places';
  end if;
  -- A group that differs only in capitals is the same group: the detail joins it under the
  -- spelling it already has, so a sheet never shows "Magic" and "magic" as two cards.
  if wanted_group is not null then
    wanted_group := coalesce(
      (select fields.own_group from public.story_character_fields as fields
       where fields.story_id = target_story_id and lower(fields.own_group) = lower(wanted_group)
       order by fields.position limit 1),
      wanted_group);
  end if;
  -- One name once in a place (removed details included: they come back from the at-a-glance
  -- page), so two boxes with the same label never sit side by side.
  if exists (select 1 from public.story_character_fields as fields
             where fields.story_id = target_story_id
               and lower(fields.name) = lower(wanted_name)
               and fields.sheet_group is not distinct from add_character_detail.sheet_group
               and fields.own_group is not distinct from wanted_group) then
    raise exception 'This place already has a detail with that name.'
      using errcode = 'check_violation', hint = 'detail_name_taken';
  end if;
  -- Step 3: the bounds. 40 details as in add_character_field(), hidden ones included (they keep
  -- their values); 12 groups of the writer's own, so a sheet stays readable.
  if (select count(*) from public.story_character_fields where story_id = target_story_id) >= 40 then
    raise exception 'A story can hold at most 40 character fields of your own.'
      using errcode = 'check_violation', hint = 'too_many_fields';
  end if;
  if wanted_group is not null
     and not exists (select 1 from public.story_character_fields as fields
                     where fields.story_id = target_story_id and fields.own_group = wanted_group)
     and (select count(distinct fields.own_group) from public.story_character_fields as fields
          where fields.story_id = target_story_id) >= 12 then
    raise exception 'A story can hold at most 12 groups of your own details.'
      using errcode = 'check_violation', hint = 'too_many_groups';
  end if;
  -- Step 4: the detail, after the others.
  insert into public.story_character_fields (story_id, user_id, position, name, sheet_group, own_group)
  values (target_story_id, caller_id,
    coalesce((select max(position) from public.story_character_fields where story_id = target_story_id), 0) + 1,
    wanted_name, sheet_group, wanted_group)
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_character_detail"("story_slug" "text", "field_name" "text", "sheet_group" "text", "own_group" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_character_detail"("story_slug" "text", "field_name" "text", "sheet_group" "text", "own_group" "text") IS 'Adds one of the caller''s own details to every character sheet of a story, under a built-in group, in a group of their own or in neither (GAPS-1; S1-E17-10).';



CREATE OR REPLACE FUNCTION "public"."add_character_field"("story_slug" "text", "field_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  new_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story.
  if caller_id is null then
    raise exception 'Sign in to add a field.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the bound, counting hidden fields too (they keep their values).
  if (select count(*) from public.story_character_fields where story_id = target_story_id) >= 40 then
    raise exception 'A story can hold at most 40 character fields of your own.'
      using errcode = 'check_violation', hint = 'too_many_fields';
  end if;
  -- Step 3: the field, after the others.
  insert into public.story_character_fields (story_id, user_id, position, name)
  values (target_story_id, caller_id,
    coalesce((select max(position) from public.story_character_fields where story_id = target_story_id), 0) + 1,
    btrim(field_name))
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_character_field"("story_slug" "text", "field_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_character_field"("story_slug" "text", "field_name" "text") IS 'Adds a custom field to every character sheet of one of the caller''s stories (S1-E17-10).';



CREATE OR REPLACE FUNCTION "public"."add_character_relationship"("from_character_id" "uuid", "to_character_id" "uuid", "relationship_kind" "text", "custom_label" "text", "note" "text", "reverse_label" "text" DEFAULT ''::"text", "cousin_degree" integer DEFAULT NULL::integer, "cousin_removed" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  from_character public.story_characters;
  to_character public.story_characters;
  is_custom boolean := relationship_kind = 'custom';
  is_cousin boolean := relationship_kind = 'cousin_of';
  -- The types that say the same thing from both sides.
  reads_both_ways boolean := relationship_kind in
    ('sibling_of', 'partner_of', 'cousin_of', 'friend_of', 'ally_of', 'enemy_of');
  new_id uuid;
begin
  -- Step 1: a signed-in writer and two of their own characters.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your characters.' using errcode = 'insufficient_privilege';
  end if;
  from_character := public.my_story_character(from_character_id);
  to_character := public.my_story_character(to_character_id);
  if from_character.id is null or to_character.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: both in the same story, within the bound.
  if from_character.story_id <> to_character.story_id then
    raise exception 'Both characters must be in the same story.'
      using errcode = 'check_violation', hint = 'different_stories';
  end if;
  -- One add at a time per story, so two clicks at once can't both pass the checks below.
  perform pg_advisory_xact_lock(hashtext('story_character_relationships:' || from_character.story_id));
  if (select count(*) from public.story_character_relationships
      where story_id = from_character.story_id) >= 2000 then
    raise exception 'A story can hold at most 2,000 relationships.'
      using errcode = 'check_violation', hint = 'too_many_relationships';
  end if;
  -- Step 3: the same relationship is recorded once.
  if not is_custom and exists (
    select 1 from public.story_character_relationships as existing
    where existing.kind = relationship_kind
      and ((existing.from_character_id = from_character.id and existing.to_character_id = to_character.id)
        or (reads_both_ways
            and existing.from_character_id = to_character.id and existing.to_character_id = from_character.id))
  ) then
    raise exception 'That relationship is already there.'
      using errcode = 'check_violation', hint = 'already_there';
  end if;
  -- Step 4: the relationship; values that don't belong to its type are dropped, and the table's
  -- checks refuse the rest (a custom one with no label, a cousin with no degree).
  insert into public.story_character_relationships
    (story_id, user_id, from_character_id, to_character_id, kind, custom_label, reverse_label,
     note, cousin_degree, cousin_removed)
  values (from_character.story_id, from_character.user_id, from_character.id, to_character.id,
    relationship_kind,
    case when is_custom then btrim(coalesce(custom_label, '')) else '' end,
    case when is_custom then btrim(coalesce(reverse_label, '')) else '' end,
    btrim(coalesce(note, '')),
    case when is_cousin then cousin_degree end,
    case when is_cousin then coalesce(cousin_removed, 0) end)
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_character_relationship"("from_character_id" "uuid", "to_character_id" "uuid", "relationship_kind" "text", "custom_label" "text", "note" "text", "reverse_label" "text", "cousin_degree" integer, "cousin_removed" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_character_relationship"("from_character_id" "uuid", "to_character_id" "uuid", "relationship_kind" "text", "custom_label" "text", "note" "text", "reverse_label" "text", "cousin_degree" integer, "cousin_removed" integer) IS 'Records how two of the caller''s characters are connected, once: the same relationship a second time is refused (S1-E17-14, G10b, GAPS-3).';



CREATE TABLE IF NOT EXISTS "public"."cases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reference" "text" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "item_type" "public"."reportable_type" NOT NULL,
    "item_id" "uuid" NOT NULL,
    "source" "public"."case_source" NOT NULL,
    "tier" "public"."case_tier" NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deadline_at" timestamp with time zone NOT NULL,
    "top_reason" "public"."report_reason",
    "report_count" integer DEFAULT 0 NOT NULL,
    "reporter_under_18" boolean DEFAULT false NOT NULL,
    "is_safeguarding" boolean DEFAULT false NOT NULL,
    "status" "public"."case_status" DEFAULT 'open'::"public"."case_status" NOT NULL,
    "decision" "public"."moderation_action",
    "decided_at" timestamp with time zone,
    "decided_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "disabled_at" timestamp with time zone,
    "preserve_until" timestamp with time zone,
    "claimed_by_user_id" "uuid",
    "claimed_at" timestamp with time zone,
    CONSTRAINT "cases_claim_fields_go_together" CHECK ((("claimed_by_user_id" IS NULL) = ("claimed_at" IS NULL))),
    CONSTRAINT "cases_decided_fields_go_together" CHECK ((("status" = 'decided'::"public"."case_status") = (("decision" IS NOT NULL) AND ("decided_at" IS NOT NULL) AND ("decided_by_user_id" IS NOT NULL))))
);


