CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "number" bigint DEFAULT "nextval"('"public"."support_ticket_number_seq"'::"regclass") NOT NULL,
    "requester_user_id" "uuid",
    "requester_email" "text",
    "language" "text" DEFAULT 'ro'::"text" NOT NULL,
    "subject" "text" NOT NULL,
    "channel" "public"."support_ticket_channel" NOT NULL,
    "status" "public"."support_ticket_status" DEFAULT 'new'::"public"."support_ticket_status" NOT NULL,
    "priority" "public"."support_ticket_priority" DEFAULT 'normal'::"public"."support_ticket_priority" NOT NULL,
    "category" "public"."support_ticket_category" DEFAULT 'other'::"public"."support_ticket_category" NOT NULL,
    "assigned_to_user_id" "uuid",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "first_replied_at" timestamp with time zone,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "solved_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "follow_up_of_ticket_id" "uuid",
    "is_spam" boolean DEFAULT false NOT NULL,
    "marked_spam_at" timestamp with time zone,
    "merged_into_ticket_id" "uuid",
    CONSTRAINT "support_tickets_email_shape" CHECK ((("requester_email" IS NULL) OR (("char_length"("requester_email") <= 254) AND ("requester_email" ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::"text")))),
    CONSTRAINT "support_tickets_language_is_known" CHECK (("language" = ANY (ARRAY['ro'::"text", 'en'::"text"]))),
    CONSTRAINT "support_tickets_not_merged_into_itself" CHECK ((("merged_into_ticket_id" IS NULL) OR ("merged_into_ticket_id" <> "id"))),
    CONSTRAINT "support_tickets_someone_to_answer" CHECK ((("requester_user_id" IS NOT NULL) OR ("requester_email" IS NOT NULL))),
    CONSTRAINT "support_tickets_subject_length" CHECK ((("char_length"("btrim"("subject")) >= 1) AND ("char_length"("btrim"("subject")) <= 150))),
    CONSTRAINT "support_tickets_tags_shape" CHECK ((("cardinality"("tags") <= 10) AND (("cardinality"("tags") = 0) OR ("array_to_string"("tags", ' '::"text") ~ '^[a-z0-9-]{1,30}( [a-z0-9-]{1,30})*$'::"text"))))
);


