COMMENT ON FUNCTION "public"."add_email_to_support_ticket"("ticket" "public"."support_tickets", "body" "text", "email_message_id" "text") IS 'Internal: an incoming email joins its support ticket, which opens again when it was waiting or solved (S1-E11-13).';



CREATE OR REPLACE FUNCTION "public"."add_marketing_detail"("story_slug" "text", "detail_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  clean_name text := public.plan_text(detail_name);
  current_details jsonb;
  new_id uuid := gen_random_uuid();
begin
  -- Step 1: a signed-in writer and their own planned story.
  if caller_id is null then
    raise exception 'Sign in to add a detail.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: a real name.
  if char_length(clean_name) not between 1 and 80 then
    raise exception 'A detail''s name has 1 to 80 characters.'
      using errcode = 'check_violation', hint = 'name_length';
  end if;
  -- Step 3: the row, made empty on the first save, then the bound.
  insert into public.story_marketing (story_id, user_id) values (target_story_id, caller_id)
  on conflict (story_id) do nothing;
  -- The row is locked until this change ends: two presses of "Add" at the same moment wait for
  -- each other, so the checks below see the first one's detail (break test, 10 Nov 2026).
  select own_details into current_details from public.story_marketing
  where story_id = target_story_id for update;
  -- One name once, capitals aside, so two boxes never carry the same label.
  if exists (select 1 from jsonb_array_elements(current_details) as detail
             where lower(detail ->> 'name') = lower(clean_name)) then
    raise exception 'This story already has a marketing detail with that name.'
      using errcode = 'check_violation', hint = 'name_taken';
  end if;
  if jsonb_array_length(current_details) >= 12 then
    raise exception 'A story can hold at most 12 marketing details of your own.'
      using errcode = 'check_violation', hint = 'too_many_details';
  end if;
  -- Step 4: the detail, after the others.
  update public.story_marketing
  set own_details = own_details || jsonb_build_object('id', new_id, 'name', clean_name, 'text', '')
  where story_id = target_story_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_marketing_detail"("story_slug" "text", "detail_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_marketing_detail"("story_slug" "text", "detail_name" "text") IS 'Adds one of the caller''s own details to a story''s marketing notes (GAPS-2b; S1-E17-29).';



CREATE OR REPLACE FUNCTION "public"."add_plan_act"("story_slug" "text", "act_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  new_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story.
  if caller_id is null then
    raise exception 'Sign in to add an act.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- One change to a story's acts at a time: two presses of "Add" at the same moment wait for
  -- each other, so the checks below see the first one's act (break test, 10 Nov 2026).
  perform pg_advisory_xact_lock(hashtext('story_plan_acts:' || target_story_id::text));
  -- Step 2: one name once, capitals aside, so two columns never carry the same heading.
  if exists (select 1 from public.story_plan_acts as acts
             where acts.story_id = target_story_id
               and lower(acts.name) = lower(btrim(coalesce(act_name, '')))) then
    raise exception 'This story already has an act with that name.'
      using errcode = 'check_violation', hint = 'name_taken';
  end if;
  -- The bound. 12 acts, so the board stays readable (builder's choice, GAPS-2a).
  if (select count(*) from public.story_plan_acts where story_id = target_story_id) >= 12 then
    raise exception 'A story can hold at most 12 acts.'
      using errcode = 'check_violation', hint = 'too_many_acts';
  end if;
  -- Step 3: the act, after the others.
  insert into public.story_plan_acts (story_id, user_id, position, name)
  values (target_story_id, caller_id,
    coalesce((select max(position) from public.story_plan_acts where story_id = target_story_id), 0) + 1,
    btrim(act_name))
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_plan_act"("story_slug" "text", "act_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_plan_act"("story_slug" "text", "act_name" "text") IS 'Adds an act to the caller''s own story plan, after the acts it has (GAPS-2a; S1-E17-01).';



CREATE OR REPLACE FUNCTION "public"."add_reading_minute"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := (select auth.uid());
  habit public.reading_habits;
  today date;
  day_row public.reading_minutes;
begin
  -- Step 1: a signed-in reader with the streak on.
  if caller is null then
    raise exception 'Log in to count your reading.' using errcode = '42501';
  end if;
  select * into habit from public.reading_habits where reading_habits.user_id = caller;
  if habit.id is null then
    return 0;
  end if;
  -- Step 2: today's row, created with the first minute.
  today := (now() at time zone habit.time_zone)::date;
  insert into public.reading_minutes (user_id, read_on, minutes) values (caller, today, 1)
  on conflict (user_id, read_on) do nothing
  returning * into day_row;
  if day_row.id is not null then
    return 1;
  end if;
  -- Step 3: one more minute, unless one came in the last 45 seconds or the day is full.
  update public.reading_minutes set minutes = reading_minutes.minutes + 1
  where reading_minutes.user_id = caller and reading_minutes.read_on = today
    and reading_minutes.updated_at < now() - interval '45 seconds'
    and reading_minutes.minutes < 1440;
  return (select reading_minutes.minutes from public.reading_minutes
    where reading_minutes.user_id = caller and reading_minutes.read_on = today);
end;
$$;


ALTER FUNCTION "public"."add_reading_minute"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_reading_minute"() IS 'Adds one minute of reading to the caller''s day, for their private streak (IDEAS-1b).';



CREATE OR REPLACE FUNCTION "public"."add_story_event"("story_slug" "text", "event_title" "text", "display_date" "text", "sort_value" numeric, "description" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  new_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story with its plan.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your timeline.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null or not exists (
    select 1 from public.story_plans where story_plans.story_id = target_story_id) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: a sort value is needed to place it; a bound on how many.
  if sort_value is null then
    raise exception 'An event needs a number to sort by.' using errcode = 'check_violation', hint = 'sort_value_required';
  end if;
  if (select count(*) from public.story_events where story_events.story_id = target_story_id) >= 500 then
    raise exception 'A timeline can hold at most 500 events.' using errcode = 'check_violation', hint = 'too_many_events';
  end if;
  -- Step 3: the event, its texts cleaned (rule 4).
  insert into public.story_events (story_id, user_id, title, display_date, sort_value, description)
  values (target_story_id, (select auth.uid()), public.plan_text(event_title), public.plan_text(display_date),
          sort_value, public.plan_text(description))
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_story_event"("story_slug" "text", "event_title" "text", "display_date" "text", "sort_value" numeric, "description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_story_event"("story_slug" "text", "event_title" "text", "display_date" "text", "sort_value" numeric, "description" "text") IS 'Adds an event to the caller''s story timeline (S1-E17-20).';



CREATE OR REPLACE FUNCTION "public"."add_story_idea"("story_slug" "text", "idea_kind" "text", "idea_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to add a note.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if (select count(*) from public.story_ideas where story_ideas.story_id = target_story_id) >= 1000 then
    raise exception 'A story can hold at most 1,000 notes.' using errcode = 'check_violation', hint = 'too_many_ideas';
  end if;
  insert into public.story_ideas (story_id, user_id, kind, body)
  values (target_story_id, (select auth.uid()), idea_kind, public.plan_text(idea_body))
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."add_story_idea"("story_slug" "text", "idea_kind" "text", "idea_body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_story_idea"("story_slug" "text", "idea_kind" "text", "idea_body" "text") IS 'Adds a question, idea, to-do or decision to one of the caller''s stories (S1-E17-27).';



CREATE OR REPLACE FUNCTION "public"."admin_abuse_image_evidence"("target_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('safeguarding', 'view') then
    raise exception 'Only safeguarding staff can see this.' using errcode = 'insufficient_privilege';
  end if;
  return (select jsonb_build_object(
      'id', evidence.id, 'source', evidence.source, 'uploadedAt', evidence.uploaded_at,
      'reportedAt', evidence.reported_at, 'fileSha256', evidence.file_sha256,
      'hasScrambledIp', evidence.uploader_ip_scrambled is not null, 'ipPeriod', evidence.uploader_ip_period,
      'description', evidence.description,
      'describedBy', (select profiles.handle from public.profiles where profiles.id = evidence.described_by_user_id),
      'keepUntil', evidence.keep_until, 'legalHold', evidence.legal_hold,
      'legalHoldReason', evidence.legal_hold_reason,
      'accountClosed', (public.active_sanction(evidence.user_id, 'ban')).id is not null,
      'uploaderIsStaff', exists (select 1 from public.staff_roles where staff_roles.user_id = evidence.user_id),
      'uploaderLocale', (select profiles.locale from public.profiles where profiles.id = evidence.user_id))
    from public.abuse_image_evidence as evidence where evidence.case_id = target_case_id);
end;
$$;


ALTER FUNCTION "public"."admin_abuse_image_evidence"("target_case_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_abuse_image_evidence"("target_case_id" "uuid") IS 'Safeguarding staff: the evidence about a case''s suspected abuse image (ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."admin_account_notes"("target_user_id" "uuid", "page_number" integer DEFAULT 1, "page_size" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "body" "text", "author_handle" "text", "author_user_id_short" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  -- Step 1: keep the page size and number sensible whatever the screen sends.
  rows_per_page integer := least(greatest(coalesce(page_size, 20), 1), 50);
  rows_to_skip integer := (greatest(coalesce(page_number, 1), 1) - 1) * rows_per_page;
begin
  -- Step 2: only staff who may open accounts, in a staff session.
  if not public.staff_may('users', 'view') then
    raise exception 'Only staff with the Users area can read notes on an account.'
      using errcode = 'insufficient_privilege';
  end if;
  -- Step 3: the page, with the count of every note on the account beside each row.
  return query
    select notes.id, notes.body, authors.handle, left(notes.author_user_id::text, 8),
           notes.created_at, count(*) over ()
    from public.account_staff_notes as notes
    left join public.profiles as authors on authors.id = notes.author_user_id
    where notes.user_id = target_user_id
    order by notes.created_at desc, notes.id
    limit rows_per_page offset rows_to_skip;
end;
$$;


ALTER FUNCTION "public"."admin_account_notes"("target_user_id" "uuid", "page_number" integer, "page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_account_notes"("target_user_id" "uuid", "page_number" integer, "page_size" integer) IS 'One page of the staff notes on an account, newest first, for staff with the Users area (LOGS-1a).';



CREATE OR REPLACE FUNCTION "public"."admin_account_open_cases"("target_user_id" "uuid") RETURNS TABLE("case_id" "uuid", "reference" "text", "item_type" "public"."reportable_type", "top_reason" "public"."report_reason", "tier" "public"."case_tier", "deadline_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('moderation', 'view') then
    raise exception 'Only moderation staff can see cases.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  return query
    select cases.id, cases.reference, cases.item_type, cases.top_reason, cases.tier, cases.deadline_at
    from public.cases
    where cases.user_id = target_user_id and cases.status = 'open'
      and public.may_see_case(cases.is_safeguarding)
    order by cases.deadline_at;
end;
$$;


ALTER FUNCTION "public"."admin_account_open_cases"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_account_open_cases"("target_user_id" "uuid") IS 'The open cases about an account that the caller may see, most urgent first (S1-E11-02).';



CREATE OR REPLACE FUNCTION "public"."admin_account_sanctions"("target_user_id" "uuid") RETURNS TABLE("id" "uuid", "kind" "public"."sanction_kind", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "lifted_at" timestamp with time zone, "note" "text", "applied_by_handle" "text", "case_reference" "text", "is_live" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('user_sanctions', 'view') then
    raise exception 'Only moderation staff can see sanctions.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select sanctions.id, sanctions.kind, sanctions.starts_at, sanctions.ends_at, sanctions.lifted_at,
           sanctions.note, staff.handle, cases.reference,
           -- A warning is a record, never "live"; the others are live until they end or are lifted.
           sanctions.kind <> 'warning' and sanctions.lifted_at is null
             and (sanctions.ends_at is null or sanctions.ends_at > now())
    from public.sanctions
    join public.profiles as staff on staff.id = sanctions.applied_by_user_id
    left join public.cases on cases.id = sanctions.case_id
    where sanctions.user_id = target_user_id
    order by sanctions.starts_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_account_sanctions"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_account_sanctions"("target_user_id" "uuid") IS 'An account''s sanction history, for staff (S1-E10-06).';



CREATE OR REPLACE FUNCTION "public"."admin_acknowledge_on_call_alert"("alert_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  alert public.on_call_alerts;
begin
  if not public.staff_may('removal_orders', 'act') then
    raise exception 'Only someone with the on-call permission can acknowledge an alert.' using errcode = 'insufficient_privilege';
  end if;
  select * into alert from public.on_call_alerts where on_call_alerts.id = alert_id for update;
  if alert.id is null or alert.acknowledged_at is not null then
    raise exception 'This alert is already acknowledged.' using errcode = 'check_violation';
  end if;
  update public.on_call_alerts set acknowledged_at = now(), acknowledged_by_user_id = (select auth.uid())
  where on_call_alerts.id = alert.id;
  perform public.log_staff_action('on_call.alert_acknowledged', 'on_call_alerts', alert.id::text, null, null,
    null, jsonb_build_object('case_id', alert.case_id, 'acknowledged_at', now()));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_acknowledge_on_call_alert"("alert_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_acknowledge_on_call_alert"("alert_id" "uuid") IS 'On-call staff acknowledge a removal-order alert, which stops its escalation; logged (S1-E10-09).';



CREATE OR REPLACE FUNCTION "public"."admin_ad_placements"("week_count" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  first_monday date := date_trunc('week', public.romania_today())::date;
  weeks date[];
  network_ready boolean := public.ad_network_is_ready();
begin
  perform public.require_sponsor_staff();
  -- Step 1: the Mondays shown, 1 to 12 of them.
  select array_agg(first_monday + 7 * step order by step) into weeks
  from generate_series(0, least(greatest(coalesce(week_count, 6), 1), 12) - 1) as step;
  -- Step 2: each slot with each week's state, then the bookings for the list under the grid.
  return jsonb_build_object(
    'weeks', to_jsonb(weeks),
    'network_ready', network_ready,
    'slots', coalesce((
      select jsonb_agg(jsonb_build_object('slot_key', ad_slots.slot_key, 'page_key', ad_slots.page_key,
          'position', ad_slots.position, 'format', ad_slots.format, 'is_on', ad_slots.is_on,
          'weeks', (select jsonb_agg(public.ad_placement_week(ad_slots.slot_key, ad_slots.format, monday, network_ready)
                                     order by monday) from unnest(weeks) as monday))
        order by ad_slots.page_key, ad_slots.position)
      from public.ad_slots), '[]'::jsonb),
    'bookings', coalesce((
      select jsonb_agg(to_jsonb(bookings) || jsonb_build_object('campaign_name', campaigns.name,
          'sponsor_name', sponsors.name) order by bookings.starts_on, bookings.slot_key)
      from public.ad_bookings as bookings
      join public.sponsor_campaigns as campaigns on campaigns.id = bookings.campaign_id
      join public.sponsors on sponsors.id = campaigns.sponsor_id
      where bookings.cancelled_at is null and campaigns.state <> 'ended'
        and bookings.ends_on >= public.romania_today()), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."admin_ad_placements"("week_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_ad_placements"("week_count" integer) IS 'Every ad slot against the next weeks (Booked, House ad, Ad network or Free) and the bookings; owner and admin only (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."admin_add_account_note"("target_user_id" "uuid", "body" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_body text;
  new_note_id uuid;
begin
  -- Step 1: only staff who may open accounts, in a staff session.
  if not public.staff_may('users', 'view') then
    raise exception 'Only staff with the Users area can leave notes on an account.'
      using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the account must exist.
  if not exists (select 1 from public.profiles where profiles.id = target_user_id) then
    raise exception 'There is no such account.' using errcode = 'no_data_found';
  end if;
  -- Step 3: trim the note and refuse an empty or too long one, with a plain message.
  clean_body := public.clean_mail_text(body, 2000);
  -- Step 4: store it, with the signed-in staff member as its author.
  insert into public.account_staff_notes (user_id, author_user_id, body)
  values (target_user_id, (select auth.uid()), clean_body)
  returning id into new_note_id;
  -- Step 5: the audit row, in the same transaction, without the words.
  perform public.log_staff_action('account.note_added', 'account_staff_notes',
    new_note_id::text, target_user_id, null, null, null);
  return new_note_id;
end;
$$;


ALTER FUNCTION "public"."admin_add_account_note"("target_user_id" "uuid", "body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_add_account_note"("target_user_id" "uuid", "body" "text") IS 'Staff with the Users area leave a note on an account; logged without the words (LOGS-1a).';



