CREATE OR REPLACE FUNCTION "public"."admin_add_classic_author"("author_name" "text", "died" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_name text := public.normalise_romanian_letters(regexp_replace(btrim(coalesce(author_name, '')), '\s+', ' ', 'g'));
  existing public.classic_authors;
  new_id uuid;
begin
  perform public.require_classics_staff();
  -- Step 1: the same name (ignoring case) is the same author, if the year agrees.
  select * into existing from public.classic_authors where lower(classic_authors.name) = lower(clean_name);
  if found then
    if existing.died_year <> died then
      raise exception 'This author is already listed with another year of death.'
        using errcode = 'check_violation', hint = 'author_died_year_differs';
    end if;
    return existing.id;
  end if;
  -- Step 2: a new author; the table's checks refuse a blank name or an impossible year.
  insert into public.classic_authors (name, died_year) values (clean_name, died) returning id into new_id;
  perform public.log_staff_action('classics.author_added', 'classic_authors', new_id::text, null, null,
    null, jsonb_build_object('name', clean_name, 'died_year', died));
  return new_id;
end;
$$;


ALTER FUNCTION "public"."admin_add_classic_author"("author_name" "text", "died" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_add_name_word"("word_language" "text", "new_word" "text", "how_it_matches" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  added_id uuid;
begin
  perform public.require_settings_staff();
  if btrim(coalesce(new_word, '')) = '' or word_language not in ('ro', 'en') then
    raise exception 'Type a word and pick Română or English.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.username_word_lists
             where language = word_language and lower(word) = lower(btrim(new_word))) then
    raise exception 'That word is already on the list.' using errcode = 'unique_violation';
  end if;
  insert into public.username_word_lists (language, word, match_rule)
  values (word_language, btrim(new_word), how_it_matches)
  returning id into added_id;
  perform public.log_staff_action('settings.name_word_added', 'username_word_lists', added_id::text, null, null,
    null, jsonb_build_object('language', word_language, 'word', btrim(new_word), 'match_rule', how_it_matches));
  return added_id;
end;
$$;


ALTER FUNCTION "public"."admin_add_name_word"("word_language" "text", "new_word" "text", "how_it_matches" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_add_name_word"("word_language" "text", "new_word" "text", "how_it_matches" "text") IS 'Adds a word to a username word list; owner and admin only; logged (S1-E11-03, S1-E2-04).';



CREATE OR REPLACE FUNCTION "public"."admin_add_nudge_word"("word_language" "text", "new_phrase" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_phrase text := btrim(coalesce(new_phrase, ''));
  added_id uuid;
begin
  perform public.require_settings_staff();
  -- Step 1: a phrase of 1 to 60 characters, in one of the two lists.
  if clean_phrase = '' or char_length(clean_phrase) > 60 or word_language not in ('ro', 'en') then
    raise exception 'Type a word or phrase of up to 60 characters and pick Română or English.'
      using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.comment_nudge_words
             where language = word_language and lower(phrase) = lower(clean_phrase)) then
    raise exception 'That phrase is already on the list.' using errcode = 'unique_violation';
  end if;
  -- Step 2: add it and log it in the same transaction.
  insert into public.comment_nudge_words (language, phrase)
  values (word_language, clean_phrase)
  returning id into added_id;
  perform public.log_staff_action('settings.nudge_word_added', 'comment_nudge_words', added_id::text, null, null,
    null, jsonb_build_object('language', word_language, 'phrase', clean_phrase));
  return added_id;
end;
$$;


ALTER FUNCTION "public"."admin_add_nudge_word"("word_language" "text", "new_phrase" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_add_nudge_word"("word_language" "text", "new_phrase" "text") IS 'Adds a phrase to a comment nudge list; owner and admin only; logged (Robert, 2 Nov 2026).';



CREATE OR REPLACE FUNCTION "public"."admin_add_reserved_name"("new_name" "text", "how_it_matches" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  added_id uuid;
begin
  perform public.require_settings_staff();
  if btrim(coalesce(new_name, '')) = '' then
    raise exception 'Type the name to reserve.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.reserved_names where lower(name) = lower(btrim(new_name))) then
    raise exception 'That name is already reserved.' using errcode = 'unique_violation';
