CREATE OR REPLACE FUNCTION "public"."admin_admit_from_waitlist"("entry_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wanted uuid;
  admitted integer := 0;
begin
  -- Step 1: owner and admin only, in a staff session.
  if not public.staff_may('waitlist', 'act') then
    raise exception 'Only an owner or admin can let people in.' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(cardinality(entry_ids), 0) not between 1 and 100 then
    raise exception 'Tick 1 to 100 people.' using errcode = 'check_violation', hint = 'pick_people';
  end if;
  -- Step 2: each person, in the order ticked.
  foreach wanted in array entry_ids loop
    if public.admit_waitlist_entry(wanted, 'one_by_one') then
      admitted := admitted + 1;
    end if;
  end loop;
  return admitted;
end;
$$;


ALTER FUNCTION "public"."admin_admit_from_waitlist"("entry_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_admit_from_waitlist"("entry_ids" "uuid"[]) IS 'Staff › Waitlist: lets the ticked people in and emails each "You''re in"; audited (WAITLIST-1).';



CREATE OR REPLACE FUNCTION "public"."admin_admit_waitlist_wave"("wanted_interest" "text", "wanted_country" "text", "how_many" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  country_filter text := nullif(upper(btrim(coalesce(wanted_country, ''))), '');
  interest_filter text := nullif(btrim(coalesce(wanted_interest, '')), '');
  next_entry uuid;
  admitted integer := 0;
begin
  -- Step 1: owner and admin only, in a staff session, with a sensible size.
  if not public.staff_may('waitlist', 'act') then
    raise exception 'Only an owner or admin can let people in.' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(how_many, 0) not between 1 and 1000 then
    raise exception 'A wave is 1 to 1,000 people.' using errcode = 'check_violation', hint = 'wave_size';
  end if;
  -- Step 2: the oldest confirmed people who fit, each let in and told.
  for next_entry in
    select entries.id from public.waitlist_entries as entries
    join public.profiles on profiles.id = entries.user_id
    join auth.users on users.id = entries.user_id
    where entries.admitted_at is null and profiles.deleted_at is null and users.email_confirmed_at is not null
      and public.waitlist_interest_matches(entries.interest, interest_filter)
      and (country_filter is null or profiles.country_code = country_filter)
    order by entries.joined_at, entries.id
    limit how_many
  loop
    if public.admit_waitlist_entry(next_entry, 'wave') then
      admitted := admitted + 1;
    end if;
  end loop;
  return admitted;
end;
$$;


ALTER FUNCTION "public"."admin_admit_waitlist_wave"("wanted_interest" "text", "wanted_country" "text", "how_many" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_admit_waitlist_wave"("wanted_interest" "text", "wanted_country" "text", "how_many" integer) IS 'Staff › Waitlist: lets the next confirmed people in, oldest first, by interest and country; audited (WAITLIST-1).';



CREATE OR REPLACE FUNCTION "public"."admin_appeals_queue"("status_filter" "public"."appeal_status" DEFAULT NULL::"public"."appeal_status") RETURNS TABLE("id" "uuid", "reference" "text", "status" "public"."appeal_status", "statement_reference" "text", "statement_action" "public"."statement_action", "item_summary" "text", "case_reference" "text", "appellant_handle" "text", "explanation" "text", "created_at" timestamp with time zone, "original_decider_handle" "text", "may_decide" boolean, "decided_by_handle" "text", "decided_at" timestamp with time zone, "decision_note" "text", "message_to_person" "text", "decided_by_original_decider" boolean, "needs_owner_review" boolean, "may_mark_reviewed" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_is_owner boolean;
begin
  -- Step 1: only staff who decide appeals.
  if not public.staff_may('appeals', 'act') then
    raise exception 'Only staff who decide appeals can see them.' using errcode = 'insufficient_privilege';
  end if;
  caller_is_owner := public.is_staff('owner');
  -- Step 2: the appeals the caller may see (safeguarding ones need that permission).
  return query
    select appeals.id, appeals.reference, appeals.status, statements_of_reasons.reference,
      statements_of_reasons.action, statements_of_reasons.item_summary, cases.reference,
      appellant.handle, appeals.explanation, appeals.created_at, original.handle,
      appeals.status = 'open' and (appeals.original_decider_user_id is distinct from (select auth.uid())
                                   or not public.another_appeals_decider_exists()),
      decider.handle, appeals.decided_at, appeals.decision_note, appeals.message_to_person,
      appeals.decided_by_original_decider,
      appeals.decided_by_original_decider and appeals.owner_reviewed_at is null,
      caller_is_owner and appeals.decided_by_original_decider and appeals.owner_reviewed_at is null
    from public.appeals
    join public.statements_of_reasons on statements_of_reasons.id = appeals.statement_id
    join public.profiles as appellant on appellant.id = appeals.user_id
    left join public.cases on cases.id = statements_of_reasons.case_id
    left join public.profiles as original on original.id = appeals.original_decider_user_id
    left join public.profiles as decider on decider.id = appeals.decided_by_user_id
    where public.may_see_case(coalesce(cases.is_safeguarding, false))
      and (status_filter is null or appeals.status = status_filter)
    order by (appeals.status <> 'open'), case when appeals.status = 'open' then appeals.created_at end,
      appeals.decided_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_appeals_queue"("status_filter" "public"."appeal_status") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_appeals_queue"("status_filter" "public"."appeal_status") IS 'Appeals for staff: open ones oldest first, with who may decide each and whether the owner must review a same-moderator decision (S1-E10-07; QA-7).';



CREATE OR REPLACE FUNCTION "public"."admin_apply_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind", "days" integer DEFAULT NULL::integer, "source_case_id" "uuid" DEFAULT NULL::"uuid", "note_text" "text" DEFAULT NULL::"text", "message_to_person" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_sanction public.sanctions;
  target_email text;
  hash text;
begin
  -- Step 1: may act, and never on a staff account (staff powers are removed first, S1-E2-07a).
  if not public.staff_may('user_sanctions', 'act') then
    raise exception 'Only moderation staff can apply a sanction.' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from public.staff_roles where staff_roles.user_id = target_user_id) then
    raise exception 'A staff account can''t be sanctioned; remove its role first.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(note_text, '')) = '' then
    raise exception 'Write a note with the sanction.' using errcode = 'check_violation';
  end if;
  -- Step 2: one live sanction of a kind at a time (a warning is only a record, so any number).
  if wanted_kind <> 'warning' and (public.active_sanction(target_user_id, wanted_kind)).id is not null then
    raise exception 'This account already has a live % .', wanted_kind using errcode = 'check_violation';
  end if;
  -- Step 3: the row.
  insert into public.sanctions (user_id, kind, case_id, applied_by_user_id, note, ends_at)
  values (target_user_id, wanted_kind, source_case_id, (select auth.uid()), btrim(note_text),
          public.sanction_end(wanted_kind, days))
  returning * into new_sanction;
  -- Step 4: a ban reaches Supabase Auth, ends every session and blocks the email (Q7, Q8).
  if wanted_kind = 'ban' then
    update auth.users set banned_until = now() + interval '100 years' where users.id = target_user_id
      returning users.email into target_email;
    perform public.sign_out_everywhere(target_user_id);
    hash := public.banned_email_hash(target_email);
    if hash is not null then
      insert into public.banned_email_hashes (email_hash, sanction_id) values (hash, new_sanction.id)
        on conflict (email_hash) do nothing;
    end if;
  end if;
  -- Step 5: the audit row, in the same transaction.
  perform public.log_staff_action(
    'sanction.applied', 'sanctions', new_sanction.id::text, target_user_id, btrim(note_text),
    null,
    jsonb_build_object('kind', wanted_kind, 'ends_at', new_sanction.ends_at, 'case_id', source_case_id,
                       'email_blocked', hash is not null)
  );
  -- Step 6: outside a case, the statement of reasons (S1-E10-04); a case sends its own.
  if source_case_id is null then
    perform public.issue_statement_of_reasons(target_user_id,
      case wanted_kind when 'warning' then 'warn' when 'suspension' then 'suspend'
        when 'ban' then 'ban' else 'reporting_pause' end::public.statement_action,
      'terms', 'community_rules', message_to_person,
      jsonb_build_object('sanction_id', new_sanction.id, 'item_type', 'profile', 'item_id', target_user_id,
        'restriction_ends_at', new_sanction.ends_at));
  end if;
  return new_sanction.id;
end;
$$;


ALTER FUNCTION "public"."admin_apply_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind", "days" integer, "source_case_id" "uuid", "note_text" "text", "message_to_person" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_apply_sanction"("target_user_id" "uuid", "wanted_kind" "public"."sanction_kind", "days" integer, "source_case_id" "uuid", "note_text" "text", "message_to_person" "text") IS 'Warns, suspends, bans or pauses reporting, logged; outside a case it sends the statement of reasons (S1-E10-06, S1-E10-04).';



CREATE TABLE IF NOT EXISTS "public"."stories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "slug" "text" NOT NULL,
    "title" "text" NOT NULL,
    "blurb" "text" DEFAULT ''::"text" NOT NULL,
    "language_code" "text" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "cover_kind" "public"."cover_kind" DEFAULT 'automatic'::"public"."cover_kind" NOT NULL,
    "cover_design" "text",
    "cover_background" "text",
    "cover_accent" "text",
    "cover_tall_path" "text",
    "cover_square_path" "text",
    "first_published_at" timestamp with time zone,
    "last_chapter_published_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completion_status" "public"."completion_status" DEFAULT 'ongoing'::"public"."completion_status" NOT NULL,
    "comments_enabled" boolean DEFAULT true NOT NULL,
    "rating" "public"."story_rating" NOT NULL,
    "is_fan_fiction" boolean DEFAULT false NOT NULL,
    "is_parody" boolean DEFAULT false NOT NULL,
    "deals_with_abuse_or_coercion" boolean DEFAULT false NOT NULL,
    "content_note" "text" DEFAULT ''::"text" NOT NULL,
    "ai_disclosure" "public"."ai_disclosure" DEFAULT 'no_ai'::"public"."ai_disclosure" NOT NULL,
    "ai_undisclosed_labelled_at" timestamp with time zone,
    "classic_author_id" "uuid",
    "rank_badge_tag_ids" "uuid"[],
    "quote_cards_enabled" boolean DEFAULT true NOT NULL,
    "picture_sharing_enabled" boolean DEFAULT true NOT NULL,
    "card_colour" "text",
    "class_only" boolean DEFAULT false NOT NULL,
    "class_space_id" "uuid",
    "title_hidden_at" timestamp with time zone,
    "cover_hidden_at" timestamp with time zone,
    "rating_reasons" "public"."story_rating_reason"[] DEFAULT '{}'::"public"."story_rating_reason"[] NOT NULL,
    "visibility" "public"."story_visibility" DEFAULT 'public'::"public"."story_visibility" NOT NULL,
    "first_published_year" integer,
    "writing_prompt_id" "uuid",
    "is_app_only" boolean DEFAULT false NOT NULL,
    CONSTRAINT "stories_abuse_needs_rating_and_note" CHECK (((NOT "deals_with_abuse_or_coercion") OR (("rating" = ANY (ARRAY['16_plus'::"public"."story_rating", '18_plus'::"public"."story_rating"])) AND ("btrim"("content_note") <> ''::"text")))),
    CONSTRAINT "stories_blurb_length" CHECK (("char_length"("blurb") <= 500)),
    CONSTRAINT "stories_card_colour_on_palette" CHECK ((("card_colour" IS NULL) OR ("card_colour" = ANY (ARRAY['plum'::"text", 'violet'::"text", 'gold'::"text", 'ink'::"text", 'lilac'::"text", 'blush'::"text", 'sky'::"text", 'sage'::"text", 'paper'::"text"])))),
    CONSTRAINT "stories_class_link_only_when_class_only" CHECK (("class_only" OR ("class_space_id" IS NULL))),
    CONSTRAINT "stories_content_note_length" CHECK (("char_length"("content_note") <= 300)),
    CONSTRAINT "stories_cover_colours_are_in_the_palette" CHECK (((("cover_background" IS NULL) OR ("cover_background" = ANY (ARRAY['plum'::"text", 'ink'::"text", 'violet'::"text", 'gold'::"text", 'lilac'::"text", 'blush'::"text", 'sky'::"text", 'sage'::"text", 'paper'::"text"]))) AND (("cover_accent" IS NULL) OR ("cover_accent" = ANY (ARRAY['plum'::"text", 'ink'::"text", 'violet'::"text", 'gold'::"text", 'lilac'::"text", 'blush'::"text", 'sky'::"text", 'sage'::"text", 'paper'::"text"]))))),
    CONSTRAINT "stories_cover_columns_match_kind" CHECK (
CASE "cover_kind"
    WHEN 'automatic'::"public"."cover_kind" THEN (("cover_design" IS NULL) AND ("cover_background" IS NULL) AND ("cover_accent" IS NULL) AND ("cover_tall_path" IS NULL) AND ("cover_square_path" IS NULL))
    WHEN 'drawn'::"public"."cover_kind" THEN (("cover_design" IS NOT NULL) AND ("cover_background" IS NOT NULL) AND ("cover_accent" IS NOT NULL) AND ("cover_tall_path" IS NULL) AND ("cover_square_path" IS NULL))
    WHEN 'upload'::"public"."cover_kind" THEN (("cover_design" IS NULL) AND ("cover_background" IS NULL) AND ("cover_accent" IS NULL) AND ("cover_tall_path" IS NOT NULL))
    ELSE NULL::boolean
END),
    CONSTRAINT "stories_cover_design_is_approved" CHECK ((("cover_design" IS NULL) OR ("cover_design" = ANY (ARRAY['plum'::"text", 'ink'::"text", 'violet'::"text", 'gold'::"text", 'lilac'::"text", 'blush'::"text", 'sky'::"text", 'sage'::"text", 'paper'::"text", 'stripes'::"text", 'dots'::"text", 'grid'::"text", 'waves'::"text", 'starry'::"text", 'sparkles'::"text", 'twotone'::"text", 'arches'::"text", 'rings'::"text", 'forestwaves'::"text"])))),
    CONSTRAINT "stories_first_published_year_range" CHECK ((("first_published_year" >= 1) AND ("first_published_year" <= 2100))),
    CONSTRAINT "stories_language_code_shape" CHECK (("language_code" ~ '^[a-z]{2}(-[A-Z]{2})?$'::"text")),
    CONSTRAINT "stories_rank_badge_tag_ids_check" CHECK ((("rank_badge_tag_ids" IS NULL) OR ("cardinality"("rank_badge_tag_ids") <= 3))),
    CONSTRAINT "stories_slug_shape" CHECK ((("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text") AND ("char_length"("slug") <= 80))),
    CONSTRAINT "stories_title_length" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 120)))
);


ALTER TABLE "public"."stories" OWNER TO "postgres";


COMMENT ON TABLE "public"."stories" IS 'kind: user_content; reportable: story
One row per story, owned by the writer''s user ID; made only by create_story() (S1-E3-01).';



COMMENT ON COLUMN "public"."stories"."user_id" IS 'The writer''s permanent user ID (architecture 1.6). Never shown publicly: screens use slug and the pen name.';



COMMENT ON COLUMN "public"."stories"."slug" IS 'The public address, fixed at creation so shared links survive a rename (S1-E3-01).';



COMMENT ON COLUMN "public"."stories"."first_published_at" IS 'Set once by publish_chapter() (S1-E3-03); null means only the writer sees the story.';



COMMENT ON COLUMN "public"."stories"."completion_status" IS 'Ongoing or Completed; shown on the card and story page, a Discover filter (S1-E3-05, S1-E5-01).';



COMMENT ON COLUMN "public"."stories"."comments_enabled" IS 'Off hides existing comments and refuses new ones; enforced by S1-E6-01 (S1-E3-05).';



COMMENT ON COLUMN "public"."stories"."rating" IS 'All ages, 13+, 16+ or 18+; readers younger than it never see the story (Q17; rule 18; rating_allows()).';



COMMENT ON COLUMN "public"."stories"."deals_with_abuse_or_coercion" IS 'Abuse or coercion as a theme: must be 16+ or 18+ with a content note (17 Oct 2026).';



COMMENT ON COLUMN "public"."stories"."ai_undisclosed_labelled_at" IS 'When staff labelled the story "AI-written, not disclosed" after confirmed reports (Q24); never from a detector.';



COMMENT ON COLUMN "public"."stories"."classic_author_id" IS 'The real author of a public-domain classic, shown as its byline; null for writers'' own stories (S1-E5-06).';



COMMENT ON COLUMN "public"."stories"."rank_badge_tag_ids" IS 'The up to 3 tags the writer picked for the rank badges on the cover; null means the 3 best ranks (CMS-1g).';



COMMENT ON COLUMN "public"."stories"."quote_cards_enabled" IS 'The writer''s switch: false hides "Share quote" on every chapter of the story (S1-E4-07).';



COMMENT ON COLUMN "public"."stories"."picture_sharing_enabled" IS 'Whether readers may share this story''s chapter pictures as picture cards and links (S1-E4-11). On by default.';



COMMENT ON COLUMN "public"."stories"."card_colour" IS 'The palette colour new quote and picture cards for this story start in; null for our default (IDEAS-1c).';



COMMENT ON COLUMN "public"."stories"."class_only" IS 'kind: setting. True while the writer shares the story only with one class space (S1-E8-11).';



COMMENT ON COLUMN "public"."stories"."class_space_id" IS 'kind: link. The class space a class-only story is shared with; null once that class is gone (S1-E8-11).';



COMMENT ON COLUMN "public"."stories"."title_hidden_at" IS 'When staff hid the title on public screens (S1-E11-08); null while it shows. Cleared when the writer changes the title.';



COMMENT ON COLUMN "public"."stories"."cover_hidden_at" IS 'When staff hid the cover (S1-E11-08); readers see the automatic cover meanwhile. Cleared when the writer picks another cover.';



COMMENT ON COLUMN "public"."stories"."rating_reasons" IS 'Why the story is 16+ or 18+, ticked by the writer (staff may add); empty for All ages and 13+. Sexual content, nudity or graphic violence keep network ads off its pages (SPONSORS-f).';



COMMENT ON COLUMN "public"."stories"."visibility" IS 'kind: setting. Who can read the story: public, unlisted (link only, in no list) or private (the writer only) (NEW-1).';



COMMENT ON COLUMN "public"."stories"."first_published_year" IS 'The year the work was first published anywhere; set for classics from classic_works (copied by a trigger). Null for a writer''s own story, whose first chapter''s year is shown instead.';



COMMENT ON COLUMN "public"."stories"."writing_prompt_id" IS 'The writing prompt this story was started from, or null (GAPS-12c).';



COMMENT ON COLUMN "public"."stories"."is_app_only" IS 'The writer chose "In the app only" (S1-E3-08). Applies only while the app_only_stories flag is on (GAPS-15).';



COMMENT ON CONSTRAINT "stories_cover_design_is_approved" ON "public"."stories" IS 'A drawn cover uses one of the designs the app can draw (src/components/covers/coverDesigns.ts); "doodles" was renamed "sparkles" in NO-DOODLES, and G9c added arches, rings and forestwaves.';



CREATE OR REPLACE FUNCTION "public"."admin_apply_story_settings"("story_row" "public"."stories", "changes" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_language text := coalesce(changes ->> 'language_code', story_row.language_code);
  new_category_id uuid;
  new_labels jsonb;
begin
  -- Step 1: category and language, checked as when the writer saves (S1-E3-01).
  new_category_id := public.check_story_basics(story_row.title, story_row.blurb, new_language,
    coalesce(changes ->> 'category_slug',
      (select categories.slug from public.categories where categories.id = story_row.category_id)));
  -- Step 2: the labels, filled from the row and checked together (S1-E3-06).
  new_labels := jsonb_build_object('rating', story_row.rating, 'is_fan_fiction', story_row.is_fan_fiction,
    'is_parody', story_row.is_parody, 'deals_with_abuse_or_coercion', story_row.deals_with_abuse_or_coercion,
    'content_note', story_row.content_note, 'ai_disclosure', story_row.ai_disclosure,
    'rating_reasons', to_jsonb(story_row.rating_reasons))
    || jsonb_strip_nulls(jsonb_build_object('rating', changes -> 'rating', 'rating_reasons', changes -> 'rating_reasons',
      'is_fan_fiction', changes -> 'is_fan_fiction', 'is_parody', changes -> 'is_parody',
      'deals_with_abuse_or_coercion', changes -> 'deals_with_abuse_or_coercion'));
  perform public.check_story_labels(new_labels);
  -- Step 3: save.
  update public.stories set
    language_code = new_language,
    category_id = new_category_id,
    completion_status = coalesce((changes ->> 'completion_status')::public.completion_status, completion_status),
    comments_enabled = coalesce((changes ->> 'comments_enabled')::boolean, comments_enabled),
    rating = (new_labels ->> 'rating')::public.story_rating,
    is_fan_fiction = (new_labels ->> 'is_fan_fiction')::boolean,
    is_parody = (new_labels ->> 'is_parody')::boolean,
    deals_with_abuse_or_coercion = (new_labels ->> 'deals_with_abuse_or_coercion')::boolean,
    -- Staff may add a reason; sexual content, nudity or graphic violence turn network ads off.
    rating_reasons = public.story_rating_reasons_from(new_labels)
  where stories.id = story_row.id;
  -- Step 4: the tags, when given, through the writer's own tag rules (new names wait for staff).
  if changes ? 'tag_names' then
    if jsonb_array_length(changes -> 'tag_names') > 10 then
      raise exception 'A story can have at most 10 tags (S1-E3-01).' using errcode = 'check_violation';
    end if;
    perform public.set_story_tags(story_row.id, story_row.user_id,
      array(select jsonb_array_elements_text(changes -> 'tag_names')));
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_apply_story_settings"("story_row" "public"."stories", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_apply_story_settings"("story_row" "public"."stories", "changes" "jsonb") IS 'Internal: checks and saves the settings staff changed, never the writer''s words (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_approve_picture"("target_case_id" "uuid", "note_text" "text", "new_rating" "public"."story_rating" DEFAULT NULL::"public"."story_rating") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases := public.picture_review_case(target_case_id);
  picture public.picture_checks;
begin
  -- Step 1: a note, and the picture the case is about.
  if btrim(coalesce(note_text, '')) = '' then
    raise exception 'Write a note with the decision.' using errcode = 'check_violation';
  end if;
  select * into picture from public.picture_checks where picture_checks.id = target.item_id;
  -- Step 2: yellow raises the story first (its own statement of reasons and audit row).
  if new_rating is not null then
    perform public.raise_rating_for_picture(picture, new_rating, note_text);
  end if;
  -- Step 3: no action on the case approves the picture; decide_case() writes the audit row.
  perform public.decide_case(target, 'no_action', note_text, null, null, false);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_approve_picture"("target_case_id" "uuid", "note_text" "text", "new_rating" "public"."story_rating") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_approve_picture"("target_case_id" "uuid", "note_text" "text", "new_rating" "public"."story_rating") IS 'Staff: approves a waiting picture, optionally raising its story to 16+ or 18+ first (ADMIN-2e1b).';



CREATE OR REPLACE FUNCTION "public"."admin_approve_username"("target_user_id" "uuid", "name_kind" "text", "approved_name" "text", "reason_given" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  approval_id uuid;
begin
  -- Step 1: owner, admin or moderator, in a staff session (architecture 1.8.3, Users: sanctions).
  if not public.staff_may('user_sanctions', 'act') then
    raise exception 'Only moderators can approve a name.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: save the approval (the table refuses a blank reason or an unknown kind).
  insert into public.username_approvals (
    user_id, name_kind, approved_name, approved_skeleton, approved_by_user_id, reason
  )
  values (
    target_user_id, name_kind, approved_name, public.username_skeleton(approved_name),
    (select auth.uid()), coalesce(reason_given, '')
  )
  returning id into approval_id;
  -- Step 3: the audit log, in the same transaction.
  perform public.log_staff_action(
    'username.approved', 'username_approvals', approval_id::text, target_user_id, reason_given,
    null, jsonb_build_object('name_kind', name_kind, 'approved_name', approved_name)
  );
  return approval_id;
end;
$$;


ALTER FUNCTION "public"."admin_approve_username"("target_user_id" "uuid", "name_kind" "text", "approved_name" "text", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_approve_username"("target_user_id" "uuid", "name_kind" "text", "approved_name" "text", "reason_given" "text") IS 'A moderator approves one exact name refused by mistake; logged (S1-E2-04, S1-E11-02).';



