CREATE OR REPLACE FUNCTION "public"."admin_ask_data_request_confirmation"("target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
begin
  -- Step 1: only a request that still needs the check.
  if request.identity = 'not_needed' then
    raise exception 'This request was made inside the account.' using errcode = 'check_violation', hint = 'no_check_needed';
  end if;
  if request.identity in ('confirmed', 'denied') then
    raise exception 'The person has already answered.' using errcode = 'check_violation', hint = 'already_answered';
  end if;
  -- Step 2: about an under-16, the check goes to the parent or guardian (GDPR art. 8; part c2).
  if public.data_request_person_is_under_16(request.user_id) then
    raise exception 'This person is under 16: the request goes through their parent or guardian.'
      using errcode = 'check_violation', hint = 'parent_needed';
  end if;
  -- Step 3: ask, log it and tell the person (always sent, by email to the account's own address).
  update public.data_requests set identity = 'asked', identity_asked_at = now(),
    handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id returning * into request;
  perform public.log_staff_action('data_request.confirmation_asked', 'data_requests', request.id::text,
    request.user_id, null, null, jsonb_build_object('method', 'sign_in'));
  perform public.notify(request.user_id, 'data_request_confirm', null,
    jsonb_build_object('data_request_id', request.id));
  return public.data_request_json(request);
end;
$$;


ALTER FUNCTION "public"."admin_ask_data_request_confirmation"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_ask_data_request_confirmation"("target_request_id" "uuid") IS 'Staff ask the person to confirm, signed in, that a data request was theirs (S1-E11-09; GDPR art. 12(6)).';



CREATE OR REPLACE FUNCTION "public"."admin_ask_data_request_parent"("target_request_id" "uuid", "token_hash" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
  consent public.parental_consents := public.data_request_parent_consent(request.user_id);
begin
  -- Step 1: only our server makes the link, so only the parent's inbox ever holds it.
  if not public.data_request_parent_is_signed('ask', request.id, token_hash, signature) then
    raise exception 'This request wasn''t signed by our server.'
      using errcode = 'insufficient_privilege', hint = 'unsigned';
  end if;
  -- Step 2: a check that is still open, about an under-16, with a parent on record.
  if request.identity = 'not_needed' then
    raise exception 'The request came from inside the account.' using errcode = 'check_violation', hint = 'no_check_needed';
  end if;
  if request.identity in ('confirmed', 'denied') then
    raise exception 'The check is already answered.' using errcode = 'check_violation', hint = 'already_answered';
  end if;
  if not public.data_request_person_is_under_16(request.user_id) then
    raise exception 'This person is 16 or over.' using errcode = 'check_violation', hint = 'not_under_16';
  end if;
  if consent.id is null then
    raise exception 'No parent or guardian agreed for this account.'
      using errcode = 'check_violation', hint = 'no_parent_on_record';
  end if;
  -- Step 3: the request goes through the parent; only the hash of the new link is kept.
  update public.data_requests
  set goes_to_parent = true, identity = 'asked', identity_asked_at = now(),
      parent_check_token_hash = lower(token_hash), handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id;
  perform public.log_staff_action('data_request.parent_asked', 'data_requests', request.id::text,
    request.user_id, null, jsonb_build_object('identity', request.identity),
    jsonb_build_object('identity', 'asked', 'method', 'parent_link'));
  return public.data_request_parent_email(request, consent);
end;
$$;


ALTER FUNCTION "public"."admin_ask_data_request_parent"("target_request_id" "uuid", "token_hash" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_ask_data_request_parent"("target_request_id" "uuid", "token_hash" "text", "signature" "text") IS 'Staff ask an under-16''s parent or guardian to confirm a data request, signed by our server (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_assign_mail"("thread_reference" "text", "assignee_handle" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.moderator_mail_threads := public.require_mail_thread_for_staff(thread_reference);
  assignee_id uuid;
begin
  if nullif(btrim(assignee_handle), '') is not null then
    select profiles.id into assignee_id from public.profiles
    join public.staff_roles on staff_roles.user_id = profiles.id
    join public.staff_role_areas on staff_role_areas.role = staff_roles.role
      and staff_role_areas.area = 'moderation' and staff_role_areas.access = 'act'
    where profiles.handle = btrim(assignee_handle, ' @') limit 1;
    if assignee_id is null then
      raise exception '@% can''t answer moderator mail.', btrim(assignee_handle, ' @') using errcode = 'check_violation';
    end if;
  end if;
  update public.moderator_mail_threads set assigned_to_user_id = assignee_id where id = thread.id;
  perform public.log_staff_action('moderator_mail.assigned', 'moderator_mail_threads', thread.id::text, thread.user_id, null,
    jsonb_build_object('assigned_to_user_id', thread.assigned_to_user_id), jsonb_build_object('assigned_to_user_id', assignee_id));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_assign_mail"("thread_reference" "text", "assignee_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_assign_mail"("thread_reference" "text", "assignee_handle" "text") IS 'Assigns a moderator mail thread to a moderator or nobody, logged (S1-E10-11).';



CREATE OR REPLACE FUNCTION "public"."admin_book_ad_slot"("target_campaign_id" "uuid", "fields" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  campaign public.sponsor_campaigns;
  first_day date := (fields ->> 'starts_on')::date;
  last_day date := (fields ->> 'ends_on')::date;
  targets record;
  new_id uuid;
begin
  -- Step 1: only owner and admin, and only an approved banner campaign.
  perform public.require_sponsor_staff();
  campaign := public.locked_sponsor_campaign(target_campaign_id, array['approved']::public.sponsor_campaign_state[]);
  if campaign.placement in ('category', 'contest') then
    raise exception 'A "Sponsored by" credit doesn''t go in an ad slot.' using errcode = 'check_violation';
  end if;
  -- Step 2: the booking stays inside the campaign's own dates.
  if first_day < campaign.starts_on or last_day > campaign.ends_on then
    raise exception 'Book days inside the campaign''s own dates.' using errcode = 'check_violation',
      detail = campaign.starts_on || ' to ' || campaign.ends_on;
  end if;
  -- Step 3: the slot is free on those days, then the booking is saved and logged.
  perform public.require_free_ad_slot(fields ->> 'slot_key', first_day, last_day, null);
  select * into targets from public.ad_booking_targets(fields);
  insert into public.ad_bookings (user_id, campaign_id, slot_key, starts_on, ends_on,
    target_categories, target_tags, target_languages)
  values (auth.uid(), campaign.id, fields ->> 'slot_key', first_day, last_day,
    targets.categories, targets.tags, targets.languages)
  returning id into new_id;
  perform public.log_staff_action('ad_booking.made', 'ad_bookings', new_id::text, null, null, null,
    (select to_jsonb(bookings) from public.ad_bookings as bookings where bookings.id = new_id));
  return new_id;
end;
$$;


ALTER FUNCTION "public"."admin_book_ad_slot"("target_campaign_id" "uuid", "fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_book_ad_slot"("target_campaign_id" "uuid", "fields" "jsonb") IS 'Books an approved campaign into one ad slot for some days, refusing clashes; owner and admin only; logged (S1-E12-05).';



