CREATE OR REPLACE FUNCTION "public"."admin_case_message"("target_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
  chat public.conversations;
begin
  -- Step 1: staff who may see this case, in the same order as the other case panels.
  select * into target from public.cases where id = target_case_id;
  if target.id is null or not public.staff_may('moderation', 'view') or not public.may_see_case(target.is_safeguarding) then
    raise exception 'You can''t see this case.' using errcode = 'insufficient_privilege';
  end if;
  if target.item_type <> 'message' then
    return null;
  end if;
  -- Step 2: the chat the message belongs to; nothing when it has gone since the report.
  select conversations.* into chat
  from public.conversations
  join public.messages on messages.conversation_id = conversations.id
  where messages.id = target.item_id;
  if chat.id is null then
    return jsonb_build_object('between', '[]'::jsonb, 'messages', '[]'::jsonb);
  end if;
  -- Step 3: reading private messages is a sensitive read, logged before anything is returned.
  perform public.log_staff_action('sensitive_read.case_message', 'messages', target.item_id::text, target.user_id);
  -- Step 4: the two people and the messages.
  return jsonb_build_object(
    'between', (select jsonb_agg(profiles.handle order by profiles.handle)
      from public.profiles where profiles.id in (chat.user_id, chat.recipient_user_id)),
    'messages', public.message_with_context(target.item_id));
end;
$$;


ALTER FUNCTION "public"."admin_case_message"("target_case_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_case_message"("target_case_id" "uuid") IS 'A message case''s reported message and up to 20 before it, for the case page; a logged sensitive read (S1-E9-02).';



CREATE OR REPLACE FUNCTION "public"."admin_case_notices"("target_case_id" "uuid") RETURNS TABLE("notice_id" "uuid", "reference" "text", "kind" "text", "reason" "public"."report_reason", "content_url" "text", "explanation" "text", "notifier_name" "text", "notifier_email" "text", "authority_name" "text", "order_reference" "text", "copy_source_title" "text", "copy_source_author" "text", "copy_source_reference" "text", "copy_source_passage" "text", "language" "text", "received_at" timestamp with time zone, "alerted_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: only staff who may see this case.
  if not exists (select 1 from public.cases where cases.id = target_case_id and public.may_see_case(cases.is_safeguarding)) then
    raise exception 'You can''t see this case.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: its notices, with the alert time for an order.
  return query
    select public_notices.id, public_notices.reference, public_notices.kind, public_notices.reason,
           public_notices.content_url, public_notices.explanation, public_notices.notifier_name,
           public_notices.notifier_email, public_notices.authority_name, public_notices.order_reference,
           public_notices.copy_source_title, public_notices.copy_source_author,
           public_notices.copy_source_reference, public_notices.copy_source_passage,
           public_notices.language, public_notices.received_at,
           (select min(on_call_alerts.created_at) from public.on_call_alerts where on_call_alerts.notice_id = public_notices.id)
    from public.public_notices
    where public_notices.case_id = target_case_id
    order by public_notices.received_at;
end;
$$;


