CREATE OR REPLACE FUNCTION "public"."admin_change_ad_booking"("target_booking_id" "uuid", "fields" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  booking public.ad_bookings;
  campaign public.sponsor_campaigns;
  first_day date := (fields ->> 'starts_on')::date;
  last_day date := (fields ->> 'ends_on')::date;
  targets record;
begin
  -- Step 1: only owner and admin, and only a booking that still stands.
  perform public.require_sponsor_staff();
  select * into booking from public.ad_bookings where id = target_booking_id for update;
  if booking.id is null then
    raise exception 'No such booking.' using errcode = 'no_data_found';
  elsif booking.cancelled_at is not null then
    raise exception 'That booking was cancelled.' using errcode = 'check_violation';
  end if;
  -- Step 2: the new days sit inside the campaign's dates and clash with no other booking.
  select * into campaign from public.sponsor_campaigns where id = booking.campaign_id;
  if first_day < campaign.starts_on or last_day > campaign.ends_on then
    raise exception 'Book days inside the campaign''s own dates.' using errcode = 'check_violation',
      detail = campaign.starts_on || ' to ' || campaign.ends_on;
  end if;
  perform public.require_free_ad_slot(booking.slot_key, first_day, last_day, booking.id);
  -- Step 3: save and log the before and after.
  select * into targets from public.ad_booking_targets(fields);
  update public.ad_bookings
  set starts_on = first_day, ends_on = last_day, target_categories = targets.categories,
      target_tags = targets.tags, target_languages = targets.languages
  where id = booking.id;
  perform public.log_staff_action('ad_booking.changed', 'ad_bookings', booking.id::text, null, null,
    to_jsonb(booking), (select to_jsonb(bookings) from public.ad_bookings as bookings where bookings.id = booking.id));
end;
$$;


ALTER FUNCTION "public"."admin_change_ad_booking"("target_booking_id" "uuid", "fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_change_ad_booking"("target_booking_id" "uuid", "fields" "jsonb") IS 'Changes a slot booking''s days or pages, refusing clashes; owner and admin only; logged (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."admin_change_story_settings"("target_story_id" "uuid", "changes" "jsonb", "reason_code" "text", "reason_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story_row public.stories := public.admin_story_change_target(target_story_id, reason_code, reason_text);
  settings_before jsonb := public.admin_story_settings_json(story_row);
  settings_after jsonb;
  changed_fields text[];
  revision_id uuid;
  rating_went_up boolean;
begin
  -- Step 1: save, then read back what is saved now.
  perform public.admin_apply_story_settings(story_row, coalesce(changes, '{}'::jsonb));
  select public.admin_story_settings_json(stories) into settings_after
  from public.stories where stories.id = story_row.id;
  -- Step 2: only the fields that really changed go into the version.
  select array_agg(field order by field) into changed_fields
  from jsonb_object_keys(settings_after) as field
  where settings_after -> field is distinct from settings_before -> field;
  if changed_fields is null then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'nothing_changed';
  end if;
  -- Step 3: a raised rating restricts who can read it, so it needs a statement of reasons.
  rating_went_up := (settings_after ->> 'rating')::public.story_rating > story_row.rating;
  revision_id := public.admin_record_story_change(story_row, null, 'settings', reason_code, reason_text,
    (select jsonb_object_agg(field, settings_before -> field) from unnest(changed_fields) as field),
    (select jsonb_object_agg(field, settings_after -> field) from unnest(changed_fields) as field),
    case when rating_went_up then 'rating_raised'::public.statement_action end);
  return jsonb_build_object('revision_id', revision_id, 'changed', to_jsonb(changed_fields),
    'statement_sent', rating_went_up);
end;
$$;


ALTER FUNCTION "public"."admin_change_story_settings"("target_story_id" "uuid", "changes" "jsonb", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_change_story_settings"("target_story_id" "uuid", "changes" "jsonb", "reason_code" "text", "reason_text" "text") IS 'Staff change a story''s settings and details with a reason; versioned, audited, the writer told (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_chapter_text"("target_chapter_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter_row public.chapters;
begin
  -- Step 1: only staff who may change stories need the words.
  if not public.staff_may('story_changes', 'act') then
    raise exception 'Only owner, admin and moderator staff can read a chapter here.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: a live chapter with published words.
  select * into chapter_row from public.chapters
  where chapters.id = target_chapter_id and chapters.deleted_at is null;
  if not found then
    raise exception 'There is no such chapter.' using errcode = 'check_violation', hint = 'no_such_story';
  end if;
  if chapter_row.published_body is null then
    raise exception 'This chapter has never been published.'
      using errcode = 'check_violation', hint = 'not_published';
  end if;
  return jsonb_build_object('chapter_id', chapter_row.id, 'number', chapter_row.position,
    'title', chapter_row.published_title, 'text', chapter_row.published_body);
end;
$$;


