CREATE OR REPLACE FUNCTION "public"."admin_close_account_for_abuse_image"("target_case_id" "uuid", "note_text" "text", "account_message" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
begin
  if not public.staff_may('safeguarding', 'act') or not public.staff_may('user_sanctions', 'act') then
    raise exception 'Only safeguarding staff can close the account.' using errcode = 'insufficient_privilege';
  end if;
  select cases.* into target from public.cases
    join public.abuse_image_evidence on abuse_image_evidence.case_id = cases.id
    where cases.id = target_case_id;
  if target.id is null then
    raise exception 'This case has no suspected abuse image.' using errcode = 'no_data_found';
  end if;
  if btrim(coalesce(note_text, '')) = '' or btrim(coalesce(account_message, '')) = ''
     or char_length(account_message) > 4000 then
    raise exception 'Write the note and the message.' using errcode = 'check_violation';
  end if;
  return public.close_account_for_abuse_image(target, note_text, account_message);
end;
$$;


ALTER FUNCTION "public"."admin_close_account_for_abuse_image"("target_case_id" "uuid", "note_text" "text", "account_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_close_account_for_abuse_image"("target_case_id" "uuid", "note_text" "text", "account_message" "text") IS 'Safeguarding staff: closes the account that uploaded a matched abuse image for good (ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."admin_close_data_request"("target_request_id" "uuid", "outcome" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
begin
  if btrim(coalesce(outcome, '')) = '' or char_length(outcome) > 2000 then
    raise exception 'Say what was done, in at most 2000 characters.'
      using errcode = 'check_violation', hint = 'outcome_needed';
  end if;
  update public.data_requests set state = 'closed', closed_at = now(), outcome = btrim(admin_close_data_request.outcome),
    handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id returning * into request;
  perform public.log_staff_action('data_request.closed', 'data_requests', request.id::text, request.user_id,
    request.outcome, jsonb_build_object('state', 'open'),
    jsonb_build_object('state', 'closed', 'identity', request.identity,
      'deadline', public.data_request_deadline(request)));
  return public.data_request_json(request);
end;
$$;


