COMMENT ON FUNCTION "public"."admin_close_data_request"("target_request_id" "uuid", "outcome" "text") IS 'Staff close a data request with what was done (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_close_unmatched_notice"("target_notice_id" "uuid", "note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  notice public.public_notices;
begin
  -- Step 1: who may act, and on which notice.
  select * into notice from public.public_notices
    where id = target_notice_id and case_id is null and closed_at is null for update;
  if notice.id is null then
    raise exception 'There is no open unmatched notice like that.' using errcode = 'no_data_found';
  end if;
  if not public.staff_may('moderation', 'act')
     or not public.may_see_case(notice.reason in ('child_sexual_content', 'threat_to_minor')) then
    raise exception 'Only moderators close notices.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_staff_session() then
    raise exception 'Sign in again as staff to do this.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(note, '')) = '' then
    raise exception 'Write a note saying what you found.' using errcode = 'check_violation';
  end if;
  -- Step 2: closed and decided, so the decision email goes out (S1-E10-04), and audited.
  update public.public_notices set decided_at = now(), closed_at = now() where id = notice.id;
  perform public.log_staff_action('notice.closed_unmatched', 'public_notices', notice.id::text, null,
    btrim(note), null, jsonb_build_object('reference', notice.reference));
end;
$$;


ALTER FUNCTION "public"."admin_close_unmatched_notice"("target_notice_id" "uuid", "note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_close_unmatched_notice"("target_notice_id" "uuid", "note" "text") IS 'Staff: closes an unmatched public notice with a note, audited (S1-E10-02).';



CREATE OR REPLACE FUNCTION "public"."admin_complete_compliance_entry"("entry_reference" "text", "action" "text", "done_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  entry public.compliance_log_entries;
  finished_at timestamptz := coalesce(done_at, now());
  problem text;
begin
  perform public.require_compliance_staff();
  -- Step 1: the entry, locked for the change.
  select * into entry from public.compliance_log_entries where reference = entry_reference for update;
  if entry.id is null then
    raise exception 'There is no compliance log entry %.', entry_reference using errcode = 'no_data_found';
  end if;
  -- Step 2: only an open entry can be finished, with an action and a possible time.
  problem := case
    when entry.completed_at is not null then 'already_done'
    when nullif(btrim(action), '') is null then 'empty'
    when char_length(btrim(action)) > 2000 then 'too_long'
    else public.compliance_times_problem(entry.received_at, finished_at)
  end;
  if problem is not null then
    raise exception 'This entry can''t be finished (%).', problem using errcode = 'check_violation', hint = problem;
  end if;
  -- Step 3: the change and its log line.
  update public.compliance_log_entries
  set action_taken = btrim(action), completed_at = finished_at, completed_by_user_id = (select auth.uid())
  where id = entry.id;
  perform public.log_staff_action('compliance_log.entry_completed', 'compliance_log_entries', entry.id::text,
    null, null, jsonb_build_object('action_taken', null, 'completed_at', null),
    jsonb_build_object('action_taken', btrim(action), 'completed_at', finished_at));
  return finished_at;
end;
$$;


ALTER FUNCTION "public"."admin_complete_compliance_entry"("entry_reference" "text", "action" "text", "done_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_complete_compliance_entry"("entry_reference" "text", "action" "text", "done_at" timestamp with time zone) IS 'Records the action and time on an open compliance log entry; done entries are locked; audited (S1-E11-04).';



CREATE OR REPLACE FUNCTION "public"."admin_compliance_log"("for_export" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  entries jsonb;
begin
  perform public.require_compliance_staff();
  -- Step 1: the logged entries and the removal orders, newest first.
  select coalesce(jsonb_agg(row_value order by (row_value ->> 'received_at')::timestamptz desc), '[]'::jsonb)
  into entries
  from (
    select jsonb_build_object('reference', reference, 'source', 'log', 'kind', entry_kind,
      'authority', authority, 'received_at', received_at, 'content', content,
      'action_taken', action_taken, 'decision', null, 'completed_at', completed_at) as row_value
    from public.compliance_log_entries
    union all
    select public.removal_order_log_rows()
  ) as rows;
  -- Step 2: a download is a sensitive read, so it goes in the audit log.
  if for_export then
    perform public.log_staff_action('compliance_log.exported', 'compliance_log_entries', null, null, null,
      null, jsonb_build_object('rows', jsonb_array_length(entries)));
  end if;
  return jsonb_build_object('entries', entries, 'launch', public.launch_task());
end;
$$;


ALTER FUNCTION "public"."admin_compliance_log"("for_export" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_compliance_log"("for_export" boolean) IS 'The compliance log with removal orders and the launch task; owner and admin only; exports audited (S1-E11-04).';



