COMMENT ON FUNCTION "public"."admin_create_class_space"("teacher_handle" "text", "name" "text", "school_name" "text", "description" "text") IS 'Staff (Schools): sets up a class space owned by a named teacher (S1-E8-11 criterion 10).';



CREATE OR REPLACE FUNCTION "public"."admin_create_contest"("landing_slug" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  page public.landing_pages;
  new_contest_id uuid;
begin
  perform public.require_contest_staff();
  -- Step 1: a contest landing page that has no contest yet.
  select * into page from public.landing_pages
  where slug = lower(btrim(coalesce(landing_slug, ''))) and archived_at is null;
  if page.id is null then
    raise exception 'No landing page has that address.' using errcode = 'no_data_found';
  end if;
  if page.page_type <> 'contest' then
    raise exception 'Pick a contest landing page.' using errcode = 'check_violation', hint = 'not_a_contest_page';
  end if;
  if exists (select 1 from public.contests where landing_page_id = page.id) then
    raise exception 'That page already has a contest.' using errcode = 'check_violation', hint = 'already_has_contest';
  end if;
  -- Step 2: the contest, empty until staff fill it in, and the audit row.
  insert into public.contests (landing_page_id, user_id)
  values (page.id, (select auth.uid()))
  returning id into new_contest_id;
  perform public.log_staff_action('contest.created', 'contests', new_contest_id::text, null, null, null,
    jsonb_build_object('landing_page', page.slug));
  return new_contest_id;
end;
$$;


ALTER FUNCTION "public"."admin_create_contest"("landing_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_contest"("landing_slug" "text") IS 'Starts a contest on a contest landing page; owner and admin only; logged (S1-E11-15).';



CREATE OR REPLACE FUNCTION "public"."admin_create_invite"("admits" integer DEFAULT 1, "valid_days" integer DEFAULT 14, "private_note" "text" DEFAULT NULL::"text") RETURNS TABLE("invite_id" "uuid", "code" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_code text;
  new_invite public.invites;
  trimmed_note text := nullif(btrim(coalesce(private_note, '')), '');
begin
  -- Step 1: only owner and admin, in a staff session.
  if not public.staff_may('invites', 'act') then
    raise exception 'Only an owner or admin can make invite links.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the limits (decided 23 Oct 2026, Q12).
  if admits is null or admits not between 1 and 50 then
    raise exception 'A link admits between 1 and 50 people.' using errcode = 'check_violation';
  end if;
  if valid_days is null or valid_days not between 1 and 90 then
    raise exception 'A link lasts between 1 and 90 days.' using errcode = 'check_violation';
  end if;
  if trimmed_note is not null and (char_length(trimmed_note) > 80 or trimmed_note like '%@%') then
    raise exception 'The note is at most 80 characters and never an email address.'
      using errcode = 'check_violation';
  end if;
  -- Step 3: a fresh code, stored only as its hash.
  new_code := public.generate_invite_code();
  insert into public.invites (user_id, purpose, code_hash, max_uses, expires_at, note)
  values (
    (select auth.uid()), 'platform', public.invite_code_hash(new_code), admits,
    now() + make_interval(days => valid_days), trimmed_note
  )
  returning * into new_invite;
  -- Step 4: the audit row, in the same transaction.
  perform public.log_staff_action(
    'invite.created', 'invites', new_invite.id::text, null, null, null,
    jsonb_build_object('admits', admits, 'expires_at', new_invite.expires_at, 'note', trimmed_note)
  );
  return query select new_invite.id, new_code, new_invite.expires_at;
end;
$$;


ALTER FUNCTION "public"."admin_create_invite"("admits" integer, "valid_days" integer, "private_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_invite"("admits" integer, "valid_days" integer, "private_note" "text") IS 'Makes a platform invite link (owner and admin); returns the code once; logged as invite.created (S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."admin_create_landing_page"("new_slug" "text", "new_page_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_slug text := lower(btrim(coalesce(new_slug, '')));
  slug_problem text := public.landing_page_slug_problem(lower(btrim(coalesce(new_slug, ''))));
  new_page_id uuid;
begin
  perform public.require_website_staff();
  -- Step 1: a free, allowed address and a known type.
  if slug_problem is not null then
    raise exception 'That address can''t be used.' using errcode = 'check_violation', hint = slug_problem;
  end if;
  if new_page_type is null or new_page_type not in ('contest', 'campaign', 'information') then
    raise exception 'Pick contest, campaign or information.' using errcode = 'check_violation', hint = 'bad_type';
  end if;
  -- Step 2: the page and its first, empty draft.
  insert into public.landing_pages (slug, page_type, user_id)
  values (clean_slug, new_page_type, (select auth.uid()))
  returning id into new_page_id;
  insert into public.landing_page_versions (page_id, user_id) values (new_page_id, (select auth.uid()));
  perform public.log_staff_action('landing_page.created', 'landing_pages', new_page_id::text, null, null, null,
    jsonb_build_object('slug', clean_slug, 'type', new_page_type));
  return new_page_id;
end;
$$;


ALTER FUNCTION "public"."admin_create_landing_page"("new_slug" "text", "new_page_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_create_landing_page"("new_slug" "text", "new_page_type" "text") IS 'Starts a landing page at /c/<slug>; owner and admin only; logged (S1-E11-14).';



CREATE OR REPLACE FUNCTION "public"."admin_data_request"("target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests;
begin
  -- Step 1: the same checks as every action, without needing it to be open or locking it.
  if not public.staff_may('data_requests', 'act') then
    raise exception 'You can''t handle data requests.' using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  select * into request from public.data_requests where data_requests.id = target_request_id;
  if not found then
    raise exception 'There is no such request.' using errcode = 'check_violation', hint = 'no_such_request';
  end if;
  -- Step 2: the request as the staff screen shows it, with its files and what was sent.
  return public.data_request_json(request) || jsonb_build_object(
    'language', (select profiles.locale from public.profiles where profiles.id = request.user_id),
    'files', public.data_request_files_json(request.id, false),
    'copies_sent', request.copies_sent);
end;
$$;


ALTER FUNCTION "public"."admin_data_request"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_data_request"("target_request_id" "uuid") IS 'Staff open one data request (S1-E11-09).';



CREATE SEQUENCE IF NOT EXISTS "public"."data_request_reference_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."data_request_reference_seq" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."data_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reference" "text" DEFAULT ('D-'::"text" || "lpad"(("nextval"('"public"."data_request_reference_seq"'::"regclass"))::"text", 6, '0'::"text")) NOT NULL,
    "user_id" "uuid" NOT NULL,
    "request_type" "public"."data_request_type" NOT NULL,
    "channel" "public"."data_request_channel" NOT NULL,
    "received_on" "date" NOT NULL,
    "due_on" "date" NOT NULL,
    "extended_to" "date",
    "extension_reason" "text",
    "extended_at" timestamp with time zone,
    "identity" "public"."data_request_identity" NOT NULL,
    "identity_asked_at" timestamp with time zone,
    "identity_answered_at" timestamp with time zone,
    "state" "public"."data_request_state" DEFAULT 'open'::"public"."data_request_state" NOT NULL,
    "outcome" "text",
    "closed_at" timestamp with time zone,
    "note" "text" DEFAULT ''::"text" NOT NULL,
    "created_by_user_id" "uuid" NOT NULL,
    "handled_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "copies_sent" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "goes_to_parent" boolean DEFAULT false NOT NULL,
    "parent_check_token_hash" "text",
    "parent_copy_token_hash" "text",
    "parent_copy_sent_at" timestamp with time zone,
    "parent_copy_opened_at" timestamp with time zone,
    "support_ticket_id" "uuid",
    CONSTRAINT "data_requests_closed_together" CHECK ((("state" = 'closed'::"public"."data_request_state") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "data_requests_copies_sent_is_list" CHECK (("jsonb_typeof"("copies_sent") = 'array'::"text")),
    CONSTRAINT "data_requests_due_one_month" CHECK (("due_on" = (("received_on" + '1 mon'::interval))::"date")),
    CONSTRAINT "data_requests_extension_at_most_two_months" CHECK ((("extended_to" IS NULL) OR (("extended_to" > "due_on") AND ("extended_to" <= (("received_on" + '3 mons'::interval))::"date") AND ("btrim"(COALESCE("extension_reason", ''::"text")) <> ''::"text")))),
    CONSTRAINT "data_requests_note_length" CHECK (("char_length"("note") <= 2000)),
    CONSTRAINT "data_requests_outcome_length" CHECK ((("outcome" IS NULL) OR ("char_length"("outcome") <= 2000))),
    CONSTRAINT "data_requests_outcome_when_closed" CHECK ((("state" = 'open'::"public"."data_request_state") OR ("btrim"(COALESCE("outcome", ''::"text")) <> ''::"text"))),
    CONSTRAINT "data_requests_parent_links_need_parent" CHECK (("goes_to_parent" OR (("parent_check_token_hash" IS NULL) AND ("parent_copy_token_hash" IS NULL))))
);


ALTER TABLE "public"."data_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."data_requests" IS 'kind: staff
Every request to see, move, correct or delete someone''s data: dates, deadline, extension, identity check and who handled it; never the files (S1-E11-09; GDPR art. 5(2), 12). Kept as our proof.';



COMMENT ON COLUMN "public"."data_requests"."user_id" IS 'The person the request is about; staff see it, the public never (rule 15).';



COMMENT ON COLUMN "public"."data_requests"."due_on" IS 'One month from receipt (GDPR art. 12(3)); extended_to, when set, is the deadline instead.';



COMMENT ON COLUMN "public"."data_requests"."copies_sent" IS 'Every copy sent for the request: sent_at, expires_at and the files'' names and sizes, never their contents (S1-E11-09, "which files were sent").';



COMMENT ON COLUMN "public"."data_requests"."goes_to_parent" IS 'True when the request goes through the under-16''s parent or guardian (S1-E11-09 criterion 5).';



COMMENT ON COLUMN "public"."data_requests"."parent_copy_opened_at" IS 'When the parent first opened the copy''s one-time link; it works for one hour from then (proposal).';



COMMENT ON COLUMN "public"."data_requests"."support_ticket_id" IS 'The support ticket the request started from (S1-E11-13 criterion 11), or empty.';



CREATE OR REPLACE FUNCTION "public"."admin_data_request_copy_target"("target_request_id" "uuid") RETURNS "public"."data_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
begin
  if request.request_type not in ('copy', 'move') then
    raise exception 'Only a request for a copy, or to move the data, gets a copy.'
      using errcode = 'check_violation', hint = 'not_a_copy';
  end if;
  -- An under-16's request from outside their own account goes through the parent (GDPR art. 8).
  if request.identity <> 'not_needed' and not request.goes_to_parent
     and public.data_request_person_is_under_16(request.user_id) then
    raise exception 'This person is under 16: the copy goes through their parent or guardian.'
      using errcode = 'check_violation', hint = 'parent_needed';
  end if;
  if request.identity = 'denied' then
    raise exception 'The person said this request wasn''t theirs.'
      using errcode = 'check_violation', hint = 'identity_denied';
  end if;
  if request.identity not in ('not_needed', 'confirmed') then
    raise exception 'Check the person''s identity first.'
      using errcode = 'check_violation', hint = 'identity_not_checked';
  end if;
  return request;
end;
$$;


ALTER FUNCTION "public"."admin_data_request_copy_target"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_data_request_copy_target"("target_request_id" "uuid") IS 'Internal: the checks before staff build or send a data request copy (S1-E11-09).';



