ALTER FUNCTION "public"."admin_data_request_export"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_data_request_export"("target_request_id" "uuid") IS 'Staff read a data request''s person''s data, as my_data_export() gives it, logged (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_data_request_target"("target_request_id" "uuid", "must_be_open" boolean) RETURNS "public"."data_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests;
begin
  -- Step 1: the server decides who may act, never the menu (architecture 1.8.1).
  if not public.staff_may('data_requests', 'act') then
    raise exception 'Only owner, admin and support staff handle data requests.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: the request, locked so two staff members don't change it at once.
  select * into request from public.data_requests where data_requests.id = target_request_id for update;
  if not found then
    raise exception 'There is no such request.' using errcode = 'check_violation', hint = 'no_such_request';
  end if;
  if must_be_open and request.state = 'closed' then
    raise exception 'This request is closed.' using errcode = 'check_violation', hint = 'request_closed';
  end if;
  return request;
end;
$$;


ALTER FUNCTION "public"."admin_data_request_target"("target_request_id" "uuid", "must_be_open" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_data_request_target"("target_request_id" "uuid", "must_be_open" boolean) IS 'Internal: the staff, request and open checks every data request action starts with (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_data_requests"("only_open" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('data_requests', 'act') then
    raise exception 'Only owner, admin and support staff handle data requests.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  return coalesce((
    select jsonb_agg(public.data_request_json(listed) order by listed.state = 'closed',
      case when listed.state = 'open' then public.data_request_deadline(listed) end,
      listed.created_at desc)
    from (select * from public.data_requests
          where not only_open or data_requests.state = 'open'
          order by data_requests.state = 'closed', data_requests.created_at desc
          limit 200) as listed), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."admin_data_requests"("only_open" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_data_requests"("only_open" boolean) IS 'Staff list data requests, nearest deadline first (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_decide_appeal"("target_appeal_id" "uuid", "outcome" "public"."appeal_status", "note_text" "text", "message_to_person" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  appeal public.appeals;
  statement public.statements_of_reasons;
  is_same_decider boolean;
begin
  -- Step 1: may decide appeals, may see this one, and it's open.
  select * into appeal from public.appeals where id = target_appeal_id for update;
  select * into statement from public.statements_of_reasons where id = appeal.statement_id;
  if appeal.id is null or not public.staff_may('appeals', 'act') or not public.may_see_case(coalesce(
      (select cases.is_safeguarding from public.cases where cases.id = statement.case_id), false)) then
    raise exception 'You can''t decide this appeal.' using errcode = 'insufficient_privilege';
  end if;
  if appeal.status <> 'open' then
    raise exception 'This appeal is already decided.' using errcode = 'check_violation';
  end if;
  -- Step 2: a different moderator where possible (criterion 2); otherwise the same one, marked.
  is_same_decider := appeal.original_decider_user_id = (select auth.uid());
  if is_same_decider and public.another_appeals_decider_exists() then
    raise exception 'You made this decision, so another moderator decides the appeal.' using errcode = 'insufficient_privilege';
  end if;
  if outcome not in ('upheld', 'overturned') or btrim(coalesce(note_text, '')) = ''
     or btrim(coalesce(admin_decide_appeal.message_to_person, '')) = ''
     or char_length(admin_decide_appeal.message_to_person) > 4000 then
    raise exception 'Choose upheld or overturned, and write a note and a message to the person.' using errcode = 'check_violation';
  end if;
  -- Step 3: an overturned decision is undone.
  if outcome = 'overturned' then
    perform public.undo_decision_for_appeal(statement, appeal.reference);
  end if;
  -- Step 4: the appeal, the person told, the audit row (with same_decider, QA-7).
  update public.appeals set status = outcome, decided_by_user_id = (select auth.uid()), decided_at = now(),
    decision_note = btrim(note_text), message_to_person = btrim(admin_decide_appeal.message_to_person),
    decided_by_original_decider = coalesce(is_same_decider, false)
  where id = appeal.id;
  perform public.notify(appeal.user_id, 'appeal_decided', null,
    jsonb_build_object('appeal_id', appeal.id, 'statement_id', statement.id));
  perform public.log_staff_action('appeal.decided', 'appeals', appeal.id::text, appeal.user_id, btrim(note_text),
    jsonb_build_object('status', 'open'),
    jsonb_build_object('status', outcome, 'statement', statement.reference,
      'same_decider', coalesce(is_same_decider, false)));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_decide_appeal"("target_appeal_id" "uuid", "outcome" "public"."appeal_status", "note_text" "text", "message_to_person" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_decide_appeal"("target_appeal_id" "uuid", "outcome" "public"."appeal_status", "note_text" "text", "message_to_person" "text") IS 'A moderator upholds or overturns an appeal; overturning undoes the decision; the person is told (S1-E10-07).';



CREATE OR REPLACE FUNCTION "public"."admin_decide_case"("target_case_id" "uuid", "chosen_action" "public"."moderation_action", "note_text" "text", "suspension_days" integer DEFAULT NULL::integer, "message_to_person" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
begin
  -- Step 1: may act, and may see this case.
  select * into target from public.cases where id = target_case_id for update;
  if target.id is null or not public.may_see_case(target.is_safeguarding) or not public.staff_may('moderation', 'act') then
    raise exception 'You can''t decide this case.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a note is required; a decided case stays decided; a public note goes on a story or a
  -- chapter only.
  if btrim(coalesce(note_text, '')) = '' then
    raise exception 'Write a note with the decision.' using errcode = 'check_violation';
  end if;
  if char_length(coalesce(message_to_person, '')) > 4000 then
    raise exception 'The message to the person is too long.' using errcode = 'check_violation';
  end if;
  if target.status <> 'open' then
    raise exception 'This case is already decided.' using errcode = 'check_violation';
  end if;
  if chosen_action = 'public_note' and target.item_type not in ('story', 'chapter') then
    raise exception 'A public note goes on a story or a chapter only.' using errcode = 'check_violation';
  end if;
  -- Step 3: "restrict" (QA-9) is for a story readers can still see, and not already restricted.
  if chosen_action = 'restrict' then
    perform public.require_story_restrictable_by_case(target);
  end if;
  -- Step 4: the shared steps, with the statement of reasons.
  perform public.decide_case(target, chosen_action, note_text, message_to_person, suspension_days, true);
  return true;
end;
$$;


