COMMENT ON FUNCTION "public"."admin_decide_case"("target_case_id" "uuid", "chosen_action" "public"."moderation_action", "note_text" "text", "suspension_days" integer, "message_to_person" "text") IS 'Moderators decide an open case; the action is carried out, the statement of reasons sent and the reporters told (S1-E10-03a, 06, 08, 04; restrict on a story from QA-9).';



CREATE OR REPLACE FUNCTION "public"."admin_decide_manual_age_check"("request_id" "uuid", "decision" "text", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.manual_age_checks;
  before_result public.age_check_result;
  after_result public.age_check_result;
  clean_reason text := btrim(coalesce(reason, ''));
begin
  -- Step 1: who may decide, and a decision with a reason (canvas 2.3).
  if not public.staff_may('users', 'act') then
    raise exception 'Only staff who handle accounts may decide manual age checks.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  if decision is null or decision not in ('passed_13', 'passed_18', 'refused') then
    raise exception 'Unknown decision.' using errcode = 'check_violation', hint = 'unknown_decision';
  end if;
  if char_length(clean_reason) not between 1 and 1000 then
    raise exception 'Write a reason (up to 1,000 characters).'
      using errcode = 'check_violation', hint = 'reason_needed';
  end if;
  -- Step 2: the request must still be open.
  select * into request from public.manual_age_checks
  where manual_age_checks.id = request_id and manual_age_checks.status = 'open'
  for update;
  if not found then
    raise exception 'This manual check is already decided.' using errcode = 'check_violation', hint = 'not_open';
  end if;
  -- Step 3: the decision on the request, and the result on the profile.
  update public.manual_age_checks
  set status = decision, decision_reason = clean_reason, decided_at = now()
  where manual_age_checks.id = request.id;
  select age_check_result into before_result from public.profiles where profiles.id = request.user_id;
  after_result := public.manual_decision_result(decision, before_result);
  if decision <> 'refused' then
    update public.profiles
    set age_check_result = after_result, age_checked_at = now(), age_check_method = 'manual'
    where profiles.id = request.user_id;
  end if;
  -- Step 4: the audit log and the person's notification.
  perform public.log_staff_action('manual_age_check.decided', 'manual_age_checks', request.id::text,
    request.user_id, clean_reason, jsonb_build_object('age_check_result', before_result),
    jsonb_build_object('age_check_result', after_result, 'decision', decision));
  perform public.notify(request.user_id, 'age_check_decided', null, '{}'::jsonb);
  return jsonb_build_object('outcome', 'ok', 'result', after_result);
end;
$$;


ALTER FUNCTION "public"."admin_decide_manual_age_check"("request_id" "uuid", "decision" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_decide_manual_age_check"("request_id" "uuid", "decision" "text", "reason" "text") IS 'Staff: decides one manual age check with a reason; logged and the person told (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."admin_decide_teacher_check"("check_id" "uuid", "decision" "text", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.teacher_checks;
  clean_reason text := btrim(coalesce(reason, ''));
begin
  -- Step 1: who may decide, and a known decision with a reason (board 8.9).
  perform public.require_teacher_checks_access();
  if decision is null or decision not in ('approved', 'rejected') then
    raise exception 'Unknown decision.' using errcode = 'check_violation', hint = 'unknown_decision';
  end if;
  if char_length(clean_reason) not between 1 and 1000 then
    raise exception 'Write a reason (up to 1,000 characters).' using errcode = 'check_violation', hint = 'reason_needed';
  end if;
  -- Step 2: the request must still wait, and its proof must already be deleted.
  select * into request from public.teacher_checks
  where teacher_checks.id = admin_decide_teacher_check.check_id and teacher_checks.status = 'waiting_for_staff'
  for update;
  if not found then
    raise exception 'This request is already decided.' using errcode = 'check_violation', hint = 'not_waiting';
  end if;
  if request.proof_path is not null and exists (
      select 1 from storage.objects
      where objects.bucket_id = 'teacher-proofs' and objects.name = request.proof_path) then
    raise exception 'Delete the proof first.' using errcode = 'check_violation', hint = 'proof_not_deleted';
  end if;
  -- Step 3: the decision, with only the way, the outcome and the date kept (criterion 6).
  update public.teacher_checks
  set status = decision, decision_reason = clean_reason, decided_at = now(), proof_path = null
  where teacher_checks.id = request.id;
  if decision = 'approved' then
    perform public.grant_teacher_badge(request.user_id);
  end if;
  -- Step 4: the audit log and the person's notification.
  perform public.log_staff_action('teacher_check.decided', 'teacher_checks', request.id::text,
    request.user_id, clean_reason, null,
    jsonb_build_object('decision', decision, 'way', request.way, 'school_domain', request.school_domain));
  perform public.notify(request.user_id, 'teacher_check_decided', null, '{}'::jsonb);
  return jsonb_build_object('outcome', 'ok');
end;
$$;


