COMMENT ON FUNCTION "public"."admin_due_decision_emails"() IS 'Staff: decided public notices still waiting for their decision email (S1-E10-04; DSA art. 16(5)).';



CREATE OR REPLACE FUNCTION "public"."admin_emergency_disable"("target_case_id" "uuid", "note_text" "text", "message_to_person" "text", "tell_uploader" boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
  decided public.cases;
begin
  -- Step 1: the on-call permission, and an open authority order.
  select * into target from public.cases where id = target_case_id for update;
  if target.id is null or not public.may_see_case(target.is_safeguarding) or not public.staff_may('removal_orders', 'act') then
    raise exception 'Only someone with the on-call permission can use Emergency disable.' using errcode = 'insufficient_privilege';
  end if;
  if target.source <> 'authority_order' or target.status <> 'open' then
    raise exception 'Emergency disable is for an open removal order.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(note_text, '')) = '' then
    raise exception 'Write a note with the decision.' using errcode = 'check_violation';
  end if;
  -- Step 2: acting on the order acknowledges its alert.
  update public.on_call_alerts set acknowledged_at = now(), acknowledged_by_user_id = (select auth.uid())
  where on_call_alerts.case_id = target.id and on_call_alerts.acknowledged_at is null;
  -- Step 3: removed everywhere, decided, preserved (mark_order_item_disabled()), told or not.
  perform public.decide_case(target, 'remove', note_text, message_to_person, null, coalesce(tell_uploader, true));
  -- Step 4: the proof, with every timestamp.
  select * into decided from public.cases where id = target.id;
  perform public.log_staff_action('removal_order.disabled', 'cases', target.id::text, target.user_id, btrim(note_text),
    null, public.order_timeline_json(decided));
  return decided.disabled_at;
end;
$$;


ALTER FUNCTION "public"."admin_emergency_disable"("target_case_id" "uuid", "note_text" "text", "message_to_person" "text", "tell_uploader" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_emergency_disable"("target_case_id" "uuid", "note_text" "text", "message_to_person" "text", "tell_uploader" boolean) IS 'On-call staff take an authority order''s item down everywhere in one action, preserved six months, logged (S1-E10-09; TCO).';



CREATE OR REPLACE FUNCTION "public"."admin_end_sponsor_campaign"("target_campaign_id" "uuid", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  campaign public.sponsor_campaigns;
begin
  perform public.require_sponsor_staff();
  if btrim(coalesce(reason, '')) = '' then
    raise exception 'Say why it ends.' using errcode = 'check_violation';
  end if;
  campaign := public.locked_sponsor_campaign(target_campaign_id,
    array['draft', 'in_review', 'approved', 'sent_back']::public.sponsor_campaign_state[]);
  update public.sponsor_campaigns set state = 'ended' where id = campaign.id;
  perform public.log_staff_action('sponsor_campaign.ended', 'sponsor_campaigns', campaign.id::text, null, btrim(reason),
    jsonb_build_object('state', campaign.state), jsonb_build_object('state', 'ended'));
end;
$$;


