CREATE OR REPLACE FUNCTION "public"."admin_extend_data_request"("target_request_id" "uuid", "extra_months" integer, "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
  wanted date;
begin
  -- Step 1: a reason the person can read.
  if btrim(coalesce(reason, '')) = '' or char_length(reason) > 1000 then
    raise exception 'Say why you need more time, in at most 1000 characters.'
      using errcode = 'check_violation', hint = 'reason_needed';
  end if;
  -- Step 2: one or two months from the first deadline, and more than any earlier extension.
  wanted := (request.due_on + make_interval(months => coalesce(extra_months, 0)))::date;
  if extra_months is null or extra_months not in (1, 2) or wanted <= coalesce(request.extended_to, request.due_on) then
    raise exception 'Pick one or two more months, more than before.' using errcode = 'check_violation', hint = 'bad_months';
  end if;
  -- Step 3: the person must be told within the first month (art. 12(3)).
  if public.romania_today() > request.due_on then
    raise exception 'The first month is over, so the deadline can''t be extended now.'
      using errcode = 'check_violation', hint = 'too_late';
  end if;
  -- Step 4: the extension, the audit log and the person's notice (always sent, by email too).
  update public.data_requests set extended_to = wanted, extension_reason = btrim(reason),
    extended_at = now(), handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id returning * into request;
  perform public.log_staff_action('data_request.extended', 'data_requests', request.id::text, request.user_id,
    btrim(reason), jsonb_build_object('deadline', request.due_on), jsonb_build_object('deadline', wanted));
  perform public.notify(request.user_id, 'data_request_extended', null,
    jsonb_build_object('data_request_id', request.id));
  return public.data_request_json(request);
end;
$$;


ALTER FUNCTION "public"."admin_extend_data_request"("target_request_id" "uuid", "extra_months" integer, "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_extend_data_request"("target_request_id" "uuid", "extra_months" integer, "reason" "text") IS 'Staff give a data request one or two more months, with a reason; the person is told (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_featured_candidates"("view" "text" DEFAULT 'all'::"text", "category_slug" "text" DEFAULT NULL::"text", "rating" "public"."story_rating" DEFAULT NULL::"public"."story_rating", "page_size" integer DEFAULT 200, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  promising_through double precision :=
    (public.setting_value('featured_promising_read_through'))::text::double precision;
  first_row integer := greatest(page_offset, 0);
  last_row integer := greatest(page_offset, 0) + least(greatest(page_size, 1), 500);
  answer jsonb;
begin
  -- Step 1: admins and the owner only, in a staff session.
  if not public.staff_may('featured', 'view') then
    raise exception 'Only admins can open Featured this week.' using errcode = 'insufficient_privilege';
  end if;
  if view not in ('all', 'rising', 'new_writers', 'promising') then
    raise exception 'Unknown view: %', view using errcode = 'invalid_parameter_value';
  end if;
  -- Step 2: the candidates once; the median of this week's reads across all of them; then the
  -- view and filters, numbered in the view's order (rising: biggest climb first; else by rank).
  with candidate_rows as materialized (
    select * from public.featured_candidate_rows()
  ),
  median as (
    select coalesce(percentile_cont(0.5) within group (order by candidate_rows.reads_7d), 0) as reads
    from candidate_rows
  ),
  chosen as (
    select candidate_rows.*,
      row_number() over (order by
        case when view = 'rising' then -coalesce(candidate_rows.rank_change, 0) end,
        candidate_rows.rank nulls last, candidate_rows.title) as sort_order,
      count(*) over () as matching_total
    from candidate_rows, median
    where (admin_featured_candidates.category_slug is null
           or candidate_rows.category_slug = admin_featured_candidates.category_slug)
      and (admin_featured_candidates.rating is null
           or candidate_rows.rating = admin_featured_candidates.rating)
      and (view <> 'rising' or coalesce(candidate_rows.rank_change, 0) > 0)
      and (view <> 'new_writers' or candidate_rows.is_new_writer)
      and (view <> 'promising'
           or (candidate_rows.read_through >= promising_through and candidate_rows.reads_7d < median.reads))
  )
  -- Step 3: one page, with the totals and the current picks so the screen can tick them.
  select jsonb_build_object(
    'total', coalesce((select max(chosen.matching_total) from chosen), 0),
    'median_reads_7d', (select median.reads from median),
    'featured_max', (public.setting_value('featured_max'))::text::integer,
    'picks', coalesce((select jsonb_agg(featured_picks.story_id order by featured_picks.position)
                       from public.featured_picks where featured_picks.removed_at is null), '[]'::jsonb),
    'stories', coalesce((select jsonb_agg(
        (to_jsonb(chosen) - 'story_id' - 'sort_order' - 'matching_total')
          || jsonb_build_object('id', chosen.story_id)
        order by chosen.sort_order)
      from chosen where chosen.sort_order > first_row and chosen.sort_order <= last_row), '[]'::jsonb))
  into answer;
  return answer;
end;
$$;


ALTER FUNCTION "public"."admin_featured_candidates"("view" "text", "category_slug" "text", "rating" "public"."story_rating", "page_size" integer, "page_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_featured_candidates"("view" "text", "category_slug" "text", "rating" "public"."story_rating", "page_size" integer, "page_offset" integer) IS 'Admins and the owner: every current active story with its rank, signals and whether it can be featured (S1-E5-10).';



CREATE OR REPLACE FUNCTION "public"."admin_find_accounts"("search_text" "text") RETURNS TABLE("user_id" "uuid", "handle" "text", "pen_name" "text", "email_masked" "text", "matched_by" "text", "staff_roles" "public"."staff_role"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  wanted text := btrim(coalesce(search_text, ''));
  is_email boolean := wanted ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$';
  found record;
begin
  -- Step 1: owner and admin only, in a staff session.
  if not public.staff_may('roles', 'act') then
    raise exception 'Only an owner or admin can look up accounts here.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: too short to search finds nothing (no listing every account by typing one letter).
  if char_length(btrim(wanted, ' @')) < 2 then
    return;
  end if;

  -- Step 3: the matches, an email match first, then usernames, then pen names.
  for found in
    select
      profiles.id,
      profiles.handle,
      profiles.pen_name,
      public.mask_email(users.email) as masked,
      case
        when is_email and lower(users.email) = lower(wanted) then 'email'
        when starts_with(profiles.handle_skeleton, public.username_skeleton(btrim(wanted, ' @'))) then 'username'
        else 'pen_name'
      end as matched,
      coalesce(
        (select array_agg(roles.role order by roles.role) from public.staff_roles as roles
         where roles.user_id = profiles.id),
        '{}'
      ) as roles
    from public.profiles
    join auth.users on users.id = profiles.id
    where profiles.deleted_at is null
      and (
        (is_email and lower(users.email) = lower(wanted))
        or (not is_email
            and starts_with(profiles.handle_skeleton, public.username_skeleton(btrim(wanted, ' @'))))
        or (not is_email and strpos(lower(profiles.pen_name), lower(wanted)) > 0)
      )
    order by (is_email and lower(users.email) = lower(wanted)) desc, profiles.handle nulls last
    limit 10
  loop
    -- Step 4: finding an account by its email is logged, naming the account, never the address.
    if found.matched = 'email' then
      perform public.log_staff_action('sensitive_read.account_found_by_email', 'profiles',
        found.id::text, found.id);
    end if;
    user_id := found.id;
    handle := found.handle;
    pen_name := found.pen_name;
    email_masked := found.masked;
    matched_by := found.matched;
    staff_roles := found.roles;
    return next;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."admin_find_accounts"("search_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_find_accounts"("search_text" "text") IS 'Owner and admin find accounts by username, pen name or whole email, email masked; an email match is logged (S1-E11-01b).';



CREATE OR REPLACE FUNCTION "public"."admin_finish_data_request_copy"("target_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_copy_target(target_request_id);
  sent_files jsonb;
  expires timestamptz := now() + interval '7 days';
begin
  -- Step 1: a copy being built, and every one of its files really there.
  if not exists (select 1 from public.exports
                 where exports.data_request_id = request.id and exports.state = 'building') then
    raise exception 'No copy is being built.' using errcode = 'check_violation', hint = 'not_found';
  end if;
  if exists (select 1 from public.exports
             where exports.data_request_id = request.id and exports.state = 'building'
               and not exists (select 1 from storage.objects
                               where objects.bucket_id = 'exports' and objects.name = exports.file_name)) then
    raise exception 'A file hasn''t arrived.' using errcode = 'check_violation', hint = 'no_file';
  end if;
  -- Step 2: an earlier copy for this request goes; its files go with the nightly sweep (S1-E13-04).
  delete from public.exports where exports.data_request_id = request.id and exports.state = 'ready';
  -- Step 3: ready for seven days, each size taken from storage, never from the browser.
  update public.exports
  set state = 'ready', ready_at = now(), expires_at = expires,
      file_size = (select (objects.metadata ->> 'size')::bigint from storage.objects
                   where objects.bucket_id = 'exports' and objects.name = exports.file_name)
  where exports.data_request_id = request.id and exports.state = 'building';
  -- Step 4: the log keeps which files were sent, never the files (criterion "a request is closed").
  select jsonb_agg(jsonb_build_object('name', exports.display_name, 'size', exports.file_size)
      order by exports.display_name)
    into sent_files from public.exports where exports.data_request_id = request.id;
  update public.data_requests
  set copies_sent = copies_sent || jsonb_build_array(jsonb_build_object(
        'sent_at', now(), 'expires_at', expires, 'files', sent_files)),
      handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id;
  perform public.log_staff_action('data_request.copy_sent', 'data_requests', request.id::text,
    request.user_id, null, null, jsonb_build_object('files', sent_files, 'expires_at', expires));
  -- Step 5: tell the person, unless the copy goes to their parent (part c3).
  if not request.goes_to_parent then
    perform public.notify(request.user_id, 'data_request_copy_ready', null,
      jsonb_build_object('data_request_id', request.id));
  end if;
  return public.admin_data_request(request.id);
end;
$$;


ALTER FUNCTION "public"."admin_finish_data_request_copy"("target_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_finish_data_request_copy"("target_request_id" "uuid") IS 'Staff mark a data request copy ready for seven days, log the files and tell the person (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_fix_classic_typo"("target_chapter_code" "text", "corrected_body" "text", "reason_given" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  live_chapter public.chapters;
  clean_body text;
begin
  perform public.require_classics_staff();
  -- Step 1: a live chapter of a classic, and a reason.
  select chapters.* into live_chapter from public.chapters
  join public.classic_works on classic_works.story_id = chapters.story_id
  where chapters.code = target_chapter_code and chapters.status = 'published' and chapters.deleted_at is null;
  if live_chapter.id is null then
    raise exception 'That isn''t a live classic chapter.' using errcode = 'no_data_found', hint = 'not_a_classic';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Write a reason first.' using errcode = 'check_violation', hint = 'reason_missing';
  end if;
  -- Step 2: the same rules as any chapter text, and only a small change.
  clean_body := public.check_chapter_text(coalesce(corrected_body, ''));
  if clean_body = live_chapter.published_body then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'no_change';
  end if;
  if not public.classic_fix_is_small(live_chapter.published_body, clean_body) then
    raise exception 'That is more than a typo fix.' using errcode = 'check_violation', hint = 'too_big';
  end if;
  -- Step 3: the corrected text goes live, and the version keeps it beside the earlier ones.
  update public.chapters set draft_body = clean_body, published_body = clean_body,
    word_count = public.count_words(clean_body), published_word_count = public.count_words(clean_body)
  where chapters.id = live_chapter.id;
  insert into public.chapter_revisions (chapter_id, user_id, created_by_user_id, reason, title, body)
  values (live_chapter.id, live_chapter.user_id, (select auth.uid()), 'edited', live_chapter.published_title, clean_body);
  -- Step 4: the audit log keeps the reason and the size of the change, not the text.
  perform public.log_staff_action('classics.typo_fixed', 'chapters', live_chapter.id::text, live_chapter.user_id,
    btrim(reason_given), jsonb_build_object('words', live_chapter.published_word_count),
    jsonb_build_object('words', public.count_words(clean_body)));
  return public.admin_classic_chapter(target_chapter_code);
end;
$$;


ALTER FUNCTION "public"."admin_fix_classic_typo"("target_chapter_code" "text", "corrected_body" "text", "reason_given" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_grant_role"("target_user_id" "uuid", "granted_role" "public"."staff_role", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_row_id uuid;
  domain text := public.staff_email_domain();
begin
  -- Step 1: who may do this, and to whom.
  perform public.require_role_change_allowed(target_user_id, reason_given);
  perform public.require_role_in_reach(granted_role);
  -- Step 2: once staff sign in through Google Workspace, only a Workspace account can be staff.
  if domain is not null and not public.has_workspace_account(target_user_id, domain) then
    -- The hint lets the Roles page name the problem (S1-E11-01b's one-reason-each rule).
    raise exception 'This account has not signed in with a Google Workspace account on the staff domain.'
      using errcode = 'check_violation', hint = 'no_workspace_account';
  end if;
  -- Step 3: grant it, once.
  insert into public.staff_roles (user_id, role, granted_by_user_id)
  values (target_user_id, granted_role, (select auth.uid()))
  on conflict (user_id, role) do nothing
  returning id into new_row_id;
  if new_row_id is null then
    return false;
  end if;
  -- Step 4: the audit log, in the same transaction.
  perform public.log_staff_action('staff.role_granted', 'staff_roles', new_row_id::text, target_user_id,
    reason_given, null, jsonb_build_object('role', granted_role));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_grant_role"("target_user_id" "uuid", "granted_role" "public"."staff_role", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_grant_role"("target_user_id" "uuid", "granted_role" "public"."staff_role", "reason_given" "text") IS 'Gives someone a staff role, within the caller''s reach, with a reason; once the staff domain is set, only to an account with a Google Workspace identity on it; logged (S1-E2-07a, S1-E2-07b).';



CREATE OR REPLACE FUNCTION "public"."admin_home_comment_candidates"() RETURNS TABLE("comment_id" "uuid", "handle" "text", "display_name" "text", "body" "text", "story_title" "text", "chapter_position" integer, "written_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('featured', 'view') then
    raise exception 'Only staff with the featured area can see these comments.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select comments.id, profiles.handle, public.display_name(profiles.handle, profiles.pen_name),
      btrim(comments.body), stories.title, chapters.position, comments.created_at
    from public.comments
    join public.profiles on profiles.id = comments.user_id
    join public.chapters on chapters.id = comments.chapter_id
    join public.stories on stories.id = chapters.story_id
    where comments.created_at > now() - interval '90 days'
      and comments.deleted_at is null
      and public.home_comment_can_show(comments.id)
      and not exists (select 1 from public.home_comment_picks as picks
                      where picks.comment_id = comments.id and picks.deleted_at is null)
    order by comments.created_at desc
    limit 40;
end;
$$;


ALTER FUNCTION "public"."admin_home_comment_candidates"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_home_comment_candidates"() IS 'Staff with the featured area: recent short public comments that could be shown on the home page (GAPS-13).';



CREATE OR REPLACE FUNCTION "public"."admin_home_comment_picks"() RETURNS TABLE("pick_id" "uuid", "handle" "text", "display_name" "text", "body" "text", "story_title" "text", "chapter_position" integer, "answer" "text", "can_show" boolean, "is_on_home_page" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shown_pick uuid;
begin
  if not public.staff_may('featured', 'view') then
    raise exception 'Only staff with the featured area can see these picks.' using errcode = 'insufficient_privilege';
  end if;
  -- The pick visitors see: the same choice as home_comment_card(), without the caller's blocks.
  select picks.id into shown_pick
  from public.home_comment_picks as picks
  where picks.deleted_at is null and picks.agreed_at is not null
    and public.home_comment_can_show(picks.comment_id)
  order by picks.agreed_at desc limit 1;
  return query
    select picks.id, profiles.handle, public.display_name(profiles.handle, profiles.pen_name),
      btrim(comments.body), stories.title, chapters.position,
      case when picks.agreed_at is not null then 'agreed'
           when picks.declined_at is not null then 'declined'
           else 'waiting' end,
      public.home_comment_can_show(comments.id),
      picks.id is not distinct from shown_pick
    from public.home_comment_picks as picks
    join public.comments on comments.id = picks.comment_id
    join public.profiles on profiles.id = comments.user_id
    join public.chapters on chapters.id = comments.chapter_id
    join public.stories on stories.id = chapters.story_id
    where picks.deleted_at is null
    order by picks.created_at desc;
end;
$$;


