CREATE OR REPLACE FUNCTION "public"."admin_import_classics"("list_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  list_row jsonb;
  line_number integer;
  added integer := 0;
  already_listed integer := 0;
  refused jsonb := '[]'::jsonb;
  failure_hint text;
begin
  perform public.require_classics_staff();
  -- The drafts belong to the classics account; without it nothing can be imported.
  perform public.classics_account_id();
  if jsonb_typeof(list_rows) is distinct from 'array' or jsonb_array_length(list_rows) > 500 then
    raise exception 'Import at most 500 rows at a time.' using errcode = 'check_violation', hint = 'too_many_rows';
  end if;
  -- Each row in its own sub-transaction, so one bad row doesn't stop the rest.
  for list_row, line_number in select rows.value, rows.position from jsonb_array_elements(list_rows)
    with ordinality as rows (value, position)
  loop
    begin
      if public.classic_import_row(list_row) = 'added' then
        added := added + 1;
      else
        already_listed := already_listed + 1;
      end if;
    exception when others then
      get stacked diagnostics failure_hint = pg_exception_hint;
      refused := refused || jsonb_build_object('line', line_number, 'title', coalesce(list_row ->> 'title', ''),
        'reason', coalesce(nullif(failure_hint, ''), 'row_invalid'));
    end;
  end loop;
  perform public.log_staff_action('classics.list_imported', 'classic_works', null, null, null, null,
    jsonb_build_object('added', added, 'already_listed', already_listed, 'refused', jsonb_array_length(refused)));
  return jsonb_build_object('added', added, 'already_listed', already_listed, 'refused', refused);
end;
$$;


ALTER FUNCTION "public"."admin_import_classics"("list_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_invite_home_comment"("target_comment" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reader_id uuid;
  saved public.home_comment_picks;
begin
  -- Step 1: staff with the featured area only (the server decides, architecture 1.8.1).
  if not public.staff_may('featured', 'act') then
    raise exception 'Only staff with the featured area can pick a home page comment.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the comment must be one the home page may show.
  if target_comment is null or not public.home_comment_can_show(target_comment) then
    raise exception 'This comment can''t be shown on the home page.' using errcode = 'check_violation';
  end if;
  select comments.user_id into reader_id from public.comments where comments.id = target_comment;
  -- Step 3: the pick, waiting for the reader's answer.
  insert into public.home_comment_picks (user_id, comment_id, picked_by_user_id)
  values (reader_id, target_comment, (select auth.uid()))
  returning * into saved;
  -- Step 4: tell the reader, with no actor (it comes from the team), and log it.
  perform public.notify(reader_id, 'home_comment_invited', null,
    jsonb_build_object('comment_id', target_comment));
  perform public.log_staff_action('home_comment.invited', 'home_comment_picks', saved.id::text, reader_id, null,
    null, jsonb_build_object('comment_id', target_comment));
  return saved.id;
end;
$$;


ALTER FUNCTION "public"."admin_invite_home_comment"("target_comment" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_invite_home_comment"("target_comment" "uuid") IS 'Staff with the featured area invite a reader to have one comment shown on the home page; the reader is told; logged (GAPS-13).';



CREATE OR REPLACE FUNCTION "public"."admin_invite_writer_spotlight"("target_handle" "text", "first_day" "date", "reason_ro" "text", "reason_en" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  writer public.profiles;
  saved public.writer_spotlights;
begin
  -- Step 1: staff with the contests area only (the server decides, architecture 1.8.1).
  if not public.staff_may('contests', 'act') then
    raise exception 'Only contest staff can pick the writer of the week.' using errcode = 'insufficient_privilege';
  end if;
  if first_day is null then
    raise exception 'A pick needs its first day.' using errcode = 'check_violation';
  end if;
  -- Step 2: the writer exists, can write and is an adult.
  select * into writer from public.profile_for_handle(btrim(coalesce(target_handle, '')));
  if writer.id is null or public.account_state(writer.id) <> 'active' then
    raise exception 'There is no active account with that username.' using errcode = 'check_violation';
  end if;
  if public.age_band_of(writer.id) <> '18_plus' then
    raise exception 'Only an adult can be writer of the week.' using errcode = 'check_violation';
  end if;
  -- Step 3: the pick, waiting for the writer's answer. The table's checks refuse bad lines.
  insert into public.writer_spotlights (user_id, starts_on, reason_ro, reason_en, updated_by_user_id)
  values (writer.id, first_day, btrim(reason_ro), btrim(reason_en), (select auth.uid()))
  returning * into saved;
  -- Step 4: the audit log, in the same transaction.
  perform public.log_staff_action('writer_spotlight.invited', 'writer_spotlights', saved.id::text, writer.id, null,
    null, jsonb_build_object('starts_on', saved.starts_on, 'reason_ro', saved.reason_ro, 'reason_en', saved.reason_en));
  return saved.id;
end;
$$;


ALTER FUNCTION "public"."admin_invite_writer_spotlight"("target_handle" "text", "first_day" "date", "reason_ro" "text", "reason_en" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_invite_writer_spotlight"("target_handle" "text", "first_day" "date", "reason_ro" "text", "reason_en" "text") IS 'Contest staff invite an adult writer to be writer of the week; shown only once the writer agrees; logged (GAPS-12e).';



CREATE OR REPLACE FUNCTION "public"."admin_issue_contest_certificates"("target_contest_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  contest public.contests;
  entry public.contest_entries;
  issued_count integer := 0;
begin
  -- Step 1: only the owner and admins, and only after the results are published.
  perform public.require_contest_staff();
  select * into contest from public.contests where contests.id = target_contest_id for update;
  if contest.id is null then
    raise exception 'There is no such contest.' using errcode = 'no_data_found', hint = 'no_contest';
  end if;
  if contest.results_published_at is null then
    raise exception 'Publish the results first.' using errcode = 'check_violation', hint = 'not_published';
  end if;
  -- Step 2: one certificate per valid entry; withdrawn and disqualified entries get none.
  for entry in
    select * from public.contest_entries
    where contest_entries.contest_id = contest.id and contest_entries.status = 'valid'
  loop
    if public.write_contest_certificate(contest, entry) is not null then
      issued_count := issued_count + 1;
      perform public.notify(entry.user_id, 'certificate_issued', null,
        jsonb_build_object('landing_page_id', contest.landing_page_id));
    end if;
  end loop;
  -- Step 3: the audit row.
  perform public.log_staff_action('contest.certificates_issued', 'contests', contest.id::text, null,
    null, null, jsonb_build_object('count', issued_count));
  return jsonb_build_object('issued', issued_count);
end;
$$;


ALTER FUNCTION "public"."admin_issue_contest_certificates"("target_contest_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_issue_contest_certificates"("target_contest_id" "uuid") IS 'Owner and admins: issue certificates to a contest''s valid entries once its results are out (S1-E11-15 criterion 9).';



