CREATE OR REPLACE FUNCTION "public"."admin_lift_sanction"("target_sanction_id" "uuid", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.sanctions;
begin
  if not public.staff_may('user_sanctions', 'act') then
    raise exception 'Only moderation staff can lift a sanction.' using errcode = 'insufficient_privilege';
  end if;
  select * into target from public.sanctions where id = target_sanction_id for update;
  if target.id is null or target.lifted_at is not null then
    raise exception 'There is no live sanction to lift.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Say why the sanction is lifted.' using errcode = 'check_violation';
  end if;
  update public.sanctions set lifted_at = now(), lifted_by_user_id = (select auth.uid()),
    lift_reason = btrim(reason_given)
  where id = target.id;
  if target.kind = 'ban' then
    update auth.users set banned_until = null where users.id = target.user_id;
    delete from public.banned_email_hashes where sanction_id = target.id;
  end if;
  perform public.log_staff_action(
    'sanction.lifted', 'sanctions', target.id::text, target.user_id, btrim(reason_given),
    jsonb_build_object('kind', target.kind, 'ends_at', target.ends_at), jsonb_build_object('lifted', true)
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_lift_sanction"("target_sanction_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_lift_sanction"("target_sanction_id" "uuid", "reason_given" "text") IS 'Ends a sanction early, with a reason; a lifted ban clears Supabase''s ban and the email hash (S1-E10-06).';



CREATE OR REPLACE FUNCTION "public"."admin_link_returning_user"("target_case_id" "uuid", "other_handle" "text", "reason_given" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases := public.case_for_links(target_case_id, true);
  other_id uuid;
  new_link_id uuid;
begin
  -- Step 1: a case about an account, another account that exists, and a reason.
  if target.item_type <> 'profile' then
    raise exception 'Only a case about an account can link accounts.' using errcode = 'check_violation', hint = 'not_a_profile_case';
  end if;
  select profiles.id into other_id from public.profiles
  where profiles.handle_skeleton = public.username_skeleton(btrim(coalesce(other_handle, ''), ' @'));
  if other_id is null then
    raise exception 'There is no account with that username.' using errcode = 'check_violation', hint = 'no_such_account';
  end if;
  if other_id = target.user_id then
    raise exception 'Choose another account.' using errcode = 'check_violation', hint = 'same_account';
  end if;
  if btrim(coalesce(reason_given, '')) = '' or char_length(reason_given) > 1000 then
    raise exception 'Say why.' using errcode = 'check_violation', hint = 'reason_missing';
  end if;
  if exists (select 1 from public.case_account_links where case_id = target.id
             and linked_user_id = other_id and removed_at is null) then
    raise exception 'These accounts are already linked in this case.' using errcode = 'check_violation', hint = 'already_linked';
  end if;
  -- Step 2: the link and its audit row, in one transaction.
  insert into public.case_account_links (case_id, user_id, linked_user_id, source, reason, linked_by_user_id)
  values (target.id, target.user_id, other_id, 'moderator', btrim(reason_given), (select auth.uid()))
  returning id into new_link_id;
  perform public.log_staff_action('moderation.returning_user_linked', 'case_account_links', new_link_id::text,
    target.user_id, btrim(reason_given), null,
    jsonb_build_object('case_id', target.id, 'linked_user_id', other_id));
  return new_link_id;
end;
$$;


ALTER FUNCTION "public"."admin_link_returning_user"("target_case_id" "uuid", "other_handle" "text", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_link_returning_user"("target_case_id" "uuid", "other_handle" "text", "reason_given" "text") IS 'Moderation staff: links another account to a case''s account as a possible returning user, with a reason, logged (part f2).';



CREATE OR REPLACE FUNCTION "public"."admin_list_calls"("since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval), "only_failures" boolean DEFAULT false, "kind" "text" DEFAULT NULL::"text", "name_contains" "text" DEFAULT NULL::"text", "person_handle" "text" DEFAULT NULL::"text", "before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "max_rows" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "called_at" timestamp with time zone, "user_id" "uuid", "handle" "text", "call_kind" "text", "call_name" "text", "http_method" "text", "outcome" "text", "status_code" integer, "error_code" "text", "duration_ms" integer, "route_path" "text", "app_version" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person_id uuid;
begin
  -- Step 1: owner and admin only, in a staff session.
  if not public.staff_may('call_log', 'view') then
    raise exception 'Only an owner or admin can read the call log.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: one person's calls: find the account and write the audit row.
  if nullif(btrim(person_handle), '') is not null then
    select profiles.id into person_id from public.profiles
    where lower(profiles.handle) = lower(btrim(ltrim(person_handle, '@')));
    if person_id is null then
      raise exception 'There is no account with that username.' using errcode = 'no_data_found';
    end if;
    perform public.log_staff_action('call_log.viewed_for_account', 'call_log', null, person_id,
      null, null, null);
  end if;
  -- Step 3: the page of rows.
  return query
    select calls.id, calls.called_at, calls.user_id, profiles.handle, calls.call_kind,
      calls.call_name, calls.http_method, calls.outcome, calls.status_code, calls.error_code,
      calls.duration_ms, calls.route_path, calls.app_version
    from public.call_log as calls
    left join public.profiles on profiles.id = calls.user_id
    where calls.called_at >= admin_list_calls.since
      and (admin_list_calls.before is null or calls.called_at < admin_list_calls.before)
      and (not coalesce(only_failures, false) or calls.outcome <> 'ok')
      and (admin_list_calls.kind is null or calls.call_kind = admin_list_calls.kind)
      and (nullif(btrim(name_contains), '') is null
           or calls.call_name ilike '%' || btrim(name_contains) || '%')
      and (person_id is null or calls.user_id = person_id)
    order by calls.called_at desc
    limit least(greatest(coalesce(max_rows, 100), 1), 500);
end;
$$;


ALTER FUNCTION "public"."admin_list_calls"("since" timestamp with time zone, "only_failures" boolean, "kind" "text", "name_contains" "text", "person_handle" "text", "before" timestamp with time zone, "max_rows" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_calls"("since" timestamp with time zone, "only_failures" boolean, "kind" "text", "name_contains" "text", "person_handle" "text", "before" timestamp with time zone, "max_rows" integer) IS 'One page of the call log, newest first, with filters, for owner and admin; one person''s calls are audited (LOGS-1).';



