CREATE OR REPLACE FUNCTION "public"."admin_list_client_errors"("since" timestamp with time zone DEFAULT ("now"() - '7 days'::interval), "max_rows" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "error_name" "text", "error_message" "text", "route_path" "text", "app_version" "text", "browser_family" "text", "created_at" timestamp with time zone)
