CREATE OR REPLACE FUNCTION "public"."admin_list_forums"() RETURNS TABLE("id" "uuid", "parent_id" "uuid", "level" smallint, "slug" "text", "position" integer, "is_pinned" boolean, "accent" "public"."forum_accent", "names" "jsonb", "missing_languages" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Only forum staff may see the list.
  perform public.require_forum_staff();
  -- Every live public forum, with its names per language and the interface languages it lacks.
  return query
  select forums.id, forums.parent_id, forums.level, forums.slug, forums.position, forums.is_pinned,
    forums.accent,
    coalesce((select jsonb_object_agg(forum_names.language_code,
        jsonb_build_object('name', forum_names.name, 'description', forum_names.description))
      from public.forum_names where forum_names.forum_id = forums.id), '{}'::jsonb),
    array(select languages.code from public.languages
      where languages.is_interface and not exists (
        select 1 from public.forum_names
        where forum_names.forum_id = forums.id and forum_names.language_code = languages.code)
      order by languages.code)
  from public.forums
  where forums.deleted_at is null and forums.space_id is null
  order by forums.level, forums.position, forums.slug;
end;
$$;


ALTER FUNCTION "public"."admin_list_forums"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_forums"() IS 'Every live forum with its names, for staff (FORUMS-1a).';



CREATE OR REPLACE FUNCTION "public"."admin_list_invites"() RETURNS TABLE("id" "uuid", "note" "text", "max_uses" integer, "use_count" integer, "expires_at" timestamp with time zone, "revoked_at" timestamp with time zone, "status" "text", "made_by_handle" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('invites', 'view') then
    raise exception 'Only an owner or admin can see invite links.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select
      invites.id,
      invites.note,
      invites.max_uses,
      invites.use_count,
      invites.expires_at,
      invites.revoked_at,
      case
        when invites.revoked_at is not null then 'revoked'
        when invites.use_count >= invites.max_uses then 'used_up'
        when invites.expires_at <= now() then 'expired'
        else 'active'
      end,
      maker.handle,
      invites.created_at
    from public.invites
    join public.profiles as maker on maker.id = invites.user_id
    where invites.purpose = 'platform'
    order by invites.created_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_list_invites"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_invites"() IS 'Every platform invite link with its status and maker, never who used it (owner and admin; S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."admin_list_staff"() RETURNS TABLE("user_id" "uuid", "handle" "text", "roles" "public"."staff_role"[], "permissions" "public"."staff_permission"[], "is_intern" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('roles', 'view') then
    raise exception 'Only an owner or admin can see the staff list.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select
      profiles.id,
      profiles.handle,
      array_agg(distinct staff_roles.role order by staff_roles.role),
      coalesce(
        (select array_agg(permissions.permission order by permissions.permission)
         from public.staff_permissions as permissions where permissions.user_id = profiles.id),
        '{}'),
      exists (select 1 from public.staff_interns where staff_interns.user_id = profiles.id)
    from public.staff_roles
    join public.profiles on profiles.id = staff_roles.user_id
    group by profiles.id, profiles.handle
    order by profiles.handle;
end;
$$;


ALTER FUNCTION "public"."admin_list_staff"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_staff"() IS 'Everyone with a staff role, their roles, permissions and intern marker, for owner and admin (S1-E2-07a, ADMIN-2e2a).';



CREATE OR REPLACE FUNCTION "public"."admin_list_tags"("which_tags" "text") RETURNS TABLE("tag_id" "uuid", "name" "text", "status" "public"."tag_status", "is_recommended" boolean, "story_count" bigint, "names" "jsonb", "missing_languages" "text"[], "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.require_tag_staff();
  return query
  with named as (
    select tags.id, tags.name, tags.status, tags.is_recommended, tags.created_at,
      (select count(*) from public.story_tags where story_tags.tag_id = tags.id) as story_count,
      coalesce((select jsonb_object_agg(tag_names.language_code, tag_names.name)
        from public.tag_names where tag_names.tag_id = tags.id), '{}'::jsonb) as names,
      array(select languages.code from public.languages
        where languages.is_interface and not exists (
          select 1 from public.tag_names
          where tag_names.tag_id = tags.id and tag_names.language_code = languages.code)
        order by languages.code) as missing_languages
    from public.tags
  )
  select named.id, named.name, named.status, named.is_recommended, named.story_count, named.names,
    named.missing_languages, named.created_at
  from named
  where case which_tags
      when 'waiting' then named.status = 'waiting'
      when 'missing' then named.status = 'approved' and cardinality(named.missing_languages) > 0
      when 'approved' then named.status = 'approved'
      else false
    end
  order by case when which_tags = 'waiting' then named.created_at end,
    named.name;
end;
$$;


ALTER FUNCTION "public"."admin_list_tags"("which_tags" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_list_tags"("which_tags" "text") IS 'The tags waiting for staff, missing a name, or approved, with story counts and names; moderation staff only (CMS-1e).';



CREATE OR REPLACE FUNCTION "public"."admin_lock_forum_thread"("thread_number" bigint, "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads := public.forum_thread_for_moderation(thread_number, reason);
begin
  update public.forum_threads
  set locked_at = now(), locked_by_user_id = (select auth.uid()), lock_reason = btrim(reason)
  where forum_threads.id = thread.id;
  perform public.log_thread_moderation(thread, 'locked', reason,
    jsonb_build_object('locked_at', thread.locked_at, 'lock_reason', thread.lock_reason),
    jsonb_build_object('locked_at', now(), 'lock_reason', btrim(reason)));
end;
$$;


ALTER FUNCTION "public"."admin_lock_forum_thread"("thread_number" bigint, "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_lock_forum_thread"("thread_number" bigint, "reason" "text") IS 'Locks a forum thread with a public reason; moderation staff; logged (S1-E8-05).';



CREATE OR REPLACE FUNCTION "public"."admin_log_compliance_entry"("kind" "public"."compliance_entry_kind", "authority" "text", "received" timestamp with time zone, "what_was_asked" "text", "action" "text" DEFAULT NULL::"text", "done_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  problem text := public.compliance_times_problem(received, done_at);
  saved public.compliance_log_entries;
begin
  perform public.require_compliance_staff();
  -- Step 1: the fields a record of proof needs, with plain reasons the form can show.
  if received is null or nullif(btrim(authority), '') is null or nullif(btrim(what_was_asked), '') is null then
    problem := 'empty';
  elsif char_length(btrim(authority)) > 200 or char_length(btrim(what_was_asked)) > 2000
        or char_length(coalesce(btrim(action), '')) > 2000 then
    problem := 'too_long';
  elsif (nullif(btrim(action), '') is null) <> (done_at is null) then
    problem := 'action_needs_time';
  end if;
  if problem is not null then
    raise exception 'This entry can''t be saved (%).', problem using errcode = 'check_violation', hint = problem;
  end if;
  -- Step 2: the entry, and its line in the audit log.
  insert into public.compliance_log_entries (user_id, entry_kind, authority, received_at, content,
    action_taken, completed_at, completed_by_user_id)
  values ((select auth.uid()), kind, btrim(authority), received, btrim(what_was_asked),
    nullif(btrim(action), ''), done_at, case when done_at is not null then (select auth.uid()) end)
  returning * into saved;
  perform public.log_staff_action('compliance_log.entry_logged', 'compliance_log_entries', saved.id::text,
    null, null, null, to_jsonb(saved) - 'user_id' - 'completed_by_user_id');
  return saved.reference;
end;
$$;


ALTER FUNCTION "public"."admin_log_compliance_entry"("kind" "public"."compliance_entry_kind", "authority" "text", "received" timestamp with time zone, "what_was_asked" "text", "action" "text", "done_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_log_compliance_entry"("kind" "public"."compliance_entry_kind", "authority" "text", "received" timestamp with time zone, "what_was_asked" "text", "action" "text", "done_at" timestamp with time zone) IS 'Logs an authority order, legal request or launch notice; owner and admin only; audited (S1-E11-04).';



CREATE OR REPLACE FUNCTION "public"."admin_log_referral"("target_case_id" "uuid", "authority_name" "text", "authority_reference" "text" DEFAULT NULL::"text", "note_text" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
  new_referral_id uuid;
begin
  select * into target from public.cases where id = target_case_id;
  if target.id is null or not public.may_see_case(target.is_safeguarding) or not public.staff_may('safeguarding', 'act') then
    raise exception 'Only safeguarding staff can log a referral.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(authority_name, '')) = '' then
    raise exception 'Name the authority.' using errcode = 'check_violation';
  end if;
  insert into public.safeguarding_referrals (case_id, user_id, authority_name, authority_reference, note)
  values (target.id, (select auth.uid()), btrim(authority_name), nullif(btrim(coalesce(authority_reference, '')), ''),
          nullif(btrim(coalesce(note_text, '')), ''))
  returning id into new_referral_id;
  perform public.log_staff_action('safeguarding.referred', 'safeguarding_referrals', new_referral_id::text, target.user_id,
    nullif(btrim(coalesce(note_text, '')), ''), null,
    jsonb_build_object('case_id', target.id, 'authority_name', btrim(authority_name), 'authority_reference', authority_reference));
  return new_referral_id;
end;
$$;


ALTER FUNCTION "public"."admin_log_referral"("target_case_id" "uuid", "authority_name" "text", "authority_reference" "text", "note_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_log_referral"("target_case_id" "uuid", "authority_name" "text", "authority_reference" "text", "note_text" "text") IS 'Safeguarding staff log a referral of a case to an authority; logged (S1-E10-10; DSA art. 18).';



CREATE OR REPLACE FUNCTION "public"."admin_manual_age_checks"() RETURNS TABLE("request_id" "uuid", "handle" "text", "birth_year" integer, "birth_month" integer, "age_band" "public"."age_band", "age_check_result" "public"."age_check_result", "requested_at" timestamp with time zone, "answer_by" "date", "attempts" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request record;
begin
  -- Step 1: owner, admin or moderator, in a staff session (architecture 1.8.3).
  if not public.staff_may('users', 'act') then
    raise exception 'Only staff who handle accounts may see manual age checks.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: each open request with what staff need to decide, nothing more.
  for request in
    select manual_age_checks.id, manual_age_checks.user_id, manual_age_checks.created_at,
      profiles.handle, profiles.birth_year, profiles.birth_month, profiles.age_check_result
    from public.manual_age_checks
    join public.profiles on profiles.id = manual_age_checks.user_id and profiles.deleted_at is null
    where manual_age_checks.status = 'open'
    order by manual_age_checks.created_at
  loop
    -- Seeing the year of birth is a sensitive read, logged per account.
    perform public.log_staff_action('sensitive_read.manual_age_check', 'manual_age_checks',
      request.id::text, request.user_id);
    request_id := request.id;
    handle := request.handle;
    birth_year := request.birth_year;
    birth_month := request.birth_month;
    age_band := public.age_band_from_birth(request.birth_year, request.birth_month, 'pending',
      (now() at time zone 'Europe/Bucharest')::date);
    age_check_result := request.age_check_result;
    requested_at := request.created_at;
    answer_by := public.working_days_after(request.created_at, 5);
    attempts := public.age_check_attempt_history(request.user_id);
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."admin_manual_age_checks"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_manual_age_checks"() IS 'Staff: the open manual age checks with the year of birth and attempt history; each read logged (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."admin_march_numbers"("days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  listed_days integer := least(greatest(coalesce(days, 30), 7), 90);
  counted_on date;
begin
  -- Step 1: owner and admins only (architecture 1.8.3).
  if not public.may_see_march_numbers() then
    raise exception 'Only the owner and admins can see the March test numbers.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: the latest day the job has counted.
  select max(metric_date) into counted_on from public.daily_metrics;
  -- Step 3: the numbers, the targets and the lists.
  return jsonb_build_object(
    'counted_on', counted_on,
    'writers', public.metric_on(counted_on, 'writers_published'),
    'readers', public.metric_on(counted_on, 'signed_up_readers'),
    'return_rate', public.metric_on(counted_on, 'return_rate'),
    'targets', jsonb_build_object(
      'writers', public.setting_value('march_target_writers'),
      'readers', public.setting_value('march_target_readers'),
      'return_rate', public.setting_value('march_target_return_rate')),
    'writers_by_market', coalesce((
      select jsonb_agg(jsonb_build_object('market', market, 'count', value) order by value desc, market)
      from public.daily_metrics
      where metric_date = counted_on and metric = 'writers_published' and market <> 'all'), '[]'::jsonb),
    'reads_per_day', coalesce((
      select jsonb_agg(jsonb_build_object('day', metric_date, 'reads', value) order by metric_date)
      from public.daily_metrics
      where metric = 'chapter_reads' and market = 'all'
        and metric_date > counted_on - listed_days), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."admin_march_numbers"("days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_march_numbers"("days" integer) IS 'The staff Metrics page: the March test numbers, totals only, for the owner and admins (S1-E15-02).';



CREATE OR REPLACE FUNCTION "public"."admin_mark_appeal_reviewed"("target_appeal_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  appeal public.appeals;
begin
  -- Step 1: an owner who decides appeals and may see this one.
  select * into appeal from public.appeals where id = target_appeal_id for update;
  if appeal.id is null or not public.staff_may('appeals', 'act') or not public.is_staff('owner')
     or not public.may_see_case(coalesce((select cases.is_safeguarding from public.cases
       join public.statements_of_reasons on statements_of_reasons.case_id = cases.id
       where statements_of_reasons.id = appeal.statement_id), false)) then
    raise exception 'Only an owner can review this appeal.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: only an appeal the original decider decided, reviewed once.
  if not appeal.decided_by_original_decider or appeal.owner_reviewed_at is not null then
    raise exception 'This appeal doesn''t need a review.' using errcode = 'check_violation';
  end if;
  -- Step 3: the review and its audit row, in the same transaction.
  update public.appeals set owner_reviewed_at = now(), owner_reviewed_by_user_id = (select auth.uid())
    where id = appeal.id;
  perform public.log_staff_action('appeal.owner_reviewed', 'appeals', appeal.id::text, appeal.user_id,
    null, jsonb_build_object('owner_reviewed', false), jsonb_build_object('owner_reviewed', true));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_mark_appeal_reviewed"("target_appeal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_mark_appeal_reviewed"("target_appeal_id" "uuid") IS 'The owner marks a same-moderator appeal decision as reviewed, logged (QA-7; DSA art. 20(6)).';



CREATE OR REPLACE FUNCTION "public"."admin_mark_contest_prize_sent"("target_entry_id" "uuid", "parent_consent_on_file" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  entry public.contest_entries;
  needs_parent boolean;
begin
  -- Step 1: owner or admin, a valid winner of a contest whose results are out, not sent yet.
  perform public.require_contest_staff();
  select * into entry from public.contest_entries where id = target_entry_id for update;
  if entry.id is null then
    raise exception 'There is no such entry.' using errcode = 'no_data_found', hint = 'no_entry';
  end if;
  if entry.status <> 'valid' or entry.award is distinct from 'winner' then
    raise exception 'Only a winner gets a prize.' using errcode = 'check_violation', hint = 'not_a_winner';
  end if;
  if not exists (select 1 from public.contests where contests.id = entry.contest_id and contests.results_published_at is not null) then
    raise exception 'Publish the results first.' using errcode = 'check_violation', hint = 'not_published';
  end if;
  if entry.prize_sent_at is not null then
    raise exception 'This prize is already marked as sent.' using errcode = 'check_violation', hint = 'already_sent';
  end if;
  -- Step 2: under 16, or not known, needs the parent's or guardian's consent on file (criterion 10).
  needs_parent := public.age_band_of(entry.user_id) not in ('16_to_17', '18_plus');
  if needs_parent and not coalesce(parent_consent_on_file, false) then
    raise exception 'Confirm the parent''s or guardian''s consent first.' using errcode = 'check_violation', hint = 'parent_consent_needed';
  end if;
  -- Step 3: the date and the confirmation, then the audit row.
  update public.contest_entries
  set prize_sent_at = now(), prize_parent_consent = needs_parent and coalesce(parent_consent_on_file, false)
  where id = entry.id;
  perform public.log_staff_action('contest.prize_sent', 'contests', entry.id::text, entry.user_id, null,
    null, jsonb_build_object('parent_consent_on_file', needs_parent and coalesce(parent_consent_on_file, false)));
end;
$$;


ALTER FUNCTION "public"."admin_mark_contest_prize_sent"("target_entry_id" "uuid", "parent_consent_on_file" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_mark_contest_prize_sent"("target_entry_id" "uuid", "parent_consent_on_file" boolean) IS 'Owner and admins: record that a winner''s prize was sent; under 16 needs the parent''s consent on file (S1-E11-15 criterion 10).';



CREATE OR REPLACE FUNCTION "public"."admin_mark_decision_emails_sent"("notice_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  marked integer;
begin
  if not public.staff_may('moderation', 'act') then
    raise exception 'Only moderation staff can send decision emails.' using errcode = 'insufficient_privilege';
  end if;
  update public.public_notices set decision_emailed_at = now()
  where public_notices.id = any(notice_ids) and public_notices.decided_at is not null
    and public_notices.decision_emailed_at is null;
  get diagnostics marked = row_count;
  return marked;
end;
$$;


