COMMENT ON FUNCTION "public"."admin_mark_decision_emails_sent"("notice_ids" "uuid"[]) IS 'Staff: marks public notices whose decision email was sent (S1-E10-04).';



CREATE OR REPLACE FUNCTION "public"."admin_mark_safeguarding"("target_case_id" "uuid", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
begin
  select * into target from public.cases where id = target_case_id for update;
  if target.id is null or not public.may_see_case(target.is_safeguarding) or not public.staff_may('moderation', 'act') then
    raise exception 'You can''t change this case.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Write a reason.' using errcode = 'check_violation';
  end if;
  if target.status <> 'open' or target.is_safeguarding then
    raise exception 'Only an open case outside the safeguarding lane can be moved into it.' using errcode = 'check_violation';
  end if;
  update public.cases set is_safeguarding = true where id = target.id;
  perform public.log_staff_action('case.safeguarding_marked', 'cases', target.id::text, target.user_id,
    btrim(reason_given), jsonb_build_object('is_safeguarding', false), jsonb_build_object('is_safeguarding', true));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_mark_safeguarding"("target_case_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_mark_safeguarding"("target_case_id" "uuid", "reason_given" "text") IS 'Moderation staff move an open case into the safeguarding lane; logged (S1-E10-10).';



CREATE OR REPLACE FUNCTION "public"."admin_mark_support_spam"("ticket_number" bigint, "spam" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ticket public.support_tickets := public.require_support_ticket_for_staff(ticket_number);
  marking boolean := coalesce(spam, true);
begin
  -- Step 1: nothing to do when it already says so.
  if ticket.is_spam = marking then
    return true;
  end if;
  -- Step 2: the mark, and the history line.
  update public.support_tickets
  set is_spam = marking, marked_spam_at = case when marking then now() else null end
  where id = ticket.id;
  perform public.record_support_event(ticket.id, case when marking then 'spam_marked' else 'spam_cleared' end, null, null);
  -- Step 3: a spammer gets nothing: emails still waiting are closed without sending.
  if marking then
    update public.support_ticket_emails set sent_at = now()
    where support_ticket_emails.ticket_id = ticket.id and sent_at is null;
  end if;
  perform public.log_staff_action(case when marking then 'support_ticket.spam_marked' else 'support_ticket.spam_cleared' end,
    'support_tickets', ticket.id::text, ticket.requester_user_id, null, null, null);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_mark_support_spam"("ticket_number" bigint, "spam" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_mark_support_spam"("ticket_number" bigint, "spam" boolean) IS 'Staff mark a support ticket as spam or not; logged (S1-E11-13 criterion 13).';



CREATE OR REPLACE FUNCTION "public"."admin_merge_support_tickets"("source_number" bigint, "target_number" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source public.support_tickets := public.require_support_ticket_for_staff(source_number);
  target public.support_tickets := public.require_support_ticket_for_staff(target_number);
begin
  -- Step 1: two open tickets from the same person (their account, or the same address).
  if source.id = target.id then
    raise exception 'A ticket can''t be merged into itself.' using errcode = 'check_violation';
  end if;
  if source.status = 'closed' or target.status = 'closed' or source.is_spam or target.is_spam then
    raise exception 'Closed and spam tickets can''t be merged.' using errcode = 'check_violation';
  end if;
  if not ((source.requester_user_id is not null and source.requester_user_id = target.requester_user_id)
          or lower(coalesce(source.requester_email, '-')) = lower(coalesce(target.requester_email, '+'))) then
    raise exception 'Only tickets from the same person can be merged.' using errcode = 'check_violation';
  end if;
  -- Step 2: the messages move; what the source was still going to email is cancelled.
  update public.support_ticket_messages set ticket_id = target.id where ticket_id = source.id;
  update public.support_ticket_emails set sent_at = now() where ticket_id = source.id and sent_at is null;
  -- Step 3: the ticket that stays gets the tags of both and the latest activity.
  update public.support_tickets
  set tags = (select coalesce(array_agg(distinct tag order by tag), '{}') from unnest(target.tags || source.tags) as tag),
      last_message_at = greatest(target.last_message_at, source.last_message_at)
  where id = target.id;
  -- Step 4: the merged ticket closes and points to the one that stays.
  update public.support_tickets
  set status = 'closed', closed_at = now(), merged_into_ticket_id = target.id
  where id = source.id;
  perform public.record_support_event(source.id, 'merged_into', null, to_jsonb(target.number::text));
  perform public.record_support_event(target.id, 'merged_from', null, to_jsonb(source.number::text));
  -- Step 5: the person is told the new number (criterion 9).
  insert into public.support_ticket_emails (ticket_id, kind) values (source.id, 'merged');
  perform public.log_staff_action('support_ticket.merged', 'support_tickets', source.id::text, source.requester_user_id, null,
    jsonb_build_object('number', source.number), jsonb_build_object('merged_into', target.number));
  return target.number;
end;
$$;


ALTER FUNCTION "public"."admin_merge_support_tickets"("source_number" bigint, "target_number" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_merge_support_tickets"("source_number" bigint, "target_number" bigint) IS 'Staff merge two support tickets from the same person; the person is told the new number (S1-E11-13 criterion 9).';



CREATE OR REPLACE FUNCTION "public"."admin_metrics_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  window_days integer := coalesce(public.setting_value('tier_numbers_days') #>> '{}', '30')::integer;
begin
  -- Step 1: owner and admins only, like the March numbers.
  if not public.may_see_march_numbers() then
    raise exception 'Only the owner and admins can see these numbers.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
