  return jsonb_build_object(
    'sign_ups_by_age', public.sign_ups_by_age_group(),
    'age_checks', public.age_check_numbers(),
    'cases_by_tier', public.cases_by_tier(window_days),
    'tier_window_days', window_days);
end;
$$;


