CREATE OR REPLACE FUNCTION "public"."admin_moderation_queue"("tier_filter" "public"."case_tier" DEFAULT NULL::"public"."case_tier", "status_filter" "public"."case_status" DEFAULT NULL::"public"."case_status", "under_18_filter" boolean DEFAULT NULL::boolean, "source_filter" "public"."case_source" DEFAULT NULL::"public"."case_source", "case_id" "uuid" DEFAULT NULL::"uuid", "reason_filter" "public"."report_reason" DEFAULT NULL::"public"."report_reason", "claimed_filter" "text" DEFAULT NULL::"text", "search_text" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."moderation_queue_row"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('moderation', 'view') then
    raise exception 'Only moderation staff can see the queue.' using errcode = 'insufficient_privilege';
  end if;
  if claimed_filter is not null and claimed_filter not in ('mine', 'anyone', 'nobody') then
    raise exception 'Unknown claimed filter "%".', claimed_filter using errcode = 'check_violation';
  end if;
  return query
    select
      cases.id, cases.reference, cases.source, cases.tier, cases.status, cases.item_type, cases.item_id,
      public.reportable_item_summary(cases.item_type, cases.item_id),
      reported.handle,
      public.age_band_from_birth(reported.birth_year::integer, reported.birth_month::integer, reported.age_check_result, current_date),
      cases.top_reason, cases.report_count, cases.reporter_under_18, cases.is_safeguarding,
      cases.received_at, cases.deadline_at, cases.decision, cases.decided_at, decider.handle,
      cases.user_id, claimer.handle, cases.claimed_at, cases.claimed_by_user_id = (select auth.uid())
    from public.cases
    join public.profiles as reported on reported.id = cases.user_id
    left join public.profiles as decider on decider.id = cases.decided_by_user_id
    left join public.profiles as claimer on claimer.id = cases.claimed_by_user_id
    where public.may_see_case(cases.is_safeguarding)
      and (admin_moderation_queue.case_id is null or cases.id = admin_moderation_queue.case_id)
      and (tier_filter is null or cases.tier = tier_filter)
      and (status_filter is null or cases.status = status_filter)
      and (under_18_filter is null or cases.reporter_under_18 = under_18_filter)
      and (source_filter is null or cases.source = source_filter)
      and public.case_matches_queue_filters(cases, reported.handle, reason_filter, claimed_filter, search_text)
    order by cases.status, cases.deadline_at, cases.decided_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_moderation_queue"("tier_filter" "public"."case_tier", "status_filter" "public"."case_status", "under_18_filter" boolean, "source_filter" "public"."case_source", "case_id" "uuid", "reason_filter" "public"."report_reason", "claimed_filter" "text", "search_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_moderation_queue"("tier_filter" "public"."case_tier", "status_filter" "public"."case_status", "under_18_filter" boolean, "source_filter" "public"."case_source", "case_id" "uuid", "reason_filter" "public"."report_reason", "claimed_filter" "text", "search_text" "text") IS 'The moderation queue, most urgent first, with who claimed each case and filters for reason, claim and search (S1-E10-03a, 06, 03b).';



CREATE OR REPLACE FUNCTION "public"."admin_moderator_mail_inbox"("status_filter" "text" DEFAULT NULL::"text", "assigned_filter" "text" DEFAULT NULL::"text") RETURNS TABLE("reference" "text", "subject" "text", "status" "text", "member_handle" "text", "assigned_handle" "text", "assigned_to_me" boolean, "message_count" integer, "last_message_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('moderation', 'view') then
    raise exception 'Only moderation staff can read moderator mail.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select threads.reference, threads.subject, threads.status, member.handle, assignee.handle,
      coalesce(threads.assigned_to_user_id = (select auth.uid()), false),
      (select count(*)::integer from public.moderator_mail_messages where moderator_mail_messages.thread_id = threads.id),
      threads.last_message_at
    from public.moderator_mail_threads as threads
    join public.profiles as member on member.id = threads.user_id
    left join public.profiles as assignee on assignee.id = threads.assigned_to_user_id
    where (status_filter is null or threads.status = status_filter)
      and (assigned_filter is null
           or (assigned_filter = 'mine' and threads.assigned_to_user_id = (select auth.uid()))
           or (assigned_filter = 'nobody' and threads.assigned_to_user_id is null))
    order by (threads.status = 'closed'), (threads.status = 'waiting'), threads.last_message_at;
end;
$$;


