COMMENT ON FUNCTION "public"."admin_moderator_mail_thread"("thread_reference" "text") IS 'One moderator mail thread for staff, with notes and authors (S1-E10-11).';



CREATE OR REPLACE FUNCTION "public"."admin_move_category"("category_slug" "text", "move_by" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  moving public.categories;
  neighbour public.categories;
  order_before jsonb;
begin
  perform public.require_settings_staff();
  if move_by not in (-1, 1) then
    raise exception 'A category moves one place at a time.' using errcode = 'check_violation';
  end if;
  -- Step 1: the category and the one it swaps places with.
  select * into moving from public.categories where slug = category_slug for update;
  if moving.id is null then
    raise exception 'There is no such category.' using errcode = 'no_data_found';
  end if;
  select * into neighbour from public.categories
  where (move_by = -1 and position < moving.position) or (move_by = 1 and position > moving.position)
  order by case when move_by = -1 then -position else position end
  limit 1
  for update;
  if neighbour.id is null then
    return moving.position;
  end if;
  -- Step 2: swap the two positions and log the whole order before and after.
  select jsonb_agg(slug order by position) into order_before from public.categories;
  update public.categories set position = neighbour.position where id = moving.id;
  update public.categories set position = moving.position where id = neighbour.id;
  perform public.log_staff_action('settings.category_moved', 'categories', moving.slug, null, null,
    jsonb_build_object('order', order_before),
    jsonb_build_object('order', (select jsonb_agg(slug order by position) from public.categories)));
  return neighbour.position;
end;
$$;


ALTER FUNCTION "public"."admin_move_category"("category_slug" "text", "move_by" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_move_category"("category_slug" "text", "move_by" integer) IS 'Moves a category one place up or down; owner and admin only; logged (S1-E11-03).';



CREATE OR REPLACE FUNCTION "public"."admin_name_tag"("tag_id" "uuid", "names" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_tag public.tags;
  before_names jsonb;
  merged_names jsonb;
  problems text[];
  given record;
begin
  perform public.require_tag_staff();
  -- Step 1: the tag, which must be waiting or approved.
  select * into before_tag from public.tags where tags.id = admin_name_tag.tag_id for update;
  if before_tag.id is null or before_tag.status = 'rejected' then
    raise exception 'There is no tag to name with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 2: the names it has now, with the given ones on top; refuse anything to fix.
  before_names := coalesce((select jsonb_object_agg(tag_names.language_code, tag_names.name)
    from public.tag_names where tag_names.tag_id = before_tag.id), '{}'::jsonb);
  merged_names := before_names || coalesce(names, '{}'::jsonb);
  problems := public.tag_name_problems(before_tag.id, merged_names);
  if cardinality(problems) > 0 then
    raise exception 'Fix the tag''s names before saving.' using errcode = 'check_violation', hint = array_to_string(problems, ',');
  end if;
  -- Step 3: write each name, then approve the tag.
  for given in select * from jsonb_each_text(coalesce(names, '{}'::jsonb)) loop
    insert into public.tag_names (tag_id, language_code, name, normalised_name, named_by_user_id)
    values (before_tag.id, given.key, regexp_replace(btrim(given.value), '\s+', ' ', 'g'),
      public.normalise_tag(given.value), (select auth.uid()))
    on conflict on constraint tag_names_one_per_language do update
      set name = excluded.name, normalised_name = excluded.normalised_name,
          named_by_user_id = excluded.named_by_user_id;
  end loop;
  update public.tags
  set status = 'approved', decided_by_user_id = (select auth.uid()), decided_at = now(), decision_reason = null
  where tags.id = before_tag.id;
  -- Step 4: the audit log.
  perform public.log_staff_action(
    case when before_tag.status = 'waiting' then 'tag.approved' else 'tag.named' end,
    'tags', before_tag.id::text, null, null,
    jsonb_build_object('name', before_tag.name, 'status', before_tag.status, 'names', before_names),
    jsonb_build_object('name', before_tag.name, 'status', 'approved', 'names', merged_names));
end;
$$;


ALTER FUNCTION "public"."admin_name_tag"("tag_id" "uuid", "names" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_name_tag"("tag_id" "uuid", "names" "jsonb") IS 'Approves or renames a tag with a name in every interface language; moderation staff; logged (CMS-1e).';



CREATE OR REPLACE FUNCTION "public"."admin_on_call_alerts"() RETURNS TABLE("alert_id" "uuid", "kind" "text", "case_id" "uuid", "case_reference" "text", "notice_reference" "text", "created_at" timestamp with time zone, "on_call_handle" "text", "acknowledged_at" timestamp with time zone, "escalated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('moderation', 'view') then
    raise exception 'Only moderation staff see on-call alerts.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select on_call_alerts.id, on_call_alerts.kind, on_call_alerts.case_id, cases.reference,
           public_notices.reference, on_call_alerts.created_at, on_call.handle,
           on_call_alerts.acknowledged_at, on_call_alerts.escalated_at
    from public.on_call_alerts
    left join public.cases on cases.id = on_call_alerts.case_id
    left join public.public_notices on public_notices.id = on_call_alerts.notice_id
    left join public.profiles as on_call on on_call.id = on_call_alerts.on_call_user_id
    order by on_call_alerts.created_at desc
    limit 20;
end;
$$;


