COMMENT ON FUNCTION "public"."admin_on_call_rota"() IS 'Staff: the on-call rota, its gaps in the next 14 days and who may take a shift (S1-E10-09).';



CREATE OR REPLACE FUNCTION "public"."admin_open_contest"("target_contest_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.contests;
  problems text[];
begin
  perform public.require_contest_staff();
  select * into target from public.contests where id = target_contest_id for update;
  if target.id is null then
    raise exception 'That contest doesn''t exist.' using errcode = 'no_data_found';
  end if;
  if target.opened_at is not null then
    raise exception 'That contest is already open.' using errcode = 'check_violation', hint = 'already_open';
  end if;
  -- Opening is refused until the rules are published in both languages and linked (criterion 2).
  problems := public.contest_problems(target);
  if cardinality(problems) > 0 then
    raise exception 'The contest isn''t ready to open.'
      using errcode = 'check_violation', hint = 'not_ready', detail = array_to_string(problems, ',');
  end if;
  update public.contests set opened_at = now() where id = target_contest_id;
  perform public.log_staff_action('contest.opened', 'contests', target_contest_id::text, null, null, null,
    jsonb_build_object('entries_open_on', target.entries_open_on, 'entries_close_on', target.entries_close_on));
end;
$$;


ALTER FUNCTION "public"."admin_open_contest"("target_contest_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_open_contest"("target_contest_id" "uuid") IS 'Opens a complete contest for entries; owner and admin only; logged (S1-E11-15 criterion 2).';



CREATE OR REPLACE FUNCTION "public"."admin_open_data_request"("target_user_id" "uuid", "request_type" "public"."data_request_type", "channel" "public"."data_request_channel", "received_on" "date", "note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests;
begin
  -- Step 1: who may log one.
  if not public.staff_may('data_requests', 'act') then
    raise exception 'Only owner, admin and support staff handle data requests.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: an account that exists, a date that has happened and a note that fits.
  if not exists (select 1 from public.profiles where profiles.id = target_user_id) then
    raise exception 'There is no such account.' using errcode = 'check_violation', hint = 'no_such_person';
  end if;
  if received_on is null or received_on > public.romania_today() then
    raise exception 'The date received can''t be in the future.' using errcode = 'check_violation', hint = 'bad_date';
  end if;
  if char_length(coalesce(note, '')) > 2000 then
    raise exception 'The note is too long.' using errcode = 'check_violation', hint = 'note_too_long';
  end if;
  -- Step 3: the request, with its deadline one month from receipt (GDPR art. 12(3)).
  insert into public.data_requests (user_id, request_type, channel, received_on, due_on, identity,
    note, created_by_user_id, handled_by_user_id)
  values (target_user_id, request_type, channel, received_on, (received_on + interval '1 month')::date,
    case when channel = 'in_app' then 'not_needed' else 'not_asked' end::public.data_request_identity,
    btrim(coalesce(note, '')), (select auth.uid()), (select auth.uid()))
  returning * into request;
  -- Step 4: the audit log, naming the person by user ID (never the email used to find them).
  perform public.log_staff_action('data_request.opened', 'data_requests', request.id::text, request.user_id,
    null, null, jsonb_build_object('reference', request.reference, 'type', request.request_type,
      'channel', request.channel, 'received_on', request.received_on));
  return public.data_request_json(request);
end;
$$;


ALTER FUNCTION "public"."admin_open_data_request"("target_user_id" "uuid", "request_type" "public"."data_request_type", "channel" "public"."data_request_channel", "received_on" "date", "note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_open_data_request"("target_user_id" "uuid", "request_type" "public"."data_request_type", "channel" "public"."data_request_channel", "received_on" "date", "note" "text") IS 'Staff log a new data request; the deadline is one month from receipt (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_open_data_request_copy"("target_request_id" "uuid", "files" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  request public.data_requests := public.admin_data_request_copy_target(target_request_id);
  names text[];
  opened jsonb;
begin
  -- Step 1: the names, checked: a list of 1 to 500 unique names of the allowed kinds.
  if jsonb_typeof(files) <> 'array' then
    raise exception 'Send the list of files.' using errcode = 'check_violation', hint = 'bad_files';
  end if;
  select array_agg(file ->> 'display_name') into names from jsonb_array_elements(files) as file;
  if coalesce(array_length(names, 1), 0) not between 1 and 500
     or (select count(distinct name) from unnest(names) as name) <> array_length(names, 1)
     or exists (select 1 from unnest(names) as name
                where name is null or name !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,150}\.(zip|docx|pdf|json|csv)$') then
    raise exception 'The list of files isn''t right.' using errcode = 'check_violation', hint = 'bad_files';
  end if;
  -- Step 2: an unfinished copy for this request goes; nobody could read its files.
  delete from public.exports
  where exports.data_request_id = request.id and exports.state = 'building';
  -- Step 3: one export per file, owned by the person, under a random name with the same ending.
  with inserted as (
    insert into public.exports (user_id, kind, data_request_id, display_name, file_name)
    select request.user_id, 'data_request', request.id, name,
      gen_random_uuid()::text || '.' || substring(name from '\.([a-z]+)$')
    from unnest(names) as name
    returning exports.id, exports.file_name, exports.display_name
  )
  select jsonb_agg(jsonb_build_object('export_id', inserted.id, 'file_name', inserted.file_name,
      'display_name', inserted.display_name) order by inserted.display_name)
    into opened from inserted;
  return opened;
end;
$_$;


ALTER FUNCTION "public"."admin_open_data_request_copy"("target_request_id" "uuid", "files" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_open_data_request_copy"("target_request_id" "uuid", "files" "jsonb") IS 'Staff open the files of a data request copy (Word, PDF, JSON, CSV or a ZIP), under random names, before uploading them (S1-E11-09, ADMIN-2d).';



CREATE OR REPLACE FUNCTION "public"."admin_open_data_request_file"("target_request_id" "uuid", "target_export_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, false);
  chosen public.exports;
begin
  select * into chosen from public.exports
  where exports.id = target_export_id and exports.data_request_id = request.id
    and exports.state = 'ready' and exports.expires_at > now();
  if chosen.id is null then
    raise exception 'That file isn''t there any more.' using errcode = 'check_violation', hint = 'not_found';
  end if;
  perform public.log_staff_action('data_request.file_opened', 'exports', chosen.id::text,
    request.user_id, null, null,
    jsonb_build_object('data_request_id', request.id, 'file', chosen.display_name));
  return chosen.file_name;
end;
$$;


ALTER FUNCTION "public"."admin_open_data_request_file"("target_request_id" "uuid", "target_export_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_open_data_request_file"("target_request_id" "uuid", "target_export_id" "uuid") IS 'Staff open a data request file, logged first (S1-E11-09).';



