CREATE OR REPLACE FUNCTION "public"."admin_passage_case"("case_reference" "text") RETURNS "public"."cases"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  case_row public.cases;
begin
  if btrim(coalesce(case_reference, '')) = '' then
    return case_row;
  end if;
  select * into case_row from public.cases
  where cases.reference = upper(btrim(case_reference)) and public.may_see_case(cases.is_safeguarding);
  if not found then
    raise exception 'There is no such case.' using errcode = 'check_violation', hint = 'no_such_case';
  end if;
  return case_row;
end;
$$;


ALTER FUNCTION "public"."admin_passage_case"("case_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_passage_case"("case_reference" "text") IS 'Internal: the case named for a passage removal, if the caller may see it (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_passage_place"("full_text" "text", "passage" "text", "occurrence" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  searched_from integer := 1;
  found_at integer;
  copies_seen integer := 0;
begin
  loop
    -- Step 1: the next copy after the last one found.
    found_at := strpos(substr(full_text, searched_from), passage);
    if found_at = 0 then
      return null;
    end if;
    found_at := searched_from + found_at - 1;
    -- Step 2: the one staff selected, or move one character on and look again.
    if copies_seen = occurrence then
      return found_at;
    end if;
    copies_seen := copies_seen + 1;
    searched_from := found_at + 1;
  end loop;
end;
$$;


ALTER FUNCTION "public"."admin_passage_place"("full_text" "text", "passage" "text", "occurrence" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_passage_place"("full_text" "text", "passage" "text", "occurrence" integer) IS 'Internal: where the nth copy of a passage starts, in characters from 1 (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_pause_reporting"("reporter_handle" "text", "source_case_id" "uuid" DEFAULT NULL::"uuid", "note_text" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reporter_id uuid;
begin
  select id into reporter_id from public.profiles
    where profiles.handle = reporter_handle and profiles.deleted_at is null;
  if reporter_id is null then
    raise exception 'No account has the username %.', reporter_handle using errcode = 'check_violation';
  end if;
  return public.admin_apply_sanction(reporter_id, 'reporting_pause', null, source_case_id, note_text);
end;
$$;


