CREATE OR REPLACE FUNCTION "public"."admin_pictures_to_check"() RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  waiting jsonb[];
begin
  -- Step 1: only picture reviewers.
  perform public.require_picture_reviewer();
  -- Step 2: the waiting pictures, oldest first.
  select array_agg(jsonb_build_object(
      'caseId', cases.id, 'pictureId', picture.id, 'kind', picture.kind, 'bucket', picture.bucket,
      'path', picture.path, 'uploaderHandle', uploader.handle,
      'uploaderAgeBand', public.age_band_of(picture.user_id), 'uploaderLocale', uploader.locale,
      'story', case when story.id is null then null else jsonb_build_object(
        'id', story.id, 'title', story.title, 'slug', story.slug, 'rating', story.rating) end,
      'ownerAgeBand', case when story.id is null then null else public.age_band_of(story.user_id) end,
      'waitingSince', cases.created_at, 'source', cases.source) order by cases.created_at)
  into waiting
  from public.cases
  join public.picture_checks as picture on picture.id = cases.item_id
  join public.profiles as uploader on uploader.id = picture.user_id
  left join public.stories as story on story.id = picture.story_id
  where cases.item_type = 'picture' and cases.status = 'open' and not cases.is_safeguarding
    and cases.source in ('picture_review', 'picture_check') and picture.status = 'held';
  -- Step 3: each file handed out is an opening (brief section 5).
  perform public.record_picture_opened((entry ->> 'pictureId')::uuid, 'pictures_to_check')
  from unnest(coalesce(waiting, '{}')) as entry;
  return query select unnest(coalesce(waiting, '{}'));
end;
$$;


ALTER FUNCTION "public"."admin_pictures_to_check"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_pictures_to_check"() IS 'Staff: the pictures waiting for a picture reviewer, oldest first, each opening logged (ADMIN-2e1b, ADMIN-2e2a).';



CREATE OR REPLACE FUNCTION "public"."admin_publish_classic"("target_story_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  work jsonb;
  chapter public.chapters;
begin
  perform public.require_classics_staff();
  work := public.classic_work_json(target_story_id);
  if work is null then
    raise exception 'That isn''t a classic.' using errcode = 'no_data_found', hint = 'not_a_classic';
  end if;
  -- Step 1: free in Romania today, or it stays a draft (Law 8/1996 art. 28(1)).
  if not (work -> 'free_markets' ->> 'RO')::boolean then
    raise exception 'This work isn''t in the public domain in Romania yet.'
      using errcode = 'check_violation', hint = 'not_free_in_romania';
  end if;
  -- Step 2: a work from a research list is checked by a person before it goes live (16b).
  if not (work ->> 'details_checked')::boolean then
    raise exception 'Check and save the details first.' using errcode = 'check_violation', hint = 'details_unchecked';
  end if;
  if jsonb_array_length(work -> 'chapters') = 0 then
    raise exception 'Add the text first.' using errcode = 'check_violation', hint = 'no_chapters';
  end if;
  -- Step 3: every chapter that isn't live goes live, in order.
  for chapter in select * from public.chapters
    where chapters.story_id = target_story_id and chapters.deleted_at is null and chapters.status <> 'published'
    order by chapters.position
  loop
    perform public.chapter_publish_now(chapter);
  end loop;
  perform public.log_staff_action('classics.published', 'stories', target_story_id::text,
    public.classics_account_id(), null, null, null);
  return public.classic_work_json(target_story_id);
end;
$$;


ALTER FUNCTION "public"."admin_publish_classic"("target_story_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_publish_cms_version"("version_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  draft public.cms_versions;
  problems text[];
  goes_live date;
begin
  perform public.require_website_staff();
  -- Step 1: the draft, locked so it is published once.
  select * into draft from public.cms_versions where id = version_id and status = 'draft' for update;
  if draft.id is null then
    raise exception 'There is no draft with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 2: refuse while a field is empty, too long or links nowhere, or while a notice would come
  -- down before it goes up (a "show until" date on or before the day it goes live).
  goes_live := greatest(coalesce(draft.show_from, public.romania_today()), public.romania_today());
  problems := public.cms_content_problems(draft);
  if draft.show_until is not null and draft.show_until <= goes_live then
    problems := problems || 'showUntil:before_show_from'::text;
  end if;
  if cardinality(problems) > 0 then
    raise exception 'Fix these fields before publishing.' using errcode = 'check_violation', hint = array_to_string(problems, ',');
  end if;
  -- Step 3: publish, logging what showed before and what will show.
  perform public.log_staff_action('website.published', 'cms_versions', draft.id::text, null, null,
    jsonb_build_object('content', public.cms_live_content_of(draft)),
    jsonb_build_object('kind', draft.content_kind, 'entry', draft.entry_key, 'market', draft.market_code,
      'language', draft.language_code, 'show_from', goes_live, 'show_until', draft.show_until, 'content', draft.content));
  update public.cms_versions
  set status = 'published', show_from = goes_live, published_at = now(), user_id = (select auth.uid())
  where id = draft.id;
  return goes_live;
end;
$$;


ALTER FUNCTION "public"."admin_publish_cms_version"("version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_publish_cms_version"("version_id" "uuid") IS 'Publishes a website content draft from its show-from date; owner and admin only; logged (S1-E11-06).';



CREATE OR REPLACE FUNCTION "public"."admin_publish_contest_results"("target_contest_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.contests;
begin
  -- Step 1: owner or admin, a closed contest, not published yet.
  perform public.require_contest_staff();
  select * into target from public.contests where id = target_contest_id for update;
  if target.id is null then
    raise exception 'There is no such contest.' using errcode = 'no_data_found', hint = 'no_contest';
  end if;
  if not public.contest_entries_have_closed(target) then
    raise exception 'Publish results once entries close.' using errcode = 'check_violation', hint = 'entries_open';
  end if;
  if target.results_published_at is not null then
    raise exception 'The results are already published.' using errcode = 'check_violation', hint = 'already_published';
  end if;
  -- Step 2: at least one winner, or there is nothing to announce.
  if not exists (select 1 from public.contest_entries as entries
                 where entries.contest_id = target.id and entries.status = 'valid' and entries.award = 'winner') then
    raise exception 'Choose at least one winner first.' using errcode = 'check_violation', hint = 'no_winner';
  end if;
  -- Step 3: publish, then the audit row.
  update public.contests set results_published_at = now() where id = target.id;
  perform public.log_staff_action('contest.results_published', 'contests', target.id::text, null, null,
    null, jsonb_build_object('results_published', true));
end;
$$;


ALTER FUNCTION "public"."admin_publish_contest_results"("target_contest_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_publish_contest_results"("target_contest_id" "uuid") IS 'Owner and admins: publish a closed contest''s winners and finalists on its landing page (S1-E11-15 criterion 8).';



CREATE OR REPLACE FUNCTION "public"."admin_publish_interface_text"("version_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  draft public.interface_text_overrides;
  goes_live date;
begin
  perform public.require_website_staff();
  -- Step 1: the draft, locked so it is published once.
  select * into draft from public.interface_text_overrides where id = version_id and status = 'draft' for update;
  if draft.id is null then
    raise exception 'There is no draft with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 2: publish, logging what showed before (null: the file text) and what will show.
  goes_live := greatest(coalesce(draft.show_from, public.romania_today()), public.romania_today());
  perform public.log_staff_action('interface_text.published', 'interface_text_overrides', draft.id::text, null, null,
    jsonb_build_object('text', public.interface_text_live_text(draft.text_key, draft.locale)),
    jsonb_build_object('key', draft.text_key, 'locale', draft.locale, 'show_from', goes_live, 'text', draft.text));
  update public.interface_text_overrides
  set status = 'published', show_from = goes_live, published_at = clock_timestamp(), user_id = (select auth.uid())
  where id = draft.id;
  return goes_live;
end;
$$;


