COMMENT ON FUNCTION "public"."admin_publish_landing_page"("version_id" "uuid") IS 'Publishes a landing page draft from its show-from date; owner and admin only; logged (S1-E11-14).';



CREATE TABLE IF NOT EXISTS "public"."story_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "story_id" "uuid" NOT NULL,
    "chapter_id" "uuid",
    "changed_by_user_id" "uuid" NOT NULL,
    "change_kind" "text" NOT NULL,
    "reason_code" "text" NOT NULL,
    "reason_text" "text" NOT NULL,
    "before_values" "jsonb" NOT NULL,
    "after_values" "jsonb" NOT NULL,
    "audit_log_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "restores_revision_id" "uuid",
    CONSTRAINT "story_revisions_change_kind_is_known" CHECK (("change_kind" = ANY (ARRAY['settings'::"text", 'visibility'::"text", 'chapter_visibility'::"text", 'passage'::"text", 'presentation'::"text"]))),
    CONSTRAINT "story_revisions_reason_code_is_known" CHECK (("reason_code" = ANY (ARRAY['rating_rules'::"text", 'story_details'::"text", 'community_rules'::"text", 'illegal_content'::"text", 'personal_data'::"text", 'copyright'::"text", 'writer_asked'::"text", 'other'::"text"]))),
    CONSTRAINT "story_revisions_reason_text_is_written" CHECK ((("btrim"("reason_text") <> ''::"text") AND ("char_length"("reason_text") <= 1000)))
);


ALTER TABLE "public"."story_revisions" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_revisions" IS 'kind: staff
Every staff change to a story''s settings or visibility: who, when, the reason and the before and after (S1-E11-08 criterion "a new version is stored"). Written only by the admin_* change functions.';



COMMENT ON COLUMN "public"."story_revisions"."restores_revision_id" IS 'For a version made by Restore: the earlier change it undid (S1-E11-08 criterion "Restore").';



CREATE OR REPLACE FUNCTION "public"."admin_put_back_passage"("story_row" "public"."stories", "removal" "public"."story_revisions", "reason_code" "text", "reason_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  passage_row public.removed_passages;
  chapter_row public.chapters;
begin
  -- Step 1: the original, while it hasn't been put back already.
  select * into passage_row from public.removed_passages
  where removed_passages.story_revision_id = removal.id;
  if not found or passage_row.put_back_at is not null then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'nothing_changed';
  end if;
  -- Step 2: the marker must still be where the cut left it.
  select * into chapter_row from public.chapters
  where chapters.id = passage_row.chapter_id and chapters.deleted_at is null;
  if substr(coalesce(chapter_row.published_body, ''), passage_row.marker_starts_at,
            char_length(passage_row.marker)) is distinct from passage_row.marker then
    raise exception 'The writer has changed this chapter since; the words can''t go back by themselves.'
      using errcode = 'check_violation', hint = 'text_changed';
  end if;
  -- Step 3: put the words back and note it.
  perform public.admin_swap_chapter_words(chapter_row, passage_row.marker_starts_at,
    passage_row.marker, passage_row.removed_text);
  update public.removed_passages set put_back_at = now() where removed_passages.id = passage_row.id;
  return public.admin_record_story_change(story_row, chapter_row.id, 'passage', reason_code, reason_text,
    jsonb_build_object('passage', 'removed'), jsonb_build_object('passage', 'put_back'), null);
end;
$$;


ALTER FUNCTION "public"."admin_put_back_passage"("story_row" "public"."stories", "removal" "public"."story_revisions", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_put_back_passage"("story_row" "public"."stories", "removal" "public"."story_revisions", "reason_code" "text", "reason_text" "text") IS 'Internal: Restore for a removed passage: the words go back where the marker is (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_raise_story_rating"("target_story_id" "uuid", "new_rating" "public"."story_rating", "reason_given" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  audit_id uuid;
begin
  -- Step 1: a staff session with the Stories › change permission (architecture 1.8.3).
  if not public.staff_may('story_changes', 'act') then
    raise exception 'Only staff who may change stories can raise a rating.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'A reason is required.' using errcode = 'check_violation';
  end if;
  select * into story from public.stories where stories.id = target_story_id;
  if not found then
    raise exception 'No such story.' using errcode = 'no_data_found';
  end if;
  -- Step 2: only up, never down or sideways (the enum's order is the ratings' order).
  if new_rating <= story.rating then
    raise exception 'A rating can only be raised, never lowered (S1-E3-06).' using errcode = 'check_violation';
  end if;
  -- Step 3: change, log and queue the statement of reasons, all in one transaction.
  update public.stories set rating = new_rating where stories.id = target_story_id;
  audit_id := public.log_staff_action('story.rating_raised', 'stories', target_story_id::text, story.user_id,
    reason_given, jsonb_build_object('rating', story.rating), jsonb_build_object('rating', new_rating));
  insert into public.jobs (kind, payload) values ('statement_of_reasons_needed',
    jsonb_build_object('story_id', target_story_id, 'audit_log_id', audit_id, 'action', 'rating_raised'));
  return audit_id;
end;
$$;


ALTER FUNCTION "public"."admin_raise_story_rating"("target_story_id" "uuid", "new_rating" "public"."story_rating", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_raise_story_rating"("target_story_id" "uuid", "new_rating" "public"."story_rating", "reason_given" "text") IS 'Staff raise a story''s rating (never lower); logged; a statement of reasons is queued (S1-E3-06).';



CREATE OR REPLACE FUNCTION "public"."admin_recent_picture_openings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
     or not exists (select 1 from public.picture_open_alert_recipients() as recipient
                    where recipient = (select auth.uid())) then
    return null;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('staffHandle', grouped.handle, 'openings', grouped.openings,
                                        'lastOpenedAt', grouped.last_opened_at)
                     order by grouped.last_opened_at desc)
    from (select profiles.handle, count(*) as openings, max(audit_log.created_at) as last_opened_at
          from public.audit_log
          join public.profiles on profiles.id = audit_log.user_id
          where audit_log.action = 'picture.opened' and audit_log.created_at > now() - interval '7 days'
          group by profiles.handle) as grouped), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."admin_recent_picture_openings"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_recent_picture_openings"() IS 'Staff: who opened original pictures in the last seven days, for the people alerted (ADMIN-2e2a).';



CREATE OR REPLACE FUNCTION "public"."admin_record_story_change"("story_row" "public"."stories", "target_chapter_id" "uuid", "change_kind" "text", "reason_code" "text", "reason_text" "text", "values_before" "jsonb", "values_after" "jsonb", "statement_action" "public"."statement_action") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  audit_id uuid;
  revision_id uuid;
  item_type public.reportable_type := case when target_chapter_id is null then 'story' else 'chapter' end;
  item_id uuid := coalesce(target_chapter_id, story_row.id);
begin
  -- Step 1: the audit log, with the owner's user ID (S1-E11-08 criterion "any change").
  audit_id := public.log_staff_action('story.' || change_kind || '_changed', item_type::text, item_id::text,
    story_row.user_id, reason_code || ': ' || btrim(reason_text), values_before, values_after);
  -- Step 2: the version.
  insert into public.story_revisions (user_id, story_id, chapter_id, changed_by_user_id, change_kind,
    reason_code, reason_text, before_values, after_values, audit_log_id)
  values (story_row.user_id, story_row.id, target_chapter_id, (select auth.uid()), change_kind,
    reason_code, btrim(reason_text), values_before, values_after, audit_id)
  returning id into revision_id;
  -- Step 3: the writer is told: a statement of reasons when content is restricted (criterion 3),
  -- otherwise a notification saying what changed and why (criterion 4).
  if statement_action is not null then
    perform public.issue_statement_of_reasons(story_row.user_id, statement_action,
      public.admin_story_reason_ground(reason_code), reason_code, reason_text,
      jsonb_build_object('story_id', story_row.id, 'item_type', item_type, 'item_id', item_id));
  else
    perform public.notify(story_row.user_id, 'story_changed_by_staff', null,
      jsonb_build_object('story_id', story_row.id, 'chapter_id', target_chapter_id,
        'story_revision_id', revision_id));
  end if;
  return revision_id;
end;
$$;


