CREATE OR REPLACE FUNCTION "public"."admin_reject_picture"("target_case_id" "uuid", "reason_key" "text", "message_to_person" "text", "note_text" "text", "police_description" "text" DEFAULT NULL::"text", "account_message" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases := public.picture_review_case(target_case_id);
  is_minor boolean := reason_key = 'sexual_image_of_minor';
  picture public.picture_checks;
begin
  -- Step 1: a known reason, a message for the person and a note for staff; for a minor, the
  -- words for the police and the account message too.
  if not exists (select 1 from public.settings, jsonb_array_elements_text(settings.value) as allowed(reason)
                 where settings.key = 'picture_reject_reasons' and allowed.reason = reason_key) then
    raise exception 'Choose what the picture shows.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(message_to_person, '')) = '' or btrim(coalesce(note_text, '')) = ''
     or char_length(message_to_person) > 4000 then
    raise exception 'Write the message and the note.' using errcode = 'check_violation';
  end if;
  if is_minor and (btrim(coalesce(police_description, '')) = '' or char_length(police_description) > 500
                   or btrim(coalesce(account_message, '')) = '' or char_length(account_message) > 4000) then
    raise exception 'Describe the image for the police.' using errcode = 'check_violation',
      hint = 'police_description_missing';
  end if;
  -- Step 2: the statement first, so the case's notification links it when the case is decided.
  perform public.issue_statement_of_reasons(target.user_id, 'remove',
    case when is_minor then 'law' else 'terms' end::public.statement_ground,
    case when is_minor then 'child_sexual_content' else 'picture_check' end, message_to_person,
    jsonb_build_object('case_id', target.id, 'item_type', 'picture', 'item_id', target.item_id,
      'automated_detection', target.source = 'picture_check'));
  -- Step 3: remove it through the case (moderate_item, the decision trigger, notifications, audit).
  perform public.decide_case(target, 'remove', note_text, message_to_person, null, false);
  perform public.log_staff_action('picture.rejected', 'picture_checks', target.item_id::text, target.user_id,
    note_text, jsonb_build_object('status', 'held'), jsonb_build_object('status', 'removed', 'reason', reason_key));
  if not is_minor then
    return true;
  end if;
  -- Step 4 (a minor): the evidence, the file deleted, the case to safeguarding, the account closed.
  select * into picture from public.picture_checks where id = target.item_id;
  perform public.record_abuse_image_evidence(picture, target, 'moderator', police_description, (select auth.uid()));
  update public.cases set is_safeguarding = true where id = target.id;
  perform public.close_account_for_abuse_image(target, note_text, account_message);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_reject_picture"("target_case_id" "uuid", "reason_key" "text", "message_to_person" "text", "note_text" "text", "police_description" "text", "account_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reject_picture"("target_case_id" "uuid", "reason_key" "text", "message_to_person" "text", "note_text" "text", "police_description" "text", "account_message" "text") IS 'Staff: rejects a waiting picture with a reason; for a sexual image of a minor also keeps the evidence, deletes the file and closes the account (ADMIN-2e1b, ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."admin_reject_tag"("tag_id" "uuid", "reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_status public.tag_status;
  rejected public.tags;
  link record;
  removed_count integer := 0;
begin
  perform public.require_tag_staff();
  -- Step 1: the reason staff give.
  if btrim(coalesce(reason, '')) = '' then
    raise exception 'Give a reason.' using errcode = 'check_violation', hint = 'reason:empty';
  end if;
  if char_length(btrim(reason)) > 300 then
    raise exception 'The reason is too long.' using errcode = 'check_violation', hint = 'reason:too_long';
  end if;
  -- Step 2: the tag, rejected.
  select tags.status into before_status from public.tags where tags.id = admin_reject_tag.tag_id for update;
  update public.tags
  set status = 'rejected', decided_by_user_id = (select auth.uid()), decided_at = now(),
      decision_reason = btrim(reason)
  where tags.id = admin_reject_tag.tag_id and tags.status <> 'rejected'
  returning * into rejected;
  if rejected.id is null then
    raise exception 'There is no tag to reject with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 3: off every story, and each writer told once per story.
  for link in
    delete from public.story_tags where story_tags.tag_id = rejected.id
    returning story_tags.story_id, story_tags.user_id
  loop
    perform public.notify(link.user_id, 'tag_rejected', null, jsonb_build_object('story_id', link.story_id));
    removed_count := removed_count + 1;
  end loop;
  -- Step 4: the audit log, with the reason and how many stories it left.
  perform public.log_staff_action('tag.rejected', 'tags', rejected.id::text, null, btrim(reason),
    jsonb_build_object('name', rejected.name, 'status', before_status),
    jsonb_build_object('name', rejected.name, 'status', 'rejected', 'stories', removed_count));
  return removed_count;
end;
$$;


ALTER FUNCTION "public"."admin_reject_tag"("tag_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reject_tag"("tag_id" "uuid", "reason" "text") IS 'Rejects a tag: off every story, writers told; moderation staff; logged (CMS-1e).';



CREATE OR REPLACE FUNCTION "public"."admin_release_case"("target_case_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases := public.require_case_for_acting(target_case_id);
  claim_minutes integer := coalesce((public.setting_value('case_claim_minutes'))::text::integer, 60);
begin
  if target.claimed_by_user_id is null then
    return true;
  end if;
  if target.claimed_by_user_id <> (select auth.uid()) and target.claimed_at > now() - make_interval(mins => claim_minutes) then
    raise exception 'Only the moderator who claimed this case can release it now.' using errcode = 'check_violation';
  end if;
  update public.cases set claimed_by_user_id = null, claimed_at = null where id = target.id;
  perform public.log_staff_action('case.released', 'cases', target.id::text, target.user_id, null,
    jsonb_build_object('claimed_by_user_id', target.claimed_by_user_id), jsonb_build_object('claimed_by_user_id', null));
  return true;
end;
$$;


