COMMENT ON FUNCTION "public"."admin_release_case"("target_case_id" "uuid") IS 'A moderator gives a claimed case back to the queue; logged (S1-E10-03b).';



CREATE OR REPLACE FUNCTION "public"."admin_remove_ad_blocked_category"("target_key" "text", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  removed public.ad_blocked_categories;
begin
  -- Step 1: owner or admin, with a reason.
  perform public.require_sponsor_staff();
  if btrim(coalesce(reason, '')) = '' then
    raise exception 'Say why it is removed.' using errcode = 'check_violation';
  end if;
  -- Step 2: never a fixed category.
  select * into removed from public.ad_blocked_categories where category_key = target_key for update;
  if removed.id is null then
    raise exception 'No such category.' using errcode = 'no_data_found';
  elsif removed.is_fixed then
    raise exception 'This category can never be removed.' using errcode = 'check_violation';
  end if;
  -- Step 3: remove it and log it.
  delete from public.ad_blocked_categories where id = removed.id;
  perform public.log_staff_action('ad_blocked_category.removed', 'ad_blocked_categories', target_key, null, btrim(reason),
    jsonb_build_object('label_ro', removed.label_ro, 'label_en', removed.label_en), null);
end;
$$;


ALTER FUNCTION "public"."admin_remove_ad_blocked_category"("target_key" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_remove_ad_blocked_category"("target_key" "text", "reason" "text") IS 'Removes a staff-added ad category, never a fixed one; owner and admin only; logged (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."admin_remove_chapter_passage"("target_chapter_id" "uuid", "passage" "text", "occurrence" integer, "case_reference" "text", "reason_code" "text", "reason_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter_row public.chapters;
  story_row public.stories;
  case_row public.cases;
  starts_at integer;
  marker text;
  revision_id uuid;
begin
  -- Step 1: the chapter, then the checks every change starts with.
  select * into chapter_row from public.chapters
  where chapters.id = target_chapter_id and chapters.deleted_at is null;
  story_row := public.admin_story_change_target(chapter_row.story_id, reason_code, reason_text);
  if chapter_row.published_body is null then
    raise exception 'This chapter has never been published.'
      using errcode = 'check_violation', hint = 'not_published';
  end if;
  if char_length(coalesce(passage, '')) > 20000 then
    raise exception 'Remove at most 20,000 characters at once.'
      using errcode = 'check_violation', hint = 'passage_too_long';
  end if;
  case_row := public.admin_passage_case(case_reference);
  -- Step 2: the exact words must still be where staff selected them.
  starts_at := public.admin_passage_place(chapter_row.published_body, passage, coalesce(occurrence, 0));
  if coalesce(passage, '') = '' or starts_at is null then
    raise exception 'Those words are no longer in the chapter; open it again.'
      using errcode = 'check_violation', hint = 'text_changed';
  end if;
  -- Step 3: the cut. The marker is in the story's language.
  marker := public.removed_passage_marker(story_row.language_code);
  perform public.admin_swap_chapter_words(chapter_row, starts_at, passage, marker);
  -- Step 4: the version (no words in it), the audit log and the statement of reasons.
  revision_id := public.admin_record_story_change(story_row, chapter_row.id, 'passage', reason_code,
    reason_text,
    jsonb_build_object('passage', jsonb_build_object('characters', char_length(passage))),
    jsonb_build_object('passage', 'removed'),
    'remove');
  -- Step 5: the original, for staff only.
  insert into public.removed_passages (user_id, story_id, chapter_id, story_revision_id, case_id,
    case_is_safeguarding, removed_by_user_id, removed_text, marker_starts_at, marker)
  values (story_row.user_id, story_row.id, chapter_row.id, revision_id, case_row.id,
    coalesce(case_row.is_safeguarding, false), (select auth.uid()), passage, starts_at, marker);
  return revision_id;
end;
$$;


ALTER FUNCTION "public"."admin_remove_chapter_passage"("target_chapter_id" "uuid", "passage" "text", "occurrence" integer, "case_reference" "text", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_remove_chapter_passage"("target_chapter_id" "uuid", "passage" "text", "occurrence" integer, "case_reference" "text", "reason_code" "text", "reason_text" "text") IS 'Staff cut one exact passage out of a chapter, leaving the marker; versioned, audited, the writer gets a statement of reasons (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_remove_cms_entry"("content_kind" "text", "entry_key" "text", "market_code" "text", "language_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  removal public.cms_versions;
  live_content jsonb;
begin
  perform public.require_website_staff();
  language_code := nullif(btrim(language_code), '');
  -- Step 1: the home page always has a version; it is replaced, never removed.
  if content_kind = 'home_page' then
    raise exception 'The home page can be replaced, not removed.' using errcode = 'check_violation', hint = 'home_page_stays';
  end if;
  removal := row(null, content_kind, entry_key, market_code, language_code, '{}'::jsonb, 'published', true,
    public.romania_today(), null, (select auth.uid()), now(), now(), now())::public.cms_versions;
  live_content := public.cms_live_content_of(removal);
  if live_content is null then
    raise exception 'Nothing is live there.' using errcode = 'no_data_found';
  end if;
  -- Step 2: a published removal from today hides the entry; earlier versions stay for Restore.
  insert into public.cms_versions (content_kind, entry_key, market_code, language_code, status, is_removal, show_from, user_id, published_at)
  values (content_kind, entry_key, market_code, language_code, 'published', true, public.romania_today(), (select auth.uid()), now())
  returning * into removal;
  perform public.log_staff_action('website.removed', 'cms_versions', removal.id::text, null, null,
    jsonb_build_object('content', live_content),
    jsonb_build_object('kind', content_kind, 'entry', entry_key, 'market', market_code, 'language', language_code));
end;
$$;


