CREATE OR REPLACE FUNCTION "public"."admin_removed_passage"("target_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  passage_row public.removed_passages;
begin
  -- Step 1: the passage, then who may read it.
  select * into passage_row from public.removed_passages
  where removed_passages.story_revision_id = target_revision_id;
  if not public.staff_may('story_changes', 'act')
     or (found and not public.may_see_case(passage_row.case_is_safeguarding)) then
    raise exception 'Only the staff working on this can read a removed passage.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  if not found then
    raise exception 'That version removed no passage.' using errcode = 'check_violation', hint = 'no_such_version';
  end if;
  -- Step 2: the read goes in the audit log, with the writer's user ID.
  perform public.log_staff_action('story.removed_passage_read', 'chapter', passage_row.chapter_id::text,
    passage_row.user_id, null, null, null);
  return jsonb_build_object('text', passage_row.removed_text,
    'case_reference', (select cases.reference from public.cases where cases.id = passage_row.case_id),
    'put_back', passage_row.put_back_at is not null);
end;
$$;


ALTER FUNCTION "public"."admin_removed_passage"("target_revision_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_removed_passage"("target_revision_id" "uuid") IS 'The original words of a removed passage for staff who may change stories; the read is logged (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_reply_mail"("thread_reference" "text", "body" "text", "is_note" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.moderator_mail_threads := public.require_mail_thread_for_staff(thread_reference);
  clean_body text := public.clean_mail_text(body, 4000);
begin
  insert into public.moderator_mail_messages (thread_id, user_id, body, is_internal_note, from_team)
  values (thread.id, (select auth.uid()), clean_body, coalesce(is_note, false), true);
  if not coalesce(is_note, false) then
    update public.moderator_mail_threads set status = 'waiting', last_message_at = now() where id = thread.id;
    perform public.notify(thread.user_id, 'moderator_mail_reply', null, jsonb_build_object('mail_thread_id', thread.id));
  end if;
  perform public.log_staff_action(
    case when coalesce(is_note, false) then 'moderator_mail.noted' else 'moderator_mail.replied' end,
    'moderator_mail_threads', thread.id::text, thread.user_id, null, null, null);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_reply_mail"("thread_reference" "text", "body" "text", "is_note" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reply_mail"("thread_reference" "text", "body" "text", "is_note" boolean) IS 'Staff reply as the moderation team, or add an internal note; logged without the words (S1-E10-11).';



CREATE OR REPLACE FUNCTION "public"."admin_reply_support_ticket"("ticket_number" bigint, "body" "text", "is_note" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ticket public.support_tickets := public.require_support_ticket_for_staff(ticket_number);
  clean_body text := public.clean_mail_text(body, 4000);
  note boolean := coalesce(is_note, false);
begin
  -- Step 1: a closed ticket takes notes only.
  if ticket.status = 'closed' and not note then
    raise exception 'This ticket is closed, so it can''t be answered.' using errcode = 'check_violation';
  end if;
  -- Step 2: the message.
  insert into public.support_ticket_messages (ticket_id, kind, author_user_id, body, channel)
  values (ticket.id, case when note then 'internal_note' else 'staff_reply' end::public.support_message_kind,
    (select auth.uid()), clean_body, case when ticket.channel = 'in_app' then 'in_app' else 'email' end::public.support_ticket_channel);
  -- Step 3: a reply moves the ticket on and is what the first-reply timer measures.
  if not note then
    update public.support_tickets set last_message_at = now(), first_replied_at = coalesce(first_replied_at, now())
    where id = ticket.id;
    if ticket.status in ('new', 'open') then
      update public.support_tickets set status = 'pending_on_user' where id = ticket.id;
      perform public.record_support_event(ticket.id, 'status', to_jsonb(ticket.status), to_jsonb('pending_on_user'::text));
    end if;
  end if;
  perform public.log_staff_action(case when note then 'support_ticket.noted' else 'support_ticket.replied' end,
    'support_tickets', ticket.id::text, ticket.requester_user_id, null, null, null);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_reply_support_ticket"("ticket_number" bigint, "body" "text", "is_note" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reply_support_ticket"("ticket_number" bigint, "body" "text", "is_note" boolean) IS 'Staff answer a support ticket or add an internal note; logged without the words (S1-E11-13 criteria 3 and 5).';



CREATE OR REPLACE FUNCTION "public"."admin_request_customisation_change"("item" "text", "reference" "text", "reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_id uuid;
  target_space_id uuid;
  new_id uuid;
begin
  -- Step 1: moderation staff only, in a staff session.
  if not public.staff_may('moderation', 'act') then
    raise exception 'Only moderators can do that.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: whose signature or banner it is; there must be one to change.
  if admin_request_customisation_change.item = 'signature' then
    select profiles.id into owner_id from public.profile_for_handle(reference) as profiles
    where profiles.signature is not null or profiles.signature_picture_id is not null;
  elsif admin_request_customisation_change.item = 'space_banner' then
    select spaces.user_id, spaces.id into owner_id, target_space_id from public.spaces
    where spaces.slug = btrim(reference) and spaces.deleted_at is null and spaces.banner_picture_id is not null;
  end if;
  if owner_id is null then
    raise exception 'There is nothing to change.' using errcode = 'no_data_found', hint = 'change:nothing';
  end if;
  -- Step 3: one open request at a time.
  if exists (select 1 from public.customisation_change_requests as requests
             where requests.user_id = owner_id and requests.item = admin_request_customisation_change.item
               and requests.space_id is not distinct from target_space_id and requests.resolved_at is null) then
    raise exception 'A request is already open.' using errcode = 'unique_violation', hint = 'change:open';
  end if;
  -- Step 4: the request, the person's notification and the audit log.
  insert into public.customisation_change_requests (user_id, item, space_id, requested_by_user_id, reason)
  values (owner_id, admin_request_customisation_change.item, target_space_id, (select auth.uid()), btrim(reason))
  returning id into new_id;
  perform public.notify(owner_id, 'customisation_change_requested', null,
    jsonb_build_object('change_request_id', new_id, 'space_id', target_space_id));
  perform public.log_staff_action('customisation.change_requested', 'customisation_change_requests',
    new_id::text, owner_id, btrim(reason), null, jsonb_build_object('item', admin_request_customisation_change.item));
  return new_id;
end;
$$;


ALTER FUNCTION "public"."admin_request_customisation_change"("item" "text", "reference" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_request_customisation_change"("item" "text", "reference" "text", "reason" "text") IS 'A moderator asks a person to change their signature or space banner within 24 hours; logged (S1-E8-08).';



CREATE OR REPLACE FUNCTION "public"."admin_request_report_details"("report_reference" "text", "question" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.reports;
  target_case public.cases;
begin
  -- Step 1: the report and its case, and whether the caller may act on it.
  select * into target from public.reports where reports.reference = report_reference;
  if target.id is null then
    raise exception 'There is no report like that.' using errcode = 'no_data_found';
  end if;
  select * into target_case from public.cases where cases.id = target.case_id;
  if not public.staff_may('moderation', 'act') or not public.may_see_case(target_case.is_safeguarding) then
    raise exception 'You can''t ask about this report.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a question, on an open case, one at a time.
  if btrim(coalesce(question, '')) = '' then
    raise exception 'Write the question.' using errcode = 'check_violation';
  end if;
  if target_case.status <> 'open' then
    raise exception 'This case is already decided.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.report_detail_requests
             where report_id = target.id and answered_at is null) then
    raise exception 'A question about this report is still waiting for an answer.' using errcode = 'check_violation';
  end if;
  -- Step 3: the request and the audit row.
  insert into public.report_detail_requests (user_id, report_id, case_id, requested_by_user_id, question)
  values (target.user_id, target.id, target.case_id, (select auth.uid()), btrim(question));
  perform public.log_staff_action('report.details_requested', 'reports', target.id::text, target.user_id,
    null, null, jsonb_build_object('reference', target.reference));
end;
$$;


ALTER FUNCTION "public"."admin_request_report_details"("report_reference" "text", "question" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_request_report_details"("report_reference" "text", "question" "text") IS 'Staff: asks a reporter for more details about one report, audited (S1-E10-08).';



CREATE OR REPLACE FUNCTION "public"."admin_reset_interface_text"("text_key" "text", "locale" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  live_text text := public.interface_text_live_text(text_key, locale);
  reset_id uuid;
begin
  perform public.require_website_staff();
  if live_text is null then
    raise exception 'This text already shows the default.' using errcode = 'no_data_found';
  end if;
  -- A published reset from today; earlier versions stay for Restore.
  insert into public.interface_text_overrides (text_key, locale, status, is_reset, show_from, user_id, published_at)
  values (text_key, locale, 'published', true, public.romania_today(), (select auth.uid()), clock_timestamp())
  returning id into reset_id;
  perform public.log_staff_action('interface_text.reset', 'interface_text_overrides', reset_id::text, null, null,
    jsonb_build_object('text', live_text), jsonb_build_object('key', text_key, 'locale', locale, 'text', null));
end;
$$;


ALTER FUNCTION "public"."admin_reset_interface_text"("text_key" "text", "locale" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reset_interface_text"("text_key" "text", "locale" "text") IS 'Brings the locale file text of a key back from today; owner and admin only; logged (S1-E11-18).';



CREATE OR REPLACE FUNCTION "public"."admin_reset_pen_name"("target_user_id" "uuid", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  old_pen_name text;
begin
  -- Step 1: the shared checks.
  perform public.require_account_action_allowed(target_user_id, reason_given);
  -- Step 2: there must be a pen name to reset.
  select profiles.pen_name into old_pen_name from public.profiles
    where profiles.id = target_user_id for update;
  if old_pen_name is null then
    raise exception 'This account has no pen name.' using errcode = 'check_violation', hint = 'no_pen_name';
  end if;
  -- Step 3: clear it, and let the person choose a new one straight away.
  update public.profiles set pen_name = null, pen_name_changed_at = null
    where profiles.id = target_user_id;
  -- Step 4: the audit row, in the same transaction.
  perform public.log_staff_action(
    'account.pen_name_reset', 'profiles', target_user_id::text, target_user_id, btrim(reason_given),
    jsonb_build_object('pen_name', old_pen_name), jsonb_build_object('pen_name', null)
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_reset_pen_name"("target_user_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reset_pen_name"("target_user_id" "uuid", "reason_given" "text") IS 'Clears an account''s pen name with a reason; the old one stays in the audit log (S1-E11-02).';



CREATE OR REPLACE FUNCTION "public"."admin_restore_cms_version"("version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  earlier public.cms_versions;
  draft_id uuid;
begin
  perform public.require_website_staff();
  -- Step 1: the earlier version (a removal has no copy to restore).
  select * into earlier from public.cms_versions where id = version_id and status = 'published' and not is_removal;
  if earlier.id is null then
    raise exception 'There is no earlier version with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 2: its copy becomes the draft, with no date chosen yet.
  draft_id := public.admin_save_cms_draft(earlier.content_kind, earlier.entry_key, earlier.market_code,
    earlier.language_code, earlier.content, null, earlier.show_until);
  perform public.log_staff_action('website.restored', 'cms_versions', draft_id::text, null, null,
    jsonb_build_object('restored_from', earlier.id, 'published_at', earlier.published_at),
    jsonb_build_object('kind', earlier.content_kind, 'entry', earlier.entry_key, 'market', earlier.market_code,
      'language', earlier.language_code, 'content', earlier.content));
  return draft_id;
end;
$$;


ALTER FUNCTION "public"."admin_restore_cms_version"("version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_restore_cms_version"("version_id" "uuid") IS 'Restores an earlier website content version as a draft; owner and admin only; logged (S1-E11-06).';



CREATE OR REPLACE FUNCTION "public"."admin_restore_interface_text"("version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  earlier public.interface_text_overrides;
  draft_id uuid;
begin
  perform public.require_website_staff();
  -- Step 1: the earlier version (a reset has no text to restore).
  select * into earlier from public.interface_text_overrides
  where id = version_id and status = 'published' and not is_reset;
  if earlier.id is null then
    raise exception 'There is no earlier version with that id.' using errcode = 'no_data_found';
  end if;
  -- Step 2: its text becomes the draft. It was checked when it was saved, so the checks are
  -- passed its own placeholders.
  draft_id := public.admin_save_interface_text(earlier.text_key, earlier.locale, earlier.text,
    public.text_placeholders(earlier.text), '{}', null);
  perform public.log_staff_action('interface_text.restored', 'interface_text_overrides', draft_id::text, null, null,
    jsonb_build_object('restored_from', earlier.id, 'published_at', earlier.published_at),
    jsonb_build_object('key', earlier.text_key, 'locale', earlier.locale, 'text', earlier.text));
  return draft_id;
end;
$$;


ALTER FUNCTION "public"."admin_restore_interface_text"("version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_restore_interface_text"("version_id" "uuid") IS 'Restores an earlier interface text as a draft; owner and admin only; logged (S1-E11-18).';



CREATE OR REPLACE FUNCTION "public"."admin_restore_item"("target_item_id" "uuid", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.moderated_items;
begin
  if not public.staff_may('moderation', 'act') then
    raise exception 'Only moderation staff can restore an item.' using errcode = 'insufficient_privilege';
  end if;
  select * into target from public.moderated_items where id = target_item_id for update;
  if target.id is null or target.restored_at is not null then
    raise exception 'There is nothing to restore.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Say why the item is restored.' using errcode = 'check_violation';
  end if;
  update public.moderated_items set restored_at = now(), restored_by_user_id = (select auth.uid()),
    restore_reason = btrim(reason_given)
  where id = target.id;
  perform public.log_staff_action(
    'item.restored', target.item_type::text, target.item_id::text, target.user_id, btrim(reason_given),
    jsonb_build_object('state', target.state), jsonb_build_object('restored', true)
  );
  return true;
end;
$$;


