CREATE OR REPLACE FUNCTION "public"."admin_review_sponsor_campaign"("target_campaign_id" "uuid", "decision" "text", "confirmed_checks" "text"[], "note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  campaign public.sponsor_campaigns;
  new_state public.sponsor_campaign_state;
begin
  -- Step 1: owner or admin; a campaign in the queue; a known decision.
  perform public.require_sponsor_staff();
  campaign := public.locked_sponsor_campaign(target_campaign_id, array['in_review']::public.sponsor_campaign_state[]);
  if decision not in ('approve', 'send_back') then
    raise exception 'Approve or send back.' using errcode = 'check_violation';
  end if;
  -- Step 2: approving needs every check, nothing missing and a picture anyone may see.
  if decision = 'approve' then
    perform public.require_sponsor_approval_ready(campaign, confirmed_checks);
    new_state := 'approved';
  elsif btrim(coalesce(note, '')) = '' then
    raise exception 'Say what needs to change.' using errcode = 'check_violation';
  else
    new_state := 'sent_back';
  end if;
  -- Step 3: the decision, with the reviewer and the time, logged.
  update public.sponsor_campaigns
  set state = new_state, reviewer_user_id = (select auth.uid()), reviewed_at = now(),
      review_checks = case when new_state = 'approved' then public.sponsor_review_checks() else '{}' end,
      review_note = btrim(coalesce(note, ''))
  where id = campaign.id;
  perform public.log_staff_action('sponsor_campaign.' || decision, 'sponsor_campaigns', campaign.id::text, null,
    nullif(btrim(coalesce(note, '')), ''), jsonb_build_object('state', campaign.state),
    jsonb_build_object('state', new_state, 'checks', to_jsonb(coalesce(confirmed_checks, '{}'))));
end;
$$;


ALTER FUNCTION "public"."admin_review_sponsor_campaign"("target_campaign_id" "uuid", "decision" "text", "confirmed_checks" "text"[], "note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_review_sponsor_campaign"("target_campaign_id" "uuid", "decision" "text", "confirmed_checks" "text"[], "note" "text") IS 'Approves a sponsor campaign after every check, or sends it back with a note; owner and admin only; logged (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."admin_revoke_certificate"("code" "text", "reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.certificates;
  clean_reason text := btrim(coalesce(reason, ''));
begin
  perform public.require_teacher_checks_access();
  select * into target from public.certificates
  where certificates.code = public.clean_certificate_code(admin_revoke_certificate.code) for update;
  if target.id is null then
    raise exception 'There is no such certificate.' using errcode = 'no_data_found', hint = 'certificate:missing';
  end if;
  if char_length(clean_reason) not between 1 and 500 then
    raise exception 'Say why, in 1 to 500 characters.' using errcode = 'check_violation', hint = 'certificate:reason';
  end if;
  if target.revoked_at is not null then
    raise exception 'This certificate is already revoked.' using errcode = 'check_violation', hint = 'certificate:revoked';
  end if;
  update public.certificates
  set revoked_at = now(), revoke_reason = clean_reason, revoked_by_user_id = (select auth.uid())
  where certificates.id = target.id;
  perform public.log_staff_action('certificate.revoked', 'certificates', target.id::text, target.user_id,
    clean_reason, jsonb_build_object('status', 'valid'), jsonb_build_object('status', 'revoked'));
  return jsonb_build_object('status', 'revoked');
end;
$$;


ALTER FUNCTION "public"."admin_revoke_certificate"("code" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_revoke_certificate"("code" "text", "reason" "text") IS 'Staff (Schools): revokes a certificate; logged (S1-E8-12 criterion 7).';



CREATE OR REPLACE FUNCTION "public"."admin_revoke_invite"("target_invite_id" "uuid", "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.invites;
begin
  if not public.staff_may('invites', 'act') then
    raise exception 'Only an owner or admin can revoke invite links.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Give a reason.' using errcode = 'check_violation';
  end if;
  select * into target from public.invites
    where invites.id = target_invite_id and invites.purpose = 'platform';
  if target.id is null then
    raise exception 'There is no such invite link.' using errcode = 'check_violation';
  end if;
  if target.revoked_at is not null then
    return false;
  end if;
  update public.invites set revoked_at = now() where invites.id = target_invite_id;
  perform public.log_staff_action(
    'invite.revoked', 'invites', target.id::text, null, reason_given,
    jsonb_build_object('revoked_at', null, 'note', target.note),
    jsonb_build_object('revoked_at', now(), 'note', target.note)
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_revoke_invite"("target_invite_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_revoke_invite"("target_invite_id" "uuid", "reason_given" "text") IS 'Revokes a platform invite link with a reason (owner and admin); logged as invite.revoked (S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."admin_safety_contact_checks"() RETURNS TABLE("country_code" "text", "check_month" "date", "contact_count" integer, "still_to_confirm" integer, "closed_at" timestamp with time zone, "closed_by_handle" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('safety_contacts', 'view') then
    raise exception 'Only staff can see the safety contact checks.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select checks.country_code, checks.check_month,
      (select count(*)::integer from public.safety_contacts where safety_contacts.country_code = checks.country_code),
      (select count(*)::integer from public.safety_contacts where safety_contacts.country_code = checks.country_code
         and safety_contacts.last_checked_on < checks.created_at::date),
      checks.closed_at, closer.handle
    from public.safety_contact_checks as checks
    left join public.profiles as closer on closer.id = checks.closed_by_user_id
    where checks.closed_at is null or checks.closed_at > now() - interval '12 months'
    order by (checks.closed_at is not null), checks.check_month desc, checks.country_code;
end;
$$;


ALTER FUNCTION "public"."admin_safety_contact_checks"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_safety_contact_checks"() IS 'The monthly safety contact checks, open ones first (S1-E10-13b).';



CREATE OR REPLACE FUNCTION "public"."admin_safety_contact_warnings"() RETURNS TABLE("id" "uuid", "country_code" "text", "label" "text", "last_checked_on" "date", "days_since" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  warning_days integer := coalesce((public.setting_value('safety_contact_warning_days'))::text::integer, 45);
begin
  if not public.staff_may('safety_contacts', 'view') then
    raise exception 'Only staff can see the safety contact warnings.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select safety_contacts.id, safety_contacts.country_code, safety_contacts.label, safety_contacts.last_checked_on,
      (current_date - safety_contacts.last_checked_on)::integer
    from public.safety_contacts
    where safety_contacts.last_checked_on < current_date - warning_days
    order by safety_contacts.last_checked_on, safety_contacts.country_code;
end;
$$;


ALTER FUNCTION "public"."admin_safety_contact_warnings"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_safety_contact_warnings"() IS 'Safety contacts not confirmed for 45 days, for the owner''s warning (S1-E10-13b).';



CREATE OR REPLACE FUNCTION "public"."admin_save_age_rule"("rule" "jsonb", "reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wanted_country text := upper(btrim(coalesce(rule ->> 'country_code', '')));
  wanted_region text := upper(btrim(coalesce(rule ->> 'region_code', '')));
  before_row public.country_age_rules;
  after_row public.country_age_rules;
  graced integer;
begin
  -- Step 1: owner and admin only, in a staff session, with a reason.
  if not public.staff_may('settings', 'act') then
    raise exception 'Only an owner or admin can change the age rules.' using errcode = 'insufficient_privilege';
  end if;
  if char_length(btrim(coalesce(reason, ''))) = 0 then
    raise exception 'Say why the rule changes.' using errcode = 'check_violation', hint = 'reason_needed';
  end if;
  -- Step 2: the row as it was, if any.
  select * into before_row from public.country_age_rules
  where country_age_rules.country_code = wanted_country and country_age_rules.region_code = wanted_region
  for update;
  -- Step 3: write it; the table's checks refuse values out of range.
  insert into public.country_age_rules as rules (country_code, region_code, name, region_name,
    minimum_age, parental_consent_below, signup_blocked_below, legal_basis, source, date_checked,
    confidence, status, notes)
  values (wanted_country, wanted_region, btrim(coalesce(rule ->> 'name', '')),
    btrim(coalesce(rule ->> 'region_name', '')),
    (rule ->> 'minimum_age')::smallint, (rule ->> 'parental_consent_below')::smallint,
    nullif(rule ->> 'signup_blocked_below', '')::smallint,
    btrim(coalesce(rule ->> 'legal_basis', '')), btrim(coalesce(rule ->> 'source', '')),
    coalesce((rule ->> 'date_checked')::date, current_date),
    coalesce(rule ->> 'confidence', 'medium'), coalesce(rule ->> 'status', 'to_verify'),
    btrim(coalesce(rule ->> 'notes', '')))
  on conflict (country_code, region_code) do update set
    name = excluded.name, region_name = excluded.region_name, minimum_age = excluded.minimum_age,
    parental_consent_below = excluded.parental_consent_below,
    signup_blocked_below = excluded.signup_blocked_below, legal_basis = excluded.legal_basis,
    source = excluded.source, date_checked = excluded.date_checked,
    confidence = excluded.confidence, status = excluded.status, notes = excluded.notes
  returning * into after_row;
  -- Step 4: members newly asked for a parent's consent get 14 days (criterion 4).
  graced := public.start_consent_grace_for_rule(after_row.id);
  -- Step 5: the audit row, with the values before and after and how many got the grace.
  perform public.log_staff_action('age_rule.saved', 'country_age_rules', after_row.id::text, null,
    btrim(reason),
    case when before_row.id is null then null else to_jsonb(before_row) - 'created_at' - 'updated_at' end,
    (to_jsonb(after_row) - 'created_at' - 'updated_at') || jsonb_build_object('members_given_grace', graced));
  return after_row.id;
end;
$$;


ALTER FUNCTION "public"."admin_save_age_rule"("rule" "jsonb", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_age_rule"("rule" "jsonb", "reason" "text") IS 'Owner and admin add or change an age rule by country; audited with before and after (MARKETS-1, S1-E2-21).';



CREATE OR REPLACE FUNCTION "public"."admin_save_canned_reply"("reply_id" "uuid", "title" "text", "body_ro" "text", "body_en" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_row public.support_canned_replies;
  saved public.support_canned_replies;
begin
  -- Step 1: support staff only.
  if not public.staff_may('support_tickets', 'act') then
    raise exception 'Only support staff can change canned replies.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a new reply, or the change to one that exists.
  if reply_id is null then
    insert into public.support_canned_replies (title, body_ro, body_en, updated_by_user_id)
    values (btrim(title), btrim(body_ro), btrim(body_en), (select auth.uid()))
    returning * into saved;
  else
    select * into before_row from public.support_canned_replies
    where support_canned_replies.id = reply_id and deleted_at is null for update;
    if before_row.id is null then
      raise exception 'There is no such canned reply.' using errcode = 'no_data_found';
    end if;
    update public.support_canned_replies set title = btrim(admin_save_canned_reply.title),
      body_ro = btrim(admin_save_canned_reply.body_ro), body_en = btrim(admin_save_canned_reply.body_en),
      updated_by_user_id = (select auth.uid())
    where id = reply_id returning * into saved;
  end if;
  -- Step 3: the audit log keeps what changed.
  perform public.log_staff_action('support_canned_reply.saved', 'support_canned_replies', saved.id::text, null, null,
    case when before_row.id is null then null
         else jsonb_build_object('title', before_row.title, 'body_ro', before_row.body_ro, 'body_en', before_row.body_en) end,
    jsonb_build_object('title', saved.title, 'body_ro', saved.body_ro, 'body_en', saved.body_en));
  return saved.id;
end;
$$;


ALTER FUNCTION "public"."admin_save_canned_reply"("reply_id" "uuid", "title" "text", "body_ro" "text", "body_en" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_canned_reply"("reply_id" "uuid", "title" "text", "body_ro" "text", "body_en" "text") IS 'Support staff add or change a canned reply; logged with before and after (S1-E11-13 criterion 8).';



CREATE OR REPLACE FUNCTION "public"."admin_save_classic_work"("details" "jsonb", "target_story_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_values jsonb := case when target_story_id is null then null else public.classic_work_json(target_story_id) end;
  saved_story_id uuid;
begin
  perform public.require_classics_staff();
  -- Step 1: the story itself (title, rating, category, author byline).
  saved_story_id := public.classic_upsert_story(target_story_id, details, public.classic_story_category(details));
  -- Step 2: the public-domain details, kept beside it. A person saved them, so they are checked.
  insert into public.classic_works (story_id, kind, original_language, source_title, source_url,
    translator_name, translator_died_year, first_published_year, added_by_user_id, details_checked)
  values (saved_story_id, (details ->> 'kind')::public.classic_kind, details ->> 'original_language',
    btrim(details ->> 'source_title'), btrim(details ->> 'source_url'),
    nullif(btrim(coalesce(details ->> 'translator_name', '')), ''),
    (details ->> 'translator_died_year')::integer, (details ->> 'first_published_year')::integer,
    (select auth.uid()), true)
  on conflict (story_id) do update set kind = excluded.kind,
    original_language = excluded.original_language, source_title = excluded.source_title,
    source_url = excluded.source_url, translator_name = excluded.translator_name,
    translator_died_year = excluded.translator_died_year,
    first_published_year = excluded.first_published_year, details_checked = true;
  -- Step 3: the audit log, then the saved work.
  perform public.log_staff_action('classics.work_saved', 'stories', saved_story_id::text,
    public.classics_account_id(), null, before_values, public.classic_work_json(saved_story_id));
  return public.classic_work_json(saved_story_id);
end;
$$;


ALTER FUNCTION "public"."admin_save_classic_work"("details" "jsonb", "target_story_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_cms_draft"("content_kind" "text", "entry_key" "text", "market_code" "text", "language_code" "text", "new_content" "jsonb", "new_show_from" "date" DEFAULT NULL::"date", "new_show_until" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  place_problem text;
  draft_id uuid;
begin
  perform public.require_website_staff();
  -- Step 1: the entry's place must make sense. An empty language means none (a notice).
  language_code := nullif(btrim(language_code), '');
  place_problem := public.cms_entry_problem(content_kind, entry_key, market_code, language_code);
  if place_problem is not null then
    raise exception 'This draft can''t be saved there.' using errcode = 'check_violation', hint = place_problem;
  end if;
  -- Step 2: update the entry's draft, or start one.
  update public.cms_versions as versions
  set content = coalesce(new_content, '{}'::jsonb), show_from = new_show_from,
    show_until = new_show_until, user_id = (select auth.uid())
  where versions.status = 'draft' and versions.content_kind = admin_save_cms_draft.content_kind
    and versions.entry_key = admin_save_cms_draft.entry_key
    and versions.market_code = admin_save_cms_draft.market_code
    and coalesce(versions.language_code, '') = coalesce(admin_save_cms_draft.language_code, '')
  returning versions.id into draft_id;
  if draft_id is null then
    insert into public.cms_versions (content_kind, entry_key, market_code, language_code, content, show_from, show_until, user_id)
    values (content_kind, entry_key, market_code, language_code, coalesce(new_content, '{}'::jsonb),
      new_show_from, new_show_until, (select auth.uid()))
    returning id into draft_id;
  end if;
  return draft_id;
end;
$$;


ALTER FUNCTION "public"."admin_save_cms_draft"("content_kind" "text", "entry_key" "text", "market_code" "text", "language_code" "text", "new_content" "jsonb", "new_show_from" "date", "new_show_until" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_cms_draft"("content_kind" "text", "entry_key" "text", "market_code" "text", "language_code" "text", "new_content" "jsonb", "new_show_from" "date", "new_show_until" "date") IS 'Saves a website content draft; owner and admin only (S1-E11-06).';



CREATE OR REPLACE FUNCTION "public"."admin_save_contest"("target_contest_id" "uuid", "details" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_row public.contests;
  changed public.contests;
  problems text[];
begin
  perform public.require_contest_staff();
  -- Step 1: the contest, locked so two editors can't save at once.
  select * into current_row from public.contests where id = target_contest_id for update;
  if current_row.id is null then
    raise exception 'That contest doesn''t exist.' using errcode = 'no_data_found';
  end if;
  -- Step 2: the new values, checked field by field.
  changed := public.contest_details_from_json(current_row, coalesce(details, '{}'::jsonb));
  problems := public.contest_problems(changed);
  -- Step 3: an open contest must stay ready to be open.
  if current_row.opened_at is not null and cardinality(problems) > 0 then
    raise exception 'This change would leave the open contest incomplete.'
      using errcode = 'check_violation', hint = 'breaks_open_contest', detail = array_to_string(problems, ',');
  end if;
  -- Step 4: save and log, with the values before and after.
  update public.contests set
    name_ro = changed.name_ro, name_en = changed.name_en,
    entries_open_on = changed.entries_open_on, entries_close_on = changed.entries_close_on,
    results_on = changed.results_on, age_groups = changed.age_groups,
    market_codes = changed.market_codes, language_codes = changed.language_codes,
    what_counts_ro = changed.what_counts_ro, what_counts_en = changed.what_counts_en,
    word_limit = changed.word_limit, prize_ro = changed.prize_ro, prize_en = changed.prize_en,
    prize_delivered_by = changed.prize_delivered_by, judges = changed.judges,
    rules_page_key = changed.rules_page_key
  where id = target_contest_id;
  perform public.log_staff_action('contest.saved', 'contests', target_contest_id::text, null, null,
    to_jsonb(current_row) - array['created_at', 'updated_at'], to_jsonb(changed) - array['created_at', 'updated_at']);
  return problems;
end;
$$;


ALTER FUNCTION "public"."admin_save_contest"("target_contest_id" "uuid", "details" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_contest"("target_contest_id" "uuid", "details" "jsonb") IS 'Saves a contest''s details; owner and admin only; logged with before and after (S1-E11-15).';



CREATE OR REPLACE FUNCTION "public"."admin_save_forum"("forum_id" "uuid", "parent_id" "uuid", "slug" "text", "sort_position" integer, "is_pinned" boolean, "accent" "public"."forum_accent", "names" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  problems text[];
  before_forum jsonb;
  saved_id uuid;
begin
  perform public.require_forum_staff();
  -- Step 1: the names, the address and the pin, before anything is written.
  problems := public.forum_name_problems(names);
  if admin_save_forum.slug is null or admin_save_forum.slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
     or char_length(admin_save_forum.slug) not between 2 and 60 then
    problems := array_append(problems, 'slug:format');
  end if;
  -- An address stays taken by a removed forum too, so an old link never leads somewhere new.
  if exists (select 1 from public.forums where forums.slug = admin_save_forum.slug
             and forums.id is distinct from admin_save_forum.forum_id) then
    problems := array_append(problems, 'slug:taken');
  end if;
  if coalesce(admin_save_forum.is_pinned, false) and admin_save_forum.parent_id is not null then
    problems := array_append(problems, 'pin:not_category');
  end if;
  if cardinality(problems) > 0 then
    raise exception 'Fix the forum before saving.' using errcode = 'check_violation', hint = array_to_string(problems, ',');
  end if;
  -- Step 2: add it, or change the one staff opened (the level trigger checks the parent).
  if admin_save_forum.forum_id is null then
    insert into public.forums (parent_id, slug, position, is_pinned, accent)
    values (admin_save_forum.parent_id, admin_save_forum.slug, greatest(coalesce(sort_position, 0), 0),
      coalesce(admin_save_forum.is_pinned, false), coalesce(admin_save_forum.accent, 'plum'))
    returning forums.id into saved_id;
  else
    before_forum := public.forum_as_json(admin_save_forum.forum_id);
    update public.forums
    set parent_id = admin_save_forum.parent_id, slug = admin_save_forum.slug,
      position = greatest(coalesce(sort_position, 0), 0),
      is_pinned = coalesce(admin_save_forum.is_pinned, false),
      accent = coalesce(admin_save_forum.accent, 'plum')
    where forums.id = admin_save_forum.forum_id and forums.deleted_at is null
    returning forums.id into saved_id;
    if saved_id is null then
      raise exception 'There is no forum with that id.' using errcode = 'no_data_found';
    end if;
  end if;
  -- Step 3: the names, then the audit log in the same transaction.
  perform public.write_forum_names(saved_id, names);
  perform public.log_staff_action(
    case when before_forum is null then 'forum.created' else 'forum.changed' end,
    'forums', saved_id::text, null, null, before_forum, public.forum_as_json(saved_id));
  return saved_id;
end;
$_$;


ALTER FUNCTION "public"."admin_save_forum"("forum_id" "uuid", "parent_id" "uuid", "slug" "text", "sort_position" integer, "is_pinned" boolean, "accent" "public"."forum_accent", "names" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_forum"("forum_id" "uuid", "parent_id" "uuid", "slug" "text", "sort_position" integer, "is_pinned" boolean, "accent" "public"."forum_accent", "names" "jsonb") IS 'Adds or changes a forum category, forum or subforum; owner and admin; logged (S1-E8-01).';



CREATE OR REPLACE FUNCTION "public"."admin_save_house_ad"("target_house_ad_id" "uuid", "fields" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_values jsonb;
  saved_id uuid;
begin
  perform public.require_sponsor_staff();
  -- Step 1: a change starts from a house ad that exists and isn't archived.
  if target_house_ad_id is not null then
    select to_jsonb(house_ads) into before_values from public.house_ads
    where id = target_house_ad_id and archived_at is null for update;
    if before_values is null then
      raise exception 'No such house ad.' using errcode = 'no_data_found';
    end if;
  end if;
  -- Step 2: save; the table's checks refuse a missing title, someone else's link or bad days.
  if target_house_ad_id is null then
    insert into public.house_ads (user_id, title_ro, title_en, text_ro, text_en, link_path, slot_key, starts_on, ends_on)
    values (auth.uid(), btrim(fields ->> 'title_ro'), btrim(fields ->> 'title_en'),
      btrim(coalesce(fields ->> 'text_ro', '')), btrim(coalesce(fields ->> 'text_en', '')),
      btrim(fields ->> 'link_path'), nullif(fields ->> 'slot_key', ''),
      (fields ->> 'starts_on')::date, (fields ->> 'ends_on')::date)
    returning id into saved_id;
  else
    update public.house_ads
    set title_ro = btrim(fields ->> 'title_ro'), title_en = btrim(fields ->> 'title_en'),
        text_ro = btrim(coalesce(fields ->> 'text_ro', '')), text_en = btrim(coalesce(fields ->> 'text_en', '')),
        link_path = btrim(fields ->> 'link_path'), slot_key = nullif(fields ->> 'slot_key', ''),
        starts_on = (fields ->> 'starts_on')::date, ends_on = (fields ->> 'ends_on')::date
    where id = target_house_ad_id
    returning id into saved_id;
  end if;
  -- Step 3: the audit log keeps the before and after.
  perform public.log_staff_action('house_ad.saved', 'house_ads', saved_id::text, null, null, before_values,
    (select to_jsonb(house_ads) from public.house_ads where id = saved_id));
  return saved_id;
end;
$$;


