CREATE OR REPLACE FUNCTION "public"."admin_search_audit_log"("action_prefix" "text" DEFAULT NULL::"text", "staff_handle" "text" DEFAULT NULL::"text", "target_user_id" "uuid" DEFAULT NULL::"uuid", "from_date" "date" DEFAULT NULL::"date", "to_date" "date" DEFAULT NULL::"date", "page_size" integer DEFAULT 50, "page_number" integer DEFAULT 1) RETURNS SETOF "public"."audit_log_row"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('audit_log', 'view') then
    raise exception 'Only an owner or admin can read the audit log.' using errcode = 'insufficient_privilege';
  end if;
  return query
    select * from public.audit_log_rows(
      action_prefix, staff_handle, target_user_id, from_date, to_date,
      least(greatest(page_size, 1), 100), (greatest(page_number, 1) - 1) * least(greatest(page_size, 1), 100)
    );
end;
$$;


ALTER FUNCTION "public"."admin_search_audit_log"("action_prefix" "text", "staff_handle" "text", "target_user_id" "uuid", "from_date" "date", "to_date" "date", "page_size" integer, "page_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_search_audit_log"("action_prefix" "text", "staff_handle" "text", "target_user_id" "uuid", "from_date" "date", "to_date" "date", "page_size" integer, "page_number" integer) IS 'One page of the audit log for owner and admin, newest first (S1-E11-01).';



CREATE OR REPLACE FUNCTION "public"."admin_search_stories"("search_text" "text" DEFAULT ''::"text", "story_status" "text" DEFAULT NULL::"text", "category_slug" "text" DEFAULT NULL::"text", "language_code" "text" DEFAULT NULL::"text", "wanted_rating" "public"."story_rating" DEFAULT NULL::"public"."story_rating", "only_open_reports" boolean DEFAULT false, "only_minor_writers" boolean DEFAULT false, "readable_by" "text" DEFAULT NULL::"text", "page_number" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wanted text := lower(btrim(coalesce(search_text, '')));
  page_size constant integer := 50;
  result jsonb;
begin
  -- Step 1: owner, admin, moderator and support, in a staff session (architecture 1.8.3).
  if not public.staff_may('stories', 'view') then
    raise exception 'Only staff with the Stories area can list stories.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;

  -- Step 2: every matching story, filtered, counted and cut to one page.
  with matching as (
    select stories.*
    from public.stories
    left join public.categories on categories.id = stories.category_id
    where stories.deleted_at is null
      and public.admin_story_matches(stories, wanted)
      and (story_status is null or public.admin_story_status(stories) = story_status)
      and (admin_search_stories.category_slug is null or categories.slug = admin_search_stories.category_slug)
      and (admin_search_stories.language_code is null or stories.language_code = admin_search_stories.language_code)
      and (wanted_rating is null or stories.rating = wanted_rating)
      and (not only_open_reports
           or (public.admin_story_report_counts(stories.id) ->> 'open')::integer > 0)
      and (not only_minor_writers or public.admin_story_owner_is_minor(stories.user_id))
      -- "Where it can be read": everyone, or one class only (S1-E8-11). App-only stories aren't
      -- built yet (S1-E3-08 is after March), so these are the two places today.
      and (admin_search_stories.readable_by is null
           or (admin_search_stories.readable_by = 'class') = stories.class_only)
  ),
  one_page as (
    select matching.* from matching
    order by matching.updated_at desc, matching.id
    limit page_size offset greatest(page_number, 0) * page_size
  )
  select jsonb_build_object(
    'total', (select count(*) from matching),
    'page_size', page_size,
    'stories', coalesce((select jsonb_agg(public.admin_story_row(one_page::public.stories)
                                          order by one_page.updated_at desc, one_page.id)
                         from one_page), '[]'::jsonb))
  into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."admin_search_stories"("search_text" "text", "story_status" "text", "category_slug" "text", "language_code" "text", "wanted_rating" "public"."story_rating", "only_open_reports" boolean, "only_minor_writers" boolean, "readable_by" "text", "page_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_search_stories"("search_text" "text", "story_status" "text", "category_slug" "text", "language_code" "text", "wanted_rating" "public"."story_rating", "only_open_reports" boolean, "only_minor_writers" boolean, "readable_by" "text", "page_number" integer) IS 'Staff › Stories for owner, admin, moderator and support: search and filter every story, no text (S1-E11-07).';



CREATE OR REPLACE FUNCTION "public"."admin_send_data_request_parent_copy"("target_request_id" "uuid", "token_hash" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.admin_data_request_target(target_request_id, true);
  consent public.parental_consents := public.data_request_parent_consent(request.user_id);
  expires timestamptz;
begin
  -- Step 1: our server's link, for a request the parent confirmed.
  if not public.data_request_parent_is_signed('copy', request.id, token_hash, signature) then
    raise exception 'This request wasn''t signed by our server.'
      using errcode = 'insufficient_privilege', hint = 'unsigned';
  end if;
  if not request.goes_to_parent or request.identity <> 'confirmed' then
    raise exception 'The parent hasn''t confirmed this request.'
      using errcode = 'check_violation', hint = 'identity_not_checked';
  end if;
  if consent.id is null then
    raise exception 'No parent or guardian agreed for this account.'
      using errcode = 'check_violation', hint = 'no_parent_on_record';
  end if;
  -- Step 2: a ready copy to point to.
  select max(exports.expires_at) into expires from public.exports
  where exports.data_request_id = request.id and exports.state = 'ready' and exports.expires_at > now();
  if expires is null then
    raise exception 'There is no copy to send.' using errcode = 'check_violation', hint = 'not_found';
  end if;
  -- Step 3: the new link; the old one stops working.
  update public.data_requests
  set parent_copy_token_hash = lower(token_hash), parent_copy_sent_at = now(),
      parent_copy_opened_at = null, handled_by_user_id = (select auth.uid())
  where data_requests.id = request.id;
  perform public.log_staff_action('data_request.parent_copy_link_sent', 'data_requests',
    request.id::text, request.user_id, null, null, jsonb_build_object('expires_at', expires));
  return public.data_request_parent_email(request, consent) || jsonb_build_object('expires_at', expires);
end;
$$;


ALTER FUNCTION "public"."admin_send_data_request_parent_copy"("target_request_id" "uuid", "token_hash" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_send_data_request_parent_copy"("target_request_id" "uuid", "token_hash" "text", "signature" "text") IS 'Staff send a parent the one-time link to a data request copy, signed by our server (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."admin_set_ai_undisclosed_label"("target_story_id" "uuid", "reason_given" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  audit_id uuid;
begin
  if not public.staff_may('story_changes', 'act') then
    raise exception 'Only staff who may change stories can add this label.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'A reason is required.' using errcode = 'check_violation';
  end if;
  select * into story from public.stories where stories.id = target_story_id;
  if not found then
    raise exception 'No such story.' using errcode = 'no_data_found';
  end if;
  update public.stories set ai_undisclosed_labelled_at = now() where stories.id = target_story_id;
  audit_id := public.log_staff_action('story.ai_undisclosed_labelled', 'stories', target_story_id::text, story.user_id,
    reason_given, jsonb_build_object('ai_undisclosed_labelled_at', story.ai_undisclosed_labelled_at),
    jsonb_build_object('ai_undisclosed_labelled_at', now()));
  insert into public.jobs (kind, payload) values ('statement_of_reasons_needed',
    jsonb_build_object('story_id', target_story_id, 'audit_log_id', audit_id, 'action', 'ai_undisclosed_labelled'));
  return audit_id;
end;
$$;


ALTER FUNCTION "public"."admin_set_ai_undisclosed_label"("target_story_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_ai_undisclosed_label"("target_story_id" "uuid", "reason_given" "text") IS 'Staff label a story "AI-written, not disclosed" after confirmed reports; logged; queued (S1-E3-06, Q24).';



CREATE OR REPLACE FUNCTION "public"."admin_set_birthday"("target_user_id" "uuid", "reason_given" "text", "wanted_month" integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  before_month smallint;
begin
  -- Step 1: the shared account-action checks, then the month itself.
  perform public.require_account_action_allowed(target_user_id, reason_given);
  perform public.check_birthday(wanted_month);
  -- Step 2: the change, keeping the old value for the log.
  select profiles.birthday_month into before_month
    from public.profiles where profiles.id = target_user_id for update;
  update public.profiles set birthday_month = wanted_month where profiles.id = target_user_id;
  -- Step 3: the audit row, in the same transaction.
  perform public.log_staff_action(
    'account.birthday_corrected', 'profiles', target_user_id::text, target_user_id, btrim(reason_given),
    jsonb_build_object('birthday_month', before_month),
    jsonb_build_object('birthday_month', wanted_month)
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_set_birthday"("target_user_id" "uuid", "reason_given" "text", "wanted_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_birthday"("target_user_id" "uuid", "reason_given" "text", "wanted_month" integer) IS 'Staff correct an account''s optional birthday month on request, with a reason, logged (S1-E2-12; QA-7).';



CREATE OR REPLACE FUNCTION "public"."admin_set_brand_asset"("target_slot" "public"."brand_asset_slot", "target_picture_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  earlier_picture_id uuid;
begin
  -- Step 1: owner or admin.
  perform public.require_website_staff();
  -- Step 2: a brand picture uploaded for this slot, not removed by moderation.
  if not exists (
    select 1 from public.picture_checks
    where picture_checks.id = target_picture_id and picture_checks.kind = 'brand_asset'
      and picture_checks.deleted_at is null and picture_checks.status <> 'removed'
      and split_part(picture_checks.path, '/', 1) = target_slot::text) then
    raise exception 'That picture isn''t a logo or emblem for this place.' using errcode = 'check_violation';
  end if;
  -- Step 3: remember what was there, then put the new picture in the slot. The picture the app
  -- shows now (the newest if approved, otherwise the earlier one) becomes the fallback.
  select brand_assets.picture_id into earlier_picture_id
  from public.brand_assets where brand_assets.slot = target_slot;
  insert into public.brand_assets (slot, picture_id, user_id)
  values (target_slot, target_picture_id, (select auth.uid()))
  on conflict (slot) do update
    set earlier_picture_id = public.brand_shown_picture(brand_assets),
        picture_id = excluded.picture_id, user_id = excluded.user_id, updated_at = now();
  -- Step 4: the audit log, in the same transaction (architecture 1.8.1).
  perform public.log_staff_action('website.brand_asset_set', 'brand_assets', target_slot::text, null, null,
    jsonb_build_object('picture_id', earlier_picture_id), jsonb_build_object('picture_id', target_picture_id));
end;
$$;


ALTER FUNCTION "public"."admin_set_brand_asset"("target_slot" "public"."brand_asset_slot", "target_picture_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_brand_asset"("target_slot" "public"."brand_asset_slot", "target_picture_id" "uuid") IS 'Puts an uploaded logo or emblem in its slot and logs it; owner and admin only (BRAND-1a).';



CREATE OR REPLACE FUNCTION "public"."admin_set_chapter_visibility"("target_chapter_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owning_story_id uuid := (select chapters.story_id from public.chapters
                           where chapters.id = target_chapter_id and chapters.deleted_at is null);
  story_row public.stories := public.admin_story_change_target(owning_story_id, reason_code, reason_text);
  current_visibility text := coalesce(public.moderated_state_of('chapter', target_chapter_id)::text, 'shown');
begin
  -- Step 1: a move staff may make here.
  if wanted_visibility is null or wanted_visibility not in ('shown', 'hidden') then
    raise exception 'Pick shown or hidden.' using errcode = 'check_violation', hint = 'bad_visibility';
  end if;
  if current_visibility = 'removed' then
    raise exception 'A case removed this chapter; only the case or an appeal can bring it back.'
      using errcode = 'check_violation', hint = 'removed_by_case';
  end if;
  if current_visibility = wanted_visibility then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'nothing_changed';
  end if;
  -- Step 2: hide it, or end the hide.
  if wanted_visibility = 'hidden' then
    insert into public.moderated_items (user_id, item_type, item_id, state, moderated_by_user_id, note)
    values (story_row.user_id, 'chapter', target_chapter_id, 'hidden', (select auth.uid()), btrim(reason_text));
  else
    perform public.admin_end_story_visibility_state('chapter', target_chapter_id, 'hidden', reason_text);
  end if;
  -- Step 3: the version, the audit log and the writer's statement or notification.
  return public.admin_record_story_change(story_row, target_chapter_id, 'chapter_visibility', reason_code,
    reason_text, jsonb_build_object('visibility', current_visibility),
    jsonb_build_object('visibility', wanted_visibility),
    case when wanted_visibility = 'hidden' then 'hide'::public.statement_action end);
end;
$$;


ALTER FUNCTION "public"."admin_set_chapter_visibility"("target_chapter_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_chapter_visibility"("target_chapter_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") IS 'Staff hide one chapter or show it again with a reason; versioned, audited, the writer told (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_set_class_school"("slug" "text", "school_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.spaces;
  clean_school text := btrim(coalesce(school_name, ''));
begin
  perform public.require_teacher_checks_access();
  select * into target from public.spaces
  where spaces.slug = admin_set_class_school.slug and spaces.kind = 'class' and spaces.deleted_at is null
  for update;
  if target.id is null then
    raise exception 'There is no such class.' using errcode = 'no_data_found', hint = 'space:missing';
  end if;
  if clean_school = '' then
    raise exception 'Write the school''s name.' using errcode = 'check_violation', hint = 'school:needed';
  end if;
  if char_length(clean_school) > 120 then
    raise exception 'The school''s name is too long.' using errcode = 'check_violation', hint = 'school:length';
  end if;
  update public.spaces set school_name = clean_school where spaces.id = target.id;
  perform public.log_staff_action('class_space.school_changed', 'spaces', target.id::text, target.user_id, null,
    jsonb_build_object('school_name', target.school_name), jsonb_build_object('school_name', clean_school));
  return jsonb_build_object('school_name', clean_school);
end;
$$;


ALTER FUNCTION "public"."admin_set_class_school"("slug" "text", "school_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_class_school"("slug" "text", "school_name" "text") IS 'Staff (Schools): writes the school a class belongs to; logged (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."admin_set_classic_chapters"("target_story_id" "uuid", "chapter_list" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_id uuid;
  chapter jsonb;
  chapter_number integer := 0;
  clean_body text;
begin
  perform public.require_classics_staff();
  -- Step 1: a classic that isn't live yet, and at least one chapter.
  select stories.user_id into owner_id from public.stories
  join public.classic_works on classic_works.story_id = stories.id
  where stories.id = target_story_id and stories.deleted_at is null;
  if owner_id is null then
    raise exception 'That isn''t a classic.' using errcode = 'no_data_found', hint = 'not_a_classic';
  end if;
  if exists (select 1 from public.chapters where chapters.story_id = target_story_id
             and chapters.deleted_at is null and chapters.first_published_at is not null) then
    raise exception 'This work has been published; its text can''t be replaced.'
      using errcode = 'check_violation', hint = 'already_published';
  end if;
  if jsonb_typeof(chapter_list) <> 'array' or jsonb_array_length(chapter_list) = 0 then
    raise exception 'Add the text first.' using errcode = 'check_violation', hint = 'no_chapters';
  end if;
  -- Step 2: the old drafts go (they were never public), the new ones come in order.
  update public.chapters set deleted_at = now()
  where chapters.story_id = target_story_id and chapters.deleted_at is null;
  for chapter in select * from jsonb_array_elements(chapter_list) loop
    chapter_number := chapter_number + 1;
    clean_body := public.check_chapter_text(coalesce(chapter ->> 'body', ''));
    insert into public.chapters (story_id, user_id, code, position, draft_title, draft_body, draft_saved_at, word_count)
    values (target_story_id, owner_id, public.chapter_code(), chapter_number,
      left(public.normalise_romanian_letters(btrim(coalesce(chapter ->> 'title', ''))), 120),
      clean_body, now(), public.count_words(clean_body));
  end loop;
  -- Step 3: the audit log keeps how many chapters and words, not the text itself.
  perform public.log_staff_action('classics.text_set', 'stories', target_story_id::text, owner_id, null,
    null, jsonb_build_object('chapters', chapter_number));
  return public.classic_work_json(target_story_id);
end;
$$;


ALTER FUNCTION "public"."admin_set_classic_chapters"("target_story_id" "uuid", "chapter_list" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_contest_placing"("target_entry_id" "uuid", "wanted_placing" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  entry public.contest_entries;
  target public.contests;
begin
  -- Step 1: owner or admin, a known placing and a valid entry.
  perform public.require_contest_staff();
  if wanted_placing is not null and wanted_placing not in ('winner', 'finalist') then
    raise exception 'A placing is winner, finalist or none.' using errcode = 'check_violation', hint = 'bad_placing';
  end if;
  select * into entry from public.contest_entries where id = target_entry_id for update;
  if entry.id is null then
    raise exception 'There is no such entry.' using errcode = 'no_data_found', hint = 'no_entry';
  end if;
  if entry.status <> 'valid' then
    raise exception 'Only a valid entry can place.' using errcode = 'check_violation', hint = 'not_valid';
  end if;
  -- Step 2: judging starts once entries close, so nobody is placed while others can still enter.
  select * into target from public.contests where id = entry.contest_id;
  if not public.contest_entries_have_closed(target) then
    raise exception 'Choose results once entries close.' using errcode = 'check_violation', hint = 'entries_open';
  end if;
  -- Step 3: the placing, then the audit row.
  update public.contest_entries set award = wanted_placing where id = entry.id;
  perform public.log_staff_action('contest.placing_set', 'contests', entry.id::text, entry.user_id, null,
    jsonb_build_object('placing', entry.award), jsonb_build_object('placing', wanted_placing, 'contest_id', target.id));
end;
$$;


ALTER FUNCTION "public"."admin_set_contest_placing"("target_entry_id" "uuid", "wanted_placing" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_contest_placing"("target_entry_id" "uuid", "wanted_placing" "text") IS 'Owner and admins: mark a contest entry as winner, finalist or neither, once entries close (S1-E11-15 criterion 7).';



CREATE OR REPLACE FUNCTION "public"."admin_set_evidence_hold"("evidence_id" "uuid", "should_hold" boolean, "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  found public.abuse_image_evidence := public.safeguarding_evidence_target(evidence_id);
begin
  if btrim(coalesce(reason_given, '')) = '' or char_length(reason_given) > 1000 then
    raise exception 'Write why.' using errcode = 'check_violation';
  end if;
  update public.abuse_image_evidence
    set legal_hold = should_hold, legal_hold_reason = case when should_hold then btrim(reason_given) end
    where id = found.id;
  perform public.log_staff_action(
    case when should_hold then 'safeguarding.legal_hold_set' else 'safeguarding.legal_hold_lifted' end,
    'abuse_image_evidence', found.id::text, found.user_id, btrim(reason_given),
    jsonb_build_object('legal_hold', found.legal_hold), jsonb_build_object('legal_hold', should_hold));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_set_evidence_hold"("evidence_id" "uuid", "should_hold" boolean, "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_evidence_hold"("evidence_id" "uuid", "should_hold" boolean, "reason_given" "text") IS 'Safeguarding staff: sets or lifts the legal hold on suspected abuse image evidence (ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."admin_set_featured_picks"("story_ids" "uuid"[], "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  picks uuid[] := coalesce(story_ids, '{}');
  before_list uuid[];
  refused text;
  pick_position integer;
begin
  -- Step 1: admins and the owner only, in a staff session, with a reason.
  if not public.staff_may('featured', 'act') then
    raise exception 'Only admins can change Featured this week.' using errcode = 'insufficient_privilege';
  end if;
  if reason is null or btrim(reason) = '' then
    raise exception 'Say why you are changing Featured this week.' using errcode = 'check_violation';
  end if;
  -- Step 2: the list's shape: not too long, no story twice.
  if cardinality(picks) > (public.setting_value('featured_max'))::text::integer then
    raise exception 'Featured this week holds at most % stories.',
      (public.setting_value('featured_max'))::text using errcode = 'check_violation';
  end if;
  if cardinality(picks) <> (select count(distinct pick) from unnest(picks) as pick) then
    raise exception 'A story is in the list twice.' using errcode = 'check_violation';
  end if;
  -- Step 3: every story must be one we may put on show (Robert, 6 Nov 2026: 16 or over).
  select public.featured_ineligible_reason(pick) into refused
  from unnest(picks) as pick
  where public.featured_ineligible_reason(pick) is not null
  limit 1;
  if refused is not null then
    raise exception 'A story in the list can''t be featured: %.', refused using errcode = 'check_violation';
  end if;
  -- Step 4: take the old list out (kept as a record) and put the new one in, in order.
  select coalesce(array_agg(featured_picks.story_id order by featured_picks.position), '{}')
  into before_list
  from public.featured_picks where featured_picks.removed_at is null;
  update public.featured_picks set removed_at = now(), updated_at = now() where removed_at is null;
  for pick_position in 1 .. cardinality(picks) loop
    insert into public.featured_picks (story_id, position, user_id)
    values (picks[pick_position], pick_position, (select auth.uid()));
  end loop;
  -- Step 5: the audit row with both lists, in the same transaction.
  perform public.log_staff_action('featured.picks_set', 'featured_picks', null, null, reason,
    jsonb_build_object('story_ids', to_jsonb(before_list)),
    jsonb_build_object('story_ids', to_jsonb(picks)));
  -- Step 6: tell each newly picked writer (not the classics account), once per story.
  insert into public.notifications (user_id, kind, actor_user_ids, actor_count, story_id, is_required)
  select stories.user_id, 'story_featured', '{}'::uuid[], 0, stories.id, false
  from public.stories
  where stories.id = any (picks)
    and not (stories.id = any (before_list))
    and not public.is_classics_account(stories.user_id);
end;
$$;


ALTER FUNCTION "public"."admin_set_featured_picks"("story_ids" "uuid"[], "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_featured_picks"("story_ids" "uuid"[], "reason" "text") IS 'Admins and the owner: replace Featured this week, logged with before and after; new writers are told (S1-E5-10).';



CREATE OR REPLACE FUNCTION "public"."admin_set_flag"("flag_key" "text", "turn_on" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  was_on boolean;
begin
  perform public.require_settings_staff();
  -- Step 1: the emergency switch needs the owner.
  if flag_key = 'parental_consent' and not turn_on and not public.is_staff('owner') then
    raise exception 'Only the owner can turn parental consent off.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the flag as it was, locked so two admins can't both change it at once.
  select is_enabled into was_on from public.feature_flags where key = flag_key for update;
  if was_on is null then
    raise exception 'There is no flag called %.', flag_key using errcode = 'no_data_found';
  end if;
  -- Step 3: the change and its log line, in the same transaction.
  update public.feature_flags set is_enabled = turn_on where key = flag_key;
  perform public.log_staff_action('settings.flag', 'feature_flags', flag_key, null, null,
    jsonb_build_object('is_enabled', was_on), jsonb_build_object('is_enabled', turn_on));
  return turn_on;
end;
$$;


ALTER FUNCTION "public"."admin_set_flag"("flag_key" "text", "turn_on" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_flag"("flag_key" "text", "turn_on" boolean) IS 'Switches a feature flag on or off; owner and admin only; logged (S1-E11-03).';



CREATE OR REPLACE FUNCTION "public"."admin_set_forum_rules_thread"("thread_number" bigint, "is_rules" boolean, "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads := public.forum_thread_for_moderation(thread_number, reason);
  previous_rules_thread_id uuid;
  -- A missing answer counts as "stop", the change that can't take anything from another thread.
  make_rules boolean := coalesce(is_rules, false);
begin
  -- Step 1: what the forum had before, for the log.
  select forums.rules_thread_id into previous_rules_thread_id
  from public.forums where forums.id = thread.forum_id for update;
  -- Step 2: make the change.
  if make_rules then
    update public.forums set rules_thread_id = thread.id where forums.id = thread.forum_id;
    update public.forum_threads set is_sticky = true where forum_threads.id = thread.id;
  else
    -- Only this thread's own mark is taken away, never another thread's.
    update public.forums set rules_thread_id = null
    where forums.id = thread.forum_id and forums.rules_thread_id = thread.id;
  end if;
  -- Step 3: log it with the reason.
  perform public.log_thread_moderation(thread,
    case when make_rules then 'rules_set' else 'rules_removed' end, reason,
    jsonb_build_object('rules_thread_id', previous_rules_thread_id, 'is_sticky', thread.is_sticky),
    jsonb_build_object(
      'rules_thread_id', case when make_rules then thread.id
                              when previous_rules_thread_id = thread.id then null
                              else previous_rules_thread_id end,
      'is_sticky', thread.is_sticky or make_rules));
end;
$$;


ALTER FUNCTION "public"."admin_set_forum_rules_thread"("thread_number" bigint, "is_rules" boolean, "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_forum_rules_thread"("thread_number" bigint, "is_rules" boolean, "reason" "text") IS 'Makes a thread its forum''s rules thread (and pins it), or stops it; moderators; logged (GAPS-9).';



CREATE OR REPLACE FUNCTION "public"."admin_set_forum_thread_next"("thread_number" bigint, "reason" "text", "next_thread_number" bigint DEFAULT NULL::bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads := public.forum_thread_for_moderation(thread_number, reason);
  next_thread public.forum_threads;
begin
  -- Step 1: only a locked thread points on.
  if thread.locked_at is null then
    raise exception 'Lock the thread first.' using errcode = 'check_violation', hint = 'thread:not_locked';
  end if;
  -- Step 2: find the other thread, when one is named.
  if next_thread_number is not null then
    select * into next_thread from public.forum_threads
    where forum_threads.thread_number = next_thread_number and forum_threads.deleted_at is null;
    if next_thread.id is null or not public.forum_thread_is_shown(next_thread) then
      raise exception 'That thread isn''t there.' using errcode = 'no_data_found', hint = 'next:missing';
    end if;
    if next_thread.id = thread.id then
      raise exception 'A thread can''t point at itself.' using errcode = 'check_violation', hint = 'next:same';
    end if;
  end if;
  -- Step 3: save and log.
  update public.forum_threads set continues_in_thread_id = next_thread.id where forum_threads.id = thread.id;
  perform public.log_thread_moderation(thread,
    case when next_thread.id is null then 'next_removed' else 'next_set' end, reason,
    jsonb_build_object('continues_in_thread_id', thread.continues_in_thread_id),
    jsonb_build_object('continues_in_thread_id', next_thread.id));
end;
$$;


ALTER FUNCTION "public"."admin_set_forum_thread_next"("thread_number" bigint, "reason" "text", "next_thread_number" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_forum_thread_next"("thread_number" bigint, "reason" "text", "next_thread_number" bigint) IS 'Points a locked thread at the thread that carries on, or takes the pointer away; moderators; logged (GAPS-9).';



CREATE OR REPLACE FUNCTION "public"."admin_set_forum_thread_sticky"("thread_number" bigint, "is_sticky" boolean, "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads := public.forum_thread_for_moderation(thread_number, reason);
begin
  update public.forum_threads set is_sticky = admin_set_forum_thread_sticky.is_sticky where forum_threads.id = thread.id;
  perform public.log_thread_moderation(thread,
    case when is_sticky then 'made_sticky' else 'sticky_removed' end, reason,
    jsonb_build_object('is_sticky', thread.is_sticky), jsonb_build_object('is_sticky', is_sticky));
end;
$$;


ALTER FUNCTION "public"."admin_set_forum_thread_sticky"("thread_number" bigint, "is_sticky" boolean, "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_forum_thread_sticky"("thread_number" bigint, "is_sticky" boolean, "reason" "text") IS 'Pins a forum thread to the top of its forum, or unpins it; moderation staff; logged (S1-E8-05).';



CREATE OR REPLACE FUNCTION "public"."admin_set_intern"("target_user_id" "uuid", "should_be_intern" boolean, "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  changed_row_id uuid;
begin
  -- Step 1: the same checks as a role or permission change.
  perform public.require_role_change_allowed(target_user_id, reason_given);
  if not exists (select 1 from public.staff_roles where staff_roles.user_id = target_user_id) then
    raise exception 'Only staff can be marked as interns.' using errcode = 'check_violation', hint = 'not_staff';
  end if;
  -- Step 2: the marker.
  if should_be_intern then
    insert into public.staff_interns (user_id, marked_by_user_id)
    values (target_user_id, (select auth.uid()))
    on conflict (user_id) do nothing
    returning id into changed_row_id;
  else
    delete from public.staff_interns where staff_interns.user_id = target_user_id
    returning id into changed_row_id;
  end if;
  if changed_row_id is null then
    return false;
  end if;
  perform public.log_staff_action(
    case when should_be_intern then 'staff.intern_marked' else 'staff.intern_unmarked' end,
    'staff_interns', changed_row_id::text, target_user_id, reason_given,
    jsonb_build_object('intern', not should_be_intern), jsonb_build_object('intern', should_be_intern));
  -- Step 3: an intern never keeps picture review (brief section 5).
  if should_be_intern then
    perform public.admin_set_permission(target_user_id, 'picture_review', false, reason_given);
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_set_intern"("target_user_id" "uuid", "should_be_intern" boolean, "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_intern"("target_user_id" "uuid", "should_be_intern" boolean, "reason_given" "text") IS 'Marks or unmarks a staff member as an intern, with a reason; marking removes picture review; logged (ADMIN-2e2a).';



CREATE OR REPLACE FUNCTION "public"."admin_set_language_status"("language_code" "text", "new_status" "public"."language_status") RETURNS "public"."language_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.languages;
  moderator_count integer;
begin
  perform public.require_settings_staff();
  select * into target from public.languages where code = language_code for update;
  if target.id is null then
    raise exception 'There is no such language.' using errcode = 'no_data_found';
  end if;
  -- Step 1: the interface languages stay open: every screen is written in them.
  if target.is_interface and new_status <> 'open' then
    raise exception 'The interface is in this language, so it stays open.' using errcode = 'check_violation', hint = 'interface_language';
  end if;
  -- Step 2: criterion 2: a language opens only with a moderator who reads it.
  select moderators into moderator_count from public.language_moderator_counts() where code = language_code;
  if new_status <> 'closed' and coalesce(moderator_count, 0) = 0 then
    raise exception 'No moderator who reads this language is on the rota yet.' using errcode = 'check_violation', hint = 'no_moderator';
  end if;
  update public.languages set status = new_status where id = target.id;
  perform public.log_staff_action('settings.language_status', 'languages', target.code, null, null,
    jsonb_build_object('status', target.status), jsonb_build_object('status', new_status));
  return new_status;
end;
$$;


ALTER FUNCTION "public"."admin_set_language_status"("language_code" "text", "new_status" "public"."language_status") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_language_status"("language_code" "text", "new_status" "public"."language_status") IS 'Opens, readies or closes a language; refused without a moderator who reads it; logged (S1-E11-05).';



CREATE OR REPLACE FUNCTION "public"."admin_set_launch_date"("new_date" "date") RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  old_value jsonb := public.setting_value('launch_date');
  new_value jsonb := to_jsonb(coalesce(new_date::text, ''));
begin
  perform public.require_compliance_staff();
  update public.settings set value = new_value where key = 'launch_date';
  perform public.log_staff_action('settings.value', 'settings', 'launch_date', null, null,
    jsonb_build_object('value', old_value), jsonb_build_object('value', new_value));
  return new_date;
end;
$$;


