CREATE OR REPLACE FUNCTION "public"."admin_set_market"("market_country" "text", "new_status" "public"."market_status", "new_legal_check" "public"."legal_check_status") RETURNS "public"."market_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.markets;
  problem text;
begin
  perform public.require_settings_staff();
  select * into target from public.markets where country_code = upper(market_country) for update;
  if target.id is null then
    raise exception 'There is no such market.' using errcode = 'no_data_found';
  end if;
  -- Step 1: the rules; opening without the owner's right is a privilege problem, not a value one.
  problem := public.market_change_problem(target, new_status, new_legal_check);
  if problem = 'owner_only' then
    raise exception 'Only the owner opens a market.' using errcode = 'insufficient_privilege', hint = problem;
  elsif problem is not null then
    raise exception 'This market can''t take that status (%).', problem using errcode = 'check_violation', hint = problem;
  end if;
  -- Step 2: the change (is_open follows by trigger) and its log line.
  update public.markets set status = new_status, legal_check = new_legal_check where id = target.id;
  perform public.log_staff_action('settings.market', 'markets', target.country_code, null, null,
    jsonb_build_object('status', target.status, 'legal_check', target.legal_check),
    jsonb_build_object('status', new_status, 'legal_check', new_legal_check));
  return new_status;
end;
$$;


ALTER FUNCTION "public"."admin_set_market"("market_country" "text", "new_status" "public"."market_status", "new_legal_check" "public"."legal_check_status") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_market"("market_country" "text", "new_status" "public"."market_status", "new_legal_check" "public"."legal_check_status") IS 'Changes a market''s status and legal check; opening is the owner''s; logged (S1-E11-05).';



CREATE OR REPLACE FUNCTION "public"."admin_set_on_call_shift"("on_call_user_id" "uuid", "shift_starts_at" timestamp with time zone, "shift_ends_at" timestamp with time zone, "reason_given" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_shift_id uuid;
begin
  -- Step 1: only owners and admins set the rota (architecture 1.8.3: they grant the permission).
  if not public.staff_may('on_call_rota', 'act') then
    raise exception 'Only an owner or admin can set the on-call rota.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the person holds the on-call permission, the shift makes sense, a reason is given.
  if not exists (select 1 from public.staff_permissions
                 where staff_permissions.user_id = on_call_user_id and staff_permissions.permission = 'on_call') then
    raise exception 'This person doesn''t hold the on-call permission.' using errcode = 'check_violation';
  end if;
  if shift_ends_at is null or shift_starts_at is null or shift_ends_at <= shift_starts_at or shift_ends_at <= now() then
    raise exception 'The shift must end after it starts, and in the future.' using errcode = 'check_violation';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Write a reason.' using errcode = 'check_violation';
  end if;
  -- Step 3: the shift (the table refuses an overlap) and the audit row.
  insert into public.on_call_rota (user_id, starts_at, ends_at, created_by_user_id)
  values (on_call_user_id, shift_starts_at, shift_ends_at, (select auth.uid()))
  returning id into new_shift_id;
  perform public.log_staff_action('on_call.shift_set', 'on_call_rota', new_shift_id::text, on_call_user_id,
    btrim(reason_given), null, jsonb_build_object('starts_at', shift_starts_at, 'ends_at', shift_ends_at));
  return new_shift_id;
end;
$$;


ALTER FUNCTION "public"."admin_set_on_call_shift"("on_call_user_id" "uuid", "shift_starts_at" timestamp with time zone, "shift_ends_at" timestamp with time zone, "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_on_call_shift"("on_call_user_id" "uuid", "shift_starts_at" timestamp with time zone, "shift_ends_at" timestamp with time zone, "reason_given" "text") IS 'Owners and admins put someone with the on-call permission on call; no overlaps; logged (S1-E10-09).';



CREATE OR REPLACE FUNCTION "public"."admin_set_permission"("target_user_id" "uuid", "changed_permission" "public"."staff_permission", "should_hold" boolean, "reason_given" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  changed_row_id uuid;
begin
  -- Step 1: the shared checks (role, fresh sign-in, not oneself, a reason, a real account).
  perform public.require_role_change_allowed(target_user_id, reason_given);
  if not exists (select 1 from public.staff_roles where staff_roles.user_id = target_user_id) then
    raise exception 'Permissions are only for staff.' using errcode = 'check_violation', hint = 'not_staff';
  end if;
  -- Step 2: picture review never for under-18s or interns (Robert, 2 Nov 2026, 08:29).
  if should_hold and changed_permission = 'picture_review'
     and (public.age_band_of(target_user_id) <> '18_plus'
          or exists (select 1 from public.staff_interns where staff_interns.user_id = target_user_id)) then
    raise exception 'Picture review is only for staff aged 18 or over who aren''t interns.'
      using errcode = 'check_violation', hint = 'picture_review_not_allowed';
  end if;
  -- Step 3: the change itself, then the audit log.
  if should_hold then
    insert into public.staff_permissions (user_id, permission, granted_by_user_id)
    values (target_user_id, changed_permission, (select auth.uid()))
    on conflict (user_id, permission) do nothing
    returning id into changed_row_id;
  else
    delete from public.staff_permissions
    where staff_permissions.user_id = target_user_id and staff_permissions.permission = changed_permission
    returning id into changed_row_id;
  end if;
  if changed_row_id is null then
    return false;
  end if;
  perform public.log_staff_action(
    case when should_hold then 'staff.permission_granted' else 'staff.permission_removed' end,
    'staff_permissions', changed_row_id::text, target_user_id, reason_given,
    jsonb_build_object('permission', changed_permission, 'held', not should_hold),
    jsonb_build_object('permission', changed_permission, 'held', should_hold));
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_set_permission"("target_user_id" "uuid", "changed_permission" "public"."staff_permission", "should_hold" boolean, "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_permission"("target_user_id" "uuid", "changed_permission" "public"."staff_permission", "should_hold" boolean, "reason_given" "text") IS 'Ticks or unticks a staff permission for someone else, with a reason; logged (S1-E2-07a).';



CREATE OR REPLACE FUNCTION "public"."admin_set_setting"("setting_key" "text", "new_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  old_value jsonb;
  problem text;
begin
  perform public.require_settings_staff();
  -- Step 1: the value as it was, locked for the change.
  select value into old_value from public.settings where key = setting_key for update;
  if old_value is null then
    raise exception 'There is no setting called %.', setting_key using errcode = 'no_data_found';
  end if;
  -- Step 2: the new value must keep the shape the database's functions read.
  problem := public.setting_value_problem(old_value, new_value);
  if problem is not null then
    raise exception 'This value can''t be saved (%).', problem using errcode = 'check_violation', hint = problem;
  end if;
  -- Step 3: the change and its log line.
  update public.settings set value = new_value where key = setting_key;
  perform public.log_staff_action('settings.value', 'settings', setting_key, null, null,
    jsonb_build_object('value', old_value), jsonb_build_object('value', new_value));
  return new_value;
end;
$$;


ALTER FUNCTION "public"."admin_set_setting"("setting_key" "text", "new_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_setting"("setting_key" "text", "new_value" "jsonb") IS 'Changes a named setting, keeping its shape; owner and admin only; logged (S1-E11-03).';



CREATE OR REPLACE FUNCTION "public"."admin_set_staff_languages"("target_user_id" "uuid", "language_codes" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  codes_before jsonb;
begin
  if not public.staff_may('roles', 'act') then
    raise exception 'Only the owner and admins record which languages staff read.' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.staff_roles where user_id = target_user_id) then
    raise exception 'This person isn''t staff.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from unnest(language_codes) as wanted where wanted not in (select code from public.languages)) then
    raise exception 'One of those languages isn''t on the list.' using errcode = 'check_violation';
  end if;
  -- Replace the whole list, logging it before and after.
  select coalesce(jsonb_agg(language_code order by language_code), '[]'::jsonb) into codes_before
  from public.staff_languages where user_id = target_user_id;
  delete from public.staff_languages where user_id = target_user_id;
  insert into public.staff_languages (user_id, language_code)
  select distinct target_user_id, wanted from unnest(language_codes) as wanted;
  perform public.log_staff_action('settings.staff_languages', 'staff_languages', target_user_id::text, target_user_id, null,
    jsonb_build_object('languages', codes_before),
    jsonb_build_object('languages', (select coalesce(jsonb_agg(distinct wanted order by wanted), '[]'::jsonb) from unnest(language_codes) as wanted)));
  return (select count(*)::integer from public.staff_languages where user_id = target_user_id);
end;
$$;


ALTER FUNCTION "public"."admin_set_staff_languages"("target_user_id" "uuid", "language_codes" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_staff_languages"("target_user_id" "uuid", "language_codes" "text"[]) IS 'Records the languages a staff member reads; owner and admin only; logged (S1-E11-05).';



CREATE OR REPLACE FUNCTION "public"."admin_set_story_presentation"("target_story_id" "uuid", "story_part" "text", "wanted_state" "text", "reason_code" "text", "reason_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story_row public.stories := public.admin_story_change_target(target_story_id, reason_code, reason_text);
  current_state text;
  hidden_at timestamptz := case when wanted_state = 'hidden' then now() end;
begin
  -- Step 1: a part and a state staff may set here.
  if story_part is null or story_part not in ('title', 'cover') then
    raise exception 'Pick the title or the cover.' using errcode = 'check_violation', hint = 'bad_part';
  end if;
  if wanted_state is null or wanted_state not in ('shown', 'hidden') then
    raise exception 'Pick shown or hidden.' using errcode = 'check_violation', hint = 'bad_visibility';
  end if;
  current_state := public.admin_story_part_state(story_row, story_part);
  if current_state = wanted_state then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'nothing_changed';
  end if;
  -- An automatic cover is what readers would see anyway (S1-E3-13).
  if story_part = 'cover' and wanted_state = 'hidden' and story_row.cover_kind = 'automatic' then
    raise exception 'The story already shows the automatic cover.' using errcode = 'check_violation', hint = 'no_cover';
  end if;
  -- Step 2: hide or show it. The writer's title and cover stay exactly as they wrote them.
  if story_part = 'title' then
    update public.stories set title_hidden_at = hidden_at where stories.id = story_row.id;
  else
    update public.stories set cover_hidden_at = hidden_at where stories.id = story_row.id;
  end if;
  -- Step 3: the version, the audit log and the writer's statement (hidden) or notification (shown).
  return public.admin_record_story_change(story_row, null, 'presentation', reason_code, reason_text,
    jsonb_build_object(story_part, current_state), jsonb_build_object(story_part, wanted_state),
    case when wanted_state = 'hidden' then (story_part || '_hidden')::public.statement_action end);
end;
$$;


ALTER FUNCTION "public"."admin_set_story_presentation"("target_story_id" "uuid", "story_part" "text", "wanted_state" "text", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_story_presentation"("target_story_id" "uuid", "story_part" "text", "wanted_state" "text", "reason_code" "text", "reason_text" "text") IS 'Staff hide or show a story''s title or cover with a reason; versioned, audited, the writer told (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_set_story_visibility"("target_story_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story_row public.stories := public.admin_story_change_target(target_story_id, reason_code, reason_text);
  current_visibility text := public.admin_story_visibility(target_story_id);
begin
  -- Step 1: a move staff may make here.
  if wanted_visibility is null or wanted_visibility not in ('shown', 'restricted', 'hidden') then
    raise exception 'Pick shown, restricted or hidden.' using errcode = 'check_violation', hint = 'bad_visibility';
  end if;
  if current_visibility = 'removed' then
    raise exception 'A case removed this story; only the case or an appeal can bring it back.'
      using errcode = 'check_violation', hint = 'removed_by_case';
  end if;
  if current_visibility = wanted_visibility then
    raise exception 'Nothing changed.' using errcode = 'check_violation', hint = 'nothing_changed';
  end if;
  -- Step 2: leave the current state, then enter the new one.
  perform public.admin_end_story_visibility_state('story', story_row.id, current_visibility, reason_text);
  if wanted_visibility = 'hidden' then
    insert into public.moderated_items (user_id, item_type, item_id, state, moderated_by_user_id, note)
    values (story_row.user_id, 'story', story_row.id, 'hidden', (select auth.uid()), btrim(reason_text));
  elsif wanted_visibility = 'restricted' then
    insert into public.story_restrictions (user_id, story_id, restricted_by_user_id, reason)
    values (story_row.user_id, story_row.id, (select auth.uid()), btrim(reason_text));
  end if;
  -- Step 3: the version, the audit log and the writer's statement or notification.
  return public.admin_record_story_change(story_row, null, 'visibility', reason_code, reason_text,
    jsonb_build_object('visibility', current_visibility), jsonb_build_object('visibility', wanted_visibility),
    case wanted_visibility when 'hidden' then 'hide' when 'restricted' then 'restrict' end::public.statement_action);
end;
$$;


ALTER FUNCTION "public"."admin_set_story_visibility"("target_story_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_story_visibility"("target_story_id" "uuid", "wanted_visibility" "text", "reason_code" "text", "reason_text" "text") IS 'Staff show, restrict or hide a story with a reason; versioned, audited, the writer told (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."admin_sign_out_everywhere"("target_user_id" "uuid", "reason_given" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ended integer;
begin
  perform public.require_account_action_allowed(target_user_id, reason_given);
  select count(*)::integer into ended from auth.sessions where sessions.user_id = target_user_id;
  perform public.sign_out_everywhere(target_user_id);
  perform public.log_staff_action(
    'account.signed_out_everywhere', 'profiles', target_user_id::text, target_user_id,
    btrim(reason_given), null, jsonb_build_object('sessions_ended', ended)
  );
  return ended;
end;
$$;


