CREATE TABLE IF NOT EXISTS "public"."chapters" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "story_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "position" integer NOT NULL,
    "draft_title" "text" DEFAULT ''::"text" NOT NULL,
    "draft_body" "text" DEFAULT ''::"text" NOT NULL,
    "draft_version" integer DEFAULT 1 NOT NULL,
    "draft_saved_at" timestamp with time zone,
    "published_title" "text",
    "published_body" "text",
    "status" "public"."chapter_status" DEFAULT 'draft'::"public"."chapter_status" NOT NULL,
    "scheduled_for" timestamp with time zone,
    "first_published_at" timestamp with time zone,
    "last_published_at" timestamp with time zone,
    "edited_at" timestamp with time zone,
    "word_count" integer DEFAULT 0 NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "unpublished_at" timestamp with time zone,
    "published_word_count" integer,
    CONSTRAINT "chapters_code_shape" CHECK (("code" ~ '^[a-z0-9]{8}$'::"text")),
    CONSTRAINT "chapters_draft_title_length" CHECK (("char_length"("draft_title") <= 120)),
    CONSTRAINT "chapters_draft_version_positive" CHECK (("draft_version" >= 1)),
    CONSTRAINT "chapters_position_positive" CHECK (("position" >= 1)),
    CONSTRAINT "chapters_published_has_copy" CHECK ((("status" <> 'published'::"public"."chapter_status") OR ("published_body" IS NOT NULL))),
    CONSTRAINT "chapters_scheduled_has_time" CHECK ((("status" <> 'scheduled'::"public"."chapter_status") OR ("scheduled_for" IS NOT NULL)))
);


ALTER TABLE "public"."chapters" OWNER TO "postgres";


COMMENT ON TABLE "public"."chapters" IS 'kind: user_content; reportable: chapter
One row per chapter: the draft and, once published, the public copy; owned by the story''s writer (S1-E3-02a).';



COMMENT ON COLUMN "public"."chapters"."user_id" IS 'The writer''s user ID, always the story''s owner (a trigger enforces it); never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."chapters"."code" IS 'The 8-character public address part (/s/<story>/<code>); fixed at creation, so reordering never breaks a link.';



COMMENT ON COLUMN "public"."chapters"."draft_version" IS 'Grows on every save; save_chapter_draft() refuses a stale expected_version, which S1-E3-02b shows as a conflict.';



COMMENT ON COLUMN "public"."chapters"."unpublished_at" IS 'When the writer last unpublished it; the published copy and its comments are kept (S1-E3-03).';



COMMENT ON COLUMN "public"."chapters"."published_word_count" IS 'The published copy''s word count, for the minutes to read (S1-E4-01a); the draft has its own.';



CREATE OR REPLACE FUNCTION "public"."admin_swap_chapter_words"("chapter_row" "public"."chapters", "starts_at" integer, "original" "text", "replacement" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_published text := overlay(chapter_row.published_body placing replacement
                                from starts_at for char_length(original));
begin
  update public.chapters set
    published_body = new_published,
    published_word_count = public.count_words(new_published),
    draft_body = case when chapter_row.draft_body = chapter_row.published_body then new_published
                      else replace(chapter_row.draft_body, original, replacement) end,
    word_count = public.count_words(case when chapter_row.draft_body = chapter_row.published_body
                   then new_published else replace(chapter_row.draft_body, original, replacement) end),
    draft_version = chapter_row.draft_version + 1
  where chapters.id = chapter_row.id;
end;
$$;


