CREATE OR REPLACE FUNCTION "public"."admin_unpublish_classic"("target_story_id" "uuid", "reason_given" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.require_classics_staff();
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Write a reason first.' using errcode = 'check_violation', hint = 'reason_missing';
  end if;
  if public.classic_work_json(target_story_id) is null then
    raise exception 'That isn''t a classic.' using errcode = 'no_data_found', hint = 'not_a_classic';
  end if;
  -- The chapters go back to drafts, as a writer's unpublish does (S1-E3-03).
  update public.chapters set status = 'draft', unpublished_at = now()
  where chapters.story_id = target_story_id and chapters.status = 'published' and chapters.deleted_at is null;
  perform public.log_staff_action('classics.unpublished', 'stories', target_story_id::text,
    public.classics_account_id(), btrim(reason_given), null, null);
  return public.classic_work_json(target_story_id);
end;
$$;


ALTER FUNCTION "public"."admin_unpublish_classic"("target_story_id" "uuid", "reason_given" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_support_ticket"("ticket_number" bigint, "changes" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ticket public.support_tickets := public.require_support_ticket_for_staff(ticket_number);
  new_status public.support_ticket_status;
  new_priority public.support_ticket_priority;
  new_category public.support_ticket_category;
  new_assignee uuid := ticket.assigned_to_user_id;
  new_tags text[] := ticket.tags;
begin
  -- Step 1: the new values; a key that isn't given keeps the ticket's value.
  new_status := coalesce((changes ->> 'status')::public.support_ticket_status, ticket.status);
  new_priority := coalesce((changes ->> 'priority')::public.support_ticket_priority, ticket.priority);
  new_category := coalesce((changes ->> 'category')::public.support_ticket_category, ticket.category);
  if changes ? 'assignee' then
    new_assignee := case when nullif(btrim(changes ->> 'assignee'), '') is null then null
                         else public.support_assignee_id(changes ->> 'assignee') end;
  end if;
  if changes ? 'tags' then
    select coalesce(array_agg(distinct lower(btrim(tag)) order by lower(btrim(tag))), '{}')
    into new_tags from jsonb_array_elements_text(changes -> 'tags') as tag where btrim(tag) <> '';
  end if;
  -- Step 2: the ticket (the table's checks refuse tags of the wrong shape).
  update public.support_tickets set
    status = new_status, priority = new_priority, category = new_category,
    assigned_to_user_id = new_assignee, tags = new_tags,
    solved_at = case when new_status = 'solved' and ticket.status <> 'solved' then now()
                     when new_status in ('solved', 'closed') then solved_at else null end,
    closed_at = case when new_status = 'closed' then coalesce(closed_at, now()) else null end
  where id = ticket.id;
  -- Step 3: one history line and one audit line per field that changed.
  perform public.apply_support_change(ticket, 'status', to_jsonb(ticket.status), to_jsonb(new_status));
  perform public.apply_support_change(ticket, 'priority', to_jsonb(ticket.priority), to_jsonb(new_priority));
  perform public.apply_support_change(ticket, 'category', to_jsonb(ticket.category), to_jsonb(new_category));
  perform public.apply_support_change(ticket, 'assignee',
    to_jsonb((select profiles.handle from public.profiles where profiles.id = ticket.assigned_to_user_id)),
    to_jsonb((select profiles.handle from public.profiles where profiles.id = new_assignee)));
  perform public.apply_support_change(ticket, 'tags', to_jsonb(ticket.tags), to_jsonb(new_tags));
  return true;
exception
  when invalid_text_representation then
    raise exception 'That value isn''t one a ticket can have.' using errcode = 'check_violation';
end;
$$;


ALTER FUNCTION "public"."admin_update_support_ticket"("ticket_number" bigint, "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_support_ticket"("ticket_number" bigint, "changes" "jsonb") IS 'Staff change a support ticket''s status, priority, category, assignee or tags; each change is kept and logged (S1-E11-13 criterion 4).';



CREATE OR REPLACE FUNCTION "public"."admin_user_account"("target_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "handle" "text", "pen_name" "text", "joined_at" timestamp with time zone, "account_status" "public"."account_status", "age_band" "public"."age_band", "age_check_result" "public"."age_check_result", "age_checked_at" timestamp with time zone, "age_check_method" "text", "email_masked" "text", "staff_roles" "public"."staff_role"[], "may_view_sanctions" boolean, "may_act" boolean, "may_reveal_email" boolean, "may_read_audit_log" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  found record;
begin
  -- Step 1: owner, admin, moderator and support, in a staff session.
  if not public.staff_may('users', 'view') then
    raise exception 'Only staff with the Users area can open an account.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  -- Step 2: the account, deleted ones included (staff may still need their history).
  select profiles.*, users.email into found
  from public.profiles
  left join auth.users on users.id = profiles.id
  where profiles.id = target_user_id;
  if found.id is null then
    raise exception 'There is no such account.' using errcode = 'check_violation', hint = 'no_such_account';
  end if;
  -- Step 3: the row. The age group uses the younger possible age, as age_band() does.
  user_id := found.id;
  handle := found.handle;
  pen_name := found.pen_name;
  joined_at := found.created_at;
  account_status := public.account_state(found.id);
  age_band := coalesce(public.age_band_from_birth(found.birth_year, found.birth_month,
    found.age_check_result, (now() at time zone 'Europe/Bucharest')::date), 'unknown');
  age_check_result := found.age_check_result;
  age_checked_at := found.age_checked_at;
  age_check_method := found.age_check_method::text;
  email_masked := public.mask_email(found.email);
  staff_roles := coalesce(
    (select array_agg(roles.role order by roles.role) from public.staff_roles as roles
     where roles.user_id = found.id), '{}');
  may_view_sanctions := public.staff_may('user_sanctions', 'view');
  may_act := public.staff_may('user_sanctions', 'act');
  may_reveal_email := public.staff_may('reveal_email', 'act');
  may_read_audit_log := public.staff_may('audit_log', 'view');
  return next;
end;
$$;


