    "adults_may_message" boolean DEFAULT false NOT NULL,
    "teacher_badge_since" timestamp with time zone,
    "messages_from" "public"."message_audience",
    "profile_visible_to" "public"."profile_audience",
    "library_visible_to" "public"."library_audience" DEFAULT 'only_me'::"public"."library_audience" NOT NULL,
    "last_active_at" timestamp with time zone,
    "signature" "text",
    "signature_picture_id" "uuid",
    "avatar_recipe" "jsonb",
    "message_emails_on" boolean,
