    "shows_reader_level" boolean DEFAULT false NOT NULL,
    CONSTRAINT "profiles_avatar_recipe_shape" CHECK ("public"."avatar_recipe_valid"("avatar_recipe")),
    CONSTRAINT "profiles_bio_length" CHECK (("char_length"("bio") <= 300)),
    CONSTRAINT "profiles_birth_month_is_a_month" CHECK ((("birth_month" >= 1) AND ("birth_month" <= 12))),
    CONSTRAINT "profiles_birth_year_is_plausible" CHECK ((("birth_year" >= 1900) AND ("birth_year" <= 2100))),
    CONSTRAINT "profiles_birth_year_while_live" CHECK ((("birth_year" IS NOT NULL) OR ("deleted_at" IS NOT NULL))),
    CONSTRAINT "profiles_birthday_month_check" CHECK ((("birthday_month" >= 1) AND ("birthday_month" <= 12))),
    CONSTRAINT "profiles_colour_mode_known" CHECK (("colour_mode" = ANY (ARRAY['light'::"text", 'night'::"text", 'device'::"text"]))),
    CONSTRAINT "profiles_country_code_is_alpha2" CHECK (("country_code" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "profiles_handle_length" CHECK ((("handle" IS NULL) OR (("char_length"("handle") >= 3) AND ("char_length"("handle") <= 30)))),
    CONSTRAINT "profiles_legal_region_shape" CHECK (("legal_region_code" ~ '^([A-Z0-9]{1,3})?$'::"text")),
    CONSTRAINT "profiles_locale_is_supported" CHECK (("locale" = ANY (ARRAY['ro'::"text", 'en'::"text"]))),
    CONSTRAINT "profiles_look_known" CHECK (("look" = ANY (ARRAY['lilac'::"text", 'sorbet'::"text", 'seaglass'::"text", 'pistachio'::"text", 'candy'::"text", 'tmc'::"text"]))),
    CONSTRAINT "profiles_pen_name_length" CHECK ((("pen_name" IS NULL) OR (("char_length"("pen_name") >= 1) AND ("char_length"("pen_name") <= 50)))),
    CONSTRAINT "profiles_signature_short" CHECK ((("signature" IS NULL) OR ((("char_length"("signature") >= 1) AND ("char_length"("signature") <= 300)) AND ("array_length"("string_to_array"("signature", '
'::"text"), 1) <= 3))))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'kind: identity; reportable: profile
One row per account; id is the user ID from Supabase Auth (architecture 1.6). Minimal in S1-E1-02.';



COMMENT ON COLUMN "public"."profiles"."birth_year" IS 'Year of birth from sign-up; never changes. Empty only once the account is deleted (S1-E2-02, S1-E2-08).';



COMMENT ON COLUMN "public"."profiles"."birth_month" IS 'Month of birth, only when the year leaves the age unclear at 13 or 16 (S1-E2-02).';



COMMENT ON COLUMN "public"."profiles"."locale" IS 'Interface language the person chose: ro (default for everyone, 17 Oct 2026) or en (S1-E1-04).';



COMMENT ON COLUMN "public"."profiles"."handle" IS 'The username, as typed: public; people find and mention each other by it (S1-E2-04).';



COMMENT ON COLUMN "public"."profiles"."handle_slug" IS 'The username''s web-address form (name_slug()); unique (S1-E2-04).';



COMMENT ON COLUMN "public"."profiles"."handle_skeleton" IS 'The username''s look-alike form (username_skeleton()); unique, so two names can''t look the same (S1-E2-04).';



COMMENT ON COLUMN "public"."profiles"."handle_changed_at" IS 'When the username last changed; null until the first change after setup (S1-E2-04, Q11).';



COMMENT ON COLUMN "public"."profiles"."pen_name" IS 'Optional pen name shown on the person''s content instead of the username; never a legal name is asked for (S1-E2-04).';



COMMENT ON COLUMN "public"."profiles"."pen_name_changed_at" IS 'When the pen name last changed; null until the first change after the first choice (S1-E2-04, Q11).';



COMMENT ON COLUMN "public"."profiles"."country_code" IS 'Country of the connection at sign-up, from Cloudflare, never asked and never the IP; null when unknown (S1-E2-10, Q20).';



COMMENT ON COLUMN "public"."profiles"."bio" IS 'What the person writes about themselves, plain text, at most 300 characters; public on the profile (S1-E5-05).';



COMMENT ON COLUMN "public"."profiles"."shows_online_status" IS 'The opt-in to show online status: off by default (Q50). While on, the people this person follows see a dot by their name (S1-E13-01).';



COMMENT ON COLUMN "public"."profiles"."birthday_month" IS 'Optional birthday month (1 to 12), never with a day or a year, so it never makes a full date of birth with birth_year (CLAUDE.md rule 5); only the owner reads it (S1-E2-12; QA-7, 6 Nov 2026).';



COMMENT ON COLUMN "public"."profiles"."avatar_picture_id" IS 'The profile picture people see: set only once its check passed or a moderator approved it (S1-E10-05, S1-E5-05).';



COMMENT ON COLUMN "public"."profiles"."marketing_email_opt_in" IS 'The adult''s own opt-in to marketing email; refused under 18 (S1-E7-02; Law 506/2004; Q50).';



COMMENT ON COLUMN "public"."profiles"."onboarded_at" IS 'When onboarding was finished or skipped (S1-E2-06); null shows "Set up your profile".';



COMMENT ON COLUMN "public"."profiles"."region_code" IS 'The county the person chose, if any (S1-E2-06); used only for the "Popular in your area" shelf.';



COMMENT ON COLUMN "public"."profiles"."adults_may_message" IS '16 and 17-year-olds only: adults may message them (S1-E9-03). Off by default.';



COMMENT ON COLUMN "public"."profiles"."teacher_badge_since" IS 'When the Teacher badge was granted; empty without one (S1-E2-11). Shown publicly only as "Teacher".';



COMMENT ON COLUMN "public"."profiles"."messages_from" IS 'Who may message this person; empty means the default for their age group (S1-E9-03). Never public.';



COMMENT ON COLUMN "public"."profiles"."profile_visible_to" IS 'Who sees the whole profile; null is the age group''s default: everyone for adults, people_i_follow under 18 (S1-E13-01).';



COMMENT ON COLUMN "public"."profiles"."library_visible_to" IS 'Who sees the person''s library shelves on their profile; only_me for everyone at first (S1-E13-01).';



COMMENT ON COLUMN "public"."profiles"."last_active_at" IS 'When the person last had the app open; kept only while shows_online_status is on, cleared when it goes off and nightly after a day (S1-E13-01).';



COMMENT ON COLUMN "public"."profiles"."signature" IS 'The forum signature: plain text, at most 300 characters and three lines (S1-E8-08).';



COMMENT ON COLUMN "public"."profiles"."signature_picture_id" IS 'The signature''s one still picture, shown once its check passed (S1-E8-08).';



COMMENT ON COLUMN "public"."profiles"."avatar_recipe" IS 'The drawn avatar the person built (ADMIN-2g); null means the initials avatar. Never a picture.';



COMMENT ON COLUMN "public"."profiles"."message_emails_on" IS 'Whether a new private message is emailed; empty means on (IDEAS-2 idea 6). Never public.';



COMMENT ON COLUMN "public"."profiles"."message_quiet_hours_on" IS 'Whether message emails wait for the end of quiet hours; empty means on under 18, off for adults (IDEAS-2 idea 6; Q50).';



COMMENT ON COLUMN "public"."profiles"."message_quiet_from" IS 'When message quiet hours start, Romanian time; empty means the default for the age group.';



COMMENT ON COLUMN "public"."profiles"."message_quiet_until" IS 'When message quiet hours end, Romanian time; empty means 07:00.';



COMMENT ON COLUMN "public"."profiles"."highest_rank_notified" IS 'The highest rank the writer was already told about; a rank reached again after a drop is not announced twice (IDEAS-3a).';



COMMENT ON COLUMN "public"."profiles"."suggest_me" IS 'The writer''s "Suggest me and my stories to other people" switch; null: not chosen, which is on for 18+ and off for under-18s (S1-E5-11; Robert, 6 Nov 2026).';



COMMENT ON COLUMN "public"."profiles"."legal_region_code" IS 'A region with its own age law where the person lives (Quebec, a US state), or ''''; not the county in region_code (MARKETS-1).';



COMMENT ON COLUMN "public"."profiles"."country_chosen_at" IS 'When the person said which country they live in; empty for accounts made before MARKETS-1, who are asked once.';



COMMENT ON COLUMN "public"."profiles"."consent_grace_until" IS 'Until when a member newly asked for a parent''s consent (the rules changed) keeps writing; 14 days (MARKETS-1, S1-E2-22).';



COMMENT ON COLUMN "public"."profiles"."founding_member_since" IS 'When a person joined while the waiting list was on: shown publicly only as "Founding member" (WAITLIST-1).';



COMMENT ON COLUMN "public"."profiles"."look" IS 'The member''s year-round theme (Settings › Appearance; bundle G2): lilac (default), sorbet, seaglass, pistachio, candy or tmc. Night mode looks the same with every theme.';



COMMENT ON COLUMN "public"."profiles"."colour_mode" IS 'Light, night or device (Match my device, the default) (Settings › Appearance and the footer; bundle G2).';



COMMENT ON COLUMN "public"."profiles"."seasonal_looks" IS 'Whether the seasonal looks switch on by themselves in their weeks (seasonal_look_dates); off unless the member turns it on (bundle G2).';



COMMENT ON COLUMN "public"."profiles"."appearance_saved_at" IS 'When the member last saved look, colour_mode and seasonal_looks; null until they first do, so devices keep their own choice (bundle G2).';



COMMENT ON COLUMN "public"."profiles"."shows_reader_level" IS 'Settings › Privacy › Your reading level: false keeps it hidden (the default for everyone), true shows it on the profile (G7a).';



CREATE OR REPLACE FUNCTION "public"."age_check_can_ask_manual"("person" "public"."profiles") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select latest.outcome = 'failed'
      and person.age_check_result is distinct from '18_or_over'
      and not exists (
        select 1 from public.manual_age_checks
        where manual_age_checks.user_id = person.id
          and (manual_age_checks.status = 'open' or manual_age_checks.created_at >= latest.created_at))
    from public.age_check_attempts as latest
    where latest.user_id = person.id
    order by latest.created_at desc
    limit 1), false);
$$;


ALTER FUNCTION "public"."age_check_can_ask_manual"("person" "public"."profiles") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_can_ask_manual"("person" "public"."profiles") IS 'Internal: whether a profile may ask for a manual age check now (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."age_check_can_start_for"("person" "public"."profiles") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select person.birth_year is not null
    and public.age_band_from_birth(
      person.birth_year, person.birth_month, 'pending',
      (now() at time zone 'Europe/Bucharest')::date) <> 'under_13'
    and person.age_check_result is distinct from '18_or_over'
    and not (person.age_check_result = '13_or_over' and public.age_check_threshold_for(person) = 13);
$$;


ALTER FUNCTION "public"."age_check_can_start_for"("person" "public"."profiles") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_can_start_for"("person" "public"."profiles") IS 'Internal: whether a profile may start a Yoti age check (S1-E2-08).';



CREATE OR REPLACE FUNCTION "public"."age_check_is_signed"("payload" "text", "signature" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  secret text;
begin
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'age_check_secret';
  if secret is null or secret = '' or signature is null then
    return false;
  end if;
  return encode(extensions.hmac(payload, secret, 'sha256'), 'hex') = lower(signature);
end;
$$;


ALTER FUNCTION "public"."age_check_is_signed"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_is_signed"("payload" "text", "signature" "text") IS 'Internal: checks an age check payload''s signature against the Vault secret age_check_secret (S1-E2-08).';



CREATE OR REPLACE FUNCTION "public"."age_check_numbers"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'passed', count(*) filter (where age_check_result in ('13_or_over', '18_or_over')),
    'failed', count(*) filter (where age_check_result = 'failed'),
    'not_finished', count(*) filter (where age_check_result = 'pending'),
    'appealed', (select count(*) from public.manual_age_checks))
  from public.profiles
  where deleted_at is null
    and not exists (select 1 from public.staff_roles where staff_roles.user_id = profiles.id);
$$;


ALTER FUNCTION "public"."age_check_numbers"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_numbers"() IS 'Internal: age check results as totals, with manual checks as "appealed" (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."age_check_result_value"("threshold" smallint, "passed" boolean, "current_result" "public"."age_check_result") RETURNS "public"."age_check_result"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when passed and threshold = 18 then '18_or_over'::public.age_check_result
    when passed then '13_or_over'::public.age_check_result
    when current_result in ('13_or_over', '18_or_over') then current_result
    else 'failed'::public.age_check_result
  end;
$$;


ALTER FUNCTION "public"."age_check_result_value"("threshold" smallint, "passed" boolean, "current_result" "public"."age_check_result") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_result_value"("threshold" smallint, "passed" boolean, "current_result" "public"."age_check_result") IS 'Internal: the age check result to store for a finished Yoti session (S1-E2-08).';



CREATE OR REPLACE FUNCTION "public"."age_check_threshold_for"("person" "public"."profiles") RETURNS smallint
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when public.age_band_from_birth(
      person.birth_year, person.birth_month, 'pending',
      (now() at time zone 'Europe/Bucharest')::date) = '18_plus'
    then 18::smallint
    else 13::smallint
  end;
$$;


ALTER FUNCTION "public"."age_check_threshold_for"("person" "public"."profiles") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_check_threshold_for"("person" "public"."profiles") IS 'Internal: the age line a new Yoti check tests for a profile, 13 or 18 (S1-E2-08).';



CREATE TABLE IF NOT EXISTS "public"."country_age_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "country_code" "text" NOT NULL,
    "region_code" "text" DEFAULT ''::"text" NOT NULL,
    "name" "text" NOT NULL,
    "region_name" "text" DEFAULT ''::"text" NOT NULL,
    "minimum_age" smallint DEFAULT 13 NOT NULL,
    "parental_consent_below" smallint DEFAULT 16 NOT NULL,
    "signup_blocked_below" smallint,
    "legal_basis" "text" DEFAULT ''::"text" NOT NULL,
    "source" "text" DEFAULT ''::"text" NOT NULL,
    "date_checked" "date" NOT NULL,
    "confidence" "text" DEFAULT 'medium'::"text" NOT NULL,
    "status" "text" DEFAULT 'to_verify'::"text" NOT NULL,
    "notes" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "country_age_rules_ages" CHECK (((("minimum_age" >= 13) AND ("minimum_age" <= 18)) AND (("parental_consent_below" >= 13) AND ("parental_consent_below" <= 18)) AND ("parental_consent_below" >= "minimum_age") AND (("signup_blocked_below" IS NULL) OR (("signup_blocked_below" >= 13) AND ("signup_blocked_below" <= 18))))),
    CONSTRAINT "country_age_rules_confidence_known" CHECK (("confidence" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text"]))),
    CONSTRAINT "country_age_rules_country_shape" CHECK (("country_code" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "country_age_rules_default_is_whole" CHECK ((("country_code" <> 'ZZ'::"text") OR ("region_code" = ''::"text"))),
    CONSTRAINT "country_age_rules_name_size" CHECK ((("char_length"("btrim"("name")) >= 1) AND ("char_length"("btrim"("name")) <= 100))),
    CONSTRAINT "country_age_rules_region_name" CHECK (((("region_code" = ''::"text") AND ("region_name" = ''::"text")) OR (("region_code" <> ''::"text") AND (("char_length"("btrim"("region_name")) >= 1) AND ("char_length"("btrim"("region_name")) <= 60))))),
    CONSTRAINT "country_age_rules_region_shape" CHECK (("region_code" ~ '^([A-Z0-9]{1,3})?$'::"text")),
    CONSTRAINT "country_age_rules_status_known" CHECK (("status" = ANY (ARRAY['to_verify'::"text", 'verified'::"text"]))),
    CONSTRAINT "country_age_rules_texts_size" CHECK ((("char_length"("legal_basis") <= 300) AND ("char_length"("source") <= 500) AND ("char_length"("notes") <= 1000)))
);


ALTER TABLE "public"."country_age_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."country_age_rules" IS 'kind: platform
Age rules by country or region: minimum age, parental consent below, sign-up blocked below, with source, date checked, confidence and status; "ZZ" is the default (MARKETS-1, S1-E2-21).';



CREATE OR REPLACE FUNCTION "public"."age_rule_for"("country_code" "text", "region_code" "text" DEFAULT ''::"text") RETURNS "public"."country_age_rules"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select rules.*
  from public.country_age_rules as rules
  where (rules.country_code = upper(coalesce(age_rule_for.country_code, ''))
         and rules.region_code in ('', upper(coalesce(age_rule_for.region_code, ''))))
     or rules.country_code = 'ZZ'
  -- The most specific row first: the region, then the country, then the default.
  order by (rules.country_code = 'ZZ'), (rules.region_code = '')
  limit 1;
$$;


ALTER FUNCTION "public"."age_rule_for"("country_code" "text", "region_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_rule_for"("country_code" "text", "region_code" "text") IS 'The age rule for a country and region: the region''s row, else the country''s, else the default "ZZ" (MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."age_rule_needs_review"("rule" "public"."country_age_rules") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select rule.confidence = 'low' or rule.date_checked < (now() - interval '6 months')::date;
$$;


ALTER FUNCTION "public"."age_rule_needs_review"("rule" "public"."country_age_rules") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_rule_needs_review"("rule" "public"."country_age_rules") IS 'True when an age rule has low confidence or was checked more than six months ago (MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."age_rule_outcome"("birth_year" integer, "birth_month" integer, "country_code" "text", "region_code" "text" DEFAULT ''::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rule public.country_age_rules := public.age_rule_for(country_code, region_code);
  age integer := public.youngest_age(birth_year, birth_month, (now() at time zone 'Europe/Bucharest')::date);
begin
  if age is null then
    return 'unknown';
  end if;
  if rule.signup_blocked_below is not null and age < rule.signup_blocked_below then
    return 'blocked';
  end if;
  if age < rule.minimum_age then
    return 'under_minimum';
  end if;
  if age < rule.parental_consent_below then
    return 'consent_needed';
  end if;
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."age_rule_outcome"("birth_year" integer, "birth_month" integer, "country_code" "text", "region_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."age_rule_outcome"("birth_year" integer, "birth_month" integer, "country_code" "text", "region_code" "text") IS 'What a country''s age rule means for someone: blocked, under_minimum, consent_needed or ok (MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."ages_allow_messages"("first_person" "public"."profiles", "second_person" "public"."profiles") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  first_group text := public.message_age_group(first_person);
  second_group text := public.message_age_group(second_person);
begin
  -- Step 1: two adults, or two people under 18, follow the normal rules.
  if (first_group = 'adult') = (second_group = 'adult') then
    return true;
  end if;
  -- Step 2: an under-16 and an adult: never, and no setting changes it.
  if first_group = 'child' or second_group = 'child' then
    return false;
  end if;
  -- Step 3: a 16 or 17-year-old and an adult: only with the teen's own switch on.
  if first_group = 'teen' then
    return first_person.adults_may_message;
  end if;
  return second_person.adults_may_message;
end;
$$;


ALTER FUNCTION "public"."ages_allow_messages"("first_person" "public"."profiles", "second_person" "public"."profiles") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ages_allow_messages"("first_person" "public"."profiles", "second_person" "public"."profiles") IS 'Internal: whether two people''s ages allow messages either way (S1-E9-03; Q6, Q13).';



CREATE OR REPLACE FUNCTION "public"."announce_writer_rank"("person_id" "uuid", "reached" "public"."writer_rank") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: remember the new highest rank, only when it is higher than before (enum order is
  -- the ladder's order, lowest first). No row changes means nothing new to say.
  update public.profiles set highest_rank_notified = reached
  where profiles.id = person_id
    and (profiles.highest_rank_notified is null or profiles.highest_rank_notified < reached);
  if not found or reached = 'new_writer' then
    return;
  end if;
  -- Step 2: one quiet in-app row with no actor; it can be switched off like other story news.
  insert into public.notifications (user_id, kind, actor_user_ids, actor_count, writer_rank, is_required)
  values (person_id, 'rank_reached', '{}'::uuid[], 0, reached, false);
end;
$$;


