CREATE OR REPLACE FUNCTION "public"."answer_message_request"("sender_handle" "text", "should_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_messaging_caller();
  other public.profiles := public.messaging_partner(sender_handle);
  chat public.conversations;
begin
  -- Step 1: a request from that person to the caller.
  if other.id is not null then
    chat := public.conversation_between(caller_id, other.id);
  end if;
  if chat.id is null or chat.status <> 'request' or chat.recipient_user_id <> caller_id then
    raise exception 'There is no message request from that person.' using errcode = 'no_data_found';
  end if;
  -- Step 2: accepting asks the lasting rules again, so a block since then still counts.
  if should_accept and not public.may_keep_writing(caller_id, other.id) then
    raise exception 'This person isn''t taking messages right now.' using errcode = 'insufficient_privilege', hint = 'not_taking';
  end if;
  -- Step 3: the answer; reading it counts as reading the request.
  update public.conversations
    set status = case when should_accept then 'accepted'::public.conversation_status else 'declined'::public.conversation_status end,
        accepted_at = case when should_accept then now() end,
        said_no_thanks_at = null
    where conversations.id = chat.id returning * into chat;
  update public.conversation_members set last_read_at = now()
    where conversation_members.conversation_id = chat.id and conversation_members.user_id = caller_id;
  return jsonb_build_object('status', chat.status);
end;
$$;


ALTER FUNCTION "public"."answer_message_request"("sender_handle" "text", "should_accept" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."answer_message_request"("sender_handle" "text", "should_accept" boolean) IS 'The recipient accepts or deletes a message request; a deleted one is never told (S1-E9-01).';



CREATE OR REPLACE FUNCTION "public"."answer_parental_consent"("token" "text", "decision" "text", "page_language" "text", "signature" "text", "allow_spotlight" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.parental_consents;
  answer jsonb;
  -- The box counts only with a yes (GDPR art. 7: a separate, specific consent).
  wants_spotlight boolean := coalesce(allow_spotlight, false) and decision = 'agree';
  signed_message text;
begin
  -- Step 1: the request came through our server; a ticked box is part of what it signed.
  signed_message := 'answer|' || encode(extensions.digest(coalesce(token, ''), 'sha256'), 'hex')
    || '|' || decision;
  if wants_spotlight then
    signed_message := signed_message || '|spotlight';
  end if;
  if not public.parental_consent_is_signed(signed_message, signature) then
    raise exception 'This answer wasn''t signed by our server.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a live request; agree and refuse need a waiting one, withdraw an agreed one.
  request := public.parental_consent_by_token(token);
  if request.id is null or request.status = 'replaced'
     or exists (select 1 from public.profiles where id = request.user_id and deleted_at is not null) then
    return jsonb_build_object('outcome', 'gone');
  end if;
  if (decision in ('agree', 'refuse') and request.status <> 'waiting')
     or (decision = 'withdraw' and request.status <> 'agreed')
     or decision not in ('agree', 'refuse', 'withdraw') then
    return jsonb_build_object('outcome', 'already_answered', 'status', request.status);
  end if;
  -- Step 3: who to write to, read before a refusal erases the writer's address.
  select jsonb_build_object('outcome', 'ok', 'decision', decision, 'writer_email', users.email,
      'writer_language', coalesce(profiles.locale, 'ro'), 'handle', profiles.handle,
      'parent_email', request.parent_email, 'parent_language', request.language,
      'allow_spotlight', wants_spotlight)
    into answer
  from public.profiles join auth.users on users.id = profiles.id
  where profiles.id = request.user_id;
  -- Step 4: the answer itself.
  if decision = 'agree' then
    perform public.parental_consent_agree(request, coalesce(nullif(page_language, ''), request.language));
    if wants_spotlight then
      update public.parental_consents
      set spotlight_agreed_at = now(), spotlight_withdrawn_at = null
      where id = request.id;
    end if;
  elsif decision = 'refuse' then
    update public.parental_consents set status = 'refused', decided_at = now() where id = request.id;
    perform public.erase_unchecked_account(request.user_id);
  else
    update public.parental_consents
    set status = 'withdrawn', withdrawn_at = now(), withdrawn_by = 'parent',
        spotlight_withdrawn_at = case when spotlight_agreed_at is not null then now() end
    where id = request.id;
    perform public.notify(request.user_id, 'parental_consent_withdrawn', null, '{}'::jsonb);
  end if;
  return answer;
end;
$$;


ALTER FUNCTION "public"."answer_parental_consent"("token" "text", "decision" "text", "page_language" "text", "signature" "text", "allow_spotlight" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."answer_parental_consent"("token" "text", "decision" "text", "page_language" "text", "signature" "text", "allow_spotlight" boolean) IS 'A parent''s or guardian''s answer from the consent link, with the optional suggestions box, signed by our server (S1-E2-03, S1-E2-03b).';



CREATE OR REPLACE FUNCTION "public"."answer_report_detail_request"("target_request_id" "uuid", "answer_text" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: an answer within the length.
  if btrim(coalesce(answer_text, '')) = '' or char_length(btrim(answer_text)) > 4000 then
    raise exception 'Write an answer of at most 4,000 characters.' using errcode = 'check_violation';
  end if;
  -- Step 2: only the caller's own question, and only once.
  update public.report_detail_requests
    set answer = btrim(answer_text), answered_at = now()
    where id = target_request_id and user_id = (select auth.uid()) and answered_at is null;
  if not found then
    raise exception 'There is no open question like that.' using errcode = 'no_data_found';
  end if;
end;
$$;


