COMMENT ON FUNCTION "public"."answer_report_detail_request"("target_request_id" "uuid", "answer_text" "text") IS 'A reporter answers a moderator''s question about their report, once (S1-E10-08).';



CREATE OR REPLACE FUNCTION "public"."answer_space_handover"("slug" "text", "accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_space_starter();
  space public.spaces := public.space_for_handover_answer(answer_space_handover.slug);
  every_power constant public.space_power[] := enum_range(null::public.space_power);
begin
  -- Step 1: declining clears the offer and says so in the log.
  if not coalesce(accept, false) then
    update public.spaces set handover_to_user_id = null, handover_offered_at = null where spaces.id = space.id;
    perform public.log_space_action(space, 'handover_declined', space.user_id, null, null, '{}'::jsonb);
    return jsonb_build_object('outcome', 'declined');
  end if;
  -- Step 2: the old owner becomes a moderator with every power, then the caller the owner.
  update public.space_members set role = 'moderator', powers = every_power
  where space_members.space_id = space.id and space_members.user_id = space.user_id;
  update public.space_members set role = 'owner', powers = '{}'
  where space_members.space_id = space.id and space_members.user_id = caller_id;
  -- Step 3: the owner column, through the one exception refuse_space_owner_change() allows.
  perform set_config('app.space_handover', space.id::text, true);
  update public.spaces set user_id = caller_id, handover_to_user_id = null, handover_offered_at = null
  where spaces.id = space.id;
  perform set_config('app.space_handover', '', true);
  -- Step 4: the log: the new owner accepted the space from the old one (criterion 2).
  perform public.log_space_action(space, 'handover_accepted', space.user_id, null, null,
    jsonb_build_object('previous_owner_powers', to_jsonb(every_power)));
  return jsonb_build_object('outcome', 'accepted');
end;
$$;


ALTER FUNCTION "public"."answer_space_handover"("slug" "text", "accept" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."answer_space_handover"("slug" "text", "accept" boolean) IS 'The moderator a space was offered to accepts (becoming its owner) or declines; logged (IDEA-20261102-7).';



CREATE OR REPLACE FUNCTION "public"."answer_spotlight_consent"("token" "text", "decision" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  consent public.parental_consents := public.spotlight_consent_by_token(token);
  is_agreed boolean := consent.spotlight_agreed_at is not null and consent.spotlight_withdrawn_at is null;
begin
  -- Step 1: the answer came through our server.
  if not public.parental_consent_is_signed('spotlight-answer|'
      || encode(extensions.digest(coalesce(token, ''), 'sha256'), 'hex') || '|' || decision, signature) then
    raise exception 'This answer wasn''t signed by our server.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a live link, and an answer that changes something.
  if consent.id is null or exists (select 1 from public.profiles
                                   where id = consent.user_id and deleted_at is not null) then
    return jsonb_build_object('outcome', 'gone');
  end if;
  if decision not in ('agree', 'withdraw') or (decision = 'agree') = is_agreed then
    return jsonb_build_object('outcome', 'already_answered');
  end if;
  -- Step 3: the answer, then the writer is told.
  if decision = 'agree' then
    update public.parental_consents set spotlight_agreed_at = now(), spotlight_withdrawn_at = null
    where id = consent.id;
    perform public.notify(consent.user_id, 'spotlight_consent_agreed', null, '{}'::jsonb);
  else
    update public.parental_consents set spotlight_withdrawn_at = now() where id = consent.id;
    perform public.notify(consent.user_id, 'spotlight_consent_withdrawn', null, '{}'::jsonb);
  end if;
  return jsonb_build_object('outcome', 'ok', 'decision', decision, 'parent_email', consent.parent_email,
    'language', consent.language, 'handle', (select handle from public.profiles where id = consent.user_id));
end;
$$;


