CREATE OR REPLACE FUNCTION "public"."apply_support_change"("ticket" "public"."support_tickets", "field" "text", "before_value" "jsonb", "after_value" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
