    CONSTRAINT "public_notices_authority_length" CHECK ((("authority_name" IS NULL) OR ("char_length"("authority_name") <= 200))),
    CONSTRAINT "public_notices_copy_source_lengths" CHECK (((COALESCE("char_length"("copy_source_title"), 0) <= 300) AND (COALESCE("char_length"("copy_source_author"), 0) <= 200) AND (COALESCE("char_length"("copy_source_reference"), 0) <= 2000) AND (COALESCE("char_length"("copy_source_passage"), 0) <= 4000))),
    CONSTRAINT "public_notices_copy_source_only_for_copies" CHECK ((("reason" = 'copied_published_work'::"public"."report_reason") OR (("copy_source_title" IS NULL) AND ("copy_source_author" IS NULL) AND ("copy_source_reference" IS NULL) AND ("copy_source_passage" IS NULL)))),
    CONSTRAINT "public_notices_email_shape" CHECK ((("notifier_email" IS NULL) OR (("char_length"("notifier_email") <= 254) AND ("notifier_email" ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::"text")))),
    CONSTRAINT "public_notices_explanation_length" CHECK ((("char_length"("explanation") >= 1) AND ("char_length"("explanation") <= 2000))),
    CONSTRAINT "public_notices_good_faith" CHECK ((("kind" = 'removal_order'::"text") OR "good_faith_confirmed" OR ("support_ticket_number" IS NOT NULL))),
    CONSTRAINT "public_notices_item_fields_go_together" CHECK (((("item_type" IS NULL) = ("item_id" IS NULL)) AND (("item_id" IS NULL) = ("owner_user_id" IS NULL)))),
    CONSTRAINT "public_notices_kind_is_known" CHECK (("kind" = ANY (ARRAY['notice'::"text", 'removal_order'::"text"]))),
    CONSTRAINT "public_notices_language_is_known" CHECK (("language" = ANY (ARRAY['ro'::"text", 'en'::"text"]))),
    CONSTRAINT "public_notices_name_length" CHECK ((("notifier_name" IS NULL) OR ("char_length"("notifier_name") <= 120))),
    CONSTRAINT "public_notices_notice_has_reason" CHECK ((("kind" = 'notice'::"text") = ("reason" IS NOT NULL))),
    CONSTRAINT "public_notices_notifier_given" CHECK ((("kind" = 'removal_order'::"text") OR ("reason" = 'child_sexual_content'::"public"."report_reason") OR ("support_ticket_number" IS NOT NULL) OR (("notifier_name" IS NOT NULL) AND ("notifier_email" IS NOT NULL)))),
    CONSTRAINT "public_notices_order_fields" CHECK ((("kind" = 'notice'::"text") OR (("authority_name" IS NOT NULL) AND ("notifier_email" IS NOT NULL)))),
    CONSTRAINT "public_notices_order_reference_length" CHECK ((("order_reference" IS NULL) OR ("char_length"("order_reference") <= 120))),
    CONSTRAINT "public_notices_url_length" CHECK ((("char_length"("content_url") >= 1) AND ("char_length"("content_url") <= 2000)))
);


