    CONSTRAINT "reports_copy_fields_only_for_copies" CHECK ((("reason" = 'copied_published_work'::"public"."report_reason") OR (("copy_source_title" IS NULL) AND ("copy_source_author" IS NULL) AND ("copy_source_reference" IS NULL) AND ("copy_source_passage" IS NULL) AND ("reported_passage" IS NULL)))),
