CREATE OR REPLACE FUNCTION "public"."attach_report_to_case"("new_report" "public"."reports") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reason_tier public.report_reason_tiers;
  open_case public.cases;
  new_deadline timestamptz;
begin
  select * into reason_tier from public.report_reason_tiers where reason = new_report.reason;
  select * into open_case from public.cases
    where item_type = new_report.item_type and item_id = new_report.item_id and status = 'open'
    for update;
  if open_case.id is null then
    -- Step 1: a new case, referenced like its first report.
    insert into public.cases (reference, user_id, item_type, item_id, source, tier, received_at,
                              deadline_at, top_reason, report_count, reporter_under_18, is_safeguarding)
    values (new_report.reference, new_report.reported_user_id, new_report.item_type, new_report.item_id,
            'report', reason_tier.tier, new_report.created_at,
            new_report.created_at + make_interval(hours => public.tier_hours(reason_tier.tier)),
            new_report.reason, 1, new_report.reporter_age_band in ('under_13', '13_to_15', '16_to_17'),
            reason_tier.is_safeguarding)
    returning * into open_case;
    return open_case.id;
  end if;
  -- Step 2: join the open case; the more urgent tier and the earliest deadline win.
  new_deadline := open_case.received_at + make_interval(hours => public.tier_hours(reason_tier.tier));
  update public.cases set
    report_count = report_count + 1,
    reporter_under_18 = reporter_under_18 or new_report.reporter_age_band in ('under_13', '13_to_15', '16_to_17'),
    is_safeguarding = is_safeguarding or reason_tier.is_safeguarding,
    tier = case when public.tier_rank(reason_tier.tier) < public.tier_rank(tier) then reason_tier.tier else tier end,
    top_reason = case when public.tier_rank(reason_tier.tier) < public.tier_rank(tier) then new_report.reason else top_reason end,
    deadline_at = least(deadline_at, new_deadline)
  where id = open_case.id;
  return open_case.id;
end;
$$;


ALTER FUNCTION "public"."attach_report_to_case"("new_report" "public"."reports") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_report_to_case"("new_report" "public"."reports") IS 'Internal: opens or joins the item''s open case for a new report (S1-E10-03a).';



CREATE OR REPLACE FUNCTION "public"."audit_log_rows"("action_prefix" "text", "staff_handle" "text", "target_user_id" "uuid", "from_date" "date", "to_date" "date", "row_limit" integer, "row_offset" integer) RETURNS SETOF "public"."audit_log_row"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    log.id,
    log.created_at,
    actor.handle,
    log.action,
    log.target_type,
    log.target_id,
    target.handle,
    left(log.target_user_id::text, 8),
    log.reason,
    log.before_values,
    log.after_values,
    log.actor,
    left(log.user_id::text, 8)
  from public.audit_log as log
  -- A left join, because a system row has nobody behind it.
  left join public.profiles as actor on actor.id = log.user_id
  left join public.profiles as target on target.id = log.target_user_id
  where (action_prefix is null or log.action like action_prefix || '%')
    and (staff_handle is null
         or actor.handle_skeleton = public.username_skeleton(btrim(staff_handle, ' @')))
    and (target_user_id is null or log.target_user_id = target_user_id)
    and (from_date is null or log.created_at >= from_date::timestamptz)
    and (to_date is null or log.created_at < (to_date + 1)::timestamptz)
  order by log.created_at desc, log.id desc
  limit row_limit offset row_offset;
$$;


ALTER FUNCTION "public"."audit_log_rows"("action_prefix" "text", "staff_handle" "text", "target_user_id" "uuid", "from_date" "date", "to_date" "date", "row_limit" integer, "row_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_log_rows"("action_prefix" "text", "staff_handle" "text", "target_user_id" "uuid", "from_date" "date", "to_date" "date", "row_limit" integer, "row_offset" integer) IS 'Internal: the audit log search, newest first, with usernames instead of IDs and system rows (S1-E11-01, S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."auto_solve_support_tickets"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wait_days integer := greatest(coalesce((public.setting_value('support_auto_solve_days'))::integer, 7), 1);
  ticket public.support_tickets;
  solved_count integer := 0;
begin
  for ticket in
    select * from public.support_tickets
    where status = 'pending_on_user' and last_message_at < now() - make_interval(days => wait_days)
    for update skip locked
  loop
    update public.support_tickets set status = 'solved', solved_at = now() where id = ticket.id;
    -- No one is signed in here, so the history says "the system".
    insert into public.support_ticket_events (ticket_id, actor_user_id, change, value_before, value_after)
    values (ticket.id, null, 'status', to_jsonb('pending_on_user'::text), to_jsonb('solved'::text));
    insert into public.support_ticket_emails (ticket_id, kind) values (ticket.id, 'auto_solved');
    solved_count := solved_count + 1;
  end loop;
  return solved_count;
end;
$$;


