CREATE OR REPLACE FUNCTION "public"."banned_email_hash"("email" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  secret text;
  normalised text := public.normalised_email(email);
begin
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'banned_email_secret';
  if secret is null or secret = '' or normalised is null then
    return null;
  end if;
  return encode(extensions.hmac(normalised, secret, 'sha256'), 'hex');
end;
$$;


ALTER FUNCTION "public"."banned_email_hash"("email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."banned_email_hash"("email" "text") IS 'Internal: HMAC-SHA256 of the normalised email with the Vault secret banned_email_secret, or null without the secret (S1-E10-06, Q8; normalised since ADMIN-2 part f1).';



CREATE OR REPLACE FUNCTION "public"."begin_age_check"("yoti_session_id" "text", "threshold" smallint, "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person public.profiles;
begin
  -- Step 1: signed in, and the payload signed by our server.
  if (select auth.uid()) is null
     or not public.age_check_is_signed(
       'begin|' || begin_age_check.yoti_session_id || '|' || begin_age_check.threshold, signature) then
    raise exception 'Only our server can start an age check.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the person may start one, for the line their year of birth gives.
  select * into person from public.profiles
  where profiles.id = (select auth.uid()) and profiles.deleted_at is null;
  if not found or not public.age_check_can_start_for(person) then
    return jsonb_build_object('outcome', 'not_needed');
  end if;
  if begin_age_check.threshold <> public.age_check_threshold_for(person) then
    raise exception 'Wrong age line.' using errcode = 'check_violation', hint = 'wrong_threshold';
  end if;
  -- Step 3: one open check at a time; an older session is forgotten (criterion 11).
  delete from public.age_check_sessions where age_check_sessions.user_id = person.id;
  insert into public.age_check_sessions (user_id, yoti_session_id, threshold, expires_at)
  values (person.id, begin_age_check.yoti_session_id, begin_age_check.threshold, now() + interval '30 minutes');
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."begin_age_check"("yoti_session_id" "text", "threshold" smallint, "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_age_check"("yoti_session_id" "text", "threshold" smallint, "signature" "text") IS 'Our server links a new Yoti age check session to the caller, replacing any older one (S1-E2-08).';



CREATE OR REPLACE FUNCTION "public"."begin_parental_consent"("parent_email" "text", "language" "text", "token_hash" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me uuid := (select auth.uid());
  wanted_email text := lower(trim(begin_parental_consent.parent_email));
  waiting public.parental_consents;
begin
  -- Step 1: signed in, and the request came from our server.
  if me is null or not public.parental_consent_is_signed(
      'consent|' || me || '|' || wanted_email || '|' || begin_parental_consent.language || '|'
        || begin_parental_consent.token_hash, signature) then
    raise exception 'This request wasn''t signed by our server.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: only while consent is needed and nobody withdrew it.
  if not coalesce((public.my_parental_consent() ->> 'can_send')::boolean, false) then
    return jsonb_build_object('outcome', 'not_needed');
  end if;
  -- Step 3: never the writer's own address, and no flood of emails to a parent.
  if exists (select 1 from auth.users where users.id = me and lower(users.email) = wanted_email) then
    raise exception 'That is your own email.' using errcode = 'check_violation', hint = 'own_email';
  end if;
  select * into waiting from public.parental_consents
  where parental_consents.user_id = me and parental_consents.status = 'waiting' for update;
  if waiting.created_at > now() - interval '1 minute' then
    raise exception 'Wait a minute before sending again.' using errcode = 'check_violation', hint = 'too_soon';
  end if;
  -- Step 4: the old link stops working, the new one counts.
  update public.parental_consents set status = 'replaced' where id = waiting.id;
  insert into public.parental_consents (user_id, parent_email, language, token_hash)
  values (me, wanted_email, begin_parental_consent.language, lower(begin_parental_consent.token_hash));
  return jsonb_build_object(
    'outcome', 'ok',
    'handle', (select handle from public.profiles where id = me),
    'deadline', public.parental_consent_deadline(me));
end;
$$;


ALTER FUNCTION "public"."begin_parental_consent"("parent_email" "text", "language" "text", "token_hash" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_parental_consent"("parent_email" "text", "language" "text", "token_hash" "text", "signature" "text") IS 'Stores a signed request to a parent or guardian for the signed-in writer (S1-E2-03).';



CREATE OR REPLACE FUNCTION "public"."begin_spotlight_request"("token_hash" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me uuid := (select auth.uid());
  consent public.parental_consents;
begin
  -- Step 1: signed in, and the link came from our server.
  if me is null or not public.parental_consent_is_signed(
      'spotlight|' || me || '|' || begin_spotlight_request.token_hash, signature) then
    raise exception 'This request wasn''t signed by our server.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: only for a 13 to 15-year-old with an agreed consent, the switch on, no yes yet.
  select * into consent from public.parental_consents
  where parental_consents.user_id = me and parental_consents.status = 'agreed' for update;
  if consent.id is null or public.age_band_of(me) <> '13_to_15'
     or not coalesce(public.suggests_me(me), false) or public.has_spotlight_consent(me) then
    return jsonb_build_object('outcome', 'not_needed');
  end if;
  -- Step 3: no flood of emails to a parent.
  if consent.spotlight_requested_at > now() - interval '1 hour' then
    raise exception 'Wait an hour before asking again.' using errcode = 'check_violation', hint = 'too_soon';
  end if;
  -- Step 4: the new link counts; an older one stops working.
  update public.parental_consents
  set spotlight_token_hash = lower(begin_spotlight_request.token_hash), spotlight_requested_at = now()
  where id = consent.id;
  return jsonb_build_object('outcome', 'ok', 'parent_email', consent.parent_email,
    'language', consent.language, 'handle', (select handle from public.profiles where id = me));
end;
$$;


ALTER FUNCTION "public"."begin_spotlight_request"("token_hash" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_spotlight_request"("token_hash" "text", "signature" "text") IS 'The server stores the link it emails a parent asking whether their child may be suggested to other people (S1-E2-03b).';



CREATE OR REPLACE FUNCTION "public"."begin_teacher_email_check"("school_domain" "text", "token_hash" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person public.profiles;
  wanted_domain text := lower(btrim(coalesce(begin_teacher_email_check.school_domain, '')));
  expires_at timestamptz;
begin
  -- Step 1: signed in, and the request came from our server.
  person := public.caller_profile_for_teacher_check();
  if not public.teacher_check_is_signed(
      'teacher|' || (select auth.uid()) || '|' || wanted_domain || '|' || lower(begin_teacher_email_check.token_hash),
      signature) then
    raise exception 'This request wasn''t signed by our server.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: never a personal address (board 2.5, step 3).
  if public.is_personal_email_domain(wanted_domain) then
    raise exception 'Use your school address, or upload proof instead.'
      using errcode = 'check_violation', hint = 'personal_address';
  end if;
  -- Step 3: only for an adult who may write and has no badge or request waiting.
  if not public.teacher_check_can_ask(person) then
    raise exception 'A Teacher badge can''t be asked for now.' using errcode = 'check_violation', hint = 'not_available';
  end if;
  -- Step 4: no flood of emails to a school address.
  if exists (select 1 from public.teacher_checks
             where teacher_checks.user_id = person.id and teacher_checks.status = 'link_sent'
               and teacher_checks.created_at > now() - interval '1 minute') then
    raise exception 'Wait a minute before sending again.' using errcode = 'check_violation', hint = 'too_soon';
  end if;
  -- Step 5: the old link stops working, the new one counts for teacher_link_hours.
  perform public.replace_sent_teacher_link(person.id);
  expires_at := now() + make_interval(hours => coalesce((public.setting_value('teacher_link_hours'))::integer, 48));
  insert into public.teacher_checks (user_id, way, school_domain, token_hash, link_expires_at, status)
  values (person.id, 'school_email', wanted_domain, lower(begin_teacher_email_check.token_hash), expires_at, 'link_sent');
  return jsonb_build_object('outcome', 'ok', 'link_expires_at', expires_at);
end;
$$;


ALTER FUNCTION "public"."begin_teacher_email_check"("school_domain" "text", "token_hash" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_teacher_email_check"("school_domain" "text", "token_hash" "text", "signature" "text") IS 'Stores a signed school email request for the Teacher badge; only the domain is kept (S1-E2-11).';



