COMMENT ON FUNCTION "public"."case_item_content"("target" "public"."cases") IS 'Internal: the full content of a case''s item, for the evidence pack (S1-E10-10, GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."case_matches_queue_filters"("target" "public"."cases", "reported_handle" "text", "reason_filter" "public"."report_reason", "claimed_filter" "text", "search_text" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (reason_filter is null or target.top_reason = reason_filter
          or exists (select 1 from public.reports where reports.case_id = target.id and reports.reason = reason_filter))
    and (claimed_filter is null
         or (claimed_filter = 'mine' and target.claimed_by_user_id = (select auth.uid()))
         or (claimed_filter = 'anyone' and target.claimed_by_user_id is not null)
         or (claimed_filter = 'nobody' and target.claimed_by_user_id is null))
    and (nullif(btrim(search_text), '') is null
         or lower(target.reference) = lower(btrim(search_text))
         or lower(reported_handle) = lower(btrim(btrim(search_text), '@'))
         or exists (select 1 from public.reports where reports.case_id = target.id
                    and lower(reports.reference) = lower(btrim(search_text))));
$$;


ALTER FUNCTION "public"."case_matches_queue_filters"("target" "public"."cases", "reported_handle" "text", "reason_filter" "public"."report_reason", "claimed_filter" "text", "search_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."case_matches_queue_filters"("target" "public"."cases", "reported_handle" "text", "reason_filter" "public"."report_reason", "claimed_filter" "text", "search_text" "text") IS 'Internal: the queue''s reason, claimed and search filters (S1-E10-03b).';



CREATE OR REPLACE FUNCTION "public"."cases_by_tier"("window_days" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with recent as (
    select cases.tier,
      cases.status = 'decided' and cases.decided_at <= cases.deadline_at as in_time,
      cases.status = 'decided' or cases.deadline_at < now() as measured
    from public.cases
    where cases.received_at >= now() - make_interval(days => window_days)
  )
  select jsonb_agg(jsonb_build_object(
      'tier', tiers.tier,
      'hours', public.tier_hours(tiers.tier),
      'cases', (select count(*) from recent where recent.tier = tiers.tier),
      'measured', (select count(*) from recent where recent.tier = tiers.tier and recent.measured),
      'in_time', (select count(*) from recent where recent.tier = tiers.tier and recent.in_time))
    order by public.tier_rank(tiers.tier))
  from unnest(enum_range(null::public.case_tier)) as tiers (tier);
$$;


ALTER FUNCTION "public"."cases_by_tier"("window_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cases_by_tier"("window_days" integer) IS 'Internal: recent moderation cases by tier with the share handled within the time limit (S1-E11-04).';



