COMMENT ON COLUMN "public"."spaces"."school_name" IS 'kind: setting. The school a class space belongs to, printed on class certificates (S1-E8-11, S1-E8-12).';



COMMENT ON COLUMN "public"."spaces"."archived_at" IS 'kind: setting. When a class space was archived: locked for good, still readable by members (S1-E8-11, Q69).';



COMMENT ON COLUMN "public"."spaces"."welcome_note" IS 'What each new member sees once at the top of the space, written by the owner; null for none (IDEA-20261102-6). The 500-character limit is a setting, checked on save.';



COMMENT ON COLUMN "public"."spaces"."handover_to_user_id" IS 'The moderator the owner offered the space to, while the offer is open; null for none (IDEA-20261102-7).';



COMMENT ON COLUMN "public"."spaces"."handover_offered_at" IS 'When the owner made the open offer; null for none (IDEA-20261102-7).';



COMMENT ON COLUMN "public"."spaces"."logo_picture_id" IS 'The uploaded logo (G8b), shown once its check passed; null when the space has no logo.';



COMMENT ON CONSTRAINT "spaces_banner_is_offered" ON "public"."spaces" IS 'A space uses one of the fourteen banner colours the boards offer; night and gold are retired (G8b).';



CREATE OR REPLACE FUNCTION "public"."certificate_student_id"("space" "public"."spaces", "typed_handle" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  student_id uuid;
begin
  select space_members.user_id into student_id
  from public.space_members join public.profiles on profiles.id = space_members.user_id
  where space_members.space_id = space.id and space_members.status = 'active'
    and space_members.role <> 'owner'
    and profiles.handle = ltrim(lower(btrim(coalesce(typed_handle, ''))), '@');
  if student_id is null then
    raise exception 'Only the class''s students get its certificates.' using errcode = 'check_violation', hint = 'certificate:not_member';
  end if;
  return student_id;
end;
$$;


