CREATE TABLE IF NOT EXISTS "public"."story_characters" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "story_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "role" "text" DEFAULT 'supporting'::"text" NOT NULL,
    "sheet" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "custom_values" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "first_appearance_chapter_id" "uuid",
    "picture_id" "uuid",
    "picture_alt" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_private" boolean DEFAULT false NOT NULL,
    "show_from_chapter_id" "uuid",
    "public_sheet_parts" "text"[] DEFAULT ARRAY['basics'::"text", 'look_and_voice'::"text", 'in_the_story'::"text"] NOT NULL,
    "map_x" smallint,
    "map_y" smallint,
    "gender" "text",
    CONSTRAINT "story_characters_custom_values_is_object" CHECK (("jsonb_typeof"("custom_values") = 'object'::"text")),
    CONSTRAINT "story_characters_gender_known" CHECK ((("gender" IS NULL) OR ("gender" = ANY (ARRAY['she'::"text", 'he'::"text", 'they'::"text"])))),
    CONSTRAINT "story_characters_map_place" CHECK (((("map_x" IS NULL) AND ("map_y" IS NULL)) OR ((("map_x" >= 0) AND ("map_x" <= 4000)) AND (("map_y" >= 0) AND ("map_y" <= 4000))))),
    CONSTRAINT "story_characters_name_length" CHECK ((("char_length"("btrim"("name")) >= 1) AND ("char_length"("btrim"("name")) <= 120))),
    CONSTRAINT "story_characters_picture_alt_length" CHECK (("char_length"("picture_alt") <= 300)),
    CONSTRAINT "story_characters_public_sheet_parts_known" CHECK (("cardinality"("public_sheet_parts") <= 200)),
    CONSTRAINT "story_characters_role_known" CHECK (("role" = ANY (ARRAY['protagonist'::"text", 'deuteragonist'::"text", 'antagonist'::"text", 'supporting'::"text", 'minor'::"text", 'mentioned'::"text"]))),
    CONSTRAINT "story_characters_sheet_is_object" CHECK (("jsonb_typeof"("sheet") = 'object'::"text"))
);


ALTER TABLE "public"."story_characters" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_characters" IS 'kind: user_content; reportable: atlas_item
The characters of one story''s plan in Story Atlas (S1-E17-08 to S1-E17-11): role, the sheet''s text, the writer''s own fields, the first appearance and a picture. Only the writer reads the table; readers see the public parts through get_public_story_plan() (S1-E17-33).';



COMMENT ON COLUMN "public"."story_characters"."user_id" IS 'The writer''s user ID; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."story_characters"."role" IS 'The cast group: protagonist, deuteragonist, antagonist, supporting, minor or mentioned (S1-E17-08).';



COMMENT ON COLUMN "public"."story_characters"."sheet" IS 'The sheet''s text fields by key (character_sheet_keys(), S1-E17-09).';



COMMENT ON COLUMN "public"."story_characters"."is_private" IS '"Keep private": readers never see this character, even when Characters is public (S1-E17-32).';



COMMENT ON COLUMN "public"."story_characters"."show_from_chapter_id" IS 'The spoiler guard: readers see the character only once they reached this chapter (S1-E17-35).';



COMMENT ON COLUMN "public"."story_characters"."public_sheet_parts" IS 'The sheet''s groups (basics, look_and_voice, inside, in_the_story, notes) and the writer''s own field IDs readers see (S1-E17-32).';



COMMENT ON COLUMN "public"."story_characters"."map_x" IS 'The card''s left edge on the relationship map, in map pixels; null when the map places it (G10b2).';



COMMENT ON COLUMN "public"."story_characters"."map_y" IS 'The card''s top edge on the relationship map, in map pixels; null when the map places it (G10b2).';



COMMENT ON COLUMN "public"."story_characters"."gender" IS 'kind: user_content. The character''s gender for family words: she (mother, daughter, sister), he (father, son, brother), they or null (parent, child, sibling) (GAPS-3).';



CREATE OR REPLACE FUNCTION "public"."character_json"("target_character" "public"."story_characters") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
