CREATE OR REPLACE FUNCTION "public"."check_chapter_embeds"("body" "text", "owner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  most_embeds integer := coalesce((public.setting_value('chapter_max_embeds'))::integer, 10);
begin
  if (select count(*) from public.chapter_embed_references(body)) > most_embeds then
    raise exception 'A chapter can hold at most % music and video cards (S1-E3-10).', most_embeds
      using errcode = 'check_violation', hint = 'too_many_embeds';
  end if;
  if exists (select 1 from public.chapter_embed_references(body) as reference
             where not exists (select 1 from public.chapter_embeds
                               where chapter_embeds.id = reference.embed_id
                                 and chapter_embeds.user_id = owner_id
                                 and chapter_embeds.deleted_at is null)) then
    raise exception 'That music or video card isn''t one of yours (S1-E3-10).'
      using errcode = 'check_violation', hint = 'embed_unknown';
  end if;
end;
$$;


ALTER FUNCTION "public"."check_chapter_embeds"("body" "text", "owner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_chapter_embeds"("body" "text", "owner_id" "uuid") IS 'Internal: refuses too many music and video cards, or one that isn''t the writer''s own (S1-E3-10).';



CREATE OR REPLACE FUNCTION "public"."check_chapter_pictures"("body" "text", "owner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  most_pictures integer := coalesce((public.setting_value('chapter_max_pictures'))::integer, 30);
  reference record;
begin
  if (select count(*) from public.chapter_picture_references(body)) > most_pictures then
    raise exception 'A chapter can hold at most % pictures (S1-E3-09).', most_pictures
      using errcode = 'check_violation', hint = 'too_many_pictures';
  end if;
  for reference in select * from public.chapter_picture_references(body) loop
    if btrim(reference.alt_text) = '' then
      raise exception 'Every picture needs alt text (S1-E3-09).'
        using errcode = 'check_violation', hint = 'picture_needs_alt';
    end if;
    if char_length(reference.alt_text) > 300 then
      raise exception 'Alt text can have at most 300 characters (S1-E3-09).'
        using errcode = 'check_violation', hint = 'alt_too_long';
    end if;
    if not exists (select 1 from public.picture_checks
                   where picture_checks.id = reference.picture_id and picture_checks.user_id = owner_id
                     and picture_checks.kind in ('chapter_picture', 'drawing')
                     and picture_checks.deleted_at is null) then
      raise exception 'That picture isn''t one of yours (S1-E3-09).'
        using errcode = 'check_violation', hint = 'picture_unknown';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."check_chapter_pictures"("body" "text", "owner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_chapter_pictures"("body" "text", "owner_id" "uuid") IS 'Internal: refuses a chapter picture without alt text, too many, or one that isn''t the writer''s own (S1-E3-09).';



CREATE OR REPLACE FUNCTION "public"."check_chapter_text"("body" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  clean_body text := public.normalise_romanian_letters(body);
  longest integer := coalesce((public.setting_value('chapter_max_characters'))::integer, 100000);
begin
  -- Step 1: the length limit (a setting; proposal 100,000 characters).
  if char_length(clean_body) > longest then
    raise exception 'A chapter can have at most % characters (S1-E3-02a).', longest using errcode = 'check_violation';
  end if;
  -- Step 2: no raw HTML (has_html_tag(): a "<" between numbers and escaped text are fine).
  if public.has_html_tag(clean_body) then
    raise exception 'HTML tags are not allowed in a chapter (CLAUDE.md rule 8).' using errcode = 'check_violation';
  end if;
  -- Step 3: link addresses may not be javascript:, data: or vbscript: (has_unsafe_link()); the
  -- same words in a sentence ("Data: 12 martie") are fine.
  if public.has_unsafe_link(clean_body) then
    raise exception 'Only http, https and mailto links are allowed (CLAUDE.md rule 8).' using errcode = 'check_violation';
  end if;
  return clean_body;
end;
$$;


ALTER FUNCTION "public"."check_chapter_text"("body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_chapter_text"("body" "text") IS 'Internal: refuses HTML tags, script links and over-long text; corrects ş/ţ (S1-E3-02a, rule 8).';



CREATE OR REPLACE FUNCTION "public"."check_character_texts"("texts" "jsonb", "allowed_keys" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  entry record;
begin
  if jsonb_typeof(texts) <> 'object' then
    raise exception 'The sheet''s changes must be an object.' using errcode = 'check_violation', hint = 'not_text';
  end if;
  for entry in select * from jsonb_each(texts) loop
    if not (entry.key = any (allowed_keys)) then
      raise exception 'Unknown character field "%".', entry.key
        using errcode = 'check_violation', hint = 'unknown_field';
    end if;
    if jsonb_typeof(entry.value) <> 'string' then
      raise exception 'A character field holds text.' using errcode = 'check_violation', hint = 'not_text';
    end if;
    if char_length(entry.value #>> '{}') > 20000 then
      raise exception 'A character field holds at most 20,000 characters.'
        using errcode = 'check_violation', hint = 'too_long';
    end if;
  end loop;
end;
$$;


