COMMENT ON FUNCTION "public"."check_story_basics"("clean_title" "text", "clean_blurb" "text", "language_code" "text", "category_slug" "text") IS 'Internal: the title, blurb, language and category rules; returns the category ID (S1-E3-05).';



CREATE OR REPLACE FUNCTION "public"."check_story_cover"("cover" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  kind text := cover ->> 'kind';
begin
  if kind = 'automatic' then
    return;
  end if;
  if kind = 'drawn' then
    if cover ->> 'design' is null or cover ->> 'background' is null or cover ->> 'accent' is null then
      raise exception 'A drawn cover needs a design, a background colour and an accent colour (S1-E3-01).'
        using errcode = 'check_violation';
    end if;
    return;
  end if;
  if kind = 'upload' then
    if not public.is_feature_enabled('picture_uploads') then
      raise exception 'Picture uploads are switched off (picture_uploads flag; decided 23 Oct 2026).'
        using errcode = 'feature_not_supported';
    end if;
    if not exists (select 1 from public.picture_checks
                   where picture_checks.bucket = 'covers' and picture_checks.path = cover ->> 'tall_path'
                     and picture_checks.user_id = (select auth.uid()) and picture_checks.status <> 'removed') then
      raise exception 'Upload the cover picture first (S1-E10-05).' using errcode = 'check_violation';
    end if;
    return;
  end if;
  raise exception 'Unknown cover kind "%".', coalesce(kind, 'none') using errcode = 'check_violation';
end;
$$;


ALTER FUNCTION "public"."check_story_cover"("cover" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_story_cover"("cover" "jsonb") IS 'Internal: refuses a cover choice the rules don''t allow, with a plain message (S1-E3-01).';



CREATE OR REPLACE FUNCTION "public"."check_story_labels"("labels" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if labels ->> 'rating' is null or labels ->> 'rating' not in ('all_ages', '13_plus', '16_plus', '18_plus') then
    raise exception 'Pick a rating: All ages, 13+, 16+ or 18+ (S1-E3-06).' using errcode = 'check_violation';
  end if;
  if labels ->> 'ai_disclosure' is null
     or labels ->> 'ai_disclosure' not in ('no_ai', 'ai_brainstorming', 'partly_ai_written') then
    raise exception 'Say whether AI was used (S1-E3-06).' using errcode = 'check_violation';
  end if;
  if char_length(coalesce(labels ->> 'content_note', '')) > 300 then
    raise exception 'A content note can have at most 300 characters (S1-E3-06).' using errcode = 'check_violation';
  end if;
  if coalesce((labels ->> 'deals_with_abuse_or_coercion')::boolean, false)
     and not (labels ->> 'rating' in ('16_plus', '18_plus') and btrim(coalesce(labels ->> 'content_note', '')) <> '') then
    raise exception 'A story about abuse or coercion must be rated 16+ or 18+ and carry a content note (17 Oct 2026).'
      using errcode = 'check_violation';
  end if;
  -- SPONSORS-f: the reasons, when given, are a list of the seven known ones.
  if labels ? 'rating_reasons' and (jsonb_typeof(labels -> 'rating_reasons') <> 'array' or exists (
      select 1 from jsonb_array_elements(labels -> 'rating_reasons') as reason
      where jsonb_typeof(reason) <> 'string'
        or reason #>> '{}' not in ('sexual_content', 'nudity', 'graphic_violence', 'strong_language',
                                   'drugs', 'self_harm', 'dark_themes'))) then
    raise exception 'Pick the reasons from the list (SPONSORS-f).' using errcode = 'check_violation';
  end if;
end;
$$;


