CREATE TABLE IF NOT EXISTS "public"."invites" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "purpose" "text" DEFAULT 'platform'::"text" NOT NULL,
    "space_id" "uuid",
    "code_hash" "text" NOT NULL,
    "max_uses" integer DEFAULT 1 NOT NULL,
    "use_count" integer DEFAULT 0 NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '14 days'::interval) NOT NULL,
    "revoked_at" timestamp with time zone,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "invites_purpose_is_known" CHECK (("purpose" = ANY (ARRAY['platform'::"text", 'class_space'::"text"]))),
    CONSTRAINT "invites_space_only_for_class_spaces" CHECK ((("purpose" = 'class_space'::"text") = ("space_id" IS NOT NULL))),
    CONSTRAINT "invites_uses_are_counted" CHECK ((("max_uses" >= 1) AND (("use_count" >= 0) AND ("use_count" <= "max_uses"))))
);


ALTER TABLE "public"."invites" OWNER TO "postgres";


COMMENT ON TABLE "public"."invites" IS 'kind: user_action
Invite links and codes, stored hashed; user_id is the staff member or teacher who made it (S1-E2-01, S1-E11-17).';



COMMENT ON COLUMN "public"."invites"."user_id" IS 'Who made the invite (an admin for the March test; a teacher for class spaces later). Never who used it.';



COMMENT ON COLUMN "public"."invites"."code_hash" IS 'SHA-256 of the normalised code, in hex; the code itself is shown once and never stored.';



COMMENT ON COLUMN "public"."invites"."note" IS 'A private note for the admin ("for Ana, beta tester"): a first name or a role only (S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."class_invite_row"("code" "text") RETURNS "public"."invites"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select invites.* from public.invites
  join public.spaces on spaces.id = invites.space_id and spaces.deleted_at is null
  where invites.code_hash = public.invite_code_hash(code) and invites.purpose = 'class_space';
$$;


ALTER FUNCTION "public"."class_invite_row"("code" "text") OWNER TO "postgres";


