COMMENT ON FUNCTION "public"."class_space_stories"("slug" "text") IS 'The stories shared only with a class, for those who may read the class (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."class_thread_replies"("target_thread_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  class_space public.spaces;
begin
  -- Step 1: find the class space the thread lives in (a space's forum carries its space_id).
  select spaces.* into class_space
  from public.forum_threads
  join public.forums on forums.id = forum_threads.forum_id
  join public.spaces on spaces.id = forums.space_id
  where forum_threads.id = target_thread_id
    and forum_threads.deleted_at is null
    and spaces.kind = 'class';
  -- Step 2: not a class thread, or not the teacher (or someone acting for them): nothing to show.
  if class_space.id is null or not public.space_may_act(class_space, 'members') then
    return null;
  end if;
  -- Step 3: every active member but the owner, marked by whether they have a live post here.
  return (
    with members as (
      select profiles.handle,
             public.display_name(profiles.handle, profiles.pen_name) as display_name,
             exists (select 1 from public.forum_posts
                     where forum_posts.thread_id = target_thread_id
                       and forum_posts.user_id = space_members.user_id
                       and forum_posts.deleted_at is null) as has_replied
      from public.space_members
      join public.profiles on profiles.id = space_members.user_id
      where space_members.space_id = class_space.id
        and space_members.status = 'active'
        and space_members.role <> 'owner'
        and profiles.deleted_at is null
    )
    select jsonb_build_object(
      'replied', coalesce(jsonb_agg(jsonb_build_object('handle', handle, 'display_name', display_name)
                   order by lower(display_name), handle) filter (where has_replied), '[]'::jsonb),
      'not_yet', coalesce(jsonb_agg(jsonb_build_object('handle', handle, 'display_name', display_name)
                   order by lower(display_name), handle) filter (where not has_replied), '[]'::jsonb))
    from members);
end;
$$;


ALTER FUNCTION "public"."class_thread_replies"("target_thread_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."class_thread_replies"("target_thread_id" "uuid") IS 'Who in a class has posted in one of its threads and who hasn''t yet, for the teacher only (IDEAS-3b).';



CREATE OR REPLACE FUNCTION "public"."class_waiting_members"("slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(slug, 'members');
begin
  -- Step 1: only a class has members who wait to read.
  if space.kind <> 'class' then
    raise exception 'Only a class space has this list.' using errcode = 'check_violation', hint = 'space:not_class';
  end if;
  -- Step 2: every active member the account gate still stops, with the reason in plain terms.
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'handle', profiles.handle,
             'display_name', public.display_name(profiles.handle, profiles.pen_name),
             'reason', case
               when waiting.state in ('age_check_pending', 'age_check_failed') then 'age_check'
               when waiting.state = 'awaiting_parental_consent' then 'parental_consent'
               else 'account' end)
           order by space_members.joined_at, profiles.handle)
    from public.space_members
    join public.profiles on profiles.id = space_members.user_id
    cross join lateral (select public.account_state(space_members.user_id) as state) as waiting
    where space_members.space_id = space.id and space_members.status = 'active'
      and space_members.role <> 'owner' and profiles.deleted_at is null
      and waiting.state <> 'active'), '[]'::jsonb);
end;
$$;


