CREATE OR REPLACE FUNCTION "public"."classic_free_markets"("author_died_year" integer, "translator_died_year" integer, "first_published_year" integer, "on_day" "date") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with checked as (
    select extract(year from on_day)::integer as this_year
  ), life_plus_seventy as (
    select author_died_year + 70 < this_year
      and (translator_died_year is null or translator_died_year + 70 < this_year) as is_free,
      this_year
    from checked
  )
  select jsonb_build_object(
    'RO', is_free, 'EU', is_free, 'UK', is_free,
    'US', case when first_published_year is null then null
               else first_published_year + 95 < this_year end)
  from life_plus_seventy;
$$;


ALTER FUNCTION "public"."classic_free_markets"("author_died_year" integer, "translator_died_year" integer, "first_published_year" integer, "on_day" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."classic_free_markets"("author_died_year" integer, "translator_died_year" integer, "first_published_year" integer, "on_day" "date") IS 'Where a work is public domain on a day: {RO, EU, UK, US} (S1-E11-16; Law 8/1996 art. 28(1) and 34; research G5).';



CREATE OR REPLACE FUNCTION "public"."classic_import_row"("list_row" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  clean_title text := public.normalise_romanian_letters(btrim(coalesce(list_row ->> 'title', '')));
  wanted_kind public.classic_kind := public.classic_kind_from_list(list_row ->> 'type');
  wanted_language text := lower(btrim(coalesce(list_row ->> 'language', '')));
  author_id uuid;
  new_story_id uuid;
begin
  -- Step 1: every field the draft needs, in a form the database knows.
  if clean_title = '' or coalesce(btrim(list_row ->> 'author'), '') = ''
     or coalesce(list_row ->> 'author_died', '') !~ '^\d{1,4}$'
     or coalesce(list_row ->> 'source_url', '') !~ '^https://' then
    raise exception 'A field is missing.' using errcode = 'check_violation', hint = 'row_incomplete';
  end if;
  if wanted_kind is null then
    raise exception 'Unknown kind of work.' using errcode = 'check_violation', hint = 'unknown_kind';
  end if;
  if not exists (select 1 from public.languages where languages.code = wanted_language) then
    raise exception 'Unknown language.' using errcode = 'check_violation', hint = 'unknown_language';
  end if;
  -- Step 2: the author, found by name or added (a different year of death is refused).
  author_id := public.admin_add_classic_author(list_row ->> 'author', (list_row ->> 'author_died')::integer);
  -- Step 3: the same title by the same author is the same work.
  if exists (select 1 from public.stories where stories.classic_author_id = author_id
             and lower(stories.title) = lower(clean_title) and stories.deleted_at is null) then
    return 'already_listed';
  end if;
  -- Step 4: the draft story, rated All ages until staff check it, and its details. Poems go to
  -- Poetry, essays to Nonfiction and essays, the rest to Fiction.
  new_story_id := public.classic_upsert_story(null, jsonb_build_object('title', clean_title, 'blurb', '',
      'language_code', wanted_language, 'rating', 'all_ages', 'author_id', author_id),
    (select categories.id from public.categories where categories.slug = case wanted_kind
       when 'poem' then 'poetry' when 'essay' then 'nonfiction_essays' else 'fiction' end));
  insert into public.classic_works (story_id, kind, original_language, source_title, source_url,
    added_by_user_id, details_checked)
  values (new_story_id, wanted_kind, wanted_language, public.classic_source_title(list_row ->> 'source_url'),
    btrim(list_row ->> 'source_url'), (select auth.uid()), false);
  return 'added';
end;
$_$;


ALTER FUNCTION "public"."classic_import_row"("list_row" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."classic_import_row"("list_row" "jsonb") IS 'Internal: one research list row as a draft classic (S1-E11-16b).';



CREATE OR REPLACE FUNCTION "public"."classic_kind_from_list"("list_type" "text") RETURNS "public"."classic_kind"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lower(btrim(list_type)) like 'novel%' then 'novel'
    when lower(btrim(list_type)) like 'short %' then 'short_story'
    when lower(btrim(list_type)) like 'fairy tale%' then 'fairy_tale'
    when lower(btrim(list_type)) like 'poe%' then 'poem'
    when lower(btrim(list_type)) like 'play%' then 'play'
    when lower(btrim(list_type)) like 'essay%' then 'essay'
    when lower(btrim(list_type)) like 'travel %' then 'essay'
  end::public.classic_kind;
$$;


ALTER FUNCTION "public"."classic_kind_from_list"("list_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."classic_kind_from_list"("list_type" "text") IS 'Internal: a research list''s type as a classic_kind (S1-E11-16b).';



CREATE OR REPLACE FUNCTION "public"."classic_source_title"("source_link" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when source_link ~ '^https://([a-z]+\.)?wikisource\.org/' then 'Wikisource'
    when source_link ~ '^https://(www\.)?gutenberg\.org/' then 'Project Gutenberg'
    when source_link ~ '^https://(www\.)?standardebooks\.org/' then 'Standard Ebooks'
    else substring(source_link from '^https://([^/]+)')
  end;
$$;


ALTER FUNCTION "public"."classic_source_title"("source_link" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."classic_source_title"("source_link" "text") IS 'Internal: the site a classic''s source link points to (S1-E11-16b).';



CREATE OR REPLACE FUNCTION "public"."classic_story_category"("details" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  category_id uuid;
begin
  select categories.id into category_id from public.categories where categories.slug = details ->> 'category_slug';
  if category_id is null
     or not exists (select 1 from public.classic_authors where classic_authors.id = (details ->> 'author_id')::uuid)
     or (details ->> 'rating') is null then
    raise exception 'Pick an author, a category and a rating.' using errcode = 'check_violation', hint = 'details_invalid';
  end if;
  return category_id;
end;
$$;


ALTER FUNCTION "public"."classic_story_category"("details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classic_upsert_story"("target_story_id" "uuid", "details" "jsonb", "wanted_category_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_title text := public.normalise_romanian_letters(btrim(coalesce(details ->> 'title', '')));
  saved_story_id uuid := target_story_id;
begin
  if saved_story_id is null then
    -- A new classic: owned by the classics account (owner ids never change), automatic cover.
    insert into public.stories (user_id, slug, title, blurb, language_code, category_id, rating,
      content_note, classic_author_id, completion_status)
    values (public.classics_account_id(), public.story_slug_for(clean_title), clean_title,
      coalesce(details ->> 'blurb', ''), details ->> 'language_code', wanted_category_id,
      (details ->> 'rating')::public.story_rating, coalesce(details ->> 'content_note', ''),
      (details ->> 'author_id')::uuid, 'completed')
    returning id into saved_story_id;
    return saved_story_id;
  end if;
  update public.stories set title = clean_title, blurb = coalesce(details ->> 'blurb', ''),
    language_code = details ->> 'language_code', category_id = wanted_category_id,
    rating = (details ->> 'rating')::public.story_rating,
    content_note = coalesce(details ->> 'content_note', ''),
    classic_author_id = (details ->> 'author_id')::uuid
  where stories.id = saved_story_id and stories.deleted_at is null
    and exists (select 1 from public.classic_works where classic_works.story_id = stories.id);
  if not found then
    raise exception 'That isn''t a classic.' using errcode = 'no_data_found', hint = 'not_a_classic';
  end if;
  return saved_story_id;
end;
$$;


ALTER FUNCTION "public"."classic_upsert_story"("target_story_id" "uuid", "details" "jsonb", "wanted_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classic_work_json"("target_story_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'story_id', stories.id, 'slug', stories.slug, 'title', stories.title, 'blurb', stories.blurb,
    'language_code', stories.language_code, 'rating', stories.rating,
    'content_note', stories.content_note,
    'category_slug', (select categories.slug from public.categories where categories.id = stories.category_id),
    'author', jsonb_build_object('id', classic_authors.id, 'name', classic_authors.name,
      'died_year', classic_authors.died_year),
    'kind', works.kind, 'original_language', works.original_language,
    'source_title', works.source_title, 'source_url', works.source_url,
    'translator_name', works.translator_name, 'translator_died_year', works.translator_died_year,
    'first_published_year', works.first_published_year,
    'details_checked', works.details_checked,
    'free_markets', public.classic_free_markets(classic_authors.died_year, works.translator_died_year,
      works.first_published_year, (now() at time zone 'Europe/Bucharest')::date),
    'chapters', coalesce((
      select jsonb_agg(jsonb_build_object('code', chapters.code, 'title', chapters.draft_title,
          'word_count', chapters.word_count, 'status', chapters.status) order by chapters.position)
      from public.chapters
      where chapters.story_id = stories.id and chapters.deleted_at is null), '[]'::jsonb),
    -- Once any chapter has been live, the text can't be replaced, only corrected (16b).
    'was_published', exists (select 1 from public.chapters where chapters.story_id = stories.id
      and chapters.deleted_at is null and chapters.first_published_at is not null),
    'updated_at', greatest(stories.updated_at, works.updated_at))
  from public.stories
  join public.classic_works as works on works.story_id = stories.id
  join public.classic_authors on classic_authors.id = stories.classic_author_id
  where stories.id = target_story_id and stories.deleted_at is null;
$$;


ALTER FUNCTION "public"."classic_work_json"("target_story_id" "uuid") OWNER TO "postgres";


