COMMENT ON FUNCTION "public"."comment_wait_minutes"("author_id" "uuid") IS 'Internal: minutes until the author may comment again, 0 when now (S1-E6-01).';



CREATE OR REPLACE FUNCTION "public"."compliance_times_problem"("received" timestamp with time zone, "completed" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when received > now() + interval '5 minutes' or completed > now() + interval '5 minutes' then 'in_future'
    when completed < received then 'done_before_received'
  end;
$$;


