    "what_counts_en" "text" DEFAULT ''::"text" NOT NULL,
    "word_limit" integer,
    "prize_ro" "text" DEFAULT ''::"text" NOT NULL,
    "prize_en" "text" DEFAULT ''::"text" NOT NULL,
    "prize_delivered_by" "text" DEFAULT ''::"text" NOT NULL,
    "judges" "text" DEFAULT ''::"text" NOT NULL,
    "rules_page_key" "text",
    "opened_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "results_published_at" timestamp with time zone,
    CONSTRAINT "contests_age_groups_are_known" CHECK (("age_groups" <@ ARRAY['13_to_15'::"text", '16_to_17'::"text", '18_plus'::"text"])),
    CONSTRAINT "contests_rules_key_is_an_address" CHECK ((("rules_page_key" IS NULL) OR ("rules_page_key" ~ '^[a-z0-9][a-z0-9-]{0,59}$'::"text"))),
    CONSTRAINT "contests_word_limit_is_sensible" CHECK ((("word_limit" IS NULL) OR (("word_limit" >= 100) AND ("word_limit" <= 500000))))
);


