COMMENT ON FUNCTION "public"."contest_landing_problems"("target" "public"."contests") IS 'Internal: landing page problems that stop a contest from opening (S1-E11-15 criterion 2).';



CREATE OR REPLACE FUNCTION "public"."contest_problems"("target" "public"."contests") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.contest_detail_problems(target)
    || case when target.rules_page_key is not null and not public.contest_rules_are_published(target)
         then array['rules_not_published'] else '{}'::text[] end
    || public.contest_landing_problems(target);
$$;


ALTER FUNCTION "public"."contest_problems"("target" "public"."contests") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contest_problems"("target" "public"."contests") IS 'Internal: what stops a contest from opening (S1-E11-15 criterion 2).';



CREATE OR REPLACE FUNCTION "public"."contest_results_json"("target_page_id" "uuid", "content" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when contests.results_published_at is null then null else coalesce((
    select jsonb_agg(jsonb_build_object(
        'placing', entries.award,
        'pen_name', public.display_name(profiles.handle, profiles.pen_name),
        'story', (select jsonb_build_object('slug', listed.slug, 'title', listed.title)
                  from public.listed_stories('updated', null, null, null, null) as listed
                  where listed.id = entries.story_id
                    and listed.rating = any (public.landing_youngest_ratings(content)))
      ) order by entries.award desc, profiles.handle)
    from public.contest_entries as entries
    join public.profiles on profiles.id = entries.user_id
    where entries.contest_id = contests.id and entries.status = 'valid' and entries.award is not null
  ), '[]'::jsonb) end
  from public.contests
  where contests.landing_page_id = target_page_id;
$$;


