CREATE TABLE IF NOT EXISTS "public"."conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "recipient_user_id" "uuid" NOT NULL,
    "status" "public"."conversation_status" DEFAULT 'request'::"public"."conversation_status" NOT NULL,
    "accepted_at" timestamp with time zone,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "said_no_thanks_at" timestamp with time zone,
    CONSTRAINT "conversations_two_people" CHECK (("user_id" <> "recipient_user_id"))
);


ALTER TABLE "public"."conversations" OWNER TO "postgres";


COMMENT ON TABLE "public"."conversations" IS 'kind: user_action
A one-to-one chat between two people: who started it, who it went to and whether it is a request, accepted or declined (S1-E9-01). Read only through the messaging functions.';



COMMENT ON COLUMN "public"."conversations"."user_id" IS 'Who started the chat; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."conversations"."recipient_user_id" IS 'Who the first message went to.';



COMMENT ON COLUMN "public"."conversations"."said_no_thanks_at" IS 'When the recipient answered the request with "No thanks" (IDEAS-2 idea 7); the sender may ask again 30 days later.';



CREATE OR REPLACE FUNCTION "public"."conversation_between"("first_user_id" "uuid", "second_user_id" "uuid") RETURNS "public"."conversations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select * from public.conversations
  where least(conversations.user_id, conversations.recipient_user_id) = least(first_user_id, second_user_id)
    and greatest(conversations.user_id, conversations.recipient_user_id) = greatest(first_user_id, second_user_id);
$$;


ALTER FUNCTION "public"."conversation_between"("first_user_id" "uuid", "second_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."conversation_between"("first_user_id" "uuid", "second_user_id" "uuid") IS 'Internal: the chat between two people, if any (S1-E9-01).';



CREATE OR REPLACE FUNCTION "public"."conversation_can_send"("chat" "public"."conversations", "writer_id" "uuid", "other_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    -- A staff account isn't a member's inbox: people write to the team through moderator mail.
    when chat.id is null then public.can_message(writer_id, other_id)
      and public.account_state(other_id) <> 'staff_account'
    when chat.status = 'accepted' then public.may_keep_writing(writer_id, other_id)
    -- "No thanks" pauses the sender for 30 days, then they may ask once more (IDEAS-2 idea 7).
    when chat.user_id = writer_id and public.no_thanks_pause_ends(chat) is not null then
      public.no_thanks_pause_ends(chat) <= now()
      and public.can_message(writer_id, other_id)
      and public.account_state(other_id) <> 'staff_account'
    else chat.recipient_user_id = writer_id and public.may_keep_writing(writer_id, other_id)
  end;
$$;


ALTER FUNCTION "public"."conversation_can_send"("chat" "public"."conversations", "writer_id" "uuid", "other_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."conversation_can_send"("chat" "public"."conversations", "writer_id" "uuid", "other_id" "uuid") IS 'Internal: whether someone may send the next message in a chat, or start one (S1-E9-01, IDEAS-2 idea 7).';



CREATE OR REPLACE FUNCTION "public"."conversation_messages_json"("chat_id" "uuid", "reader_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', recent.id, 'from_me', recent.user_id = reader_id,
      'body', public.message_body_for(recent, reader_id), 'at', recent.created_at)
    order by recent.created_at), '[]'::jsonb)
  from (select * from public.messages
        where messages.conversation_id = chat_id and messages.deleted_at is null
          -- Only what came after the reader last deleted the chat (S1-E9-04).
          and messages.created_at > coalesce(public.chat_cleared_at(chat_id, reader_id), '-infinity'::timestamptz)
        order by messages.created_at desc limit 200) as recent;
$$;


ALTER FUNCTION "public"."conversation_messages_json"("chat_id" "uuid", "reader_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."conversation_messages_json"("chat_id" "uuid", "reader_id" "uuid") IS 'Internal: a chat''s last 200 messages for one reader (S1-E9-01).';



CREATE OR REPLACE FUNCTION "public"."conversation_with"("other_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_messaging_caller();
  other public.profiles := public.messaging_partner(other_handle);
  chat public.conversations;
  said_no_thanks boolean;
begin
  -- Step 1: someone the caller may see in Messages.
  if other.id is null then
    return null;
  end if;
  -- Step 2: their chat, if they have one, and whether it closed with "No thanks" to the caller.
  chat := public.conversation_between(caller_id, other.id);
  said_no_thanks := chat.user_id = caller_id and public.no_thanks_pause_ends(chat) is not null;
  -- Step 3: the answer.
  return jsonb_build_object(
    'handle', other.handle,
    'display_name', public.display_name(other.handle, other.pen_name),
    'status', chat.status,
    'is_request_to_me', chat.status = 'request' and chat.recipient_user_id = caller_id,
    'is_waiting', chat.status in ('request', 'declined') and chat.user_id = caller_id and not coalesce(said_no_thanks, false),
    'said_no_thanks', coalesce(said_no_thanks, false),
    'ask_again_from', case when said_no_thanks then public.no_thanks_pause_ends(chat) end,
    'can_send', public.conversation_can_send(chat, caller_id, other.id),
    'i_follow', exists (select 1 from public.follows_users
                        where follows_users.user_id = caller_id and follows_users.followed_user_id = other.id),
    'they_follow', exists (select 1 from public.follows_users
                           where follows_users.user_id = other.id and follows_users.followed_user_id = caller_id),
    'messages', case when chat.id is null or (chat.status = 'declined' and chat.recipient_user_id = caller_id)
                     then '[]'::jsonb else public.conversation_messages_json(chat.id, caller_id) end);
end;
$$;


ALTER FUNCTION "public"."conversation_with"("other_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."conversation_with"("other_handle" "text") IS 'One chat by the other person''s username, as the caller sees it; never says why sending is off (S1-E9-01, IDEAS-2 idea 7).';



