COMMENT ON FUNCTION "public"."cover_upload_allowed"("object_name" "text") IS 'True only for the story''s owner, on a <story id>/… path, while picture_uploads is on (S1-E3-01).';



CREATE OR REPLACE FUNCTION "public"."create_bible_entry"("section_id" "uuid", "entry_title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_section public.story_bible_sections;
  new_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your story bible.' using errcode = 'insufficient_privilege';
  end if;
  target_section := public.my_bible_section(section_id);
  if target_section.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if (select count(*) from public.story_bible_entries where story_id = target_section.story_id) >= 2000 then
    raise exception 'A bible can hold at most 2,000 entries.' using errcode = 'check_violation', hint = 'too_many_entries';
  end if;
  insert into public.story_bible_entries (story_id, user_id, section_id, title)
  values (target_section.story_id, target_section.user_id, target_section.id,
    btrim(public.normalise_romanian_letters(coalesce(entry_title, ''))))
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."create_bible_entry"("section_id" "uuid", "entry_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_bible_entry"("section_id" "uuid", "entry_title" "text") IS 'Adds an entry to one of the caller''s bible sections (S1-E17-18).';



CREATE OR REPLACE FUNCTION "public"."create_chapter"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  new_code text;
  new_position integer;
begin
  -- Step 1: a signed-in writer who may write, and their own live story (the account gate).
  if caller_id is null then
    raise exception 'Sign in to add a chapter.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the next position after the story's live chapters, and a fresh address.
  select coalesce(max(chapters.position), 0) + 1 into new_position
  from public.chapters where chapters.story_id = target_story_id and chapters.deleted_at is null;
  new_code := public.chapter_code();
  insert into public.chapters (story_id, user_id, code, position)
  values (target_story_id, caller_id, new_code, new_position);
  return jsonb_build_object('outcome', 'ok', 'code', new_code, 'position', new_position);
end;
$$;


ALTER FUNCTION "public"."create_chapter"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_chapter"("story_slug" "text") IS 'Adds an empty chapter to the caller''s own story: {outcome: ok, code, position} | not_active | not_found (S1-E3-02a).';



CREATE OR REPLACE FUNCTION "public"."create_class_space"("name" "text", "description" "text", "rules" "text" DEFAULT ''::"text", "banner" "public"."space_banner" DEFAULT 'plum'::"public"."space_banner") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_space_starter();
  new_space public.spaces;
begin
  -- Step 1: only an adult teacher with the badge (criterion 1; S1-E2-11 grants it to adults only).
  if public.age_band() is distinct from '18_plus'
     or (select profiles.teacher_badge_since from public.profiles where profiles.id = caller_id) is null then
    raise exception 'Only teachers can start a class space.' using errcode = 'insufficient_privilege', hint = 'space:not_teacher';
  end if;
  -- Step 2: the spam limit, then the space.
  perform public.take_rate_limit('space_create');
  new_space := public.insert_class_space(caller_id, name, description, rules, banner, null);
  return jsonb_build_object('slug', new_space.slug);
end;
$$;


