COMMENT ON FUNCTION "public"."create_class_space"("name" "text", "description" "text", "rules" "text", "banner" "public"."space_banner") IS 'Starts a private class space for a teacher with the badge; joined by invite code only (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."create_monthly_safety_checks"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  opened integer;
begin
  insert into public.safety_contact_checks (country_code, check_month)
  select markets.country_code, date_trunc('month', now() at time zone 'Europe/Bucharest')::date
  from public.markets
  on conflict (country_code, check_month) do nothing;
  get diagnostics opened = row_count;
  return opened;
end;
$$;


