COMMENT ON FUNCTION "public"."create_reading_list"("list_name" "text") IS 'Makes a private, empty reading list for the caller (GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."create_space"("name" "text", "description" "text", "rules" "text" DEFAULT ''::"text", "posting" "public"."space_posting" DEFAULT 'members'::"public"."space_posting", "joining" "public"."space_joining" DEFAULT 'approve'::"public"."space_joining", "readers" "public"."space_readers" DEFAULT 'members'::"public"."space_readers", "banner" "public"."space_banner" DEFAULT 'plum'::"public"."space_banner") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_space_starter();
  age_group public.space_age_group := public.space_age_group_of_caller();
  clean_name text := public.check_space_text(name, 'name');
  new_space public.spaces;
begin
  -- Step 1: the spam limit, then the name only once.
  perform public.take_rate_limit('space_create');
  if exists (select 1 from public.spaces
             where spaces.name_key = public.space_name_key(clean_name) and spaces.deleted_at is null) then
    raise exception 'Another space has this name.' using errcode = 'check_violation', hint = 'name:taken';
  end if;
  -- Step 2: the space, read by everybody unless it is an under-16 space its owner keeps to members.
  insert into public.spaces (user_id, slug, name, name_key, description, rules, age_group, readers,
                             posting, joining, banner)
  values (caller_id, public.space_slug_for(clean_name), clean_name, public.space_name_key(clean_name),
          public.check_space_text(description, 'description'), public.check_space_text(rules, 'rules'),
          age_group,
          case when age_group = 'under_16' then coalesce(create_space.readers, 'members') else 'everybody' end,
          coalesce(create_space.posting, 'members'), coalesce(create_space.joining, 'approve'),
          coalesce(create_space.banner, 'plum'))
  returning * into new_space;
  -- Step 3: its hidden forum, named after it, and the owner as its first member.
  insert into public.forums (slug, space_id) values ('space-' || new_space.slug, new_space.id);
  perform public.write_space_forum_names(new_space.id, new_space.name);
  insert into public.space_members (user_id, space_id, role, status, joined_at)
  values (caller_id, new_space.id, 'owner', 'active', now());
  return jsonb_build_object('slug', new_space.slug);
end;
$$;


ALTER FUNCTION "public"."create_space"("name" "text", "description" "text", "rules" "text", "posting" "public"."space_posting", "joining" "public"."space_joining", "readers" "public"."space_readers", "banner" "public"."space_banner") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_space"("name" "text", "description" "text", "rules" "text", "posting" "public"."space_posting", "joining" "public"."space_joining", "readers" "public"."space_readers", "banner" "public"."space_banner") IS 'Starts a space with its owner, age group and hidden forum; the spam limit only (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."create_story"("title" "text", "blurb" "text", "language_code" "text", "category_slug" "text", "tag_names" "text"[], "cover" "jsonb", "story_id" "uuid" DEFAULT NULL::"uuid", "labels" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  clean_title text := regexp_replace(btrim(coalesce(title, '')), '\s+', ' ', 'g');
  clean_blurb text := btrim(coalesce(blurb, ''));
  chosen_category_id uuid;
  new_story_id uuid := coalesce(story_id, gen_random_uuid());
  new_slug text;
begin
  -- Step 1: a signed-in person who may write (the account gate; every write checks it).
  if caller_id is null then
    raise exception 'Sign in to create a story.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;

  -- Step 2: the shared rules, the tags cap, the cover and the labels; an ID in use is never reused.
  chosen_category_id := public.check_story_basics(clean_title, clean_blurb, language_code, category_slug);
  if cardinality(coalesce(tag_names, '{}')) > 10 then
    raise exception 'A story can have at most 10 tags (S1-E3-01).' using errcode = 'check_violation';
  end if;
  perform public.check_story_cover(cover);
  perform public.check_story_labels(coalesce(labels, '{}'::jsonb));
  if exists (select 1 from public.stories where stories.id = new_story_id) then
    raise exception 'That story ID is already in use (S1-E3-13).' using errcode = 'check_violation';
  end if;

  -- Step 3: the row, with a fresh address; a one-in-two-billion clash just picks another.
  loop
    new_slug := public.story_slug_for(clean_title);
    exit when not exists (select 1 from public.stories where stories.slug = new_slug);
  end loop;
  insert into public.stories (
    id, user_id, slug, title, blurb, language_code, category_id,
    cover_kind, cover_design, cover_background, cover_accent, cover_tall_path, cover_square_path,
    rating, is_fan_fiction, is_parody, deals_with_abuse_or_coercion, content_note, ai_disclosure,
    rating_reasons
  ) values (
    new_story_id, caller_id, new_slug, clean_title, clean_blurb, language_code, chosen_category_id,
    (cover ->> 'kind')::public.cover_kind, cover ->> 'design', cover ->> 'background', cover ->> 'accent',
    cover ->> 'tall_path', cover ->> 'square_path',
    (labels ->> 'rating')::public.story_rating,
    coalesce((labels ->> 'is_fan_fiction')::boolean, false),
    coalesce((labels ->> 'is_parody')::boolean, false),
    coalesce((labels ->> 'deals_with_abuse_or_coercion')::boolean, false),
    btrim(coalesce(labels ->> 'content_note', '')),
    (labels ->> 'ai_disclosure')::public.ai_disclosure,
    -- Why it is 16+ or 18+ (SPONSORS-f); empty for a younger rating.
    public.story_rating_reasons_from(labels)
  );

  -- Step 4: the tags, merged and capped.
  perform public.set_story_tags(new_story_id, caller_id, tag_names);

  return jsonb_build_object('outcome', 'ok', 'slug', new_slug);
end;
$$;


ALTER FUNCTION "public"."create_story"("title" "text", "blurb" "text", "language_code" "text", "category_slug" "text", "tag_names" "text"[], "cover" "jsonb", "story_id" "uuid", "labels" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_story"("title" "text", "blurb" "text", "language_code" "text", "category_slug" "text", "tag_names" "text"[], "cover" "jsonb", "story_id" "uuid", "labels" "jsonb") IS 'Makes a story for the signed-in writer with its labels: {outcome: ok, slug} or {outcome: not_active} (S1-E3-01, 13, 06).';



CREATE OR REPLACE FUNCTION "public"."create_story_character"("story_slug" "text", "character_name" "text", "character_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  new_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story.
  if caller_id is null then
    raise exception 'Sign in to add a character.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the bound on one story's cast.
  if (select count(*) from public.story_characters where story_id = target_story_id) >= 500 then
    raise exception 'A story can hold at most 500 characters.'
      using errcode = 'check_violation', hint = 'too_many_characters';
  end if;
  -- Step 3: the character; the table's checks refuse an empty name or an unknown role.
  insert into public.story_characters (story_id, user_id, name, role)
  values (target_story_id, caller_id, btrim(character_name), character_role)
  returning id into new_id;
  return jsonb_build_object('outcome', 'ok', 'id', new_id);
end;
$$;


ALTER FUNCTION "public"."create_story_character"("story_slug" "text", "character_name" "text", "character_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_story_character"("story_slug" "text", "character_name" "text", "character_role" "text") IS 'Adds a character to one of the caller''s story plans and returns its ID (S1-E17-08).';



