COMMENT ON TABLE "public"."parental_consents" IS 'kind: user_action
A parent''s or guardian''s consent for a writer under 16 (S1-E2-03; GDPR art. 8): who was asked, when they answered, which notice versions they saw. Never the token itself.';



COMMENT ON COLUMN "public"."parental_consents"."spotlight_agreed_at" IS 'When the parent last agreed that the child may be suggested to other people (S1-E2-03b; GDPR art. 8).';



COMMENT ON COLUMN "public"."parental_consents"."spotlight_withdrawn_at" IS 'When that yes was last withdrawn, by the parent or by staff; a later yes clears it (S1-E2-03b).';



COMMENT ON COLUMN "public"."parental_consents"."spotlight_token_hash" IS 'SHA-256 of the link in the latest "may we suggest your child?" email; the link itself is never stored (S1-E2-03b).';



COMMENT ON COLUMN "public"."parental_consents"."spotlight_requested_at" IS 'When that email was last sent, so a child can''t send it again and again (S1-E2-03b).';



CREATE OR REPLACE FUNCTION "public"."data_request_parent_consent"("person_id" "uuid") RETURNS "public"."parental_consents"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select * from public.parental_consents
  where parental_consents.user_id = person_id and parental_consents.status = 'agreed'
  order by parental_consents.decided_at desc nulls last
  limit 1;
$$;


ALTER FUNCTION "public"."data_request_parent_consent"("person_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."data_request_parent_consent"("person_id" "uuid") IS 'Internal: the agreed parental consent a data request link goes to (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."data_request_parent_copy_state"("request" "public"."data_requests") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when not exists (select 1 from public.exports
                     where exports.data_request_id = request.id and exports.state = 'ready'
                       and exports.expires_at > now()) then 'expired'
    when request.parent_copy_opened_at is null then 'ready'
    when request.parent_copy_opened_at > now() - interval '1 hour' then 'open'
    else 'used'
  end;
$$;


