CREATE OR REPLACE FUNCTION "public"."data_request_parent_is_signed"("purpose" "text", "target_request_id" "uuid", "token_hash" "text", "signature" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
