COMMENT ON FUNCTION "public"."data_request_person_is_under_16"("person_id" "uuid") IS 'Internal: whether a data request''s person is under 16, so it goes through the parent (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."data_request_urgency"("request" "public"."data_requests") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when request.state = 'closed' then 'closed'
    when public.data_request_deadline(request) < public.romania_today() then 'overdue'
    when public.data_request_deadline(request) - public.romania_today() <= 2 then 'alert'
    when public.data_request_deadline(request) - public.romania_today() <= 7 then 'reminder'
    else 'on_time'
  end;
$$;


ALTER FUNCTION "public"."data_request_urgency"("request" "public"."data_requests") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."data_request_urgency"("request" "public"."data_requests") IS 'Internal: overdue, alert (2 days), reminder (7 days), on_time or closed (S1-E11-09, proposal).';



CREATE OR REPLACE FUNCTION "public"."decide_case"("target" "public"."cases", "chosen_action" "public"."moderation_action", "note_text" "text", "message_to_person" "text", "suspension_days" integer, "send_statement" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  sanction_id uuid;
  case_ground record;
begin
  -- Step 1: the decision row.
  insert into public.case_actions (case_id, user_id, action, note)
  values (target.id, (select auth.uid()), chosen_action, btrim(note_text));
  -- Step 2: carry the action out (S1-E10-06, S1-E10-08, QA-9). A sanction from a case gets no
  -- statement of its own: the case's statement covers it.
  if chosen_action in ('warn', 'suspend', 'ban') then
    sanction_id := public.admin_apply_sanction(target.user_id,
      case chosen_action when 'warn' then 'warning' when 'suspend' then 'suspension' else 'ban' end::public.sanction_kind,
      suspension_days, target.id, note_text, null);
  elsif chosen_action in ('hide', 'remove') then
    perform public.moderate_item(target.item_type, target.item_id, target.user_id,
      case chosen_action when 'hide' then 'hidden' else 'removed' end::public.moderated_state, target.id, note_text);
  elsif chosen_action = 'restrict' then
    -- A restricted story still opens from a link but leaves every list (S1-E11-08); the case
    -- note is the reason staff see on the story's admin page (the column allows 1,000 characters).
    insert into public.story_restrictions (user_id, story_id, restricted_by_user_id, reason)
    values (target.user_id, target.item_id, (select auth.uid()), left(btrim(note_text), 1000));
  elsif chosen_action = 'public_note' then
    perform public.add_copied_work_note(target);
  end if;
  -- Step 3: the statement of reasons (S1-E10-04), stored with the case.
  if chosen_action <> 'no_action' and send_statement then
    select * into case_ground from public.statement_ground_for_case(target);
    perform public.issue_statement_of_reasons(target.user_id, chosen_action::text::public.statement_action,
      case_ground.ground, case_ground.ground_key, message_to_person,
      jsonb_build_object('case_id', target.id, 'sanction_id', sanction_id, 'item_type', target.item_type,
        'item_id', target.item_id, 'automated_detection', target.source = 'picture_check',
        'restriction_ends_at', (select sanctions.ends_at from public.sanctions where sanctions.id = sanction_id)));
  end if;
  -- Step 4: the case and its reports; marking it decided tells the owner and the reporters.
  update public.cases set status = 'decided', decision = chosen_action, decided_at = now(),
    decided_by_user_id = (select auth.uid())
  where id = target.id;
  update public.reports set closed_at = now() where case_id = target.id and closed_at is null;
  -- Step 5: the audit row, in the same transaction.
  perform public.log_staff_action(
    'case.decided', 'cases', target.id::text, target.user_id, btrim(note_text),
    jsonb_build_object('status', 'open', 'tier', target.tier, 'top_reason', target.top_reason),
    jsonb_build_object('status', 'decided', 'action', chosen_action, 'suspension_days', suspension_days,
      'statement_sent', chosen_action <> 'no_action' and send_statement)
  );
end;
$$;


ALTER FUNCTION "public"."decide_case"("target" "public"."cases", "chosen_action" "public"."moderation_action", "note_text" "text", "message_to_person" "text", "suspension_days" integer, "send_statement" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decide_case"("target" "public"."cases", "chosen_action" "public"."moderation_action", "note_text" "text", "message_to_person" "text", "suspension_days" integer, "send_statement" boolean) IS 'Internal: decides one case: the action, the statement of reasons, the notifications and the audit row (S1-E10-03a, 06, 08, 04).';



CREATE OR REPLACE FUNCTION "public"."decide_space_join_request"("slug" "text", "handle" "text", "approve" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(decide_space_join_request.slug, 'members');
  request public.space_members := public.space_member_by_handle(space.id, decide_space_join_request.handle);
  outcome text;
begin
  -- Step 1: the waiting request by that username.
  if request.id is null or request.status <> 'pending' then
    raise exception 'There is no such request.' using errcode = 'no_data_found', hint = 'request:missing';
  end if;
  -- Step 2: a no, or a person no longer in the space's age group: the request goes.
  if not approve or public.space_age_group_of_person(request.user_id) is distinct from space.age_group then
    delete from public.space_members where space_members.id = request.id;
    outcome := case when approve then 'age_changed' else 'declined' end;
  else
    -- Step 3: a yes.
    update public.space_members set status = 'active', joined_at = now() where space_members.id = request.id;
    outcome := 'approved';
  end if;
  perform public.log_space_action(space, 'request_' || outcome, request.user_id, null, null);
  return jsonb_build_object('outcome', outcome);
end;
$$;


ALTER FUNCTION "public"."decide_space_join_request"("slug" "text", "handle" "text", "approve" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decide_space_join_request"("slug" "text", "handle" "text", "approve" boolean) IS 'Lets someone into a space or says no, for the owner and moderators with the members power; logged (S1-E8-06, S1-E8-07).';



