CREATE OR REPLACE FUNCTION "public"."decider_of_statement"("target" "public"."statements_of_reasons") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select cases.decided_by_user_id from public.cases where cases.id = target.case_id),
