COMMENT ON FUNCTION "public"."delete_account_data"("target_user_id" "uuid") IS 'Internal: deletes an account for good, keeping only what a case holds and the moderation records (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."delete_account_forum_posts"("target_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: threads only this person posted in, unless a case holds the thread or a post in it.
  delete from public.forum_threads
  where forum_threads.user_id = target_user_id
    and not exists (select 1 from public.forum_posts
                    where forum_posts.thread_id = forum_threads.id and forum_posts.user_id <> target_user_id)
    and not public.content_is_held_for_moderation('forum_thread', forum_threads.id)
    and not exists (select 1 from public.forum_posts
                    where forum_posts.thread_id = forum_threads.id
                      and public.content_is_held_for_moderation('forum_post', forum_posts.id));
  -- Step 2: the rest of their posts lose their words and earlier versions, unless held.
  delete from public.forum_post_revisions
  where forum_post_revisions.user_id = target_user_id
    and not public.content_is_held_for_moderation('forum_post', forum_post_revisions.post_id);
  update public.forum_posts set body = '', deleted_at = coalesce(forum_posts.deleted_at, now())
  where forum_posts.user_id = target_user_id
    and not public.content_is_held_for_moderation('forum_post', forum_posts.id);
end;
$$;


ALTER FUNCTION "public"."delete_account_forum_posts"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_account_forum_posts"("target_user_id" "uuid") IS 'Internal: deletes an account''s forum threads and erases its posts, keeping only what a case holds (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."delete_account_stories"("target_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: every chapter not held goes (its revisions, embeds, comments and likes with it).
  delete from public.chapters
  where chapters.user_id = target_user_id
    and not public.content_is_held_for_moderation('chapter', chapters.id);
  -- Step 2: the public "copies a published work" notes on stories that are going.
  delete from public.copied_work_notes
  using public.stories
  where stories.id = copied_work_notes.story_id and stories.user_id = target_user_id
    and not public.content_is_held_for_moderation('story', stories.id)
    and not exists (select 1 from public.chapters where chapters.story_id = stories.id);
  -- Step 3: every story not held and with no kept chapter goes (tags, follows, plans with it).
  delete from public.stories
  where stories.user_id = target_user_id
    and not public.content_is_held_for_moderation('story', stories.id)
    and not exists (select 1 from public.chapters where chapters.story_id = stories.id);
  -- Step 4: a kept story stays out of sight.
  update public.stories set deleted_at = coalesce(stories.deleted_at, now())
  where stories.user_id = target_user_id;
end;
$$;


ALTER FUNCTION "public"."delete_account_stories"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_account_stories"("target_user_id" "uuid") IS 'Internal: deletes an account''s stories and chapters, keeping only what a case holds (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."delete_bible_entry"("entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your story bible.' using errcode = 'insufficient_privilege';
  end if;
  delete from public.story_bible_entries
  where story_bible_entries.id = (public.my_bible_entry(entry_id)).id;
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


