CREATE OR REPLACE FUNCTION "public"."delete_comment"("comment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target public.comments;
  story_writer_id uuid;
begin
  -- Step 1: signed in, and the comment exists and isn't deleted yet.
  if caller_id is null then
    raise exception 'Log in to delete a comment.' using errcode = 'insufficient_privilege';
  end if;
  select * into target from public.comments where comments.id = comment_id and comments.deleted_at is null for update;
  if target.id is null then
    raise exception 'That comment isn''t there any more.' using errcode = 'no_data_found';
  end if;
  -- Step 2: the author, or the writer of the story it is on.
  select stories.user_id into story_writer_id
  from public.chapters join public.stories on stories.id = chapters.story_id
  where chapters.id = target.chapter_id;
  if caller_id <> target.user_id and caller_id is distinct from story_writer_id then
    raise exception 'Only its author or the story''s writer can delete a comment.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 3: the soft delete, saying who.
  update public.comments
  set deleted_at = now(),
      deleted_by = case when caller_id = target.user_id then 'author' else 'writer' end::public.comment_deleted_by
  where comments.id = target.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."delete_comment"("comment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_comment"("comment_id" "uuid") IS 'Deletes a comment: the author''s own, or any on the writer''s own story (S1-E6-01).';



CREATE OR REPLACE FUNCTION "public"."delete_conversation"("other_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_messaging_caller();
  other public.profiles;
  chat public.conversations;
begin
  -- Step 1: the person and the chat, even when a block hides them from each other.
  select * into other from public.profile_for_handle(other_handle);
  if other.id is not null then
    chat := public.conversation_between(caller_id, other.id);
  end if;
  if chat.id is null then
    raise exception 'There is no chat with that person.' using errcode = 'no_data_found';
  end if;
  -- Step 2: a request to the caller is answered, not deleted.
  if chat.status = 'request' and chat.recipient_user_id = caller_id then
    raise exception 'Answer the request instead.' using errcode = 'check_violation', hint = 'answer_request';
  end if;
  -- Step 3: the caller's own stamp; nothing changes for the other person.
  update public.conversation_members set deleted_at = now(), last_read_at = now()
    where conversation_members.conversation_id = chat.id and conversation_members.user_id = caller_id;
  return jsonb_build_object('deleted_at', now());
end;
$$;


ALTER FUNCTION "public"."delete_conversation"("other_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_conversation"("other_handle" "text") IS 'Delete chat: removes a chat for the caller only; gone for good once both delete it (S1-E9-04).';



CREATE OR REPLACE FUNCTION "public"."delete_forum_post"("post_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.forum_posts := public.own_forum_post_for_change(post_id);
  thread_goes boolean;
begin
  -- Step 1: the post becomes a marker.
  update public.forum_posts set deleted_at = now() where forum_posts.id = target.id;
  -- Step 2: the starter's #1 in a thread with no one else's live post takes the thread with it.
  thread_goes := target.post_number = 1 and not exists (
    select 1 from public.forum_posts
    where forum_posts.thread_id = target.thread_id and forum_posts.user_id <> target.user_id
      and forum_posts.deleted_at is null);
  if thread_goes then
    update public.forum_threads set deleted_at = now() where forum_threads.id = target.thread_id;
  end if;
  return jsonb_build_object('thread_deleted', thread_goes);
end;
$$;


ALTER FUNCTION "public"."delete_forum_post"("post_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_forum_post"("post_id" "uuid") IS 'Deletes the caller''s own post, keeping its number as a marker; #1 alone takes its thread (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."delete_marketing_detail"("story_slug" "text", "detail_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  current_details jsonb;
begin
  -- Step 1: a signed-in writer, their own planned story and one of its details.
  if (select auth.uid()) is null then
    raise exception 'Sign in to delete a detail.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  select own_details into current_details from public.story_marketing
  where story_id = target_story_id;
  if current_details is null or not exists (
      select 1 from jsonb_array_elements(current_details) as detail where detail ->> 'id' = detail_id) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the list again, in the same order, without this detail.
  update public.story_marketing
  set own_details = coalesce((
    select jsonb_agg(detail order by place)
    from jsonb_array_elements(current_details) with ordinality as listed(detail, place)
    where detail ->> 'id' <> detail_id), '[]'::jsonb)
  where story_id = target_story_id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."delete_marketing_detail"("story_slug" "text", "detail_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_marketing_detail"("story_slug" "text", "detail_id" "text") IS 'Deletes one of the caller''s own marketing details (GAPS-2b; S1-E17-29).';



CREATE OR REPLACE FUNCTION "public"."delete_my_story"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  purge_days integer := coalesce((public.setting_value('content_purge_days'))::integer, 30);
  deleted_time timestamptz := now();
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to delete a story.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Hidden at once: every reader path checks deleted_at; the owner still sees it for undo.
  update public.stories set deleted_at = deleted_time where stories.id = target_story_id;
  -- The chapters go with it, stamped with the same moment so undo brings back exactly these.
  update public.chapters set deleted_at = deleted_time
  where chapters.story_id = target_story_id and chapters.deleted_at is null;
  return jsonb_build_object('outcome', 'ok',
    'purge_on', ((deleted_time + make_interval(days => purge_days)) at time zone 'Europe/Bucharest')::date);
end;
$$;


ALTER FUNCTION "public"."delete_my_story"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_my_story"("story_slug" "text") IS 'Soft-deletes the caller''s own story; undo for content_purge_days (S1-E3-05).';



CREATE OR REPLACE FUNCTION "public"."delete_plan_act"("story_slug" "text", "act_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  target_act_id uuid;
  moved integer;
begin
  -- Step 1: a signed-in writer, their own live story and one of its acts.
  if (select auth.uid()) is null then
    raise exception 'Sign in to delete an act.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  -- (Looked up here, not with act_of_story(), which raises for an act of another story; here
  -- such an act is simply not found.)
  select acts.id into target_act_id from public.story_plan_acts as acts
  where acts.story_id = target_story_id and acts.id::text = act_id;
  if target_story_id is null or target_act_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: how many chapters will move to "No act", for the screen's message.
  select count(*) into moved from public.chapter_plans where chapter_plans.act_id = target_act_id;
  -- Step 3: the act goes; the foreign key clears it from its chapters' plans.
  delete from public.story_plan_acts where id = target_act_id;
  return jsonb_build_object('outcome', 'ok', 'chapters_moved', moved);
end;
$$;


ALTER FUNCTION "public"."delete_plan_act"("story_slug" "text", "act_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_plan_act"("story_slug" "text", "act_id" "text") IS 'Deletes one of the acts of the caller''s own story plan; its chapters move to "No act" (GAPS-2a; S1-E17-01).';



CREATE OR REPLACE FUNCTION "public"."delete_reading_list"("list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
begin
  if caller_id is null then
    raise exception 'Log in to delete a reading list.' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.reading_lists
                 where id = list_id and user_id = caller_id and deleted_at is null) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if public.content_is_held_for_moderation('reading_list', list_id) then
    update public.reading_lists set deleted_at = now(), is_public = false where id = list_id;
  else
    delete from public.reading_lists where id = list_id;
  end if;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


