COMMENT ON FUNCTION "public"."erase_closed_account"("target_user_id" "uuid") IS 'Internal: empties a deleted account''s profile and login, keeping the user ID so it is never reused (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."erase_unchecked_account"("target_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Mark it deleted first, so it is hidden everywhere while the rest goes.
  update public.profiles set deleted_at = coalesce(profiles.deleted_at, now())
  where profiles.id = target_user_id;
  -- Then the full deletion, which also removes the age check and consent rows.
  perform public.delete_account_data(target_user_id);
end;
$$;


ALTER FUNCTION "public"."erase_unchecked_account"("target_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."erase_unchecked_account"("target_user_id" "uuid") IS 'Internal: deletes an account whose age check or parental consent never came, like a deleted account (S1-E2-08b, S1-E13-04).';



CREATE OR REPLACE FUNCTION "public"."erase_unchecked_accounts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person record;
  erased integer := 0;
begin
  for person in
    select profiles.id from public.profiles
    join auth.users on users.id = profiles.id
    where profiles.deleted_at is null
      and coalesce(users.raw_app_meta_data ->> 'seed_persona', 'false') <> 'true'
      and (
        (users.created_at <= now() - interval '14 days'
          and public.account_state(profiles.id) in ('age_check_pending', 'age_check_failed')
          and not exists (
            select 1 from public.manual_age_checks
            where manual_age_checks.user_id = profiles.id and manual_age_checks.status = 'open'))
        or (public.parental_consent_deadline(profiles.id) <= now()
          and public.account_state(profiles.id) = 'awaiting_parental_consent'
          and not exists (
            select 1 from public.parental_consents
            where parental_consents.user_id = profiles.id and parental_consents.status = 'withdrawn')))
  loop
    perform public.erase_unchecked_account(person.id);
    erased := erased + 1;
  end loop;
  return erased;
end;
$$;


ALTER FUNCTION "public"."erase_unchecked_accounts"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."erase_unchecked_accounts"() IS 'Daily: erases accounts with no passed age check 14 days after sign-up (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."escalate_on_call_alerts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  escalated integer;
begin
  update public.on_call_alerts set escalated_at = now()
  where acknowledged_at is null and escalated_at is null
    and created_at <= now() - make_interval(mins => coalesce(public.setting_value('on_call_escalation_minutes'), '15'::jsonb)::text::integer);
  get diagnostics escalated = row_count;
  return escalated;
end;
$$;


