COMMENT ON FUNCTION "public"."featured_stories_now"() IS 'The Featured this week cards this reader may see, in the staff''s order; empty hides the band (S1-E5-10).';



CREATE OR REPLACE FUNCTION "public"."fill_ad_slot"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chosen jsonb;
  network_ad jsonb;
begin
  -- Step 1: the sponsor booked into this slot today, when the page matches its booking.
  chosen := public.booked_sponsor_ad_for_slot(wanted_slot_key, context, used_keys);
  -- Step 1b: an unbooked slot can still take a live campaign by its placement.
  if chosen is null and not public.ad_slot_is_booked(wanted_slot_key) then
    chosen := public.sponsor_ad_for_slot(wanted_slot_key, wanted_page_key, context, used_keys);
  end if;
  -- Step 2: the network's ad, unless this story's rating reasons bar it (SPONSORS-f).
  if not public.network_ads_barred(context) then
    network_ad := public.network_ad_for_slot(slot_format, used_keys);
  end if;
  -- Step 3: in order, our own house ads, the network, then our built-in ads.
  return coalesce(chosen,
    public.staff_house_ad_for_slot(wanted_slot_key, wanted_page_key, used_keys),
    public.landing_house_ad_for_slot(wanted_page_key, used_keys),
    network_ad,
    public.house_ad_for_slot(wanted_page_key, used_keys));
end;
$$;


ALTER FUNCTION "public"."fill_ad_slot"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fill_ad_slot"("wanted_slot_key" "text", "slot_format" "public"."ad_format", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) IS 'Internal: one ad slot''s ad in the fill order booked sponsor, house ad, network, built-in (S1-E12-05).';



CREATE OR REPLACE FUNCTION "public"."finish_data_export"("export_id" "uuid", "story_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_live_profile();
  open_export public.exports;
  stored_size bigint;
begin
  -- Step 1: the caller's own export, still being built, and not a staff copy.
  select * into open_export from public.exports
  where exports.id = finish_data_export.export_id and exports.user_id = caller_id
    and exports.state = 'building' and exports.kind <> 'data_request';
  if open_export.id is null then
    raise exception 'That export isn''t open.' using errcode = 'check_violation', hint = 'not_found';
  end if;
  -- Step 2: the file is really there; its size comes from storage, not from the browser.
  select (objects.metadata ->> 'size')::bigint into stored_size from storage.objects
  where objects.bucket_id = 'exports' and objects.name = open_export.file_name;
  if stored_size is null then
    raise exception 'The file hasn''t arrived.' using errcode = 'check_violation', hint = 'no_file';
  end if;
  -- Step 3: older copies of the same kind go; their files go with the nightly sweep (S1-E13-04)
  -- if the browser couldn't delete them.
  delete from public.exports
  where exports.user_id = caller_id and exports.kind = open_export.kind and exports.id <> open_export.id;
  -- Step 4: ready for seven days, and the in-app notice for its kind.
  update public.exports
  set state = 'ready', file_size = stored_size, ready_at = now(), expires_at = now() + interval '7 days',
      story_count = greatest(coalesce(finish_data_export.story_count, 0), 0)
  where exports.id = open_export.id
  returning * into open_export;
  if open_export.kind = 'my_stories' then
    perform public.notify(caller_id, 'stories_export_ready', null, '{}'::jsonb);
  else
    perform public.notify(caller_id, 'data_export_ready', null, '{}'::jsonb);
  end if;
  return jsonb_build_object('expires_at', open_export.expires_at);
end;
$$;


ALTER FUNCTION "public"."finish_data_export"("export_id" "uuid", "story_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finish_data_export"("export_id" "uuid", "story_count" integer) IS 'Marks the caller''s uploaded export ready for seven days and tells them (S1-E13-02, S1-E13-05).';



CREATE OR REPLACE FUNCTION "public"."finish_onboarding"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := public.require_live_profile();
begin
  if (select handle from public.profiles where id = caller) is null then
    raise exception 'Choose a username first.' using errcode = 'check_violation', hint = 'handle_missing';
  end if;
  update public.profiles set onboarded_at = coalesce(onboarded_at, now()) where id = caller;
end;
$$;


