CREATE OR REPLACE FUNCTION "public"."finish_social_sign_up"("sign_up_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := auth.uid();
begin
  -- Step 1: a signed-in provider account, with the buttons switched on.
  if caller is null then
    raise exception 'Sign in first.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_feature_enabled('social_login') then
    raise exception 'Sign-in with Google, Apple or Microsoft is off.' using errcode = 'feature_not_supported';
  end if;
  if exists (select 1 from public.profiles where profiles.id = caller) then
    return jsonb_build_object('outcome', 'finished');
  end if;
  if not public.unfinished_social_account(caller) then
    raise exception 'This account didn''t come from Google, Apple or Microsoft.' using errcode = 'check_violation';
  end if;

  -- Step 2: the same rules as a password sign-up; a refusal undoes everything this block did.
  begin
    perform public.create_profile_from_sign_up(caller, coalesce(sign_up_data, '{}'::jsonb));
  exception when check_violation or unique_violation then
    return jsonb_build_object('outcome', 'refused', 'rule', public.sign_up_rule_of(sqlerrm));
  end;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."finish_social_sign_up"("sign_up_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finish_social_sign_up"("sign_up_data" "jsonb") IS 'Gives a new Google, Apple or Microsoft account its profile after the sign-up rules (S1-E2-09).';



CREATE OR REPLACE FUNCTION "public"."finishes_story"("target_chapter" "public"."chapters", "read_percent" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select read_percent >= 95
    and exists (select 1 from public.stories
      where stories.id = target_chapter.story_id and stories.completion_status = 'completed')
    and not exists (select 1 from public.chapters as later
      where later.story_id = target_chapter.story_id and later.position > target_chapter.position
        and public.chapter_is_readable(later.id));
$$;


