COMMENT ON FUNCTION "public"."fold_look_alike_characters"("name" "text") IS 'Swaps non-ASCII look-alike characters for what they imitate, in lower case (Unicode TR39, S1-E2-04).';



CREATE OR REPLACE FUNCTION "public"."fold_old_daily_totals"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  cutoff date := (now() - make_interval(years => public.keep_setting('daily_totals_keep_years', 3)))::date;
  folded_reads integer;
  folded_shares integer;
begin
  -- Step 1: reads. Only chapters with more than one old row, so a folded total isn't rewritten.
  with old_rows as (
    delete from public.chapter_reads
    where chapter_reads.read_on < cutoff
      and chapter_reads.chapter_id in (select old.chapter_id from public.chapter_reads as old
                                       where old.read_on < cutoff
                                       group by old.chapter_id having count(*) > 1)
    returning chapter_reads.chapter_id, chapter_reads.read_on, chapter_reads.total)
  insert into public.chapter_reads (chapter_id, read_on, total)
  select old_rows.chapter_id, max(old_rows.read_on), sum(old_rows.total) from old_rows
  group by old_rows.chapter_id;
  get diagnostics folded_reads = row_count;
  -- Step 2: shares, the same way.
  with old_rows as (
    delete from public.chapter_shares
    where chapter_shares.shared_on < cutoff
      and chapter_shares.chapter_id in (select old.chapter_id from public.chapter_shares as old
                                        where old.shared_on < cutoff
                                        group by old.chapter_id having count(*) > 1)
    returning chapter_shares.chapter_id, chapter_shares.shared_on, chapter_shares.total)
  insert into public.chapter_shares (chapter_id, shared_on, total)
  select old_rows.chapter_id, max(old_rows.shared_on), sum(old_rows.total) from old_rows
  group by old_rows.chapter_id;
  get diagnostics folded_shares = row_count;
  return folded_reads + folded_shares;
end;
$$;


ALTER FUNCTION "public"."fold_old_daily_totals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fold_old_daily_totals"() IS 'Job: folds daily read and share totals older than daily_totals_keep_years (3) into one row per chapter (S1-E13-04).';



CREATE OR REPLACE FUNCTION "public"."follow_forum_thread"("thread_number" bigint, "wanted" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  thread public.forum_threads;
begin
  -- Step 1: only a signed-in member follows anything.
  if caller_id is null then
    raise exception 'Log in to follow a thread.' using errcode = 'insufficient_privilege';
  end if;
  select * into thread from public.forum_threads
  where forum_threads.thread_number = follow_forum_thread.thread_number;
  -- Step 2: unfollowing always works, even for a thread the caller can no longer open.
  if not coalesce(wanted, false) then
    delete from public.forum_thread_follows
    where forum_thread_follows.user_id = caller_id and forum_thread_follows.thread_id = thread.id;
    return false;
  end if;
  -- Step 3: following needs a thread the caller may open (the same rule as the thread page).
  if thread.id is null or not public.forum_thread_is_shown(thread) then
    raise exception 'That thread isn''t there any more.' using errcode = 'no_data_found', hint = 'thread:missing';
  end if;
  insert into public.forum_thread_follows (user_id, thread_id) values (caller_id, thread.id)
  on conflict on constraint forum_thread_follows_one_per_thread do nothing;
  return true;
end;
$$;


ALTER FUNCTION "public"."follow_forum_thread"("thread_number" bigint, "wanted" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."follow_forum_thread"("thread_number" bigint, "wanted" boolean) IS 'Follows or unfollows a forum thread for the caller; returns whether they follow it now (GAPS-16a).';



CREATE OR REPLACE FUNCTION "public"."follow_story"("story_slug" "text", "should_follow" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
begin
  -- Step 1: signed in.
  if caller_id is null then
    raise exception 'Log in to follow stories.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: unfollowing works on any story the person follows, even one they can no longer see.
  if not should_follow then
    delete from public.follows_stories
    using public.stories
    where stories.id = follows_stories.story_id and stories.slug = story_slug
      and follows_stories.user_id = caller_id;
    select stories.id into target_story_id from public.stories where stories.slug = story_slug;
    return jsonb_build_object('following', false,
      'follower_count', coalesce(public.story_follower_count_of(target_story_id), 0));
  end if;
  -- Step 3: the story, if the caller may read it and it has something published.
  select reader_visible_story.id into target_story_id from public.reader_visible_story(story_slug);
  if target_story_id is null or not public.story_has_readable_chapter(target_story_id) then
    raise exception 'There is no such story.' using errcode = 'no_data_found';
  end if;
  -- Step 4: the account gate, then follow; twice changes nothing.
  if not public.is_active_member() then
    raise exception 'Your account can''t follow anything right now.' using errcode = 'insufficient_privilege';
  end if;
  insert into public.follows_stories (user_id, story_id) values (caller_id, target_story_id)
  on conflict on constraint follows_stories_one_per_pair do nothing;
  return jsonb_build_object('following', true, 'follower_count', public.story_follower_count_of(target_story_id));
end;
$$;


ALTER FUNCTION "public"."follow_story"("story_slug" "text", "should_follow" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."follow_story"("story_slug" "text", "should_follow" boolean) IS 'Follows or unfollows a story by its address (S1-E6-05).';



CREATE OR REPLACE FUNCTION "public"."follow_writer"("target_handle" "text", "should_follow" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  writer public.profiles;
begin
  -- Step 1: signed in, and the writer exists (a writer who blocks the caller looks missing).
  if caller_id is null then
    raise exception 'Log in to follow writers.' using errcode = 'insufficient_privilege';
  end if;
  select * into writer from public.profile_for_handle(target_handle);
  if not found or exists (select 1 from public.blocks where blocks.user_id = writer.id and blocks.blocked_user_id = caller_id) then
    raise exception 'There is no account with that username.' using errcode = 'no_data_found';
  end if;
  if writer.id = caller_id then
    raise exception 'You can''t follow yourself.' using errcode = 'check_violation';
  end if;
  -- Step 2: unfollowing is always allowed, even for a read-only account.
  if not should_follow then
    delete from public.follows_users where follows_users.user_id = caller_id and follows_users.followed_user_id = writer.id;
    return jsonb_build_object('following', false, 'follower_count', public.follower_count_of(writer.id));
  end if;
  -- Step 3: following is a write, so the account gate applies (architecture 1.7.8).
  if not public.is_active_member() then
    raise exception 'Your account can''t follow anyone right now.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 4: a block either way: silently nothing (S1-E6-05, third criterion).
  if public.is_blocked_with(writer.id) then
    return jsonb_build_object('following', false, 'follower_count', public.follower_count_of(writer.id));
  end if;
  -- Step 5: follow; doing it twice changes nothing.
  insert into public.follows_users (user_id, followed_user_id) values (caller_id, writer.id)
  on conflict on constraint follows_users_one_per_pair do nothing;
  return jsonb_build_object('following', true, 'follower_count', public.follower_count_of(writer.id));
end;
$$;


ALTER FUNCTION "public"."follow_writer"("target_handle" "text", "should_follow" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."follow_writer"("target_handle" "text", "should_follow" boolean) IS 'Follows or unfollows a writer by username; a block makes it silently do nothing (S1-E6-05).';



