COMMENT ON FUNCTION "public"."forum_and_children"("top_forum_id" "uuid") IS 'Internal: a forum and every live forum inside it (S1-E8-04).';



CREATE TABLE IF NOT EXISTS "public"."forum_posts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "thread_id" "uuid" NOT NULL,
    "post_number" integer NOT NULL,
    "body" "text" NOT NULL,
    "edited_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "quoted_post_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "moved_from_thread_id" "uuid",
    CONSTRAINT "forum_posts_body_is_written" CHECK ((("char_length"("body") <= 20000) AND (("btrim"("body") <> ''::"text") OR ("deleted_at" IS NOT NULL)))),
    CONSTRAINT "forum_posts_number_positive" CHECK (("post_number" >= 1)),
    CONSTRAINT "forum_posts_quotes_bounded" CHECK (("cardinality"("quoted_post_ids") <= 50))
);


ALTER TABLE "public"."forum_posts" OWNER TO "postgres";


COMMENT ON TABLE "public"."forum_posts" IS 'kind: user_content; reportable: forum_post
Posts in forum threads, numbered in order (S1-E8-02). Read only through forum_thread().';



COMMENT ON COLUMN "public"."forum_posts"."post_number" IS 'The post''s place in its thread (#1, #2…), never reused.';



COMMENT ON COLUMN "public"."forum_posts"."edited_at" IS 'When its author last changed it; null when never.';



COMMENT ON COLUMN "public"."forum_posts"."quoted_post_ids" IS 'The posts this reply quotes, in thread order; drawn from the quoted posts as they are now (S1-E8-03).';



COMMENT ON COLUMN "public"."forum_posts"."moved_from_thread_id" IS 'The thread a space moderator moved this reply out of (GAPS-10); null for a reply that never moved.';



CREATE TABLE IF NOT EXISTS "public"."forum_threads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "forum_id" "uuid" NOT NULL,
    "thread_number" bigint NOT NULL,
    "title" "text" NOT NULL,
    "last_post_number" integer DEFAULT 0 NOT NULL,
    "last_post_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "is_sticky" boolean DEFAULT false NOT NULL,
    "locked_at" timestamp with time zone,
    "locked_by_user_id" "uuid",
    "lock_reason" "text",
    "bumped_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "answer_post_id" "uuid",
    "continues_in_thread_id" "uuid",
    CONSTRAINT "forum_threads_lock_is_whole" CHECK (((("locked_at" IS NULL) AND ("lock_reason" IS NULL)) OR (("locked_at" IS NOT NULL) AND ("lock_reason" IS NOT NULL) AND ("btrim"("lock_reason") <> ''::"text") AND ("char_length"("lock_reason") <= 500)))),
    CONSTRAINT "forum_threads_next_is_another" CHECK (("continues_in_thread_id" IS DISTINCT FROM "id")),
    CONSTRAINT "forum_threads_next_needs_lock" CHECK ((("continues_in_thread_id" IS NULL) OR ("locked_at" IS NOT NULL))),
    CONSTRAINT "forum_threads_title_is_written" CHECK ((("btrim"("title") <> ''::"text") AND ("char_length"("title") <= 300)))
);


ALTER TABLE "public"."forum_threads" OWNER TO "postgres";


COMMENT ON TABLE "public"."forum_threads" IS 'kind: user_content; reportable: forum_thread
Forum threads (S1-E8-02). Read only through forum_thread_list() and forum_thread().';



COMMENT ON COLUMN "public"."forum_threads"."thread_number" IS 'The public number in the thread''s address.';



COMMENT ON COLUMN "public"."forum_threads"."last_post_number" IS 'The number the latest post took; numbers are never reused.';



COMMENT ON COLUMN "public"."forum_threads"."last_post_at" IS 'When the latest post was written; orders the forum''s list (Q45).';



COMMENT ON COLUMN "public"."forum_threads"."is_sticky" IS 'Pinned to the top of its forum by a moderator (S1-E8-05).';



COMMENT ON COLUMN "public"."forum_threads"."locked_at" IS 'When a moderator locked it; null while open (S1-E8-05).';



COMMENT ON COLUMN "public"."forum_threads"."locked_by_user_id" IS 'The moderator who locked it; never shown, the thread says "the moderation team".';



COMMENT ON COLUMN "public"."forum_threads"."lock_reason" IS 'Why it was locked, shown on the thread (S1-E8-05).';



COMMENT ON COLUMN "public"."forum_threads"."bumped_at" IS 'When the thread last moved up its forum''s list; orders the list (Q45, S1-E8-05). A reply with "Don''t bump" leaves it.';



COMMENT ON COLUMN "public"."forum_threads"."answer_post_id" IS 'The reply the thread''s starter marked "This answered it"; null for none (IDEA-20261102-8).';



COMMENT ON COLUMN "public"."forum_threads"."continues_in_thread_id" IS 'Where the conversation carries on after this thread was locked (GAPS-9); null when nowhere.';



CREATE OR REPLACE FUNCTION "public"."forum_answer_post"("target" "public"."forum_threads") RETURNS "public"."forum_posts"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select forum_posts.* from public.forum_posts
  where forum_posts.id = target.answer_post_id
    and forum_posts.deleted_at is null
    and not public.is_moderated_away('forum_post', forum_posts.id);
$$;


