CREATE OR REPLACE FUNCTION "public"."forum_as_json"("target_forum_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select to_jsonb(forums) - 'created_at' - 'updated_at'
    || jsonb_build_object('names', coalesce((select jsonb_object_agg(forum_names.language_code,
        jsonb_build_object('name', forum_names.name, 'description', forum_names.description))
      from public.forum_names where forum_names.forum_id = forums.id), '{}'::jsonb))
  from public.forums where forums.id = target_forum_id;
$$;


ALTER FUNCTION "public"."forum_as_json"("target_forum_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_as_json"("target_forum_id" "uuid") IS 'Internal: a forum and its names as JSON for the audit log (FORUMS-1a).';



CREATE OR REPLACE FUNCTION "public"."forum_first_unread_post"("target" "public"."forum_threads") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select min(forum_posts.post_number)
  from public.forum_posts
  where forum_posts.thread_id = target.id
    and (select auth.uid()) is not null
    and forum_posts.user_id <> (select auth.uid())
    and forum_posts.created_at > public.forum_read_since(target.forum_id)
    and forum_posts.post_number > coalesce(
      (select reads.last_read_post_number from public.forum_thread_reads as reads
       where reads.user_id = (select auth.uid()) and reads.thread_id = target.id), 0)
    and public.forum_post_state_for_caller(forum_posts) = 'live';
$$;


ALTER FUNCTION "public"."forum_first_unread_post"("target" "public"."forum_threads") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_first_unread_post"("target" "public"."forum_threads") IS 'Internal: the first post of a thread new to the caller, or null (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."forum_has_unread"("target_forum_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when (select auth.uid()) is null then null else exists (
    select 1 from public.forum_threads
    where forum_threads.forum_id in (select public.forum_and_children(target_forum_id))
      and forum_threads.last_post_at > public.forum_read_since(forum_threads.forum_id)
      and public.forum_thread_is_shown(forum_threads)
      and public.forum_first_unread_post(forum_threads) is not null) end;
$$;


ALTER FUNCTION "public"."forum_has_unread"("target_forum_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_has_unread"("target_forum_id" "uuid") IS 'Internal: whether a forum or one inside it has new posts for the caller (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."forum_index"("language_code" "text") RETURNS TABLE("id" "uuid", "parent_id" "uuid", "level" smallint, "slug" "text", "position" integer, "is_pinned" boolean, "accent" "public"."forum_accent", "name" "text", "description" "text", "thread_count" bigint, "post_count" bigint, "latest_activity_at" timestamp with time zone, "latest_post" "jsonb", "has_unread" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select forums.id, forums.parent_id, forums.level, forums.slug, forums.position, forums.is_pinned,
    forums.accent, names.name, names.description,
    numbers.thread_count, numbers.post_count, latest.posted_at,
    case when latest.post_id is not null then jsonb_build_object(
      'thread_title', latest.thread_title,
      'thread_address', '/forums/' || forums.slug || '/' || latest.thread_number || '?post=' || latest.post_number,
      'writer_handle', latest.writer ->> 'handle',
      'writer_name', latest.writer ->> 'display_name',
      'is_staff', coalesce((latest.writer ->> 'is_staff')::boolean, false),
      'posted_at', latest.posted_at) end,
    public.forum_has_unread(forums.id)
  from public.forums
  cross join lateral public.forum_name_in(forums.id, forum_index.language_code) as names
  cross join lateral (
    select count(distinct live_threads.id) as thread_count, count(live_posts.id) as post_count
    from public.forum_threads as live_threads
    left join public.forum_posts as live_posts
      on live_posts.thread_id = live_threads.id and live_posts.deleted_at is null
    where live_threads.forum_id = forums.id and live_threads.deleted_at is null
  ) as numbers
  left join lateral (
    select newest.id as post_id, newest.post_number, newest.created_at as posted_at,
      thread.title as thread_title, thread.thread_number, public.forum_person_json(newest.user_id) as writer
    from public.forum_threads as thread
    join public.forum_posts as newest on newest.thread_id = thread.id
    where thread.forum_id = forums.id and public.forum_thread_is_shown(thread)
      and public.forum_post_state_for_caller(newest) = 'live'
    order by newest.created_at desc
    limit 1
  ) as latest on true
  where forums.deleted_at is null and forums.space_id is null;
$$;


ALTER FUNCTION "public"."forum_index"("language_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_index"("language_code" "text") IS 'The forum index in one language: every live forum with its numbers, latest post and whether it has new posts for the caller (S1-E8-01, S1-E8-02, S1-E8-04).';



