CREATE OR REPLACE FUNCTION "public"."forum_name_in"("target_forum_id" "uuid", "wanted_language" "text") RETURNS TABLE("name" "text", "description" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select forum_names.name, forum_names.description
  from public.forum_names
  where forum_names.forum_id = target_forum_id
