CREATE OR REPLACE FUNCTION "public"."forum_name_problems"("names" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select array(
    select languages.code || ':empty' from public.languages
    where languages.is_interface and coalesce(btrim(names -> languages.code ->> 'name'), '') = ''
    union all
    select given.key || ':unknown_language' from jsonb_each(coalesce(names, '{}')) as given
    where not exists (select 1 from public.languages where languages.code = given.key)
    union all
    select given.key || ':too_long' from jsonb_each(coalesce(names, '{}')) as given
    where char_length(btrim(coalesce(given.value ->> 'name', ''))) > 80
    union all
    select given.key || ':description_too_long' from jsonb_each(coalesce(names, '{}')) as given
    where char_length(btrim(coalesce(given.value ->> 'description', ''))) > 200
  );
$$;


ALTER FUNCTION "public"."forum_name_problems"("names" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_name_problems"("names" "jsonb") IS 'Internal: what is wrong with a forum''s names (FORUMS-1a).';



CREATE OR REPLACE FUNCTION "public"."forum_new_for_you"("how_many" integer DEFAULT 5, "language_code" "text" DEFAULT 'ro'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(item order by (item ->> 'last_post_at')::timestamptz desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'title', forum_threads.title,
      'forum_name', (select names.name from public.forum_name_in(forums.id, forum_new_for_you.language_code) as names),
      'forum_slug', forums.slug,
      'number', forum_threads.thread_number,
      'first_unread_post', public.forum_first_unread_post(forum_threads),
      'new_count', public.forum_unread_post_count(forum_threads),
      'last_post_at', forum_threads.last_post_at) as item
    from public.forum_threads
    join public.forums on forums.id = forum_threads.forum_id
    where (select auth.uid()) is not null
      and forum_threads.last_post_at > public.forum_read_since(forum_threads.forum_id)
      and public.forum_thread_is_shown(forum_threads)
      and public.forum_first_unread_post(forum_threads) is not null
    order by forum_threads.last_post_at desc
    limit least(greatest(coalesce(how_many, 5), 1), 20)
  ) as unread;
$$;


ALTER FUNCTION "public"."forum_new_for_you"("how_many" integer, "language_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_new_for_you"("how_many" integer, "language_code" "text") IS 'The threads with new posts for the caller, newest first, each with its first new post (S1-E8-04).';



