    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'handle', profiles.handle,
    'display_name', public.display_name(profiles.handle, profiles.pen_name),
    'is_staff', exists (select 1 from public.staff_roles where staff_roles.user_id = profiles.id))
  from public.profiles
  where profiles.id = person_id and profiles.deleted_at is null;
$$;


ALTER FUNCTION "public"."forum_person_json"("person_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_person_json"("person_id" "uuid") IS 'Internal: a username, display name and Staff pill; null for a deleted account (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."forum_post_history"("post_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('moderation', 'view') then
    raise exception 'Only moderators can see earlier versions.' using errcode = 'insufficient_privilege';
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'body', revisions.body, 'title', revisions.title, 'written_at', revisions.written_at)
      order by revisions.written_at), '[]'::jsonb)
    from public.forum_post_revisions as revisions
    where revisions.post_id = forum_post_history.post_id);
end;
$$;


ALTER FUNCTION "public"."forum_post_history"("post_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_history"("post_id" "uuid") IS 'The earlier versions of an edited post, for moderation staff only (S1-E8-02 criterion 4).';



CREATE OR REPLACE FUNCTION "public"."forum_post_is_space_hidden"("target" "public"."forum_posts") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.moderated_items
                 where moderated_items.item_type = 'forum_post' and moderated_items.item_id = target.id
                   and moderated_items.restored_at is null and moderated_items.space_id is not null);
$$;


ALTER FUNCTION "public"."forum_post_is_space_hidden"("target" "public"."forum_posts") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_is_space_hidden"("target" "public"."forum_posts") IS 'Internal: true when a space''s moderators (not our team) hid the post (GAPS-10).';



CREATE OR REPLACE FUNCTION "public"."forum_post_json"("target" "public"."forum_posts", "starter_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  state text := public.forum_post_state_for_caller(target);
  is_own boolean := caller_id is not null and target.user_id = caller_id;
  is_shown boolean := state in ('live', 'hidden');
  is_space_hidden boolean := public.forum_post_is_space_hidden(target);
  space public.spaces := public.space_of_post(target);
begin
  return jsonb_build_object(
    'id', target.id,
    'number', target.post_number,
    'author', public.forum_person_json(target.user_id),
    'is_starter', target.user_id = starter_id,
    'is_mine', is_own,
    'created_at', target.created_at,
    'edited_at', target.edited_at,
    'state', state,
    'body', case when is_shown then target.body end,
    'quotes', case when is_shown then (
      select coalesce(jsonb_agg(public.forum_quote_json(quoted_id) order by position), '[]'::jsonb)
      from unnest(target.quoted_post_ids) with ordinality as quoted(quoted_id, position)
      where public.forum_quote_json(quoted_id) is not null) else '[]'::jsonb end,
    'can_edit', is_own and is_shown,
    'can_delete', is_own and is_shown,
    'has_history', target.edited_at is not null and caller_id is not null
      and public.staff_may('moderation', 'view'),
    -- S1-E8-08: the author's signature, under the post on bigger screens (Q25).
    'signature', case when is_shown then public.signature_json(target.user_id) end,
    -- S1-E8-09: the author's rank, a chip next to their name (null before a published chapter).
    'author_rank', public.rank_of(target.user_id),
    -- IDEAS-3f: whether this reply is the thread's marked answer, and whether the caller (the
    -- thread's starter) may mark it: a live reply by someone else (criteria 1 and 2).
    'is_answer', target.id = (select forum_threads.answer_post_id from public.forum_threads
                              where forum_threads.id = target.thread_id),
    'can_mark_answer', is_own is false and caller_id is not null and caller_id = starter_id
                       and target.post_number > 1 and state = 'live',
    -- GAPS-10: who hid a hidden post, whether it was moved here, and the space moderators' tools.
    'hidden_by', case when state is distinct from 'hidden' then null when is_space_hidden then 'space' else 'team' end,
    'was_moved', is_shown and target.moved_from_thread_id is not null,
    'can_space_moderate', coalesce(
      caller_id is not null and is_shown and target.post_number > 1
      and space.id is not null and public.space_may_act(space, 'posts')
      and (state = 'live' or is_space_hidden)
      and (target.user_id <> space.user_id or space.user_id = caller_id
           or public.space_acts_as_platform(space)), false));
end;
$$;


ALTER FUNCTION "public"."forum_post_json"("target" "public"."forum_posts", "starter_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_json"("target" "public"."forum_posts", "starter_id" "uuid") IS 'Internal: one post as the thread page draws it, with its quotes and its author''s signature and rank, never a user ID (S1-E8-02, S1-E8-03, S1-E8-08, S1-E8-09).';



CREATE OR REPLACE FUNCTION "public"."forum_post_search_text"("target" "public"."forum_posts", "thread_title" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select public.search_fold(concat_ws(' ', case when target.post_number = 1 then thread_title end, target.body));
$$;


ALTER FUNCTION "public"."forum_post_search_text"("target" "public"."forum_posts", "thread_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_search_text"("target" "public"."forum_posts", "thread_title" "text") IS 'Internal: a forum post''s words (and #1''s thread title), folded for search (S1-E8-10).';



CREATE OR REPLACE FUNCTION "public"."forum_post_state_for_caller"("target" "public"."forum_posts") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  moderated public.moderated_state := public.moderated_state_of('forum_post', target.id);
begin
  -- Step 1: an author the caller blocks, or who blocks them: nothing at all.
  if public.is_blocked_with(target.user_id) then
    return null;
  end if;
  -- Step 2: deleted by its author, or removed by staff: a marker.
  if target.deleted_at is not null then
    return 'deleted';
  end if;
  if moderated = 'removed' then
    return 'removed';
  end if;
  -- Step 3: hidden: the author still sees it; so do the space's moderators when the hide is
  -- theirs; for everyone else it is gone.
  if moderated = 'hidden' then
    return case when target.user_id = (select auth.uid()) then 'hidden'
                when public.forum_post_is_space_hidden(target)
                     and public.space_may_act(public.space_of_post(target), 'posts') then 'hidden' end;
  end if;
  return 'live';
end;
$$;


ALTER FUNCTION "public"."forum_post_state_for_caller"("target" "public"."forum_posts") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_state_for_caller"("target" "public"."forum_posts") IS 'Internal: live, hidden, removed, deleted or null for the caller (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."forum_post_wait_minutes"("author_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_account_hours integer := coalesce((public.setting_value('comment_new_account_hours'))::integer, 24);
  hourly_limit integer;
  oldest_in_window timestamptz;
  posted_in_window integer;
begin
  -- Step 1: the limit for this account's age.
  select case when profiles.created_at > now() - make_interval(hours => new_account_hours)
    then coalesce((public.setting_value('forum_post_hourly_limit_new_account'))::integer, 5)
    else coalesce((public.setting_value('forum_post_hourly_limit'))::integer, 60) end
  into hourly_limit
  from public.profiles where profiles.id = author_id;
  -- Step 2: what they posted in the last hour.
  select count(*)::integer, min(forum_posts.created_at) into posted_in_window, oldest_in_window
  from public.forum_posts
  where forum_posts.user_id = author_id and forum_posts.created_at > now() - interval '1 hour';
  if posted_in_window < hourly_limit then
    return 0;
  end if;
  -- Step 3: the minutes until the oldest of them is an hour old.
  return greatest(1, ceil(extract(epoch from (oldest_in_window + interval '1 hour' - now())) / 60.0))::integer;
end;
$$;


ALTER FUNCTION "public"."forum_post_wait_minutes"("author_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_post_wait_minutes"("author_id" "uuid") IS 'Internal: minutes until the author may post in the forums again, 0 when now (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."forum_quote_json"("quoted_post_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  quoted public.forum_posts;
  state text;
begin
  select * into quoted from public.forum_posts where forum_posts.id = quoted_post_id;
  if quoted.id is null then
    return null;
  end if;
  -- The author's own hidden post isn't quoted back to them as live: quoting shows only what everyone sees.
  state := public.forum_post_state_for_caller(quoted);
  if state is null or state = 'hidden' then
    state := 'unavailable';
  end if;
  return jsonb_build_object(
    'number', quoted.post_number,
    'author', case when state = 'unavailable' then null else public.forum_person_json(quoted.user_id) end,
    'state', state,
    'body', case when state = 'live' then quoted.body end)
    -- GAPS-10: where the quoted post is now; left out of a quote the caller can't see.
    || case when state = 'unavailable' then '{}'::jsonb else (
         select jsonb_build_object('thread_number', forum_threads.thread_number, 'forum_slug', forums.slug)
         from public.forum_threads join public.forums on forums.id = forum_threads.forum_id
         where forum_threads.id = quoted.thread_id) end;
end;
$$;


ALTER FUNCTION "public"."forum_quote_json"("quoted_post_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_quote_json"("quoted_post_id" "uuid") IS 'Internal: one quoted post as a reply draws it, never a user ID (S1-E8-03).';



CREATE OR REPLACE FUNCTION "public"."forum_quotes_for_reply"("target_thread_id" "uuid", "wanted" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  distinct_wanted uuid[];
  ordered uuid[];
  most integer := coalesce((select (value #>> '{}')::integer from public.settings where key = 'forum_post_max_quotes'), 10);
begin
  -- Step 1: nothing to quote is fine.
  select coalesce(array_agg(distinct id), '{}') into distinct_wanted
  from unnest(coalesce(wanted, '{}')) as id
  where id is not null;
  if cardinality(distinct_wanted) = 0 then
    return '{}';
  end if;
  -- Step 2: the limit.
  if cardinality(distinct_wanted) > most then
    raise exception 'A reply can quote at most % posts.', most
      using errcode = 'check_violation', hint = 'quote:too_many';
  end if;
  -- Step 3: only live posts of this thread, as the caller sees them, in thread order.
  select coalesce(array_agg(forum_posts.id order by forum_posts.post_number), '{}') into ordered
  from public.forum_posts
  where forum_posts.id = any (distinct_wanted)
    and forum_posts.thread_id = target_thread_id
    and public.forum_post_state_for_caller(forum_posts) = 'live';
  if cardinality(ordered) <> cardinality(distinct_wanted) then
    raise exception 'A post you quoted isn''t there any more.'
      using errcode = 'check_violation', hint = 'quote:missing';
  end if;
  return ordered;
end;
$$;


ALTER FUNCTION "public"."forum_quotes_for_reply"("target_thread_id" "uuid", "wanted" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_quotes_for_reply"("target_thread_id" "uuid", "wanted" "uuid"[]) IS 'Internal: checks a reply''s quotes and puts them in thread order (S1-E8-03).';



CREATE OR REPLACE FUNCTION "public"."forum_read_since"("target_forum_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select greatest(
    profiles.created_at,
    (select marks.marked_at from public.forum_read_marks as marks
     where marks.user_id = profiles.id and marks.forum_id is null),
    (select marks.marked_at from public.forum_read_marks as marks
     where marks.user_id = profiles.id and marks.forum_id = target_forum_id))
  from public.profiles
  where profiles.id = (select auth.uid());
$$;


ALTER FUNCTION "public"."forum_read_since"("target_forum_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_read_since"("target_forum_id" "uuid") IS 'Internal: when a forum counts as read up to, for the caller (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."forum_search_snippet"("body" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- Step 1: drop the Markdown subset's marks (bold, italic, quotes, lists, link brackets) and
  -- join the lines, so the result reads as plain text.
  -- Step 2: cut at 240 characters.
  select case when char_length(plain.text) > 240 then left(plain.text, 239) || '…' else plain.text end
  from (select btrim(regexp_replace(regexp_replace(body, '[*_`>#\[\]]', '', 'g'), '\s+', ' ', 'g')) as text) as plain;
$$;


ALTER FUNCTION "public"."forum_search_snippet"("body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_search_snippet"("body" "text") IS 'Internal: a forum post''s words as a short plain result line (S1-E8-10).';



CREATE OR REPLACE FUNCTION "public"."forum_thread"("thread_number" bigint, "after_post" integer DEFAULT 0, "up_to_post" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads;
  page_size integer := coalesce((public.setting_value('forum_posts_page_size'))::integer, 20);
  wanted integer;
  page jsonb;
  last_number integer;
begin
  -- Step 1: the thread, if the caller may open it.
  select * into thread from public.forum_threads where forum_threads.thread_number = forum_thread.thread_number;
  if thread.id is null or not public.forum_thread_is_shown(thread) then
    return null;
  end if;
  -- Step 2: how far to read: a page, or as far as the permalink's post.
  wanted := greatest(page_size, coalesce(up_to_post, 0) - coalesce(after_post, 0));
  -- Step 3: the posts after after_post, in number order, without the ones the caller can't see.
  with listed as (
    select forum_posts.* from public.forum_posts
    where forum_posts.thread_id = thread.id
      and forum_posts.post_number > coalesce(after_post, 0)
      and public.forum_post_state_for_caller(forum_posts) is not null
    order by forum_posts.post_number
    limit wanted
  )
  select coalesce(jsonb_agg(public.forum_post_json(listed, thread.user_id) order by listed.post_number), '[]'::jsonb),
         max(listed.post_number)
  into page, last_number
  from listed;
  -- Step 4: more when a visible post comes after the last one read.
  return jsonb_build_object(
    'thread', public.forum_thread_header_json(thread),
    'posts', page,
    'has_more', exists (select 1 from public.forum_posts
                        where forum_posts.thread_id = thread.id
                          and forum_posts.post_number > coalesce(last_number, coalesce(after_post, 0))
                          and public.forum_post_state_for_caller(forum_posts) is not null));
end;
$$;


ALTER FUNCTION "public"."forum_thread"("thread_number" bigint, "after_post" integer, "up_to_post" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread"("thread_number" bigint, "after_post" integer, "up_to_post" integer) IS 'A thread with its numbered posts in order, for the thread page; never a user ID (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_follow_on_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  follower record;
begin
  -- Step 1: a new thread is followed by the person who started it.
  if new.post_number = 1 then
    insert into public.forum_thread_follows (user_id, thread_id)
    values (new.user_id, new.thread_id)
    on conflict on constraint forum_thread_follows_one_per_thread do nothing;
    return null;
  end if;
  -- Step 2: a reply reaches every other follower, one grouped row per thread a day.
  for follower in
    select follows.user_id from public.forum_thread_follows as follows
    where follows.thread_id = new.thread_id and follows.user_id <> new.user_id
  loop
    perform public.notify(follower.user_id, 'forum_reply', new.user_id,
      jsonb_build_object('forum_thread_id', new.thread_id),
      'forum_reply:' || new.thread_id::text, interval '24 hours');
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."forum_thread_follow_on_post"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_follow_on_post"() IS 'Trigger: a thread''s starter follows it; a reply tells the other followers (GAPS-16a).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_for_moderation"("thread_number" bigint, "reason" "text") RETURNS "public"."forum_threads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads;
  space public.spaces;
begin
  -- Step 1: the live thread, locked for the change.
  select * into thread from public.forum_threads
  where forum_threads.thread_number = forum_thread_for_moderation.thread_number and forum_threads.deleted_at is null
  for update;
  space := public.space_of_forum(thread.forum_id);
  -- Step 2: moderation staff, or someone with the posts power in the thread's space.
  if not (public.staff_may('moderation', 'act') or (space.id is not null and public.space_may_act(space, 'posts'))) then
    raise exception 'Only moderators can do that.' using errcode = 'insufficient_privilege';
  end if;
  if thread.id is null then
    raise exception 'That thread isn''t there any more.' using errcode = 'no_data_found', hint = 'thread:missing';
  end if;
  -- Step 3: every change needs a reason (architecture 1.8.4).
  if reason is null or btrim(reason) = '' then
    raise exception 'Say why.' using errcode = 'check_violation', hint = 'reason:empty';
  end if;
  if char_length(btrim(reason)) > 500 then
    raise exception 'Keep the reason under 500 characters.' using errcode = 'check_violation', hint = 'reason:too_long';
  end if;
  return thread;
end;
$$;


ALTER FUNCTION "public"."forum_thread_for_moderation"("thread_number" bigint, "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_for_moderation"("thread_number" bigint, "reason" "text") IS 'Internal: a live thread for moderation staff, or a space moderator with the posts power, to change (S1-E8-05, S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_header_json"("target" "public"."forum_threads") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', target.id,
    'number', target.thread_number,
    'title', target.title,
    'forum_slug', (select forums.slug from public.forums where forums.id = target.forum_id),
    'space', (select jsonb_build_object('slug', space.slug, 'name', space.name)
              from public.space_of_forum(target.forum_id) as space where space.id is not null),
    'author', public.forum_person_json(target.user_id),
    'is_mine', target.user_id = (select auth.uid()),
    -- GAPS-16a: whether the reader follows this thread (false when signed out).
    'is_following', exists (select 1 from public.forum_thread_follows as follows
                            where follows.thread_id = target.id
                              and follows.user_id = (select auth.uid())),
    'state', case when public.moderated_state_of('forum_thread', target.id) = 'hidden' then 'hidden' else 'live' end,
    'created_at', target.created_at,
    'reply_count', greatest(public.forum_live_post_count(target.id) - 1, 0),
    'writer_count', (select count(distinct forum_posts.user_id)::integer from public.forum_posts
                     where forum_posts.thread_id = target.id
                       and public.forum_post_state_for_caller(forum_posts) in ('live', 'hidden')),
    'last_post_at', target.last_post_at,
    'last_post_number', target.last_post_number,
    'is_sticky', target.is_sticky,
    'lock', case when target.locked_at is null then null
                 else jsonb_build_object('locked_at', target.locked_at, 'reason', target.lock_reason,
                                         -- GAPS-9: where the conversation carries on.
                                         'next', public.forum_thread_pointer_json(target.continues_in_thread_id)) end,
    'can_reply', (select auth.uid()) is not null and target.locked_at is null and public.is_active_member()
                 and coalesce((select public.space_may_post(space) from public.space_of_forum(target.forum_id) as space
                               where space.id is not null), true),
    -- IDEAS-3f: the reply that answered it, linked at the top of the thread (criterion 1).
    'answer', (select jsonb_build_object('number', answer.post_number,
                                         'author', public.forum_person_json(answer.user_id))
               from public.forum_answer_post(target) as answer where answer.id is not null),
    'can_moderate', (select auth.uid()) is not null and (
                      public.staff_may('moderation', 'act')
                      or coalesce((select public.space_may_act(space, 'posts') from public.space_of_forum(target.forum_id) as space
                                   where space.id is not null), false)),
    -- GAPS-9: this thread is the forum's rules thread.
    'is_rules', exists (select 1 from public.forums
                        where forums.id = target.forum_id and forums.rules_thread_id = target.id),
    -- GAPS-9: the forum's rules thread, for the strip above every other thread of the forum.
    'rules', (select public.forum_thread_pointer_json(rules_thread.id)
              from public.forums
              join public.forum_threads as rules_thread on rules_thread.id = forums.rules_thread_id
              where forums.id = target.forum_id and rules_thread.id <> target.id
                and rules_thread.forum_id = forums.id));
$$;


ALTER FUNCTION "public"."forum_thread_header_json"("target" "public"."forum_threads") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_header_json"("target" "public"."forum_threads") IS 'Internal: a thread''s heading, numbers, sticky, lock, rules strip, pointer and whether the reader follows it, never a user ID (S1-E8-02, S1-E8-05, GAPS-9, GAPS-16a).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_is_shown"("target" "public"."forum_threads") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target.deleted_at is null
    and exists (select 1 from public.forums where forums.id = target.forum_id and forums.deleted_at is null
                  and (forums.space_id is null or public.space_may_read(public.space_of_forum(forums.id))))
    and not public.is_blocked_with(target.user_id)
    and (
      not public.is_moderated_away('forum_thread', target.id)
      or (target.user_id = (select auth.uid()) and public.moderated_state_of('forum_thread', target.id) = 'hidden')
    );
$$;


ALTER FUNCTION "public"."forum_thread_is_shown"("target" "public"."forum_threads") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_is_shown"("target" "public"."forum_threads") IS 'Internal: whether the caller may open a thread (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_list"("forum_slug" "text", "older_than" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  forum public.forums;
  page_size integer := coalesce((public.setting_value('forum_threads_page_size'))::integer, 25);
  pinned jsonb := '[]'::jsonb;
  page jsonb;
  page_count integer;
begin
  -- Step 1: the forum, if it is live.
  select * into forum from public.forums where forums.slug = forum_thread_list.forum_slug and forums.deleted_at is null;
  if forum.id is null then
    return null;
  end if;
  -- Step 2: on the first page only, every sticky thread the caller may open, latest first.
  if older_than is null then
    select coalesce(jsonb_agg(public.forum_thread_summary_json(forum_threads) order by forum_threads.bumped_at desc), '[]'::jsonb)
    into pinned
    from public.forum_threads
    where forum_threads.forum_id = forum.id and forum_threads.is_sticky
      and public.forum_thread_is_shown(forum_threads);
  end if;
  -- Step 3: one page of the other threads (one extra, to know whether there is more).
  with listed as (
    select forum_threads.* from public.forum_threads
    where forum_threads.forum_id = forum.id
      and not forum_threads.is_sticky
      and (older_than is null or forum_threads.bumped_at < older_than)
      and public.forum_thread_is_shown(forum_threads)
    order by forum_threads.bumped_at desc
    limit page_size + 1
  )
  select coalesce(jsonb_agg(public.forum_thread_summary_json(listed) order by listed.bumped_at desc), '[]'::jsonb),
         count(*)::integer
  into page, page_count
  from listed;
  -- Step 4: the answer; the extra thread only says there is more.
  if page_count > page_size then
    page := page - page_size;
  end if;
  return jsonb_build_object('threads', pinned || page, 'has_more', page_count > page_size);
end;
$$;


ALTER FUNCTION "public"."forum_thread_list"("forum_slug" "text", "older_than" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_list"("forum_slug" "text", "older_than" timestamp with time zone) IS 'One page of a forum''s threads, sticky first, then latest activity; never a user ID (S1-E8-02, S1-E8-05).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_pointer_json"("pointed_thread_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'number', pointed.thread_number,
    'title', pointed.title,
    'forum_slug', (select forums.slug from public.forums where forums.id = pointed.forum_id),
    'summary', (select public.forum_search_snippet(first_post.body) from public.forum_posts as first_post
                where first_post.thread_id = pointed.id and first_post.post_number = 1
                  and public.forum_post_state_for_caller(first_post) = 'live'),
    'is_locked', pointed.locked_at is not null)
  from public.forum_threads as pointed
  where pointed.id = pointed_thread_id and public.forum_thread_is_shown(pointed);
$$;


ALTER FUNCTION "public"."forum_thread_pointer_json"("pointed_thread_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_pointer_json"("pointed_thread_id" "uuid") IS 'Internal: a thread as another links to it, or null when the caller may not open it (GAPS-9).';



CREATE OR REPLACE FUNCTION "public"."forum_thread_summary_json"("target" "public"."forum_threads") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  first_unread integer := public.forum_first_unread_post(target);
begin
  return jsonb_build_object(
    'number', target.thread_number,
    'title', target.title,
    'author', public.forum_person_json(target.user_id),
    'created_at', target.created_at,
    'reply_count', greatest(public.forum_live_post_count(target.id) - 1, 0),
    'last_post_at', target.last_post_at,
    'bumped_at', target.bumped_at,
    'last_poster', (select public.forum_person_json(latest.user_id) from public.forum_posts as latest
                    where latest.thread_id = target.id
                      and public.forum_post_state_for_caller(latest) in ('live', 'hidden')
                    order by latest.post_number desc limit 1),
    'is_unread', case when (select auth.uid()) is null then null else first_unread is not null end,
    'first_unread_post', first_unread,
    'is_sticky', target.is_sticky,
    'is_locked', target.locked_at is not null,
    -- IDEAS-3f: the starter marked a reply that answered it, and that reply can still be read.
    'is_answered', (public.forum_answer_post(target)).id is not null);
end;
$$;


ALTER FUNCTION "public"."forum_thread_summary_json"("target" "public"."forum_threads") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_thread_summary_json"("target" "public"."forum_threads") IS 'Internal: one thread as a forum''s list shows it, with whether it is new, pinned or locked; never a user ID (S1-E8-02, S1-E8-04, S1-E8-05).';



CREATE OR REPLACE FUNCTION "public"."forum_unread_post_count"("target" "public"."forum_threads") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::integer
  from public.forum_posts
  where forum_posts.thread_id = target.id
    and (select auth.uid()) is not null
    and forum_posts.user_id <> (select auth.uid())
    and forum_posts.created_at > public.forum_read_since(target.forum_id)
    and forum_posts.post_number > coalesce(
      (select reads.last_read_post_number from public.forum_thread_reads as reads
       where reads.user_id = (select auth.uid()) and reads.thread_id = target.id), 0)
    and public.forum_post_state_for_caller(forum_posts) = 'live';
$$;


ALTER FUNCTION "public"."forum_unread_post_count"("target" "public"."forum_threads") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forum_unread_post_count"("target" "public"."forum_threads") IS 'Internal: how many posts of a thread are new to the caller (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."forums_set_level"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  parent public.forums;
begin
  -- Step 1: a forum with forums inside it keeps its place in the tree.
  if tg_op = 'UPDATE' and new.parent_id is distinct from old.parent_id
     and exists (select 1 from public.forums where forums.parent_id = new.id and forums.deleted_at is null) then
    raise exception 'Move the forums inside it first.' using errcode = 'check_violation', hint = 'parent:has_children';
  end if;
  -- Step 2: a space's forum stands alone and holds threads, so it counts as a forum (level 1);
  -- a category has no parent.
  if new.space_id is not null and new.parent_id is null then
    new.level := 1;
    return new;
  end if;
  if new.parent_id is null then
    new.level := 0;
    return new;
  end if;
  -- Step 3: one level below a live staff forum, never below a subforum or a space's forum.
  select * into parent from public.forums where forums.id = new.parent_id and forums.deleted_at is null;
  if parent.id is null then
    raise exception 'The forum it should sit in doesn''t exist.' using errcode = 'check_violation', hint = 'parent:missing';
  end if;
  if parent.space_id is not null or new.space_id is not null then
    raise exception 'A space''s forum stands on its own.' using errcode = 'check_violation', hint = 'parent:space';
  end if;
  if parent.level >= 2 then
    raise exception 'A subforum can''t hold forums.' using errcode = 'check_violation', hint = 'parent:too_deep';
  end if;
  new.level := parent.level + 1;
  return new;
end;
$$;


ALTER FUNCTION "public"."forums_set_level"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."forums_set_level"() IS 'Trigger: sets a forum''s level from its parent; at most category, forum, subforum (FORUMS-1a).';



CREATE OR REPLACE FUNCTION "public"."generate_invite_code"() RETURNS "text"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  with letters as (
    select get_byte(extensions.gen_random_bytes(12), position - 1) % 32 as index, position
    from generate_series(1, 12) as position
  ),
  code as (
    select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', index + 1, 1), '' order by position) as text
    from letters
  )
  select substr(text, 1, 4) || '-' || substr(text, 5, 4) || '-' || substr(text, 9, 4) from code;
$$;


ALTER FUNCTION "public"."generate_invite_code"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_invite_code"() IS 'Internal: a random 12-character invite code without look-alike letters (S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."get_chapter"("story_slug" "text", "chapter_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  story public.stories;
  chapter public.chapters;
  readable_codes text[];
  place integer;
  text_to_send text;
  teaser_words integer;
  app_only boolean;
begin
  -- Step 1: the story, if this caller may read it (age, blocks, deleted, moderated).
  select * into story from public.reader_visible_story(story_slug);
  if not found then
    return null;
  end if;
  -- Step 2: the chapter, published and not moderated away.
  select * into chapter from public.chapters
  where chapters.code = chapter_code and chapters.story_id = story.id;
  if not found or not public.chapter_is_readable(chapter.id) then
    return null;
  end if;
  -- Step 3: its place among the chapters readers can open, for "Chapter n of N" and the arrows.
  select array_agg(others.code order by others.position) into readable_codes
  from public.chapters as others
  where others.story_id = story.id and public.chapter_is_readable(others.id);
  place := array_position(readable_codes, chapter.code);
  -- Step 4: the text. GAPS-15: none on the web while "In the app only" applies, except for the
  -- writer; otherwise all of it for a signed-in reader and the teaser for a signed-out visitor.
  app_only := public.story_app_only_applies(story.is_app_only)
    and story.user_id is distinct from caller_id;
  if app_only then
    text_to_send := '';
  elsif caller_id is not null then
    text_to_send := chapter.published_body;
  else
    select coalesce((settings.value #>> '{}')::integer, 600) into teaser_words
    from public.settings where settings.key = 'teaser_length';
    text_to_send := public.teaser_of(chapter.published_body, coalesce(teaser_words, 600));
  end if;
  -- Step 5: the answer, with the pictures and cards in the text that is sent.
  return jsonb_build_object(
    'story', jsonb_build_object(
      'slug', story.slug,
      'title', story.title,
      'language_code', story.language_code,
      'writer', (select jsonb_build_object(
          'display_name', public.story_writer_name(story.id, profiles.handle, profiles.pen_name),
          'handle', profiles.handle,
          'classic_author', public.story_classic_author(story.id))
        from public.profiles where profiles.id = story.user_id)),
    'id', chapter.id,
    'code', chapter.code,
    'title', chapter.published_title,
    'number', place,
    'total', array_length(readable_codes, 1),
    'previous_code', case when place > 1 then readable_codes[place - 1] end,
    'next_code', readable_codes[place + 1],
    'published_at', chapter.first_published_at,
    'edited_at', chapter.edited_at,
    'minutes_to_read', greatest(1, ceil(coalesce(chapter.published_word_count, 0) / 200.0))::integer,
    'is_owner', story.user_id = caller_id,
    'needs_sign_in', caller_id is null and not app_only,
    'is_teaser', caller_id is null and not app_only,
    'app_only', app_only,
    'text_continues', not app_only
      and public.word_total(text_to_send) < public.word_total(chapter.published_body),
    'body', text_to_send,
    'pictures', public.chapter_picture_states(text_to_send, story.user_id),
    'embeds', public.chapter_embed_states(text_to_send, story.user_id));
end;
$$;


ALTER FUNCTION "public"."get_chapter"("story_slug" "text", "chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_chapter"("story_slug" "text", "chapter_code" "text") IS 'A chapter as readers see it, the teaser for signed-out visitors; null when the reader may not (rating, blocks, deleted, moderated, unpublished) (S1-E4-01a, S1-E4-04, S1-E6-03).';



CREATE OR REPLACE FUNCTION "public"."get_link_preview"("story_slug" "text", "chapter_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  chapter public.chapters;
  hides_text boolean;
  chapter_part jsonb;
begin
  -- Step 1: a live story with at least one chapter published once, not hidden by a moderator.
  select * into story from public.stories
  where stories.slug = story_slug and stories.deleted_at is null and stories.first_published_at is not null;
  if not found or public.is_moderated_away('story', story.id) then
    return null;
  end if;
  -- S1-E11-08: a link preview never shows a hidden title or cover.
  story := public.story_as_shown(story);
  -- Step 2: 16+ and 18+ show nothing beyond the title to visitors who aren't logged in (Q6).
  hides_text := story.rating in ('16_plus', '18_plus');
  -- Step 3: the chapter, when the address names one; it must be readable.
  if chapter_code is not null then
    select * into chapter from public.chapters
    where chapters.code = chapter_code and chapters.story_id = story.id;
    if not found or not public.chapter_is_readable(chapter.id) then
      return null;
    end if;
    chapter_part := jsonb_build_object('code', chapter.code,
      'title', case when hides_text then null else chapter.published_title end);
  end if;
  -- Step 4: the preview, with the writer's pen name or username and never the user ID.
  return jsonb_build_object(
    'slug', story.slug,
    'title', story.title,
    'rating', story.rating,
    'language_code', story.language_code,
    'hides_text', hides_text,
    'blurb', case when hides_text then null else story.blurb end,
    'writer', case when hides_text then null else (
      select jsonb_build_object(
        'display_name', public.story_writer_name(story.id, profiles.handle, profiles.pen_name))
      from public.profiles where profiles.id = story.user_id) end,
    'cover', case when hides_text then null else jsonb_build_object(
      'kind', story.cover_kind, 'design', story.cover_design,
      'background', story.cover_background, 'accent', story.cover_accent) end,
    'chapter', chapter_part);
end;
$$;


ALTER FUNCTION "public"."get_link_preview"("story_slug" "text", "chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_link_preview"("story_slug" "text", "chapter_code" "text") IS 'What a link preview may show a visitor who is not logged in: title and rating always, the rest only for All ages and 13+ (S1-E4-04).';



CREATE OR REPLACE FUNCTION "public"."get_public_story_plan"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
