    AS $$
declare
  target_story_id uuid;
begin
  select stories.id into target_story_id from public.stories
  where stories.slug = story_slug and stories.deleted_at is null;
  if target_story_id is null or not public.plan_story_readable(target_story_id) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object('outcome', 'ok') || public.public_plan_json(target_story_id, false);
end;
$$;


ALTER FUNCTION "public"."get_public_story_plan"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_public_story_plan"("story_slug" "text") IS 'The public parts of a story''s plan, for anyone who may read the story (S1-E17-33).';



CREATE OR REPLACE FUNCTION "public"."get_shared_passage"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  chapter public.chapters;
  shared_blocks jsonb;
begin
  -- Step 1: a chapter a visitor may see a preview of, from a story that shares content.
  if first_block < 1 or last_block < first_block or last_block - first_block > 4
     or public.get_link_preview(story_slug, chapter_code) is null then
    return null;
  end if;
  select * into story from public.stories where stories.slug = story_slug and stories.deleted_at is null;
  select * into chapter from public.chapters where chapters.story_id = story.id and chapters.code = chapter_code;
  if not public.story_shares_content(story.rating) then
    return null;
  end if;
  -- GAPS-15 (S1-E3-08): no chapter text in a link preview while "In the app only" applies.
  if public.story_app_only_applies(story.is_app_only) then
    return null;
  end if;
  -- Step 2: each block in the range: a lone picture as its alt text, anything else as text.
  select jsonb_agg(block.shared order by block.block_number) into shared_blocks
  from (
    select blocks.block_number, public.shared_block(blocks.block_text, story, chapter.id) as shared
    from public.chapter_blocks(chapter.published_body) as blocks
    where blocks.block_number between first_block and last_block
  ) as block
  where block.shared is not null;
  if shared_blocks is null then
    return null;
  end if;
  return jsonb_build_object('blocks', shared_blocks);
end;
$$;


ALTER FUNCTION "public"."get_shared_passage"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shared_passage"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) IS 'The passage a shared link points to, for its link preview; only what may be shared (S1-E4-11).';



CREATE OR REPLACE FUNCTION "public"."get_shared_picture"("story_slug" "text", "chapter_code" "text", "block_number" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shared jsonb;
  story public.stories;
  chapter public.chapters;
  picture_block text;
  picture public.picture_checks;
begin
  -- Step 1: only what the shared passage itself would show as a picture (all its checks).
  shared := public.get_shared_passage(story_slug, chapter_code, block_number, block_number);
  if shared is null or jsonb_array_length(shared -> 'blocks') <> 1
     or (shared -> 'blocks' -> 0 ->> 'kind') <> 'picture' then
    return null;
  end if;
  -- Step 2: the picture that block names, checked again as the writer's own visible picture.
  select * into story from public.stories where stories.slug = story_slug and stories.deleted_at is null;
  select * into chapter from public.chapters where chapters.story_id = story.id and chapters.code = chapter_code;
  select blocks.block_text into picture_block
  from public.chapter_blocks(chapter.published_body) as blocks
  where blocks.block_number = get_shared_picture.block_number;
  select picture_checks.* into picture
  from public.chapter_picture_references(picture_block) as reference
  join public.picture_checks on picture_checks.id = reference.picture_id
  where picture_checks.user_id = story.user_id and picture_checks.bucket = 'chapter-images'
    and picture_checks.deleted_at is null
    and (public.picture_state_json(picture_checks) ->> 'state') = 'visible'
  limit 1;
  if not found then
    return null;
  end if;
  return jsonb_build_object('bucket', picture.bucket, 'path', picture.path,
    'alt', shared -> 'blocks' -> 0 ->> 'alt');
end;
$$;


ALTER FUNCTION "public"."get_shared_picture"("story_slug" "text", "chapter_code" "text", "block_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_shared_picture"("story_slug" "text", "chapter_code" "text", "block_number" integer) IS 'The passed picture a shared link points to, for its link preview; null unless it may be shared (IDEAS-2f).';



CREATE OR REPLACE FUNCTION "public"."get_story_page"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  caller_id uuid := (select auth.uid());
  is_owner boolean;
begin
  -- Step 1: the story, if it exists and isn't deleted.
  select * into story from public.stories where stories.slug = story_slug and stories.deleted_at is null;
  if not found then
    return null;
  end if;
  is_owner := caller_id is not null and caller_id = story.user_id;
  -- S1-E11-08: a hidden title or cover is masked for readers.
  story := public.story_as_shown(story);

  -- Step 2: readers see it only while a chapter is readable, if their age allows the rating
  -- (rule 18), no moderator hid it and neither side blocks the other (S1-E5-05).
  if not is_owner then
    if not public.story_has_readable_chapter(story.id) then
      return null;
    end if;
    if not public.rating_allows(story.rating) then
      return null;
    end if;
    if public.is_moderated_away('story', story.id) then
      return null;
    end if;
    if public.is_blocked_with(story.user_id) then
      return null;
    end if;
  end if;

  -- Step 3: the page, with the real author of a classic, else the writer's pen name or
  -- username, and never the user ID.
  return jsonb_build_object(
    'id', story.id,
    'slug', story.slug,
    'title', story.title,
    'blurb', story.blurb,
    'language_code', story.language_code,
    'category_slug', (select categories.slug from public.categories where categories.id = story.category_id),
    'tags', coalesce((
      select jsonb_agg(tags.name order by story_tags.created_at)
      from public.story_tags join public.tags on tags.id = story_tags.tag_id
      -- CMS-1e: readers see only approved tags; a waiting one shows only in the writer's settings.
      where story_tags.story_id = story.id and tags.status = 'approved'), '[]'::jsonb),
    'completion_status', story.completion_status,
    'comments_enabled', story.comments_enabled,
    'cover', jsonb_build_object('kind', story.cover_kind, 'design', story.cover_design,
      'background', story.cover_background, 'accent', story.cover_accent),
    'labels', jsonb_build_object('rating', story.rating, 'is_fan_fiction', story.is_fan_fiction,
      'is_parody', story.is_parody, 'deals_with_abuse_or_coercion', story.deals_with_abuse_or_coercion,
      'content_note', story.content_note, 'ai_disclosure', story.ai_disclosure,
      'ai_undisclosed_labelled', story.ai_undisclosed_labelled_at is not null),
    'writer', (select jsonb_build_object(
        'display_name', public.story_writer_name(story.id, profiles.handle, profiles.pen_name),
        'handle', profiles.handle, 'bio', public.bio_for_caller(profiles),
        'classic_author', public.story_classic_author(story.id))
      from public.profiles where profiles.id = story.user_id),
    'first_published_at', story.first_published_at,
    'last_chapter_published_at', story.last_chapter_published_at,
    'is_public', public.story_has_readable_chapter(story.id),
    'chapters', public.story_page_chapters(story.id, is_owner),
    'is_owner', is_owner,
    -- GAPS-15: the "In the app only" notice (S1-E3-08), only once the apps exist.
    'app_only', public.story_app_only_applies(story.is_app_only),
    'stats', jsonb_build_object(
      'likes', public.story_like_total(story.id),
      'comments', public.story_comment_total(story.id))
  );
end;
$$;


ALTER FUNCTION "public"."get_story_page"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_story_page"("story_slug" "text") IS 'The public story page, or null when the reader may not see it; never the user ID (S1-E3-05, ADR 0004).';



CREATE OR REPLACE FUNCTION "public"."get_writer_profile"("wanted_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  writer public.profiles;
  is_me boolean;
  i_blocked boolean;
  is_open boolean;
  story_cards jsonb;
begin
  -- Step 1: the live profile behind the username.
  select * into writer from public.profile_for_handle(wanted_handle);
  if not found then
    return null;
  end if;
  is_me := caller_id is not null and caller_id = writer.id;
  -- Step 2: hidden or removed by a moderator: gone for everyone but its owner.
  if not is_me and public.is_moderated_away('profile', writer.id) then
    return null;
  end if;
  -- Step 3: this person blocks the caller: as if there were no such profile.
  if exists (select 1 from public.blocks where blocks.user_id = writer.id and blocks.blocked_user_id = caller_id) then
    return null;
  end if;
  -- Step 4: the caller blocks this person: the header only, so they can unblock.
  i_blocked := exists (select 1 from public.blocks where blocks.user_id = caller_id and blocks.blocked_user_id = writer.id);
  story_cards := case when i_blocked then '[]'::jsonb else public.profile_story_cards(writer.id, is_me) end;
  -- Step 5: the owner's privacy choice (S1-E13-01).
  is_open := public.profile_is_open_to(writer, caller_id);
  -- Step 6: the answer, from the public columns only; can_message never says why (S1-E9-03).
  return jsonb_build_object(
    'handle', writer.handle,
    'display_name', public.display_name(writer.handle, writer.pen_name),
    'pen_name', nullif(btrim(coalesce(writer.pen_name, '')), ''),
    'bio', case when is_open then writer.bio else '' end,
    'joined_at', case when is_open then writer.created_at end,
    'is_limited', not is_open,
    'is_me', is_me,
    'i_blocked', i_blocked,
    'is_teacher', writer.teacher_badge_since is not null,
    'is_founding_member', writer.founding_member_since is not null,
    'can_message', case when caller_id is null or is_me then null
                        else public.can_message(caller_id, writer.id) end,
    'library_open', not i_blocked and public.library_is_open_to(writer, caller_id),
    'library_audience', case when is_me then writer.library_visible_to end,
    'counts', jsonb_build_object(
      'stories', jsonb_array_length(story_cards),
      'chapters', (select coalesce(sum((story ->> 'chapter_count')::integer), 0) from jsonb_array_elements(story_cards) as story),
      'reads', (select coalesce(sum(chapter_reads.total), 0)
        from public.chapter_reads
        join public.chapters on chapters.id = chapter_reads.chapter_id
        where chapters.story_id in (select (story ->> 'id')::uuid from jsonb_array_elements(story_cards) as story)
          and public.chapter_is_readable(chapters.id))),
    'stories', story_cards
  );
end;
$$;


ALTER FUNCTION "public"."get_writer_profile"("wanted_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_writer_profile"("wanted_handle" "text") IS 'A writer''s public profile by username; never the user ID, age, email or online status (S1-E5-05).';



