CREATE OR REPLACE FUNCTION "public"."issue_class_certificates"("slug" "text", "programme_name" "text", "results" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(slug, 'settings');
  clean_programme text := btrim(coalesce(programme_name, ''));
  teacher_display text;
  entry jsonb;
  student_id uuid;
  wanted_result public.certificate_result;
  issued_id uuid;
  issued_count integer := 0;
begin
  -- Step 1: a live class, and only its own teacher signs.
  perform public.check_certificate_class(space);
  if space.user_id is distinct from (select auth.uid()) then
    raise exception 'Only the class''s teacher signs its certificates.'
      using errcode = 'insufficient_privilege', hint = 'certificate:teacher_only';
  end if;
  if char_length(clean_programme) not between 1 and 120 then
    raise exception 'Name the programme in 1 to 120 characters.' using errcode = 'check_violation', hint = 'certificate:programme';
  end if;
  if jsonb_typeof(results) is distinct from 'array' or jsonb_array_length(results) = 0 then
    raise exception 'Choose a result for at least one student.' using errcode = 'check_violation', hint = 'certificate:empty';
  end if;
  select public.display_name(profiles.handle, profiles.pen_name) into teacher_display
  from public.profiles where profiles.id = space.user_id;
  -- Step 2: one certificate per student named; a second approval changes the result.
  for entry in select value from jsonb_array_elements(results) loop
    student_id := public.certificate_student_id(space, entry ->> 'handle');
    wanted_result := public.certificate_result_from(entry ->> 'result');
    issued_id := public.write_class_certificate(space, student_id, clean_programme, wanted_result, teacher_display);
    if issued_id is not null then
      issued_count := issued_count + 1;
      perform public.notify(student_id, 'certificate_issued', null, jsonb_build_object('space_id', space.id));
    end if;
  end loop;
  -- Step 3: the class's log.
  perform public.log_space_action(space, 'certificates_issued', null, null, null,
    jsonb_build_object('programme_name', clean_programme, 'count', issued_count));
  return jsonb_build_object('issued', issued_count);
end;
$$;


ALTER FUNCTION "public"."issue_class_certificates"("slug" "text", "programme_name" "text", "results" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_class_certificates"("slug" "text", "programme_name" "text", "results" "jsonb") IS 'The class''s teacher approves and signs a programme''s results; each student gets a certificate (S1-E8-12).';



CREATE OR REPLACE FUNCTION "public"."issue_statement_of_reasons"("recipient_id" "uuid", "chosen_action" "public"."statement_action", "ground" "public"."statement_ground", "ground_key" "text", "facts" "text", "about" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_statement public.statements_of_reasons;
  item_type public.reportable_type := (about ->> 'item_type')::public.reportable_type;
  item_id uuid := (about ->> 'item_id')::uuid;
begin
  -- Step 1: the stored copy, with a summary of the item made now.
  insert into public.statements_of_reasons (reference, user_id, case_id, sanction_id, story_id, action,
    item_type, item_summary, facts, ground, ground_key, automated_detection, restriction_ends_at,
    language, appeal_until)
  values (
    'S-' || lpad(nextval('public.statement_reference_seq')::text, 6, '0'),
    recipient_id, (about ->> 'case_id')::uuid, (about ->> 'sanction_id')::uuid, (about ->> 'story_id')::uuid,
    chosen_action, item_type,
    case when item_type is not null and item_id is not null then public.reportable_item_summary(item_type, item_id) end,
    nullif(btrim(coalesce(facts, '')), ''), ground, ground_key,
    coalesce((about ->> 'automated_detection')::boolean, false),
    (about ->> 'restriction_ends_at')::timestamptz,
    coalesce((select case when profiles.locale = 'en' then 'en' else 'ro' end
              from public.profiles where profiles.id = recipient_id), 'ro'),
    now() + interval '6 months')
  returning * into new_statement;
  -- Step 2: a statement without a case tells the person now; a case's notification links it.
  if new_statement.case_id is null then
    perform public.notify(recipient_id, 'moderation_decision', null,
      jsonb_build_object('statement_id', new_statement.id, 'story_id', new_statement.story_id));
  end if;
  return new_statement.id;
end;
$$;


ALTER FUNCTION "public"."issue_statement_of_reasons"("recipient_id" "uuid", "chosen_action" "public"."statement_action", "ground" "public"."statement_ground", "ground_key" "text", "facts" "text", "about" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_statement_of_reasons"("recipient_id" "uuid", "chosen_action" "public"."statement_action", "ground" "public"."statement_ground", "ground_key" "text", "facts" "text", "about" "jsonb") IS 'Internal: writes one statement of reasons and, outside a case, its required notification (S1-E10-04; DSA art. 17).';



CREATE OR REPLACE FUNCTION "public"."item_for_public_address"("address" "text") RETURNS TABLE("item_type" "public"."reportable_type", "item_id" "uuid", "owner_user_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  -- Step 1: just the path: drop the scheme and host, then any query or fragment.
  path text := regexp_replace(regexp_replace(btrim(address), '^[a-z]+://[^/]+', '', 'i'), '[?#].*$', '');
  parts text[];
begin
  -- Step 2: a chapter, /s/<story>/<chapter>.
  parts := regexp_match(path, '^/s/([a-z0-9-]+)/([a-z0-9]{8})/?$');
  if parts is not null then
    return query
      select 'chapter'::public.reportable_type, chapters.id, chapters.user_id
      from public.chapters join public.stories on stories.id = chapters.story_id
      where stories.slug = parts[1] and chapters.code = parts[2]
        and chapters.status = 'published' and chapters.deleted_at is null and stories.deleted_at is null;
    return;
  end if;
  -- Step 3: a story, /s/<story>.
  parts := regexp_match(path, '^/s/([a-z0-9-]+)/?$');
  if parts is not null then
    return query
      select 'story'::public.reportable_type, stories.id, stories.user_id
      from public.stories
      where stories.slug = parts[1] and stories.first_published_at is not null and stories.deleted_at is null;
    return;
  end if;
  -- Step 4: a profile, /u/<username> (the "@" and the letter case don't matter).
  parts := regexp_match(path, '^/u/@?([^/]+)/?$');
  if parts is not null then
    return query
      select 'profile'::public.reportable_type, profiles.id, profiles.id
      from public.profiles
      where profiles.handle_skeleton = public.username_skeleton(parts[1]) and profiles.deleted_at is null;
  end if;
end;
$_$;


ALTER FUNCTION "public"."item_for_public_address"("address" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."item_for_public_address"("address" "text") IS 'Internal: the story, chapter or profile an address on our site points to, or nothing (S1-E10-02).';



CREATE OR REPLACE FUNCTION "public"."join_class_space"("code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  invite public.invites := public.class_invite_row(code);
  space public.spaces;
begin
  -- Step 1: signed in, and a code we know.
  if caller_id is null then
    raise exception 'Log in first.' using errcode = 'insufficient_privilege', hint = 'signed_out';
  end if;
  select * into space from public.spaces where spaces.id = invite.space_id;
  if invite.id is null or space.id is null or public.is_moderated_away('space', space.id)
     or public.space_is_locked(space) then
    raise exception 'This code doesn''t work any more.' using errcode = 'check_violation', hint = 'invite:ended';
  end if;
  -- Step 2: already in the class: nothing to take.
  if public.space_is_member(space.id) then
    return jsonb_build_object('slug', space.slug, 'can_read', public.space_may_read(space));
  end if;
  -- Step 3: one place, counted and checked in one statement.
  perform public.take_rate_limit('space_join');
  update public.invites set use_count = use_count + 1
  where invites.id = invite.id and invites.revoked_at is null
    and invites.expires_at > now() and invites.use_count < invites.max_uses;
  if not found then
    raise exception 'This code doesn''t work any more.' using errcode = 'check_violation', hint = 'invite:ended';
  end if;
  -- Step 4: a member straight away (a request waiting from before becomes a place), then the log.
  insert into public.space_members (user_id, space_id, status, joined_at)
  values (caller_id, space.id, 'active', now())
  on conflict (space_id, user_id) do update set status = 'active', joined_at = now();
  perform public.log_space_action(space, 'member_joined', caller_id, null, null, '{}'::jsonb);
  return jsonb_build_object('slug', space.slug, 'can_read', public.space_may_read(space));
end;
$$;


ALTER FUNCTION "public"."join_class_space"("code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."join_class_space"("code" "text") IS 'Joins a class space with its invite code, any age; reads once the account is active (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."join_opening_list"("payload" "text", "signature" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fields jsonb;
  wanted_email text;
  wanted_country text;
  existing public.opening_list;
  token text := encode(extensions.gen_random_bytes(24), 'hex');
begin
  -- Step 1: only a payload our server signed, for this purpose.
  if not public.public_notice_payload_is_signed(payload, signature) then
    raise exception 'This request didn''t come through the form.' using errcode = 'insufficient_privilege';
  end if;
  fields := payload::jsonb;
  if fields ->> 'purpose' is distinct from 'opening_list' then
    raise exception 'This request didn''t come through the form.' using errcode = 'insufficient_privilege';
  end if;
  wanted_email := lower(btrim(coalesce(fields ->> 'email', '')));
  wanted_country := upper(btrim(coalesce(fields ->> 'countryCode', '')));
  -- Step 2: an open country needs no list; the person can sign up now.
  if exists (select 1 from public.markets where markets.country_code = wanted_country and markets.is_open) then
    raise exception 'We are already open there.' using errcode = 'check_violation', hint = 'already_open';
  end if;
  -- Step 3: a known address keeps its row; a confirmed one, or one sent a link a moment ago, gets no email.
  select * into existing from public.opening_list
  where opening_list.email = wanted_email and opening_list.country_code = wanted_country;
  if found then
    if existing.confirmed_at is not null or existing.token_sent_at > now() - interval '10 minutes' then
      return null;
    end if;
    update public.opening_list
    set token_hash = public.opening_list_token_hash(token), token_sent_at = now(),
        language = coalesce(fields ->> 'language', existing.language)
    where id = existing.id;
    return token;
  end if;
  -- Step 4: a new address; the table's checks refuse a malformed one.
  insert into public.opening_list (email, country_code, detected_country_code, language, token_hash)
  values (wanted_email, wanted_country, nullif(upper(btrim(coalesce(fields ->> 'detectedCountryCode', ''))), ''),
          coalesce(fields ->> 'language', 'ro'), public.opening_list_token_hash(token));
  return token;
end;
$$;


ALTER FUNCTION "public"."join_opening_list"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."join_opening_list"("payload" "text", "signature" "text") IS 'Puts an address on the "tell me when you open here" list; only a payload signed by our server (G5a).';



CREATE OR REPLACE FUNCTION "public"."join_space"("slug" "text", "note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_space_starter();
  space public.spaces;
  membership public.space_members;
  clean_note text := nullif(public.check_space_text(note, 'join_note'), '');
begin
  -- Step 1: a space the caller may know about.
  select * into space from public.spaces where spaces.slug = join_space.slug and spaces.deleted_at is null;
  if space.id is null or not public.space_card_visible(space) then
    raise exception 'There is no such space.' using errcode = 'no_data_found', hint = 'space:missing';
  end if;
  -- Step 2: already in, or already asked.
  membership := public.space_membership_of_caller(space.id);
  if membership.id is not null then
    return jsonb_build_object('status', membership.status);
  end if;
  -- Step 3 (S1-E8-11): a class space takes its teacher's code instead.
  if space.kind = 'class' then
    raise exception 'Join a class with your teacher''s code.' using errcode = 'insufficient_privilege', hint = 'space:class';
  end if;
  -- Step 4: only people in the space's age group join it.
  if not public.space_may_join(space) then
    raise exception 'This space is for another age group.' using errcode = 'insufficient_privilege', hint = 'space:age';
  end if;
  perform public.take_rate_limit('space_join');
  -- Step 5: in straight away, or waiting for the owner.
  insert into public.space_members (user_id, space_id, status, joined_at)
  values (caller_id, space.id,
          case when space.joining = 'open' then 'active'::public.space_member_status else 'pending' end,
          case when space.joining = 'open' then now() end)
  returning * into membership;
  -- Step 6 (IDEAS-3d): the note goes with a request only.
  if membership.status = 'pending' and clean_note is not null then
    insert into public.space_join_notes (user_id, space_id, note) values (caller_id, space.id, clean_note);
  end if;
  return jsonb_build_object('status', membership.status);
end;
$$;


ALTER FUNCTION "public"."join_space"("slug" "text", "note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."join_space"("slug" "text", "note" "text") IS 'Joins a space, or asks its owner with an optional note, by the age rules (S1-E8-06, IDEA-20261102-9).';



CREATE OR REPLACE FUNCTION "public"."join_waitlist_at_sign_up"("new_user_id" "uuid", "sign_up_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  code text := nullif(btrim(coalesce(sign_up_data ->> 'invite_code', '')), '');
begin
  -- Step 1: a code still skips the queue (S1-E11-17, IDEAS-3c).
  if code is not null then
    perform public.use_sign_up_invite(code, new_user_id);
  end if;
  -- Step 2: the entry, already let in when a code was used.
  insert into public.waitlist_entries (user_id, interest, admitted_at, admitted_by_code)
  values (new_user_id, public.sign_up_waitlist_interest(sign_up_data),
    case when code is not null then now() end, code is not null);
  -- Step 3: the badge, and occasional news only for an adult who ticked it (Law 506/2004; Q50).
  update public.profiles set
    founding_member_since = now(),
    marketing_email_opt_in = coalesce(sign_up_data ->> 'news_emails', '') = 'true'
      and public.age_band_from_birth(profiles.birth_year, profiles.birth_month,
        profiles.age_check_result, (now() at time zone 'Europe/Bucharest')::date) = '18_plus'
  where profiles.id = new_user_id;
end;
$$;


