    CONSTRAINT "landing_page_versions_down_after_up" CHECK ((("take_down_on" IS NULL) OR ("show_from" IS NULL) OR ("take_down_on" > "show_from"))),
    CONSTRAINT "landing_page_versions_published_has_a_date" CHECK ((("status" = 'draft'::"text") OR (("show_from" IS NOT NULL) AND ("published_at" IS NOT NULL)))),
    CONSTRAINT "landing_page_versions_status_is_known" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text"])))
);


