CREATE OR REPLACE FUNCTION "public"."landing_text_problem"("block" "jsonb", "language_code" "text", "field_name" "text", "field_path" "text", "longest" integer, "is_required" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
