COMMENT ON FUNCTION "public"."log_sensitive_read"("read_kind" "text", "target_table" "text", "target_row_id" "text", "affected_user_id" "uuid") IS 'Logs a sensitive read (email, draft, export, evidence pack, teacher proof) in the audit log (S1-E11-01).';



CREATE OR REPLACE FUNCTION "public"."log_space_action"("target" "public"."spaces", "action_taken" "text", "about_user_id" "uuid", "about_thread_id" "uuid", "note" "text", "details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  by_platform boolean := public.space_acts_as_platform(target);
begin
  -- Step 1: the space's own log, which the owner reads.
  insert into public.space_moderation_log (user_id, space_id, action, target_user_id, thread_id, note, details, by_platform)
  values ((select auth.uid()), target.id, action_taken, about_user_id, about_thread_id,
          nullif(btrim(coalesce(note, '')), ''), coalesce(details, '{}'::jsonb), by_platform);
  -- Step 2: staff actions are also in the audit log.
  if by_platform then
    perform public.log_staff_action('space.' || action_taken, 'spaces', target.id::text, about_user_id,
      nullif(btrim(coalesce(note, '')), ''), null, coalesce(details, '{}'::jsonb));
  end if;
end;
$$;


ALTER FUNCTION "public"."log_space_action"("target" "public"."spaces", "action_taken" "text", "about_user_id" "uuid", "about_thread_id" "uuid", "note" "text", "details" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_space_action"("target" "public"."spaces", "action_taken" "text", "about_user_id" "uuid", "about_thread_id" "uuid", "note" "text", "details" "jsonb") IS 'Internal: one row of a space''s moderation log, plus the audit log for platform staff (S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."log_staff_action"("action_taken" "text", "target_table" "text", "target_row_id" "text" DEFAULT NULL::"text", "affected_user_id" "uuid" DEFAULT NULL::"uuid", "reason_given" "text" DEFAULT NULL::"text", "values_before" "jsonb" DEFAULT NULL::"jsonb", "values_after" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_row_id uuid;
begin
  -- Only a staff session may write to the audit log (architecture 1.8.1).
  if not public.is_staff_session() then
    raise exception 'Only staff can write to the audit log.' using errcode = 'insufficient_privilege';
  end if;

  -- Write the row as the signed-in staff member; the table's checks refuse blank fields.
  insert into public.audit_log (
    user_id, action, target_type, target_id, target_user_id, reason, before_values, after_values
  )
  values (
    (select auth.uid()), action_taken, target_table, target_row_id, affected_user_id,
    reason_given, values_before, values_after
  )
  returning id into new_row_id;

  return new_row_id;
end;
$$;


ALTER FUNCTION "public"."log_staff_action"("action_taken" "text", "target_table" "text", "target_row_id" "text", "affected_user_id" "uuid", "reason_given" "text", "values_before" "jsonb", "values_after" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_staff_action"("action_taken" "text", "target_table" "text", "target_row_id" "text", "affected_user_id" "uuid", "reason_given" "text", "values_before" "jsonb", "values_after" "jsonb") IS 'Writes one audit row for the signed-in staff member; refuses non-staff (architecture 1.6, B03).';



CREATE OR REPLACE FUNCTION "public"."log_thread_moderation"("thread" "public"."forum_threads", "action_taken" "text", "reason" "text", "values_before" "jsonb", "values_after" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_of_forum(thread.forum_id);
begin
  if space.id is not null then
    perform public.log_space_action(space, 'thread_' || action_taken, thread.user_id, thread.id, btrim(reason),
      jsonb_build_object('before', values_before, 'after', values_after));
  else
    perform public.log_staff_action('forum_thread.' || action_taken, 'forum_threads', thread.id::text,
      thread.user_id, btrim(reason), values_before, values_after);
  end if;
end;
$$;


ALTER FUNCTION "public"."log_thread_moderation"("thread" "public"."forum_threads", "action_taken" "text", "reason" "text", "values_before" "jsonb", "values_after" "jsonb") OWNER TO "postgres";


