CREATE OR REPLACE FUNCTION "public"."make_quote_card"("story_slug" "text", "chapter_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  shared record;
begin
  -- Step 1: a signed-in reader and a chapter they may read.
  if caller_id is null then
    raise exception 'Log in to share a quote.' using errcode = 'insufficient_privilege';
  end if;
  select * into shared from public.shareable_chapter(story_slug, chapter_code);
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the writer's switch, then the limit of one per chapter (Q17).
  if not shared.quote_cards_enabled then
    return jsonb_build_object('outcome', 'switched_off');
  end if;
  if exists (select 1 from public.quote_cards
             where quote_cards.user_id = caller_id and quote_cards.chapter_id = shared.chapter_id) then
    return jsonb_build_object('outcome', 'already_made');
  end if;
  -- Step 3: the hourly limit, then the record and one more share (not the writer's own).
  perform public.take_rate_limit('quote_card');
  insert into public.quote_cards (user_id, chapter_id) values (caller_id, shared.chapter_id);
  if shared.writer_id <> caller_id then
    perform public.add_chapter_share(shared.chapter_id);
  end if;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."make_quote_card"("story_slug" "text", "chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."make_quote_card"("story_slug" "text", "chapter_code" "text") IS 'Records a quote card from a chapter, one per chapter per reader, and counts it as a share (S1-E4-07).';



CREATE OR REPLACE FUNCTION "public"."make_story_plan"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: the plan, with the defaults of S1-E17-01 (a 90,000-word target).
  insert into public.story_plans (story_id, user_id) values (new.id, new.user_id)
  on conflict (story_id) do nothing;
  -- Step 2: the three acts every plan starts with.
  insert into public.story_plan_acts (story_id, user_id, position, name)
  values (new.id, new.user_id, 1, 'Act I'), (new.id, new.user_id, 2, 'Act II'), (new.id, new.user_id, 3, 'Act III')
  on conflict (story_id, position) do nothing;
  -- Step 3: the bible's seven default sections (S1-E17-17).
  perform public.make_bible_sections(new.id, new.user_id);
  return new;
end;
$$;


ALTER FUNCTION "public"."make_story_plan"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."make_story_plan"() IS 'Trigger: makes a new story''s plan, its three acts and its default bible sections (S1-E17-01, S1-E17-17).';



CREATE OR REPLACE FUNCTION "public"."manual_decision_result"("decision" "text", "current_result" "public"."age_check_result") RETURNS "public"."age_check_result"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when decision = 'refused' then current_result
    when decision = 'passed_18' or current_result = '18_or_over' then '18_or_over'::public.age_check_result
    else '13_or_over'::public.age_check_result
  end;
$$;


