COMMENT ON FUNCTION "public"."mark_conversation_read"("other_handle" "text") IS 'Marks the caller''s chat with someone as read up to now (S1-E9-01).';



CREATE OR REPLACE FUNCTION "public"."mark_forum_thread_answer"("thread_number" bigint, "post_number" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thread public.forum_threads;
  answer public.forum_posts;
begin
  -- Step 1: the live thread, locked for the change.
  select * into thread from public.forum_threads
  where forum_threads.thread_number = mark_forum_thread_answer.thread_number and forum_threads.deleted_at is null
  for update;
  if thread.id is null or not public.forum_thread_is_shown(thread) then
    raise exception 'That thread isn''t there any more.' using errcode = 'no_data_found', hint = 'thread:missing';
  end if;
  -- Step 2: only the person who asked marks the answer (criterion 2).
  if thread.user_id is distinct from (select auth.uid()) or not public.is_active_member() then
    raise exception 'Only the person who started the thread can mark its answer.'
      using errcode = 'insufficient_privilege', hint = 'answer:not_starter';
  end if;
  -- Step 3: no number takes the mark away.
  if mark_forum_thread_answer.post_number is null then
    update public.forum_threads set answer_post_id = null where forum_threads.id = thread.id;
    return jsonb_build_object('answer_post_number', null);
  end if;
  -- Step 4: a live reply by someone else.
  select * into answer from public.forum_posts
  where forum_posts.thread_id = thread.id and forum_posts.post_number = mark_forum_thread_answer.post_number
    and forum_posts.post_number > 1 and forum_posts.user_id <> thread.user_id
    and forum_posts.deleted_at is null and not public.is_moderated_away('forum_post', forum_posts.id);
  if answer.id is null then
    raise exception 'Pick a reply someone else wrote.' using errcode = 'check_violation', hint = 'answer:not_reply';
  end if;
  update public.forum_threads set answer_post_id = answer.id where forum_threads.id = thread.id;
  return jsonb_build_object('answer_post_number', answer.post_number);
end;
$$;


ALTER FUNCTION "public"."mark_forum_thread_answer"("thread_number" bigint, "post_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_forum_thread_answer"("thread_number" bigint, "post_number" integer) IS 'The thread''s starter marks the reply that answered it, or takes the mark away (IDEA-20261102-8).';



CREATE OR REPLACE FUNCTION "public"."mark_forum_thread_read"("thread_number" bigint, "up_to_post" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  thread public.forum_threads;
begin
  -- Step 1: signed in, and a thread they may open.
  if caller_id is null then
    raise exception 'Log in first.' using errcode = 'insufficient_privilege', hint = 'signed_out';
  end if;
  select * into thread from public.forum_threads where forum_threads.thread_number = mark_forum_thread_read.thread_number;
  if thread.id is null or not public.forum_thread_is_shown(thread) then
    raise exception 'That thread isn''t there any more.' using errcode = 'no_data_found', hint = 'thread:missing';
  end if;
  -- Step 2: move the mark forward, never past the thread's last post.
  insert into public.forum_thread_reads (user_id, thread_id, last_read_post_number)
  values (caller_id, thread.id, least(greatest(coalesce(up_to_post, 0), 0), thread.last_post_number))
  on conflict (user_id, thread_id) do update
    set last_read_post_number = greatest(forum_thread_reads.last_read_post_number, excluded.last_read_post_number),
        read_at = now();
end;
$$;


ALTER FUNCTION "public"."mark_forum_thread_read"("thread_number" bigint, "up_to_post" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_forum_thread_read"("thread_number" bigint, "up_to_post" integer) IS 'Records that the caller has seen a thread up to a post; only moves forward (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."mark_forums_read"("forum_slug" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  top_forum_id uuid;
begin
  -- Step 1: signed in.
  if caller_id is null then
    raise exception 'Log in first.' using errcode = 'insufficient_privilege', hint = 'signed_out';
  end if;
  -- Step 2: the whole board: one mark, now.
  if forum_slug is null then
    insert into public.forum_read_marks (user_id, forum_id, marked_at) values (caller_id, null, now())
    on conflict (user_id, forum_id) do update set marked_at = now();
    return;
  end if;
  -- Step 3: one forum and everything inside it: a mark on each.
  select forums.id into top_forum_id from public.forums
  where forums.slug = mark_forums_read.forum_slug and forums.deleted_at is null;
  if top_forum_id is null then
    raise exception 'That forum isn''t there any more.' using errcode = 'no_data_found', hint = 'forum:missing';
  end if;
  insert into public.forum_read_marks (user_id, forum_id, marked_at)
  select caller_id, inside.id, now() from public.forum_and_children(top_forum_id) as inside(id)
  on conflict (user_id, forum_id) do update set marked_at = now();
end;
$$;


ALTER FUNCTION "public"."mark_forums_read"("forum_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_forums_read"("forum_slug" "text") IS '"Mark all as read" on the board, or "Mark as read" on a forum and the forums inside it (S1-E8-04).';



CREATE OR REPLACE FUNCTION "public"."mark_learning_step"("target_day" integer, "is_done" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
begin
  if caller_id is null then
    raise exception 'Log in to follow the learning path.' using errcode = 'insufficient_privilege';
  end if;
  if target_day is null or target_day not between 1 and 7 then
    raise exception 'The learning path has days 1 to 7.' using errcode = 'check_violation';
  end if;
  -- Taking the tick off removes the row; ticking twice changes nothing.
  if not coalesce(is_done, false) then
    delete from public.learning_path_progress where user_id = caller_id and day_number = target_day;
    return false;
  end if;
  insert into public.learning_path_progress (user_id, day_number) values (caller_id, target_day)
  on conflict on constraint learning_path_progress_one_per_day do nothing;
  return true;
end;
$$;


