COMMENT ON FUNCTION "public"."mark_learning_step"("target_day" integer, "is_done" boolean) IS 'The caller marks a learning path day done, or not done again (GAPS-12g).';



CREATE OR REPLACE FUNCTION "public"."mark_notifications_read"("notification_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
begin
  if caller_id is null then
    raise exception 'Log in to see your notifications.' using errcode = 'insufficient_privilege';
  end if;
  update public.notifications set read_at = now()
  where notifications.user_id = caller_id and notifications.read_at is null
    and (notification_ids is null or notifications.id = any (notification_ids));
  return public.my_unread_notification_count();
end;
$$;


