    "languages" "text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "public"."market_status" DEFAULT 'closed'::"public"."market_status" NOT NULL,
    "legal_check" "public"."legal_check_status" DEFAULT 'not_started'::"public"."legal_check_status" NOT NULL,
    CONSTRAINT "markets_country_code_is_alpha2" CHECK (("country_code" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "markets_minimum_age_is_plausible" CHECK ((("minimum_age" >= 13) AND ("minimum_age" <= 18)))
);


