COMMENT ON FUNCTION "public"."message_with_context"("reported_message_id" "uuid") IS 'A reported message and up to 20 before it in the same chat, oldest first (S1-E9-02); internal.';



CREATE OR REPLACE FUNCTION "public"."messaging_partner"("wanted_handle" "text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  partner public.profiles;
begin
  select * into partner from public.profile_for_handle(wanted_handle);
  if partner.id is null or partner.id = caller_id
     or public.is_moderated_away('profile', partner.id)
     or exists (select 1 from public.blocks where blocks.user_id = partner.id and blocks.blocked_user_id = caller_id) then
    return null;
  end if;
  return partner;
end;
$$;


