CREATE OR REPLACE FUNCTION "public"."move_bible_section"("section_id" "uuid", "new_position" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_section public.story_bible_sections;
  last_position integer;
  goal integer;
begin
  -- Step 1: a signed-in writer and their own section.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your story bible.' using errcode = 'insufficient_privilege';
  end if;
  target_section := public.my_bible_section(section_id);
  if target_section.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the goal, kept between the first and the last place.
  select max(position) into last_position from public.story_bible_sections where story_id = target_section.story_id;
  goal := greatest(1, least(coalesce(new_position, target_section.position), last_position));
  -- Step 3: the sections in between move one place towards the gap, then this one takes the goal.
  -- The unique place is checked at the end of the transaction, so the shift can pass through it.
  if goal < target_section.position then
    update public.story_bible_sections set position = position + 1
    where story_id = target_section.story_id and position >= goal and position < target_section.position;
  elsif goal > target_section.position then
    update public.story_bible_sections set position = position - 1
    where story_id = target_section.story_id and position <= goal and position > target_section.position;
  end if;
  update public.story_bible_sections set position = goal where story_bible_sections.id = target_section.id;
  return jsonb_build_object('outcome', 'ok', 'position', goal);
end;
$$;


ALTER FUNCTION "public"."move_bible_section"("section_id" "uuid", "new_position" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_bible_section"("section_id" "uuid", "new_position" integer) IS 'Moves one of the caller''s bible sections to a new place, shifting the others (S1-E17-17).';



CREATE OR REPLACE FUNCTION "public"."move_chapter"("chapter_code" "text", "direction" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter public.chapters := public.my_live_chapter(chapter_code);
  refusal text := public.chapter_gate_outcome(chapter);
  neighbour public.chapters;
  positions_before jsonb;
begin
  if refusal is not null then
    return jsonb_build_object('outcome', refusal);
  end if;
  if direction not in (-1, 1) then
    raise exception 'A chapter moves one place up (-1) or down (1).' using errcode = 'check_violation';
  end if;
  -- The live chapter next to it in that direction, if any.
  select * into neighbour from public.chapters
  where chapters.story_id = chapter.story_id and chapters.deleted_at is null
    and chapters.position = chapter.position + direction
  for update;
  if not found then
    return jsonb_build_object('outcome', 'at_edge');
  end if;
  -- Swap the two positions, then record both changes: this chapter is the one the writer moved.
  positions_before := public.chapter_positions(chapter.story_id);
  update public.chapters set position = neighbour.position where chapters.id = chapter.id;
  update public.chapters set position = chapter.position where chapters.id = neighbour.id;
  perform public.record_chapter_moves(chapter.story_id, positions_before, chapter.id);
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."move_chapter"("chapter_code" "text", "direction" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_chapter"("chapter_code" "text", "direction" integer) IS 'Moves the caller''s own chapter one place up or down and records it: {outcome: ok | not_active | not_found | at_edge} (S1-E3-04, GAPS-11).';



CREATE OR REPLACE FUNCTION "public"."move_chapter_scene"("scene_id" "uuid", "new_position" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
