CREATE OR REPLACE FUNCTION "public"."my_account_deletion"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  request public.account_deletions;
begin
  if caller_id is null then
    raise exception 'Sign in first.' using errcode = 'insufficient_privilege', hint = 'signed_out';
  end if;
  -- Step 1: an open request means the account is closing.
  select * into request from public.account_deletions
  where account_deletions.user_id = caller_id
    and account_deletions.cancelled_at is null and account_deletions.completed_at is null;
  if found then
    return jsonb_build_object('state', 'closing', 'requested_at', request.requested_at,
      'delete_after', request.delete_after);
  end if;
  -- Step 2: otherwise the account is open; say whether the log-in is fresh enough to confirm.
  return jsonb_build_object('state', 'open',
    'signed_in_recently', public.account_signed_in_recently(),
    'deletion_days', coalesce((public.setting_value('account_deletion_days'))::integer, 14));
end;
$$;


ALTER FUNCTION "public"."my_account_deletion"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."my_account_deletion"() IS 'The caller''s account deletion state: closing with its date, or open with whether they may confirm now (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."my_age_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person public.profiles;
  state public.account_status;
begin
  -- Step 1: signed in, with a live profile.
  if (select auth.uid()) is null then
    raise exception 'Sign in to check your age.' using errcode = 'insufficient_privilege';
  end if;
  select * into person from public.profiles
  where profiles.id = (select auth.uid()) and profiles.deleted_at is null;
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: what the account state says about the check, and the manual route.
  state := public.account_state(person.id);
  return jsonb_build_object(
    'outcome', 'ok',
    'result', person.age_check_result,
    'checked_at', person.age_checked_at,
    'method', person.age_check_method,
    'threshold', public.age_check_threshold_for(person),
    'can_start', public.age_check_can_start_for(person),
    'is_checking', exists (
      select 1 from public.age_check_sessions
      where age_check_sessions.user_id = person.id and age_check_sessions.expires_at > now()),
    'needs_check', state in ('age_check_pending', 'age_check_failed'),
    'can_ask_manual', public.age_check_can_ask_manual(person),
    'manual_check', public.latest_manual_age_check(person.id));
end;
$$;


