    CONSTRAINT "story_bible_sections_preset_known" CHECK ((("preset" IS NULL) OR ("preset" = ANY (ARRAY['premise'::"text", 'world'::"text", 'magic'::"text", 'cosmology'::"text", 'factions'::"text", 'history'::"text", 'glossary'::"text"]))))
);


