COMMENT ON FUNCTION "public"."my_writing_month"() IS 'The caller''s writing month: words against a goal of 15,000, the running streak and five badges, from their own activity only (GAPS-12f).';



CREATE OR REPLACE FUNCTION "public"."name_has_listed_word"("name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with forms as (select public.name_matching_words(name) as words)
  select exists (
    select 1
    from public.username_word_lists as listed, forms
    where listed.folded_word <> ''
      and (
        listed.folded_word = any (forms.words)
        or (listed.match_rule = 'anywhere' and char_length(listed.folded_word) >= 4
            and strpos(forms.words[1], listed.folded_word) > 0)
      )
  );
$$;


