CREATE OR REPLACE FUNCTION "public"."name_matching_words"("name" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  with folded as (
    select translate(public.username_skeleton(name), '34578@$!', 'eastbasi') as text
  )
  select array[regexp_replace(folded.text, '[^[:alnum:]]', '', 'g')]
    || coalesce(
      array(
        select word
        from regexp_split_to_table(folded.text, '[^[:alnum:]]+') as words (word)
        where word <> ''
      ),
      '{}'
    )
  from folded;
$_$;


