COMMENT ON FUNCTION "public"."notification_json"("target" "public"."notifications") IS 'Internal: one notification as the screen draws it, never a user ID (S1-E7-01).';



CREATE OR REPLACE FUNCTION "public"."notification_staff_change_json"("target_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'fields', (select coalesce(jsonb_agg(field order by field), '[]'::jsonb)
               from jsonb_object_keys(story_revisions.after_values) as field),
    'after', story_revisions.after_values,
    'reason_code', story_revisions.reason_code,
    'reason_text', story_revisions.reason_text)
  from public.story_revisions where story_revisions.id = target_revision_id;
$$;


ALTER FUNCTION "public"."notification_staff_change_json"("target_revision_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notification_staff_change_json"("target_revision_id" "uuid") IS 'Internal: what staff changed and why, for the writer''s notification (S1-E11-08).';



CREATE OR REPLACE FUNCTION "public"."notify"("recipient_id" "uuid", "notification_kind" "public"."notification_kind", "actor_id" "uuid", "about" "jsonb", "group_key" "text" DEFAULT NULL::"text", "group_window" interval DEFAULT NULL::interval) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  grouped public.notifications;
begin
  -- Step 1: never one's own action, never across a block.
  if recipient_id is null or recipient_id = actor_id then
    return;
  end if;
  if actor_id is not null and exists (
      select 1 from public.blocks
      where (blocks.user_id = recipient_id and blocks.blocked_user_id = actor_id)
         or (blocks.user_id = actor_id and blocks.blocked_user_id = recipient_id)) then
    return;
  end if;
  -- Step 2: a fresh grouped row takes the new person instead of a new row.
  if notify.group_key is not null then
    select * into grouped from public.notifications
    where notifications.user_id = recipient_id and notifications.group_key = notify.group_key
      and notifications.created_at > now() - group_window
    order by notifications.created_at desc limit 1
    for update;
    if grouped.id is not null then
      if actor_id = any (grouped.actor_user_ids) then
        return;
      end if;
      update public.notifications set
        actor_user_ids = (array[actor_id] || grouped.actor_user_ids)[1:50],
        actor_count = grouped.actor_count + 1,
        read_at = null,
        updated_at = now()
      where notifications.id = grouped.id;
      return;
    end if;
  end if;
  -- Step 3: a new row; a decision, an appeal's outcome or a staff change can't be switched off
  -- (DSA art. 17, 20; S1-E11-08), nor can a data request's notice (GDPR art. 12; S1-E11-09) or
  -- the alert that staff opened an uploaded picture (ADMIN-2e2a).
  insert into public.notifications (user_id, kind, actor_user_ids, actor_count, story_id, chapter_id,
    comment_id, case_id, decision, statement_id, appeal_id, mail_thread_id, space_id, change_request_id,
    story_revision_id, data_request_id, landing_page_id, live_session_id, forum_thread_id, group_key, is_required)
  values (recipient_id, notification_kind,
    case when actor_id is null then '{}'::uuid[] else array[actor_id] end,
    case when actor_id is null then 0 else 1 end,
    (about ->> 'story_id')::uuid, (about ->> 'chapter_id')::uuid, (about ->> 'comment_id')::uuid,
    (about ->> 'case_id')::uuid, (about ->> 'decision')::public.moderation_action,
    (about ->> 'statement_id')::uuid, (about ->> 'appeal_id')::uuid, (about ->> 'mail_thread_id')::uuid,
    (about ->> 'space_id')::uuid, (about ->> 'change_request_id')::uuid,
    (about ->> 'story_revision_id')::uuid, (about ->> 'data_request_id')::uuid,
    (about ->> 'landing_page_id')::uuid, (about ->> 'live_session_id')::uuid,
    (about ->> 'forum_thread_id')::uuid, notify.group_key,
    notification_kind in ('moderation_decision', 'appeal_decided', 'customisation_change_requested',
                          'story_changed_by_staff', 'data_request_confirm',
                          'data_request_extended', 'data_request_copy_ready', 'picture_opened_by_staff'));
end;
$$;


ALTER FUNCTION "public"."notify"("recipient_id" "uuid", "notification_kind" "public"."notification_kind", "actor_id" "uuid", "about" "jsonb", "group_key" "text", "group_window" interval) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify"("recipient_id" "uuid", "notification_kind" "public"."notification_kind", "actor_id" "uuid", "about" "jsonb", "group_key" "text", "group_window" interval) IS 'Internal: tells one person about one thing, or joins a fresh grouped row; never across a block (S1-E7-01).';



CREATE OR REPLACE FUNCTION "public"."notify_case_decided"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reporter_id uuid;
  statement_id uuid;
begin
  if new.status = 'decided' and old.status is distinct from 'decided' then
    -- Step 1: the owner, with the newest statement stored with the case. A removal order that
    -- forbids telling the uploader (TCO art. 11(3); S1-E10-09) leaves them with no statement and
    -- no notification.
    select statements_of_reasons.id into statement_id from public.statements_of_reasons
    where statements_of_reasons.case_id = new.id order by statements_of_reasons.issued_at desc limit 1;
    if not (new.source = 'authority_order' and new.decision <> 'no_action' and statement_id is null) then
      perform public.notify(new.user_id, 'moderation_decision', null,
        jsonb_build_object('case_id', new.id, 'decision', new.decision, 'statement_id', statement_id));
    end if;
    -- Step 2: each reporter once.
    for reporter_id in
      select distinct reports.user_id from public.reports
      where reports.case_id = new.id and reports.user_id <> new.user_id
    loop
      perform public.notify(reporter_id, 'report_outcome', null,
        jsonb_build_object('case_id', new.id, 'decision', new.decision));
    end loop;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."notify_case_decided"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_case_decided"() IS 'Internal trigger: a decided case notifies the owner of the item; always on (S1-E7-01, DSA art. 17).';



CREATE OR REPLACE FUNCTION "public"."notify_chapter_published"("payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  follower_id uuid;
begin
  select * into story from public.stories where stories.id = (payload ->> 'story_id')::uuid;
  -- NEW-1: a private story tells nobody.
  if story.id is null or story.visibility = 'private' then
    return;
  end if;
  for follower_id in
    -- NEW-1: the writer's followers hear only of public stories; an unlisted story tells only
    -- the people who follow that story.
    select follows_users.user_id from public.follows_users
    where follows_users.followed_user_id = story.user_id and story.visibility = 'public'
    union
    select follows_stories.user_id from public.follows_stories where follows_stories.story_id = story.id
  loop
    -- S1-E8-11: a chapter of a class-only story tells only followers who are in that class, so
    -- nobody else learns its title.
    if story.class_only and not exists (
      select 1 from public.space_members
      where space_members.space_id = story.class_space_id
        and space_members.user_id = follower_id
        and space_members.status = 'active'
    ) then
      continue;
    end if;
    perform public.notify(follower_id, 'new_chapter', story.user_id,
      jsonb_build_object('story_id', story.id, 'chapter_id', payload ->> 'chapter_id'));
  end loop;
end;
$$;


ALTER FUNCTION "public"."notify_chapter_published"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_chapter_published"("payload" "jsonb") IS 'Internal: a new chapter notifies the followers of its writer and of its story (S1-E7-01).';



CREATE OR REPLACE FUNCTION "public"."notify_comment_posted"("payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  comment public.comments;
  parent_author_id uuid;
  chapter record;
begin
  select * into comment from public.comments where comments.id = (payload ->> 'comment_id')::uuid;
  if comment.id is null or comment.deleted_at is not null then
    return;
  end if;
  select chapters.id, chapters.story_id, stories.user_id as writer_id into chapter
  from public.chapters join public.stories on stories.id = chapters.story_id
  where chapters.id = comment.chapter_id;
  if comment.parent_comment_id is not null then
    -- Step 1: a reply tells the author of the comment it answers.
    select comments.user_id into parent_author_id from public.comments where comments.id = comment.parent_comment_id;
    perform public.notify(parent_author_id, 'comment_reply', comment.user_id,
      jsonb_build_object('story_id', chapter.story_id, 'chapter_id', chapter.id, 'comment_id', comment.id));
    return;
  end if;
  -- Step 2: a new comment tells the writer.
  perform public.notify(chapter.writer_id, 'comment_on_chapter', comment.user_id,
    jsonb_build_object('story_id', chapter.story_id, 'chapter_id', chapter.id, 'comment_id', comment.id));
end;
$$;


