CREATE OR REPLACE FUNCTION "public"."open_data_request_parent_copy"("token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.data_requests := public.data_request_by_parent_token(token);
  link_state text;
  opened timestamptz;
begin
  -- Step 1: a copy link that hasn't been used up.
  if request.id is null
     or request.parent_copy_token_hash is distinct from
        encode(extensions.digest(coalesce(token, ''), 'sha256'), 'hex') then
    return jsonb_build_object('outcome', 'gone');
  end if;
  link_state := public.data_request_parent_copy_state(request);
  if link_state in ('used', 'expired') then
    return jsonb_build_object('outcome', link_state);
  end if;
  -- Step 2: the first opening starts the hour.
  opened := coalesce(request.parent_copy_opened_at, now());
  update public.data_requests set parent_copy_opened_at = opened where data_requests.id = request.id;
  -- Step 3: the files, with the random names the browser downloads them by.
  return jsonb_build_object('outcome', 'ok', 'open_until', opened + interval '1 hour',
    'files', public.data_request_files_json(request.id, true));
end;
$$;


ALTER FUNCTION "public"."open_data_request_parent_copy"("token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."open_data_request_parent_copy"("token" "text") IS 'A parent opens a data request copy from the one-time link; the first opening starts one hour (S1-E11-09).';



CREATE OR REPLACE FUNCTION "public"."open_downvote_case"("target" "public"."comments") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  threshold integer := coalesce(public.setting_value('downvote_case_threshold'), '5')::text::integer;
  counted integer;
begin
  -- Step 1: how many accounts count.
  select count(*) into counted
  from public.comment_downvotes
  join public.profiles on profiles.id = comment_downvotes.user_id
  where comment_downvotes.comment_id = target.id and comment_downvotes.is_counted
    and profiles.deleted_at is null;
  if counted < threshold then
    return;
  end if;
  -- Step 2: one open case per item; a report may already have opened it.
  if exists (select 1 from public.cases
             where cases.item_type = 'comment' and cases.item_id = target.id and cases.status = 'open') then
    return;
  end if;
  insert into public.cases (reference, user_id, item_type, item_id, source, tier, received_at, deadline_at)
  values ('D-' || lpad(nextval('public.downvote_case_reference_seq')::text, 6, '0'), target.user_id,
          'comment', target.id, 'downvotes', 'seven_days', now(),
          now() + make_interval(hours => public.tier_hours('seven_days')));
end;
$$;


ALTER FUNCTION "public"."open_downvote_case"("target" "public"."comments") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."open_downvote_case"("target" "public"."comments") IS 'Internal: opens a lowest-tier case once a comment has enough counted downvotes (S1-E6-04).';



CREATE TABLE IF NOT EXISTS "public"."picture_checks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "bucket" "text" NOT NULL,
    "path" "text" NOT NULL,
    "kind" "public"."picture_kind" NOT NULL,
    "story_id" "uuid",
    "status" "public"."picture_status" DEFAULT 'pending'::"public"."picture_status" NOT NULL,
    "flags" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provider" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "checked_at" timestamp with time zone,
    "case_id" "uuid",
    "preserve_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "chapter_id" "uuid",
    "rights_confirmed_at" timestamp with time zone,
    "file_sha256" "text",
    "uploader_ip_scrambled" "text",
    "uploader_ip_period" "text",
    CONSTRAINT "picture_checks_bucket_is_known" CHECK (("bucket" = ANY (ARRAY['covers'::"text", 'avatars'::"text", 'chapter-images'::"text", 'atlas-images'::"text", 'space-banners'::"text", 'signature-pictures'::"text", 'landing-pictures'::"text", 'sponsor-creatives'::"text", 'brand-assets'::"text", 'quote-card-pictures'::"text"]))),
    CONSTRAINT "picture_checks_file_sha256_shape" CHECK ((("file_sha256" IS NULL) OR ("file_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "picture_checks_ip_period_shape" CHECK ((("uploader_ip_period" IS NULL) OR ("uploader_ip_period" ~ '^[0-9]{4}-[0-9]{2}$'::"text"))),
    CONSTRAINT "picture_checks_ip_shape" CHECK ((("uploader_ip_scrambled" IS NULL) OR ("uploader_ip_scrambled" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "picture_checks_kind_matches_bucket" CHECK (((("kind" = 'cover'::"public"."picture_kind") AND ("bucket" = 'covers'::"text")) OR (("kind" = 'avatar'::"public"."picture_kind") AND ("bucket" = 'avatars'::"text")) OR (("kind" = ANY (ARRAY['chapter_picture'::"public"."picture_kind", 'drawing'::"public"."picture_kind"])) AND ("bucket" = 'chapter-images'::"text")) OR (("kind" = 'atlas_image'::"public"."picture_kind") AND ("bucket" = 'atlas-images'::"text")) OR (("kind" = ANY (ARRAY['space_banner'::"public"."picture_kind", 'space_logo'::"public"."picture_kind"])) AND ("bucket" = 'space-banners'::"text")) OR (("kind" = 'signature_picture'::"public"."picture_kind") AND ("bucket" = 'signature-pictures'::"text")) OR (("kind" = 'landing_picture'::"public"."picture_kind") AND ("bucket" = 'landing-pictures'::"text")) OR (("kind" = 'sponsor_creative'::"public"."picture_kind") AND ("bucket" = 'sponsor-creatives'::"text")) OR (("kind" = 'brand_asset'::"public"."picture_kind") AND ("bucket" = 'brand-assets'::"text")) OR (("kind" = 'quote_card'::"public"."picture_kind") AND ("bucket" = 'quote-card-pictures'::"text"))))
);


