CREATE OR REPLACE FUNCTION "public"."paragraph_key_of"("block_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select md5(regexp_replace(btrim(coalesce(block_text, ''), E' \t\n'), '\s+', ' ', 'g'));
$$;


