CREATE OR REPLACE FUNCTION "public"."parental_consent_is_signed"("payload" "text", "signature" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  secret text;
begin
  select decrypted_secret into secret from vault.decrypted_secrets
  where name = 'parental_consent_secret';
  if secret is null or secret = '' or signature is null then
    return false;
  end if;
  return encode(extensions.hmac(payload, secret, 'sha256'), 'hex') = lower(signature);
end;
$$;


