CREATE OR REPLACE FUNCTION "public"."picture_reader_may_see"("bucket" "text", "path" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.picture_checks
    left join public.cases on cases.id = picture_checks.case_id
    where picture_checks.bucket = picture_reader_may_see.bucket and picture_checks.path = picture_reader_may_see.path
      and (picture_checks.user_id = (select auth.uid())
           or (public.staff_may('moderation', 'view')
               and public.is_picture_reviewer((select auth.uid()))
               and public.may_see_case(coalesce(cases.is_safeguarding, false)))));
$$;


ALTER FUNCTION "public"."picture_reader_may_see"("bucket" "text", "path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."picture_reader_may_see"("bucket" "text", "path" "text") IS 'True for the uploader and for picture reviewers allowed to see the picture''s case (S1-E10-05, ADMIN-2e2a).';



CREATE OR REPLACE FUNCTION "public"."picture_review_case"("target_case_id" "uuid") RETURNS "public"."cases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
begin
  perform public.require_picture_reviewer();
  select * into target from public.cases where cases.id = target_case_id for update;
  if target.id is null or target.item_type <> 'picture' or target.status <> 'open' or target.is_safeguarding then
    raise exception 'This isn''t a picture waiting for a decision.' using errcode = 'check_violation';
  end if;
  return target;
end;
$$;


ALTER FUNCTION "public"."picture_review_case"("target_case_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."picture_review_case"("target_case_id" "uuid") IS 'Internal: the open, non-safeguarding picture case a review button acts on (ADMIN-2e1b).';



CREATE OR REPLACE FUNCTION "public"."picture_state_json"("picture" "public"."picture_checks") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when picture.id is null then null else jsonb_build_object(
    'state', case
      when picture.status = 'removed' or public.is_moderated_away('picture', picture.id) then 'removed'
      when picture.status in ('passed', 'approved') then 'visible'
      when picture.status = 'held' then 'waiting_for_person'
      else 'checking' end,
    'bucket', case when public.picture_is_visible(picture.bucket, picture.path)
                     or public.picture_reader_may_see(picture.bucket, picture.path) then picture.bucket end,
    'path', case when public.picture_is_visible(picture.bucket, picture.path)
                   or public.picture_reader_may_see(picture.bucket, picture.path) then picture.path end) end;
$$;


ALTER FUNCTION "public"."picture_state_json"("picture" "public"."picture_checks") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."picture_state_json"("picture" "public"."picture_checks") IS 'Internal: a picture''s state and, when the caller may read it, its file (S1-E10-05).';



CREATE OR REPLACE FUNCTION "public"."place_chapter_on_board"("chapter_code" "text", "act_id" "text", "chapter_codes" "text"[], "confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_plan public.chapter_plans;
  new_act_id uuid;
  live_codes text[];
begin
  -- Step 1: a signed-in writer who may write, and their own live chapter (the account gate:
  -- the order readers see is public, S1-E3-04).
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your storyline.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  target_plan := public.my_chapter_plan(chapter_code);
  if target_plan.chapter_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  new_act_id := public.act_of_story(target_plan.story_id, act_id);
  -- Step 2: lock the story's live chapters, then the list must be exactly those, each once.
  perform 1 from public.chapters
  where chapters.story_id = target_plan.story_id and chapters.deleted_at is null for update;
  select array_agg(chapters.code order by chapters.code) into live_codes
  from public.chapters where chapters.story_id = target_plan.story_id and chapters.deleted_at is null;
  if (select array_agg(listed order by listed) from unnest(chapter_codes) as listed) is distinct from live_codes
     or cardinality(chapter_codes) <> cardinality(live_codes) then
    return jsonb_build_object('outcome', 'wrong_list');
  end if;
  -- Step 3: ask first when readers would see the published chapters in a new order.
  if not coalesce(confirmed, false)
     and public.published_order(target_plan.story_id, chapter_codes)
         is distinct from public.published_order(target_plan.story_id, null) then
    return jsonb_build_object('outcome', 'needs_confirmation');
  end if;
  -- Step 4: each chapter takes its place (from 1), and the moved one its act.
  update public.chapters set position = ordered.place
  from unnest(chapter_codes) with ordinality as ordered(code, place)
  where chapters.code = ordered.code and chapters.story_id = target_plan.story_id
    and chapters.position is distinct from ordered.place::integer;
  update public.chapter_plans set act_id = new_act_id
  where chapter_plans.chapter_id = target_plan.chapter_id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


