CREATE OR REPLACE FUNCTION "public"."post_comment"("story_slug" "text", "chapter_code" "text", "body" "text", "is_spoiler" boolean DEFAULT false, "reply_to" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  chapter public.chapters;
  story public.stories;
  parent public.comments;
  new_comment_id uuid;
begin
  -- Step 1: signed in, and the chapter is one this reader may open.
  if caller_id is null then
    raise exception 'Log in to comment.' using errcode = 'insufficient_privilege';
  end if;
  select * into chapter from public.readable_chapter(story_slug, chapter_code);
  if chapter.id is null then
    raise exception 'There is no such chapter.' using errcode = 'no_data_found';
  end if;
  select * into story from public.stories where stories.id = chapter.story_id;
  -- Step 2: comments on, the account gate and the limit.
  perform public.require_comment_allowed(caller_id, story);
  -- Step 3: a reply needs a parent the caller can see, on this chapter.
  if reply_to is not null then
    select * into parent from public.comments where comments.id = reply_to and comments.chapter_id = chapter.id;
    if parent.id is null or not public.comment_is_shown_to_caller(parent) then
      raise exception 'That comment isn''t there any more.' using errcode = 'no_data_found';
    end if;
  end if;
  -- Step 4: save it (the trigger keeps replies one level deep) and queue the notification job.
  insert into public.comments (user_id, chapter_id, parent_comment_id, body, is_spoiler)
  values (caller_id, chapter.id, reply_to, public.check_comment_text(body), coalesce(is_spoiler, false))
  returning id into new_comment_id;
  insert into public.jobs (kind, payload)
  values ('comment_posted', jsonb_build_object('comment_id', new_comment_id, 'chapter_id', chapter.id,
    'parent_comment_id', reply_to));
  return jsonb_build_object('id', new_comment_id);
end;
$$;


ALTER FUNCTION "public"."post_comment"("story_slug" "text", "chapter_code" "text", "body" "text", "is_spoiler" boolean, "reply_to" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_comment"("story_slug" "text", "chapter_code" "text", "body" "text", "is_spoiler" boolean, "reply_to" "uuid") IS 'Posts a comment or a one-level reply on a chapter, through the account gate and the limit (S1-E6-01).';



CREATE OR REPLACE FUNCTION "public"."post_paragraph_comment"("story_slug" "text", "chapter_code" "text", "block_number" integer, "body" "text", "is_spoiler" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  chapter public.chapters;
  story public.stories;
  paragraph_text text;
  new_comment_id uuid;
begin
  -- Step 1: signed in, and the chapter is one this reader may open.
  if caller_id is null then
    raise exception 'Log in to comment.' using errcode = 'insufficient_privilege';
  end if;
  select * into chapter from public.readable_chapter(story_slug, chapter_code);
  if chapter.id is null then
    raise exception 'There is no such chapter.' using errcode = 'no_data_found';
  end if;
  select * into story from public.stories where stories.id = chapter.story_id;
  -- Step 2: comments on, the account gate and the limit (the same checks as post_comment()).
  perform public.require_comment_allowed(caller_id, story);
  -- Step 3: the paragraph, as the chapter is published now.
  select blocks.block_text into paragraph_text
  from public.chapter_blocks(chapter.published_body) as blocks
  where blocks.block_number = post_paragraph_comment.block_number;
  if paragraph_text is null then
    raise exception 'That paragraph isn''t there any more.' using errcode = 'no_data_found';
  end if;
  -- Step 4: save it with the paragraph's place and fingerprint, and queue the notification job.
  insert into public.comments (user_id, chapter_id, body, is_spoiler, paragraph_key, paragraph_number)
  values (caller_id, chapter.id, public.check_comment_text(body), coalesce(is_spoiler, false),
          public.paragraph_key_of(paragraph_text), post_paragraph_comment.block_number)
  returning id into new_comment_id;
  insert into public.jobs (kind, payload)
  values ('comment_posted', jsonb_build_object('comment_id', new_comment_id, 'chapter_id', chapter.id,
    'parent_comment_id', null));
  return jsonb_build_object('id', new_comment_id);
end;
$$;


ALTER FUNCTION "public"."post_paragraph_comment"("story_slug" "text", "chapter_code" "text", "block_number" integer, "body" "text", "is_spoiler" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_paragraph_comment"("story_slug" "text", "chapter_code" "text", "block_number" integer, "body" "text", "is_spoiler" boolean) IS 'Posts a comment on one paragraph of a chapter, through the account gate and the limit (S1-E6-06).';



CREATE OR REPLACE FUNCTION "public"."preview_story_plan"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to preview your story.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object('outcome', 'ok',
      'is_published', public.story_has_readable_chapter(target_story_id))
    || public.public_plan_json(target_story_id, true);
end;
$$;


