CREATE OR REPLACE FUNCTION "public"."profile_is_open_to"("owner" "public"."profiles", "viewer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when viewer_id is not null and viewer_id = owner.id then true
    else case public.profile_audience_of(owner)
      when 'everyone' then true
      when 'members' then viewer_id is not null
      else exists (select 1 from public.follows_users
                   where follows_users.user_id = owner.id and follows_users.followed_user_id = viewer_id)
    end
  end;
$$;


ALTER FUNCTION "public"."profile_is_open_to"("owner" "public"."profiles", "viewer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_is_open_to"("owner" "public"."profiles", "viewer_id" "uuid") IS 'Internal: whether a visitor sees someone''s whole profile (S1-E13-01).';



CREATE OR REPLACE FUNCTION "public"."profile_rank"("wanted_handle" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'rank', writer_ranks.rank,
    'chapters', coalesce(writer_ranks.chapter_count, 0),
    'words', coalesce(writer_ranks.word_count, 0))
  from public.profile_for_handle(wanted_handle) as writer
  left join public.writer_ranks on writer_ranks.user_id = writer.id
  where public.profile_is_open_to(writer, (select auth.uid()))
    and not exists (select 1 from public.blocks
                    where blocks.user_id = writer.id and blocks.blocked_user_id = (select auth.uid()));
$$;


ALTER FUNCTION "public"."profile_rank"("wanted_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_rank"("wanted_handle" "text") IS 'A profile''s rank with its published chapters and words, by the profile''s own visibility rules (S1-E8-09).';



CREATE OR REPLACE FUNCTION "public"."profile_reader_level"("wanted_handle" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'level', public.reader_level_from(counts.chapters_read, counts.stories_finished),
    'chapters_read', counts.chapters_read,
    'stories_finished', counts.stories_finished,
    'is_shown', reader.shows_reader_level,
    'is_own', reader.id = (select auth.uid()))
  from public.profile_for_handle(wanted_handle) as reader
  cross join lateral public.reader_level_counts(reader.id) as counts
  -- The owner always sees their own; anyone else only what the owner chose to show.
  where reader.id = (select auth.uid())
     or (reader.shows_reader_level
         and public.profile_is_open_to(reader, (select auth.uid()))
         and not exists (select 1 from public.blocks
                         where blocks.user_id = reader.id
                           and blocks.blocked_user_id = (select auth.uid())));
$$;


ALTER FUNCTION "public"."profile_reader_level"("wanted_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_reader_level"("wanted_handle" "text") IS 'A profile''s reading level: always for its owner, for others only when shown, by the profile''s own visibility rules (G7a).';



