    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.signature_json(writer.id)
  from public.profile_for_handle(wanted_handle) as writer
  where public.profile_is_open_to(writer, (select auth.uid()))
    and not exists (select 1 from public.blocks
                    where blocks.user_id = writer.id and blocks.blocked_user_id = (select auth.uid()));
$$;


ALTER FUNCTION "public"."profile_signature"("wanted_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_signature"("wanted_handle" "text") IS 'The forum signature shown on a profile, by the profile''s own visibility rules (S1-E8-08).';



CREATE OR REPLACE FUNCTION "public"."profile_story_cards"("writer_id" "uuid", "is_owner" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', stories.id,
      'slug', stories.slug,
      'title', stories.title,
      'blurb', stories.blurb,
      'category_slug', categories.slug,
      'completion_status', stories.completion_status,
      'rating', stories.rating,
      'cover', jsonb_build_object('kind', stories.cover_kind, 'design', stories.cover_design,
        'background', stories.cover_background, 'accent', stories.cover_accent),
      -- QA-2a: only published, undeleted chapters can be readable; saying so lets Postgres use
      -- chapters_published_idx.
      'chapter_count', (select count(*) from public.chapters
        where chapters.story_id = raw.id
          and chapters.status = 'published' and chapters.deleted_at is null
          and public.chapter_is_readable(chapters.id)),
      'last_chapter_published_at', stories.last_chapter_published_at
    ) order by stories.last_chapter_published_at desc nulls last, stories.title), '[]'::jsonb)
  -- S1-E11-08: each story as the caller may see it (a hidden title or cover masked).
  from public.stories as raw
  cross join lateral (select (public.story_as_shown(raw)).*) as stories
  join public.categories on categories.id = stories.category_id
  where raw.user_id = writer_id
    and raw.deleted_at is null
    and public.story_has_readable_chapter(raw.id)
    and not public.is_moderated_away('story', raw.id)
    and (is_owner or public.rating_allows(raw.rating))
    -- S1-E8-11: a class-only story isn't on the writer's public profile.
    and (is_owner or not raw.class_only)
    -- NEW-1: unlisted and private stories aren't on the writer's public profile.
    and (is_owner or raw.visibility = 'public');
$$;


ALTER FUNCTION "public"."profile_story_cards"("writer_id" "uuid", "is_owner" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."profile_story_cards"("writer_id" "uuid", "is_owner" boolean) IS 'Internal: the stories a reader may see on a profile (S1-E5-05).';



CREATE OR REPLACE FUNCTION "public"."public_character_json"("target_character" "public"."story_characters", "with_sheet" boolean, "as_preview" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', target_character.id, 'name', target_character.name, 'role', target_character.role,
    'gender', target_character.gender,
    'sheet', case when with_sheet then coalesce((
        select jsonb_object_agg(sheet_text.key, sheet_text.value)
        from jsonb_each(target_character.sheet) as sheet_text
        where sheet_text.key = any (public.character_part_keys(target_character.public_sheet_parts))
          and sheet_text.value #>> '{}' <> ''), '{}'::jsonb) else '{}'::jsonb end,
    'custom_values', case when with_sheet then coalesce((
        select jsonb_object_agg(custom.key, custom.value)
        from jsonb_each(target_character.custom_values) as custom
        join public.story_character_fields as fields on fields.id::text = custom.key
        where custom.key = any (target_character.public_sheet_parts)
          and fields.hidden_at is null and custom.value #>> '{}' <> ''), '{}'::jsonb) else '{}'::jsonb end,
    'first_appearance', case when with_sheet and 'in_the_story' = any (target_character.public_sheet_parts) then (
        select chapters.code from public.chapters
        where chapters.id = target_character.first_appearance_chapter_id
          and public.chapter_is_readable(chapters.id)) end,
    -- Only a picture that passed its check and wasn't moderated away (rule 19).
    'picture', (select public.picture_state_json(picture_checks) from public.picture_checks
                where picture_checks.id = target_character.picture_id
                  and picture_checks.deleted_at is null
                  and public.picture_is_visible(picture_checks.bucket, picture_checks.path)),
    'picture_alt', target_character.picture_alt,
    'show_from', public.plan_guard_json(target_character.show_from_chapter_id, as_preview));
$$;


ALTER FUNCTION "public"."public_character_json"("target_character" "public"."story_characters", "with_sheet" boolean, "as_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_character_json"("target_character" "public"."story_characters", "with_sheet" boolean, "as_preview" boolean) IS 'Internal: one character as readers see it, with only the sheet''s open parts (S1-E17-32, S1-E17-33).';



CREATE OR REPLACE FUNCTION "public"."public_forum_highlights"("wanted_language" "text" DEFAULT 'ro'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    -- Step 1: threads in the platform's forums, busiest this week first.
    'threads', coalesce((
      select jsonb_agg(picked.card order by picked.recent_posts desc, picked.last_post_at desc)
      from (
        select jsonb_build_object(
            'forum_slug', forums.slug,
            'forum_name', (select names.name from public.forum_name_in(forums.id, wanted_language) as names),
            'number', threads.thread_number,
            'title', threads.title,
            'starter', public.forum_person_json(threads.user_id) - 'is_staff',
            'reply_count', greatest(public.forum_live_post_count(threads.id) - 1, 0)) as card,
          (select count(*) from public.forum_posts as posts
           where posts.thread_id = threads.id and posts.deleted_at is null
             and posts.created_at > now() - interval '7 days') as recent_posts,
          threads.last_post_at
        from public.forum_threads as threads
        join public.forums on forums.id = threads.forum_id
          and forums.deleted_at is null and forums.space_id is null
        where public.forum_thread_is_shown(threads)
          and not public.is_moderated_away('forum_thread', threads.id)
          and public.may_spotlight_writer(threads.user_id)
        order by recent_posts desc, threads.last_post_at desc
        limit 4
      ) as picked), '[]'::jsonb),
    -- Step 2: public spaces for 16 and over, most recently active first.
    'spaces', coalesce((
      select jsonb_agg(jsonb_build_object('slug', listed.slug, 'name', listed.name)
                       order by listed.active_at desc)
      from (
        select spaces.slug, spaces.name, public.space_latest_activity(spaces) as active_at
        from public.spaces
        where spaces.deleted_at is null and spaces.archived_at is null
          and spaces.kind = 'open' and spaces.readers = 'everybody' and spaces.age_group = '16_plus'
          and not public.is_moderated_away('space', spaces.id)
          and not public.is_blocked_with(spaces.user_id)
          and public.may_spotlight_writer(spaces.user_id)
        order by active_at desc nulls last
        limit 4
      ) as listed), '[]'::jsonb));
$$;


ALTER FUNCTION "public"."public_forum_highlights"("wanted_language" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_forum_highlights"("wanted_language" "text") IS 'The home page''s forums band for anyone: busy threads in the platform''s own forums and public 16+ spaces, never a class, private or under-16 space (LOOK-3).';



CREATE OR REPLACE FUNCTION "public"."public_notice_payload_is_signed"("payload" "text", "signature" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  secret text;
begin
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'public_notice_secret';
  if secret is null or secret = '' or signature is null then
    return false;
  end if;
  return encode(extensions.hmac(payload, secret, 'sha256'), 'hex') = lower(signature);
end;
$$;


ALTER FUNCTION "public"."public_notice_payload_is_signed"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_notice_payload_is_signed"("payload" "text", "signature" "text") IS 'Internal: checks a public notice''s signature against the Vault secret public_notice_secret (S1-E10-02).';



CREATE OR REPLACE FUNCTION "public"."public_plan_bible"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(section_json order by section_position), '[]'::jsonb) from (
    select sections.position as section_position,
      jsonb_build_object('id', sections.id, 'preset', sections.preset, 'name', sections.name,
        'entries', jsonb_agg(jsonb_build_object('id', entries.id, 'title', entries.title,
            'tags', to_jsonb(entries.tags), 'body', entries.body,
            'show_from', public.plan_guard_json(entries.show_from_chapter_id, as_preview))
          order by lower(entries.title), entries.created_at)) as section_json
    from public.story_bible_sections as sections
    join public.story_bible_entries as entries on entries.section_id = sections.id
    where sections.story_id = target_story_id
      and 'bible' = any (areas)
      and public.plan_item_shows(sections.id, sections.is_private, null, as_preview)
      and public.plan_item_shows(entries.id, entries.is_private, entries.show_from_chapter_id, as_preview)
    group by sections.id) as shown_sections;
$$;


ALTER FUNCTION "public"."public_plan_bible"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_plan_bible"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) IS 'Internal: the world sections and entries readers see (S1-E17-33).';



CREATE OR REPLACE FUNCTION "public"."public_plan_characters"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(public.public_character_json(characters, 'characters' = any (areas), as_preview)
      order by lower(characters.name), characters.created_at), '[]'::jsonb)
  from public.story_characters as characters
  where characters.story_id = target_story_id
    and areas && array['characters', 'relationship_map', 'family_tree']
    and public.plan_item_shows(characters.id, characters.is_private, characters.show_from_chapter_id, as_preview);
$$;


