ALTER FUNCTION "public"."public_plan_events"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."public_plan_events"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) IS 'Internal: the timeline events readers see (S1-E17-33).';



CREATE OR REPLACE FUNCTION "public"."public_plan_fields"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', fields.id, 'name', fields.name)
      order by fields.position, fields.created_at), '[]'::jsonb)
