COMMENT ON FUNCTION "public"."public_plan_relationships"("target_story_id" "uuid", "areas" "text"[], "as_preview" boolean) IS 'Internal: the relationships readers see, without the writer''s notes (S1-E17-33).';



CREATE OR REPLACE FUNCTION "public"."publish_chapter"("chapter_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter public.chapters := public.my_live_chapter(chapter_code);
  refusal text := public.chapter_gate_outcome(chapter);
begin
  if refusal is not null then
    return jsonb_build_object('outcome', refusal);
  end if;
  if chapter.status = 'published' then
    return jsonb_build_object('outcome', 'wrong_state');
  end if;
  if btrim(chapter.draft_body) = '' then
    return jsonb_build_object('outcome', 'empty');
  end if;
  perform public.chapter_publish_now(chapter);
  return jsonb_build_object('outcome', 'ok', 'published_at', now());
end;
$$;


ALTER FUNCTION "public"."publish_chapter"("chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_chapter"("chapter_code" "text") IS 'Puts the caller''s own chapter live now: {outcome: ok | not_active | not_found | empty | wrong_state} (S1-E3-03).';



CREATE OR REPLACE FUNCTION "public"."publish_due_chapters"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  due public.chapters;
  published_count integer := 0;
begin
  for due in
    select chapters.* from public.chapters
    join public.stories on stories.id = chapters.story_id
    where chapters.status = 'scheduled'
      and chapters.scheduled_for <= now()
      and chapters.deleted_at is null
      and stories.deleted_at is null
      and public.account_state(chapters.user_id) = 'active'
    order by chapters.scheduled_for
    for update of chapters skip locked
  loop
    perform public.chapter_publish_now(due);
    published_count := published_count + 1;
  end loop;
  return published_count;
end;
$$;


ALTER FUNCTION "public"."publish_due_chapters"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_due_chapters"() IS 'The every-minute job: publishes scheduled chapters whose time has come (S1-E3-03, architecture B17).';



CREATE OR REPLACE FUNCTION "public"."published_interface_text"("wanted_locale" "text") RETURNS TABLE("text_key" "text", "text" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- The locale's own overrides first, then its base language's for keys it doesn't override.
  with own as (
    select live.text_key, live.text, live.is_reset from public.interface_text_live(wanted_locale) as live
  ),
  base as (
    select live.text_key, live.text, live.is_reset
    from public.interface_text_live(split_part(wanted_locale, '-', 1)) as live
    where wanted_locale like '%-%'
      and not exists (select 1 from own where own.text_key = live.text_key)
  )
  select chosen.text_key, chosen.text
  from (select * from own union all select * from base) as chosen
  where not chosen.is_reset;
$$;


ALTER FUNCTION "public"."published_interface_text"("wanted_locale" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."published_interface_text"("wanted_locale" "text") IS 'The live interface text overrides of a locale, for the app and the email sender (S1-E11-18, S1-E11-19).';



CREATE OR REPLACE FUNCTION "public"."published_order"("target_story_id" "uuid", "chapter_codes" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(chapters.code order by coalesce(listed.place, chapters.position)), '{}')
  from public.chapters
  left join unnest(chapter_codes) with ordinality as listed(code, place) on listed.code = chapters.code
  where chapters.story_id = target_story_id and chapters.deleted_at is null
    and chapters.status = 'published';
$$;


