CREATE OR REPLACE FUNCTION "public"."queue_daily_digests"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  queued integer;
begin
  insert into public.email_outbox (user_id, delivery, notification_ids)
  select notifications.user_id, 'daily', array_agg(notifications.id order by notifications.updated_at desc)
  from public.notifications
  where notifications.read_at is null
    and notifications.updated_at > now() - interval '1 day'
    and public.email_delivery_for(notifications.user_id, notifications.kind) = 'daily'
    and not exists (select 1 from public.email_outbox
                    where notifications.id = any (email_outbox.notification_ids))
  group by notifications.user_id;
  get diagnostics queued = row_count;
  return queued;
end;
$$;


ALTER FUNCTION "public"."queue_daily_digests"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_daily_digests"() IS 'Internal: queues one daily digest per person (S1-E7-02); pg_cron at 06:00 UTC.';



CREATE OR REPLACE FUNCTION "public"."queue_instant_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  delivery text := public.email_delivery_for(new.user_id, new.kind);
begin
  if delivery in ('instant', 'required') then
    insert into public.email_outbox (user_id, delivery, notification_ids)
    values (new.user_id, delivery, array[new.id]);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."queue_instant_email"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_instant_email"() IS 'Internal trigger: queues an instant or required email for a new notification (S1-E7-02).';



CREATE OR REPLACE FUNCTION "public"."queue_message_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chat public.conversations;
  recipient public.profiles;
begin
  -- Step 1: the chat and the other person in it.
  select * into chat from public.conversations where conversations.id = new.conversation_id;
  select profiles.* into recipient from public.profiles
  where profiles.id = case when chat.user_id = new.user_id then chat.recipient_user_id else chat.user_id end
    and profiles.deleted_at is null;
  if chat.id is null or recipient.id is null or chat.status = 'declined' then
    return new;
  end if;
  -- Step 2: their choice, and one email per chat at a time.
  if not (public.message_email_choices(recipient) ->> 'emails_on')::boolean then
    return new;
  end if;
  if exists (select 1 from public.email_outbox
             where email_outbox.user_id = recipient.id and email_outbox.conversation_id = chat.id
               and email_outbox.sent_at is null) then
    return new;
  end if;
  -- Step 3: the email, held until the short wait and any quiet hours are over.
  insert into public.email_outbox (user_id, delivery, notification_ids, conversation_id, send_after)
  values (recipient.id, 'message', '{}', chat.id, public.message_email_send_time(recipient.id, now()));
  return new;
end;
$$;


ALTER FUNCTION "public"."queue_message_email"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_message_email"() IS 'Internal trigger: queues one email per chat for a new private message (IDEAS-2 idea 6).';



