COMMENT ON FUNCTION "public"."raise_rating_for_picture"("picture" "public"."picture_checks", "new_rating" "public"."story_rating", "reason_given" "text") IS 'Internal: the yellow button raises the picture''s story to 16+ or 18+, never down (ADMIN-2e1b).';



CREATE OR REPLACE FUNCTION "public"."rank_for"("chapter_count" integer, "word_count" integer) RETURNS "public"."writer_rank"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when word_count >= 100000 then 'novelist'::public.writer_rank
    when chapter_count >= 15 or word_count >= 30000 then 'storyteller'::public.writer_rank
    when chapter_count >= 5 then 'writer'::public.writer_rank
    when chapter_count >= 1 then 'new_writer'::public.writer_rank
  end;
$$;


