CREATE OR REPLACE FUNCTION "public"."rating_allows"("story_rating" "public"."story_rating") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  band public.age_band := public.age_band();
  check_result public.age_check_result;
begin
  -- Step 1: the two ratings every signed-in person and every visitor may see.
  if story_rating = 'all_ages' then
    return true;
  end if;
  if story_rating = '13_plus' then
    return band in ('13_to_15', '16_to_17', '18_plus', 'unknown');
  end if;
  -- Step 2: 16+ needs 16 and over (a visitor's band is 'unknown': no).
  if story_rating = '16_plus' then
    return band in ('16_to_17', '18_plus');
  end if;
  -- Step 3: 18+ needs 18 and over by year, and the Yoti result once the March flag is off.
  if band <> '18_plus' then
    return false;
  end if;
  if public.is_feature_enabled('adults_only') then
    return true;
  end if;
  select profiles.age_check_result into check_result
  from public.profiles where profiles.id = (select auth.uid());
  return check_result = '18_or_over';
end;
$$;


ALTER FUNCTION "public"."rating_allows"("story_rating" "public"."story_rating") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rating_allows"("story_rating" "public"."story_rating") IS 'May the caller see a story with this rating; the one rule every reader path uses (S1-E3-06, rule 18).';



CREATE OR REPLACE FUNCTION "public"."rating_fits_band"("rating" "public"."story_rating", "band" "public"."age_band") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case rating
    when 'all_ages' then true
    when '13_plus' then band in ('13_to_15', '16_to_17', '18_plus')
    when '16_plus' then band in ('16_to_17', '18_plus')
    else band = '18_plus'
  end;
$$;


ALTER FUNCTION "public"."rating_fits_band"("rating" "public"."story_rating", "band" "public"."age_band") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rating_fits_band"("rating" "public"."story_rating", "band" "public"."age_band") IS 'Internal: whether an age group may see something with a rating; an unknown age sees only all ages (GAPS-12h).';



CREATE OR REPLACE FUNCTION "public"."react_to_comment"("comment_id" "uuid", "wanted_kind" "public"."reaction_kind") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target public.comments;
  address record;
  current_kind public.reaction_kind;
begin
  -- Step 1: signed in, and a live comment on a chapter this reader may open.
  if caller_id is null then
    raise exception 'Log in to react.' using errcode = 'insufficient_privilege';
  end if;
  select * into target from public.comments where comments.id = comment_id;
  select stories.slug, chapters.code into address
  from public.chapters join public.stories on stories.id = chapters.story_id
  where chapters.id = target.chapter_id;
  if target.id is null
     or not exists (select 1 from public.readable_chapter(address.slug, address.code))
     or public.comment_state_for_caller(target) is distinct from 'live' then
    raise exception 'That comment isn''t there any more.' using errcode = 'no_data_found';
  end if;
  -- Step 2: the same kind again, or none, takes the reaction away; always allowed.
  select comment_reactions.kind into current_kind from public.comment_reactions
  where comment_reactions.comment_id = target.id and comment_reactions.user_id = caller_id;
  if wanted_kind is null or wanted_kind = current_kind then
    delete from public.comment_reactions
    where comment_reactions.comment_id = target.id and comment_reactions.user_id = caller_id;
    return public.comment_reactions_json(target.id);
  end if;
  -- Step 3: adding or changing one is a write, so the account gate applies.
  if not public.is_active_member() then
    raise exception 'Your account can''t react right now.' using errcode = 'insufficient_privilege';
  end if;
  insert into public.comment_reactions (user_id, comment_id, kind) values (caller_id, target.id, wanted_kind)
  on conflict on constraint comment_reactions_one_per_person do update set kind = excluded.kind;
  return public.comment_reactions_json(target.id);
end;
$$;


