COMMENT ON FUNCTION "public"."reader_reached_chapter"("target_chapter_id" "uuid") IS 'Internal: true when the caller''s reading reached the chapter, or there is no chapter (S1-E17-35).';



CREATE OR REPLACE FUNCTION "public"."reader_visible_story"("story_slug" "text") RETURNS SETOF "public"."stories"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select shown.* from public.stories
  cross join lateral public.story_as_shown(stories) as shown
  where stories.slug = story_slug
    and stories.deleted_at is null
    and not public.is_moderated_away('story', stories.id)
    -- S1-E8-11: a story shared only with a class opens only for its writer and that class.
    and public.story_class_allows(stories.class_only, stories.class_space_id, stories.user_id)
    -- NEW-1: a private story opens only for its writer; an unlisted one for anyone with the link.
    and public.story_visibility_allows(stories.visibility, stories.user_id)
    and (
      stories.user_id = (select auth.uid())
      or (public.rating_allows(stories.rating) and not public.is_blocked_with(stories.user_id))
    );
$$;


ALTER FUNCTION "public"."reader_visible_story"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reader_visible_story"("story_slug" "text") IS 'Internal: the story behind an address when the caller may read it (S1-E4-01a).';



CREATE OR REPLACE FUNCTION "public"."reading_list"("list_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.reading_list_json(reading_lists)
    || case when reading_lists.user_id = (select auth.uid()) then jsonb_build_object('entries', (
        select coalesce(jsonb_agg(jsonb_build_object('slug', shown.slug, 'title', shown.title)
          order by entries.created_at desc), '[]'::jsonb)
        from public.listed_stories('reading_list', reading_lists.id::text, null, null, null) as shown
        join public.reading_list_stories as entries
          on entries.list_id = reading_lists.id and entries.story_id = shown.id))
      else '{}'::jsonb end
  from public.reading_lists
  where reading_lists.id = list_id and public.reading_list_is_visible(reading_lists);
$$;


ALTER FUNCTION "public"."reading_list"("list_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reading_list"("list_id" "uuid") IS 'One reading list the caller may see (their own, or a public one), for its page; null otherwise (GAPS-6).';



CREATE TABLE IF NOT EXISTS "public"."reading_lists" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "is_public" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "reading_lists_name_check" CHECK (((("char_length"("name") >= 1) AND ("char_length"("name") <= 60)) AND ("name" !~ '[\n\r]'::"text")))
);


