CREATE OR REPLACE FUNCTION "public"."rebuild_story_search_documents"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  done integer := 0;
  story_row record;
begin
  for story_row in select id from public.stories loop
    perform public.refresh_story_search_document(story_row.id);
    done := done + 1;
  end loop;
  return done;
end;
$$;


