CREATE OR REPLACE FUNCTION "public"."receive_support_email"("payload" "text", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fields jsonb;
  sender text;
  email_id text;
  clean_subject text;
  clean_body text;
  existing_number bigint;
  ticket public.support_tickets;
begin
  -- Step 1: only a fresh payload our server signed.
  if not public.support_payload_is_signed(payload, signature) then
    raise exception 'This email didn''t come through our server.' using errcode = 'insufficient_privilege';
  end if;
  fields := payload::jsonb;
  if (fields ->> 'sentAt')::timestamptz < now() - interval '15 minutes' then
    raise exception 'This email is too old to save.' using errcode = 'insufficient_privilege';
  end if;
  sender := lower(btrim(fields ->> 'from'));
  email_id := nullif(left(btrim(coalesce(fields ->> 'messageId', '')), 998), '');
  -- Step 2: an email saved before is not saved again.
  select tickets.number into existing_number from public.support_ticket_messages as messages
  join public.support_tickets as tickets on tickets.id = messages.ticket_id
  where messages.email_message_id = email_id;
  if existing_number is not null then
    return jsonb_build_object('number', existing_number, 'created', false, 'acknowledged', false);
  end if;
  -- Step 3: the words, trimmed to what a ticket holds; an empty email still makes a ticket.
  clean_subject := coalesce(nullif(left(btrim(coalesce(fields ->> 'subject', '')), 150), ''), '(no subject)');
  clean_body := coalesce(nullif(left(btrim(coalesce(fields ->> 'text', '')), 10000), ''), '(This email had no text.)');
  -- Step 4: an answer to an open ticket joins it; to a closed one starts a linked follow-up.
  ticket := public.support_ticket_for_email(sender, clean_subject, fields ->> 'threadHeaders');
  if ticket.id is not null and ticket.status <> 'closed' then
    return jsonb_build_object('number', public.add_email_to_support_ticket(ticket, clean_body, email_id),
      'created', false, 'acknowledged', false);
  end if;
  return public.start_email_support_ticket(sender, clean_subject, clean_body, email_id,
    (fields ->> 'automatic')::boolean, ticket.id) || jsonb_build_object('created', true);
end;
$$;


ALTER FUNCTION "public"."receive_support_email"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."receive_support_email"("payload" "text", "signature" "text") IS 'Saves an email to the support inbox, signed by our server, in its ticket or a new one (S1-E11-13 criteria 1, 3 and 7).';



CREATE OR REPLACE FUNCTION "public"."recently_banned_ip_matches"("new_user_id" "uuid") RETURNS TABLE("banned_user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with mine as (
    select sign_up_ips.ip_scrambled, sign_up_ips.ip_period from public.sign_up_ips
    where sign_up_ips.user_id = new_user_id
  ),
  banned as (
    select distinct sanctions.user_id from public.sanctions
    where sanctions.kind = 'ban' and sanctions.lifted_at is null and sanctions.user_id <> new_user_id
      and sanctions.created_at > now() - make_interval(days => public.keep_setting('returning_user_window_days', 30))
  )
  select banned.user_id from banned
  where exists (select 1 from public.sign_up_ips join mine using (ip_scrambled, ip_period)
                where sign_up_ips.user_id = banned.user_id)
     or exists (select 1 from public.picture_checks
                join mine on mine.ip_scrambled = picture_checks.uploader_ip_scrambled
                         and mine.ip_period = picture_checks.uploader_ip_period
                where picture_checks.user_id = banned.user_id);
$$;


ALTER FUNCTION "public"."recently_banned_ip_matches"("new_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recently_banned_ip_matches"("new_user_id" "uuid") IS 'Internal: recently banned accounts that share a scrambled IP with a new sign-up (part f2).';



CREATE OR REPLACE FUNCTION "public"."record_abuse_image_evidence"("picture" "public"."picture_checks", "found_case" "public"."cases", "found_by" "text", "description_text" "text", "described_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  evidence_id uuid;
begin
  -- Step 1: the evidence row, kept 5 years (setting abuse_image_evidence_keep_years).
  insert into public.abuse_image_evidence (user_id, case_id, case_reference, picture_id, picture_kind,
      uploaded_at, source, file_sha256, uploader_ip_scrambled, uploader_ip_period, description,
      described_by_user_id, keep_until)
  values (picture.user_id, found_case.id, found_case.reference, picture.id, picture.kind, picture.created_at,
      found_by, picture.file_sha256, picture.uploader_ip_scrambled, picture.uploader_ip_period,
      btrim(description_text), described_by,
      now() + make_interval(years => public.keep_setting('abuse_image_evidence_keep_years', 5)))
  on conflict (picture_id) do update set
    description = excluded.description,
    described_by_user_id = excluded.described_by_user_id
  returning id into evidence_id;
  -- Step 2: the file is never kept, so nothing preserves it any more (replaces S1-E10-10's six months).
  update public.picture_checks set preserve_until = null where id = picture.id;
  -- Step 3: start the storage sweep now; it lists this file at once (storage_files_to_sweep).
  perform public.run_storage_sweep();
  -- Step 4: the audit log, when a staff member decided it (a match is the check's own doing).
  if public.is_staff_session() then
    perform public.log_staff_action('safeguarding.abuse_image_evidence_kept', 'abuse_image_evidence',
      evidence_id::text, picture.user_id, btrim(description_text), null,
      jsonb_build_object('case_reference', found_case.reference, 'source', found_by,
                         'has_hash', picture.file_sha256 is not null,
                         'has_scrambled_ip', picture.uploader_ip_scrambled is not null));
  end if;
  return evidence_id;
end;
$$;


ALTER FUNCTION "public"."record_abuse_image_evidence"("picture" "public"."picture_checks", "found_case" "public"."cases", "found_by" "text", "description_text" "text", "described_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_abuse_image_evidence"("picture" "public"."picture_checks", "found_case" "public"."cases", "found_by" "text", "description_text" "text", "described_by" "uuid") IS 'Internal: keeps the evidence about a suspected child sexual abuse image and starts deleting its file (ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."record_age_check_result"("yoti_session_id" "text", "outcome" "text", "method" "public"."age_check_method", "signature" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_row public.age_check_sessions;
  stored public.age_check_result;
begin
  -- Step 1: only our server's signed payload counts.
  if not public.age_check_is_signed(
       'result|' || record_age_check_result.yoti_session_id || '|' || record_age_check_result.outcome
       || '|' || record_age_check_result.method, signature) then
    raise exception 'Only our server can record an age check.' using errcode = 'insufficient_privilege';
  end if;
  if record_age_check_result.outcome not in ('passed', 'failed') then
    raise exception 'Unknown outcome.' using errcode = 'check_violation', hint = 'unknown_outcome';
  end if;
  -- A manual check is a staff decision, never a Yoti result.
  if record_age_check_result.method = 'manual' then
    raise exception 'Unknown method.' using errcode = 'check_violation', hint = 'unknown_method';
  end if;
  -- Step 2: the session must be open; an expired one is simply forgotten.
  delete from public.age_check_sessions
  where age_check_sessions.yoti_session_id = record_age_check_result.yoti_session_id
  returning * into session_row;
  if not found or session_row.expires_at <= now() then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 3: only the result, its date and its method reach the profile (rule 5).
  update public.profiles
  set age_check_result = public.age_check_result_value(
        session_row.threshold, record_age_check_result.outcome = 'passed', profiles.age_check_result),
      age_checked_at = now(),
      age_check_method = record_age_check_result.method
  where profiles.id = session_row.user_id
  returning age_check_result into stored;
  -- Step 4: the attempt, for the history staff see if the person asks for a manual check.
  insert into public.age_check_attempts (user_id, threshold, outcome, method)
  values (session_row.user_id, session_row.threshold, record_age_check_result.outcome,
    record_age_check_result.method);
  return jsonb_build_object('outcome', 'ok', 'result', stored);
end;
$$;


ALTER FUNCTION "public"."record_age_check_result"("yoti_session_id" "text", "outcome" "text", "method" "public"."age_check_method", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_age_check_result"("yoti_session_id" "text", "outcome" "text", "method" "public"."age_check_method", "signature" "text") IS 'Our server stores the result of a finished Yoti age check and forgets its session (S1-E2-08).';



CREATE OR REPLACE FUNCTION "public"."record_chapter_moves"("target_story_id" "uuid", "positions_before" "jsonb", "picked_chapter_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  -- The clock's time, not the transaction's, so two reorders in one transaction keep their order.
  moved_time timestamptz := clock_timestamp();
begin
  -- Step 1: one row per chapter whose number changed.
  insert into public.chapter_moves (user_id, story_id, chapter_id, from_position, to_position, was_picked, created_at)
  select chapters.user_id, chapters.story_id, chapters.id,
         (positions_before ->> chapters.id::text)::integer, chapters.position,
         chapters.id is not distinct from picked_chapter_id, moved_time
  from public.chapters
  where chapters.story_id = target_story_id and chapters.deleted_at is null
    and positions_before ? chapters.id::text
    and (positions_before ->> chapters.id::text)::integer <> chapters.position;
  -- Step 2: the record is kept 90 days, and a story keeps its newest 2,000 rows at most, so
  -- reordering a long story over and over can't fill the table.
  delete from public.chapter_moves
  where chapter_moves.story_id = target_story_id
    and (chapter_moves.created_at < now() - interval '90 days'
         or chapter_moves.id in (
           select older.id from public.chapter_moves as older
           where older.story_id = target_story_id
           order by older.created_at desc, older.id
           offset 2000));
end;
$$;


ALTER FUNCTION "public"."record_chapter_moves"("target_story_id" "uuid", "positions_before" "jsonb", "picked_chapter_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_chapter_moves"("target_story_id" "uuid", "positions_before" "jsonb", "picked_chapter_id" "uuid") IS 'Internal: records which chapters changed number in a reorder, and drops rows over 90 days old or beyond the story''s newest 2,000 (GAPS-11).';



CREATE OR REPLACE FUNCTION "public"."record_chapter_read"("story_slug" "text", "chapter_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  story public.stories;
  read_chapter_id uuid;
begin
  if caller_id is null then
    raise exception 'Sign in to read chapters.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 1: the same rules as get_chapter(); the writer's own reads are left out.
  select * into story from public.reader_visible_story(story_slug);
  if not found or story.user_id = caller_id then
    return false;
  end if;
  select chapters.id into read_chapter_id from public.chapters
  where chapters.code = chapter_code and chapters.story_id = story.id
    and public.chapter_is_readable(chapters.id);
  if read_chapter_id is null then
    return false;
  end if;
  -- Step 2: one more on today's total (the Romanian date, Q7); nothing about the reader is kept.
  insert into public.chapter_reads (chapter_id, read_on, total)
  values (read_chapter_id, (now() at time zone 'Europe/Bucharest')::date, 1)
  on conflict (chapter_id, read_on) do update set total = public.chapter_reads.total + 1;
  return true;
end;
$$;


ALTER FUNCTION "public"."record_chapter_read"("story_slug" "text", "chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_chapter_read"("story_slug" "text", "chapter_code" "text") IS 'Adds one to today''s read total for a chapter the caller may read; never records who (S1-E4-01a).';



CREATE OR REPLACE FUNCTION "public"."record_chapter_share"("story_slug" "text", "chapter_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  shared record;
begin
  -- Step 1: only a signed-in reader's share counts.
  if caller_id is null then
    raise exception 'Log in to share chapters.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a chapter they may read; a writer sharing their own story isn't counted.
  select * into shared from public.shareable_chapter(story_slug, chapter_code);
  if not found or shared.writer_id = caller_id then
    return false;
  end if;
  -- Step 3: the hourly limit; past it the share isn't counted, and nothing is refused.
  begin
    perform public.take_rate_limit('chapter_share');
  exception when program_limit_exceeded then
    return false;
  end;
  -- Step 4: one more on today's total.
  perform public.add_chapter_share(shared.chapter_id);
  return true;
end;
$$;


ALTER FUNCTION "public"."record_chapter_share"("story_slug" "text", "chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_chapter_share"("story_slug" "text", "chapter_code" "text") IS 'Counts one share of a chapter the caller may read; never records who (S1-E4-05).';



CREATE OR REPLACE FUNCTION "public"."record_passage_share"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  shared record;
  today date := (now() at time zone 'Europe/Bucharest')::date;
begin
  -- Step 1: only a signed-in reader's share counts.
  if caller_id is null then
    raise exception 'Log in to share chapters.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: a chapter they may read, not their own, and a range of one to five blocks.
  select * into shared from public.shareable_chapter(story_slug, chapter_code);
  if not found or shared.writer_id = caller_id then
    return false;
  end if;
  if first_block is null or last_block is null or first_block < 1 or last_block < first_block
    or last_block - first_block > 4 then
    return false;
  end if;
  -- Step 3: the same hourly limit as any share; past it nothing is counted, nothing refused.
  begin
    perform public.take_rate_limit('chapter_share');
  exception when program_limit_exceeded then
    return false;
  end;
  -- Step 4: one more on the chapter's total, then on each covered paragraph's.
  perform public.add_chapter_share(shared.chapter_id);
  insert into public.paragraph_shares (chapter_id, paragraph_key, shared_on, total)
  select shared.chapter_id, paragraphs.paragraph_key, today, 1
  from public.chapters,
    lateral public.chapter_paragraphs(chapters.published_body) as paragraphs
  where chapters.id = shared.chapter_id
    and paragraphs.block_number between first_block and last_block
  on conflict (chapter_id, paragraph_key, shared_on)
    do update set total = public.paragraph_shares.total + 1;
  return true;
end;
$$;


ALTER FUNCTION "public"."record_passage_share"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_passage_share"("story_slug" "text", "chapter_code" "text", "first_block" integer, "last_block" integer) IS 'Counts one share of a passage or picture link for its chapter and paragraphs; never records who (IDEAS-1d).';



CREATE OR REPLACE FUNCTION "public"."record_picture_check"("payload" "text", "signature" "text") RETURNS "public"."picture_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  answer jsonb;
  picture public.picture_checks;
  is_match boolean;
  is_passed boolean;
  is_uploader boolean;
begin
  -- Step 1: only a result our server signed, about a picture the caller may check.
  if not public.picture_check_is_signed(payload, signature) then
    raise exception 'This result didn''t come from the picture check.' using errcode = 'insufficient_privilege';
  end if;
  answer := payload::jsonb;
  select * into picture from public.picture_checks where id = (answer ->> 'pictureId')::uuid for update;
  if picture.id is null then
    raise exception 'There is no such picture.' using errcode = 'no_data_found';
  end if;
  is_uploader := picture.user_id = (select auth.uid());
  if not is_uploader and not public.staff_may('moderation', 'act') then
    raise exception 'You can''t check this picture.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: only a pending picture moves on; a service that didn't answer leaves it pending.
  if picture.status <> 'pending' then
    return picture.status;
  end if;
  if answer ->> 'outcome' = 'unavailable' then
    update public.picture_checks set attempts = attempts + 1 where id = picture.id;
    return 'pending';
  end if;
  -- Step 3: passed and allowed to go live shows it; anything else is held for a person. The hash
  -- is kept, and the scrambled IP only when the uploader's own upload sent it (never a staff IP).
  is_match := coalesce((answer ->> 'isKnownAbuseMatch')::boolean, false);
  is_passed := answer ->> 'outcome' = 'passed';
  update public.picture_checks set
    status = case when is_passed and not public.picture_needs_person(picture) then 'passed' else 'held' end::public.picture_status,
    flags = coalesce(answer -> 'flags', '{}'::jsonb),
    provider = left(answer ->> 'provider', 40),
    attempts = attempts + 1,
    checked_at = now(),
    file_sha256 = case when answer ->> 'fileSha256' ~ '^[0-9a-f]{64}$' then answer ->> 'fileSha256' end,
    uploader_ip_scrambled = case when is_uploader and answer #>> '{uploaderIp,value}' ~ '^[0-9a-f]{64}$'
                                 then answer #>> '{uploaderIp,value}' end,
    uploader_ip_period = case when is_uploader and answer #>> '{uploaderIp,value}' ~ '^[0-9a-f]{64}$'
                                   and answer #>> '{uploaderIp,period}' ~ '^[0-9]{4}-[0-9]{2}$'
                              then answer #>> '{uploaderIp,period}' end
  where id = picture.id
  returning * into picture;
  -- Step 4: show it, or open the case: a flag is a picture_check case, a rule a picture_review one.
  if picture.status = 'passed' then
    perform public.show_passed_avatar(picture);
  elsif is_passed then
    update public.picture_checks set case_id = public.open_picture_review_case(picture) where id = picture.id;
  else
    update public.picture_checks set case_id = public.open_picture_case(picture, is_match) where id = picture.id
      returning * into picture;
  end if;
  -- Step 5: a match keeps the evidence and the file goes at once (brief section 4).
  if is_match then
    perform public.record_abuse_image_evidence(picture, (select cases from public.cases where cases.id = picture.case_id),
      'known_image_match', 'Matched a known image on Arachnid Shield’s list. A safeguarding moderator adds a description.',
      null);
  end if;
  return picture.status;
end;
$_$;


ALTER FUNCTION "public"."record_picture_check"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_picture_check"("payload" "text", "signature" "text") IS 'Saves the signed picture check result with the file''s hash; a match keeps the evidence and deletes the file (S1-E10-05, ADMIN-2e1b, ADMIN-2e2b).';



CREATE OR REPLACE FUNCTION "public"."record_picture_opened"("picture_id" "uuid", "place" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  opener_id uuid := (select auth.uid());
  owner_id uuid;
  recipient_id uuid;
begin
  -- Step 1: nothing to log for a system call, or when this opening was logged a moment ago.
  if opener_id is null or exists (
      select 1 from public.audit_log
      where audit_log.user_id = opener_id and audit_log.action = 'picture.opened'
        and audit_log.target_id = picture_id::text and audit_log.created_at > now() - interval '10 minutes') then
    return;
  end if;
  -- Step 2: the audit log names the picture, its uploader and the screen.
  select picture_checks.user_id into owner_id from public.picture_checks where picture_checks.id = picture_id;
  perform public.log_staff_action('picture.opened', 'picture_checks', picture_id::text, owner_id,
    'Opened on ' || place, null, jsonb_build_object('place', place));
  -- Step 3: the alert, in the app and by email (email_delivery_for() makes it required).
  for recipient_id in select * from public.picture_open_alert_recipients() loop
    perform public.notify(recipient_id, 'picture_opened_by_staff', opener_id, '{}'::jsonb,
      'picture_opened:' || opener_id::text, interval '1 hour');
  end loop;
end;
$$;


