CREATE OR REPLACE FUNCTION "public"."record_sign_in_failure"("email_hash" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  pause_end timestamptz;
begin
  -- Step 1: a hash, never anything that could be an email.
  if coalesce(email_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'Expected a SHA-256 hash.' using errcode = 'check_violation';
  end if;
  -- Step 2: forget tries older than a day (retention: 24 hours).
  delete from public.sign_in_failures where failed_at < now() - interval '24 hours';
  -- Step 3: during a pause, store nothing more; otherwise note the try and ask again.
  pause_end := public.sign_in_pause_until(email_hash);
  if pause_end is not null then
    return pause_end;
  end if;
  insert into public.sign_in_failures (email_hash) values (record_sign_in_failure.email_hash);
  return public.sign_in_pause_until(email_hash);
end;
$_$;


ALTER FUNCTION "public"."record_sign_in_failure"("email_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_sign_in_failure"("email_hash" "text") IS 'Notes one wrong log-in try for an email hash; answers when a pause ends, if one runs (S1-E2-05).';



CREATE OR REPLACE FUNCTION "public"."record_sign_up_consent"("new_user_id" "uuid", "document_slug" "text", "accepted_version_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_published_at timestamptz;
  version_id uuid;
begin
  -- Step 1: the newest live version of the document (every language shares its go-live time).
  select max(versions.published_at) into current_published_at
  from public.legal_document_versions as versions
  join public.legal_documents as documents on documents.id = versions.document_id
  where documents.slug = document_slug and versions.published_at <= now();

  -- Step 2: the version the form showed must be one language of that newest version.
  select versions.id into version_id
  from public.legal_document_versions as versions
  join public.legal_documents as documents on documents.id = versions.document_id
  where documents.slug = document_slug
    and versions.id::text = accepted_version_id
    and versions.published_at = current_published_at;
  if version_id is null then
    raise exception 'Sign-up needs the current % to be accepted.', document_slug
      using errcode = 'check_violation';
  end if;

  -- Step 3: the record, with the time (consent is the legal basis, Q15; GDPR Art 7(1)).
  insert into public.consents (user_id, legal_document_version_id, method)
  values (new_user_id, version_id, 'sign_up');
end;
$$;


