CREATE OR REPLACE FUNCTION "public"."refuse_space_forum_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  -- A space's forum belongs to its space: staff's forum tools may not move, pin, recolour or
  -- remove it (FORUMS-2c).
  if old.space_id is not null and (
       new.slug is distinct from old.slug or new.parent_id is distinct from old.parent_id
       or new.position is distinct from old.position or new.is_pinned is distinct from old.is_pinned
       or new.accent is distinct from old.accent
       or new.deleted_at is distinct from old.deleted_at or new.space_id is distinct from old.space_id) then
    raise exception 'A space''s forum belongs to its space.' using errcode = 'check_violation', hint = 'forum:space';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."refuse_space_forum_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refuse_space_forum_change"() IS 'Internal: keeps staff''s forum tools off a space''s hidden forum (FORUMS-2c).';



CREATE OR REPLACE FUNCTION "public"."refuse_space_owner_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  -- Step 1: nothing to check while the owner stays the same.
  if new.user_id is not distinct from old.user_id then
    return new;
  end if;
  -- Step 2: the one exception: the hand-over being accepted, to the person it was offered to.
  if current_setting('app.space_handover', true) = old.id::text
     and old.handover_to_user_id is not null and new.user_id = old.handover_to_user_id then
    return new;
  end if;
  raise exception 'The owner of a space changes only through a hand-over the new owner accepts (architecture 1.6; IDEA-20261102-7).'
    using errcode = 'check_violation';
end;
$$;


ALTER FUNCTION "public"."refuse_space_owner_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refuse_space_owner_change"() IS 'Trigger: refuses any change to spaces.user_id except an accepted hand-over (IDEAS-3e).';



CREATE OR REPLACE FUNCTION "public"."refuse_space_writer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  forum_id uuid;
  space public.spaces;
begin
  -- Step 1: which forum the row goes into.
  if tg_table_name = 'forum_threads' then
    forum_id := new.forum_id;
  else
    select forum_threads.forum_id into forum_id from public.forum_threads where forum_threads.id = new.thread_id;
  end if;
  -- Step 2: staff forums are not affected.
  space := public.space_of_forum(forum_id);
  if space.id is null or public.space_may_post(space) then
    return new;
  end if;
  -- Step 3: a locked class takes no posts (criterion 8), whoever writes.
  if public.space_is_locked(space) then
    raise exception 'This class is locked.' using errcode = 'insufficient_privilege', hint = 'space:locked';
  end if;
  -- Step 4: say whether they are waiting for the owner, or whether joining would help.
  if (public.space_membership_of_caller(space.id)).status = 'pending' then
    raise exception 'The owner hasn''t let you in yet.' using errcode = 'insufficient_privilege', hint = 'space:pending';
  end if;
  if public.space_may_join(space) then
    raise exception 'Join this space to post here.' using errcode = 'insufficient_privilege', hint = 'space:join';
  end if;
  raise exception 'This space doesn''t take posts from your account.' using errcode = 'insufficient_privilege', hint = 'space:age';
end;
$$;


ALTER FUNCTION "public"."refuse_space_writer"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refuse_space_writer"() IS 'Trigger: refuses threads and posts in a space from people it doesn''t take (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."refuse_user_id_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  protected_column text := tg_argv[0];
begin
  -- Compare the protected column before and after the update, as JSON so any column name works.
  if to_jsonb(new) -> protected_column is distinct from to_jsonb(old) -> protected_column then
    raise exception 'The % column of % can never change: user IDs are permanent (architecture 1.6).',
      protected_column, tg_table_name
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


