COMMENT ON FUNCTION "public"."refuse_user_id_change"() IS 'Trigger: refuses any change to a user ID or owner column; argument = column name (S1-E1-02).';



CREATE OR REPLACE FUNCTION "public"."register_atlas_picture"("target_path" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_id uuid;
begin
  -- Step 1: a member who may write, while uploads are on.
  if caller_id is null or not public.is_active_member() then
    raise exception 'Your account can''t add pictures right now.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_feature_enabled('picture_uploads') then
    raise exception 'Picture uploads are switched off.' using errcode = 'feature_not_supported';
  end if;
  -- Step 2: the file is there, the caller uploaded it, and it sits under one of their stories.
  if not public.atlas_picture_upload_allowed(target_path)
     or not exists (select 1 from storage.objects where objects.bucket_id = 'atlas-images'
                    and objects.name = target_path and objects.owner_id = caller_id::text) then
    raise exception 'That picture isn''t uploaded to one of your stories.' using errcode = 'check_violation';
  end if;
  -- Step 3: the upload limit (S1-E10-12), then the pending row.
  perform public.take_rate_limit('picture_upload');
  insert into public.picture_checks (user_id, bucket, path, kind, story_id)
  values (caller_id, 'atlas-images', target_path, 'atlas_image', split_part(target_path, '/', 1)::uuid)
  on conflict (bucket, path) do nothing
  returning id into new_id;
  if new_id is null then
    raise exception 'That picture is already registered.' using errcode = 'check_violation';
  end if;
  return new_id;
end;
$$;


ALTER FUNCTION "public"."register_atlas_picture"("target_path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."register_atlas_picture"("target_path" "text") IS 'Records a just-uploaded Story Atlas picture as pending its check (S1-E17-11).';



CREATE OR REPLACE FUNCTION "public"."register_brand_picture"("target_path" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  new_id uuid;
begin
  -- Step 1: owner or admin, while uploads are on.
  perform public.require_website_staff();
  if not public.is_feature_enabled('picture_uploads') then
    raise exception 'Picture uploads are switched off.' using errcode = 'feature_not_supported';
  end if;
  -- Step 2: the file is there, the caller uploaded it, under a slot's folder.
  if not public.brand_picture_upload_allowed(target_path)
     or not exists (select 1 from storage.objects where objects.bucket_id = 'brand-assets'
                    and objects.name = target_path and objects.owner_id = caller_id::text) then
    raise exception 'That picture isn''t uploaded as a logo or emblem.' using errcode = 'check_violation';
  end if;
  -- Step 3: the upload limit (S1-E10-12), then the pending row.
  perform public.take_rate_limit('picture_upload');
  insert into public.picture_checks (user_id, bucket, path, kind)
  values (caller_id, 'brand-assets', target_path, 'brand_asset')
  on conflict (bucket, path) do nothing
  returning id into new_id;
  if new_id is null then
    raise exception 'That picture is already registered.' using errcode = 'check_violation';
  end if;
  return new_id;
end;
$$;


