COMMENT ON FUNCTION "public"."relationship_json"("link" "public"."story_character_relationships", "with_note" boolean) IS 'Internal: one relationship as JSON, with the writer''s note only when asked (G10b).';



CREATE OR REPLACE FUNCTION "public"."removal_order_log_rows"() RETURNS SETOF "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'reference', notices.reference,
    'source', 'removal_order',
    'kind', 'authority_order',
    'authority', notices.authority_name,
    'received_at', notices.received_at,
    'content', concat_ws(' · ', notices.order_reference, notices.content_url),
    'action_taken', null,
    'decision', cases.decision,
    'completed_at', coalesce(cases.disabled_at, cases.decided_at))
  from public.public_notices as notices
  left join public.cases on cases.id = notices.case_id
  where notices.kind = 'removal_order';
$$;


ALTER FUNCTION "public"."removal_order_log_rows"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."removal_order_log_rows"() IS 'Internal: removal orders from the public form as compliance log rows (S1-E11-04).';



CREATE OR REPLACE FUNCTION "public"."remove_character_picture"("character_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_character public.story_characters;
  removed jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your characters.' using errcode = 'insufficient_privilege';
  end if;
  target_character := public.my_story_character(character_id);
  if target_character.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  removed := public.forget_character_picture(target_character.picture_id);
  update public.story_characters set picture_id = null, picture_alt = '' where story_characters.id = target_character.id;
  return jsonb_build_object('outcome', 'ok', 'removed', removed);
end;
$$;


