CREATE OR REPLACE FUNCTION "public"."remove_my_quote_card_picture"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  old_file jsonb;
begin
  if caller_id is null then
    raise exception 'Sign in to change your picture.' using errcode = 'insufficient_privilege';
  end if;
  -- The newest live picture's file is handed back; every live one is retired.
  select jsonb_build_object('bucket', picture_checks.bucket, 'path', picture_checks.path) into old_file
  from public.picture_checks
  where picture_checks.user_id = caller_id and picture_checks.kind = 'quote_card'
    and picture_checks.deleted_at is null
  order by picture_checks.created_at desc
  limit 1;
  update public.picture_checks set deleted_at = now()
  where picture_checks.user_id = caller_id and picture_checks.kind = 'quote_card'
    and picture_checks.deleted_at is null;
  return jsonb_build_object('old_file', old_file);
end;
$$;


ALTER FUNCTION "public"."remove_my_quote_card_picture"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_my_quote_card_picture"() IS 'Retires the caller''s quote card background and hands back its file to delete (GAPS-7).';



CREATE OR REPLACE FUNCTION "public"."remove_space_member"("slug" "text", "handle" "text", "reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(remove_space_member.slug, 'members');
  member public.space_members := public.space_member_by_handle(space.id, remove_space_member.handle);
begin
  if member.id is null or member.status <> 'active' then
    raise exception 'That person isn''t a member of this space.' using errcode = 'no_data_found', hint = 'member:missing';
  end if;
  if member.role = 'owner' then
    raise exception 'The owner can''t be removed.' using errcode = 'check_violation', hint = 'member:owner';
  end if;
  if member.role = 'moderator' and space.user_id is distinct from (select auth.uid())
     and not public.staff_may('moderation', 'act') then
    raise exception 'Only the owner can remove a moderator.' using errcode = 'insufficient_privilege', hint = 'space:not_allowed';
  end if;
  if char_length(btrim(coalesce(reason, ''))) > 500 then
    raise exception 'Keep the reason under 500 characters.' using errcode = 'check_violation', hint = 'reason:too_long';
  end if;
  delete from public.space_members where space_members.id = member.id;
  perform public.log_space_action(space, 'member_removed', member.user_id, null, reason);
end;
$$;


ALTER FUNCTION "public"."remove_space_member"("slug" "text", "handle" "text", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_space_member"("slug" "text", "handle" "text", "reason" "text") IS 'Takes a member out of a space, for the owner and moderators with the members power; logged (S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."remove_unchanged_customisations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request public.customisation_change_requests;
  removed integer := 0;
begin
  for request in
    select * from public.customisation_change_requests
    where customisation_change_requests.resolved_at is null and customisation_change_requests.due_at <= now()
    order by customisation_change_requests.due_at
    for update skip locked
  loop
    -- Step 1: the request is closed first, so the change below doesn't count as the person's.
    update public.customisation_change_requests set resolved_at = now(), outcome = 'removed', updated_at = now()
    where customisation_change_requests.id = request.id;
    -- Step 2: the signature (words and picture) or the banner picture comes off; the picture's
    -- file stays until the storage sweep, as for every removed picture.
    if request.item = 'signature' then
      update public.picture_checks set deleted_at = coalesce(deleted_at, now())
      where picture_checks.id = (select profiles.signature_picture_id from public.profiles where profiles.id = request.user_id);
      update public.profiles set signature = null, signature_picture_id = null, updated_at = now()
      where profiles.id = request.user_id;
    else
      update public.picture_checks set deleted_at = coalesce(deleted_at, now())
      where picture_checks.id = (select spaces.banner_picture_id from public.spaces where spaces.id = request.space_id);
      update public.spaces set banner_picture_id = null, updated_at = now() where spaces.id = request.space_id;
    end if;
    -- Step 3: the statement of reasons, which also tells the person (DSA art. 17).
    perform public.issue_statement_of_reasons(request.user_id, 'remove', 'terms', 'community_rules',
      request.reason,
      case when request.item = 'signature'
           then jsonb_build_object('item_type', 'profile', 'item_id', request.user_id)
           else jsonb_build_object('item_type', 'space', 'item_id', request.space_id) end);
    removed := removed + 1;
  end loop;
  return removed;
end;
$$;


ALTER FUNCTION "public"."remove_unchanged_customisations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_unchanged_customisations"() IS 'Job: removes a signature or banner still unchanged 24 hours after a moderator asked, with a statement of reasons (S1-E8-08, Q29).';



