CREATE OR REPLACE FUNCTION "public"."rename_chapter"("chapter_code" "text", "title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter public.chapters := public.my_live_chapter(chapter_code);
  refusal text := public.chapter_gate_outcome(chapter);
  clean_title text := public.normalise_romanian_letters(regexp_replace(btrim(coalesce(title, '')), '\s+', ' ', 'g'));
begin
  if refusal is not null then
    return jsonb_build_object('outcome', refusal);
  end if;
  if char_length(clean_title) > 120 then
    raise exception 'A chapter title can have at most 120 characters (S1-E3-02a).' using errcode = 'check_violation';
  end if;
  update public.chapters set
    draft_title = clean_title,
    draft_version = chapter.draft_version + 1,
    published_title = case when chapter.status = 'published' then clean_title else chapter.published_title end
  where chapters.id = chapter.id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."rename_chapter"("chapter_code" "text", "title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rename_chapter"("chapter_code" "text", "title" "text") IS 'Renames the caller''s own chapter; readers see a published chapter''s new title at once (S1-E3-04).';



CREATE OR REPLACE FUNCTION "public"."rename_character_detail_group"("story_slug" "text", "group_name" "text", "new_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  wanted_name text := btrim(coalesce(new_name, ''));
begin
  -- Step 1: a signed-in writer and their own live story.
  if (select auth.uid()) is null then
    raise exception 'Sign in to rename a group.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the same name is nothing to do; another group's name would merge two groups unasked.
  if wanted_name = group_name then
    return jsonb_build_object('outcome', 'ok');
  end if;
  if exists (select 1 from public.story_character_fields as fields
             where fields.story_id = target_story_id
               and lower(fields.own_group) = lower(wanted_name)
               and fields.own_group <> group_name) then
    raise exception 'This story already has a group with that name.'
      using errcode = 'check_violation', hint = 'name_taken';
  end if;
  -- Step 3: every detail in the group takes the new name.
  update public.story_character_fields
  set own_group = wanted_name
  where story_id = target_story_id and own_group = group_name;
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."rename_character_detail_group"("story_slug" "text", "group_name" "text", "new_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rename_character_detail_group"("story_slug" "text", "group_name" "text", "new_name" "text") IS 'Renames one of the caller''s own groups of character details, on every detail in it (GAPS-1).';



CREATE OR REPLACE FUNCTION "public"."rename_plan_act"("story_slug" "text", "act_id" "text", "act_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  target_act_id uuid;
begin
  -- Step 1: a signed-in writer, their own live story and one of its acts.
  if (select auth.uid()) is null then
    raise exception 'Sign in to rename an act.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  -- (Looked up here, not with act_of_story(), which raises for an act of another story; here
  -- such an act is simply not found.)
  select acts.id into target_act_id from public.story_plan_acts as acts
  where acts.story_id = target_story_id and acts.id::text = act_id;
  if target_story_id is null or target_act_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: never another act's name, capitals aside.
  if exists (select 1 from public.story_plan_acts as acts
             where acts.story_id = target_story_id and acts.id <> target_act_id
               and lower(acts.name) = lower(btrim(coalesce(act_name, '')))) then
    raise exception 'This story already has an act with that name.'
      using errcode = 'check_violation', hint = 'name_taken';
  end if;
  -- Step 3: the new name.
  update public.story_plan_acts set name = btrim(act_name) where id = target_act_id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."rename_plan_act"("story_slug" "text", "act_id" "text", "act_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rename_plan_act"("story_slug" "text", "act_id" "text", "act_name" "text") IS 'Renames one of the acts of the caller''s own story plan (GAPS-2a; S1-E17-01).';



CREATE OR REPLACE FUNCTION "public"."renumber_story_chapters"("target_story_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.chapters set position = ordered.new_position
  from (
    select chapters.id, row_number() over (order by chapters.position, chapters.created_at) as new_position
    from public.chapters
    where chapters.story_id = target_story_id and chapters.deleted_at is null
  ) as ordered
  where chapters.id = ordered.id and chapters.position <> ordered.new_position;
$$;


