CREATE OR REPLACE FUNCTION "public"."reply_moderator_mail"("thread_reference" "text", "body" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  clean_body text := public.clean_mail_text(body, 4000);
  thread public.moderator_mail_threads;
begin
  if caller_id is null then
    raise exception 'Log in to write to the moderators.' using errcode = 'insufficient_privilege';
  end if;
  select * into thread from public.moderator_mail_threads
  where reference = upper(btrim(thread_reference)) and user_id = caller_id for update;
  if thread.id is null then
    raise exception 'There is no such conversation.' using errcode = 'no_data_found';
  end if;
  perform public.take_rate_limit('moderator_mail');
  insert into public.moderator_mail_messages (thread_id, user_id, body) values (thread.id, caller_id, clean_body);
  update public.moderator_mail_threads set status = 'open', last_message_at = now() where id = thread.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."reply_moderator_mail"("thread_reference" "text", "body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reply_moderator_mail"("thread_reference" "text", "body" "text") IS 'The member answers in their own moderator mail thread; it opens again for the team (S1-E10-11).';



CREATE OR REPLACE FUNCTION "public"."reply_my_support_ticket"("ticket_number" bigint, "body" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  clean_body text := public.clean_mail_text(body, 4000);
  ticket public.support_tickets;
begin
  -- Step 1: signed in, and the ticket is theirs.
  if caller_id is null then
    raise exception 'Log in to answer.' using errcode = 'insufficient_privilege';
  end if;
  select * into ticket from public.support_tickets
  where support_tickets.number = ticket_number and requester_user_id = caller_id for update;
  if ticket.id is null then
    raise exception 'There is no such request.' using errcode = 'no_data_found';
  end if;
  if ticket.status = 'closed' then
    raise exception 'This request is closed. Start a new one and mention #%.', ticket.number using errcode = 'check_violation';
  end if;
  -- Step 2: the message, then the ticket opens again when it was waiting or solved.
  perform public.take_rate_limit('support_ticket');
  insert into public.support_ticket_messages (ticket_id, kind, author_user_id, body, channel)
  values (ticket.id, 'from_requester', caller_id, clean_body, 'in_app');
  update public.support_tickets set last_message_at = now() where id = ticket.id;
  if ticket.status in ('solved', 'pending_on_user') then
    update public.support_tickets set status = 'open', solved_at = null where id = ticket.id;
    perform public.record_support_event(ticket.id, 'status', to_jsonb(ticket.status), to_jsonb('open'::text));
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."reply_my_support_ticket"("ticket_number" bigint, "body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reply_my_support_ticket"("ticket_number" bigint, "body" "text") IS 'The member answers in their own support ticket; a solved or waiting one opens again (S1-E11-13 criterion 7).';



CREATE OR REPLACE FUNCTION "public"."reply_to_forum_thread"("thread_number" bigint, "body" "text", "quoted_posts" "uuid"[] DEFAULT '{}'::"uuid"[], "bump" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_forum_writer();
  clean_body text := public.check_forum_post_text(body);
  thread public.forum_threads;
  quotes uuid[];
  new_number integer;
begin
  -- Step 1: the thread, locked, if the caller may open it.
  select * into thread from public.forum_threads
  where forum_threads.thread_number = reply_to_forum_thread.thread_number
  for update;
  if thread.id is null or not public.forum_thread_is_shown(thread) then
    raise exception 'That thread isn''t there any more.' using errcode = 'no_data_found', hint = 'thread:missing';
  end if;
  -- Step 2: a locked thread takes no replies (criterion 2).
  if thread.locked_at is not null then
    raise exception 'This thread is locked.' using errcode = 'check_violation', hint = 'thread:locked';
  end if;
  -- Step 3: the quotes, checked and in thread order.
  quotes := public.forum_quotes_for_reply(thread.id, quoted_posts);
  -- Step 4: the next number and the post. Only a bumping reply moves the thread up its forum;
  -- last_post_at always moves, because it says when the newest post was written.
  new_number := thread.last_post_number + 1;
  insert into public.forum_posts (user_id, thread_id, post_number, body, quoted_post_ids)
  values (caller_id, thread.id, new_number, clean_body, quotes);
  update public.forum_threads
  set last_post_number = new_number,
      last_post_at = now(),
      bumped_at = case when coalesce(bump, true) then now() else forum_threads.bumped_at end
  where forum_threads.id = thread.id;
  return jsonb_build_object('post_number', new_number);
end;
$$;


ALTER FUNCTION "public"."reply_to_forum_thread"("thread_number" bigint, "body" "text", "quoted_posts" "uuid"[], "bump" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reply_to_forum_thread"("thread_number" bigint, "body" "text", "quoted_posts" "uuid"[], "bump" boolean) IS 'Adds a numbered post at the end of an open thread, with any quotes, bumping it unless asked not to (S1-E8-02, S1-E8-03, S1-E8-05).';



CREATE OR REPLACE FUNCTION "public"."report_client_error"("error_name" "text", "error_message" "text", "route_path" "text", "app_version" "text", "browser_family" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  reports_allowed integer := coalesce((public.setting_value('client_errors_per_minute'))::integer, 60);
  reports_last_minute integer;
  new_id uuid;
begin
  -- Step 1: over the shared limit, drop the report quietly (the browser shows no code).
  select count(*) into reports_last_minute
  from public.client_errors as errors
  where errors.created_at > now() - interval '1 minute';
  if reports_last_minute >= reports_allowed then
    return null;
  end if;

  -- Step 2: store the cleaned report.
  insert into public.client_errors (error_name, error_message, route_path, app_version, browser_family)
  values (
    coalesce(nullif(public.scrub_error_text(error_name, 100), ''), 'Error'),
    public.scrub_error_text(error_message, 500),
    public.scrub_route_path(route_path),
    case when app_version ~ '^[A-Za-z0-9._+-]{1,40}$' then app_version else 'unknown' end,
    case
      when browser_family in ('chrome', 'edge', 'firefox', 'safari', 'opera', 'samsung_internet')
        then browser_family
      else 'other'
    end
  )
  returning id into new_id;
  return new_id;
end;
$_$;


ALTER FUNCTION "public"."report_client_error"("error_name" "text", "error_message" "text", "route_path" "text", "app_version" "text", "browser_family" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."report_client_error"("error_name" "text", "error_message" "text", "route_path" "text", "app_version" "text", "browser_family" "text") IS 'Stores one scrubbed browser error report, unless the shared per-minute limit is reached (S1-E1-05).';



CREATE OR REPLACE FUNCTION "public"."report_item"("item_type" "public"."reportable_type", "item_reference" "text", "reason" "public"."report_reason", "details" "text" DEFAULT NULL::"text", "copy_details" "jsonb" DEFAULT NULL::"jsonb") RETURNS TABLE("report_reference" "text", "received_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reporter_id uuid := (select auth.uid());
  pause public.sanctions;
  item record;
  existing public.reports;
  new_report public.reports;
  hourly_limit integer := coalesce(public.setting_value('report_hourly_limit'), '20')::text::integer;
  sent_in_hour integer;
  oldest_in_hour timestamptz;
  -- The source fields count only for a copied-work report.
  copy jsonb := case when reason = 'copied_published_work' then coalesce(copy_details, '{}'::jsonb) else '{}'::jsonb end;
begin
  -- Step 1: signed in, whatever the account's state.
  if reporter_id is null then
    raise exception 'Log in to report something.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 1b: a paused reporter waits (S1-E10-06, Q83).
  pause := public.active_sanction(reporter_id, 'reporting_pause');
  if pause.id is not null then
    raise exception 'Your reporting is paused until %.', pause.ends_at using errcode = 'object_not_in_prerequisite_state';
  end if;
  -- Step 2: the item, and whose it is; never one's own.
  select * into item from public.reportable_item_owner(item_type, item_reference);
  if item.owner_user_id = reporter_id then
    raise exception 'You can''t report your own %.', item_type using errcode = 'check_violation';
  end if;
  -- Step 3: the same report twice within a day gives the same reference.
  select * into existing from public.reports
    where reports.user_id = reporter_id and reports.item_type = report_item.item_type
      and reports.item_id = item.item_id and reports.created_at > now() - interval '24 hours'
    order by reports.created_at desc limit 1;
  if existing.id is not null then
    return query select existing.reference, existing.created_at;
    return;
  end if;
  -- Step 4: the hourly limit, with how long to wait (S1-E10-12).
  select count(*)::integer, min(reports.created_at) into sent_in_hour, oldest_in_hour
  from public.reports
  where reports.user_id = reporter_id and reports.created_at > now() - interval '1 hour';
  if sent_in_hour >= hourly_limit then
    raise exception 'Too many reports in an hour. Wait % minutes.', public.wait_minutes_until_free(oldest_in_hour)
      using errcode = 'program_limit_exceeded', hint = 'wait_minutes:' || public.wait_minutes_until_free(oldest_in_hour);
  end if;
  -- Step 5: the row, with the reporter's age group, a reference and the source (S1-E10-08).
  insert into public.reports (user_id, item_type, item_id, reported_user_id, reason, details,
                              reporter_age_band, reference, copy_source_title, copy_source_author,
                              copy_source_reference, copy_source_passage, reported_passage)
  values (reporter_id, item_type, item.item_id, item.owner_user_id, reason, nullif(btrim(details), ''),
          public.age_band(), 'R-' || lpad(nextval('public.report_reference_seq')::text, 6, '0'),
          nullif(btrim(copy ->> 'sourceTitle'), ''), nullif(btrim(copy ->> 'sourceAuthor'), ''),
          nullif(btrim(copy ->> 'sourceReference'), ''), nullif(btrim(copy ->> 'sourcePassage'), ''),
          nullif(btrim(copy ->> 'reportedPassage'), ''))
  returning * into new_report;
  -- Step 6: the case: opened, or joined when the item already has one (S1-E10-03a).
  update public.reports set case_id = public.attach_report_to_case(new_report)
    where reports.id = new_report.id;
  return query select new_report.reference, new_report.created_at;
end;
$$;


ALTER FUNCTION "public"."report_item"("item_type" "public"."reportable_type", "item_reference" "text", "reason" "public"."report_reason", "details" "text", "copy_details" "jsonb") OWNER TO "postgres";


