CREATE OR REPLACE FUNCTION "public"."report_outcome_of"("decision" "public"."moderation_action") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when decision is null then null
    when decision in ('hide', 'remove') then 'removed'
    when decision = 'no_action' then 'no_action'
    else 'acted'
  end;
$$;


ALTER FUNCTION "public"."report_outcome_of"("decision" "public"."moderation_action") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."report_outcome_of"("decision" "public"."moderation_action") IS 'Internal: what a reporter or notifier is told: removed, acted or no_action, never a sanction (S1-E10-04).';



CREATE OR REPLACE FUNCTION "public"."reportable_item_owner"("item_type" "public"."reportable_type", "item_reference" "text") RETURNS TABLE("item_id" "uuid", "owner_user_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  is_row_id boolean := item_reference ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
begin
  case item_type
    when 'profile' then
      return query
        select profiles.id, profiles.id from public.profiles
        where profiles.handle_skeleton = public.username_skeleton(btrim(item_reference, ' @'))
          and profiles.deleted_at is null;
    -- A story or a chapter by its row ID, and only once readers can see it: published and not
    -- deleted, so a draft's existence never leaks.
    when 'story' then
      return query
        select stories.id, stories.user_id from public.stories
        where is_row_id and stories.id = item_reference::uuid
          and stories.first_published_at is not null
          and stories.deleted_at is null;
    when 'chapter' then
      return query
        select chapters.id, chapters.user_id from public.chapters
        join public.stories on stories.id = chapters.story_id
        where is_row_id and chapters.id = item_reference::uuid
          and chapters.status = 'published'
          and chapters.deleted_at is null
          and stories.deleted_at is null;
    when 'comment' then
      return query
        select comments.id, comments.user_id from public.comments
        join public.chapters on chapters.id = comments.chapter_id
        join public.stories on stories.id = chapters.story_id
        where is_row_id and comments.id = item_reference::uuid
          and comments.deleted_at is null
          and chapters.deleted_at is null
          and stories.deleted_at is null;
    when 'picture' then
      return query
        select picture_checks.id, picture_checks.user_id from public.picture_checks
        where is_row_id and picture_checks.id = item_reference::uuid
          and picture_checks.status in ('passed', 'approved')
          and picture_checks.deleted_at is null;
    when 'embed' then
      return query
        select chapter_embeds.id, chapter_embeds.user_id from public.chapter_embeds
        join public.chapters on chapters.id = chapter_embeds.chapter_id
        join public.stories on stories.id = chapters.story_id
        where is_row_id and chapter_embeds.id = item_reference::uuid
          and chapter_embeds.deleted_at is null
          and chapters.status = 'published'
          and chapters.deleted_at is null
          and stories.deleted_at is null;
    -- A Story Atlas item only while readers can see it, so a private one never leaks (S1-E17-34).
    when 'atlas_item' then
      return query
        select item_reference::uuid, item.owner_user_id
        from public.plan_item_row(case when is_row_id then item_reference::uuid end) as item
        where public.plan_item_is_public(item_reference::uuid);
    -- A private message only for the two people in its chat, so its existence never leaks to
    -- anyone else (S1-E9-01). Deleted ones can't be reported.
    when 'message' then
      return query
        select messages.id, messages.user_id from public.messages
        join public.conversations on conversations.id = messages.conversation_id
        where is_row_id and messages.id = item_reference::uuid
          and messages.deleted_at is null
          and (select auth.uid()) in (conversations.user_id, conversations.recipient_user_id);
    -- A forum thread or post only while readers can see it: not deleted, in a live thread and
    -- forum, so a deleted one's existence never leaks (S1-E8-02).
    when 'forum_thread' then
      return query
        select forum_threads.id, forum_threads.user_id from public.forum_threads
        join public.forums on forums.id = forum_threads.forum_id
        where is_row_id and forum_threads.id = item_reference::uuid
          and forum_threads.deleted_at is null and forums.deleted_at is null;
    when 'forum_post' then
      return query
        select forum_posts.id, forum_posts.user_id from public.forum_posts
        join public.forum_threads on forum_threads.id = forum_posts.thread_id
        join public.forums on forums.id = forum_threads.forum_id
        where is_row_id and forum_posts.id = item_reference::uuid
          and forum_posts.deleted_at is null and forum_threads.deleted_at is null
          and forums.deleted_at is null;
    -- A space only while the reporter may see that it exists, so a hidden under-16 space never
    -- leaks to an adult through the report form (S1-E8-06).
    when 'space' then
      return query
        select spaces.id, spaces.user_id from public.spaces
        where is_row_id and spaces.id = item_reference::uuid and public.space_card_visible(spaces);
    -- A note with a request to join only for the people who decide that space's requests, so a
    -- note never reaches anyone else through the report form (IDEA-20261102-9).
    when 'space_join_note' then
      return query
        select space_join_notes.id, space_join_notes.user_id from public.space_join_notes
        join public.spaces on spaces.id = space_join_notes.space_id
        where is_row_id and space_join_notes.id = item_reference::uuid
          and space_join_notes.deleted_at is null and spaces.deleted_at is null
          and public.space_may_act(spaces, 'members');
    -- A reading list only while the reporter may see it: someone else's public list, so a private
    -- list's existence never leaks through the report form (GAPS-6).
    when 'reading_list' then
      return query
        select reading_lists.id, reading_lists.user_id from public.reading_lists
        where is_row_id and reading_lists.id = item_reference::uuid
          and reading_lists.is_public and public.reading_list_is_visible(reading_lists);
  end case;
  if not found then
    raise exception 'There is no such % to report.', item_type using errcode = 'check_violation';
  end if;
end;
$_$;


ALTER FUNCTION "public"."reportable_item_owner"("item_type" "public"."reportable_type", "item_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reportable_item_owner"("item_type" "public"."reportable_type", "item_reference" "text") IS 'The reported item''s ID and owner, one branch per reportable_type (shared contract, S1-E10-01; comment S1-E6-01; picture S1-E10-05; embed S1-E3-10; atlas_item S1-E17-34; message S1-E9-01; forum_thread and forum_post S1-E8-02; space S1-E8-06; space_join_note IDEA-20261102-9, GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."reportable_item_summary"("item_type" "public"."reportable_type", "item_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  summary text;
begin
  case item_type
    when 'profile' then
      select '@' || coalesce(profiles.handle, '…') into summary
      from public.profiles where profiles.id = item_id;
    when 'story' then
      select stories.title into summary from public.stories where stories.id = item_id;
    when 'chapter' then
      select format('Chapter %s of %s', chapters.position, stories.title) into summary
      from public.chapters join public.stories on stories.id = chapters.story_id
      where chapters.id = item_id;
    when 'comment' then
      select format('Comment on chapter %s of %s: %s', chapters.position, stories.title,
          case when char_length(comments.body) > 80 then left(comments.body, 80) || '…' else comments.body end)
        into summary
      from public.comments
      join public.chapters on chapters.id = comments.chapter_id
      join public.stories on stories.id = chapters.story_id
      where comments.id = item_id;
    when 'picture' then
      select case picture_checks.kind
          when 'cover' then format('Cover picture of %s', coalesce(stories.title, 'a story'))
          when 'avatar' then format('Profile picture of @%s', coalesce(profiles.handle, '…'))
          when 'chapter_picture' then format('Picture in chapter %s of %s',
            coalesce(chapters.position::text, '?'), coalesce(stories.title, 'a story'))
          else format('Picture (%s)', picture_checks.kind) end
        into summary
      from public.picture_checks
      left join public.stories on stories.id = picture_checks.story_id
      left join public.chapters on chapters.id = picture_checks.chapter_id
      left join public.profiles on profiles.id = picture_checks.user_id
      where picture_checks.id = item_id;
    when 'embed' then
      select format('%s from %s in chapter %s of %s',
          case when chapter_embeds.service in ('spotify', 'apple_music') then 'Music' else 'Video' end,
          case chapter_embeds.service when 'youtube' then 'YouTube' when 'vimeo' then 'Vimeo'
            when 'loom' then 'Loom' when 'spotify' then 'Spotify' else 'Apple Music' end,
          chapters.position, stories.title)
        into summary
      from public.chapter_embeds
      join public.chapters on chapters.id = chapter_embeds.chapter_id
      join public.stories on stories.id = chapters.story_id
      where chapter_embeds.id = item_id;
    when 'atlas_item' then
      select format('%s "%s" in the world of %s',
          case item.item_kind when 'character' then 'Character' when 'relationship' then 'Relationship between'
            when 'section' then 'World section' when 'entry' then 'World entry' else 'Timeline event' end,
          item.title, stories.title)
        into summary
      from public.plan_item_row(item_id) as item
      join public.stories on stories.id = item.story_id;
    when 'message' then
      select format('Private message from @%s: %s', coalesce(profiles.handle, '…'),
          case when char_length(messages.body) > 80 then left(messages.body, 80) || '…' else messages.body end)
        into summary
      from public.messages
      left join public.profiles on profiles.id = messages.user_id
      where messages.id = item_id;
    when 'forum_thread' then
      select format('Forum thread "%s"', forum_threads.title) into summary
      from public.forum_threads where forum_threads.id = item_id;
    when 'forum_post' then
      select format('Post #%s in "%s": %s', forum_posts.post_number, forum_threads.title,
          case when char_length(forum_posts.body) > 80 then left(forum_posts.body, 80) || '…' else forum_posts.body end)
        into summary
      from public.forum_posts join public.forum_threads on forum_threads.id = forum_posts.thread_id
      where forum_posts.id = item_id;
    when 'space' then
      select format('Space "%s"', spaces.name) into summary from public.spaces where spaces.id = item_id;
    when 'space_join_note' then
      select format('Note asking to join "%s": %s', spaces.name,
          case when char_length(space_join_notes.note) > 80 then left(space_join_notes.note, 80) || '…' else space_join_notes.note end)
        into summary
      from public.space_join_notes join public.spaces on spaces.id = space_join_notes.space_id
      where space_join_notes.id = item_id;
    when 'reading_list' then
      select format('Reading list "%s"', reading_lists.name) into summary
      from public.reading_lists where reading_lists.id = item_id;
  end case;
  return coalesce(summary, '(gone)');
end;
$$;


ALTER FUNCTION "public"."reportable_item_summary"("item_type" "public"."reportable_type", "item_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reportable_item_summary"("item_type" "public"."reportable_type", "item_id" "uuid") IS 'A few words saying what was reported, one branch per reportable_type (shared contract, S1-E10-01; comment S1-E6-01; picture S1-E10-05, GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."request_account_deletion"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_live_profile();
  deletion_days integer := coalesce((public.setting_value('account_deletion_days'))::integer, 14);
  closes_on timestamptz := now() + make_interval(days => deletion_days);
begin
  -- Step 1: the board's "Log in again to confirm".
  if not public.account_signed_in_recently() then
    raise exception 'Log in again to confirm.' using errcode = 'check_violation', hint = 'sign_in_again';
  end if;
  -- Step 2: a staff account keeps its staff powers off a closing account (architecture 1.8.1).
  if exists (select 1 from public.staff_roles where staff_roles.user_id = caller_id) then
    raise exception 'A staff account can''t be deleted here.' using errcode = 'check_violation', hint = 'staff_account';
  end if;
  -- Step 3: the account closes: hidden everywhere, and online status forgotten.
  update public.profiles set deleted_at = now(), last_active_at = null where profiles.id = caller_id;
  -- Step 4: the live stories and comments go out of sight with the same time, so a cancel
  -- brings back exactly these (chapters follow their story).
  update public.stories set deleted_at = now()
  where stories.user_id = caller_id and stories.deleted_at is null;
  update public.comments set deleted_at = now(), deleted_by = 'author'
  where comments.user_id = caller_id and comments.deleted_at is null;
  -- Step 5: the forums (S1-E8-02): the person's posts become "Post deleted" markers, and a
  -- thread nobody else has a live post in goes with them; a cancel brings back exactly these.
  update public.forum_posts set deleted_at = now()
  where forum_posts.user_id = caller_id and forum_posts.deleted_at is null;
  update public.forum_threads set deleted_at = now()
  where forum_threads.user_id = caller_id and forum_threads.deleted_at is null
    and not exists (select 1 from public.forum_posts
                    where forum_posts.thread_id = forum_threads.id and forum_posts.user_id <> caller_id
                      and forum_posts.deleted_at is null);
  -- Step 6: the request, for the closing page and the nightly job.
  insert into public.account_deletions (user_id, delete_after) values (caller_id, closes_on);
  return jsonb_build_object('delete_after', closes_on);
end;
$$;


ALTER FUNCTION "public"."request_account_deletion"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_account_deletion"() IS 'Closes the caller''s account now and deletes it for good after account_deletion_days; needs a fresh log-in (S1-E13-03).';



CREATE OR REPLACE FUNCTION "public"."request_data_export"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_live_profile();
  new_export public.exports;
begin
  -- Step 1: at most three an hour.
  perform public.take_rate_limit('data_export');
  -- Step 2: an unfinished one goes; it never had a file anyone could read.
  delete from public.exports
  where exports.user_id = caller_id and exports.kind = 'all_my_data' and exports.state = 'building';
  -- Step 3: the new one, under a random file name.
  insert into public.exports (user_id, kind, file_name)
  values (caller_id, 'all_my_data', gen_random_uuid()::text || '.zip')
  returning * into new_export;
  return jsonb_build_object('export_id', new_export.id, 'file_name', new_export.file_name);
end;
$$;


ALTER FUNCTION "public"."request_data_export"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_data_export"() IS 'Opens a new Download my data export for the signed-in person (S1-E13-02).';



CREATE OR REPLACE FUNCTION "public"."request_manual_age_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person public.profiles;
begin
  -- Step 1: signed in, with a live profile.
  if (select auth.uid()) is null then
    raise exception 'Sign in to ask for a manual check.' using errcode = 'insufficient_privilege';
  end if;
  select * into person from public.profiles
  where profiles.id = (select auth.uid()) and profiles.deleted_at is null
  for update;
  -- Step 2: only after a failed check, and one request at a time.
  if not found or not public.age_check_can_ask_manual(person) then
    raise exception 'A manual check can be asked after a check that didn''t work.'
      using errcode = 'check_violation', hint = 'not_available';
  end if;
  insert into public.manual_age_checks (user_id) values (person.id);
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."request_manual_age_check"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_manual_age_check"() IS 'A person asks for a manual age check after a failed Yoti check (S1-E2-08b).';



CREATE OR REPLACE FUNCTION "public"."request_stories_export"("chosen_story_id" "uuid" DEFAULT NULL::"uuid", "chosen_chapter_ids" "uuid"[] DEFAULT NULL::"uuid"[], "include_chapters" boolean DEFAULT true, "include_plan" boolean DEFAULT true, "include_data" boolean DEFAULT false, "document_format" "text" DEFAULT 'word'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_live_profile();
  problem text;
  wanted public.exports;
  fingerprint text;
  earlier public.exports;
begin
  -- Step 1: the choices make sense (chosen chapters only with one story's chapters ticked) and
  -- the format is one we make.
  if document_format is null or document_format not in ('word', 'pdf', 'both') then
    raise exception 'Choose Word, PDF or both.' using errcode = 'check_violation', hint = 'bad_format';
  end if;
  if chosen_story_id is null or not include_chapters then
    chosen_chapter_ids := null;
  elsif chosen_chapter_ids is not null then
    -- In one order and once each, so the same choice is always the same list.
    chosen_chapter_ids := array(select distinct unnest(chosen_chapter_ids) order by 1);
  end if;
  problem := public.stories_export_choice_problem(caller_id, chosen_story_id, chosen_chapter_ids,
    include_chapters or include_plan or include_data);
  if problem is not null then
    raise exception 'Those files can''t be made.' using errcode = 'check_violation', hint = problem;
  end if;
  -- Step 2: the same files from the last 24 hours, if nothing changed since (criterion 4).
  wanted.story_id := chosen_story_id;
  wanted.chapter_ids := chosen_chapter_ids;
  wanted.include_chapters := include_chapters;
  wanted.include_plan := include_plan;
  wanted.include_data := include_data;
  wanted.document_format := document_format;
  fingerprint := public.stories_fingerprint(caller_id, chosen_story_id);
  earlier := public.reusable_stories_export(caller_id, wanted, fingerprint);
  if earlier.id is not null then
    return jsonb_build_object('outcome', 'reused', 'export_id', earlier.id);
  end if;
  -- Step 3: at most ten new copies an hour; an unfinished one goes.
  perform public.take_rate_limit('stories_export');
  delete from public.exports
  where exports.user_id = caller_id and exports.kind = 'my_stories' and exports.state = 'building';
  -- Step 4: the new one, under a random name of the right kind of file.
  insert into public.exports (user_id, kind, story_id, chapter_ids, include_chapters, include_plan,
    include_data, document_format, content_fingerprint, file_name)
  values (caller_id, 'my_stories', chosen_story_id, chosen_chapter_ids, include_chapters,
    include_plan, include_data, document_format, fingerprint,
    gen_random_uuid()::text || '.' || public.export_file_extension('my_stories', chosen_story_id,
      array[include_chapters, include_plan, include_data], document_format))
  returning * into wanted;
  return jsonb_build_object('outcome', 'new', 'export_id', wanted.id, 'file_name', wanted.file_name);
end;
$$;


ALTER FUNCTION "public"."request_stories_export"("chosen_story_id" "uuid", "chosen_chapter_ids" "uuid"[], "include_chapters" boolean, "include_plan" boolean, "include_data" boolean, "document_format" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_stories_export"("chosen_story_id" "uuid", "chosen_chapter_ids" "uuid"[], "include_chapters" boolean, "include_plan" boolean, "include_data" boolean, "document_format" "text") IS 'Opens a Download my stories copy of the chosen stories, chapters, plan and JSON as Word, PDF or both, or offers the unchanged one from the last 24 hours (S1-E13-05, ADMIN-2d).';



CREATE OR REPLACE FUNCTION "public"."require_account_action_allowed"("target_user_id" "uuid", "reason_given" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.staff_may('user_sanctions', 'act') then
    raise exception 'Only an owner, admin or moderator can act on an account.'
      using errcode = 'insufficient_privilege', hint = 'not_allowed';
  end if;
  if target_user_id = (select auth.uid()) then
    raise exception 'Use Settings for your own account.'
      using errcode = 'insufficient_privilege', hint = 'own_account';
  end if;
  if btrim(coalesce(reason_given, '')) = '' then
    raise exception 'Write a reason. It goes to the audit log.'
      using errcode = 'check_violation', hint = 'reason_missing';
  end if;
  if not exists (select 1 from public.profiles where profiles.id = target_user_id and profiles.deleted_at is null) then
    raise exception 'There is no such account.' using errcode = 'check_violation', hint = 'no_such_account';
  end if;
end;
$$;


ALTER FUNCTION "public"."require_account_action_allowed"("target_user_id" "uuid", "reason_given" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."require_account_action_allowed"("target_user_id" "uuid", "reason_given" "text") IS 'Internal: role, own account, reason and account checks shared by the account actions (S1-E11-02).';



CREATE OR REPLACE FUNCTION "public"."require_case_for_acting"("target_case_id" "uuid") RETURNS "public"."cases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target public.cases;
begin
  select * into target from public.cases where id = target_case_id for update;
  if target.id is null or not public.staff_may('moderation', 'act') or not public.may_see_case(target.is_safeguarding) then
    raise exception 'You can''t work on this case.' using errcode = 'insufficient_privilege';
  end if;
  if target.status <> 'open' then
    raise exception 'This case is already decided.' using errcode = 'check_violation';
  end if;
  return target;
end;
$$;


