CREATE OR REPLACE FUNCTION "public"."restore_chapter"("chapter_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  purge_days integer := coalesce((public.setting_value('content_purge_days'))::integer, 30);
  chapter public.chapters;
begin
  if caller_id is null then
    raise exception 'Sign in to restore a chapter.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  -- Step 1: the caller's own deleted chapter, within the undo time, in a live story.
  select chapters.* into chapter from public.chapters
  join public.stories on stories.id = chapters.story_id
  where chapters.code = chapter_code and chapters.user_id = caller_id
    and chapters.deleted_at is not null
    and chapters.deleted_at > now() - make_interval(days => purge_days)
    and stories.deleted_at is null
  for update of chapters;
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: back, at the end of the story.
  update public.chapters set
    deleted_at = null,
    position = (select coalesce(max(others.position), 0) + 1 from public.chapters as others
                where others.story_id = chapter.story_id and others.deleted_at is null)
  where chapters.id = chapter.id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."restore_chapter"("chapter_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_chapter"("chapter_code" "text") IS 'Undoes the caller''s own chapter deletion within content_purge_days; it comes back at the end (S1-E3-04).';



CREATE OR REPLACE FUNCTION "public"."restore_my_story"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  purge_days integer := coalesce((public.setting_value('content_purge_days'))::integer, 30);
  story public.stories;
begin
  if caller_id is null then
    raise exception 'Sign in to restore a story.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  -- Step 1: the caller's own deleted story at that address, still within the undo time.
  select * into story from public.stories
  where stories.slug = story_slug and stories.user_id = caller_id
    and stories.deleted_at is not null
    and stories.deleted_at > now() - make_interval(days => purge_days);
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the story and the chapters that went with it (same deleted_at) come back.
  update public.chapters set deleted_at = null
  where chapters.story_id = story.id and chapters.deleted_at = story.deleted_at;
  update public.stories set deleted_at = null where stories.id = story.id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."restore_my_story"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_my_story"("story_slug" "text") IS 'Undoes a story''s deletion within content_purge_days (S1-E3-05).';



CREATE OR REPLACE FUNCTION "public"."retention_periods"() RETURNS TABLE("kind" "text", "amount" integer, "unit" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  -- Step 1: the kinds the screen lists, the setting behind each and its unit, in order.
  with listed (position, kind, setting_key, unit) as (
    values
      (1, 'notifications', 'notifications_keep_days', 'days'),
      (2, 'deleted_content', 'content_purge_days', 'days'),
      (3, 'reported_messages', 'reported_messages_keep_days', 'days'),
      (4, 'moderator_mail', 'moderator_mail_keep_days', 'days'),
      (5, 'support_tickets', 'support_ticket_keep_years', 'years'),
      (6, 'reading_minutes', 'reading_minutes_keep_days', 'days'),
      (7, 'scrambled_ip', 'scrambled_ip_keep_days', 'days'),
      (8, 'invites', 'invites_keep_days', 'days'),
      (9, 'account_deletion', 'account_deletion_days', 'days')
  )
  -- Step 2: each one's current value; only whole numbers count.
  select listed.kind, (settings.value #>> '{}')::integer, listed.unit
  from listed
  join public.settings on settings.key = listed.setting_key
  where auth.uid() is not null
    and jsonb_typeof(settings.value) = 'number'
    and (settings.value #>> '{}') ~ '^[0-9]+$'
  order by listed.position;
$_$;


