CREATE OR REPLACE FUNCTION "public"."return_rate_on"("for_day" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with readable as (
    select chapters.id, chapters.story_id, chapters.position,
      (chapters.first_published_at at time zone 'Europe/Bucharest')::date as released_on
    from public.chapters
    where public.chapter_is_readable(chapters.id)
  ),
  pairs as (
    select readable.id as previous_id,
      lead(readable.id) over (partition by readable.story_id order by readable.position) as next_id,
      lead(readable.released_on) over (partition by readable.story_id order by readable.position) as next_released_on
    from readable
  ),
  counted as (
    select
      (select coalesce(sum(reads.total), 0) from public.chapter_reads as reads
        where reads.chapter_id = pairs.next_id
          and reads.read_on between pairs.next_released_on and pairs.next_released_on + 6) as next_reads,
      (select coalesce(sum(reads.total), 0) from public.chapter_reads as reads
        where reads.chapter_id = pairs.previous_id and reads.read_on < pairs.next_released_on) as previous_reads
    from pairs
    where pairs.next_id is not null
      and pairs.next_released_on between for_day - 36 and for_day - 6
  )
  select case when sum(previous_reads) > 0
    then round(100.0 * sum(next_reads) / sum(previous_reads), 1) end
  from counted;
$$;


ALTER FUNCTION "public"."return_rate_on"("for_day" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."return_rate_on"("for_day" "date") IS 'Internal: the approximate return rate from daily read totals (S1-E15-02; architecture 1.7.9).';



CREATE TABLE IF NOT EXISTS "public"."exports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "public"."export_kind" NOT NULL,
    "state" "public"."export_state" DEFAULT 'building'::"public"."export_state" NOT NULL,
    "file_name" "text" NOT NULL,
    "file_size" bigint,
    "story_count" integer,
    "ready_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "story_id" "uuid",
    "chapter_ids" "uuid"[],
    "include_chapters" boolean DEFAULT true NOT NULL,
    "include_plan" boolean DEFAULT true NOT NULL,
    "include_data" boolean DEFAULT false NOT NULL,
    "content_fingerprint" "text",
    "data_request_id" "uuid",
    "display_name" "text",
    "document_format" "text" DEFAULT 'word'::"text" NOT NULL,
    CONSTRAINT "exports_chapters_only_for_one_story" CHECK ((("chapter_ids" IS NULL) OR (("story_id" IS NOT NULL) AND "include_chapters"))),
    CONSTRAINT "exports_data_request_fields" CHECK ((("kind" = 'data_request'::"public"."export_kind") = (("data_request_id" IS NOT NULL) AND ("display_name" IS NOT NULL)))),
    CONSTRAINT "exports_display_name_shape" CHECK ((("display_name" IS NULL) OR ("display_name" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,150}\.(zip|docx|pdf|json|csv)$'::"text"))),
    CONSTRAINT "exports_document_format_known" CHECK (("document_format" = ANY (ARRAY['word'::"text", 'pdf'::"text", 'both'::"text"]))),
    CONSTRAINT "exports_file_name_shape" CHECK ((("file_name" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(zip|docx|pdf|json|csv)$'::"text") AND ((("kind" = 'data_request'::"public"."export_kind") AND ("substring"("file_name", '\.([a-z]+)$'::"text") = "substring"("display_name", '\.([a-z]+)$'::"text"))) OR (("kind" <> 'data_request'::"public"."export_kind") AND ("file_name" ~~ ('%.'::"text" || "public"."export_file_extension"("kind", "story_id", ARRAY["include_chapters", "include_plan", "include_data"], "document_format"))))))),
    CONSTRAINT "exports_ready_together" CHECK ((("state" = 'ready'::"public"."export_state") = (("ready_at" IS NOT NULL) AND ("expires_at" IS NOT NULL) AND ("file_size" IS NOT NULL)))),
    CONSTRAINT "exports_stories_choose_something" CHECK ((("kind" = 'all_my_data'::"public"."export_kind") OR "include_chapters" OR "include_plan" OR "include_data")),
    CONSTRAINT "exports_story_count_positive" CHECK ((("story_count" IS NULL) OR ("story_count" >= 0))),
    CONSTRAINT "exports_story_only_for_stories" CHECK ((("kind" = 'my_stories'::"public"."export_kind") OR ("story_id" IS NULL)))
);


ALTER TABLE "public"."exports" OWNER TO "postgres";


COMMENT ON TABLE "public"."exports" IS 'kind: user_action
A copy of someone''s data: all_my_data is one ZIP they asked for (S1-E13-02; GDPR art. 15 and 20), with every story and plan as Word and PDF files; my_stories is the stories they chose, as Word files, PDF files or both (S1-E13-05, ADMIN-2d); data_request is a file staff built for their data request (S1-E11-09). Each sits in the private exports bucket, readable only by them while ready and for seven days. Purged by S1-E13-04.';



COMMENT ON COLUMN "public"."exports"."user_id" IS 'The person whose data it is; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."exports"."file_name" IS 'The ZIP''s random name in the exports bucket ("<uuid>.zip"), never the user ID (architecture 1.6).';



COMMENT ON COLUMN "public"."exports"."story_id" IS 'For my_stories: the one story the files hold, or null for all of them (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."chapter_ids" IS 'For my_stories of one story: the chapters the writer chose, or null for every chapter (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."include_chapters" IS 'For my_stories: the Word file of the story''s chapters is in (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."include_plan" IS 'For my_stories: the Word file of the story''s plan from Story Atlas is in (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."include_data" IS 'For my_stories: the machine-readable copy (JSON) of the stories is in (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."content_fingerprint" IS 'For my_stories: stories_fingerprint() when it was asked for, so an unchanged copy can be offered again (S1-E13-05).';



COMMENT ON COLUMN "public"."exports"."data_request_id" IS 'For data_request: the staff data request this file answers (S1-E11-09).';



COMMENT ON COLUMN "public"."exports"."display_name" IS 'For data_request: the file''s name as the person and staff see it, for example "rain.docx" (S1-E11-09).';



COMMENT ON COLUMN "public"."exports"."document_format" IS 'For my_stories: the chapters and plan as Word files, PDF files or both (ADMIN-2d; S1-E11-09b). Other kinds keep word and hold both formats inside their ZIP.';



CREATE OR REPLACE FUNCTION "public"."reusable_stories_export"("owner_id" "uuid", "wanted" "public"."exports", "current_fingerprint" "text") RETURNS "public"."exports"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exports.* from public.exports
  where exports.user_id = owner_id and exports.kind = 'my_stories' and exports.state = 'ready'
    and exports.ready_at > now() - interval '24 hours'
    and exports.expires_at > now()
    and exports.story_id is not distinct from wanted.story_id
    and exports.chapter_ids is not distinct from wanted.chapter_ids
    and exports.include_chapters = wanted.include_chapters
    and exports.include_plan = wanted.include_plan
    and exports.include_data = wanted.include_data
    and exports.document_format = wanted.document_format
    and exports.content_fingerprint = current_fingerprint
  order by exports.ready_at desc
  limit 1;
$$;


