COMMENT ON FUNCTION "public"."run_email_worker"() IS 'Internal: calls the email worker through pg_net when emails are due (S1-E7-02); pg_cron every 5 minutes.';



CREATE OR REPLACE FUNCTION "public"."run_notification_jobs"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job public.jobs;
  handled integer := 0;
begin
  for job in
    select * from public.jobs
    where jobs.kind in ('chapter_published', 'comment_posted') and jobs.processed_at is null
      and jobs.run_after <= now()
    order by jobs.created_at
    limit 500
    for update skip locked
  loop
    if job.kind = 'chapter_published' then
      perform public.notify_chapter_published(job.payload);
    else
      perform public.notify_comment_posted(job.payload);
    end if;
    update public.jobs set processed_at = now() where jobs.id = job.id;
    handled := handled + 1;
  end loop;
  return handled;
end;
$$;


ALTER FUNCTION "public"."run_notification_jobs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_notification_jobs"() IS 'Turns waiting chapter_published and comment_posted jobs into notifications; every minute (S1-E7-01).';



CREATE OR REPLACE FUNCTION "public"."run_opening_email_worker"() RETURNS boolean
