COMMENT ON FUNCTION "public"."sanction_end"("wanted_kind" "public"."sanction_kind", "days" integer) IS 'Internal: when a new sanction ends (S1-E10-06).';



CREATE OR REPLACE FUNCTION "public"."sanctions_close_for_good"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.kind <> 'ban' then
    return null;
  end if;
  -- Step 1: a new ban hides the account.
  if tg_op = 'INSERT' and new.lifted_at is null then
    perform public.hide_banned_account(new);
  end if;
  -- Step 2: a lifted ban brings back what it hid.
  if tg_op = 'UPDATE' and old.lifted_at is null and new.lifted_at is not null then
    update public.moderated_items
    set restored_at = new.lifted_at, restored_by_user_id = new.lifted_by_user_id,
        restore_reason = coalesce(nullif(btrim(coalesce(new.lift_reason, '')), ''), 'The ban was lifted.')
    where moderated_items.sanction_id = new.id and moderated_items.restored_at is null;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."sanctions_close_for_good"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sanctions_close_for_good"() IS 'Trigger: a ban hides the account''s profile and content; lifting it restores exactly those (part f1).';



CREATE OR REPLACE FUNCTION "public"."save_canva_connection"("access_ciphertext" "text", "refresh_ciphertext" "text", "access_expires" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
begin
  -- Step 1: a member who may write, while Canva covers are on.
  if caller_id is null or not public.is_active_member() then
    raise exception 'Your account can''t connect Canva right now.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_feature_enabled('canva_covers') then
    raise exception 'Designing covers in Canva is switched off.' using errcode = 'feature_not_supported';
  end if;
  -- Step 2: one row per account; a new connection replaces the old one.
  insert into public.canva_connections (user_id, access_token_ciphertext, refresh_token_ciphertext, access_expires_at)
  values (caller_id, access_ciphertext, refresh_ciphertext, access_expires)
  on conflict (user_id) do update
    set access_token_ciphertext = excluded.access_token_ciphertext,
        refresh_token_ciphertext = excluded.refresh_token_ciphertext,
        access_expires_at = excluded.access_expires_at;
end;
$$;


ALTER FUNCTION "public"."save_canva_connection"("access_ciphertext" "text", "refresh_ciphertext" "text", "access_expires" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_canva_connection"("access_ciphertext" "text", "refresh_ciphertext" "text", "access_expires" timestamp with time zone) IS 'Stores the caller''s encrypted Canva tokens; called by /api/canva (S1-E3-12).';



CREATE OR REPLACE FUNCTION "public"."save_chapter_draft"("chapter_code" "text", "title" "text", "body" "text", "expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  chapter public.chapters;
  clean_title text := public.normalise_romanian_letters(regexp_replace(btrim(coalesce(title, '')), '\s+', ' ', 'g'));
  clean_body text;
  saved_time timestamptz := now();
begin
  -- Step 1: a signed-in writer who may write.
  if caller_id is null then
    raise exception 'Sign in to save a chapter.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('status', 'not_active');
  end if;
  -- Step 2: their own live chapter, locked for this save so two devices can't interleave.
  select * into chapter from public.chapters
  where chapters.code = chapter_code and chapters.user_id = caller_id and chapters.deleted_at is null
  for update;
  if not found then
    return jsonb_build_object('status', 'not_found');
  end if;
  -- Step 3: a stale version means another device saved first: tell the editor, change nothing.
  if chapter.draft_version <> expected_version then
    return jsonb_build_object('status', 'conflict', 'version', chapter.draft_version, 'saved_at', chapter.draft_saved_at);
  end if;
  -- Step 4: the rules (rule 8): length, no HTML, safe links, ş/ţ corrected; then pictures and cards.
  if char_length(clean_title) > 120 then
    raise exception 'A chapter title can have at most 120 characters (S1-E3-02a).' using errcode = 'check_violation';
  end if;
  clean_body := public.check_chapter_text(body);
  perform public.check_chapter_pictures(clean_body, caller_id);
  perform public.check_chapter_embeds(clean_body, caller_id);
  -- Step 5: save and move the version on.
  update public.chapters set
    draft_title = clean_title,
    draft_body = clean_body,
    draft_version = chapter.draft_version + 1,
    draft_saved_at = saved_time,
    word_count = public.count_words(clean_body)
  where chapters.id = chapter.id;
  return jsonb_build_object('status', 'saved', 'version', chapter.draft_version + 1,
    'saved_at', saved_time, 'word_count', public.count_words(clean_body));
end;
$$;


ALTER FUNCTION "public"."save_chapter_draft"("chapter_code" "text", "title" "text", "body" "text", "expected_version" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_chapter_draft"("chapter_code" "text", "title" "text", "body" "text", "expected_version" integer) IS 'The autosave: {status: saved, version, saved_at, word_count} | conflict | not_active | not_found (S1-E3-02a).';



CREATE OR REPLACE FUNCTION "public"."save_my_preferences"("read_categories" "text"[], "write_categories" "text"[], "topic_tag_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := public.require_live_profile();
  wanted_categories text[] := coalesce(read_categories, '{}') || coalesce(write_categories, '{}');
  wanted_topics uuid[] := coalesce(topic_tag_ids, '{}');
begin
  -- Step 1: every choice must be one the screen offers.
  if cardinality(wanted_topics) > 30 then
    raise exception 'Pick at most 30 topics.' using errcode = 'check_violation', hint = 'too_many_topics';
  end if;
  if exists (select 1 from unnest(wanted_categories) as wanted_slug
             where not exists (select 1 from public.categories where categories.slug = wanted_slug))
     or exists (select 1 from unnest(wanted_topics) as wanted_tag
                where not exists (select 1 from public.tags where tags.id = wanted_tag
                                  and tags.status = 'approved' and tags.is_recommended)) then
    raise exception 'That choice isn''t on the list.' using errcode = 'check_violation', hint = 'unknown_choice';
  end if;
  -- Step 2: the new set replaces the old one.
  delete from public.reading_preferences where user_id = caller;
  insert into public.reading_preferences (user_id, preference_kind, category_id)
  select caller, 'read', categories.id from public.categories where categories.slug = any (read_categories)
  union all
  select caller, 'write', categories.id from public.categories where categories.slug = any (write_categories);
  insert into public.reading_preferences (user_id, preference_kind, tag_id)
  select distinct caller, 'topic', wanted_tag from unnest(wanted_topics) as wanted_tag;
end;
$$;


ALTER FUNCTION "public"."save_my_preferences"("read_categories" "text"[], "write_categories" "text"[], "topic_tag_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_my_preferences"("read_categories" "text"[], "write_categories" "text"[], "topic_tag_ids" "uuid"[]) IS 'Replaces the caller''s likes: categories to read and write, and topics (S1-E2-06).';



