CREATE OR REPLACE FUNCTION "public"."save_reading_habit"("wanted_target" smallint, "wanted_reminders_on" boolean, "wanted_reminder_time" time without time zone, "device_time_zone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := (select auth.uid());
begin
  -- Step 1: a signed-in reader whose streak is on, from a clock we know.
  if caller is null then
    raise exception 'Log in to keep a reading streak.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.reading_habits where reading_habits.user_id = caller) then
    raise exception 'Turn the reading streak on first.' using errcode = 'P0002';
  end if;
  if not public.is_known_time_zone(device_time_zone) then
    raise exception 'That time zone isn''t one we know.' using errcode = '22023';
  end if;
  -- Step 2: quiet hours for under-18s: no reminder between 22:00 and 07:00 (Q50).
  if wanted_reminders_on and public.is_in_quiet_hours(wanted_reminder_time)
     and public.is_under_18_or_unknown(caller) then
    raise exception 'quiet_hours' using errcode = '23514';
  end if;
  -- Step 3: keep it; the table's checks refuse a target out of range or a half-set reminder.
  update public.reading_habits set
    daily_target_minutes = wanted_target,
    reminders_on = wanted_reminders_on,
    reminder_time = wanted_reminder_time,
    time_zone = device_time_zone
  where reading_habits.user_id = caller;
end;
$$;


ALTER FUNCTION "public"."save_reading_habit"("wanted_target" smallint, "wanted_reminders_on" boolean, "wanted_reminder_time" time without time zone, "device_time_zone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_reading_habit"("wanted_target" smallint, "wanted_reminders_on" boolean, "wanted_reminder_time" time without time zone, "device_time_zone" "text") IS 'Keeps the caller''s daily reading target and reminder (IDEAS-1b).';



CREATE OR REPLACE FUNCTION "public"."save_reading_position"("story_slug" "text", "chapter_code" "text", "read_percent" integer, "device_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  chapter public.chapters;
  current_shelf public.library_shelf;
  new_shelf public.library_shelf;
  clamped integer := least(100, greatest(0, coalesce(read_percent, 0)));
begin
  -- Step 1: signed in, and a chapter this reader may read.
  if caller_id is null then
    raise exception 'Log in to keep your place.' using errcode = 'insufficient_privilege';
  end if;
  if device_kind is null or device_kind not in ('phone', 'tablet', 'computer') then
    raise exception 'Unknown kind of device.' using errcode = 'invalid_parameter_value';
  end if;
  select * into chapter from public.readable_chapter_for(story_slug, chapter_code);
  if not found then
    raise exception 'There is no such chapter.' using errcode = 'no_data_found';
  end if;
  -- Step 2: the place, one row per chapter; saving again moves it.
  insert into public.reading_positions (user_id, story_id, chapter_id, percent, device_kind)
  values (caller_id, chapter.story_id, chapter.id, clamped, device_kind)
  on conflict on constraint reading_positions_one_per_chapter
  do update set percent = excluded.percent, device_kind = excluded.device_kind, updated_at = now();
  -- Step 3: the shelf. A writer's own story never fills their library.
  if exists (select 1 from public.stories where stories.id = chapter.story_id and stories.user_id = caller_id) then
    return jsonb_build_object('shelf', null);
  end if;
  select library_entries.shelf into current_shelf from public.library_entries
  where library_entries.user_id = caller_id and library_entries.story_id = chapter.story_id;
  new_shelf := case
    when public.finishes_story(chapter, clamped) and coalesce(current_shelf, 'reading') = 'reading' then 'finished'
    when current_shelf is null or current_shelf = 'saved' then 'reading'
    else current_shelf
  end::public.library_shelf;
  if current_shelf is distinct from new_shelf then
    insert into public.library_entries (user_id, story_id, shelf)
    values (caller_id, chapter.story_id, new_shelf)
    on conflict on constraint library_entries_one_per_story do update set shelf = excluded.shelf;
  end if;
  return jsonb_build_object('shelf', new_shelf);
end;
$$;


ALTER FUNCTION "public"."save_reading_position"("story_slug" "text", "chapter_code" "text", "read_percent" integer, "device_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_reading_position"("story_slug" "text", "chapter_code" "text", "read_percent" integer, "device_kind" "text") IS 'Keeps the caller''s place in a chapter and files the story on a shelf (S1-E4-03).';



CREATE OR REPLACE FUNCTION "public"."save_reading_settings"("wanted_font" "public"."reading_font", "wanted_text_size" smallint, "wanted_line_spacing" "public"."reading_line_spacing", "wanted_line_width" "public"."reading_line_width", "wanted_theme" "public"."reading_theme", "wanted_night_by_clock" boolean DEFAULT false, "wanted_night_from" time without time zone DEFAULT NULL::time without time zone, "wanted_night_until" time without time zone DEFAULT NULL::time without time zone, "wanted_reading_ruler" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := (select auth.uid());
begin
  -- Step 1: only a signed-in reader has settings to keep.
  if caller is null then
    raise exception 'Log in to save your reading settings.' using errcode = '42501';
  end if;
  -- Step 2: one row per reader, replaced as a whole.
  insert into public.reading_settings (user_id, font, text_size, line_spacing, line_width, theme,
    night_by_clock, night_from, night_until, reading_ruler)
  values (caller, wanted_font, wanted_text_size, wanted_line_spacing, wanted_line_width, wanted_theme,
    coalesce(wanted_night_by_clock, false), wanted_night_from, wanted_night_until,
    coalesce(wanted_reading_ruler, false))
  on conflict (user_id) do update
    set font = excluded.font,
        text_size = excluded.text_size,
        line_spacing = excluded.line_spacing,
        line_width = excluded.line_width,
        theme = excluded.theme,
        night_by_clock = excluded.night_by_clock,
        night_from = excluded.night_from,
        night_until = excluded.night_until,
        reading_ruler = excluded.reading_ruler;
end;
$$;


ALTER FUNCTION "public"."save_reading_settings"("wanted_font" "public"."reading_font", "wanted_text_size" smallint, "wanted_line_spacing" "public"."reading_line_spacing", "wanted_line_width" "public"."reading_line_width", "wanted_theme" "public"."reading_theme", "wanted_night_by_clock" boolean, "wanted_night_from" time without time zone, "wanted_night_until" time without time zone, "wanted_reading_ruler" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_reading_settings"("wanted_font" "public"."reading_font", "wanted_text_size" smallint, "wanted_line_spacing" "public"."reading_line_spacing", "wanted_line_width" "public"."reading_line_width", "wanted_theme" "public"."reading_theme", "wanted_night_by_clock" boolean, "wanted_night_from" time without time zone, "wanted_night_until" time without time zone, "wanted_reading_ruler" boolean) IS 'Keeps the caller''s reading settings for every device (S1-E4-02; IDEAS-1 part a).';



CREATE OR REPLACE FUNCTION "public"."say_no_thanks_to_request"("sender_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_messaging_caller();
  other public.profiles := public.messaging_partner(sender_handle);
  chat public.conversations;
begin
  -- Step 1: a request from that person to the caller.
  if other.id is not null then
    chat := public.conversation_between(caller_id, other.id);
  end if;
  if chat.id is null or chat.status <> 'request' or chat.recipient_user_id <> caller_id then
    raise exception 'There is no message request from that person.' using errcode = 'no_data_found';
  end if;
  -- Step 2: closed with "No thanks"; reading it counts as reading the request.
  update public.conversations
    set status = 'declined', accepted_at = null, said_no_thanks_at = now()
    where conversations.id = chat.id returning * into chat;
  update public.conversation_members set last_read_at = now()
    where conversation_members.conversation_id = chat.id and conversation_members.user_id = caller_id;
  -- Step 3: a message email still waiting for the caller about it is no longer news.
  update public.email_outbox set sent_at = now()
    where email_outbox.conversation_id = chat.id and email_outbox.user_id = caller_id
      and email_outbox.sent_at is null;
  return jsonb_build_object('status', chat.status);
end;
$$;


ALTER FUNCTION "public"."say_no_thanks_to_request"("sender_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."say_no_thanks_to_request"("sender_handle" "text") IS 'The recipient answers a message request with "No thanks": the sender sees a fixed message and waits 30 days (IDEAS-2 idea 7).';



CREATE OR REPLACE FUNCTION "public"."schedule_chapter"("chapter_code" "text", "publish_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chapter public.chapters := public.my_live_chapter(chapter_code);
  refusal text := public.chapter_gate_outcome(chapter);
begin
  if refusal is not null then
    return jsonb_build_object('outcome', refusal);
  end if;
  if chapter.status = 'published' then
    return jsonb_build_object('outcome', 'wrong_state');
  end if;
  if btrim(chapter.draft_body) = '' then
    return jsonb_build_object('outcome', 'empty');
  end if;
  if publish_at is null or publish_at <= now() or publish_at > now() + interval '1 year' then
    return jsonb_build_object('outcome', 'bad_time');
  end if;
  update public.chapters set status = 'scheduled', scheduled_for = publish_at where chapters.id = chapter.id;
  return jsonb_build_object('outcome', 'ok', 'scheduled_for', publish_at);
end;
$$;


ALTER FUNCTION "public"."schedule_chapter"("chapter_code" "text", "publish_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."schedule_chapter"("chapter_code" "text", "publish_at" timestamp with time zone) IS 'Schedules the caller''s own draft chapter: {outcome: ok | not_active | not_found | empty | wrong_state | bad_time} (S1-E3-03).';



CREATE OR REPLACE FUNCTION "public"."scrub_error_text"("raw_text" "text", "max_length" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select left(
    -- Step 6: long runs of digits (phone numbers, account numbers, timestamps).
    regexp_replace(
      -- Step 5: long unbroken strings of letters, digits, _ and - (API keys, codes, hashes).
      regexp_replace(
        -- Step 4: text in quotes ("…", '…', “…”, „…”), which is often what someone typed.
        regexp_replace(
          -- Step 3: IDs (UUIDs) and signed tokens (JWTs, "eyJ…").
          regexp_replace(
            regexp_replace(
              -- Step 2: email addresses.
              regexp_replace(
                -- Step 1: web addresses, which can carry codes in their query string.
                regexp_replace(coalesce(raw_text, ''), 'https?://[^[:space:]]+', '[url]', 'gi'),
                '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '[email]', 'g'
              ),
              'eyJ[A-Za-z0-9_-]+(\.[A-Za-z0-9_-]+){0,2}', '[token]', 'g'
            ),
            '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', '[id]', 'g'
          ),
          -- A single quote counts only after a space, a bracket or the start, so "can't" stays.
          '(^|[[:space:](\[{:=,])("[^"]*"|''[^'']*''|“[^”]*”|„[^”“]*[”“])', '\1[text]', 'g'
        ),
        '[A-Za-z0-9_-]{24,}', '[token]', 'g'
      ),
      '[0-9]{6,}', '[number]', 'g'
    ),
    max_length
  );
$$;


ALTER FUNCTION "public"."scrub_error_text"("raw_text" "text", "max_length" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."scrub_error_text"("raw_text" "text", "max_length" integer) IS 'Replaces web addresses, emails, tokens, IDs, quoted text and long numbers in error text with placeholders (S1-E1-05).';



CREATE OR REPLACE FUNCTION "public"."scrub_route_path"("raw_path" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select '/' || left(
    ltrim(
      -- Step 3: long numbers and token-like segments (invite codes, reset codes).
      regexp_replace(
        regexp_replace(
          -- Step 2: IDs (UUIDs).
          regexp_replace(
            -- Step 1: drop the query string and the hash, which can carry codes.
            regexp_replace(coalesce(raw_path, ''), '[?#].*$', ''),
            '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', ':id', 'g'
          ),
          '[A-Za-z0-9_-]{24,}', ':token', 'g'
        ),
        '[0-9]{6,}', ':number', 'g'
      ),
      '/'
    ),
    199
  );
$_$;


ALTER FUNCTION "public"."scrub_route_path"("raw_path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."scrub_route_path"("raw_path" "text") IS 'Keeps only the path of a page address, without query, hash, IDs or tokens (S1-E1-05).';



CREATE OR REPLACE FUNCTION "public"."search_fold"("raw_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select public.normalise_tag(raw_text);
$$;


ALTER FUNCTION "public"."search_fold"("raw_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_fold"("raw_text" "text") IS 'Internal: text in the form search compares, without diacritics (S1-E5-04).';



CREATE OR REPLACE FUNCTION "public"."search_forum_posts"("term" "text", "forum_slug" "text" DEFAULT NULL::"text", "author_handle" "text" DEFAULT NULL::"text", "skip" integer DEFAULT 0, "language_code" "text" DEFAULT 'ro'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  page_size constant integer := 20;
  query tsquery := public.search_query(term);
  pattern text := public.search_like_pattern(term);
  wanted_handle text := lower(ltrim(btrim(coalesce(author_handle, '')), '@'));
  scope_id uuid;
  found jsonb;
  found_count integer;
begin
  -- Step 1: a term of under 2 characters finds nothing (a single letter matches everything).
  if char_length(public.search_fold(coalesce(term, ''))) < 2 then
    return jsonb_build_object('results', '[]'::jsonb, 'has_more', false);
  end if;
  -- Step 2: the forum to search in, if one was picked; an unknown one finds nothing.
  if forum_slug is not null then
    select forums.id into scope_id from public.forums
    where forums.slug = search_forum_posts.forum_slug and forums.deleted_at is null;
    if scope_id is null then
      return jsonb_build_object('results', '[]'::jsonb, 'has_more', false);
    end if;
  end if;
  -- Step 3: every live post the caller may read that matches, in its thread and forum, ranked
  -- (one extra, to know whether there is more).
  with candidates as (
    select forum_posts.id as post_id, forum_posts.post_number, forum_posts.user_id, forum_posts.created_at,
           forum_posts.body, forum_threads.thread_number, forum_threads.title, forums.id as forum_id,
           forums.slug, public.forum_post_search_text(forum_posts, forum_threads.title) as text
    from public.forum_posts
    join public.forum_threads on forum_threads.id = forum_posts.thread_id
    join public.forums on forums.id = forum_threads.forum_id and forums.deleted_at is null
    where (scope_id is null or forums.id in (select public.forum_and_children(scope_id)))
      and (wanted_handle = '' or forum_posts.user_id in
            (select profiles.id from public.profiles where lower(profiles.handle) = wanted_handle))
      and public.forum_thread_is_shown(forum_threads)
      and public.forum_post_state_for_caller(forum_posts) = 'live'
  ), matched as (
    select candidates.*,
           candidates.post_number = 1 and public.search_fold(candidates.title) like pattern as title_matches,
           ts_rank(to_tsvector('pg_catalog.romanian', candidates.text) || to_tsvector('pg_catalog.english', candidates.text), query) as closeness
    from candidates
    where (to_tsvector('pg_catalog.romanian', candidates.text) || to_tsvector('pg_catalog.english', candidates.text)) @@ query
       or candidates.text like pattern
  ), page as (
    select * from matched
    order by matched.title_matches desc, matched.closeness desc, matched.created_at desc
    offset greatest(coalesce(skip, 0), 0)
    limit page_size + 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'kind', case when page.title_matches then 'thread' else 'post' end,
           'thread_number', page.thread_number,
           'thread_title', page.title,
           'forum_slug', page.slug,
           'forum_name', (select names.name from public.forum_name_in(page.forum_id, search_forum_posts.language_code) as names),
           'post_number', page.post_number,
           'author', public.forum_person_json(page.user_id),
           'created_at', page.created_at,
           'snippet', public.forum_search_snippet(page.body))
         order by page.title_matches desc, page.closeness desc, page.created_at desc), '[]'::jsonb),
         count(*)::integer
  into found, found_count
  from page;
  -- Step 4: the answer; the extra result only says there is more.
  if found_count > page_size then
    found := found - page_size;
  end if;
  return jsonb_build_object('results', found, 'has_more', found_count > page_size);
end;
$$;


ALTER FUNCTION "public"."search_forum_posts"("term" "text", "forum_slug" "text", "author_handle" "text", "skip" integer, "language_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_forum_posts"("term" "text", "forum_slug" "text", "author_handle" "text", "skip" integer, "language_code" "text") IS 'Threads and posts matching a search, by forum and author, without removed posts or blocked people; never a user ID (S1-E8-10).';



