COMMENT ON FUNCTION "public"."search_story"("story_slug" "text", "query" "text") IS 'One search across the caller''s story: characters, bible, chapters, scenes, ideas, events, marketing (S1-E17-30).';



CREATE OR REPLACE FUNCTION "public"."search_tags"("term" "text", "page_size" integer DEFAULT 21, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wanted_rows integer := least(greatest(coalesce(page_size, 21), 1), 60);
  total integer;
  page jsonb;
begin
  -- Step 1: a term of at least 2 letters and a page that starts at 0 or later.
  if coalesce(page_offset, 0) < 0 then
    raise exception 'The page can''t start before the first tag.' using errcode = 'invalid_parameter_value';
  end if;
  if char_length(public.search_fold(term)) < 2 then
    return jsonb_build_object('total', 0, 'tags', '[]'::jsonb);
  end if;
  -- Step 2: approved tags with a matching name in any language, counted over the visible stories;
  -- then the count and one page.
  with found_tags as (
    select tags.name, count(*)::integer as story_count
    from public.tags
    join public.story_tags on story_tags.tag_id = tags.id
    join public.listed_stories('popular', null, null, null, null) as visible on visible.id = story_tags.story_id
    where tags.status = 'approved'
      and (tags.normalised_name like public.search_like_pattern(term)
        or exists (select 1 from public.tag_names
          where tag_names.tag_id = tags.id and tag_names.normalised_name like public.search_like_pattern(term)))
    group by tags.id, tags.name
  ),
  ordered as (
    select found_tags.*, row_number() over (order by found_tags.story_count desc, found_tags.name) as position
    from found_tags
  )
  select (select count(*)::integer from found_tags),
    coalesce((select jsonb_agg(jsonb_build_object('name', ordered.name, 'story_count', ordered.story_count)
        order by ordered.position)
      from ordered where ordered.position > coalesce(page_offset, 0)
        and ordered.position <= coalesce(page_offset, 0) + wanted_rows), '[]'::jsonb)
  into total, page;
  return jsonb_build_object('total', total, 'tags', page);
end;
$$;


ALTER FUNCTION "public"."search_tags"("term" "text", "page_size" integer, "page_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_tags"("term" "text", "page_size" integer, "page_offset" integer) IS 'Approved tags whose name in any language answers a search, with the stories the reader may see (S1-E5-04).';



CREATE OR REPLACE FUNCTION "public"."search_writers"("term" "text", "page_size" integer DEFAULT 21, "page_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  wanted_rows integer := least(greatest(coalesce(page_size, 21), 1), 60);
  folded text := public.search_fold(term);
  total integer;
  page jsonb;
begin
  -- Step 1: a term of at least 2 letters and a page that starts at 0 or later.
  if coalesce(page_offset, 0) < 0 then
    raise exception 'The page can''t start before the first writer.' using errcode = 'invalid_parameter_value';
  end if;
  if char_length(folded) < 2 then
    return jsonb_build_object('total', 0, 'writers', '[]'::jsonb);
  end if;
  -- Step 2: the writers of the stories this reader may see, whose names contain the term; then
  -- the count and one page, best match first.
  with found_writers as (
    select profiles.handle, public.display_name(profiles.handle, profiles.pen_name) as display_name,
      public.bio_for_caller(profiles) as bio, count(*)::integer as story_count,
      (public.search_fold(profiles.handle) like folded || '%'
        or public.search_fold(profiles.pen_name) like folded || '%') as starts_with
    from public.listed_stories('popular', null, null, null, null) as visible
    join public.profiles on profiles.id = visible.user_id
    where not public.is_moderated_away('profile', profiles.id)
      and (public.search_fold(profiles.handle) like public.search_like_pattern(term)
        or public.search_fold(profiles.pen_name) like public.search_like_pattern(term))
    group by profiles.id
  ),
  ordered as (
    select found_writers.*, row_number() over (order by found_writers.starts_with desc,
      found_writers.story_count desc, found_writers.handle) as position
    from found_writers
  )
  select (select count(*)::integer from found_writers),
    coalesce((select jsonb_agg(jsonb_build_object('handle', ordered.handle, 'display_name', ordered.display_name,
        'bio', ordered.bio, 'story_count', ordered.story_count) order by ordered.position)
      from ordered where ordered.position > coalesce(page_offset, 0)
        and ordered.position <= coalesce(page_offset, 0) + wanted_rows), '[]'::jsonb)
  into total, page;
  return jsonb_build_object('total', total, 'writers', page);
end;
$$;


ALTER FUNCTION "public"."search_writers"("term" "text", "page_size" integer, "page_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_writers"("term" "text", "page_size" integer, "page_offset" integer) IS 'Writers whose username or pen name answers a search, with a story the reader may see (S1-E5-04).';



CREATE OR REPLACE FUNCTION "public"."send_finished_thanks"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  story public.stories;
begin
  -- Step 1: a signed-in member who may act (the account gate, B02).
  if caller_id is null then
    raise exception 'Log in to thank a writer.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  -- Step 2: a story the caller may see, not their own, and on their Finished shelf.
  select * into story from public.reader_visible_story(story_slug);
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if story.user_id = caller_id then
    return jsonb_build_object('outcome', 'own_story');
  end if;
  if not exists (select 1 from public.library_entries
    where library_entries.user_id = caller_id and library_entries.story_id = story.id
      and library_entries.shelf = 'finished') then
    return jsonb_build_object('outcome', 'not_finished');
  end if;
  -- Step 3: once per story; a second press changes nothing.
  insert into public.finished_thanks (user_id, story_id) values (caller_id, story.id)
  on conflict on constraint finished_thanks_once_a_story do nothing;
  if not found then
    return jsonb_build_object('outcome', 'already_sent');
  end if;
  -- Step 4: the writer's notification: who and which story, never any text from the reader.
  perform public.notify(story.user_id, 'story_finished', caller_id,
    jsonb_build_object('story_id', story.id));
  return jsonb_build_object('outcome', 'ok');
end;
$$;


ALTER FUNCTION "public"."send_finished_thanks"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_finished_thanks"("story_slug" "text") IS 'Tells a story''s writer, in fixed words, that the caller finished it; once per story (IDEAS-1c).';



CREATE OR REPLACE FUNCTION "public"."send_landing_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reminder record;
  sent integer := 0;
begin
  -- Step 1: each waiting reminder for a live page whose entries are open now.
  for reminder in
    select reminders.id, reminders.user_id, reminders.page_id
    from public.landing_page_reminders as reminders
    join public.landing_pages as pages on pages.id = reminders.page_id and pages.archived_at is null
    cross join lateral public.landing_page_live_version(pages.id) as live
    where reminders.notified_at is null and live.id is not null
      and (live.take_down_on is null or live.take_down_on > public.romania_today())
      and public.landing_entries_open_on(live.content) <= public.romania_today()
    for update of reminders skip locked
  loop
    -- Step 2: one in-app notification, with no actor, then mark the reminder as sent.
    perform public.notify(reminder.user_id, 'landing_entries_open', null,
      jsonb_build_object('landing_page_id', reminder.page_id));
    update public.landing_page_reminders set notified_at = now(), updated_at = now()
    where landing_page_reminders.id = reminder.id;
    sent := sent + 1;
  end loop;
  -- Step 3: a sent reminder isn't needed after 30 days.
  delete from public.landing_page_reminders where notified_at < now() - interval '30 days';
  return sent;
end;
$$;


ALTER FUNCTION "public"."send_landing_reminders"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_landing_reminders"() IS 'Hourly: sends each landing page reminder once, when entries open (S1-E11-14).';



CREATE OR REPLACE FUNCTION "public"."send_live_session_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reminder record;
  sent integer := 0;
begin
  -- Step 1: each waiting reminder for a session that starts within the hour.
  for reminder in
    select reminders.id, reminders.user_id, reminders.session_id, sessions.rating
    from public.live_session_reminders as reminders
    join public.live_sessions as sessions on sessions.id = reminders.session_id
    where reminders.notified_at is null and sessions.deleted_at is null
      and sessions.starts_at > now() and sessions.starts_at <= now() + interval '1 hour'
    for update of reminders skip locked
  loop
    if public.rating_fits_band(reminder.rating, public.age_band_of(reminder.user_id)) then
      -- Step 2: one in-app notification, with no actor, then mark the reminder as sent.
      perform public.notify(reminder.user_id, 'live_session_soon', null,
        jsonb_build_object('live_session_id', reminder.session_id));
      update public.live_session_reminders set notified_at = now()
      where live_session_reminders.id = reminder.id;
      sent := sent + 1;
    else
      -- The session is no longer for this member's age group: no notification, no reminder.
      delete from public.live_session_reminders where live_session_reminders.id = reminder.id;
    end if;
  end loop;
  -- Step 3: a reminder isn't needed 30 days after its session (docs/retention.md).
  delete from public.live_session_reminders as reminders
  using public.live_sessions as sessions
  where sessions.id = reminders.session_id and sessions.starts_at < now() - interval '30 days';
  return sent;
end;
$$;


ALTER FUNCTION "public"."send_live_session_reminders"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_live_session_reminders"() IS 'Every ten minutes: sends each live session reminder once, in the hour before the start (GAPS-12h).';



CREATE OR REPLACE FUNCTION "public"."send_message"("recipient_handle" "text", "body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_messaging_caller();
  words text := btrim(coalesce(body, ''));
  other public.profiles := public.messaging_partner(recipient_handle);
  chat public.conversations;
begin
  -- Step 1: the words: text only, 1 to 2,000 characters.
  if char_length(words) not between 1 and 2000 then
    raise exception 'Write between 1 and 2,000 characters.' using errcode = 'check_violation';
  end if;
  -- Step 2: someone the caller may see.
  if other.id is null then
    raise exception 'There is nobody with that username.' using errcode = 'no_data_found';
  end if;
  -- Step 3: may the caller write to them now? One neutral answer for every reason.
  chat := public.conversation_between(caller_id, other.id);
  if not public.conversation_can_send(chat, caller_id, other.id) then
    raise exception 'This person isn''t taking messages right now.' using errcode = 'insufficient_privilege', hint = 'not_taking';
  end if;
  -- Step 4: the limits, then the chat: new, a new request after "No thanks", or a request the
  -- recipient now answers.
  perform public.take_rate_limit('message');
  if chat.id is null then
    chat := public.start_conversation(caller_id, other.id);
  elsif chat.status = 'declined' and chat.user_id = caller_id then
    update public.conversations set status = 'request', said_no_thanks_at = null
      where conversations.id = chat.id returning * into chat;
  elsif chat.status <> 'accepted' then
    update public.conversations set status = 'accepted', accepted_at = now(), said_no_thanks_at = null
      where conversations.id = chat.id returning * into chat;
  end if;
  -- Step 5: the message, and the chat moves to the top of both lists.
  insert into public.messages (conversation_id, user_id, body) values (chat.id, caller_id, words);
  update public.conversations set last_message_at = now() where conversations.id = chat.id;
  update public.conversation_members set last_read_at = now()
    where conversation_members.conversation_id = chat.id and conversation_members.user_id = caller_id;
  return jsonb_build_object('status', chat.status);
end;
$$;


ALTER FUNCTION "public"."send_message"("recipient_handle" "text", "body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_message"("recipient_handle" "text", "body" "text") IS 'Sends a private message, starting the chat or a request when there is none (S1-E9-01, S1-E9-03, IDEAS-2 idea 7).';



CREATE OR REPLACE FUNCTION "public"."send_moderator_mail"("subject" "text", "body" "text", "statement_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  clean_subject text := public.clean_mail_text(subject, 150);
  clean_body text := public.clean_mail_text(body, 4000);
  linked_statement_id uuid;
  new_thread public.moderator_mail_threads;
begin
  -- Step 1: signed in; the statement, when named, is theirs.
  if caller_id is null then
    raise exception 'Log in to write to the moderators.' using errcode = 'insufficient_privilege';
  end if;
  if nullif(btrim(statement_reference), '') is not null then
    select statements_of_reasons.id into linked_statement_id from public.statements_of_reasons
    where statements_of_reasons.reference = upper(btrim(statement_reference)) and statements_of_reasons.user_id = caller_id;
    if linked_statement_id is null then
      raise exception 'That decision isn''t one of yours.' using errcode = 'check_violation';
    end if;
  end if;
  -- Step 2: the limit (S1-E10-12), then the thread and its first message.
  perform public.take_rate_limit('moderator_mail');
  insert into public.moderator_mail_threads (reference, user_id, subject, statement_id)
  values ('M-' || lpad(nextval('public.moderator_mail_reference_seq')::text, 6, '0'), caller_id, clean_subject, linked_statement_id)
  returning * into new_thread;
  insert into public.moderator_mail_messages (thread_id, user_id, body) values (new_thread.id, caller_id, clean_body);
  return jsonb_build_object('reference', new_thread.reference);
end;
$$;


ALTER FUNCTION "public"."send_moderator_mail"("subject" "text", "body" "text", "statement_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_moderator_mail"("subject" "text", "body" "text", "statement_reference" "text") IS 'A member writes to the moderation team''s shared inbox (S1-E10-11).';



CREATE OR REPLACE FUNCTION "public"."send_on_call_alert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  new.on_call_user_id := public.on_call_now(new.created_at);
  new.alerted_at := now();
  if new.on_call_user_id is null then
    new.escalated_at := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."send_on_call_alert"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_on_call_alert"() IS 'Trigger: names who is on call and logs the (stub) phone alert as an on-call alert is made (S1-E10-09).';



CREATE OR REPLACE FUNCTION "public"."send_reading_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  habit record;
  sent_count integer := 0;
begin
  for habit in
    select reading_habits.user_id, (now() at time zone reading_habits.time_zone) as local_now,
      reading_habits.reminder_time, reading_habits.daily_target_minutes
    from public.reading_habits
    where reading_habits.reminders_on
  loop
    -- Step 1: the chosen time has come, within the last two hours, and not already today.
    --   (A late time's window stops at midnight: the next day is a new day, never a catch-up.)
    continue when habit.local_now::time < habit.reminder_time
      or habit.local_now::time - habit.reminder_time >= interval '2 hours';
    continue when exists (select 1 from public.reading_habits as already
      where already.user_id = habit.user_id and already.last_reminded_on = habit.local_now::date);
    -- Step 2: not when the target is met today.
    continue when coalesce((select reading_minutes.minutes from public.reading_minutes
      where reading_minutes.user_id = habit.user_id
        and reading_minutes.read_on = habit.local_now::date), 0) >= habit.daily_target_minutes;
    -- Step 3: quiet hours for under-18s (Q50).
    continue when public.is_in_quiet_hours(habit.local_now::time)
      and public.is_under_18_or_unknown(habit.user_id);
    -- Step 4: send it and remember the day.
    perform public.notify(habit.user_id, 'reading_reminder', null, '{}'::jsonb);
    update public.reading_habits set last_reminded_on = habit.local_now::date
    where reading_habits.user_id = habit.user_id;
    sent_count := sent_count + 1;
  end loop;
  return sent_count;
end;
$$;


