CREATE OR REPLACE FUNCTION "public"."set_block"("target_handle" "text", "should_block" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target public.profiles;
begin
  -- Step 1: signed in.
  if caller_id is null then
    raise exception 'Log in to block someone.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the person, never oneself.
  select * into target from public.profile_for_handle(target_handle);
  if not found then
    raise exception 'There is no account with that username.' using errcode = 'no_data_found';
  end if;
  if target.id = caller_id then
    raise exception 'You can''t block yourself.' using errcode = 'check_violation';
  end if;
  -- Step 3: unblock, or block and end the follows both ways.
  if not should_block then
    delete from public.blocks where blocks.user_id = caller_id and blocks.blocked_user_id = target.id;
    return jsonb_build_object('blocked', false);
  end if;
  insert into public.blocks (user_id, blocked_user_id) values (caller_id, target.id)
  on conflict on constraint blocks_one_per_pair do nothing;
  delete from public.follows_users
  where (follows_users.user_id = caller_id and follows_users.followed_user_id = target.id)
     or (follows_users.user_id = target.id and follows_users.followed_user_id = caller_id);
  delete from public.follows_stories
  using public.stories
  where stories.id = follows_stories.story_id
    and ((follows_stories.user_id = caller_id and stories.user_id = target.id)
      or (follows_stories.user_id = target.id and stories.user_id = caller_id));
  return jsonb_build_object('blocked', true);
end;
$$;


ALTER FUNCTION "public"."set_block"("target_handle" "text", "should_block" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_block"("target_handle" "text", "should_block" boolean) IS 'Blocks or unblocks a person by username; the other person isn''t told (S1-E5-05).';



CREATE OR REPLACE FUNCTION "public"."set_certificate_printed_name"("certificate_id" "uuid", "printed_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target public.certificates;
  clean_name text := nullif(btrim(regexp_replace(coalesce(printed_name, ''), '\s+', ' ', 'g')), '');
begin
  if caller_id is null then
    raise exception 'Log in to change your certificate.' using errcode = 'insufficient_privilege';
  end if;
  select * into target from public.certificates
  where certificates.id = certificate_id and certificates.user_id = caller_id for update;
  if target.id is null or target.space_id is null then
    raise exception 'There is no such certificate.' using errcode = 'no_data_found', hint = 'certificate:missing';
  end if;
  if target.revoked_at is not null then
    raise exception 'This certificate was revoked.' using errcode = 'check_violation', hint = 'certificate:revoked';
  end if;
  if public.certificate_name_deleted_on(target) < now() then
    raise exception 'Printed names are deleted 30 days after the class is archived.' using errcode = 'check_violation', hint = 'certificate:name_deleted';
  end if;
  if char_length(clean_name) > 80 then
    raise exception 'Write the name in 80 characters or fewer.' using errcode = 'check_violation', hint = 'certificate:name_length';
  end if;
  update public.certificates set printed_name = clean_name where certificates.id = target.id;
  return jsonb_build_object('printed_name', clean_name);
end;
$$;


