CREATE OR REPLACE FUNCTION "public"."set_character_picture"("character_id" "uuid", "new_picture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_character public.story_characters;
  replaced jsonb;
begin
  -- Step 1: a signed-in writer and their own character.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your characters.' using errcode = 'insufficient_privilege';
  end if;
  target_character := public.my_story_character(character_id);
  if target_character.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the picture is the caller's own, for this story, and not deleted.
  if not exists (select 1 from public.picture_checks
                 where picture_checks.id = new_picture_id and picture_checks.user_id = (select auth.uid())
                   and picture_checks.kind = 'atlas_image' and picture_checks.story_id = target_character.story_id
                   and picture_checks.deleted_at is null) then
    raise exception 'That picture isn''t one of yours for this story.' using errcode = 'check_violation';
  end if;
  -- Step 3: the old picture is forgotten, the new one put on the sheet.
  if target_character.picture_id is distinct from new_picture_id then
    replaced := public.forget_character_picture(target_character.picture_id);
  end if;
  update public.story_characters set picture_id = new_picture_id where story_characters.id = target_character.id;
  return jsonb_build_object('outcome', 'ok', 'replaced', replaced);
end;
$$;


ALTER FUNCTION "public"."set_character_picture"("character_id" "uuid", "new_picture_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_character_picture"("character_id" "uuid", "new_picture_id" "uuid") IS 'Puts one of the caller''s registered Story Atlas pictures on a character''s sheet (S1-E17-11).';



CREATE OR REPLACE FUNCTION "public"."set_character_public_parts"("character_id" "uuid", "parts" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your settings.' using errcode = 'insufficient_privilege';
  end if;
  if public.my_plan_item_kind(character_id) is distinct from 'character' then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  select story_id into target_story_id from public.story_characters where id = character_id;
  -- Every part is a group or one of this story's own fields.
  if exists (
    select 1 from unnest(coalesce(parts, '{}')) as part
    where part not in ('basics', 'look_and_voice', 'inside', 'in_the_story', 'notes')
      and not exists (select 1 from public.story_character_fields as fields
                      where fields.story_id = target_story_id and fields.id::text = part)) then
    raise exception 'Unknown part of a character sheet.' using errcode = 'check_violation', hint = 'unknown_part';
  end if;
  update public.story_characters
  set public_sheet_parts = array(select distinct part from unnest(coalesce(parts, '{}')) as part order by part)
  where id = character_id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


