COMMENT ON FUNCTION "public"."set_character_updated_at"() IS 'Trigger: keeps story_characters.updated_at current, except when only the map place changed (G10b2).';



CREATE OR REPLACE FUNCTION "public"."set_class_lock"("slug" "text", "new_locks_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(slug, 'settings');
  was_locked boolean := public.space_is_locked(space);
  wanted timestamptz := new_locks_at;
  action_taken text;
begin
  -- Step 1: only a class locks, and not further ahead than two years.
  if space.kind <> 'class' then
    raise exception 'Only a class space locks.' using errcode = 'check_violation', hint = 'space:not_class';
  end if;
  -- CLASSES-d: an archived class stays locked for good (S1-E8-11 criterion 8, Q69).
  if space.archived_at is not null then
    raise exception 'This class is archived.' using errcode = 'check_violation', hint = 'space:archived';
  end if;
  if new_locks_at > now() + interval '2 years' then
    raise exception 'Choose a date within two years.' using errcode = 'check_violation', hint = 'lock:date';
  end if;
  -- Step 2: a time in the past means "now", so the log says when it really locked.
  if new_locks_at < now() then
    wanted := now();
  end if;
  update public.spaces set locks_at = wanted where spaces.id = space.id returning * into space;
  -- Step 3: the space's log says what changed.
  action_taken := case
    when public.space_is_locked(space) and not was_locked then 'class_locked'
    when was_locked and not public.space_is_locked(space) then 'class_unlocked'
    else 'lock_date_changed' end;
  perform public.log_space_action(space, action_taken, null, null, null,
    jsonb_build_object('locks_at', space.locks_at));
  return jsonb_build_object('locks_at', space.locks_at, 'is_locked', public.space_is_locked(space));
end;
$$;


ALTER FUNCTION "public"."set_class_lock"("slug" "text", "new_locks_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_class_lock"("slug" "text", "new_locks_at" timestamp with time zone) IS 'Sets when a class space locks, locks it now or unlocks it; logged (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."set_landing_reminder"("page_slug" "text", "wanted" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  page public.landing_pages;
  live public.landing_page_versions;
  opens_on date;
begin
  -- Step 1: only a signed-in reader; a visitor is asked to sign in.
  if caller_id is null then
    raise exception 'Sign in to be reminded.' using errcode = 'insufficient_privilege', hint = 'sign_in';
  end if;
  -- Step 2: a live page with a Remind me block, whose entries haven't opened yet.
  select * into page from public.landing_pages
  where landing_pages.slug = lower(btrim(page_slug)) and landing_pages.archived_at is null;
  live := public.landing_page_live_version(page.id);
  if page.id is null or live.id is null
     or not coalesce(live.content -> 'blocks', '[]') @> '[{"kind": "remind_me"}]' then
    raise exception 'This page has no reminder.' using errcode = 'check_violation', hint = 'no_reminder';
  end if;
  opens_on := public.landing_entries_open_on(live.content);
  if wanted and (opens_on is null or opens_on <= public.romania_today()) then
    raise exception 'Entries are open already.' using errcode = 'check_violation', hint = 'already_open';
  end if;
  -- Step 3: add or remove the reader's one reminder; asking twice changes nothing.
  if wanted then
    insert into public.landing_page_reminders (user_id, page_id) values (caller_id, page.id)
    on conflict (user_id, page_id) do nothing;
  else
    delete from public.landing_page_reminders
    where landing_page_reminders.user_id = caller_id and landing_page_reminders.page_id = page.id;
  end if;
  return public.landing_reminder_json(page.id, live.content);
end;
$$;


