CREATE OR REPLACE FUNCTION "public"."set_my_country"("country_code" "text", "region_code" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me uuid := (select auth.uid());
  place jsonb := public.sign_up_country(jsonb_build_object('country', country_code, 'legal_region', region_code));
  profile_row public.profiles;
  outcome text;
  needed_before boolean;
  grace timestamptz;
begin
  -- Step 1: a signed-in member, and a real code.
  if me is null then
    raise exception 'Sign in to set your country.' using errcode = 'insufficient_privilege';
  end if;
  if place ->> 'country' is null then
    raise exception 'Pick a country.' using errcode = 'check_violation', hint = 'unknown_country';
  end if;
  select * into profile_row from public.profiles where profiles.id = me for update;
  -- Step 2: the new country's rule, checked before anything is saved (criterion 2).
  outcome := public.age_rule_outcome(profile_row.birth_year, profile_row.birth_month,
    place ->> 'country', place ->> 'region');
  if outcome in ('blocked', 'under_minimum') then
    raise exception 'People your age can''t use the app in that country.' using errcode = 'check_violation', hint = 'under_country_age';
  end if;
  -- Step 3: save it; a consent the old rule didn't ask for starts the 14 days' grace.
  needed_before := coalesce(public.needs_country_consent(me), false);
  update public.profiles set country_code = place ->> 'country', legal_region_code = place ->> 'region',
    country_chosen_at = now()
  where profiles.id = me;
  if public.needs_country_consent(me) and not needed_before then
    grace := now() + interval '14 days';
    update public.profiles set consent_grace_until = grace where profiles.id = me;
  end if;
  return jsonb_build_object('outcome', 'ok', 'consent_needed', coalesce(public.needs_country_consent(me), false),
    'grace_until', grace);
end;
$$;


ALTER FUNCTION "public"."set_my_country"("country_code" "text", "region_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_country"("country_code" "text", "region_code" "text") IS 'A member sets the country (and region) they live in, after checking its age rule; a new consent need starts 14 days'' grace (MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."set_my_handle"("new_handle" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  profile_row public.profiles;
  outcome text;
begin
  -- Step 1: a signed-in person with a live profile.
  select * into profile_row from public.profiles where profiles.id = caller_id and profiles.deleted_at is null;
  if not found then
    raise exception 'Sign in to choose a username.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: nothing to do when the name is the same, character for character.
  if profile_row.handle is not distinct from new_handle then
    return 'ok';
  end if;
  -- Step 3: the waiting time, then the name checks.
  if public.change_is_too_soon(profile_row.handle_changed_at, 'handle_change_days') then
    return 'too_soon';
  end if;
  outcome := public.check_handle(new_handle);
  if outcome <> 'ok' then
    return outcome;
  end if;
  -- Step 4: save; a change after the first choice starts the waiting time and is logged.
  update public.profiles
    set handle = new_handle,
        handle_changed_at = case when profile_row.handle is null then null else now() end
    where profiles.id = caller_id;
  if profile_row.handle is not null then
    perform public.log_account_change(caller_id, 'profile.handle_changed',
      jsonb_build_object('handle', profile_row.handle), jsonb_build_object('handle', new_handle));
  end if;
  return 'ok';
exception
  -- Two people saving look-alike names at the same moment: the unique index lets one through.
  when unique_violation then
    return 'taken';
end;
$$;


ALTER FUNCTION "public"."set_my_handle"("new_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_handle"("new_handle" "text") IS 'Saves the signed-in person''s username, or says why not (S1-E2-04).';



CREATE OR REPLACE FUNCTION "public"."set_my_locale"("new_locale" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved_locale text;
begin
  -- Step 1: only a signed-in person has a profile to save to.
  if (select auth.uid()) is null then
    raise exception 'Sign in to save your language to your account.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Step 2: refuse anything but the two interface languages, with a clear message (the table's
  -- check would refuse it too, but with a less helpful one).
  if new_locale is null or new_locale not in ('ro', 'en') then
    raise exception 'Unsupported interface language: %. Use ro or en.', coalesce(new_locale, 'null')
      using errcode = 'invalid_parameter_value';
  end if;

  -- Step 3: change the caller's own row only, and only while the account is live.
  update public.profiles
    set locale = new_locale
    where profiles.id = (select auth.uid()) and profiles.deleted_at is null
    returning profiles.locale into saved_locale;

  -- Step 4: no row means a deleted account or a sign-up whose profile doesn't exist yet.
  if saved_locale is null then
    raise exception 'This account has no profile to save the language to.'
      using errcode = 'no_data_found';
  end if;

  return saved_locale;
end;
$$;


ALTER FUNCTION "public"."set_my_locale"("new_locale" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_locale"("new_locale" "text") IS 'Saves the signed-in person''s interface language (ro or en) on their own profile (S1-E1-04).';



CREATE OR REPLACE FUNCTION "public"."set_my_pen_name"("new_pen_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  profile_row public.profiles;
  cleaned_pen_name text := public.normalise_pen_name(new_pen_name);
  is_first_choice boolean;
  outcome text;
begin
  -- Step 1: a signed-in person with a live profile.
  select * into profile_row from public.profiles where profiles.id = caller_id and profiles.deleted_at is null;
  if not found then
    raise exception 'Sign in to choose a pen name.' using errcode = 'insufficient_privilege';
  end if;
  if profile_row.pen_name is not distinct from cleaned_pen_name then
    return 'ok';
  end if;
  -- Step 2: the waiting time (not for the very first pen name), then the name checks.
  is_first_choice := profile_row.pen_name is null and profile_row.pen_name_changed_at is null;
  if not is_first_choice and public.change_is_too_soon(profile_row.pen_name_changed_at, 'pen_name_change_days') then
    return 'too_soon';
  end if;
  outcome := public.check_pen_name(new_pen_name);
  if outcome <> 'ok' then
    return outcome;
  end if;
  -- Step 3: save, and log anything but the first choice.
  update public.profiles
    set pen_name = cleaned_pen_name,
        pen_name_changed_at = case when is_first_choice then null else now() end
    where profiles.id = caller_id;
  if not is_first_choice then
    perform public.log_account_change(caller_id, 'profile.pen_name_changed',
      jsonb_build_object('pen_name', profile_row.pen_name), jsonb_build_object('pen_name', cleaned_pen_name));
  end if;
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."set_my_pen_name"("new_pen_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_pen_name"("new_pen_name" "text") IS 'Saves or removes the signed-in person''s pen name, or says why not (S1-E2-04).';



CREATE OR REPLACE FUNCTION "public"."set_my_signature"("signature_text" "text", "picture_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  cleaned text := nullif(btrim(replace(coalesce(signature_text, ''), E'\r', ''), E' \n\t'), '');
  me public.profiles;
  old_file jsonb;
begin
  -- Step 1: an account that may write.
  if caller_id is null or not public.is_active_member() then
    raise exception 'Your account can''t change its signature right now.' using errcode = 'insufficient_privilege';
  end if;
  select * into me from public.profiles where profiles.id = caller_id;
  -- Step 2: the limits (criterion 1), with a hint the screen turns into words.
  if char_length(coalesce(cleaned, '')) > 300 then
    raise exception 'A signature is at most 300 characters.' using errcode = 'check_violation', hint = 'signature:too_long';
  end if;
  if array_length(string_to_array(coalesce(cleaned, ''), E'\n'), 1) > 3 then
    raise exception 'A signature is at most three lines.' using errcode = 'check_violation', hint = 'signature:too_many_lines';
  end if;
  -- Step 3: the picture is the caller's own signature picture.
  if set_my_signature.picture_id is not null and not exists (
      select 1 from public.picture_checks
      where picture_checks.id = set_my_signature.picture_id and picture_checks.kind = 'signature_picture'
        and picture_checks.user_id = caller_id and picture_checks.deleted_at is null) then
    raise exception 'That picture isn''t yours.' using errcode = 'check_violation', hint = 'picture:not_yours';
  end if;
  -- Step 4: a replaced picture is marked deleted and its file handed back.
  if me.signature_picture_id is not null and me.signature_picture_id is distinct from set_my_signature.picture_id then
    update public.picture_checks set deleted_at = coalesce(deleted_at, now())
    where picture_checks.id = me.signature_picture_id
    returning jsonb_build_object('bucket', picture_checks.bucket, 'path', picture_checks.path) into old_file;
  end if;
  -- Step 5: the change.
  update public.profiles set signature = cleaned, signature_picture_id = set_my_signature.picture_id,
    updated_at = now()
  where profiles.id = caller_id;
  return jsonb_build_object('old_file', old_file);
end;
$$;


ALTER FUNCTION "public"."set_my_signature"("signature_text" "text", "picture_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_signature"("signature_text" "text", "picture_id" "uuid") IS 'Saves the caller''s forum signature: 300 characters, three lines, one still picture (S1-E8-08).';



CREATE OR REPLACE FUNCTION "public"."set_my_story_app_only"("story_slug" "text", "wanted" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  -- Step 1: a signed-in writer who may write, and their own live story.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change a story.' using errcode = 'insufficient_privilege';
  end if;
  if not public.is_active_member() then
    return jsonb_build_object('outcome', 'not_active');
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: save it. Library entries and follows stay as they are (S1-E3-08).
  update public.stories set is_app_only = coalesce(wanted, false) where stories.id = target_story_id;
  return jsonb_build_object('outcome', 'ok');
end;
$$;


