CREATE OR REPLACE FUNCTION "public"."set_my_waitlist_interest"("wanted" "public"."waitlist_interest") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
