COMMENT ON FUNCTION "public"."set_space_moderator"("slug" "text", "handle" "text", "powers" "public"."space_power"[]) IS 'The owner appoints a space moderator, changes their powers or removes them; logged (S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."set_space_welcome_note"("slug" "text", "note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(set_space_welcome_note.slug, 'settings');
  clean_note text := nullif(public.check_space_text(note, 'welcome'), '');
begin
  -- Step 1: nothing to do when the words are the same.
  if clean_note is not distinct from space.welcome_note then
    return public.space_json(space);
  end if;
  -- Step 2: the change, and the log line (without the words: the space has them).
  update public.spaces set welcome_note = clean_note where spaces.id = space.id returning * into space;
  perform public.log_space_action(space, 'welcome_note_changed', null, null, null,
    jsonb_build_object('has_note', clean_note is not null));
  return public.space_json(space);
end;
$$;


ALTER FUNCTION "public"."set_space_welcome_note"("slug" "text", "note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_space_welcome_note"("slug" "text", "note" "text") IS 'Saves the welcome note a space''s new members see once, for whoever holds the settings power; logged (IDEA-20261102-6).';



CREATE OR REPLACE FUNCTION "public"."set_story_class"("story_slug" "text", "class_slug" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid := public.my_live_story_id(story_slug);
  target_space_id uuid;
begin
  -- Step 1: only the writer changes this, so a teacher can never make a student's story public.
  if target_story_id is null then
    raise exception 'There is no such story of yours.' using errcode = 'check_violation', hint = 'story:missing';
  end if;
  -- Step 2: no class means everyone may read it again (the usual rating rules still apply).
  if class_slug is null then
    update public.stories set class_only = false, class_space_id = null, updated_at = now()
    where stories.id = target_story_id;
    return public.story_class_share(story_slug);
  end if;
  -- Step 3: the class must be one the writer is in and may read now, and not locked.
  select spaces.id into target_space_id from public.spaces
  where spaces.slug = class_slug
    and public.my_class_choices() @> jsonb_build_array(jsonb_build_object('slug', spaces.slug, 'name', spaces.name));
  if target_space_id is null then
    raise exception 'You can only share with a class you are in.' using errcode = 'check_violation', hint = 'class:not_yours';
  end if;
  update public.stories set class_only = true, class_space_id = target_space_id, updated_at = now()
  where stories.id = target_story_id;
  return public.story_class_share(story_slug);
end;
$$;


ALTER FUNCTION "public"."set_story_class"("story_slug" "text", "class_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_story_class"("story_slug" "text", "class_slug" "text") IS 'The writer shares their own story only with one of their classes, or makes it public again (S1-E8-11).';



CREATE OR REPLACE FUNCTION "public"."set_story_in_reading_list"("list_id" "uuid", "story_slug" "text", "is_in" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  most_stories integer := coalesce(public.setting_value('reading_list_stories_max') #>> '{}', '200')::integer;
begin
  -- Step 1: signed in, and the caller's own list. The lock makes two presses at the same moment
  -- wait for each other, so the count below is true.
  if caller_id is null then
    raise exception 'Log in to keep reading lists.' using errcode = 'insufficient_privilege';
  end if;
  perform pg_advisory_xact_lock(hashtext('reading_lists:' || caller_id::text));
  if not exists (select 1 from public.reading_lists
                 where id = list_id and user_id = caller_id and deleted_at is null) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: taking a story out works on any story in the list.
  if is_in is not true then
    delete from public.reading_list_stories as entries
    using public.stories
    where stories.id = entries.story_id and stories.slug = story_slug and entries.list_id = set_story_in_reading_list.list_id;
    update public.reading_lists set updated_at = now() where id = list_id;
    return jsonb_build_object('outcome', 'ok', 'in_list', false);
  end if;
  -- Step 3: a story the caller may read, with something published.
  select story.id into target_story_id from public.reader_visible_story(story_slug) as story;
  if target_story_id is null or not public.story_has_readable_chapter(target_story_id) then
    raise exception 'There is no such story.' using errcode = 'no_data_found';
  end if;
  -- Step 4: room in the list, unless the story is already in it.
  if not exists (select 1 from public.reading_list_stories as entries
                 where entries.list_id = set_story_in_reading_list.list_id and entries.story_id = target_story_id)
     and (select count(*) from public.reading_list_stories as entries
          where entries.list_id = set_story_in_reading_list.list_id) >= most_stories then
    raise exception 'A reading list holds at most % stories.', most_stories
      using errcode = 'check_violation', hint = 'too_many_stories';
  end if;
  -- Step 5: in, once; the list counts as changed, so it moves to the top of the Library's rows.
  insert into public.reading_list_stories (list_id, user_id, story_id)
  values (list_id, caller_id, target_story_id)
  on conflict on constraint reading_list_stories_once_per_list do nothing;
  update public.reading_lists set updated_at = now() where id = list_id;
  return jsonb_build_object('outcome', 'ok', 'in_list', true);
end;
$$;


ALTER FUNCTION "public"."set_story_in_reading_list"("list_id" "uuid", "story_slug" "text", "is_in" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_story_in_reading_list"("list_id" "uuid", "story_slug" "text", "is_in" boolean) IS 'Puts a story in one of the caller''s reading lists or takes it out (GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."set_story_public_areas"("story_slug" "text", "areas" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  saved_areas text[];
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your settings.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if not coalesce(areas, '{}') <@ public.plan_area_names() then
    raise exception 'Unknown area.' using errcode = 'check_violation', hint = 'unknown_area';
  end if;
  -- Each area once, in the settings' order.
  update public.story_plans
  set public_areas = array(select area from unnest(public.plan_area_names()) as area
                           where area = any (coalesce(set_story_public_areas.areas, '{}')))
  where story_plans.story_id = target_story_id
  returning public_areas into saved_areas;
  return jsonb_build_object('outcome', 'ok', 'areas', to_jsonb(saved_areas));
end;
$$;


ALTER FUNCTION "public"."set_story_public_areas"("story_slug" "text", "areas" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_story_public_areas"("story_slug" "text", "areas" "text"[]) IS 'Sets which areas of the caller''s plan readers see (S1-E17-32).';



CREATE OR REPLACE FUNCTION "public"."set_story_tags"("target_story_id" "uuid", "owner_id" "uuid", "tag_names" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  tag_name text;
  normalised text;
  seen uuid[] := '{}';
  tag_row_id uuid;
  writer_language text := (select profiles.locale from public.profiles where profiles.id = owner_id);
begin
  -- Step 1: start from a clean list, so the order and the merging are the same every time.
  delete from public.story_tags where story_tags.story_id = target_story_id;

  foreach tag_name in array coalesce(tag_names, '{}') loop
    -- Step 2: the one shared form; empty names are skipped.
    normalised := public.normalise_tag(tag_name);
    if normalised = '' then
      continue;
    end if;
    if char_length(normalised) > 40 then
      raise exception 'A tag can have at most 40 characters (S1-E3-01).' using errcode = 'check_violation';
    end if;

    -- Step 3: the tag this name stands for, in any language; else a new one waiting for staff,
    -- unless staff already rejected that name.
    tag_row_id := public.tag_for_name(tag_name, writer_language, true);
    if tag_row_id is null then
      if exists (select 1 from public.tags where tags.normalised_name = normalised) then
        continue;
      end if;
      insert into public.tags (name, normalised_name, status)
      values (regexp_replace(btrim(tag_name), '\s+', ' ', 'g'), normalised, 'waiting')
      returning tags.id into tag_row_id;
    end if;

    -- Step 4: link it once; the trigger refuses an eleventh tag.
    if tag_row_id = any (seen) then
      continue;
    end if;
    seen := seen || tag_row_id;
    insert into public.story_tags (story_id, tag_id, user_id) values (target_story_id, tag_row_id, owner_id);
  end loop;
end;
$$;


