CREATE OR REPLACE FUNCTION "public"."setting_value_problem"("old_value" "jsonb", "new_value" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  old_keys text[];
  new_keys text[];
  entry record;
  problem text;
begin
  -- Step 1: the type must stay the same (a number stays a number, a list a list).
  if new_value is null or jsonb_typeof(old_value) <> jsonb_typeof(new_value) then
    return 'wrong_kind';
  end if;
  -- Step 2: numbers are counts, limits, hours or weights: never below zero.
  if jsonb_typeof(new_value) = 'number' and (new_value #>> '{}')::numeric < 0 then
    return 'below_zero';
  end if;
  -- Step 3: a list keeps its kind of items; texts are distinct and not empty.
  if jsonb_typeof(new_value) = 'array' then
    if exists (select 1 from jsonb_array_elements(new_value) as item
               where jsonb_typeof(item) not in ('string', 'number')
                  or (jsonb_typeof(item) = 'string' and btrim(item #>> '{}') = '')
                  or (jsonb_typeof(item) = 'number' and (item #>> '{}')::numeric < 0)) then
      return 'bad_item';
    end if;
    if (select count(*) from jsonb_array_elements(new_value)) <> (select count(distinct item) from jsonb_array_elements(new_value) as item) then
      return 'repeated_item';
    end if;
  end if;
  -- Step 4: an object keeps its keys, and each value follows the same rules.
  if jsonb_typeof(new_value) = 'object' then
    select array_agg(key order by key) into old_keys from jsonb_object_keys(old_value) as key;
    select array_agg(key order by key) into new_keys from jsonb_object_keys(new_value) as key;
    if old_keys is distinct from new_keys then
      return 'changed_parts';
    end if;
    for entry in select key from jsonb_object_keys(old_value) as key loop
      problem := public.setting_value_problem(old_value -> entry.key, new_value -> entry.key);
      if problem is not null then
        return problem;
      end if;
    end loop;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."setting_value_problem"("old_value" "jsonb", "new_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setting_value_problem"("old_value" "jsonb", "new_value" "jsonb") IS 'Internal: a reason word when a new setting value can''t replace the old one, or null (S1-E11-03).';



CREATE OR REPLACE FUNCTION "public"."share_options"("story_slug" "text", "chapter_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shared record;
  story public.stories;
  cover_kind public.cover_kind;
begin
  -- Step 1: a signed-in reader and a chapter they may read, or nothing at all.
  select * into shared from public.shareable_chapter(story_slug, chapter_code);
  if (select auth.uid()) is null or not found then
    return jsonb_build_object('passages', false, 'pictures', false, 'card_colour', null, 'cover', null);
  end if;
  -- Step 2: the story, for the writer's switches, their card colour and the cover.
  select stories.* into story
  from public.chapters join public.stories on stories.id = chapters.story_id
  where chapters.id = shared.chapter_id;
  -- Step 3: a cover staff hid shows as the automatic one (S1-E11-08).
  cover_kind := case when story.cover_hidden_at is null then story.cover_kind else 'automatic' end;
  return jsonb_build_object(
    'passages', shared.quote_cards_enabled,
    -- The writer's picture switch, never for 16+ or 18+ (S1-E4-11, criterion 4).
    'pictures', coalesce(story.picture_sharing_enabled and public.story_shares_content(story.rating), false),
    'card_colour', story.card_colour,
    'cover', jsonb_build_object(
      'kind', cover_kind,
      -- The story's ID (never the writer's) draws the automatic cover (S1-E3-13).
      'story_id', story.id,
      'design', case when cover_kind = 'drawn' then story.cover_design end,
      'background', case when cover_kind = 'drawn' then story.cover_background end,
      'accent', case when cover_kind = 'drawn' then story.cover_accent end));
end;
$$;


