CREATE OR REPLACE FUNCTION "public"."sign_up_age_outcome"("birth_year" integer, "birth_month" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Europe/Bucharest')::date;
  needs_month boolean;
  band public.age_band;
begin
  -- Step 1: the year is required; the month only when the year needs it.
  if birth_year is null then
    return 'year_needed';
  end if;
  needs_month := public.birth_year_needs_month(birth_year, today);
  if needs_month and birth_month is null then
    return 'month_needed';
  end if;
  -- Step 2: the younger possible age; a month given for a year that doesn't need it is ignored.
  band := public.age_band_from_birth(
    birth_year, case when needs_month then birth_month end, 'pending', today
  );
  -- Step 3: the minimum age, then the March rule.
  if band = 'under_13' then
    return 'under_13';
  end if;
  if public.is_feature_enabled('adults_only') and band <> '18_plus' then
    return 'adults_only';
  end if;
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."sign_up_age_outcome"("birth_year" integer, "birth_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_age_outcome"("birth_year" integer, "birth_month" integer) IS 'What sign-up says about a year (and month): ok, year_needed, month_needed, under_13 or adults_only (S1-E2-02).';



CREATE OR REPLACE FUNCTION "public"."sign_up_birth_month"("sign_up_data" "jsonb", "birth_year" integer) RETURNS smallint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  month_text text := sign_up_data ->> 'birth_month';
  place jsonb := public.sign_up_country(sign_up_data);
begin
  if not public.birth_year_needs_month_where(birth_year, (now() at time zone 'Europe/Bucharest')::date,
      place ->> 'country', place ->> 'region')
    or month_text is null then
    return null;
  end if;
  if month_text !~ '^\d{1,2}$' or month_text::integer not between 1 and 12 then
    raise exception 'The month of birth must be 1 to 12.' using errcode = 'check_violation';
  end if;
  return month_text::smallint;
end;
$_$;


ALTER FUNCTION "public"."sign_up_birth_month"("sign_up_data" "jsonb", "birth_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_birth_month"("sign_up_data" "jsonb", "birth_year" integer) IS 'The month of birth from the sign-up, kept only when the year leaves the age unclear at 13, 16 or the country''s ages (S1-E2-02, MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."sign_up_birth_year"("sign_up_data" "jsonb") RETURNS smallint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  year_text text := sign_up_data ->> 'birth_year';
  this_year integer := extract(year from (now() at time zone 'Europe/Bucharest'))::integer;
begin
  if year_text is null or year_text !~ '^\d{4}$'
    or year_text::integer not between 1900 and this_year then
    raise exception 'Sign-up needs a year of birth.' using errcode = 'check_violation';
  end if;
  return year_text::smallint;
end;
$_$;


ALTER FUNCTION "public"."sign_up_birth_year"("sign_up_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_birth_year"("sign_up_data" "jsonb") IS 'Internal: the year of birth from the sign-up data, checked (S1-E2-01; S1-E2-02 adds the age rules).';



CREATE OR REPLACE FUNCTION "public"."sign_up_country"("sign_up_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  chosen text := upper(btrim(coalesce(sign_up_data ->> 'country', '')));
  region text := upper(btrim(coalesce(sign_up_data ->> 'legal_region', '')));
begin
  if chosen !~ '^[A-Z]{2}$' or chosen = 'ZZ' then
    return jsonb_build_object('country', null, 'region', '');
  end if;
  if not exists (select 1 from public.country_age_rules as rules
                 where rules.country_code = chosen and rules.region_code = region and region <> '') then
    region := '';
  end if;
  return jsonb_build_object('country', chosen, 'region', region);
end;
$_$;


ALTER FUNCTION "public"."sign_up_country"("sign_up_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_country"("sign_up_data" "jsonb") IS 'The country (and region with its own age law) chosen at sign-up, checked (MARKETS-1, S1-E2-20).';



CREATE OR REPLACE FUNCTION "public"."sign_up_handle"("sign_up_data" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  chosen_handle text := nullif(sign_up_data ->> 'handle', '');
  outcome text;
begin
  -- Step 1: no username sent, so the person picks one in /setup (S1-E2-04).
  if chosen_handle is null then
    return null;
  end if;
  -- Step 2: the same rules as setup and Settings: length, look-alikes, listed words, taken.
  outcome := public.check_handle(chosen_handle);
  if outcome <> 'ok' then
    raise exception 'Sign-up refused by the username rules: %.', outcome using errcode = 'check_violation';
  end if;
  return chosen_handle;
end;
$$;


ALTER FUNCTION "public"."sign_up_handle"("sign_up_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_handle"("sign_up_data" "jsonb") IS 'Internal: the checked username from the sign-up data, or null (S1-E2-04, username at sign-up).';



CREATE OR REPLACE FUNCTION "public"."sign_up_market_outcome"("country_code" "text", "birth_year" integer, "birth_month" integer DEFAULT NULL::integer, "region_code" "text" DEFAULT ''::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  market_row public.markets;
begin
  -- Step 1: the invited test admits adults from anywhere (Q6b, Q6c).
  if public.is_feature_enabled('invite_only') and public.is_feature_enabled('adults_only') then
    return 'ok';
  end if;
  -- Step 2: a closed or unknown market is closed.
  select * into market_row from public.markets where markets.country_code = sign_up_market_outcome.country_code;
  if not found or not market_row.is_open then
    return 'market_closed';
  end if;
  -- Step 3: the country's own ages (S1-E2-22).
  if public.age_rule_outcome(birth_year, birth_month, country_code, region_code) in ('blocked', 'under_minimum') then
    return 'under_market_age';
  end if;
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."sign_up_market_outcome"("country_code" "text", "birth_year" integer, "birth_month" integer, "region_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sign_up_market_outcome"("country_code" "text", "birth_year" integer, "birth_month" integer, "region_code" "text") IS 'Whether someone this old may join from this country: ok, market_closed or under_market_age, from the country''s age rule (S1-E2-10, MARKETS-1).';



CREATE OR REPLACE FUNCTION "public"."sign_up_rule_of"("message" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when message like '%age rules%' then 'age'
    when message like '%market rules%' then 'market'
    when message like '%username%' or message like '%profiles_handle%' then 'username'
    when message like '%invit%' then 'invite'
    else 'terms'
  end;
$$;


