CREATE OR REPLACE FUNCTION "public"."space_for_handover_answer"("target_slug" "text") RETURNS "public"."spaces"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces;
  refusal text;
begin
  select * into space from public.spaces
  where spaces.slug = target_slug and spaces.deleted_at is null
  for update;
  if space.id is null or space.handover_to_user_id is distinct from (select auth.uid()) then
    raise exception 'There is no offer to hand this space over to you.' using errcode = 'no_data_found', hint = 'handover:missing';
  end if;
  refusal := public.space_handover_refusal(space, (select auth.uid()));
  if refusal is not null then
    raise exception 'You can''t take this space over.' using errcode = 'check_violation', hint = 'handover:' || refusal;
  end if;
  return space;
end;
$$;


ALTER FUNCTION "public"."space_for_handover_answer"("target_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_for_handover_answer"("target_slug" "text") IS 'Internal: a space with an open hand-over offer to the caller, locked (IDEAS-3e).';



CREATE OR REPLACE FUNCTION "public"."space_for_power"("target_slug" "text", "wanted" "public"."space_power") RETURNS "public"."spaces"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces;
begin
  select * into space from public.spaces
  where spaces.slug = target_slug and spaces.deleted_at is null
  for update;
  if space.id is null or not (public.space_card_visible(space) or public.staff_may('moderation', 'act')) then
    raise exception 'There is no such space.' using errcode = 'no_data_found', hint = 'space:missing';
  end if;
  if not public.space_may_act(space, wanted) then
    raise exception 'You can''t do this in this space.' using errcode = 'insufficient_privilege', hint = 'space:not_allowed';
  end if;
  return space;
end;
$$;


