ALTER FUNCTION "public"."space_handover_json"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_handover_json"("target" "public"."spaces") IS 'Internal: a space''s open hand-over offer, for the owner and the moderator it is for (IDEAS-3e).';



CREATE OR REPLACE FUNCTION "public"."space_handover_refusal"("target" "public"."spaces", "person_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when not exists (select 1 from public.space_members
                     where space_members.space_id = target.id and space_members.user_id = person_id
                       and space_members.role = 'moderator' and space_members.status = 'active')
      then 'not_moderator'
    -- S1-E8-06: only under-16 accounts run an under-16 space, only 16+ accounts a 16+ one.
    when public.space_age_group_of_person(person_id) is distinct from target.age_group then 'age'
    -- S1-E2-11: a class is run by a teacher with the badge.
    when target.kind = 'class'
         and (select profiles.teacher_badge_since from public.profiles where profiles.id = person_id) is null
      then 'not_teacher'
  end;
$$;


ALTER FUNCTION "public"."space_handover_refusal"("target" "public"."spaces", "person_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_handover_refusal"("target" "public"."spaces", "person_id" "uuid") IS 'Internal: why a person may not take a space over, or null (IDEAS-3e).';



CREATE OR REPLACE FUNCTION "public"."space_hide_forum_post"("post_id" "uuid", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  post public.forum_posts := public.space_post_for_moderation(post_id, reason);
  space public.spaces := public.space_of_post(post);
begin
  if public.moderated_state_of('forum_post', post.id) is not null then
    raise exception 'This post is already hidden.' using errcode = 'check_violation', hint = 'post:already';
  end if;
  insert into public.moderated_items (user_id, item_type, item_id, state, moderated_by_user_id, note, space_id)
  values (post.user_id, 'forum_post', post.id, 'hidden', (select auth.uid()), btrim(reason), space.id);
  perform public.log_space_action(space, 'post_hidden', post.user_id, post.thread_id, reason,
    jsonb_build_object('post_id', post.id, 'post_number', post.post_number));
end;
$$;


