CREATE TABLE IF NOT EXISTS "public"."space_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "space_id" "uuid" NOT NULL,
    "role" "public"."space_member_role" DEFAULT 'member'::"public"."space_member_role" NOT NULL,
    "status" "public"."space_member_status" DEFAULT 'active'::"public"."space_member_status" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "joined_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "powers" "public"."space_power"[] DEFAULT '{}'::"public"."space_power"[] NOT NULL,
    "welcome_seen_at" timestamp with time zone,
    CONSTRAINT "space_members_joined_when_active" CHECK ((("status" = 'active'::"public"."space_member_status") = ("joined_at" IS NOT NULL))),
    CONSTRAINT "space_members_moderator_is_active" CHECK ((("role" <> 'moderator'::"public"."space_member_role") OR ("status" = 'active'::"public"."space_member_status"))),
    CONSTRAINT "space_members_owner_is_active" CHECK ((("role" <> 'owner'::"public"."space_member_role") OR ("status" = 'active'::"public"."space_member_status"))),
    CONSTRAINT "space_members_powers_only_moderators" CHECK ((("role" = 'moderator'::"public"."space_member_role") = ("cardinality"("powers") > 0)))
);


ALTER TABLE "public"."space_members" OWNER TO "postgres";


COMMENT ON TABLE "public"."space_members" IS 'kind: user_action
Who is in a space, and requests waiting for its owner (S1-E8-06).';



COMMENT ON COLUMN "public"."space_members"."powers" IS 'A moderator''s powers, chosen by the owner (S1-E8-07); empty for everyone else.';



