COMMENT ON FUNCTION "public"."space_join_requests"("slug" "text") IS 'The requests to join a space, oldest first, for the owner and moderators with the members power (S1-E8-06, S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."space_json"("target" "public"."spaces") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', target.id,
    'slug', target.slug,
    'forum_slug', 'space-' || target.slug,
    'name', target.name,
    'kind', target.kind,
    'locks_at', target.locks_at,
    'is_locked', public.space_is_locked(target),
    -- CLASSES-d: an archived class is locked for good; the school's name prints on certificates.
    'is_archived', target.archived_at is not null,
    'school_name', target.school_name,
    'description', target.description,
    'rules', target.rules,
    'age_group', case when target.kind = 'open'
                        and (target.age_group = public.space_age_group_of_caller()
                             or public.space_is_member(target.id) or public.staff_may('moderation', 'view'))
                      then target.age_group end,
    'readers', target.readers,
    'posting', target.posting,
    'joining', target.joining,
    'banner', target.banner,
    'banner_picture', (select public.picture_state_json(picture_checks) from public.picture_checks
                       where picture_checks.id = target.banner_picture_id
                         and picture_checks.deleted_at is null),
    -- G8b: the space's logo, once uploaded; null when it has none (the boards then show no picture).
    'logo_picture', (select public.picture_state_json(picture_checks) from public.picture_checks
                     where picture_checks.id = target.logo_picture_id
                       and picture_checks.deleted_at is null),
    'owner', public.forum_person_json(target.user_id),
    'member_count', (select count(*)::integer from public.space_members
                     where space_members.space_id = target.id and space_members.status = 'active'),
    'thread_count', (select count(*)::integer from public.forum_threads
                     where forum_threads.forum_id = public.space_forum_id(target.id) and forum_threads.deleted_at is null),
    'latest_activity_at', public.space_latest_activity(target),
    'created_at', target.created_at,
    'viewer', public.space_viewer_json(target));
$$;


ALTER FUNCTION "public"."space_json"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_json"("target" "public"."spaces") IS 'Internal: a space for the screens, never a user ID (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_latest_activity"("target" "public"."spaces") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select greatest(target.created_at, (
    select max(forum_threads.last_post_at) from public.forum_threads
    where forum_threads.forum_id = public.space_forum_id(target.id) and forum_threads.deleted_at is null));
$$;


ALTER FUNCTION "public"."space_latest_activity"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_latest_activity"("target" "public"."spaces") IS 'Internal: a space''s newest post, or its start (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_list"("skip" integer DEFAULT 0, "how_many" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  page_size integer := least(greatest(coalesce(how_many, 20), 1), 50);
  found jsonb;
  total integer;
begin
  -- Step 1: every live space whose card the caller may see, the busiest first; then one page.
  with seen as (
    select spaces as row_data, public.space_latest_activity(spaces) as activity from public.spaces
    where spaces.deleted_at is null and public.space_card_visible(spaces)
  ), page as (
    select seen.* from seen order by seen.activity desc, (seen.row_data).name
    offset greatest(coalesce(skip, 0), 0) limit page_size
  )
  select coalesce((select jsonb_agg(public.space_json(page.row_data) order by page.activity desc, (page.row_data).name)
                   from page), '[]'::jsonb),
         (select count(*)::integer from seen)
  into found, total;
  -- Step 2: the answer.
  return jsonb_build_object('spaces', found, 'total', total,
    'has_more', greatest(coalesce(skip, 0), 0) + page_size < total);
end;
$$;


ALTER FUNCTION "public"."space_list"("skip" integer, "how_many" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_list"("skip" integer, "how_many" integer) IS 'The spaces the caller may see, busiest first (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_log"("slug" "text", "skip" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces;
  page_size constant integer := 50;
begin
  -- Step 1: the space, for its owner or platform moderators only (the table's policy says the same).
  select * into space from public.spaces where spaces.slug = space_log.slug and spaces.deleted_at is null;
  if space.id is null or not (public.space_card_visible(space) or public.staff_may('moderation', 'view')) then
    raise exception 'There is no such space.' using errcode = 'no_data_found', hint = 'space:missing';
  end if;
  if space.user_id is distinct from (select auth.uid()) and not public.staff_may('moderation', 'view') then
    raise exception 'Only the space''s owner can read its log.' using errcode = 'insufficient_privilege', hint = 'space:not_owner';
  end if;
  -- Step 2: one page, one row more to know whether there is another.
  return (
    with page as (
      select log.* from public.space_moderation_log as log
      where log.space_id = space.id
      order by log.created_at desc, log.id
      offset greatest(coalesce(skip, 0), 0) limit page_size + 1
    )
    select jsonb_build_object(
      'entries', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'actor', case when page.by_platform then null else public.forum_person_json(page.user_id) end,
                 'action', page.action,
                 'target', public.forum_person_json(page.target_user_id),
                 'thread', (select jsonb_build_object('number', forum_threads.thread_number, 'title', forum_threads.title)
                            from public.forum_threads where forum_threads.id = page.thread_id),
                 'note', page.note,
                 'details', page.details,
                 'created_at', page.created_at) order by page.created_at desc, page.id)
        from (select * from page order by page.created_at desc, page.id limit page_size) as page), '[]'::jsonb),
      'has_more', (select count(*) > page_size from page)));
end;
$$;


ALTER FUNCTION "public"."space_log"("slug" "text", "skip" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_log"("slug" "text", "skip" integer) IS 'A space''s moderation log, for its owner and platform moderators (S1-E8-07 criterion 2).';



CREATE OR REPLACE FUNCTION "public"."space_may_act"("target" "public"."spaces", "wanted" "public"."space_power") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target.id is not null and target.deleted_at is null and (
    public.staff_may('moderation', 'act')
    or target.user_id = (select auth.uid())
    or exists (select 1 from public.space_members
               where space_members.space_id = target.id and space_members.user_id = (select auth.uid())
                 and space_members.role = 'moderator' and space_members.status = 'active'
                 and wanted = any (space_members.powers)));
$$;


