COMMENT ON FUNCTION "public"."space_may_act"("target" "public"."spaces", "wanted" "public"."space_power") IS 'Internal: whether the caller is the owner, a moderator with this power or platform moderation staff (S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."space_may_join"("target" "public"."spaces") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (select auth.uid()) is not null
    and target.kind = 'open'
    and public.space_card_visible(target)
    and public.is_active_member()
    and public.space_age_group_of_caller() = target.age_group
    and (public.space_membership_of_caller(target.id)).id is null;
$$;


ALTER FUNCTION "public"."space_may_join"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_may_join"("target" "public"."spaces") IS 'Internal: whether the caller may join a space: active, in its age group, not in it yet (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_may_post"("target" "public"."spaces") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (select auth.uid()) is not null
    and public.space_may_read(target)
    and not public.is_moderated_away('space', target.id)
    and public.is_active_member()
    and not public.space_is_locked(target)
    and (public.space_is_member(target.id)
         or (target.kind = 'open' and target.posting = 'anyone'
             and public.space_age_group_of_caller() = target.age_group));
$$;


ALTER FUNCTION "public"."space_may_post"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_may_post"("target" "public"."spaces") IS 'Internal: whether the caller may post in a space: members, or anyone in its age group when it allows (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_may_read"("target" "public"."spaces") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target.id is not null and target.deleted_at is null and (
    public.staff_may('moderation', 'view')
    or (target.user_id = (select auth.uid()) and public.moderated_state_of('space', target.id) is distinct from 'removed')
    or (not public.is_moderated_away('space', target.id)
        and not public.is_blocked_with(target.user_id)
        and target.kind = 'open'
        and (target.age_group = '16_plus' or target.readers = 'everybody' or public.space_is_member(target.id)))
    -- S1-E8-11: a class space, only for its members once their account is fully active.
    or (not public.is_moderated_away('space', target.id)
        and public.space_is_in_class(target)
        and public.is_active_member()));
$$;


ALTER FUNCTION "public"."space_may_read"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_may_read"("target" "public"."spaces") IS 'Internal: whether the caller may read a space''s threads, by the age rules (S1-E8-06; 34p).';



