CREATE OR REPLACE FUNCTION "public"."space_member_list"("slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(space_member_list.slug, 'members');
begin
