    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(power order by power), '{}')
  from unnest(enum_range(null::public.space_power)) as power
  where public.space_may_act(target, power);
$$;


ALTER FUNCTION "public"."space_powers_of_caller"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_powers_of_caller"("target" "public"."spaces") IS 'Internal: the caller''s powers in a space (S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."space_show_forum_post"("post_id" "uuid", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  post public.forum_posts := public.space_post_for_moderation(post_id, reason);
  space public.spaces := public.space_of_post(post);
  hide public.moderated_items;
begin
  select * into hide from public.moderated_items
  where moderated_items.item_type = 'forum_post' and moderated_items.item_id = post.id
    and moderated_items.restored_at is null
  for update;
  if hide.id is null then
    raise exception 'This post isn''t hidden.' using errcode = 'check_violation', hint = 'post:not_hidden';
  end if;
  if hide.space_id is distinct from space.id then
    raise exception 'Our moderation team hid this post.' using errcode = 'check_violation', hint = 'post:by_team';
  end if;
  update public.moderated_items
  set restored_at = now(), restored_by_user_id = (select auth.uid()), restore_reason = btrim(reason)
  where moderated_items.id = hide.id;
  perform public.log_space_action(space, 'post_shown', post.user_id, post.thread_id, reason,
    jsonb_build_object('post_id', post.id, 'post_number', post.post_number));
end;
$$;


ALTER FUNCTION "public"."space_show_forum_post"("post_id" "uuid", "reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_show_forum_post"("post_id" "uuid", "reason" "text") IS 'Shows again a reply a space''s moderators hid; never one our team hid; logged (GAPS-10).';



CREATE OR REPLACE FUNCTION "public"."space_slug_for"("name" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  base text := left(btrim(regexp_replace(public.space_name_key(name), '[^a-z0-9]+', '-', 'g'), '-'), 44);
  candidate text;
  attempt integer := 1;
begin
  -- Step 1: a name of only marks or one letter still gets an address.
  base := btrim(base, '-');
  if char_length(base) < 2 or base = 'new' then
    base := 'space';
  end if;
  -- Step 2: the first free one.
  candidate := base;
  while exists (select 1 from public.spaces where spaces.slug = candidate) loop
    attempt := attempt + 1;
    candidate := base || '-' || attempt;
  end loop;
  return candidate;
end;
$$;


ALTER FUNCTION "public"."space_slug_for"("name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_slug_for"("name" "text") IS 'Internal: a free address for a new space, from its name (S1-E8-06).';



CREATE OR REPLACE FUNCTION "public"."space_viewer_json"("target" "public"."spaces") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'membership', case
      when membership.role = 'owner' then 'owner'
      when membership.role = 'moderator' then 'moderator'
      when membership.status = 'active' then 'member'
      when membership.status = 'pending' then 'pending' end,
    'can_read', public.space_may_read(target),
    'can_join', public.space_may_join(target),
    'can_post', public.space_may_post(target),
    'can_manage', public.space_may_act(target, 'settings'),
    'can_appoint', target.user_id = (select auth.uid()) or public.staff_may('moderation', 'act'),
    'can_read_log', target.user_id = (select auth.uid()) or public.staff_may('moderation', 'view'),
    'can_invite', target.kind = 'class' and public.space_may_act(target, 'members'),
    'waits_for_account', public.space_is_in_class(target) and not public.space_may_read(target),
    'powers', to_jsonb(public.space_powers_of_caller(target)),
    -- IDEAS-3d: the welcome note, for members and the people who run the space only.
    'welcome_note', case when membership.status = 'active' or public.space_may_act(target, 'settings')
                         then target.welcome_note end,
    'show_welcome', coalesce(target.welcome_note is not null and membership.status = 'active'
                             and membership.role <> 'owner' and membership.welcome_seen_at is null, false),
    -- IDEAS-3e: the owner may offer the space to a moderator; an open offer is shown to the owner
    -- and to the moderator it is for, never to anyone else.
    'can_hand_over', target.user_id = (select auth.uid()),
    'handover', public.space_handover_json(target))
  from (select (public.space_membership_of_caller(target.id)).*) as membership;
$$;


ALTER FUNCTION "public"."space_viewer_json"("target" "public"."spaces") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."space_viewer_json"("target" "public"."spaces") IS 'Internal: the caller''s place in a space and what they may do (S1-E8-06, S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."sponsor_ad_for_slot"("wanted_slot_key" "text", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
      'key', 'campaign:' || campaigns.id, 'label', 'sponsored', 'kind', 'sponsor',
      'page_slug', null, 'title_ro', null, 'title_en', null,
      'sponsor_name', sponsors.name, 'text_ro', campaigns.text_ro, 'text_en', campaigns.text_en,
      'alt_ro', campaigns.alt_ro, 'alt_en', campaigns.alt_en,
      'picture_bucket', picture_checks.bucket, 'picture_path', picture_checks.path,
      'link_url', campaigns.link_url, 'discount_code', nullif(campaigns.discount_code, ''))
  from public.sponsor_campaigns as campaigns
  join public.sponsors on sponsors.id = campaigns.sponsor_id
  left join public.picture_checks on picture_checks.id = campaigns.picture_id
  where wanted_slot_key = any (public.sponsor_placement_slots(campaigns.placement))
    and public.sponsor_campaign_is_live(campaigns)
    and not ('campaign:' || campaigns.id) = any (coalesce(used_keys, '{}'))
    and (cardinality(campaigns.target_categories) = 0 or context ->> 'category' = any (campaigns.target_categories))
    and (cardinality(campaigns.target_tags) = 0
         or public.normalise_tag(coalesce(context ->> 'tag', '')) = any (campaigns.target_tags))
    and (cardinality(campaigns.target_languages) = 0 or context ->> 'language' = any (campaigns.target_languages))
  order by md5(campaigns.id::text || wanted_page_key || public.romania_today()::text)
  limit 1;
$$;


ALTER FUNCTION "public"."sponsor_ad_for_slot"("wanted_slot_key" "text", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_ad_for_slot"("wanted_slot_key" "text", "wanted_page_key" "text", "context" "jsonb", "used_keys" "text"[]) IS 'Internal: the live sponsor campaign matching a slot and the page''s context only (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."sponsor_campaign_from_json"("campaign" "public"."sponsor_campaigns", "fields" "jsonb") RETURNS "public"."sponsor_campaigns"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  campaign.sponsor_id := (fields ->> 'sponsor_id')::uuid;
  campaign.name := btrim(coalesce(fields ->> 'name', ''));
  campaign.placement := (fields ->> 'placement')::public.sponsor_placement;
  -- A category or contest only for its own placement, so the table's checks hold.
  campaign.category_slug := case when campaign.placement = 'category' then nullif(fields ->> 'category_slug', '') end;
  campaign.contest_id := case when campaign.placement = 'contest' then nullif(fields ->> 'contest_id', '')::uuid end;
  -- Targeting: the page's category, tag and language only.
  campaign.target_categories := array(select jsonb_array_elements_text(coalesce(fields -> 'target_categories', '[]')));
  campaign.target_tags := array(select distinct public.normalise_tag(tag)
                                from jsonb_array_elements_text(coalesce(fields -> 'target_tags', '[]')) as tag);
  campaign.target_languages := array(select jsonb_array_elements_text(coalesce(fields -> 'target_languages', '[]')));
  -- The creative's words, the link and the code.
  campaign.alt_ro := btrim(coalesce(fields ->> 'alt_ro', ''));
  campaign.alt_en := btrim(coalesce(fields ->> 'alt_en', ''));
  campaign.text_ro := btrim(coalesce(fields ->> 'text_ro', ''));
  campaign.text_en := btrim(coalesce(fields ->> 'text_en', ''));
  campaign.link_url := btrim(coalesce(fields ->> 'link_url', ''));
  campaign.discount_code := btrim(coalesce(fields ->> 'discount_code', ''));
  campaign.starts_on := nullif(fields ->> 'starts_on', '')::date;
  campaign.ends_on := nullif(fields ->> 'ends_on', '')::date;
  -- Any change needs a new review (criterion 2).
  campaign.state := 'draft';
  campaign.submitted_at := null;
  campaign.reviewer_user_id := null;
  campaign.reviewed_at := null;
  campaign.review_checks := '{}';
  -- The note from a send-back stays, so the editor still sees what to fix.
  campaign.review_note := coalesce(campaign.review_note, '');
  return campaign;
end;
$$;


ALTER FUNCTION "public"."sponsor_campaign_from_json"("campaign" "public"."sponsor_campaigns", "fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_campaign_from_json"("campaign" "public"."sponsor_campaigns", "fields" "jsonb") IS 'Internal: fills a campaign from the editor''s fields and puts it back in draft (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."sponsor_campaign_is_live"("campaign" "public"."sponsor_campaigns") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select campaign.state = 'approved'
    and public.romania_today() between campaign.starts_on and campaign.ends_on
    and (campaign.picture_id is null or exists (
      select 1 from public.picture_checks
      where picture_checks.id = campaign.picture_id
        and public.picture_is_visible(picture_checks.bucket, picture_checks.path)));
$$;


ALTER FUNCTION "public"."sponsor_campaign_is_live"("campaign" "public"."sponsor_campaigns") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_campaign_is_live"("campaign" "public"."sponsor_campaigns") IS 'Internal: approved, within its dates and with a visible picture (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."sponsor_campaign_problems"("campaign" "public"."sponsor_campaigns") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  problems text[] := public.sponsor_creative_problems(campaign);
  link_problem text := public.sponsor_link_problem(campaign.link_url);
begin
  -- Step 1: a name, and a sponsor that is still active.
  if btrim(campaign.name) = '' then
    problems := 'name:empty'::text || problems;
  end if;
  if exists (select 1 from public.sponsors where sponsors.id = campaign.sponsor_id and sponsors.archived_at is not null) then
    problems := problems || 'sponsor:archived'::text;
  end if;
  -- Step 2: the link; a credit may go without one.
  if link_problem is not null
     and not (link_problem = 'link:empty' and campaign.placement in ('category', 'contest')) then
    problems := problems || link_problem;
  end if;
  -- Step 3: a discount code is letters, digits and hyphens.
  if campaign.discount_code <> '' and campaign.discount_code !~ '^[A-Za-z0-9-]{3,40}$' then
    problems := problems || 'discount_code:bad'::text;
  end if;
  -- Step 4: both dates, and not over before it starts.
  if campaign.starts_on is null or campaign.ends_on is null then
    problems := problems || 'dates:missing'::text;
  elsif campaign.ends_on < public.romania_today() then
    problems := problems || 'dates:past'::text;
  end if;
  -- Step 5: the categories it targets exist.
  if exists (select 1 from unnest(campaign.target_categories) as wanted (slug)
             where not exists (select 1 from public.categories where categories.slug = wanted.slug)) then
    problems := problems || 'targets:unknown_category'::text;
  end if;
  return problems;
end;
$_$;


ALTER FUNCTION "public"."sponsor_campaign_problems"("campaign" "public"."sponsor_campaigns") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_campaign_problems"("campaign" "public"."sponsor_campaigns") IS 'Internal: what a sponsor campaign still needs before review (S1-E12-02 criterion 1).';



CREATE OR REPLACE FUNCTION "public"."sponsor_creative_problems"("campaign" "public"."sponsor_campaigns") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  problems text[] := '{}';
  is_credit boolean := campaign.placement in ('category', 'contest');
  language_code text;
  alt_text text;
  line_text text;
begin
  -- Step 1: a banner or featured slot has a picture.
  if campaign.picture_id is null and not is_credit then
    problems := problems || 'picture:missing'::text;
  end if;
  -- Step 2: alt text for any picture, and the line of text for a banner, in both languages.
  foreach language_code in array array['ro', 'en'] loop
    alt_text := btrim(case language_code when 'ro' then campaign.alt_ro else campaign.alt_en end);
    line_text := btrim(case language_code when 'ro' then campaign.text_ro else campaign.text_en end);
    if campaign.picture_id is not null and alt_text = '' then
      problems := problems || (language_code || '.alt:empty');
    elsif char_length(alt_text) > 200 then
      problems := problems || (language_code || '.alt:too_long');
    end if;
    if line_text = '' and not is_credit then
      problems := problems || (language_code || '.text:empty');
    elsif char_length(line_text) > 140 then
      problems := problems || (language_code || '.text:too_long');
    end if;
  end loop;
  return problems;
end;
$$;


ALTER FUNCTION "public"."sponsor_creative_problems"("campaign" "public"."sponsor_campaigns") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_creative_problems"("campaign" "public"."sponsor_campaigns") IS 'Internal: a campaign''s picture, alt text and line of text problems (S1-E12-02 criterion 1).';



CREATE OR REPLACE FUNCTION "public"."sponsor_creative_upload_allowed"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select public.is_feature_enabled('picture_uploads')
    and public.staff_may('sponsors', 'act')
    and coalesce(object_name, '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpe?g|png|webp)$'
    and exists (
      select 1 from public.sponsor_campaigns
      where sponsor_campaigns.id = split_part(object_name, '/', 1)::uuid
        and sponsor_campaigns.state in ('draft', 'sent_back'));
$_$;


ALTER FUNCTION "public"."sponsor_creative_upload_allowed"("object_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_creative_upload_allowed"("object_name" "text") IS 'True for owner and admin, a random file name under a draft or sent-back campaign and picture_uploads on (SPONSORS-b1).';



CREATE OR REPLACE FUNCTION "public"."sponsor_credit"("credit_kind" "text", "credit_key" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- The earliest-starting live campaign wins, so the line doesn't flip between two sponsors.
  select jsonb_build_object('sponsor_name', sponsors.name, 'link_url', nullif(campaigns.link_url, ''),
                            'ad_key', 'campaign:' || campaigns.id)
  from public.sponsor_campaigns as campaigns
  join public.sponsors on sponsors.id = campaigns.sponsor_id
  left join public.contests on contests.id = campaigns.contest_id
  left join public.landing_pages on landing_pages.id = contests.landing_page_id
  where public.sponsor_campaign_is_live(campaigns)
    and ((credit_kind = 'category' and campaigns.placement = 'category' and campaigns.category_slug = credit_key)
      or (credit_kind = 'contest' and campaigns.placement = 'contest' and campaigns.contest_id::text = credit_key)
      or (credit_kind = 'contest_page' and campaigns.placement = 'contest'
          and landing_pages.slug = credit_key and landing_pages.archived_at is null))
  order by campaigns.starts_on, campaigns.id
  limit 1;
$$;


ALTER FUNCTION "public"."sponsor_credit"("credit_kind" "text", "credit_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_credit"("credit_kind" "text", "credit_key" "text") IS 'Public: the live sponsor of a category, contest or contest page, for "Sponsored by"; never changes lists or ranking (S1-E12-02).';



CREATE OR REPLACE FUNCTION "public"."sponsor_link_problem"("link" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when btrim(coalesce(link, '')) = '' then 'link:empty'
    when char_length(link) > 500 or link !~ '^https://[^/?#@\s]+([/?#]\S*)?$' then 'link:not_https'
    when link ~* '[?&#](utm_[a-z_]+|gclid|fbclid|msclkid|dclid|yclid|mc_cid|mc_eid|ref|aff|affid|aff_id|affiliate|affiliate_id|tag|clickid|click_id|partner|irclickid)='
      then 'link:tracking'
  end;
$_$;


ALTER FUNCTION "public"."sponsor_link_problem"("link" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sponsor_link_problem"("link" "text") IS 'Internal: a sponsor link must be https with no tracking or affiliate parameters (S1-E12-02).';



