CREATE OR REPLACE FUNCTION "public"."start_email_support_ticket"("sender" "text", "subject" "text", "body" "text", "email_message_id" "text", "is_automatic" boolean, "follow_up_of" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  sender_account uuid := public.account_for_email(sender);
  sender_language text;
  is_known_spam boolean := public.support_sender_is_spam(sender, sender_account);
  new_ticket public.support_tickets;
  recent_acknowledgements integer;
begin
  -- Step 1: the language: the account's, or Romanian (the acknowledgement then carries both).
  select case when profiles.locale = 'en' then 'en' else 'ro' end into sender_language
  from public.profiles where profiles.id = sender_account;
  -- Step 2: the ticket, its first message and its first history line.
  insert into public.support_tickets (requester_user_id, requester_email, language, subject, channel,
    follow_up_of_ticket_id, is_spam, marked_spam_at)
  values (sender_account, lower(btrim(sender)), coalesce(sender_language, 'ro'), subject, 'email', follow_up_of,
    is_known_spam, case when is_known_spam then now() end)
  returning * into new_ticket;
  insert into public.support_ticket_messages (ticket_id, kind, author_user_id, body, channel, email_message_id)
  values (new_ticket.id, 'from_requester', sender_account, body, 'email', email_message_id);
  perform public.record_support_event(new_ticket.id, 'created', null, jsonb_strip_nulls(jsonb_build_object(
    'channel', 'email',
    'follow_up_of', (select tickets.number from public.support_tickets as tickets where tickets.id = follow_up_of))));
  -- Step 3: no acknowledgement for spam, a machine, or a loop.
  select count(*) into recent_acknowledgements
  from public.support_ticket_emails as emails
  join public.support_tickets as tickets on tickets.id = emails.ticket_id
  where emails.kind = 'acknowledgement' and emails.created_at > now() - interval '1 hour'
    and tickets.requester_email = new_ticket.requester_email;
  if is_known_spam or coalesce(is_automatic, false) or recent_acknowledgements >= 3 then
    return jsonb_build_object('number', new_ticket.number, 'acknowledged', false);
  end if;
  insert into public.support_ticket_emails (ticket_id, kind) values (new_ticket.id, 'acknowledgement');
  return jsonb_build_object('number', new_ticket.number, 'acknowledged', true);
end;
$$;


ALTER FUNCTION "public"."start_email_support_ticket"("sender" "text", "subject" "text", "body" "text", "email_message_id" "text", "is_automatic" boolean, "follow_up_of" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_email_support_ticket"("sender" "text", "subject" "text", "body" "text", "email_message_id" "text", "is_automatic" boolean, "follow_up_of" "uuid") IS 'Internal: a new support ticket from an email, acknowledged unless automatic or looping (S1-E11-13 criteria 1, 2 and 7).';



CREATE OR REPLACE FUNCTION "public"."start_forum_thread"("forum_slug" "text", "title" "text", "body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := public.require_forum_writer();
  forum public.forums;
  clean_title text := public.check_forum_thread_title(title);
  clean_body text := public.check_forum_post_text(body);
  new_thread public.forum_threads;
begin
  -- Step 1: a live forum that holds threads.
  select * into forum from public.forums
  where forums.slug = start_forum_thread.forum_slug and forums.deleted_at is null;
  if forum.id is null then
    raise exception 'There is no such forum.' using errcode = 'no_data_found', hint = 'forum:missing';
  end if;
  if forum.level = 0 then
    raise exception 'Start a thread in one of the forums inside this category.' using errcode = 'check_violation', hint = 'forum:category';
  end if;
  -- Step 2: the thread, then its first post, numbered #1.
  insert into public.forum_threads (user_id, forum_id, title, last_post_number, last_post_at)
  values (caller_id, forum.id, clean_title, 1, now())
  returning * into new_thread;
  insert into public.forum_posts (user_id, thread_id, post_number, body)
  values (caller_id, new_thread.id, 1, clean_body);
  return jsonb_build_object('thread_number', new_thread.thread_number, 'forum_slug', forum.slug);
end;
$$;


ALTER FUNCTION "public"."start_forum_thread"("forum_slug" "text", "title" "text", "body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_forum_thread"("forum_slug" "text", "title" "text", "body" "text") IS 'Starts a thread with its first post, through the account gate and the limit (S1-E8-02).';



CREATE OR REPLACE FUNCTION "public"."start_reading_habit"("device_time_zone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller uuid := (select auth.uid());
begin
  if caller is null then
    raise exception 'Log in to keep a reading streak.' using errcode = '42501';
  end if;
  if not public.is_known_time_zone(device_time_zone) then
    raise exception 'That time zone isn''t one we know.' using errcode = '22023';
  end if;
  insert into public.reading_habits (user_id, time_zone) values (caller, device_time_zone)
  on conflict (user_id) do nothing;
end;
$$;


