CREATE OR REPLACE FUNCTION "public"."start_story_from_prompt"("story_slug" "text", "prompt_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  changed_rows integer;
begin
  -- Step 1: a signed-in writer only.
  if caller_id is null then
    raise exception 'Log in to write from a prompt.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: the prompt must be one the hub shows (started, not deleted).
  if not exists (select 1 from public.writing_prompts
                 where writing_prompts.id = prompt_id and writing_prompts.deleted_at is null
                   and writing_prompts.starts_on <= public.romania_today()) then
    return false;
  end if;
  -- Step 3: the caller's own live story, and only if it has no prompt yet.
  update public.stories set writing_prompt_id = prompt_id
  where stories.slug = story_slug and stories.user_id = caller_id
    and stories.deleted_at is null and stories.writing_prompt_id is null;
  get diagnostics changed_rows = row_count;
  return changed_rows = 1;
end;
$$;


ALTER FUNCTION "public"."start_story_from_prompt"("story_slug" "text", "prompt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_story_from_prompt"("story_slug" "text", "prompt_id" "uuid") IS 'The signed-in writer ties their own story to a started writing prompt, once; false when it can''t (GAPS-12c).';



CREATE OR REPLACE FUNCTION "public"."statement_from_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story_owner_id uuid;
  staff_reason text;
  is_ai_label boolean := new.payload ->> 'action' = 'ai_undisclosed_labelled';
begin
  if new.kind <> 'statement_of_reasons_needed' then
    return new;
  end if;
  -- Step 1: whose story, and why staff changed it.
  select stories.user_id into story_owner_id from public.stories where stories.id = (new.payload ->> 'story_id')::uuid;
  select audit_log.reason into staff_reason from public.audit_log where audit_log.id = (new.payload ->> 'audit_log_id')::uuid;
  -- Step 2: the statement, and the job is done.
  if story_owner_id is not null then
    perform public.issue_statement_of_reasons(story_owner_id,
      case when is_ai_label then 'ai_label_added' else 'rating_raised' end::public.statement_action,
      'terms', case when is_ai_label then 'undisclosed_ai' else 'rating_rules' end, staff_reason,
      jsonb_build_object('story_id', new.payload ->> 'story_id', 'item_type', 'story', 'item_id', new.payload ->> 'story_id'));
  end if;
  new.processed_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."statement_from_job"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."statement_from_job"() IS 'Trigger: a queued statement_of_reasons_needed job becomes a statement of reasons to the writer at once (S1-E3-06, S1-E10-04).';



CREATE OR REPLACE FUNCTION "public"."statement_ground_for_case"("target" "public"."cases") RETURNS TABLE("ground" "public"."statement_ground", "ground_key" "text")
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select
    case
      when target.source = 'authority_order' then 'law'::public.statement_ground
      when target.top_reason in ('illegal_content', 'child_sexual_content', 'terrorism', 'threat_to_minor',
                                 'copyright', 'copied_published_work') then 'law'::public.statement_ground
      else 'terms'::public.statement_ground
    end,
    case
      when target.source = 'authority_order' then 'authority_order'
      when target.source in ('picture_check', 'picture_review') then 'picture_check'
      else coalesce(target.top_reason::text, 'community_rules')
    end;
$$;


ALTER FUNCTION "public"."statement_ground_for_case"("target" "public"."cases") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."statement_ground_for_case"("target" "public"."cases") IS 'Internal: the rule or law a case''s decision rests on, for its statement (S1-E10-04; DSA art. 17(3)(d), (e)).';



CREATE OR REPLACE FUNCTION "public"."statement_json"("target" "public"."statements_of_reasons") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'reference', target.reference,
    'action', target.action,
    'item_type', target.item_type,
    'item_summary', target.item_summary,
    'facts', target.facts,
    'ground', target.ground,
    'ground_key', target.ground_key,
    'automated_detection', target.automated_detection,
    'automated_decision', target.automated_decision,
    'restriction_ends_at', target.restriction_ends_at,
    'appeal_until', target.appeal_until,
    'can_challenge', target.appeal_until > now(),
    'can_appeal', target.appeal_until > now()
      and not exists (select 1 from public.appeals where appeals.statement_id = target.id and appeals.status = 'open'),
    'appeal', (select jsonb_build_object('reference', appeals.reference, 'status', appeals.status,
                 'created_at', appeals.created_at, 'decided_at', appeals.decided_at,
                 'message', appeals.message_to_person)
               from public.appeals where appeals.statement_id = target.id
               order by appeals.created_at desc limit 1),
    'issued_at', target.issued_at,
    'case_reference', (select cases.reference from public.cases where cases.id = target.case_id));
$$;


ALTER FUNCTION "public"."statement_json"("target" "public"."statements_of_reasons") OWNER TO "postgres";


