COMMENT ON FUNCTION "public"."story_card_json"("target_story_id" "uuid") IS 'Internal: one story as a card in a list, never a user ID (S1-E5-01).';



CREATE OR REPLACE FUNCTION "public"."story_card_writer_rank"("writer" "public"."profiles", "target_story_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.rank_of(writer.id)
  where public.story_classic_author(target_story_id) is null
    and public.profile_is_open_to(writer, (select auth.uid()))
    and not exists (select 1 from public.blocks
                    where blocks.user_id = writer.id and blocks.blocked_user_id = (select auth.uid()));
$$;


