COMMENT ON FUNCTION "public"."story_card_writer_rank"("writer" "public"."profiles", "target_story_id" "uuid") IS 'Internal: the writer''s rank on a story card, null for classics, blocks and private profiles (IDEAS-3a).';



CREATE OR REPLACE FUNCTION "public"."story_cast"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story.
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your characters.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  -- Step 2: the characters, the writer's own fields with their places, the chapters to pick from
  -- and the relationships between the characters, with their notes (the writer's own).
  return (select jsonb_build_object(
    'outcome', 'ok',
    'story', jsonb_build_object('id', stories.id, 'slug', stories.slug, 'title', stories.title),
    'characters', coalesce((
      select jsonb_agg(public.character_json(story_characters) order by lower(story_characters.name), story_characters.created_at)
      from public.story_characters where story_characters.story_id = stories.id), '[]'::jsonb),
    'fields', coalesce((
      select jsonb_agg(jsonb_build_object('id', fields.id, 'name', fields.name, 'position', fields.position,
          'is_hidden', fields.hidden_at is not null,
          'sheet_group', fields.sheet_group, 'own_group', fields.own_group)
        order by fields.position, fields.created_at)
      from public.story_character_fields as fields where fields.story_id = stories.id), '[]'::jsonb),
    'chapters', coalesce((
      select jsonb_agg(jsonb_build_object('code', chapters.code, 'position', chapters.position,
          'title', chapters.draft_title) order by chapters.position)
      from public.chapters where chapters.story_id = stories.id and chapters.deleted_at is null), '[]'::jsonb),
    'relationships', coalesce((
      select jsonb_agg(public.relationship_json(links, true) order by links.created_at)
      from public.story_character_relationships as links where links.story_id = stories.id), '[]'::jsonb))
    from public.stories where stories.id = target_story_id);
end;
$$;


ALTER FUNCTION "public"."story_cast"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_cast"("story_slug" "text") IS 'The cast of one of the caller''s stories: its characters, custom fields, chapters and relationships (S1-E17-08 to S1-E17-16).';



CREATE OR REPLACE FUNCTION "public"."story_chapter_progress"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your chapters.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- The writer's own titles and word counts (the draft), never readers' numbers.
  return jsonb_build_object('outcome', 'ok', 'chapters', coalesce((
    select jsonb_agg(jsonb_build_object(
        'code', chapters.code, 'position', chapters.position, 'title', chapters.draft_title,
        'status', chapters.status, 'kind', coalesce(plans.kind, 'chapter'),
        'word_count', chapters.word_count, 'word_target', plans.word_target)
      order by chapters.position)
    from public.chapters
    left join public.chapter_plans as plans on plans.chapter_id = chapters.id
    where chapters.story_id = target_story_id and chapters.deleted_at is null), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."story_chapter_progress"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_chapter_progress"("story_slug" "text") IS 'The caller''s chapters of one story with words against each target (S1-E17-23, S1-E17-26).';



