CREATE OR REPLACE FUNCTION "public"."story_link_targets"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your story.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object('outcome', 'ok', 'targets', coalesce((
    select jsonb_agg(targets.target order by targets.kind_place, targets.title)
    from (
      select 1 as kind_place, cast_member.name as title, jsonb_build_object('kind', 'character',
          'ref', cast_member.id, 'title', cast_member.name,
          'names', to_jsonb(public.character_link_names(cast_member))) as target
      from public.story_characters as cast_member where cast_member.story_id = target_story_id
      union all
      select 2, entries.title, jsonb_build_object('kind', 'entry', 'ref', entries.id,
          'title', entries.title, 'names', jsonb_build_array(btrim(entries.title)))
      from public.story_bible_entries as entries where entries.story_id = target_story_id
      union all
      -- A chapter without a title can't be named, so it can't be linked.
      select 3, chapters.draft_title, jsonb_build_object('kind', 'chapter', 'ref', chapters.code,
          'title', chapters.draft_title, 'names', jsonb_build_array(btrim(chapters.draft_title)))
      from public.chapters
      where chapters.story_id = target_story_id and chapters.deleted_at is null
        and btrim(chapters.draft_title) <> ''
    ) as targets
  ), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."story_link_targets"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_link_targets"("story_slug" "text") IS 'What a [[Name]] in the caller''s story can point to: characters, bible entries, chapters (S1-E17-31).';



CREATE OR REPLACE FUNCTION "public"."story_listing_allows"("target" "public"."stories", "list_kind" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target.visibility = 'public'
    or target.user_id = (select auth.uid())
    or (target.visibility = 'unlisted' and (
      list_kind = 'library'
      -- GAPS-6: in a reading list as in someone's library: only for a reader who already keeps
      -- the story (in their library, their follows or one of their own lists).
      or (list_kind in ('reader_library', 'reading_list') and (
        exists (select 1 from public.library_entries
                where library_entries.user_id = (select auth.uid()) and library_entries.story_id = target.id)
        or exists (select 1 from public.reading_list_stories
                   where reading_list_stories.user_id = (select auth.uid()) and reading_list_stories.story_id = target.id)
        or exists (select 1 from public.follows_stories
                   where follows_stories.user_id = (select auth.uid()) and follows_stories.story_id = target.id)))));
$$;


ALTER FUNCTION "public"."story_listing_allows"("target" "public"."stories", "list_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_listing_allows"("target" "public"."stories", "list_kind" "text") IS 'Internal: unlisted stories show only in libraries, private ones nowhere but the writer''s own (NEW-1, GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."story_marketing"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  notes public.story_marketing;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your marketing notes.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  select * into notes from public.story_marketing where story_marketing.story_id = target_story_id;
  return jsonb_build_object('outcome', 'ok',
    'notes', jsonb_build_object(
      'back_cover_blurb', coalesce(notes.back_cover_blurb, ''),
      'comparable_titles', coalesce(notes.comparable_titles, ''),
      'hooks_keywords', coalesce(notes.hooks_keywords, ''),
      'query_pitch', coalesce(notes.query_pitch, ''),
      'launch_notes', coalesce(notes.launch_notes, '')),
    'own_details', coalesce(notes.own_details, '[]'::jsonb));
end;
$$;


