CREATE OR REPLACE FUNCTION "public"."story_page_chapters"("target_story_id" "uuid", "is_owner" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'code', listed.code,
      'number', listed.number,
      'title', listed.title,
      'status', listed.status,
      'published_at', listed.first_published_at,
      'edited_at', listed.edited_at,
      'word_count', listed.word_count
    ) order by listed.number), '[]'::jsonb)
  from (
    select chapters.code,
      row_number() over (order by chapters.position) as number,
      case when is_owner then chapters.draft_title else chapters.published_title end as title,
      chapters.status,
      chapters.first_published_at,
      chapters.edited_at,
      case when is_owner then chapters.word_count else chapters.published_word_count end as word_count
    from public.chapters
    where chapters.story_id = target_story_id
      and chapters.deleted_at is null
      and (is_owner or public.chapter_is_readable(chapters.id))
  ) as listed;
$$;


ALTER FUNCTION "public"."story_page_chapters"("target_story_id" "uuid", "is_owner" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_page_chapters"("target_story_id" "uuid", "is_owner" boolean) IS 'Internal: the story page''s chapter list, readable chapters for readers and every live one for the owner (S1-E3-03).';



CREATE OR REPLACE FUNCTION "public"."story_plan"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  result jsonb;
begin
  -- Step 1: a signed-in writer and their own live story.
  if caller_id is null then
    raise exception 'Sign in to see your plan.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  -- Step 2: the story's own fields and the plan's, never the user ID (rule 15).
  select jsonb_build_object(
    'outcome', 'ok',
    'story', jsonb_build_object(
      'slug', stories.slug, 'title', stories.title, 'blurb', stories.blurb,
      'category_slug', categories.slug, 'rating', stories.rating,
      'first_published_at', stories.first_published_at
    ),
    'plan', jsonb_build_object(
      'logline', plans.logline, 'series_name', plans.series_name, 'word_target', plans.word_target,
      'writing_status', plans.writing_status, 'publishing_route', plans.publishing_route,
      'linked_project_label', plans.linked_project_label, 'linked_project_url', plans.linked_project_url,
      'updated_at', plans.updated_at
    ),
    'acts', coalesce((
      select jsonb_agg(jsonb_build_object('position', acts.position, 'name', acts.name) order by acts.position)
      from public.story_plan_acts as acts where acts.story_id = stories.id
    ), '[]'::jsonb),
    'chapters', public.story_plan_chapters(stories.id),
    -- Step 3: the cast count and the five characters edited last, with role and line (G10a).
    'cast', jsonb_build_object(
      'count', (select count(*) from public.story_characters where story_characters.story_id = stories.id),
      'recent', coalesce((
        select jsonb_agg(jsonb_build_object(
                           'id', recent.id, 'name', recent.name, 'role', recent.role,
                           'summary', coalesce(recent.sheet ->> 'summary', ''),
                           'updated_at', recent.updated_at)
                         order by recent.updated_at desc)
        from (select story_characters.id, story_characters.name, story_characters.role,
                     story_characters.sheet, story_characters.updated_at
              from public.story_characters where story_characters.story_id = stories.id
              order by story_characters.updated_at desc limit 5) as recent
      ), '[]'::jsonb))
  )
  into result
  from public.stories
  join public.story_plans as plans on plans.story_id = stories.id
  join public.categories on categories.id = stories.category_id
  where stories.id = target_story_id;
  return result;
end;
$$;


ALTER FUNCTION "public"."story_plan"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_plan"("story_slug" "text") IS 'The at-a-glance page of one of the caller''s stories: the story, its plan, acts, chapter numbers and cast (S1-E17-06, G10a).';



CREATE OR REPLACE FUNCTION "public"."story_plan_chapters"("plan_story_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    -- The words in the writer's current drafts, published or not (S1-E17-06).
    'words_written', coalesce(sum(chapters.word_count), 0),
    'chapter_count', count(*),
    'published_count', count(*) filter (where chapters.status = 'published'),
    'recent', coalesce((
      select jsonb_agg(recent_chapter order by recent_chapter ->> 'edited_at' desc)
      from (
        select jsonb_build_object(
          'code', latest.code, 'position', latest.position, 'title', latest.draft_title,
          'edited_at', coalesce(latest.draft_saved_at, latest.updated_at),
          'status', latest.status, 'scheduled_for', latest.scheduled_for,
          'published_at', latest.last_published_at,
          'planning_status', plans.planning_status
        ) as recent_chapter
        from public.chapters as latest
        left join public.chapter_plans as plans on plans.chapter_id = latest.id
        where latest.story_id = plan_story_id and latest.deleted_at is null
        order by coalesce(latest.draft_saved_at, latest.updated_at) desc
        limit 5
      ) as recent_rows
    ), '[]'::jsonb)
  )
  from public.chapters
  where chapters.story_id = plan_story_id and chapters.deleted_at is null;
$$;


ALTER FUNCTION "public"."story_plan_chapters"("plan_story_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_plan_chapters"("plan_story_id" "uuid") IS 'Internal: words written, chapter counts and the recently edited chapters of one story, with their status (S1-E17-06, G10a).';



CREATE OR REPLACE FUNCTION "public"."story_plan_visibility"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your settings.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  return jsonb_build_object(
    'outcome', 'ok',
    'areas', (select to_jsonb(story_plans.public_areas) from public.story_plans
              where story_plans.story_id = target_story_id),
    'items', coalesce((
      select jsonb_object_agg(item.id, jsonb_build_object('is_private', item.is_private,
          'show_from', (select chapters.code from public.chapters
                        where chapters.id = item.show_from and chapters.deleted_at is null)))
      from (
        select id, is_private, show_from_chapter_id as show_from from public.story_characters where story_id = target_story_id
        union all
        select id, is_private, null from public.story_character_relationships where story_id = target_story_id
        union all
        select id, is_private, null from public.story_bible_sections where story_id = target_story_id
        union all
        select id, is_private, show_from_chapter_id from public.story_bible_entries where story_id = target_story_id
        union all
        select id, is_private, show_from_chapter_id from public.story_events where story_id = target_story_id
      ) as item), '{}'::jsonb),
    'sheet_parts', coalesce((
      select jsonb_object_agg(characters.id, to_jsonb(characters.public_sheet_parts))
      from public.story_characters as characters where characters.story_id = target_story_id), '{}'::jsonb),
    'chapters', coalesce((
      select jsonb_agg(jsonb_build_object('code', chapters.code, 'position', chapters.position,
          'title', chapters.draft_title) order by chapters.position)
      from public.chapters
      where chapters.story_id = target_story_id and chapters.deleted_at is null), '[]'::jsonb));
end;
$$;


