CREATE OR REPLACE FUNCTION "public"."story_rating_fits_writer"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.rating in ('16_plus', '18_plus')
     and public.age_band_of(new.user_id) in ('under_13', '13_to_15') then
    raise exception 'A writer under 16 can rate a story All ages or 13+ only.'
      using errcode = 'check_violation', hint = 'rating_too_high_for_age';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."story_rating_fits_writer"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_rating_fits_writer"() IS 'Trigger: a writer under 16 rates a story All ages or 13+ only (Robert, 2 Nov 2026, 08:50).';



CREATE OR REPLACE FUNCTION "public"."story_rating_reasons_fit_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  -- Rule 1: below 16+ there is nothing to explain.
  if new.rating not in ('16_plus', '18_plus') then
    new.rating_reasons := '{}';
  -- Rule 2: an 18+ story always says why; with nothing ticked, sexual content.
  elsif new.rating = '18_plus' and cardinality(new.rating_reasons) = 0 then
    new.rating_reasons := '{sexual_content}';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."story_rating_reasons_fit_rating"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_rating_reasons_fit_rating"() IS 'Trigger: a story rated All ages or 13+ has no rating reasons; an 18+ story with none gets sexual_content (SPONSORS-f).';



CREATE OR REPLACE FUNCTION "public"."story_rating_reasons_from"("labels" "jsonb") RETURNS "public"."story_rating_reason"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when labels ->> 'rating' in ('16_plus', '18_plus') then coalesce((
      select array_agg(distinct reason::public.story_rating_reason order by reason::public.story_rating_reason)
      from jsonb_array_elements_text(coalesce(labels -> 'rating_reasons', '[]'::jsonb)) as reason), '{}')
    else '{}'::public.story_rating_reason[] end;
$$;


