CREATE OR REPLACE FUNCTION "public"."story_signals"() RETURNS TABLE("story_id" "uuid", "reads" double precision, "likes" double precision, "comments" double precision, "read_through" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with window_start as (
    select now() - make_interval(days => public.ranking_setting('ranking_window_days', 60)::integer) as since,
      public.ranking_setting('ranking_half_life_days', 7) as half_life
  ),
  readable as materialized (
    select * from public.readable_chapters_for_ranking()
  ),
  read_points as (
    select readable.story_id, sum(reads.total * power(0.5,
      ((now() at time zone 'Europe/Bucharest')::date - reads.read_on) / window_start.half_life)) as points
    from readable cross join window_start
    join public.chapter_reads as reads on reads.chapter_id = readable.id
    where reads.read_on >= (window_start.since at time zone 'Europe/Bucharest')::date
    group by readable.story_id
  ),
  like_points as (
    select readable.story_id, sum(power(0.5,
      extract(epoch from now() - likes.created_at) / 86400 / window_start.half_life)) as points
    from readable cross join window_start
    join public.chapter_likes as likes on likes.chapter_id = readable.id and likes.user_id <> readable.user_id
    join public.profiles on profiles.id = likes.user_id and profiles.deleted_at is null
    where likes.created_at >= window_start.since
    group by readable.story_id
  ),
  comment_points as (
    select readable.story_id, sum(power(0.5,
      extract(epoch from now() - comments.created_at) / 86400 / window_start.half_life)) as points
    from readable cross join window_start
    join public.comments on comments.chapter_id = readable.id and comments.user_id <> readable.user_id
      and comments.deleted_at is null
    where comments.created_at >= window_start.since
    group by readable.story_id
  ),
  chapter_ends as (
    select distinct on (readable.story_id) readable.story_id,
      first_value(readable.id) over (partition by readable.story_id order by readable.chapter_position) as first_id,
      last_value(readable.id) over (partition by readable.story_id order by readable.chapter_position
        rows between unbounded preceding and unbounded following) as last_id
    from readable
  ),
  through as (
    select chapter_ends.story_id,
      case when chapter_ends.first_id = chapter_ends.last_id then 0
           else least(1.0, coalesce(
             (select sum(total) from public.chapter_reads, window_start
              where chapter_id = chapter_ends.last_id and read_on >= (window_start.since at time zone 'Europe/Bucharest')::date)::double precision
             / nullif((select sum(total) from public.chapter_reads, window_start
              where chapter_id = chapter_ends.first_id and read_on >= (window_start.since at time zone 'Europe/Bucharest')::date), 0), 0))
      end as ratio
    from chapter_ends
  )
  select through.story_id,
    coalesce(read_points.points, 0), coalesce(like_points.points, 0),
    coalesce(comment_points.points, 0), through.ratio
  from through
  left join read_points on read_points.story_id = through.story_id
  left join like_points on like_points.story_id = through.story_id
  left join comment_points on comment_points.story_id = through.story_id;
$$;


ALTER FUNCTION "public"."story_signals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_signals"() IS 'Internal: each readable story''s decayed reads, likes, comments and read-through (S1-E5-03; QA-2d).';



CREATE OR REPLACE FUNCTION "public"."story_slug_for"("title" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  base text;
  random_part text := '';
  alphabet text := 'abcdefghijklmnopqrstuvwxyz0123456789';
begin
  -- Step 1: the title's web form, dashes between words, nothing else.
  base := regexp_replace(public.name_slug(title), '[^a-z0-9]+', '-', 'g');
  base := btrim(left(base, 60), '-');
  if base = '' then
    base := 'story';
  end if;
  -- Step 2: six random characters, so two stories with one title get two addresses.
  for position in 1..6 loop
    random_part := random_part || substr(alphabet, 1 + floor(random() * 36)::integer, 1);
  end loop;
  return base || '-' || random_part;
end;
$$;


ALTER FUNCTION "public"."story_slug_for"("title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_slug_for"("title" "text") IS 'A public address for a story title: its web form plus six random characters (S1-E3-01).';



CREATE OR REPLACE FUNCTION "public"."story_storyline"("story_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
begin
  -- Step 1: a signed-in writer and their own live story with its plan.
  if (select auth.uid()) is null then
    raise exception 'Sign in to see your storyline.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null or not exists (
    select 1 from public.story_plans where story_plans.story_id = target_story_id) then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the chapters, acts, characters and events.
  return jsonb_build_object(
    'outcome', 'ok',
    'title', (select stories.title from public.stories where stories.id = target_story_id),
    'chapters', public.storyline_chapters_json(target_story_id),
    'acts', coalesce((select jsonb_agg(jsonb_build_object('id', acts.id, 'name', acts.name,
        'position', acts.position) order by acts.position)
      from public.story_plan_acts as acts where acts.story_id = target_story_id), '[]'::jsonb),
    'characters', coalesce((select jsonb_agg(jsonb_build_object('id', cast_member.id, 'name', cast_member.name)
        order by lower(cast_member.name), cast_member.created_at)
      from public.story_characters as cast_member where cast_member.story_id = target_story_id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object('id', events.id, 'title', events.title,
        'display_date', events.display_date, 'sort_value', events.sort_value,
        'description', events.description) order by events.sort_value, events.created_at)
      from public.story_events as events where events.story_id = target_story_id), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."story_storyline"("story_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."story_storyline"("story_slug" "text") IS 'The caller''s chapters, acts, characters and timeline events of one story (S1-E17-19 to 22).';



CREATE OR REPLACE FUNCTION "public"."story_tag_ranks"("story_slug" "text") RETURNS TABLE("tag_name" "text", "tag_rank" integer, "stories_in_tag" integer, "is_picked" boolean, "is_badge" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  story public.stories;
  has_score boolean;
  smallest_tag integer := public.ranking_setting('rank_badge_min_stories', 5)::integer;
begin
  -- Step 1: the story, if this reader may see it (the owner always; others as on its page).
  select * into story from public.stories where stories.slug = story_slug and stories.deleted_at is null;
  if not found then
    return;
  end if;
  if story.user_id is distinct from (select auth.uid()) and not (
      public.story_has_readable_chapter(story.id) and public.rating_allows(story.rating)
      and not public.is_moderated_away('story', story.id) and not public.is_blocked_with(story.user_id)) then
    return;
  end if;
  has_score := exists (select 1 from public.story_scores where story_scores.story_id = story.id and story_scores.score > 0);

  -- Step 2: each approved tag's rank, kept only when it means something; then the badges.
  return query
  with tag_rows as (
    select tags.id, tags.name, story_tags.created_at,
      array_position(story.rank_badge_tag_ids, tags.id) as pick_position
    from public.story_tags join public.tags on tags.id = story_tags.tag_id
    where story_tags.story_id = story.id and tags.status = 'approved'
  ),
  ranked as (
    select tag_rows.*, place.tag_rank, place.stories_in_tag
    from tag_rows
    -- A story without a score gets no rank at all (see the header).
    left join lateral public.story_rank_in_tag(story.id, tag_rows.name) as place on has_score
  ),
  shown as (
    select ranked.*,
      (ranked.tag_rank is not null and ranked.stories_in_tag >= smallest_tag) as has_rank
    from ranked
  ),
  badge_order as (
    select shown.id, row_number() over (order by
        shown.pick_position nulls last, shown.tag_rank, shown.stories_in_tag desc, shown.name) as position
    from shown
    where shown.has_rank and (story.rank_badge_tag_ids is null or shown.pick_position is not null)
  )
  select shown.name,
    case when shown.has_rank then shown.tag_rank end,
    case when shown.has_rank then shown.stories_in_tag end,
    shown.pick_position is not null,
    coalesce(badge_order.position <= 3, false)
  from shown left join badge_order on badge_order.id = shown.id
  order by shown.created_at;
end;
$$;


