CREATE OR REPLACE FUNCTION "public"."submit_appeal"("statement_reference" "text", "explanation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  statement public.statements_of_reasons;
  clean_explanation text := btrim(coalesce(explanation, ''));
  new_reference text;
begin
  -- Step 1: their own statement, within six months (DSA art. 20(1)).
  if caller_id is null then
    raise exception 'Log in to appeal.' using errcode = 'insufficient_privilege';
  end if;
  select * into statement from public.statements_of_reasons
  where reference = upper(btrim(statement_reference)) and user_id = caller_id;
  if statement.id is null then
    raise exception 'There is no such decision on your account.' using errcode = 'no_data_found';
  end if;
  if statement.appeal_until <= now() then
    raise exception 'The six months to appeal this decision are over.' using errcode = 'check_violation';
  end if;
  -- Step 2: the explanation, and one open appeal at a time.
  if clean_explanation = '' or char_length(clean_explanation) > 4000 then
    raise exception 'Explain why the decision is wrong, in at most 4,000 characters.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.appeals where appeals.statement_id = statement.id and appeals.status = 'open') then
    raise exception 'You already appealed this decision; we''ll tell you the outcome.' using errcode = 'check_violation';
  end if;
  -- Step 3: the limit (S1-E10-12), then the appeal.
  perform public.take_rate_limit('appeal');
  new_reference := 'A-' || lpad(nextval('public.appeal_reference_seq')::text, 6, '0');
  insert into public.appeals (reference, user_id, statement_id, explanation, original_decider_user_id)
  values (new_reference, caller_id, statement.id, clean_explanation, public.decider_of_statement(statement));
  return jsonb_build_object('reference', new_reference);
end;
$$;


ALTER FUNCTION "public"."submit_appeal"("statement_reference" "text", "explanation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_appeal"("statement_reference" "text", "explanation" "text") IS 'The person appeals a decision on one of their statements of reasons within six months (S1-E10-07).';



CREATE OR REPLACE FUNCTION "public"."submit_contact_ticket"("payload" "text", "signature" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fields jsonb;
  sender_email text;
  sender_language text;
  sender_account_id uuid;
  new_ticket public.support_tickets;
begin
  -- Step 1: only a fresh payload our server signed.
  if not public.support_payload_is_signed(payload, signature) then
    raise exception 'This message didn''t come through the form.' using errcode = 'insufficient_privilege';
  end if;
  fields := payload::jsonb;
  if (fields ->> 'sentAt')::timestamptz < now() - interval '15 minutes' then
    raise exception 'This message is too old to save.' using errcode = 'insufficient_privilege';
  end if;
  -- Step 2: who wrote, and in which language.
  sender_email := btrim(fields ->> 'email');
  sender_language := case when fields ->> 'language' = 'en' then 'en' else 'ro' end;
  sender_account_id := public.account_for_email(sender_email);
  -- Step 3: the ticket, its first message and the first history line.
  insert into public.support_tickets (requester_user_id, requester_email, language, subject, channel, category)
  values (sender_account_id, sender_email, sender_language,
    public.contact_topic_subject(fields ->> 'topic', sender_language), 'contact_form',
    case when fields ->> 'topic' = 'account' then 'account'::public.support_ticket_category else 'other' end)
  returning * into new_ticket;
  insert into public.support_ticket_messages (ticket_id, kind, author_user_id, body, channel)
  values (new_ticket.id, 'from_requester', sender_account_id, public.clean_mail_text(fields ->> 'message', 4000), 'contact_form');
  perform public.record_support_event(new_ticket.id, 'created', null,
    jsonb_build_object('channel', 'contact_form', 'topic', fields ->> 'topic'));
  return new_ticket.number;
end;
$$;


ALTER FUNCTION "public"."submit_contact_ticket"("payload" "text", "signature" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_contact_ticket"("payload" "text", "signature" "text") IS 'Saves a Contact us message, signed by our server, as a support ticket (S1-E11-13 criterion 1).';



CREATE OR REPLACE FUNCTION "public"."submit_public_notice"("payload" "text", "signature" "text") RETURNS TABLE("notice_reference" "text", "received_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fields jsonb;
  notice_kind text;
  matched record;
  new_notice public.public_notices;
  new_case_id uuid;
begin
  -- Step 1: only a payload our server signed.
  if not public.public_notice_payload_is_signed(payload, signature) then
    raise exception 'This notice didn''t come through the form.' using errcode = 'insufficient_privilege';
  end if;
  fields := payload::jsonb;
  notice_kind := fields ->> 'kind';
  -- Step 2: what the address points to, if anything.
  select * into matched from public.item_for_public_address(fields ->> 'contentUrl') limit 1;
  -- Step 3: the row; the table's constraints refuse a notice missing what DSA art. 16 asks for.
  insert into public.public_notices (kind, reason, content_url, item_type, item_id, owner_user_id,
    explanation, notifier_name, notifier_email, good_faith_confirmed, authority_name, order_reference,
    copy_source_title, copy_source_author, copy_source_reference, copy_source_passage,
    language, reference)
  values (
    notice_kind,
    case when notice_kind = 'notice' then (fields ->> 'reason')::public.report_reason end,
    btrim(fields ->> 'contentUrl'),
    matched.item_type, matched.item_id, matched.owner_user_id,
    btrim(fields ->> 'explanation'),
    nullif(btrim(fields ->> 'notifierName'), ''),
    nullif(lower(btrim(fields ->> 'notifierEmail')), ''),
    coalesce((fields ->> 'goodFaith')::boolean, false),
    nullif(btrim(fields ->> 'authorityName'), ''),
    nullif(btrim(fields ->> 'orderReference'), ''),
    nullif(btrim(fields -> 'copySource' ->> 'title'), ''),
    nullif(btrim(fields -> 'copySource' ->> 'author'), ''),
    nullif(btrim(fields -> 'copySource' ->> 'reference'), ''),
    nullif(btrim(fields -> 'copySource' ->> 'passage'), ''),
    coalesce(fields ->> 'language', 'ro'),
    public.next_notice_reference(notice_kind))
  returning * into new_notice;
  -- Step 4: the case, when the address matched something we host.
  if new_notice.item_id is not null then
    new_case_id := public.attach_notice_to_case(new_notice);
    update public.public_notices set case_id = new_case_id where id = new_notice.id;
  end if;
  -- Step 5: an order alerts whoever is on call at once (logged; the phone comes with S1-E10-09).
  if notice_kind = 'removal_order' then
    insert into public.on_call_alerts (kind, case_id, notice_id) values ('removal_order', new_case_id, new_notice.id);
  end if;
  return query select new_notice.reference, new_notice.received_at;
end;
$$;


