CREATE OR REPLACE FUNCTION "public"."support_email_worker_mark_sent"("worker_key" "text", "email_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  marked integer;
begin
  if not public.email_worker_key_matches(worker_key) then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  update public.support_ticket_emails set sent_at = now()
  where id = any(email_ids) and sent_at is null;
  get diagnostics marked = row_count;
  return marked;
end;
$$;


