CREATE OR REPLACE FUNCTION "public"."unsubscribe_from_emails"("unsubscribe_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_id uuid;
begin
  -- Step 1: whose key it is.
  select keys.user_id into owner_id from public.email_unsubscribe_keys as keys
  where keys.unsubscribe_key = lower(btrim(coalesce(unsubscribe_from_emails.unsubscribe_key, '')));
  if owner_id is null then
    return false;
  end if;
  -- Step 2: every optional notification email off, and message emails off.
  insert into public.notification_email_settings (user_id, kind, delivery)
  select owner_id, listed.kind, 'off'
  from unnest(array['comment_reply', 'new_chapter', 'comment_on_chapter', 'new_follower']::public.notification_kind[])
    as listed (kind)
  on conflict on constraint notification_email_settings_one_per_kind do update set delivery = 'off';
  update public.profiles set message_emails_on = false where profiles.id = owner_id;
  -- Step 3: emails already waiting stop too, except the required ones.
  update public.email_outbox set sent_at = now()
  where email_outbox.user_id = owner_id and email_outbox.sent_at is null and email_outbox.delivery <> 'required';
  return true;
end;
$$;


ALTER FUNCTION "public"."unsubscribe_from_emails"("unsubscribe_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."unsubscribe_from_emails"("unsubscribe_key" "text") IS 'One-click unsubscribe: every optional notification email and message emails off (S1-E7-02, IDEAS-2 idea 6).';



CREATE OR REPLACE FUNCTION "public"."update_bible_entry"("entry_id" "uuid", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_entry public.story_bible_entries;
  target_section public.story_bible_sections;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer, their own entry and only known changes.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your story bible.' using errcode = 'insufficient_privilege';
  end if;
  target_entry := public.my_bible_entry(entry_id);
  if target_entry.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(changes, '{}'::jsonb)) as change_key
             where change_key not in ('title', 'tags', 'body', 'section_id')) then
    raise exception 'Unknown change to an entry.' using errcode = 'check_violation', hint = 'unknown_change';
  end if;
  -- Step 2: a move stays inside the same story.
  if changes ? 'section_id' then
    target_section := public.my_bible_section((changes ->> 'section_id')::uuid);
    if target_section.id is null or target_section.story_id <> target_entry.story_id then
      raise exception 'An entry moves only to a section of its own story.' using errcode = 'check_violation', hint = 'other_story';
    end if;
  end if;
  -- Step 3: change only what was given; the checks refuse the rest.
  update public.story_bible_entries set
    title = case when changes ? 'title' then btrim(public.normalise_romanian_letters(changes ->> 'title')) else title end,
    tags = case when changes ? 'tags' then public.clean_bible_tags(changes -> 'tags') else tags end,
    body = case when changes ? 'body' then public.check_bible_text(changes ->> 'body') else body end,
    section_id = coalesce(target_section.id, section_id)
  where story_bible_entries.id = target_entry.id
  returning updated_at into saved_at;
  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


ALTER FUNCTION "public"."update_bible_entry"("entry_id" "uuid", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_bible_entry"("entry_id" "uuid", "changes" "jsonb") IS 'Changes one of the caller''s bible entries: title, tags, text or section (S1-E17-18).';



CREATE OR REPLACE FUNCTION "public"."update_chapter_plan"("chapter_code" "text", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_plan public.chapter_plans;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer, their own chapter and only known changes.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your chapter plan.' using errcode = 'insufficient_privilege';
  end if;
  target_plan := public.my_chapter_plan(chapter_code);
  if target_plan.chapter_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(changes, '{}'::jsonb)) as change_key
             where change_key not in ('kind', 'planning_status', 'pov_character_id', 'pov_is_narrator', 'act_id',
                                      'word_target',
                                      'world_date', 'world_sort', 'location', 'summary')) then
    raise exception 'Unknown change to a chapter plan.' using errcode = 'check_violation', hint = 'unknown_change';
  end if;
  -- Step 2: numbers must be numbers (or null, which clears them).
  if (changes ? 'word_target' and jsonb_typeof(changes -> 'word_target') not in ('number', 'null'))
     or (changes ? 'world_sort' and jsonb_typeof(changes -> 'world_sort') not in ('number', 'null')) then
    raise exception 'A target or sort value is a number.' using errcode = 'check_violation', hint = 'bad_number';
  end if;
  -- Step 2b (G10c2): the Narrator is yes or no, never anything else.
  if changes ? 'pov_is_narrator' and jsonb_typeof(changes -> 'pov_is_narrator') <> 'boolean' then
    raise exception 'The Narrator is true or false.' using errcode = 'check_violation', hint = 'bad_narrator';
  end if;
  -- Step 3: change only what was given; the helpers and the table's checks refuse the rest.
  update public.chapter_plans set
    kind = case when changes ? 'kind' then changes ->> 'kind' else kind end,
    planning_status = case when changes ? 'planning_status' then changes ->> 'planning_status' else planning_status end,
    -- One teller at a time (G10c2): picking a character takes the Narrator off, and picking the
    -- Narrator clears the character, unless the same call says otherwise (the table's check then
    -- refuses a chapter told by both).
    pov_character_id = case
      when changes ? 'pov_character_id'
        then public.character_of_story(target_plan.story_id, changes ->> 'pov_character_id')
      when (changes ->> 'pov_is_narrator')::boolean then null
      else pov_character_id end,
    pov_is_narrator = case
      when changes ? 'pov_is_narrator' then (changes ->> 'pov_is_narrator')::boolean
      when changes ->> 'pov_character_id' is not null then false
      else pov_is_narrator end,
    act_id = case when changes ? 'act_id' then public.act_of_story(target_plan.story_id, changes ->> 'act_id') else act_id end,
    word_target = case when changes ? 'word_target' then (changes ->> 'word_target')::numeric::integer else word_target end,
    world_date = case when changes ? 'world_date' then public.plan_text(changes ->> 'world_date') else world_date end,
    world_sort = case when changes ? 'world_sort' then (changes ->> 'world_sort')::numeric else world_sort end,
    location = case when changes ? 'location' then public.plan_text(changes ->> 'location') else location end,
    summary = case when changes ? 'summary' then public.plan_text(changes ->> 'summary') else summary end
  where chapter_plans.chapter_id = target_plan.chapter_id
  returning updated_at into saved_at;
  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


