COMMENT ON FUNCTION "public"."update_chapter_plan"("chapter_code" "text", "changes" "jsonb") IS 'Changes the planning of one of the caller''s chapters (S1-E17-24).';



CREATE OR REPLACE FUNCTION "public"."update_chapter_scene"("scene_id" "uuid", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_scene public.chapter_scenes;
  saved_at timestamptz;
begin
