COMMENT ON FUNCTION "public"."update_published_chapter"("chapter_code" "text") IS 'Readers get the writer''s saved edits ("Edited on"): {outcome: ok | not_active | not_found | empty | wrong_state} (S1-E3-03, Q10).';



CREATE OR REPLACE FUNCTION "public"."update_reading_list"("list_id" "uuid", "new_name" "text" DEFAULT NULL::"text", "make_public" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target public.reading_lists;
  clean_name text;
  will_be_public boolean;
begin
  -- Step 1: signed in, and one change to this person's lists at a time.
  if caller_id is null then
    raise exception 'Log in to change a reading list.' using errcode = 'insufficient_privilege';
  end if;
  perform pg_advisory_xact_lock(hashtext('reading_lists:' || caller_id::text));
  select * into target from public.reading_lists
  where id = list_id and user_id = caller_id and deleted_at is null;
  if not found then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the name, when it changes: valid, and not another of the caller's lists' (a list may
  -- change its own capitals).
  clean_name := case when new_name is null then target.name else public.clean_reading_list_name(new_name) end;
  if exists (select 1 from public.reading_lists
             where user_id = caller_id and deleted_at is null and id <> target.id
               and lower(name) = lower(clean_name)) then
    raise exception 'You already have a list with that name.'
      using errcode = 'check_violation', hint = 'name_taken';
  end if;
  -- Step 3: a public list needs an active account.
  will_be_public := coalesce(make_public, target.is_public);
  if will_be_public and (make_public is true or new_name is not null) and not public.is_active_member() then
    raise exception 'Your account can''t make a list public right now.'
      using errcode = 'insufficient_privilege', hint = 'not_active';
  end if;
  -- Step 4: save.
  update public.reading_lists set name = clean_name, is_public = will_be_public where id = target.id;
  return jsonb_build_object('outcome', 'ok', 'name', clean_name, 'is_public', will_be_public);
end;
$$;


ALTER FUNCTION "public"."update_reading_list"("list_id" "uuid", "new_name" "text", "make_public" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_reading_list"("list_id" "uuid", "new_name" "text", "make_public" boolean) IS 'Renames one of the caller''s reading lists or makes it public or private (GAPS-6).';



CREATE OR REPLACE FUNCTION "public"."update_space"("slug" "text", "name" "text", "description" "text", "rules" "text" DEFAULT ''::"text", "posting" "public"."space_posting" DEFAULT NULL::"public"."space_posting", "joining" "public"."space_joining" DEFAULT NULL::"public"."space_joining", "readers" "public"."space_readers" DEFAULT NULL::"public"."space_readers", "banner" "public"."space_banner" DEFAULT NULL::"public"."space_banner") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  space public.spaces := public.space_for_power(update_space.slug, 'settings');
  before_change public.spaces := space;
  clean_name text := public.check_space_text(name, 'name');
begin
  -- Step 1: a new name is still only once.
  if exists (select 1 from public.spaces
             where spaces.name_key = public.space_name_key(clean_name) and spaces.deleted_at is null
               and spaces.id <> space.id) then
    raise exception 'Another space has this name.' using errcode = 'check_violation', hint = 'name:taken';
  end if;
  -- Step 2: the change; a 16+ space stays read by everybody (S1-E8-06 criterion 5).
  update public.spaces set
    name = clean_name,
    name_key = public.space_name_key(clean_name),
    description = public.check_space_text(update_space.description, 'description'),
    rules = public.check_space_text(update_space.rules, 'rules'),
    posting = coalesce(update_space.posting, spaces.posting),
    joining = coalesce(update_space.joining, spaces.joining),
    readers = case when spaces.age_group = 'under_16' then coalesce(update_space.readers, spaces.readers) else 'everybody' end,
    banner = coalesce(update_space.banner, spaces.banner)
  where spaces.id = space.id
  returning * into space;
  perform public.write_space_forum_names(space.id, space.name);
  -- Step 3: the log, with what changed.
  perform public.log_space_action(space, 'settings_changed', null, null, null, jsonb_build_object(
    'before', jsonb_build_object('name', before_change.name, 'posting', before_change.posting,
                                 'joining', before_change.joining, 'readers', before_change.readers,
                                 'banner', before_change.banner),
    'after', jsonb_build_object('name', space.name, 'posting', space.posting, 'joining', space.joining,
                                'readers', space.readers, 'banner', space.banner)));
  return public.space_json(space);
end;
$$;


