COMMENT ON FUNCTION "public"."update_space"("slug" "text", "name" "text", "description" "text", "rules" "text", "posting" "public"."space_posting", "joining" "public"."space_joining", "readers" "public"."space_readers", "banner" "public"."space_banner") IS 'Changes a space''s name, description, rules and settings, for the owner and moderators with the settings power; logged (S1-E8-06, S1-E8-07).';



CREATE OR REPLACE FUNCTION "public"."update_story_character"("character_id" "uuid", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_character public.story_characters;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer and their own character.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your characters.' using errcode = 'insufficient_privilege';
  end if;
  target_character := public.my_story_character(character_id);
  if target_character.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  -- Step 2: the texts use only known fields and stay within bounds.
  perform public.check_character_texts(coalesce(changes -> 'sheet', '{}'::jsonb), public.character_sheet_keys());
  perform public.check_custom_value_keys(target_character.story_id, coalesce(changes -> 'custom', '{}'::jsonb));

  -- Step 3: change only what was given; the table's checks refuse the rest (an unknown gender
  -- among them). An empty gender means "not set".
  update public.story_characters set
    name = coalesce(btrim(changes ->> 'name'), name),
    role = coalesce(changes ->> 'role', role),
    gender = case when changes ? 'gender' then nullif(changes ->> 'gender', '') else gender end,
    sheet = sheet || coalesce(changes -> 'sheet', '{}'::jsonb),
    custom_values = custom_values || coalesce(changes -> 'custom', '{}'::jsonb),
    first_appearance_chapter_id = case when changes ? 'first_appearance'
      then public.chapter_of_story(target_character.story_id, changes ->> 'first_appearance')
      else first_appearance_chapter_id end,
    picture_alt = coalesce(btrim(changes ->> 'picture_alt'), picture_alt)
  where story_characters.id = target_character.id
  returning updated_at into saved_at;
  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


ALTER FUNCTION "public"."update_story_character"("character_id" "uuid", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_story_character"("character_id" "uuid", "changes" "jsonb") IS 'Changes one of the caller''s characters: name, role, gender, sheet text, custom values, first appearance or picture alt text (S1-E17-08 to S1-E17-11; GAPS-3).';



CREATE OR REPLACE FUNCTION "public"."update_story_event"("event_id" "uuid", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_event public.story_events;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer, their own event and only known changes.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your timeline.' using errcode = 'insufficient_privilege';
  end if;
  target_event := public.my_story_event(event_id);
  if target_event.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(changes, '{}'::jsonb)) as change_key
             where change_key not in ('title', 'display_date', 'sort_value', 'description')) then
    raise exception 'Unknown change to an event.' using errcode = 'check_violation', hint = 'unknown_change';
  end if;
  -- Step 2: the sort value stays a number (it can't be cleared: the timeline needs it).
  if changes ? 'sort_value' and jsonb_typeof(changes -> 'sort_value') <> 'number' then
    raise exception 'An event sorts by a number.' using errcode = 'check_violation', hint = 'bad_number';
  end if;
  -- Step 3: change only what was given.
  update public.story_events set
    title = case when changes ? 'title' then public.plan_text(changes ->> 'title') else title end,
    display_date = case when changes ? 'display_date' then public.plan_text(changes ->> 'display_date') else display_date end,
    sort_value = case when changes ? 'sort_value' then (changes ->> 'sort_value')::numeric else sort_value end,
    description = case when changes ? 'description' then public.plan_text(changes ->> 'description') else description end
  where story_events.id = target_event.id
  returning updated_at into saved_at;
  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


ALTER FUNCTION "public"."update_story_event"("event_id" "uuid", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_story_event"("event_id" "uuid", "changes" "jsonb") IS 'Changes one of the caller''s timeline events (S1-E17-20).';



CREATE OR REPLACE FUNCTION "public"."update_story_idea"("idea_id" "uuid", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_idea public.story_ideas;
  saved_done_at timestamptz;
begin
  -- Step 1: a signed-in writer, their own item and only known changes.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your notes.' using errcode = 'insufficient_privilege';
  end if;
  target_idea := public.my_story_idea(idea_id);
  if target_idea.id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(changes, '{}'::jsonb)) as change_key
             where change_key not in ('kind', 'body', 'outcome', 'is_done')) then
    raise exception 'Unknown change to a note.' using errcode = 'check_violation', hint = 'unknown_change';
  end if;
  if changes ? 'is_done' and jsonb_typeof(changes -> 'is_done') <> 'boolean' then
    raise exception 'Done is true or false.' using errcode = 'check_violation', hint = 'bad_flag';
  end if;
  -- Step 2: change only what was given. Ticking done keeps the first date it was done.
  update public.story_ideas set
    kind = case when changes ? 'kind' then changes ->> 'kind' else kind end,
    body = case when changes ? 'body' then public.plan_text(changes ->> 'body') else body end,
    outcome = case when changes ? 'outcome' then public.plan_text(changes ->> 'outcome') else outcome end,
    done_at = case
      when not changes ? 'is_done' then done_at
      when (changes ->> 'is_done')::boolean then coalesce(done_at, now())
      else null end
  where story_ideas.id = target_idea.id
  returning done_at into saved_done_at;
  return jsonb_build_object('outcome', 'ok', 'done_at', saved_done_at);
end;
$$;


