COMMENT ON FUNCTION "public"."update_story_idea"("idea_id" "uuid", "changes" "jsonb") IS 'Changes one of the caller''s questions or ideas: type, text, outcome or done (S1-E17-28).';



CREATE OR REPLACE FUNCTION "public"."update_story_marketing"("story_slug" "text", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_story_id uuid;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer, their own planned story and only known changes.
  if (select auth.uid()) is null then
    raise exception 'Sign in to change your marketing notes.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_planned_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(changes, '{}'::jsonb)) as change_key
             where change_key not in ('back_cover_blurb', 'comparable_titles', 'hooks_keywords',
                                      'query_pitch', 'launch_notes')) then
    raise exception 'Unknown change to marketing notes.' using errcode = 'check_violation', hint = 'unknown_change';
  end if;
  -- Step 2: the row, made empty on the first save, then only the fields given.
  insert into public.story_marketing (story_id, user_id) values (target_story_id, (select auth.uid()))
  on conflict (story_id) do nothing;
  update public.story_marketing set
    back_cover_blurb = case when changes ? 'back_cover_blurb' then public.plan_text(changes ->> 'back_cover_blurb') else back_cover_blurb end,
    comparable_titles = case when changes ? 'comparable_titles' then public.plan_text(changes ->> 'comparable_titles') else comparable_titles end,
    hooks_keywords = case when changes ? 'hooks_keywords' then public.plan_text(changes ->> 'hooks_keywords') else hooks_keywords end,
    query_pitch = case when changes ? 'query_pitch' then public.plan_text(changes ->> 'query_pitch') else query_pitch end,
    launch_notes = case when changes ? 'launch_notes' then public.plan_text(changes ->> 'launch_notes') else launch_notes end
  where story_marketing.story_id = target_story_id
  returning updated_at into saved_at;
  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


ALTER FUNCTION "public"."update_story_marketing"("story_slug" "text", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_story_marketing"("story_slug" "text", "changes" "jsonb") IS 'Changes the caller''s marketing notes on one story (S1-E17-29).';



CREATE OR REPLACE FUNCTION "public"."update_story_plan"("story_slug" "text", "changes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  target_story_id uuid;
  saved_at timestamptz;
begin
  -- Step 1: a signed-in writer and their own live story. A plan is private, so a read-only
  -- account may still plan; the account gate guards what others can see, not the writer's notes.
  if caller_id is null then
    raise exception 'Sign in to change your plan.' using errcode = 'insufficient_privilege';
  end if;
  target_story_id := public.my_live_story_id(story_slug);
  if target_story_id is null then
    return jsonb_build_object('outcome', 'not_found');
  end if;

  -- Step 2: change only the fields given; the text is trimmed, and the table's checks refuse
  -- anything out of range.
  update public.story_plans set
    logline = coalesce(btrim(changes ->> 'logline'), logline),
    series_name = coalesce(btrim(changes ->> 'series_name'), series_name),
    word_target = coalesce((changes ->> 'word_target')::integer, word_target),
    writing_status = coalesce(changes ->> 'writing_status', writing_status),
    publishing_route = coalesce(changes ->> 'publishing_route', publishing_route),
    linked_project_label = coalesce(btrim(changes ->> 'linked_project_label'), linked_project_label),
    linked_project_url = coalesce(btrim(changes ->> 'linked_project_url'), linked_project_url)
  where story_plans.story_id = target_story_id
  returning updated_at into saved_at;

  return jsonb_build_object('outcome', 'ok', 'updated_at', saved_at);
end;
$$;


ALTER FUNCTION "public"."update_story_plan"("story_slug" "text", "changes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_story_plan"("story_slug" "text", "changes" "jsonb") IS 'Changes the plan''s own fields of one of the caller''s stories: logline, series, word target, writing status, publishing route and linked project (S1-E17-03, S1-E17-04).';



CREATE OR REPLACE FUNCTION "public"."use_platform_invite"("code" "text", "new_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  used public.invites;
begin
  -- Step 1: take a place, only if the invite is a live platform invite with a place left.
  update public.invites
    set use_count = use_count + 1
    where invites.code_hash = public.invite_code_hash(code)
      and invites.purpose = 'platform'
      and invites.revoked_at is null
      and invites.expires_at > now()
      and invites.use_count < invites.max_uses
    returning * into used;
  if used.id is null then
    raise exception 'This invitation is not valid any more.' using errcode = 'check_violation';
  end if;

  -- Step 2: the new account says it used a place. target_user_id is whose invite it is.
  insert into public.audit_log (user_id, actor, action, target_type, target_id, target_user_id, after_values)
  values (
    new_user_id, 'person', 'invite.redeemed', 'invites', used.id::text, used.user_id,
    jsonb_build_object('place', used.use_count, 'admits', used.max_uses)
  );

  -- Step 3: the last place closes the invite; nobody chose that, so the system is the actor.
  if used.use_count >= used.max_uses then
    insert into public.audit_log (user_id, actor, action, target_type, target_id, target_user_id, reason, after_values)
    values (
      null, 'system', 'invite.used_up', 'invites', used.id::text, used.user_id,
      'Automatic: the last place was taken at sign-up.',
      jsonb_build_object('admits', used.max_uses, 'note', used.note)
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."use_platform_invite"("code" "text", "new_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_platform_invite"("code" "text", "new_user_id" "uuid") IS 'Internal: takes one place on a platform invite in the sign-up transaction, or refuses; logs invite.redeemed and invite.used_up (S1-E2-01, S1-E11-17).';



CREATE OR REPLACE FUNCTION "public"."use_sign_up_invite"("code" "text", "new_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  used public.invites;
begin
  -- Step 1: a platform invite is used the way it always was.
  if exists (select 1 from public.invites
             where invites.code_hash = public.invite_code_hash(code) and invites.purpose = 'platform') then
    perform public.use_platform_invite(code, new_user_id);
    return;
  end if;
  -- Step 2: otherwise only a working class code, in a class that is open, will do.
  if not public.class_invite_opens_sign_up(code) then
    raise exception 'This invitation is not valid any more.' using errcode = 'check_violation';
  end if;
  update public.invites set use_count = use_count + 1
  where invites.code_hash = public.invite_code_hash(code) and invites.purpose = 'class_space'
    and invites.revoked_at is null and invites.expires_at > now() and invites.use_count < invites.max_uses
  returning * into used;
  if used.id is null then
    raise exception 'This invitation is not valid any more.' using errcode = 'check_violation';
  end if;
  -- Step 3: a member of the class straight away, logged as joining with the code is.
  insert into public.space_members (user_id, space_id, status, joined_at)
  values (new_user_id, used.space_id, 'active', now())
  on conflict (space_id, user_id) do update set status = 'active', joined_at = now();
  insert into public.space_moderation_log (user_id, space_id, action, target_user_id, details, by_platform)
  values (new_user_id, used.space_id, 'member_joined', new_user_id,
          jsonb_build_object('at_sign_up', true), false);
  -- Step 4: the audit log names the code that let the account in, as for a platform invite.
  insert into public.audit_log (user_id, actor, action, target_type, target_id, target_user_id, after_values)
  values (new_user_id, 'person', 'invite.redeemed', 'invites', used.id::text, used.user_id,
          jsonb_build_object('purpose', 'class_space', 'place', used.use_count, 'admits', used.max_uses));
end;
$$;


