CREATE OR REPLACE FUNCTION "public"."verified_signup_country"("token" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  parts text[] := string_to_array(coalesce(token, ''), '.');
  secret text;
  issued_at bigint;
begin
  -- Step 1: the shape: version, country, time in seconds, 64-character signature.
  if array_length(parts, 1) <> 4 or parts[1] <> 'v1' or parts[2] !~ '^[A-Z]{2}$'
    or parts[3] !~ '^\d{1,12}$' or parts[4] !~ '^[0-9a-f]{64}$' then
    return null;
  end if;
  -- Step 2: at most 10 minutes old (and not from the future, beyond a minute of clock drift).
  issued_at := parts[3]::bigint;
  if issued_at < extract(epoch from now())::bigint - 600 or issued_at > extract(epoch from now())::bigint + 60 then
    return null;
  end if;
  -- Step 3: the signature, with the secret from Vault; without the secret nothing is trusted.
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'signup_context_secret';
  if secret is null or secret = '' then
    return null;
  end if;
  if encode(extensions.hmac(parts[1] || '.' || parts[2] || '.' || parts[3], secret, 'sha256'), 'hex') <> parts[4] then
    return null;
  end if;
  return parts[2];
end;
$_$;


ALTER FUNCTION "public"."verified_signup_country"("token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verified_signup_country"("token" "text") IS 'Internal: the country in a genuine sign-up token at most 10 minutes old, else null (S1-E2-10, Q6a).';



CREATE OR REPLACE FUNCTION "public"."verified_signup_ips"("token" "text") RETURNS TABLE("ip_scrambled" "text", "ip_period" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  parts text[] := string_to_array(coalesce(token, ''), '.');
  secret text;
  issued_at bigint;
begin
  -- Step 1: the shape: version, two values with their months, the time, the signature.
  if array_length(parts, 1) is distinct from 7 or parts[1] <> 'ip1'
    or parts[2] !~ '^[0-9a-f]{64}$' or parts[3] !~ '^\d{4}-\d{2}$'
    or parts[4] !~ '^[0-9a-f]{64}$' or parts[5] !~ '^\d{4}-\d{2}$'
    or parts[6] !~ '^\d{1,12}$' or parts[7] !~ '^[0-9a-f]{64}$' then
    return;
  end if;
  -- Step 2: at most 10 minutes old, like the country token (S1-E2-10).
  issued_at := parts[6]::bigint;
  if issued_at < extract(epoch from now())::bigint - 600 or issued_at > extract(epoch from now())::bigint + 60 then
    return;
  end if;
  -- Step 3: the signature, with the secret from Vault; without it nothing is trusted.
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'signup_context_secret';
  if secret is null or secret = '' then
    return;
  end if;
  if encode(extensions.hmac(array_to_string(parts[1:6], '.'), secret, 'sha256'), 'hex') <> parts[7] then
    return;
  end if;
  return query values (parts[2], parts[3]), (parts[4], parts[5]);
end;
$_$;


ALTER FUNCTION "public"."verified_signup_ips"("token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verified_signup_ips"("token" "text") IS 'Internal: the scrambled IP values in a genuine sign-up IP token at most 10 minutes old (part f2).';



CREATE OR REPLACE FUNCTION "public"."verify_certificate"("code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  clean_code text := public.clean_certificate_code(code);
  target public.certificates;
begin
  select * into target from public.certificates where certificates.code = clean_code;
  if target.id is not null then
    return jsonb_build_object('status', public.certificate_status(target),
      'programme_name', target.programme_name, 'result', target.result,
      'school_name', target.school_name, 'signed_at', target.signed_at);
  end if;
  if exists (select 1 from public.retired_certificate_codes where retired_certificate_codes.code = clean_code) then
    return jsonb_build_object('status', 'retired');
  end if;
  return jsonb_build_object('status', 'unknown');
end;
$$;


