    "withdrawn_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "disqualified_at" timestamp with time zone,
    "disqualified_by_user_id" "uuid",
    "statement_id" "uuid",
    "award" "text",
    "prize_sent_at" timestamp with time zone,
    "prize_parent_consent" boolean DEFAULT false NOT NULL,
    CONSTRAINT "contest_entries_award_is_known" CHECK ((("award" IS NULL) OR ("award" = ANY (ARRAY['winner'::"text", 'finalist'::"text"])))),
    CONSTRAINT "contest_entries_disqualified_has_a_time" CHECK ((("status" = 'disqualified'::"text") = ("disqualified_at" IS NOT NULL))),
    CONSTRAINT "contest_entries_prize_only_for_winners" CHECK ((("prize_sent_at" IS NULL) OR ("award" = 'winner'::"text"))),
    CONSTRAINT "contest_entries_status_is_known" CHECK (("status" = ANY (ARRAY['valid'::"text", 'withdrawn'::"text", 'disqualified'::"text"]))),
    CONSTRAINT "contest_entries_withdrawn_has_a_time" CHECK ((("status" = 'withdrawn'::"text") = ("withdrawn_at" IS NOT NULL)))
);


