COMMENT ON FUNCTION "public"."writer_chapter_insights"("story_slug" "text", "chapter_code" "text") IS 'The writer''s most-loved lines and where readers stop for one of their own chapters; totals only (IDEAS-1d).';



CREATE OR REPLACE FUNCTION "public"."writer_chapter_numbers"("writer_id" "uuid", "since" timestamp with time zone) RETURNS TABLE("chapter_id" "uuid", "reads" numeric, "readers" bigint, "finished" bigint, "likes" bigint, "comments" bigint, "shares" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with writer_chapters as (
    select chapters.id from public.chapters
    join public.stories on stories.id = chapters.story_id
    where stories.user_id = writer_id and stories.deleted_at is null and chapters.deleted_at is null
  ),
  since_day as (
    -- The day totals are kept by Romanian date (Q7), so "since" is a Romanian day too.
    select (since at time zone 'Europe/Bucharest')::date as first_day
  )
  select writer_chapters.id,
    (select coalesce(sum(chapter_reads.total), 0) from public.chapter_reads, since_day
      where chapter_reads.chapter_id = writer_chapters.id
        and (since is null or chapter_reads.read_on >= since_day.first_day)),
    (select count(*) from public.reading_positions
      where reading_positions.chapter_id = writer_chapters.id and reading_positions.user_id <> writer_id
        and (since is null or reading_positions.updated_at >= since)),
    (select count(*) from public.reading_positions
      where reading_positions.chapter_id = writer_chapters.id and reading_positions.user_id <> writer_id
        and reading_positions.furthest_percent >= 95
        and (since is null or reading_positions.updated_at >= since)),
    (select count(*) from public.chapter_likes
      where chapter_likes.chapter_id = writer_chapters.id and chapter_likes.user_id <> writer_id
        and (since is null or chapter_likes.created_at >= since)),
    (select count(*) from public.comments
      where comments.chapter_id = writer_chapters.id and comments.user_id <> writer_id
        and public.comment_is_shown_to_caller(comments)
        and (since is null or comments.created_at >= since)),
    (select coalesce(sum(chapter_shares.total), 0) from public.chapter_shares, since_day
      where chapter_shares.chapter_id = writer_chapters.id
        and (since is null or chapter_shares.shared_on >= since_day.first_day))
  from writer_chapters;
$$;


ALTER FUNCTION "public"."writer_chapter_numbers"("writer_id" "uuid", "since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_chapter_numbers"("writer_id" "uuid", "since" timestamp with time zone) IS 'Internal: raw totals per chapter for the writer dashboard; finished counts the furthest place (S1-E3-07, IDEAS-2d).';



CREATE OR REPLACE FUNCTION "public"."writer_dashboard"("period" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  since timestamptz;
  totals record;
begin
  -- Step 1: a signed-in writer and a known period.
  if caller_id is null then
    raise exception 'Log in to see your numbers.' using errcode = 'insufficient_privilege';
  end if;
  if period is null or period not in ('all', 'last_30_days') then
    raise exception 'Unknown period.' using errcode = 'invalid_parameter_value';
  end if;
  if period = 'last_30_days' then
    since := now() - interval '30 days';
  end if;
  -- Step 2: the period's totals across every chapter, summed before rounding.
  select sum(numbers.reads) as reads, sum(numbers.readers) as readers,
    sum(numbers.finished) as finished, sum(numbers.likes) as likes,
    count(*) filter (where numbers.likes > 0) as liked_chapters,
    sum(numbers.comments) as comments, sum(numbers.shares) as shares
  into totals
  from public.writer_chapter_numbers(caller_id, since) as numbers;
  -- Step 3: the whole dashboard, every number rounded by the "fewer than 5" rule.
  return jsonb_build_object(
    'period', period,
    'totals', jsonb_build_object(
      'reads', public.shown_count(totals.reads),
      'read_through', public.read_through_percent(totals.readers, totals.finished),
      'likes', public.shown_count(totals.likes),
      'liked_chapters', totals.liked_chapters,
      'comments', public.shown_count(totals.comments),
      'followers', public.shown_count((select count(*) from public.follows_users
        where follows_users.followed_user_id = caller_id
          and (since is null or follows_users.created_at >= since))),
      'shares', public.shown_count(totals.shares),
      -- The chart's heading always counts every follower, whatever the period.
      'followers_all_time', public.shown_count((select count(*) from public.follows_users
        where follows_users.followed_user_id = caller_id))),
    'first_published_at', (select min(chapters.first_published_at) from public.chapters
      join public.stories on stories.id = chapters.story_id
      where stories.user_id = caller_id and stories.deleted_at is null and chapters.deleted_at is null),
    'followers_by_week', public.writer_followers_by_week(caller_id),
    'chapters', public.writer_dashboard_chapters(caller_id),
    'latest_comments', public.writer_latest_comments(caller_id));
end;
$$;


ALTER FUNCTION "public"."writer_dashboard"("period" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_dashboard"("period" "text") IS 'The signed-in writer''s dashboard: totals only, "fewer than 5" below five (S1-E3-07).';



CREATE OR REPLACE FUNCTION "public"."writer_dashboard_chapters"("writer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'story_slug', stories.slug,
    'chapter_code', chapters.code,
    'position', chapters.position,
    'title', coalesce(nullif(chapters.published_title, ''), chapters.draft_title),
    'status', chapters.status,
    'scheduled_for', chapters.scheduled_for,
    'first_published_at', chapters.first_published_at,
    'edited_at', chapters.edited_at,
    'unpublished_at', chapters.unpublished_at,
    'draft_saved_at', coalesce(chapters.draft_saved_at, chapters.updated_at),
    'word_count', chapters.word_count,
    'reads', public.shown_count(numbers.reads),
    'read_through', public.read_through_percent(numbers.readers, numbers.finished),
    'likes', public.shown_count(numbers.likes),
    'comments', public.shown_count(numbers.comments),
    'shares', public.shown_count(numbers.shares)
  ) order by stories.created_at desc, chapters.position), '[]'::jsonb)
  from public.writer_chapter_numbers(writer_id, null) as numbers
  join public.chapters on chapters.id = numbers.chapter_id
  join public.stories on stories.id = chapters.story_id;
$$;


ALTER FUNCTION "public"."writer_dashboard_chapters"("writer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_dashboard_chapters"("writer_id" "uuid") IS 'Internal: the dashboard''s per-chapter numbers, rounded (S1-E3-07).';



CREATE OR REPLACE FUNCTION "public"."writer_follow_state"("wanted_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  writer public.profiles;
begin
  select * into writer from public.profile_for_handle(wanted_handle);
  if not found or exists (select 1 from public.blocks where blocks.user_id = writer.id and blocks.blocked_user_id = caller_id) then
    return null;
  end if;
  return jsonb_build_object(
    'follower_count', public.follower_count_of(writer.id),
    'following', exists (select 1 from public.follows_users
      where follows_users.user_id = caller_id and follows_users.followed_user_id = writer.id));
end;
$$;


ALTER FUNCTION "public"."writer_follow_state"("wanted_handle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_follow_state"("wanted_handle" "text") IS 'A writer''s public follower count and whether the caller follows them (S1-E6-05).';



CREATE OR REPLACE FUNCTION "public"."writer_followers_by_week"("writer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with weeks as (
    select generate_series(
      date_trunc('week', (now() at time zone 'Europe/Bucharest')::date) - interval '7 weeks',
      date_trunc('week', (now() at time zone 'Europe/Bucharest')::date),
      interval '1 week')::date as week_start
  )
  select jsonb_agg(jsonb_build_object(
    'week_start', weeks.week_start,
    'total', public.shown_count((select count(*) from public.follows_users
      where follows_users.followed_user_id = writer_id
        and (follows_users.created_at at time zone 'Europe/Bucharest')::date >= weeks.week_start
        and (follows_users.created_at at time zone 'Europe/Bucharest')::date < weeks.week_start + 7))
  ) order by weeks.week_start)
  from weeks;
$$;


ALTER FUNCTION "public"."writer_followers_by_week"("writer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_followers_by_week"("writer_id" "uuid") IS 'Internal: new followers per week for the writer dashboard chart (S1-E3-07).';



CREATE OR REPLACE FUNCTION "public"."writer_latest_comments"("writer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(latest.item order by latest.created_at desc), '[]'::jsonb)
  from (
    select comments.created_at, jsonb_build_object(
      'display_name', public.display_name(profiles.handle, profiles.pen_name),
      'handle', profiles.handle,
      'story_slug', stories.slug,
      'chapter_code', chapters.code,
      'chapter_position', chapters.position,
      'body', left(comments.body, 280),
      'created_at', comments.created_at) as item
    from public.comments
    join public.chapters on chapters.id = comments.chapter_id
    join public.stories on stories.id = chapters.story_id
    join public.profiles on profiles.id = comments.user_id
    where stories.user_id = writer_id and stories.deleted_at is null and chapters.deleted_at is null
      and chapters.status = 'published' and comments.user_id <> writer_id
      and public.comment_is_shown_to_caller(comments)
    order by comments.created_at desc
    limit 3
  ) as latest;
$$;


ALTER FUNCTION "public"."writer_latest_comments"("writer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_latest_comments"("writer_id" "uuid") IS 'Internal: the newest comments on a writer''s chapters for the dashboard (S1-E3-07).';



CREATE OR REPLACE FUNCTION "public"."writer_loved_lines"("target_chapter_id" "uuid", "writer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with paragraphs as (
    select blocks.block_number, blocks.block_text, public.paragraph_key_of(blocks.block_text) as paragraph_key
    from public.chapters, lateral public.chapter_blocks(chapters.published_body) as blocks
    where chapters.id = target_chapter_id
  ),
  counted as (
    select paragraphs.block_number, paragraphs.block_text,
      (select coalesce(sum(paragraph_shares.total), 0) from public.paragraph_shares
        where paragraph_shares.chapter_id = target_chapter_id
          and paragraph_shares.paragraph_key = paragraphs.paragraph_key) as shares,
      (select count(*) from public.comments
        where comments.chapter_id = target_chapter_id
          and comments.paragraph_key = paragraphs.paragraph_key
          and comments.user_id <> writer_id
          and public.comment_is_shown_to_caller(comments)) as comments
    from paragraphs
  ),
  top_five as (
    select * from counted where shares + comments > 0
    order by shares + comments desc, block_number
    limit 5
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'number', top_five.block_number,
    'excerpt', public.paragraph_excerpt(top_five.block_text),
    'shares', public.shown_count(top_five.shares),
    'comments', public.shown_count(top_five.comments),
    'total', public.shown_count(top_five.shares + top_five.comments)
  ) order by top_five.shares + top_five.comments desc, top_five.block_number), '[]'::jsonb)
  from top_five;
$$;


ALTER FUNCTION "public"."writer_loved_lines"("target_chapter_id" "uuid", "writer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_loved_lines"("target_chapter_id" "uuid", "writer_id" "uuid") IS 'Internal: a chapter''s five most shared and commented paragraphs, "fewer than 5" below five (IDEAS-1d).';



CREATE OR REPLACE FUNCTION "public"."writer_reader_stops"("target_chapter_id" "uuid", "writer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with places as (
    select least(reading_positions.furthest_percent / 10, 9) as tenth
    from public.reading_positions
    where reading_positions.chapter_id = target_chapter_id and reading_positions.user_id <> writer_id
  ),
  totals as (select count(*) as readers from places)
  select jsonb_build_object(
    'readers', public.shown_count(totals.readers),
    'tenths', case when totals.readers < 5 then null else (
      select jsonb_agg(round(100.0 * (select count(*) from places where places.tenth = slot) / totals.readers)::integer
        order by slot)
      from generate_series(0, 9) as slot) end)
  from totals;
$$;


ALTER FUNCTION "public"."writer_reader_stops"("target_chapter_id" "uuid", "writer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_reader_stops"("target_chapter_id" "uuid", "writer_id" "uuid") IS 'Internal: how far readers got in a chapter, in tenths, only from five readers (IDEAS-1d, IDEAS-2d).';



CREATE TABLE IF NOT EXISTS "public"."writer_spotlights" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "starts_on" "date" NOT NULL,
    "reason_ro" "text" NOT NULL,
    "reason_en" "text" NOT NULL,
    "agreed_at" timestamp with time zone,
    "declined_at" timestamp with time zone,
    "updated_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "writer_spotlights_one_answer" CHECK ((("agreed_at" IS NULL) OR ("declined_at" IS NULL))),
    CONSTRAINT "writer_spotlights_reason_en_length" CHECK ((("char_length"("btrim"("reason_en")) >= 1) AND ("char_length"("btrim"("reason_en")) <= 300))),
    CONSTRAINT "writer_spotlights_reason_ro_length" CHECK ((("char_length"("btrim"("reason_ro")) >= 1) AND ("char_length"("btrim"("reason_ro")) <= 300)))
);


ALTER TABLE "public"."writer_spotlights" OWNER TO "postgres";


COMMENT ON TABLE "public"."writer_spotlights" IS 'kind: user_action
Writer of the week on the Writers'' hub: the writer staff picked, the first day, staff''s line on why in Romanian and English, and the writer''s own answer with its time (GAPS-12e). Personal data: that the person was picked and whether they agreed.';



CREATE OR REPLACE FUNCTION "public"."writer_spotlight_answer"("spotlight" "public"."writer_spotlights") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when spotlight.agreed_at is not null then 'agreed'
    when spotlight.declined_at is not null then 'declined'
    else 'waiting'
  end;
$$;


ALTER FUNCTION "public"."writer_spotlight_answer"("spotlight" "public"."writer_spotlights") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writer_spotlight_answer"("spotlight" "public"."writer_spotlights") IS 'Internal: a writer-of-the-week pick''s answer as agreed, declined or waiting (GAPS-12e).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_calls"() RETURNS TABLE("call_id" "uuid", "title_ro" "text", "title_en" "text", "details_ro" "text", "details_en" "text", "link_url" "text", "closes_on" "date", "is_paid" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    submission_calls.id,
    submission_calls.title_ro,
    submission_calls.title_en,
    submission_calls.details_ro,
    submission_calls.details_en,
    submission_calls.link_url,
    submission_calls.closes_on,
    submission_calls.is_paid
  from public.submission_calls
  where (select auth.uid()) is not null
    and submission_calls.deleted_at is null
    -- Still open: the last day is included.
    and submission_calls.closes_on >= public.romania_today()
    -- Paid writing work is for adults only (Robert, 8 Nov 2026).
    and (not submission_calls.is_paid or (select public.age_band()) = '18_plus')
  order by submission_calls.closes_on, submission_calls.created_at
  limit 12;
$$;


ALTER FUNCTION "public"."writers_hub_calls"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_calls"() IS 'The calls for submissions still open today, soonest closing first; paid ones only for adults (GAPS-12d).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_contests"() RETURNS TABLE("contest_id" "uuid", "name_ro" "text", "name_en" "text", "page_slug" "text", "entries_close_on" "date", "word_limit" integer, "prize_ro" "text", "prize_en" "text", "entry_count" integer, "cover" "jsonb", "cover_alt_ro" "text", "cover_alt_en" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select contests.id, contests.name_ro, contests.name_en, pages.slug,
    contests.entries_close_on, contests.word_limit, contests.prize_ro, contests.prize_en,
    -- Entries that count today: not withdrawn, not disqualified.
    (select count(*)::integer from public.contest_entries
     where contest_entries.contest_id = contests.id and contest_entries.status = 'valid'),
    -- The picture as this caller may see it; {} when the page has none.
    coalesce((select jsonb_build_object(picture_checks.id, public.picture_state_json(picture_checks))
              from public.picture_checks
              where picture_checks.id::text = cover_block.block ->> 'picture_id'
                and picture_checks.kind = 'landing_picture' and picture_checks.deleted_at is null),
             '{}'::jsonb),
    coalesce(cover_block.block -> 'ro' ->> 'alt', ''),
    coalesce(cover_block.block -> 'en' ->> 'alt', '')
  from public.contests
  join public.landing_pages as pages on pages.id = contests.landing_page_id
  -- The live version's first block that carries a picture, top to bottom (the hero comes first).
  left join lateral (
    select each_block.block
    from public.landing_page_live_version(pages.id) as live
    cross join lateral jsonb_array_elements(coalesce(live.content -> 'blocks', '[]'::jsonb))
      with ordinality as each_block(block, place)
    where each_block.block ->> 'picture_id' is not null
    order by each_block.place
    limit 1
  ) as cover_block on true
  -- Step 1: only signed-in writers; a visitor sees the contest on its landing page instead.
  where (select auth.uid()) is not null
    -- Step 2: the contest takes entries today and its landing page still shows.
    and public.contest_takes_entries_today(contests)
    and pages.archived_at is null
    -- Step 3: the writer's age group and market are among the contest's (criterion 1).
    and public.contest_writer_fits(contests)
  order by contests.entries_close_on, contests.name_en;
$$;


ALTER FUNCTION "public"."writers_hub_contests"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_contests"() IS 'The contests the signed-in writer can enter today, each with its entry count and cover picture, for the Writers'' hub (G9a, GAPS-12a; S1-E11-15 rules).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_learning_path"() RETURNS TABLE("day_number" integer, "title_ro" "text", "title_en" "text", "lesson_ro" "text", "lesson_en" "text", "task_ro" "text", "task_en" "text", "is_done" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    steps.day_number,
    steps.title_ro,
    steps.title_en,
    steps.lesson_ro,
    steps.lesson_en,
    steps.task_ro,
    steps.task_en,
    exists (
      select 1 from public.learning_path_progress as progress
      where progress.user_id = (select auth.uid()) and progress.day_number = steps.day_number
    )
  from public.learning_path_steps as steps
  where (select auth.uid()) is not null
  order by steps.day_number;
$$;


ALTER FUNCTION "public"."writers_hub_learning_path"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_learning_path"() IS 'The learning path''s seven days in order, each with whether the caller marked it done (GAPS-12g).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_prompts"() RETURNS TABLE("prompt_id" "uuid", "prompt_ro" "text", "prompt_en" "text", "starts_on" "date", "ends_on" "date", "is_current" boolean, "writer_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    writing_prompts.id,
    writing_prompts.prompt_ro,
    writing_prompts.prompt_en,
    writing_prompts.starts_on,
    writing_prompts.starts_on + 6,
    public.romania_today() <= writing_prompts.starts_on + 6,
    (select count(distinct stories.user_id)::integer from public.stories
      where stories.writing_prompt_id = writing_prompts.id and stories.deleted_at is null)
  from public.writing_prompts
  where (select auth.uid()) is not null
    and writing_prompts.deleted_at is null
    -- An upcoming prompt stays hidden until its first day.
    and writing_prompts.starts_on <= public.romania_today()
  order by writing_prompts.starts_on desc
  limit 8;
$$;


ALTER FUNCTION "public"."writers_hub_prompts"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_prompts"() IS 'The writing prompts that have started, newest first, each with how many writers started a story from it, for the Writers'' hub (GAPS-12c).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_sessions"() RETURNS TABLE("session_id" "uuid", "title_ro" "text", "title_en" "text", "starts_at" timestamp with time zone, "language_code" "text", "rating" "public"."story_rating", "place_ro" "text", "place_en" "text", "link_url" "text", "is_reminded" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    live_sessions.id,
    live_sessions.title_ro,
    live_sessions.title_en,
    live_sessions.starts_at,
    live_sessions.language_code,
    live_sessions.rating,
    live_sessions.place_ro,
    live_sessions.place_en,
    live_sessions.link_url,
    exists (select 1 from public.live_session_reminders as reminders
            where reminders.session_id = live_sessions.id
              and reminders.user_id = (select auth.uid()))
  from public.live_sessions
  where (select auth.uid()) is not null
    and live_sessions.deleted_at is null
    and live_sessions.starts_at > now()
    -- Never to a member younger than the session's age group (CLAUDE.md rule 18).
    and public.rating_fits_band(live_sessions.rating, (select public.age_band()))
  order by live_sessions.starts_at, live_sessions.created_at
  limit 6;
$$;


ALTER FUNCTION "public"."writers_hub_sessions"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_sessions"() IS 'The live sessions coming up that fit the caller''s age group, soonest first, with the caller''s own reminders (GAPS-12h).';



CREATE OR REPLACE FUNCTION "public"."writers_hub_spotlight"() RETURNS TABLE("handle" "text", "display_name" "text", "reason_ro" "text", "reason_en" "text", "is_me" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    profiles.handle,
    public.display_name(profiles.handle, profiles.pen_name),
    writer_spotlights.reason_ro,
    writer_spotlights.reason_en,
    -- The picked writer sees their own card without Follow.
    profiles.id = (select auth.uid())
  from public.writer_spotlights
  join public.profiles on profiles.id = writer_spotlights.user_id
  where (select auth.uid()) is not null
    and writer_spotlights.deleted_at is null
    -- The writer's agreement comes first (GAPS-12 brief).
    and writer_spotlights.agreed_at is not null
    -- Its 7 days, the first and the last included.
    and public.romania_today() between writer_spotlights.starts_on and writer_spotlights.starts_on + 6
    -- A deleted, suspended or banned account is never put forward.
    and profiles.deleted_at is null
    and public.account_state(profiles.id) = 'active'
    -- Adults only (architecture 1.10: under-18s are private by default).
    and public.age_band_of(profiles.id) = '18_plus'
    -- Blocks are respected (CLAUDE.md rule 6).
    and not public.is_blocked_with(profiles.id)
  order by writer_spotlights.starts_on desc
  limit 1;
$$;


ALTER FUNCTION "public"."writers_hub_spotlight"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_hub_spotlight"() IS 'This week''s writer of the week, only once the writer agreed and while the account is active and adult; blocks respected (GAPS-12e).';



CREATE OR REPLACE FUNCTION "public"."writers_published_by_market"("for_day" "date") RETURNS TABLE("market" "text", "writer_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with writers as (
    select distinct stories.user_id,
      case when markets.is_open then profiles.country_code else 'other' end as market
    from public.chapters
    join public.stories on stories.id = chapters.story_id
    join public.profiles on profiles.id = stories.user_id
    left join public.markets on markets.country_code = profiles.country_code
    where public.chapter_is_readable(chapters.id)
      and (chapters.first_published_at at time zone 'Europe/Bucharest')::date <= for_day
      and profiles.deleted_at is null
      and profiles.handle is distinct from (public.setting_value('classics_account_handle') #>> '{}')
  )
  select 'all', count(distinct user_id)::integer from writers
  union all
  select coalesce(writers.market, 'other'), count(*)::integer from writers
  group by coalesce(writers.market, 'other');
$$;


ALTER FUNCTION "public"."writers_published_by_market"("for_day" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."writers_published_by_market"("for_day" "date") IS 'Internal: writers with a readable chapter by the end of a day, in total and by market (S1-E15-02).';



CREATE OR REPLACE FUNCTION "public"."youngest_age"("birth_year" integer, "birth_month" integer, "on_date" "date") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when birth_year is null then null
    when birth_month is null or extract(month from on_date)::integer <= birth_month
      then extract(year from on_date)::integer - birth_year - 1
    else extract(year from on_date)::integer - birth_year
  end;
$$;


ALTER FUNCTION "public"."youngest_age"("birth_year" integer, "birth_month" integer, "on_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."youngest_age"("birth_year" integer, "birth_month" integer, "on_date" "date") IS 'The youngest age someone born in a year (and month) can be on a date (MARKETS-1).';



