    CONSTRAINT "classic_works_translator_name_check" CHECK ((("translator_name" IS NULL) OR (("btrim"("translator_name") <> ''::"text") AND ("char_length"("translator_name") <= 120))))
);


ALTER TABLE "public"."classic_works" OWNER TO "postgres";


