CREATE TABLE IF NOT EXISTS "public"."compliance_log_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reference" "text" DEFAULT ('LR-'::"text" || "lpad"(("nextval"('"public"."compliance_log_reference_seq"'::"regclass"))::"text", 3, '0'::"text")) NOT NULL,
    "user_id" "uuid" NOT NULL,
    "entry_kind" "public"."compliance_entry_kind" NOT NULL,
    "authority" "text" NOT NULL,
    "received_at" timestamp with time zone NOT NULL,
    "content" "text" NOT NULL,
    "action_taken" "text",
    "completed_at" timestamp with time zone,
    "completed_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "compliance_log_entries_action_length" CHECK ((("action_taken" IS NULL) OR (("char_length"("btrim"("action_taken")) >= 1) AND ("char_length"("btrim"("action_taken")) <= 2000)))),
    CONSTRAINT "compliance_log_entries_authority_length" CHECK ((("char_length"("btrim"("authority")) >= 1) AND ("char_length"("btrim"("authority")) <= 200))),
    CONSTRAINT "compliance_log_entries_content_length" CHECK ((("char_length"("btrim"("content")) >= 1) AND ("char_length"("btrim"("content")) <= 2000))),
    CONSTRAINT "compliance_log_entries_done_after_received" CHECK ((("completed_at" IS NULL) OR ("completed_at" >= "received_at"))),
    CONSTRAINT "compliance_log_entries_done_fields_go_together" CHECK (((("completed_at" IS NULL) = ("action_taken" IS NULL)) AND (("completed_at" IS NULL) = ("completed_by_user_id" IS NULL))))
);


ALTER TABLE "public"."compliance_log_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."compliance_log_entries" IS 'kind: staff
