CREATE TABLE IF NOT EXISTS "public"."forums" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "parent_id" "uuid",
    "level" smallint DEFAULT 0 NOT NULL,
    "slug" "text" NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "is_pinned" boolean DEFAULT false NOT NULL,
    "accent" "public"."forum_accent" DEFAULT 'plum'::"public"."forum_accent" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "space_id" "uuid",
    "rules_thread_id" "uuid",
    CONSTRAINT "forums_level_range" CHECK ((("level" >= 0) AND ("level" <= 2))),
    CONSTRAINT "forums_not_own_parent" CHECK (("parent_id" IS DISTINCT FROM "id")),
    CONSTRAINT "forums_only_categories_pinned" CHECK (((NOT "is_pinned") OR ("parent_id" IS NULL))),
    CONSTRAINT "forums_position_range" CHECK ((("position" >= 0) AND ("position" <= 10000))),
    CONSTRAINT "forums_slug_format" CHECK ((("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text") AND (("char_length"("slug") >= 2) AND ("char_length"("slug") <= 60)))),
    CONSTRAINT "forums_slug_not_search" CHECK (("slug" <> 'search'::"text")),
    CONSTRAINT "forums_space_slug" CHECK ((("space_id" IS NULL) = ("slug" !~ '^space-'::"text")))
);


ALTER TABLE "public"."forums" OWNER TO "postgres";


COMMENT ON TABLE "public"."forums" IS 'kind: platform
Forum categories (level 0), forums (level 1) and subforums (level 2), made by staff (S1-E8-01).';



COMMENT ON COLUMN "public"."forums"."space_id" IS 'The space this hidden forum belongs to; null for staff''s forums (S1-E8-06). Space forums never show on the forum index.';



COMMENT ON COLUMN "public"."forums"."rules_thread_id" IS 'The thread that holds this forum''s rules, shown in a strip above its other threads (GAPS-9).';



