CREATE SEQUENCE IF NOT EXISTS "public"."statement_reference_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."statement_reference_seq" OWNER TO "postgres";


COMMENT ON SEQUENCE "public"."statement_reference_seq" IS 'Numbers the statements of reasons: S-000123 (S1-E10-04).';



CREATE TABLE IF NOT EXISTS "public"."story_character_fields" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "story_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "name" "text" NOT NULL,
    "hidden_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sheet_group" "text",
    "own_group" "text",
    CONSTRAINT "story_character_fields_name_length" CHECK ((("char_length"("btrim"("name")) >= 1) AND ("char_length"("btrim"("name")) <= 60))),
    CONSTRAINT "story_character_fields_one_place" CHECK ((("sheet_group" IS NULL) OR ("own_group" IS NULL))),
    CONSTRAINT "story_character_fields_own_group_length" CHECK ((("own_group" IS NULL) OR (("char_length"("btrim"("own_group")) >= 1) AND ("char_length"("btrim"("own_group")) <= 60)))),
    CONSTRAINT "story_character_fields_position_counts_from_one" CHECK (("position" >= 1)),
    CONSTRAINT "story_character_fields_sheet_group_known" CHECK ((("sheet_group" IS NULL) OR ("sheet_group" = ANY (ARRAY['basics'::"text", 'look_and_voice'::"text", 'inside'::"text", 'in_the_story'::"text"]))))
);


ALTER TABLE "public"."story_character_fields" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_character_fields" IS 'kind: user_content; reportable: story
The writer''s own character fields in one story''s plan, shown on every sheet (S1-E17-10). A removed field is hidden, never deleted, so its values come back with it.';



COMMENT ON COLUMN "public"."story_character_fields"."user_id" IS 'The writer''s user ID; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."story_character_fields"."sheet_group" IS 'kind: setting. The built-in sheet group this detail shows under (basics, look_and_voice, inside, in_the_story); null when it sits elsewhere (GAPS-1).';



COMMENT ON COLUMN "public"."story_character_fields"."own_group" IS 'kind: user_content. The name of the writer''s own group this detail sits in; null when it sits elsewhere. A group exists while one of its details does (GAPS-1).';



CREATE TABLE IF NOT EXISTS "public"."story_marketing" (
    "story_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "back_cover_blurb" "text" DEFAULT ''::"text" NOT NULL,
    "comparable_titles" "text" DEFAULT ''::"text" NOT NULL,
    "hooks_keywords" "text" DEFAULT ''::"text" NOT NULL,
    "query_pitch" "text" DEFAULT ''::"text" NOT NULL,
    "launch_notes" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "own_details" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    CONSTRAINT "story_marketing_blurb_length" CHECK (("char_length"("back_cover_blurb") <= 3000)),
    CONSTRAINT "story_marketing_comparable_titles_length" CHECK (("char_length"("comparable_titles") <= 1000)),
    CONSTRAINT "story_marketing_hooks_keywords_length" CHECK (("char_length"("hooks_keywords") <= 1000)),
    CONSTRAINT "story_marketing_launch_notes_length" CHECK (("char_length"("launch_notes") <= 5000)),
    CONSTRAINT "story_marketing_own_details_list" CHECK ((("jsonb_typeof"("own_details") = 'array'::"text") AND ("jsonb_array_length"("own_details") <= 12))),
    CONSTRAINT "story_marketing_query_pitch_length" CHECK (("char_length"("query_pitch") <= 3000))
);


ALTER TABLE "public"."story_marketing" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_marketing" IS 'kind: user_content; reportable: story
The writer''s marketing notes on one story (S1-E17-29): back-cover blurb, comparable titles, hooks and keywords, query pitch and launch notes. Only the writer reads them.';



COMMENT ON COLUMN "public"."story_marketing"."user_id" IS 'The writer''s user ID; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."story_marketing"."own_details" IS 'kind: user_content. The writer''s own marketing details, in the order added: a list of { id, name (1 to 80 characters), text (up to 5,000) }; at most 12 (GAPS-2b).';



CREATE TABLE IF NOT EXISTS "public"."story_plan_acts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "story_id" "uuid" NOT NULL,
