    CONSTRAINT "story_plan_acts_position_counts_from_one" CHECK (("position" >= 1))
);


ALTER TABLE "public"."story_plan_acts" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_plan_acts" IS 'kind: user_content; reportable: story
The acts of one story''s plan (S1-E17-01: Act I, Act II and Act III to start with). Private groupings of chapters; never shown to readers.';



COMMENT ON COLUMN "public"."story_plan_acts"."user_id" IS 'The writer''s user ID; never shown publicly (rule 15).';



CREATE TABLE IF NOT EXISTS "public"."story_plans" (
    "story_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "logline" "text" DEFAULT ''::"text" NOT NULL,
    "series_name" "text" DEFAULT ''::"text" NOT NULL,
    "word_target" integer DEFAULT 90000 NOT NULL,
    "writing_status" "text" DEFAULT 'planning'::"text" NOT NULL,
    "publishing_route" "text" DEFAULT 'undecided'::"text" NOT NULL,
    "linked_project_label" "text" DEFAULT ''::"text" NOT NULL,
    "linked_project_url" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "public_areas" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "story_plans_linked_project_label_length" CHECK (("char_length"("linked_project_label") <= 60)),
    CONSTRAINT "story_plans_linked_project_url_web" CHECK ((("linked_project_url" = ''::"text") OR (("linked_project_url" ~* '^https?://[^\s]+$'::"text") AND ("char_length"("linked_project_url") <= 2000)))),
    CONSTRAINT "story_plans_logline_length" CHECK (("char_length"("logline") <= 400)),
    CONSTRAINT "story_plans_public_areas_known" CHECK (("public_areas" <@ ARRAY['characters'::"text", 'relationship_map'::"text", 'family_tree'::"text", 'bible'::"text", 'timeline'::"text"])),
    CONSTRAINT "story_plans_publishing_route_known" CHECK (("publishing_route" = ANY (ARRAY['undecided'::"text", 'serial_here'::"text", 'complete_here'::"text", 'here_and_elsewhere'::"text"]))),
    CONSTRAINT "story_plans_series_name_length" CHECK (("char_length"("series_name") <= 120)),
    CONSTRAINT "story_plans_word_target_range" CHECK ((("word_target" >= 1) AND ("word_target" <= 5000000))),
    CONSTRAINT "story_plans_writing_status_known" CHECK (("writing_status" = ANY (ARRAY['planning'::"text", 'drafting'::"text", 'revising'::"text", 'editing'::"text", 'finished'::"text", 'on_hold'::"text"])))
);


ALTER TABLE "public"."story_plans" OWNER TO "postgres";


COMMENT ON TABLE "public"."story_plans" IS 'kind: user_content; reportable: story
The private plan of one story in Story Atlas (S1-E17-01 to S1-E17-06): logline, series, word target, writing status, publishing route and a linked project. Only the writer reads it.';



COMMENT ON COLUMN "public"."story_plans"."user_id" IS 'The writer''s user ID; never shown publicly (rule 15).';



COMMENT ON COLUMN "public"."story_plans"."writing_status" IS 'Where the writer is with the story: planning, drafting, revising, editing, finished or on_hold (S1-E17-03).';



COMMENT ON COLUMN "public"."story_plans"."publishing_route" IS 'How the writer means to publish it: undecided, serial_here, complete_here or here_and_elsewhere (S1-E17-06).';



COMMENT ON COLUMN "public"."story_plans"."public_areas" IS 'The plan''s areas readers see once the story is published (S1-E17-32); none by default.';



