CREATE TABLE IF NOT EXISTS "public"."teacher_checks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "way" "text" NOT NULL,
    "school_domain" "text",
    "proof_path" "text",
    "token_hash" "text",
    "link_expires_at" timestamp with time zone,
    "status" "text" NOT NULL,
    "decision_reason" "text",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "teacher_checks_decided_together" CHECK ((("status" = ANY (ARRAY['approved'::"text", 'rejected'::"text"])) = ("decided_at" IS NOT NULL))),
    CONSTRAINT "teacher_checks_domain_looks_right" CHECK ((("school_domain" IS NULL) OR ("school_domain" ~ '^[a-z0-9-]+(\.[a-z0-9-]+)+$'::"text"))),
    CONSTRAINT "teacher_checks_proof_only_while_waiting" CHECK ((("proof_path" IS NULL) OR ("status" = 'waiting_for_staff'::"text"))),
    CONSTRAINT "teacher_checks_reason_length" CHECK ((("decision_reason" IS NULL) OR (("char_length"("decision_reason") >= 1) AND ("char_length"("decision_reason") <= 1000)))),
    CONSTRAINT "teacher_checks_status_known" CHECK (("status" = ANY (ARRAY['link_sent'::"text", 'waiting_for_staff'::"text", 'approved'::"text", 'rejected'::"text", 'replaced'::"text"]))),
    CONSTRAINT "teacher_checks_way_has_its_part" CHECK (((("way" = 'school_email'::"text") AND ("school_domain" IS NOT NULL) AND ("proof_path" IS NULL)) OR (("way" = 'proof'::"text") AND ("school_domain" IS NULL)))),
    CONSTRAINT "teacher_checks_way_known" CHECK (("way" = ANY (ARRAY['school_email'::"text", 'proof'::"text"])))
);


ALTER TABLE "public"."teacher_checks" OWNER TO "postgres";


COMMENT ON TABLE "public"."teacher_checks" IS 'kind: user_action
A request for the Teacher badge: the way, the school domain (never the address), the proof only until the decision, and the outcome with its reason (S1-E2-11). Who decided is in the audit log only.';



COMMENT ON COLUMN "public"."teacher_checks"."user_id" IS 'The person asking; never shown publicly (rule 15).';



CREATE TABLE IF NOT EXISTS "public"."username_approvals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name_kind" "text" NOT NULL,
    "approved_name" "text" NOT NULL,
    "approved_skeleton" "text" NOT NULL,
    "approved_by_user_id" "uuid" NOT NULL,
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "username_approvals_kind_is_known" CHECK (("name_kind" = ANY (ARRAY['handle'::"text", 'pen_name'::"text"]))),
    CONSTRAINT "username_approvals_reason_is_given" CHECK (("btrim"("reason") <> ''::"text"))
);


ALTER TABLE "public"."username_approvals" OWNER TO "postgres";


COMMENT ON TABLE "public"."username_approvals" IS 'kind: user_action
A moderator''s approval of one exact username or pen name the word checks refused by mistake (S1-E2-04).';



CREATE TABLE IF NOT EXISTS "public"."username_word_lists" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "language" "text" NOT NULL,
    "word" "text" NOT NULL,
    "folded_word" "text" DEFAULT ''::"text" NOT NULL,
    "match_rule" "text" DEFAULT 'anywhere'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "username_word_lists_language_is_known" CHECK (("language" = ANY (ARRAY['en'::"text", 'ro'::"text"]))),
    CONSTRAINT "username_word_lists_match_rule_is_known" CHECK (("match_rule" = ANY (ARRAY['anywhere'::"text", 'whole_word'::"text"])))
);


ALTER TABLE "public"."username_word_lists" OWNER TO "postgres";


COMMENT ON TABLE "public"."username_word_lists" IS 'kind: platform
Swearwords refused in usernames and pen names, per language; drafts from content/username-word-lists/ (S1-E2-04).';



CREATE TABLE IF NOT EXISTS "public"."waitlist_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "interest" "public"."waitlist_interest" DEFAULT 'both'::"public"."waitlist_interest" NOT NULL,
    "joined_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "admitted_at" timestamp with time zone,
    "admitted_by_code" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waitlist_entries_code_means_admitted" CHECK (((NOT "admitted_by_code") OR ("admitted_at" IS NOT NULL)))
);


ALTER TABLE "public"."waitlist_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."waitlist_entries" IS 'kind: user_action
One person who signed up while the waiting list was on, what they come for and when they were let in (WAITLIST-1, S1-E2-24).';



CREATE TABLE IF NOT EXISTS "public"."writer_ranks" (
    "user_id" "uuid" NOT NULL,
    "rank" "public"."writer_rank" NOT NULL,
    "chapter_count" integer NOT NULL,
    "word_count" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "writer_ranks_chapters_not_negative" CHECK (("chapter_count" >= 0)),
    CONSTRAINT "writer_ranks_words_not_negative" CHECK (("word_count" >= 0))
);


ALTER TABLE "public"."writer_ranks" OWNER TO "postgres";


COMMENT ON TABLE "public"."writer_ranks" IS 'kind: identity
Each writer''s rank, worked out again whenever their published chapters change; others read it only through rank_of() and profile_rank() (S1-E8-09).';



CREATE TABLE IF NOT EXISTS "public"."writing_days" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "day" "date" NOT NULL,
    "words" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "writing_days_words_not_negative" CHECK (("words" >= 0))
);


ALTER TABLE "public"."writing_days" OWNER TO "postgres";


COMMENT ON TABLE "public"."writing_days" IS 'kind: user_action
A writer''s net new words per day in Romanian time, kept by a trigger on chapters, for the writing month, streaks and badges on the Writers'' hub (GAPS-12f). Personal data: on which days the person wrote and how much; never the words themselves. Kept 400 days.';



CREATE TABLE IF NOT EXISTS "public"."writing_prompts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prompt_ro" "text" NOT NULL,
    "prompt_en" "text" NOT NULL,
    "starts_on" "date" NOT NULL,
    "updated_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "writing_prompts_prompt_en_length" CHECK ((("char_length"("btrim"("prompt_en")) >= 1) AND ("char_length"("btrim"("prompt_en")) <= 300))),
    CONSTRAINT "writing_prompts_prompt_ro_length" CHECK ((("char_length"("btrim"("prompt_ro")) >= 1) AND ("char_length"("btrim"("prompt_ro")) <= 300)))
);


ALTER TABLE "public"."writing_prompts" OWNER TO "postgres";


COMMENT ON TABLE "public"."writing_prompts" IS 'kind: platform
The prompt of the week on the Writers'' hub: staff-written words in Romanian and English with a start day (GAPS-12c). No personal data.';



