CREATE POLICY "abuse_image_evidence_select_safeguarding" ON "public"."abuse_image_evidence" FOR SELECT TO "authenticated" USING (( SELECT "public"."staff_may"('safeguarding'::"text", 'view'::"text") AS "staff_may"));



ALTER TABLE "public"."account_deletions" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "account_deletions_select_own" ON "public"."account_deletions" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



COMMENT ON POLICY "account_deletions_select_own" ON "public"."account_deletions" IS 'Allows a signed-in person to read only their own deletion requests (S1-E13-03).';



ALTER TABLE "public"."account_staff_notes" ENABLE ROW LEVEL SECURITY;


