CREATE POLICY "messages_select_member" ON "public"."messages" FOR SELECT TO "authenticated" USING ((("deleted_at" IS NULL) AND (EXISTS ( SELECT 1
   FROM "public"."conversations"
  WHERE (("conversations"."id" = "messages"."conversation_id") AND ((( SELECT "auth"."uid"() AS "uid") = "conversations"."user_id") OR (( SELECT "auth"."uid"() AS "uid") = "conversations"."recipient_user_id"))))) AND (("user_id" = ( SELECT "auth"."uid"() AS "uid")) OR (NOT "public"."is_moderated_away"('message'::"public"."reportable_type", "id"))) AND ("created_at" > COALESCE("public"."chat_cleared_at"("conversation_id", ( SELECT "auth"."uid"() AS "uid")), '-infinity'::timestamp with time zone))));



