CREATE POLICY "username_approvals_select_staff" ON "public"."username_approvals" FOR SELECT TO "authenticated" USING (( SELECT "public"."staff_may"('user_sanctions'::"text", 'view'::"text") AS "staff_may"));



COMMENT ON POLICY "username_approvals_select_staff" ON "public"."username_approvals" IS 'Allows owner, admin and moderator, in a staff session, to read username approvals (S1-E2-04).';



ALTER TABLE "public"."username_word_lists" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "username_word_lists_select_admin" ON "public"."username_word_lists" FOR SELECT TO "authenticated" USING (( SELECT "public"."staff_may"('settings'::"text", 'view'::"text") AS "staff_may"));



COMMENT ON POLICY "username_word_lists_select_admin" ON "public"."username_word_lists" IS 'Allows owner and admin, in a staff session, to read the swearword lists, a setting (S1-E2-04).';



ALTER TABLE "public"."waitlist_entries" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "waitlist_entries_select_own" ON "public"."waitlist_entries" FOR SELECT TO "authenticated" USING ((( SELECT "auth"."uid"() AS "uid") = "user_id"));



