CREATE POLICY "waitlist_entries_select_staff" ON "public"."waitlist_entries" FOR SELECT TO "authenticated" USING (( SELECT "public"."staff_may"('waitlist'::"text", 'view'::"text") AS "staff_may"));



COMMENT ON POLICY "waitlist_entries_select_staff" ON "public"."waitlist_entries" IS 'Allows owner and admin, in a staff session, to read every waiting list entry (WAITLIST-1).';



ALTER TABLE "public"."writer_ranks" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "writer_ranks_select_own" ON "public"."writer_ranks" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



COMMENT ON POLICY "writer_ranks_select_own" ON "public"."writer_ranks" IS 'Allows a person to read their own rank row; others see ranks only through functions without the user ID (S1-E8-09).';



ALTER TABLE "public"."writer_spotlights" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "writer_spotlights_select_contest_staff" ON "public"."writer_spotlights" FOR SELECT TO "authenticated" USING ((("deleted_at" IS NULL) AND ( SELECT "public"."staff_may"('contests'::"text", 'view'::"text") AS "staff_may")));



